using System.Buffers;
using System.Collections;
using System.Collections.Immutable;
using System.Diagnostics;
using System.Globalization;
using System.Linq;
using System.Security.Cryptography;
using NLink.Core.Configuration;
using NLink.Core.Logging;

namespace NLink.Core.FileTransfer;

public sealed partial class SessionFileTransferService
{
    private enum RetainedPeerProofApplicationStatus
    {
        Applied,
        Idempotent,
        Held,
        Rejected,
    }

    private readonly record struct RetainedPeerProofApplicationResult(
        RetainedPeerProofApplicationStatus Status,
        string Reason);

    private const int OutboundSparsePendingFrontierDispatchProofLimit = 256;

    internal static Func<string, string, Task>? OutboundSparseTailReconciliationQueueBarrierForTests { get; set; }
    internal static Func<string, string, Task>? OutboundSparseFailureDeferralBarrierForTests { get; set; }
    internal static Func<string, string, Task>? OutboundSparseStateRefreshPreSendBarrierForTests { get; set; }
    internal static Func<string, string, string, Task>? OutboundSparseBootstrapBarrierForTests { get; set; }
    internal static Func<string, string, string, Task>? OutboundSparseRepairContinuationBarrierForTests { get; set; }
    internal static Func<string, string, Task>? OutboundSparseSourceReopenBarrierForTests { get; set; }
    internal static Func<string, string, Task>? InboundRegularV4ProjectionPreSendBarrierForTests { get; set; }
    internal static Func<string, string, Task>? InboundRegularV4FrontierTailRepairPreSendBarrierForTests { get; set; }
    internal static Func<string, string, bool>? OutboundSparseSenderPumpNormalCompletionForTests { get; set; }

    private static bool ShouldUseV6SparseCreditEnvelope(OutboundTransferContext context)
        => context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           context.RouteRuntime.UsesV6FeedbackEnvelope;

    private static bool ShouldUseV6SparseCreditEnvelope(InboundTransferContext context)
        => context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           context.RouteRuntime.UsesV6FeedbackEnvelope;

    private static bool ShouldAcceptSparseCreditRuntimeDataFrame(
        OutboundTransferContext context,
        FileTransferDataFrame frame)
        => ShouldUseV6SparseCreditEnvelope(context)
            ? FileTransferProtocol.IsV6DataFrame(frame)
            : FileTransferProtocol.IsV4DataFrame(frame) ||
              ShouldAcceptCurrentPostTunaFallbackV6RuntimeFrame(context, frame) ||
              ShouldAcceptLiveRouteV6ProbeFrame(context, frame);

    private static bool ShouldAcceptSparseCreditRuntimeDataFrame(
        InboundTransferContext context,
        FileTransferDataFrame frame)
        => ShouldUseV6SparseCreditEnvelope(context)
            ? FileTransferProtocol.IsV6DataFrame(frame)
            : FileTransferProtocol.IsV4DataFrame(frame) ||
              ShouldAcceptCurrentPostTunaFallbackV6RuntimeFrame(context, frame) ||
              ShouldAcceptLiveRouteV6ProbeFrame(context, frame);

    private static bool ShouldAcceptCurrentPostTunaFallbackV6RuntimeFrame(
        OutboundTransferContext context,
        FileTransferDataFrame frame)
        => FileTransferProtocol.IsV6DataFrame(frame) &&
           IsCurrentPostTunaFallbackV6RouteOwner(context);

    private static bool ShouldAcceptCurrentPostTunaFallbackV6RuntimeFrame(
        InboundTransferContext context,
        FileTransferDataFrame frame)
        => FileTransferProtocol.IsV6DataFrame(frame) &&
           IsCurrentPostTunaFallbackV6RouteOwner(context);

    private static bool IsCurrentPostTunaFallbackV6RouteOwner(OutboundTransferContext context)
        => context.RouteSelection.Route == FileTransferRoute.PostTunaFallbackV6 &&
           context.RouteSelection.ProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
           context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V6 &&
           IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg);

    private static bool IsCurrentPostTunaFallbackV6RouteOwner(InboundTransferContext context)
        => context.RouteSelection.Route == FileTransferRoute.PostTunaFallbackV6 &&
           context.RouteSelection.ProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
           context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V6 &&
           IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg);

    private bool ShouldKeepOutboundV4ReceiveLoopAliveAfterSenderPumpCompleted(OutboundTransferContext context)
    {
        lock (gate)
        {
            return ReferenceEquals(outboundTransfer, context) &&
                   !context.IsTerminal &&
                   SupportsOutboundSparsePumpInstall(context);
        }
    }

    private static bool ShouldAcceptLiveRouteV6ProbeFrame(OutboundTransferContext context, FileTransferDataFrame frame)
        => frame is FileTransferTransportProbeFrameV6 &&
           context.CurrentLiveRouteEpoch is
           {
               HandoffKind: FileTransferTransportHandoffKind.NormalToTunaActivation,
               TargetTransport: FileTransferTransportKind.Tuna,
           };

    private static bool IsPeerPostTunaFallbackV6RuntimeProofFrame(FileTransferDataFrame frame)
        => frame switch
        {
            FileTransferReceiverStateFrameV6 state => IsPeerPostTunaFallbackV6RuntimeProofMetadata(
                state.TransportEpoch,
                state.RepairRequestId,
                state.Priority,
                state.RecoveryMode),
            FileTransferFrontierRequestFrameV6 request => IsPeerPostTunaFallbackV6RuntimeProofMetadata(
                request.TransportEpoch,
                request.RepairRequestId,
                request.Priority,
                request.RecoveryMode),
            _ => false,
        };

    private static bool IsCurrentPostTunaFallbackV6LiveRouteEpoch(LiveRouteEpoch? epoch)
        => epoch is
        {
            RouteSelection.Route: FileTransferRoute.PostTunaFallbackV6,
            RouteSelection.ProtocolVersion: FileTransferProtocol.ProtocolVersionV6,
            HandoffKind: FileTransferTransportHandoffKind.TunaToNormalFallback,
            TargetTransport: FileTransferTransportKind.RegularNkn,
        };

    private static bool IsCurrentPostTunaFallbackV6LiveRouteFrame(
        LiveRouteEpoch? epoch,
        FileTransferDataFrame frame)
        => IsCurrentPostTunaFallbackV6LiveRouteEpoch(epoch) &&
           FileTransferProtocol.IsV6DataFrame(frame);

    private static bool IsPeerPostTunaFallbackV6RuntimeProofMetadata(
        long transportEpoch,
        string? repairRequestId,
        string? priority,
        string? recoveryMode)
    {
        if (transportEpoch <= 0)
        {
            return false;
        }

        return ContainsPostTunaFallbackV6RuntimeProofToken(repairRequestId) ||
               ContainsPostTunaFallbackV6RuntimeProofToken(priority) ||
               ContainsPostTunaFallbackV6RuntimeProofToken(recoveryMode);
    }

    private static bool ContainsPostTunaFallbackV6RuntimeProofToken(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return false;
        }

        return value.Contains("post_tuna", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("fallback", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("regular_nkn", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("frontier", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("state_refresh", StringComparison.OrdinalIgnoreCase) ||
               value.Contains("checkpoint", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsRecoveredFileTunaV4LiveActivationEpoch(LiveRouteEpoch? epoch)
        => epoch is
        {
            RouteSelection.Route: FileTransferRoute.FileTunaV4,
            RouteSelection.ProtocolVersion: FileTransferProtocol.ProtocolVersionV4,
            HandoffKind: FileTransferTransportHandoffKind.NormalToTunaActivation,
            TargetTransport: FileTransferTransportKind.Tuna,
            State: "recovered",
        };

    private static bool IsPostRecoveryFileTunaV4LiveActivationEpoch(
        LiveRouteEpoch? epoch,
        int lastRecoveredLiveRouteEpochId)
        => lastRecoveredLiveRouteEpochId > 0 &&
           IsRecoveredFileTunaV4LiveActivationEpoch(epoch) &&
           epoch!.EpochId > lastRecoveredLiveRouteEpochId;

    private static long ResolveV6RuntimeProofTransportEpoch(FileTransferDataFrame frame)
        => frame switch
        {
            FileTransferReceiverStateFrameV6 state => state.TransportEpoch,
            FileTransferFrontierRequestFrameV6 request => request.TransportEpoch,
            FileTransferChunkBatchFrameV6 batch => batch.TransportEpoch,
            _ => 0,
        };

    private static bool IsFreshPostReactivationFallbackV6Proof(
        OutboundTransferContext context,
        FileTransferDataFrame frame)
        => IsFreshPostReactivationFallbackV6Proof(
            context,
            ResolveV6RuntimeProofTransportEpoch(frame));

    private static bool IsFreshPostReactivationFallbackV6Proof(
        OutboundTransferContext context,
        long frameTransportEpoch)
    {
        return frameTransportEpoch > 0 &&
               context.LastRecoveredV6TransportEpoch > 0 &&
               frameTransportEpoch >= context.LastRecoveredV6TransportEpoch &&
               context.LastRecoveredV6TransportEpochKind == FileTransferTransportHandoffKind.NormalToTunaActivation &&
               context.LastRecoveredV6TransportTargetTransport == FileTransferTransportKind.Tuna;
    }

    private static bool IsFreshPostReactivationFallbackV6Proof(
        InboundTransferContext context,
        FileTransferDataFrame frame)
        => IsFreshPostReactivationFallbackV6Proof(
            context,
            ResolveV6RuntimeProofTransportEpoch(frame));

    private static bool IsFreshPostReactivationFallbackV6Proof(
        InboundTransferContext context,
        long frameTransportEpoch)
    {
        return frameTransportEpoch > 0 &&
               context.LastRecoveredV6TransportEpoch > 0 &&
               frameTransportEpoch >= context.LastRecoveredV6TransportEpoch &&
               context.LastRecoveredV6TransportEpochKind == FileTransferTransportHandoffKind.NormalToTunaActivation &&
               context.LastRecoveredV6TransportTargetTransport == FileTransferTransportKind.Tuna;
    }

    private static bool IsStalePostReactivationFallbackV6Proof(
        OutboundTransferContext context,
        long frameTransportEpoch)
        => frameTransportEpoch > 0 &&
           context.LastRecoveredV6TransportEpoch > 0 &&
           frameTransportEpoch < context.LastRecoveredV6TransportEpoch &&
           context.LastRecoveredV6TransportEpochKind ==
               FileTransferTransportHandoffKind.NormalToTunaActivation &&
           context.LastRecoveredV6TransportTargetTransport ==
               FileTransferTransportKind.Tuna;

    private static bool IsStalePostReactivationFallbackV6Proof(
        InboundTransferContext context,
        long frameTransportEpoch)
        => frameTransportEpoch > 0 &&
           context.LastRecoveredV6TransportEpoch > 0 &&
           frameTransportEpoch < context.LastRecoveredV6TransportEpoch &&
           context.LastRecoveredV6TransportEpochKind ==
               FileTransferTransportHandoffKind.NormalToTunaActivation &&
           context.LastRecoveredV6TransportTargetTransport ==
               FileTransferTransportKind.Tuna;

    private static void LogPeerPostTunaFallbackV6ProofIgnoredAfterLiveActivation(
        FileTransferDirection direction,
        string transferId,
        string sessionId,
        FileTransferDataFrame frame,
        LiveRouteEpoch? currentEpoch)
        => LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_peer_post_tuna_fallback_v6_proof_ignored; direction={direction.ToString().ToLowerInvariant()}; transfer_id={transferId}; session_id={FormatProtocolLogValue(sessionId)}; frame_type={FormatProtocolLogValue(frame.Type)}; frame_transport_epoch={ResolveV6RuntimeProofTransportEpoch(frame)}; current_live_route_epoch={currentEpoch?.EpochId ?? 0}; current_handoff_kind={FormatFileTransferTransportHandoffKind(currentEpoch?.HandoffKind ?? FileTransferTransportHandoffKind.None)}; current_target_transport={FormatFileTransferTransportKind(currentEpoch?.TargetTransport ?? FileTransferTransportKind.Unknown)}; reason=stale_after_live_tuna_activation");

    private static bool ShouldAcceptLiveRouteV6ProbeFrame(InboundTransferContext context, FileTransferDataFrame frame)
        => frame is FileTransferTransportProbeFrameV6 &&
           context.CurrentLiveRouteEpoch is
           {
               HandoffKind: FileTransferTransportHandoffKind.NormalToTunaActivation,
               TargetTransport: FileTransferTransportKind.Tuna,
           };

    private bool TryPromoteOutboundFileTunaV4FallbackFromPeerV6Proof(
        OutboundTransferContext context,
        FileTransferDataFrame frame,
        out SessionFileTransferSnapshot? snapshot,
        OutboundSparsePumpInstall? receiveInstall = null,
        RuntimeOwnerToken? receiveRuntimeOwner = null,
        IFileTransferDataSession? receiveDataSession = null,
        long receiveDataSessionGeneration = 0)
    {
        snapshot = null;
        var currentLiveFallbackFrame = IsCurrentPostTunaFallbackV6LiveRouteFrame(context.CurrentLiveRouteEpoch, frame);
        if (!IsPeerPostTunaFallbackV6RuntimeProofFrame(frame) &&
            !currentLiveFallbackFrame)
        {
            return false;
        }

        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                (receiveDataSession is not null &&
                 !IsOutboundSparseReceiveResultCurrentLocked(
                     context,
                     receiveInstall,
                     receiveRuntimeOwner,
                     receiveDataSession,
                     receiveDataSessionGeneration,
                     out _)) ||
                context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4)
            {
                return false;
            }

            if (context.RouteRuntime.UsesRegularNknV4FastRuntime)
            {
                return TryRetainOutboundFileTransferRouteTransitionPeerFrameLocked(
                    context,
                    frame,
                    currentLiveFallbackFrame
                        ? "current_post_tuna_fallback_live_route_frame"
                        : "peer_post_tuna_fallback_v6_proof",
                    coordinatorEvidence: null,
                    out snapshot,
                    out _);
            }

            if (!context.RouteRuntime.UsesFileTunaV4Runtime)
            {
                return false;
            }

            var coordinatorState = CreateCoordinatorStateLocked(context);
            var bootstrapPeerBoundary =
                FileTransferCoordinator
                    .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                        coordinatorState,
                        frame,
                        out var bootstrapCommand,
                        out var bootstrapReasonCode);
            FileTransferFallbackV6ProofBootstrapPeerBoundary? proofBoundary = null;
            FileTransferFallbackV6ProofBootstrapPeerFrameBinding?
                bootstrapPeerBinding = null;
            if (bootstrapPeerBoundary &&
                FileTransferCoordinator
                    .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerProofBoundary(
                        coordinatorState,
                        frame,
                        out var exactProofBoundary,
                        out _))
            {
                proofBoundary = exactProofBoundary;
            }
            if (bootstrapPeerBoundary &&
                TryCreateFallbackV6ProofBootstrapPeerFrameBinding(
                    context,
                    frame,
                    FileTransferDirection.Outbound,
                    out var exactBootstrapPeerBinding))
            {
                bootstrapPeerBinding = exactBootstrapPeerBinding;
            }
            if (IsRecoveredFileTunaV4LiveActivationEpoch(context.CurrentLiveRouteEpoch) &&
                !IsFreshPostReactivationFallbackV6Proof(context, frame) &&
                !bootstrapPeerBoundary)
            {
                if (string.Equals(
                        bootstrapReasonCode,
                        "bootstrap_not_current",
                        StringComparison.Ordinal) &&
                    TryStageOutboundFallbackV6ProofBootstrapPeerFrameLocked(
                        context,
                        frame,
                        out var stagingReason))
                {
                    LogFallbackV6ProofBootstrapPeerFrameDecision(
                        context.SessionId,
                        context.TransferId,
                        FileTransferDirection.Outbound,
                        frame,
                        bootstrapCommand,
                        "staged",
                        stagingReason,
                        "evidence_only",
                        context.PendingFallbackV6ProofBootstrapPeerFrameBinding);
                    return true;
                }

                LogFallbackV6ProofBootstrapPeerFrameDecision(
                    context.SessionId,
                    context.TransferId,
                    FileTransferDirection.Outbound,
                    frame,
                    bootstrapCommand,
                    "rejected",
                    bootstrapReasonCode,
                    "none");
                LogPeerPostTunaFallbackV6ProofIgnoredAfterLiveActivation(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    frame,
                    context.CurrentLiveRouteEpoch);
                return false;
            }

            var peerFrameHandled =
                TryRetainOutboundFileTransferRouteTransitionPeerFrameLocked(
                    context,
                    frame,
                    currentLiveFallbackFrame
                        ? "current_post_tuna_fallback_live_route_frame"
                        : "peer_post_tuna_fallback_v6_proof",
                    proofBoundary?.PeerProofEvidence,
                    out snapshot,
                    out var peerFrameRetained);
            if (!peerFrameHandled)
            {
                if (bootstrapPeerBoundary)
                {
                    LogFallbackV6ProofBootstrapPeerFrameDecision(
                        context.SessionId,
                        context.TransferId,
                        FileTransferDirection.Outbound,
                        frame,
                        bootstrapCommand,
                        "rejected",
                        "peer_frame_retention_rejected",
                        "none");
                }
                return false;
            }

            if (bootstrapPeerBoundary)
            {
                LogFallbackV6ProofBootstrapPeerFrameDecision(
                    context.SessionId,
                    context.TransferId,
                    FileTransferDirection.Outbound,
                    frame,
                    bootstrapCommand,
                    peerFrameRetained ? "accepted" : "rejected",
                    peerFrameRetained
                        ? bootstrapReasonCode
                        : "peer_frame_retention_rejected",
                    peerFrameRetained && proofBoundary is not null
                        ? "peer_proof_binding_only"
                        : "peer_frame_retention_only",
                    bootstrapPeerBinding);
                if (peerFrameRetained && proofBoundary is not null)
                {
                    LogFallbackV6ProofBootstrapPeerBoundaryBound(
                        proofBoundary,
                        "Bound",
                        "bootstrap_peer_frame_bound",
                        bootstrapPeerBinding);
                }
            }
            return true;
        }
    }

    private bool TryPromoteInboundFileTunaV4FallbackFromPeerV6Proof(
        InboundTransferContext context,
        FileTransferDataFrame frame,
        out SessionFileTransferSnapshot? snapshot)
    {
        snapshot = null;
        var currentLiveFallbackFrame = IsCurrentPostTunaFallbackV6LiveRouteFrame(context.CurrentLiveRouteEpoch, frame);
        if (!IsPeerPostTunaFallbackV6RuntimeProofFrame(frame) &&
            !currentLiveFallbackFrame)
        {
            return false;
        }

        lock (gate)
        {
            if (!ReferenceEquals(inboundTransfer, context) ||
                context.IsTerminal ||
                context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4)
            {
                return false;
            }

            var canPromoteFromFileTuna = context.RouteRuntime.UsesFileTunaV4Runtime;
            var canPromoteFromRegularV4 = context.RouteRuntime.UsesRegularNknV4FastRuntime;
            if (!canPromoteFromFileTuna && !canPromoteFromRegularV4)
            {
                return false;
            }

            FileTransferFallbackV6ProofBootstrapCommand bootstrapCommand = null!;
            var bootstrapReasonCode = "bootstrap_not_current";
            var coordinatorState = CreateCoordinatorStateLocked(context);
            var bootstrapPeerBoundary = canPromoteFromFileTuna &&
                FileTransferCoordinator
                    .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerBoundary(
                        coordinatorState,
                        frame,
                        out bootstrapCommand,
                        out bootstrapReasonCode);
            FileTransferFallbackV6ProofBootstrapPeerBoundary? proofBoundary = null;
            FileTransferFallbackV6ProofBootstrapPeerFrameBinding?
                bootstrapPeerBinding = null;
            if (bootstrapPeerBoundary &&
                FileTransferCoordinator
                    .TryGetCurrentFileTransferFallbackV6ProofBootstrapPeerProofBoundary(
                        coordinatorState,
                        frame,
                        out var exactProofBoundary,
                        out _))
            {
                proofBoundary = exactProofBoundary;
            }
            if (bootstrapPeerBoundary &&
                TryCreateFallbackV6ProofBootstrapPeerFrameBinding(
                    context,
                    frame,
                    FileTransferDirection.Inbound,
                    out var exactBootstrapPeerBinding))
            {
                bootstrapPeerBinding = exactBootstrapPeerBinding;
            }
            if (canPromoteFromFileTuna &&
                IsRecoveredFileTunaV4LiveActivationEpoch(context.CurrentLiveRouteEpoch) &&
                !IsFreshPostReactivationFallbackV6Proof(context, frame) &&
                !bootstrapPeerBoundary)
            {
                if (string.Equals(
                        bootstrapReasonCode,
                        "bootstrap_not_current",
                        StringComparison.Ordinal) &&
                    TryStageInboundFallbackV6ProofBootstrapPeerFrameLocked(
                        context,
                        frame,
                        out var stagingReason))
                {
                    LogFallbackV6ProofBootstrapPeerFrameDecision(
                        context.SessionId,
                        context.TransferId,
                        FileTransferDirection.Inbound,
                        frame,
                        bootstrapCommand,
                        "staged",
                        stagingReason,
                        "evidence_only",
                        context.PendingFallbackV6ProofBootstrapPeerFrameBinding);
                    return true;
                }

                LogFallbackV6ProofBootstrapPeerFrameDecision(
                    context.SessionId,
                    context.TransferId,
                    FileTransferDirection.Inbound,
                    frame,
                    bootstrapCommand,
                    "rejected",
                    bootstrapReasonCode,
                    "none");
                LogPeerPostTunaFallbackV6ProofIgnoredAfterLiveActivation(
                    FileTransferDirection.Inbound,
                    context.TransferId,
                    context.SessionId,
                    frame,
                    context.CurrentLiveRouteEpoch);
                return false;
            }

            var promotionReason = currentLiveFallbackFrame
                ? "current_post_tuna_fallback_live_route_frame"
                : "peer_post_tuna_fallback_v6_proof";
            var promoted = TryRetainInboundFileTransferRouteTransitionPeerFrameLocked(
                context,
                frame,
                promotionReason,
                proofBoundary?.PeerProofEvidence,
                out snapshot,
                out var peerFrameRetained);
            if (!promoted)
            {
                if (bootstrapPeerBoundary)
                {
                    LogFallbackV6ProofBootstrapPeerFrameDecision(
                        context.SessionId,
                        context.TransferId,
                        FileTransferDirection.Inbound,
                        frame,
                        bootstrapCommand,
                        "rejected",
                        "peer_frame_retention_rejected",
                        "none");
                }
                return false;
            }

            if (bootstrapPeerBoundary)
            {
                LogFallbackV6ProofBootstrapPeerFrameDecision(
                    context.SessionId,
                    context.TransferId,
                    FileTransferDirection.Inbound,
                    frame,
                    bootstrapCommand,
                    peerFrameRetained ? "accepted" : "rejected",
                    peerFrameRetained
                        ? bootstrapReasonCode
                        : "peer_frame_retention_rejected",
                    peerFrameRetained && proofBoundary is not null
                        ? "peer_proof_binding_only"
                        : "peer_frame_retention_only",
                    bootstrapPeerBinding);
                if (peerFrameRetained && proofBoundary is not null)
                {
                    LogFallbackV6ProofBootstrapPeerBoundaryBound(
                        proofBoundary,
                        "Bound",
                        "bootstrap_peer_frame_bound",
                        bootstrapPeerBinding);
                }
            }
            return true;
        }
    }

    private static void LogFallbackV6ProofBootstrapPeerFrameDecision(
        string sessionId,
        string transferId,
        FileTransferDirection direction,
        FileTransferDataFrame frame,
        FileTransferFallbackV6ProofBootstrapCommand? command,
        string decisionStatus,
        string reasonCode,
        string authorityEffect,
        FileTransferFallbackV6ProofBootstrapPeerFrameBinding? binding = null)
    {
        var requestCorrelationId = frame is FileTransferFrontierRequestFrameV6 request
            ? request.RequestCorrelationId
            : null;
        var frameFingerprint =
            PostTunaFallbackPeerProofFrameIdentity.TryCreate(
                frame,
                out var frameIdentity)
                ? frameIdentity.Sha256
                : "(none)";
        var checkpoint = binding?.DurableCheckpoint;
        var sourceCommit = binding?.SourceRouteCommit;
        var bindingFields = binding is null
            ? "; peer_binding_present=0; peer_data_session_reference_generation=0; peer_data_session_generation=0; source_route=(none); source_protocol_version=0; source_live_route_epoch=0; source_runtime_generation=0; source_route_publication_generation=0; source_route_commit_generation=0; source_terminal_generation=0; source_leg_generation=0; source_transport_epoch=0; source_bridge_recovery_generation=0; source_checkpoint_request_id=(none); source_checkpoint_generation=0; source_durable_checkpoint_generation=0; source_state_epoch=0; source_contiguous_frontier=0; source_durable_highest=-1; source_chunk_count=0"
            : $"; peer_binding_present=1; peer_data_session_reference_generation={binding.DataSessionReferenceGeneration}; peer_data_session_generation={binding.DataSessionGeneration}; source_route={FormatProtocolLogValue(sourceCommit?.RouteToken ?? "(none)")}; source_protocol_version={sourceCommit?.ProtocolVersion ?? 0}; source_live_route_epoch={sourceCommit?.LiveRouteEpoch ?? 0}; source_runtime_generation={checkpoint?.SourceRuntimeOwner.RuntimeGeneration ?? 0}; source_route_publication_generation={checkpoint?.SourceRoutePublication.PublicationGeneration ?? 0}; source_route_commit_generation={sourceCommit?.CommitGeneration ?? 0}; source_terminal_generation={checkpoint?.SourceTerminalGeneration ?? 0}; source_leg_generation={checkpoint?.SourceLegGeneration ?? 0}; source_transport_epoch={checkpoint?.SourceTransportEpoch ?? 0}; source_bridge_recovery_generation={checkpoint?.SourceBridgeRecoveryGeneration ?? 0}; source_checkpoint_request_id={FormatProtocolLogValue(binding.CheckpointRequestId)}; source_checkpoint_generation={binding.CheckpointGeneration}; source_durable_checkpoint_generation={checkpoint?.CheckpointGeneration ?? 0}; source_state_epoch={checkpoint?.StateEpoch ?? 0}; source_contiguous_frontier={checkpoint?.ContiguousCommittedChunkIndex ?? 0}; source_durable_highest={checkpoint?.DurableHighestChunkIndex ?? -1}; source_chunk_count={checkpoint?.ChunkCount ?? 0}";
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_fallback_v6_proof_bootstrap_peer_frame_decided; session_id={FormatProtocolLogValue(sessionId)}; transfer_id={FormatProtocolLogValue(transferId)}; direction={direction.ToString().ToLowerInvariant()}; authority_id={FormatProtocolLogValue(command?.AuthorityId.ToString() ?? "(none)")}; bootstrap_generation={command?.BootstrapGeneration ?? 0}; fallback_epoch={command?.Observation.FallbackEpoch ?? 0}; target_transport_epoch={command?.TargetTransportEpoch ?? 0}; frame_kind={FormatProtocolLogValue(command?.FrameKind.ToString() ?? "(none)")}; frame_type={FormatProtocolLogValue(frame.Type)}; frame_transport_epoch={ResolveV6RuntimeProofTransportEpoch(frame)}; frame_fingerprint={FormatProtocolLogValue(frameFingerprint)}; request_correlation_id={FormatProtocolLogValue(requestCorrelationId ?? "(none)")}{bindingFields}; decision_status={FormatProtocolLogValue(decisionStatus)}; reason_code={FormatProtocolLogValue(reasonCode)}; authority_effect={FormatProtocolLogValue(authorityEffect)}; decision_reason={FormatProtocolLogValue(reasonCode)}");
    }

    private static void LogFallbackV6ProofBootstrapPeerBoundaryBound(
        FileTransferFallbackV6ProofBootstrapPeerBoundary boundary,
        string status,
        string reason,
        FileTransferFallbackV6ProofBootstrapPeerFrameBinding? binding = null)
        => LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_fallback_v6_proof_bootstrap_peer_boundary_bound; session_id={FormatProtocolLogValue(boundary.Command.Observation.SessionId)}; transfer_id={FormatProtocolLogValue(boundary.Command.Observation.TransferId)}; direction={boundary.Command.Observation.Direction.ToString().ToLowerInvariant()}; authority_id={FormatProtocolLogValue(boundary.Command.AuthorityId.ToString())}; bootstrap_generation={boundary.Command.BootstrapGeneration}; fallback_epoch={boundary.Command.Observation.FallbackEpoch}; source_route=file_tuna_v4; source_protocol_version=4; source_live_route_epoch={boundary.Command.SourceLiveRouteEpoch}; source_runtime_generation={boundary.Command.SourceRuntimeOwner.RuntimeGeneration}; source_route_publication_generation={boundary.Command.SourceRoutePublication.PublicationGeneration}; source_route_commit_generation={boundary.Command.SourceRouteCommit.CommitGeneration}; source_terminal_generation={boundary.Command.SourceTerminalGeneration}; source_leg_generation={boundary.Command.SourceLegGeneration}; source_transport_epoch={boundary.Command.SourceTransportEpoch}; source_bridge_recovery_generation={boundary.Command.SourceBridgeRecoveryGeneration}; source_data_session_generation={boundary.Command.SourceDataSessionGeneration}; source_checkpoint_request_id={FormatProtocolLogValue(binding?.CheckpointRequestId ?? "(none)")}; source_checkpoint_generation={binding?.CheckpointGeneration ?? 0}; source_durable_checkpoint_generation={boundary.Command.Observation.DurableCheckpoint.CheckpointGeneration}; source_state_epoch={boundary.Command.Observation.DurableCheckpoint.StateEpoch}; source_contiguous_frontier={boundary.Command.Observation.DurableCheckpoint.ContiguousCommittedChunkIndex}; source_durable_highest={boundary.Command.Observation.DurableCheckpoint.DurableHighestChunkIndex}; source_chunk_count={boundary.Command.Observation.DurableCheckpoint.ChunkCount}; target_route=post_tuna_fallback_v6; target_protocol_version=6; target_transport_epoch={boundary.Command.TargetTransportEpoch}; local_receipt_status={boundary.LocalDeliveryReceipt.Status}; local_frame_fingerprint={FormatProtocolLogValue(boundary.LocalDeliveryReceipt.FrameIdentity?.Sha256 ?? "(none)")}; peer_frame_type={FormatProtocolLogValue(boundary.PeerFrameIdentity.FrameType)}; peer_frame_fingerprint={FormatProtocolLogValue(boundary.PeerFrameIdentity.Sha256)}; proof_generation={boundary.PeerProofEvidence.ProofGeneration}; proof_kind={FormatProtocolLogValue(boundary.PeerProofEvidence.ProofKind)}; pairing_status={FormatProtocolLogValue(status)}; authority_effect=peer_proof_binding_only; decision_reason={reason}");

    private bool ShouldBoundOutboundV4TransportSendForV6RegularNknSparseRuntime(OutboundTransferContext context)
    {
        if (!ShouldUseV6RegularNknSparseRuntime(context))
        {
            return false;
        }

        lock (gate)
        {
            return ReferenceEquals(outboundTransfer, context) &&
                   !context.IsTerminal &&
                   IsOutboundV6PrimaryRegularNknWithoutTunaRecoveryLocked(context);
        }
    }

    private bool ShouldBoundOutboundV4TransportSendForFileTunaV4PostTunaRecovery(OutboundTransferContext context)
    {
        lock (gate)
        {
            return ReferenceEquals(outboundTransfer, context) &&
                   !context.IsTerminal &&
                   IsOutboundFileTunaV4PostTunaRecoveryActiveLocked(context);
        }
    }

    private bool ShouldBoundOutboundV4TransportSendForPostTunaFallbackV6LiveSparseRecovery(OutboundTransferContext context)
    {
        lock (gate)
        {
            return ReferenceEquals(outboundTransfer, context) &&
                   !context.IsTerminal &&
                   IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(context);
        }
    }

    private bool ShouldBoundOutboundV4TransportSendForRegularNknV4FastRuntime(OutboundTransferContext context)
    {
        lock (gate)
        {
            return ReferenceEquals(outboundTransfer, context) &&
                   !context.IsTerminal &&
                   context.RouteRuntime.UsesRegularNknV4FastRuntime &&
                   context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
                   context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4;
        }
    }

    private bool ShouldBoundOutboundV4TransportSend(OutboundTransferContext context)
        => ShouldBoundOutboundV4TransportSendForV6RegularNknSparseRuntime(context) ||
           ShouldBoundOutboundV4TransportSendForFileTunaV4PostTunaRecovery(context) ||
           ShouldBoundOutboundV4TransportSendForPostTunaFallbackV6LiveSparseRecovery(context) ||
           ShouldBoundOutboundV4TransportSendForRegularNknV4FastRuntime(context);

    private static TimeSpan CurrentV6RegularNknSparseRuntimeV4TransportSendTimeout =>
        V6RegularNknSparseRuntimeV4TransportSendTimeoutOverrideForTests ??
        TimeSpan.FromMilliseconds(V6RegularNknSparseRuntimeV4TransportSendTimeoutMs);

    private FileTransferManifestFrameV4 CreateOutboundV4ManifestFrame(
        OutboundTransferContext context,
        bool? useV6EnvelopeOverride = null)
    {
        if (useV6EnvelopeOverride ?? ShouldUseV6SparseCreditEnvelope(context))
        {
            return new FileTransferManifestFrameV6
            {
                SessionId = context.SessionId,
                TransferId = context.TransferId,
                FileName = context.FileName,
                FileSizeBytes = context.FileSizeBytes,
                ChunkSizeBytes = context.ChunkSizeBytes,
                ChunkCount = context.ChunkCount,
                Sha256Base64 = context.Sha256Base64!,
            };
        }

        return new FileTransferManifestFrameV4
        {
            SessionId = context.SessionId,
            TransferId = context.TransferId,
            FileName = context.FileName,
            FileSizeBytes = context.FileSizeBytes,
            ChunkSizeBytes = context.ChunkSizeBytes,
            ChunkCount = context.ChunkCount,
            Sha256Base64 = context.Sha256Base64!,
        };
    }

    private static bool SupportsOutboundSparsePumpInstall(OutboundTransferContext context)
        => (context.RouteSelection.Route is FileTransferRoute.RegularNknV4Fast or
                FileTransferRoute.FileTunaV4 or
                FileTransferRoute.PostTunaFallbackV6 or
                FileTransferRoute.DiagnosticRegularNknV6) &&
           (context.RouteSelection.ProtocolVersion is FileTransferProtocol.ProtocolVersionV4 or
                FileTransferProtocol.ProtocolVersionV6);

    private bool IsOutboundSparsePumpInstallCurrentLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall install,
        IFileTransferDataSession? expectedDataSession,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (!ReferenceEquals(outboundTransfer, context))
        {
            rejectionReason = "transfer_context_replaced";
            return false;
        }

        if (context.IsTerminal)
        {
            rejectionReason = "transfer_terminal";
            return false;
        }

        if (!SupportsOutboundSparsePumpInstall(context))
        {
            rejectionReason = "sparse_runtime_not_current";
            return false;
        }

        if (context.InstalledOutboundSparsePump != install &&
            context.PendingOutboundSparsePumpInstall != install)
        {
            rejectionReason = "install_generation_mismatch";
            return false;
        }

        if (context.DataSession is null)
        {
            rejectionReason = "data_session_missing";
            return false;
        }

        if (expectedDataSession is not null && !ReferenceEquals(context.DataSession, expectedDataSession))
        {
            rejectionReason = "data_session_replaced";
            return false;
        }

        if (context.DataSessionGeneration != install.DataSessionGeneration)
        {
            rejectionReason = "data_session_generation_mismatch";
            return false;
        }

        if (context.CurrentRuntimeOwner is not { } owner || owner.IsDefault)
        {
            rejectionReason = "runtime_owner_missing";
            return false;
        }

        if (owner != install.RuntimeOwner)
        {
            rejectionReason = "runtime_owner_replaced";
            return false;
        }

        if (context.CurrentRoutePublicationToken is not { } publication || publication.IsDefault)
        {
            rejectionReason = "route_publication_missing";
            return false;
        }

        if (publication != install.RoutePublication)
        {
            rejectionReason = "route_publication_replaced";
            return false;
        }

        if (context.CurrentTransferLeg is not { } leg ||
            context.TerminalGeneration != install.TerminalGeneration ||
            leg.Generation != install.LegGeneration ||
            publication.RuntimeOwner != owner ||
            publication.SessionId != context.SessionId ||
            publication.TransferId != context.TransferId ||
            publication.Direction != FileTransferDirection.Outbound ||
            publication.Route != context.RouteSelection.Route ||
            publication.RouteToken != context.RouteSelection.TelemetryToken ||
            publication.ProtocolVersion != context.NegotiatedDataProtocolVersion ||
            publication.LiveRouteEpoch != (context.CurrentLiveRouteEpoch?.EpochId ?? 0) ||
            publication.RuntimeGeneration != owner.RuntimeGeneration ||
            publication.TerminalGeneration != context.TerminalGeneration ||
            publication.LegGeneration != leg.Generation)
        {
            rejectionReason = "coordinator_tuple_mismatch";
            return false;
        }

        return true;
    }

    private bool IsOutboundSparseReceiveResultCurrentLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall? receiveInstall,
        RuntimeOwnerToken? receiveRuntimeOwner,
        IFileTransferDataSession? receiveDataSession,
        long receiveDataSessionGeneration,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (!ReferenceEquals(outboundTransfer, context))
        {
            rejectionReason = "transfer_context_replaced";
            return false;
        }

        if (context.IsTerminal)
        {
            rejectionReason = "transfer_terminal";
            return false;
        }

        if (receiveDataSession is null || !ReferenceEquals(context.DataSession, receiveDataSession))
        {
            rejectionReason = "data_session_replaced";
            return false;
        }

        if (context.DataSessionGeneration != receiveDataSessionGeneration)
        {
            rejectionReason = "data_session_generation_mismatch";
            return false;
        }

        if (receiveRuntimeOwner is null ||
            receiveRuntimeOwner.Value.IsDefault ||
            context.CurrentRuntimeOwner != receiveRuntimeOwner)
        {
            rejectionReason = "runtime_owner_replaced";
            return false;
        }

        if (receiveInstall is null)
        {
            rejectionReason = "receive_install_missing";
            return false;
        }

        if (context.InstalledOutboundSparsePump != receiveInstall ||
            !IsOutboundSparsePumpInstallCurrentLocked(
                context,
                receiveInstall,
                receiveDataSession,
                out rejectionReason))
        {
            if (string.Equals(rejectionReason, "accepted", StringComparison.Ordinal))
            {
                rejectionReason = "receive_install_replaced";
            }

            return false;
        }

        return true;
    }

    private bool IsOutboundSparsePumpContinuationCurrentLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall? pumpInstall,
        IFileTransferDataSession dataSession)
        => pumpInstall is null
            ? ReferenceEquals(outboundTransfer, context) && !context.IsTerminal
            : IsOutboundSparsePumpInstallCurrentLocked(
                context,
                pumpInstall,
                dataSession,
                out _);

    private bool IsOutboundSparseReceiveSessionCurrentLocked(
        OutboundTransferContext context,
        IFileTransferDataSession? receiveDataSession,
        long receiveDataSessionGeneration,
        long receiveSupervisorGeneration,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (!ReferenceEquals(outboundTransfer, context))
        {
            rejectionReason = "transfer_context_replaced";
            return false;
        }

        if (context.IsTerminal)
        {
            rejectionReason = "transfer_terminal";
            return false;
        }

        if (context.ActiveOutboundSparseReceiveSupervisorGeneration != receiveSupervisorGeneration)
        {
            rejectionReason = "receive_supervisor_replaced";
            return false;
        }

        if (receiveDataSession is null || !ReferenceEquals(context.DataSession, receiveDataSession))
        {
            rejectionReason = "data_session_replaced";
            return false;
        }

        if (context.DataSessionGeneration != receiveDataSessionGeneration)
        {
            rejectionReason = "data_session_generation_mismatch";
            return false;
        }

        return true;
    }

    private bool TryResolveOutboundSparseReceiveDispatchInstallLocked(
        OutboundTransferContext context,
        IFileTransferDataSession? receiveDataSession,
        long receiveDataSessionGeneration,
        long receiveSupervisorGeneration,
        out OutboundSparsePumpInstall? receiveInstall,
        out RuntimeOwnerToken? receiveRuntimeOwner,
        out string rejectionReason)
    {
        receiveInstall = null;
        receiveRuntimeOwner = null;
        if (!IsOutboundSparseReceiveSessionCurrentLocked(
                context,
                receiveDataSession,
                receiveDataSessionGeneration,
                receiveSupervisorGeneration,
                out rejectionReason))
        {
            return false;
        }

        var installed = context.InstalledOutboundSparsePump;
        if (installed is not null &&
            IsOutboundSparsePumpInstallCurrentLocked(
                context,
                installed,
                receiveDataSession,
                out rejectionReason))
        {
            receiveInstall = installed;
        }
        else if (context.PendingOutboundSparsePumpInstall is { } pending &&
                 IsOutboundSparsePumpInstallCurrentLocked(
                     context,
                     pending,
                     receiveDataSession,
                     out rejectionReason))
        {
            receiveInstall = pending;
        }
        else
        {
            rejectionReason = string.Equals(rejectionReason, "accepted", StringComparison.Ordinal)
                ? "receive_install_missing"
                : rejectionReason;
            return false;
        }

        receiveRuntimeOwner = receiveInstall.RuntimeOwner;
        return true;
    }

    private static bool CanRebindOutboundSparseReceiveFrameAcrossInstall(
        FileTransferDataFrame frame)
        => frame is FileTransferFrontierRequestFrameV6;

    private static string FormatOutboundSparsePumpInstallTuple(OutboundSparsePumpInstall install)
    {
        var owner = install.RuntimeOwner;
        var publication = install.RoutePublication;
        var publicationOwner = publication.RuntimeOwner;
        return $"install_generation={install.InstallGeneration}; predecessor_install_generation={install.PredecessorInstallGeneration}; session_id={FormatProtocolLogValue(owner.SessionId)}; transfer_id={FormatProtocolLogValue(owner.TransferId)}; direction=outbound; route={FormatProtocolLogValue(publication.RouteToken)}; protocol_version={publication.ProtocolVersion}; live_route_epoch={publication.LiveRouteEpoch}; runtime_generation={publication.RuntimeGeneration}; terminal_generation={publication.TerminalGeneration}; leg_generation={publication.LegGeneration}; route_publication_generation={publication.PublicationGeneration}; route_commit_generation={publication.RouteCommitGeneration ?? 0}; target_route={FormatProtocolLogValue(FileTransferRouteResolver.Resolve(publication.TargetRoute).TelemetryToken)}; target_protocol_version={publication.TargetProtocolVersion}; target_transport={FormatFileTransferTransportKind(publication.TargetTransport)}; data_session_generation={install.DataSessionGeneration}; runtime_family={FormatProtocolLogValue(owner.RuntimeFamily)}; descriptor_terminal_generation={install.TerminalGeneration}; descriptor_leg_generation={install.LegGeneration}; installation_reason={FormatProtocolLogValue(install.Reason)}; runtime_owner_session_id={FormatProtocolLogValue(owner.SessionId)}; runtime_owner_transfer_id={FormatProtocolLogValue(owner.TransferId)}; runtime_owner_direction={FormatFileTransferDirection(owner.Direction)}; runtime_owner_route={FormatProtocolLogValue(FileTransferRouteResolver.Resolve(owner.Route).TelemetryToken)}; runtime_owner_route_token={FormatProtocolLogValue(owner.RouteToken)}; runtime_owner_protocol_version={owner.ProtocolVersion}; runtime_owner_live_route_epoch={owner.LiveRouteEpoch}; runtime_owner_runtime_generation={owner.RuntimeGeneration}; runtime_owner_terminal_generation={owner.TerminalGeneration}; runtime_owner_runtime_family={FormatProtocolLogValue(owner.RuntimeFamily)}; runtime_owner_created_reason={FormatProtocolLogValue(owner.CreatedReason)}; route_publication_session_id={FormatProtocolLogValue(publication.SessionId)}; route_publication_transfer_id={FormatProtocolLogValue(publication.TransferId)}; route_publication_direction={FormatFileTransferDirection(publication.Direction)}; route_publication_route={FormatProtocolLogValue(FileTransferRouteResolver.Resolve(publication.Route).TelemetryToken)}; route_publication_route_token={FormatProtocolLogValue(publication.RouteToken)}; route_publication_protocol_version={publication.ProtocolVersion}; route_publication_live_route_epoch={publication.LiveRouteEpoch}; route_publication_runtime_generation={publication.RuntimeGeneration}; route_publication_terminal_generation={publication.TerminalGeneration}; route_publication_leg_generation={publication.LegGeneration}; route_publication_route_commit_generation={publication.RouteCommitGeneration ?? 0}; route_publication_target_route={FormatProtocolLogValue(FileTransferRouteResolver.Resolve(publication.TargetRoute).TelemetryToken)}; route_publication_target_protocol_version={publication.TargetProtocolVersion}; route_publication_target_transport={FormatFileTransferTransportKind(publication.TargetTransport)}; route_publication_token_generation={publication.PublicationGeneration}; route_publication_action_kind={FormatProtocolLogValue(publication.ActionKind.ToString())}; route_publication_reason={FormatProtocolLogValue(publication.Reason)}; route_publication_owner_session_id={FormatProtocolLogValue(publicationOwner.SessionId)}; route_publication_owner_transfer_id={FormatProtocolLogValue(publicationOwner.TransferId)}; route_publication_owner_direction={FormatFileTransferDirection(publicationOwner.Direction)}; route_publication_owner_route={FormatProtocolLogValue(FileTransferRouteResolver.Resolve(publicationOwner.Route).TelemetryToken)}; route_publication_owner_route_token={FormatProtocolLogValue(publicationOwner.RouteToken)}; route_publication_owner_protocol_version={publicationOwner.ProtocolVersion}; route_publication_owner_live_route_epoch={publicationOwner.LiveRouteEpoch}; route_publication_owner_runtime_generation={publicationOwner.RuntimeGeneration}; route_publication_owner_terminal_generation={publicationOwner.TerminalGeneration}; route_publication_owner_runtime_family={FormatProtocolLogValue(publicationOwner.RuntimeFamily)}; route_publication_owner_created_reason={FormatProtocolLogValue(publicationOwner.CreatedReason)}";
    }

    private bool TryStageOutboundSparsePumpInstallLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall? predecessor,
        string reason,
        out OutboundSparsePumpInstall? pendingInstall,
        out string rejectionReason)
    {
        pendingInstall = null;
        rejectionReason = "accepted";
        if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
        {
            rejectionReason = context.IsTerminal ? "transfer_terminal" : "transfer_context_replaced";
            return false;
        }

        if (!SupportsOutboundSparsePumpInstall(context) ||
            context.DataSession is null ||
            context.DataSessionGeneration <= 0 ||
            context.CurrentRuntimeOwner is not { IsDefault: false } owner ||
            context.CurrentRoutePublicationToken is not { IsDefault: false } publication ||
            context.CurrentTransferLeg is not { } leg)
        {
            rejectionReason = !SupportsOutboundSparsePumpInstall(context)
                ? "sparse_runtime_not_current"
                : context.DataSession is null || context.DataSessionGeneration <= 0
                    ? "data_session_missing"
                    : context.CurrentRuntimeOwner is not { IsDefault: false }
                        ? "runtime_owner_missing"
                        : context.CurrentRoutePublicationToken is not { IsDefault: false }
                            ? "route_publication_missing"
                            : "transfer_leg_missing";
            return false;
        }

        if (predecessor is null)
        {
            if (context.InstalledOutboundSparsePump is not null)
            {
                rejectionReason = "predecessor_install_missing";
                return false;
            }
        }
        else if (context.InstalledOutboundSparsePump != predecessor)
        {
            rejectionReason = "predecessor_install_mismatch";
            return false;
        }

        if (context.PendingOutboundSparsePumpInstall is { } existingPending)
        {
            if (existingPending.RuntimeOwner == owner &&
                existingPending.RoutePublication == publication &&
                existingPending.TerminalGeneration == context.TerminalGeneration &&
                existingPending.LegGeneration == leg.Generation &&
                existingPending.DataSessionGeneration == context.DataSessionGeneration &&
                existingPending.PredecessorInstallGeneration == (predecessor?.InstallGeneration ?? 0))
            {
                pendingInstall = existingPending;
                rejectionReason = "idempotent";
                return true;
            }

            rejectionReason = "pending_install_exists";
            return false;
        }

        var installGeneration = Math.Max(1, context.LastOutboundSparsePumpInstallGeneration + 1);
        pendingInstall = new OutboundSparsePumpInstall(
            installGeneration,
            predecessor?.InstallGeneration ?? 0,
            owner,
            publication,
            context.TerminalGeneration,
            leg.Generation,
            context.DataSessionGeneration,
            NormalizeReason(reason) ?? "unspecified");
        context.LastOutboundSparsePumpInstallGeneration = installGeneration;
        context.PendingOutboundSparsePumpInstall = pendingInstall;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_outbound_sparse_worker_handoff_required; {FormatOutboundSparsePumpInstallTuple(pendingInstall)}; retired_runtime_generation={predecessor?.RuntimeOwner.RuntimeGeneration ?? 0}; retired_route={FormatProtocolLogValue(predecessor?.RuntimeOwner.RouteToken ?? "(none)")}; decision_reason={FormatProtocolLogValue(pendingInstall.Reason)}");
        return true;
    }

    private bool TryCommitOutboundSparsePumpInstallLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall pendingInstall,
        IFileTransferDataSession dataSession,
        out OutboundSparsePumpInstall? installed,
        out string rejectionReason)
    {
        installed = null;
        rejectionReason = "accepted";
        if (context.InstalledOutboundSparsePump == pendingInstall)
        {
            if (!IsOutboundSparsePumpInstallCurrentLocked(
                    context,
                    pendingInstall,
                    dataSession,
                    out rejectionReason))
            {
                DiscardOutboundSparseFrontierDispatchProofsLocked(
                    context,
                    pendingInstall,
                    rejectionReason);
                LogOutboundSparsePumpInstallRejected(context, pendingInstall, "commit", rejectionReason);
                return false;
            }

            installed = pendingInstall;
            rejectionReason = "idempotent";
            return true;
        }

        if (context.PendingOutboundSparsePumpInstall != pendingInstall)
        {
            rejectionReason = "pending_install_mismatch";
            DiscardOutboundSparseFrontierDispatchProofsLocked(
                context,
                pendingInstall,
                rejectionReason);
            LogOutboundSparsePumpInstallRejected(context, pendingInstall, "commit", rejectionReason);
            return false;
        }

        if (pendingInstall.PredecessorInstallGeneration == 0
                ? context.InstalledOutboundSparsePump is not null
                : context.InstalledOutboundSparsePump?.InstallGeneration !=
                  pendingInstall.PredecessorInstallGeneration)
        {
            rejectionReason = "predecessor_install_mismatch";
            context.PendingOutboundSparsePumpInstall = null;
            DiscardOutboundSparseFrontierDispatchProofsLocked(
                context,
                pendingInstall,
                rejectionReason);
            LogOutboundSparsePumpInstallRejected(context, pendingInstall, "commit", rejectionReason);
            return false;
        }

        if (!IsOutboundSparsePumpInstallCurrentLocked(
                context,
                pendingInstall,
                dataSession,
                out rejectionReason))
        {
            context.PendingOutboundSparsePumpInstall = null;
            DiscardOutboundSparseFrontierDispatchProofsLocked(
                context,
                pendingInstall,
                rejectionReason);
            LogOutboundSparsePumpInstallRejected(context, pendingInstall, "commit", rejectionReason);
            return false;
        }

        context.PendingOutboundSparsePumpInstall = null;
        context.InstalledOutboundSparsePump = pendingInstall;
        installed = pendingInstall;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_outbound_sparse_worker_handoff_installed; {FormatOutboundSparsePumpInstallTuple(pendingInstall)}; decision_reason={FormatProtocolLogValue(pendingInstall.Reason)}");
        FlushOutboundSparseFrontierDispatchProofsLocked(context, pendingInstall);
        return true;
    }

    private static void StageOutboundSparseFrontierDispatchProofLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall install,
        FileTransferFrontierRequestFrameV6 request,
        FileTransferTransportKind receivedTransportKind,
        int firstStartChunkIndex,
        int firstChunkCount,
        int rangeCount)
    {
        var correlationKey =
            $"{install.InstallGeneration}:{request.TransportEpoch}:{request.Priority}:{request.RecoveryMode}:{string.Join(',', request.MissingRanges.Select(static range => $"{range.StartChunkIndex}:{range.ChunkCount}"))}";
        if (!context.PendingOutboundSparseFrontierDispatchProofs.ContainsKey(correlationKey) &&
            context.PendingOutboundSparseFrontierDispatchProofs.Count >=
            OutboundSparsePendingFrontierDispatchProofLimit)
        {
            var retiredKey = context.PendingOutboundSparseFrontierDispatchProofs.Keys.First();
            context.PendingOutboundSparseFrontierDispatchProofs.Remove(retiredKey);
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v6_frontier_request_receive_dispatch_rejected; {FormatOutboundSparsePumpInstallTuple(install)}; transport_epoch={request.TransportEpoch}; repair_request_id={FormatProtocolLogValue(request.RepairRequestId ?? "(none)")}; request_correlation_id={FormatProtocolLogValue(request.RequestCorrelationId ?? "(none)")}; first_start_chunk_index={firstStartChunkIndex}; first_chunk_count={firstChunkCount}; range_count={rangeCount}; decision_reason=pending_install_dispatch_proof_capacity_replaced; retired_correlation_key={FormatProtocolLogValue(retiredKey)}");
        }

        context.PendingOutboundSparseFrontierDispatchProofs[correlationKey] =
            new OutboundSparseFrontierDispatchProof(
                correlationKey,
                install,
                request with
                {
                    MissingRanges = request.MissingRanges
                        .Select(static range => range with { })
                        .ToArray(),
                },
                request.TransportEpoch,
                request.RepairRequestId,
                request.RequestCorrelationId,
                firstStartChunkIndex,
                firstChunkCount,
                rangeCount,
                receivedTransportKind);
    }

    private void FlushOutboundSparseFrontierDispatchProofsLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall installed)
    {
        if (context.PendingOutboundSparseFrontierDispatchProofs.Count == 0)
        {
            return;
        }

        foreach (var pair in context.PendingOutboundSparseFrontierDispatchProofs.ToArray())
        {
            var proof = pair.Value;
            context.PendingOutboundSparseFrontierDispatchProofs.Remove(pair.Key);
            if (proof.Install != installed)
            {
                LogOutboundSparsePumpInstallRejected(
                    context,
                    proof.Install,
                    "frontier_dispatch_proof",
                    "install_no_longer_current");
                continue;
            }

            ApplyOutboundV6RepairRequestCore(
                context,
                proof.Request,
                proof.ReceivedTransportKind,
                installed,
                installed.RuntimeOwner,
                context.DataSession,
                context.DataSessionGeneration,
                context.ActiveOutboundSparseReceiveSupervisorGeneration);
        }
    }

    private static void DiscardOutboundSparseFrontierDispatchProofsLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall invalidatedInstall,
        string reason)
    {
        foreach (var pair in context.PendingOutboundSparseFrontierDispatchProofs
                     .Where(pair => pair.Value.Install == invalidatedInstall)
                     .ToArray())
        {
            context.PendingOutboundSparseFrontierDispatchProofs.Remove(pair.Key);
            var proof = pair.Value;
            LogOutboundV6FrontierRequestReceiveDispatch(
                context,
                proof.Request,
                proof.ReceivedTransportKind,
                "rejected",
                reason,
                proof.FirstStartChunkIndex,
                proof.FirstChunkCount,
                proof.RangeCount,
                invalidatedInstall);
        }
    }

    private static void LogOutboundSparsePumpInstallRejected(
        OutboundTransferContext context,
        OutboundSparsePumpInstall? install,
        string stage,
        string reason)
    {
        var tuple = install is null
            ? $"install_generation=0; predecessor_install_generation=0; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.TerminalGeneration}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; route_publication_generation={context.CurrentRoutePublicationToken?.PublicationGeneration ?? 0}; route_commit_generation={context.CurrentRoutePublicationToken?.RouteCommitGeneration ?? 0}; target_route={FormatProtocolLogValue(context.CurrentRoutePublicationToken is { } publication ? FileTransferRouteResolver.Resolve(publication.TargetRoute).TelemetryToken : "(none)")}; target_protocol_version={context.CurrentRoutePublicationToken?.TargetProtocolVersion ?? 0}; target_transport={FormatFileTransferTransportKind(context.CurrentRoutePublicationToken?.TargetTransport ?? FileTransferTransportKind.Unknown)}; data_session_generation={context.DataSessionGeneration}"
            : FormatOutboundSparsePumpInstallTuple(install);
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_outbound_sparse_worker_handoff_rejected; {tuple}; stage={FormatProtocolLogValue(stage)}; decision_reason={FormatProtocolLogValue(reason)}; current_route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; current_protocol_version={context.NegotiatedDataProtocolVersion}; current_live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; current_runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; current_terminal_generation={context.TerminalGeneration}; current_leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; current_route_publication_generation={context.CurrentRoutePublicationToken?.PublicationGeneration ?? 0}; current_route_commit_generation={context.CurrentRoutePublicationToken?.RouteCommitGeneration ?? 0}; current_data_session_generation={context.DataSessionGeneration}");
    }

    private bool TryUpdateOutboundSparseBootstrapStateIfCurrent(
        OutboundTransferContext context,
        OutboundSparsePumpInstall requiredInstall,
        IFileTransferDataSession requiredDataSession,
        FileTransferTransferState state,
        string statusMessage,
        bool markManifestDispatched,
        string stage,
        out string rejectionReason)
    {
        SessionFileTransferSnapshot? snapshot;
        lock (gate)
        {
            if (context.PendingOutboundSparsePumpInstall != requiredInstall)
            {
                rejectionReason = "pending_install_mismatch";
                LogOutboundSparsePumpInstallRejected(
                    context,
                    requiredInstall,
                    stage,
                    rejectionReason);
                return false;
            }

            if (!IsOutboundSparsePumpInstallCurrentLocked(
                    context,
                    requiredInstall,
                    requiredDataSession,
                    out rejectionReason))
            {
                LogOutboundSparsePumpInstallRejected(
                    context,
                    requiredInstall,
                    stage,
                    rejectionReason);
                return false;
            }

            context.State = state;
            context.BytesTransferred = 0;
            context.ChunksTransferred = 0;
            context.BytesAcknowledgedByReceiver = Math.Max(context.BytesAcknowledgedByReceiver, 0);
            context.StatusMessage = context.UserPaused
                ? "Transfer paused."
                : context.PeerPaused
                    ? "Peer paused transfer."
                    : statusMessage;
            if (markManifestDispatched)
            {
                context.OutboundSparseManifestDispatched = true;
            }
            snapshot = CreateSnapshotLocked();
        }

        RaiseTransferChanged(snapshot);
        MaybeLogProgressMilestone(context, FileTransferDirection.Outbound);
        rejectionReason = "accepted";
        return true;
    }

    private static bool HasOutboundSparsePumpWorkLocked(OutboundTransferContext context)
        => context.PullV4SenderPumpRepairQueue.Count > 0 ||
           (!context.V4TerminalReady &&
            Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount) > context.ChunksAcceptedForTransport);

    private async Task<OutboundSparsePumpRuntime?> TryInstallOutboundSparsePumpAsync(
        OutboundTransferContext context,
        OutboundSparsePumpInstall? predecessor,
        Stream? reusableStream,
        bool reopenSource,
        string reason,
        CancellationToken installCancellationToken)
    {
        OutboundSparsePumpInstall? pending;
        IFileTransferDataSession? dataSession;
        int chunksAcceptedForTransport;
        lock (gate)
        {
            if (!TryStageOutboundSparsePumpInstallLocked(
                    context,
                    predecessor,
                    reason,
                    out pending,
                    out var stageRejection) ||
                pending is null)
            {
                LogOutboundSparsePumpInstallRejected(context, predecessor, "stage", stageRejection);
                return null;
            }

            dataSession = context.DataSession;
            chunksAcceptedForTransport = context.ChunksAcceptedForTransport;
        }

        Stream? pumpStream = reusableStream;
        var openedReplacementStream = false;
        try
        {
            if (pumpStream is null || reopenSource)
            {
                if (reopenSource &&
                    OutboundSparseSourceReopenBarrierForTests is { } sourceReopenBarrier)
                {
                    await sourceReopenBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                }

                pumpStream = await context.OpenReadStreamAsync(installCancellationToken).ConfigureAwait(false);
                openedReplacementStream = true;
                ValidateReadableStream(pumpStream);
                if (reopenSource && !pumpStream.CanSeek && chunksAcceptedForTransport > 0)
                {
                    throw new InvalidOperationException("A non-seekable source cannot be rebound after sparse sender progress.");
                }
            }
        }
        catch (OperationCanceledException) when (installCancellationToken.IsCancellationRequested)
        {
            if (openedReplacementStream && pumpStream is not null)
            {
                await DisposeOutboundSparsePumpStreamDiagnosticOnlyAsync(pumpStream).ConfigureAwait(false);
            }

            lock (gate)
            {
                if (context.PendingOutboundSparsePumpInstall == pending)
                {
                    context.PendingOutboundSparsePumpInstall = null;
                }

                LogOutboundSparsePumpInstallRejected(context, pending, "source_open", "install_invalidated");
            }

            return null;
        }
        catch (Exception ex)
        {
            if (openedReplacementStream && pumpStream is not null)
            {
                await DisposeOutboundSparsePumpStreamDiagnosticOnlyAsync(pumpStream).ConfigureAwait(false);
            }

            var sourceFailureCurrent = false;
            lock (gate)
            {
                sourceFailureCurrent = context.PendingOutboundSparsePumpInstall == pending &&
                    dataSession is not null &&
                    IsOutboundSparsePumpInstallCurrentLocked(
                        context,
                        pending,
                        dataSession,
                        out _);
                if (!sourceFailureCurrent &&
                    context.PendingOutboundSparsePumpInstall == pending)
                {
                    context.PendingOutboundSparsePumpInstall = null;
                }

                LogOutboundSparsePumpInstallRejected(
                    context,
                    pending,
                    "source_open",
                    sourceFailureCurrent ? "source_stream_open_failed" : "install_invalidated");
            }

            if (!sourceFailureCurrent)
            {
                return null;
            }

            var errorCode = ClassifyOutboundFailureErrorCode(ex, StreamReadFailedErrorCode);
            await FailOutboundV4Async(
                    context,
                    dataSession,
                    pending.RuntimeOwner,
                    errorCode,
                    ClassifyOutboundFailureStatusMessage(ex, errorCode),
                    notifyPeer: true,
                    requiredSparsePumpInstall: pending)
                .ConfigureAwait(false);
            return null;
        }

        OutboundSparsePumpInstall? installed;
        lock (gate)
        {
            if (dataSession is null ||
                !TryCommitOutboundSparsePumpInstallLocked(
                    context,
                    pending,
                    dataSession,
                    out installed,
                    out _))
            {
                installed = null;
            }
        }

        if (installed is null || dataSession is null)
        {
            if (openedReplacementStream && pumpStream is not null)
            {
                await DisposeOutboundSparsePumpStreamDiagnosticOnlyAsync(pumpStream).ConfigureAwait(false);
            }

            return null;
        }

        var pumpCancellation = new CancellationTokenSource();
        var pumpTask = RunOutboundV4SenderPumpAsync(
            context,
            pumpStream!,
            dataSession,
            pumpCancellation.Token,
            installed);
        await TryApplyOutboundCommittedFileTransferRouteTransitionRetainedFrameAsync(
                context,
                installed,
                dataSession)
            .ConfigureAwait(false);
        return new OutboundSparsePumpRuntime(
            installed,
            pumpStream!,
            dataSession,
            pumpCancellation,
            pumpTask);
    }

    private static async Task DisposeOutboundSparsePumpStreamDiagnosticOnlyAsync(Stream stream)
    {
        try
        {
            await stream.DisposeAsync().ConfigureAwait(false);
        }
        catch
        {
            // Cleanup from an invalidated descriptor is diagnostic-only.
        }
    }

    private static async Task DisposeRetiredOutboundSparsePumpAsync(
        Task pumpTask,
        Stream pumpStream,
        CancellationTokenSource pumpCancellation)
    {
        try
        {
            await pumpTask.ConfigureAwait(false);
        }
        catch
        {
            // A retired descriptor is diagnostic-only. Its exact failure is handled by the
            // supervisor that observed the authority handoff; never let it mutate new state.
        }
        finally
        {
            await DisposeOutboundSparsePumpStreamDiagnosticOnlyAsync(pumpStream).ConfigureAwait(false);
            try
            {
                pumpCancellation.Dispose();
            }
            catch (ObjectDisposedException)
            {
            }
        }
    }

    private async Task DisposeRetiredOutboundSparsePumpInstallAsync(
        OutboundTransferContext context,
        long receiveSupervisorGeneration,
        Task<OutboundSparsePumpRuntime?> installTask,
        CancellationTokenSource? installCancellation)
    {
        try
        {
            OutboundSparsePumpRuntime? runtime;
            try
            {
                runtime = await installTask.ConfigureAwait(false);
            }
            catch
            {
                return;
            }

            if (runtime is null)
            {
                return;
            }

            lock (gate)
            {
                if (context.InstalledOutboundSparsePump == runtime.Install &&
                    (context.ActiveOutboundSparseReceiveSupervisorGeneration != receiveSupervisorGeneration ||
                     !IsOutboundSparsePumpInstallCurrentLocked(
                         context,
                         runtime.Install,
                         runtime.DataSession,
                         out _)))
                {
                    context.InstalledOutboundSparsePump = null;
                }
            }

            try
            {
                runtime.Cancellation.Cancel();
            }
            catch (ObjectDisposedException)
            {
            }

            await DisposeRetiredOutboundSparsePumpAsync(
                    runtime.PumpTask,
                    runtime.Stream,
                    runtime.Cancellation)
                .ConfigureAwait(false);
        }
        finally
        {
            try
            {
                installCancellation?.Dispose();
            }
            catch (ObjectDisposedException)
            {
            }
        }
    }

    private async Task ObserveRetiredOutboundSparseReceiveAsync(
        OutboundTransferContext context,
        Task<FileTransferReceivedDataFrame> receiveTask,
        OutboundSparsePumpInstall? receiveInstall,
        long dataSessionGeneration,
        CancellationTokenSource? receiveCancellation,
        string rejectionReason = "data_session_replaced")
    {
        try
        {
            var received = await receiveTask.ConfigureAwait(false);
            LogOutboundSparsePumpInstallRejected(
                context,
                receiveInstall,
                "receive_result",
                rejectionReason);
            LogPullDataFrameIgnored(
                context.TransferId,
                context.SessionId,
                received.Frame,
                $"stale_outbound_sparse_receive_data_session_generation_{dataSessionGeneration}");
        }
        catch
        {
            LogOutboundSparsePumpInstallRejected(
                context,
                receiveInstall,
                "receive_failure",
                rejectionReason);
        }
        finally
        {
            try
            {
                receiveCancellation?.Dispose();
            }
            catch (ObjectDisposedException)
            {
            }
        }
    }

    private async Task RunOutboundSparseCreditSenderAsync(
        OutboundTransferContext context,
        FileTransferSparseCreditRuntimeKind runtimeKind)
    {
        IFileTransferDataSession? dataSession = null;
        RuntimeOwnerToken? senderRuntimeOwner = null;
        Stream? senderPumpStream = null;
        CancellationTokenSource? senderPumpCancellation = null;
        Task? senderPumpTask = null;
        Task<OutboundSparsePumpRuntime?>? pendingPumpInstallTask = null;
        CancellationTokenSource? pendingPumpInstallCancellation = null;
        OutboundSparsePumpInstall? pendingPumpInstallDescriptor = null;
        OutboundSparsePumpInstall? startupPumpInstall = null;
        OutboundSparsePumpInstall? senderPumpInstall = null;
        Task<FileTransferReceivedDataFrame>? pendingReceiveTask = null;
        CancellationTokenSource? pendingReceiveCancellation = null;
        OutboundSparsePumpInstall? pendingReceiveInstall = null;
        RuntimeOwnerToken? pendingReceiveRuntimeOwner = null;
        IFileTransferDataSession? pendingReceiveDataSession = null;
        long pendingReceiveDataSessionGeneration = 0;
        long receiveSupervisorGeneration = 0;
        var receiveSupervisorStopReason = "completed";
        var restartSupervisorAfterCleanup = false;
        OutboundSparsePumpInstall? resumableInstalledPump = null;
        RoutePublicationToken? runtimePublicationToken;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal)
            {
                return;
            }

            if (context.ActiveOutboundSparseReceiveSupervisorGeneration > 0)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_outbound_sparse_receive_supervisor_duplicate_ignored; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; active_receive_supervisor_generation={context.ActiveOutboundSparseReceiveSupervisorGeneration}; decision_reason=already_active");
                return;
            }

            runtimePublicationToken = context.CurrentRoutePublicationToken;
            receiveSupervisorGeneration = Math.Max(
                1,
                context.LastOutboundSparseReceiveSupervisorGeneration + 1);
            context.LastOutboundSparseReceiveSupervisorGeneration = receiveSupervisorGeneration;
            context.ActiveOutboundSparseReceiveSupervisorGeneration = receiveSupervisorGeneration;
            if (context.DataSession is { } existingDataSession && context.DataSessionGeneration > 0)
            {
                dataSession = existingDataSession;
                senderRuntimeOwner = context.CurrentRuntimeOwner;
                resumableInstalledPump = context.InstalledOutboundSparsePump;
            }
        }

        var isPrimaryRegularNknBulkV6 = IsPrimaryRegularNknBulkV6Runtime(runtimeKind);
        bool IsCurrentPrimaryRegularNknBulkV6()
        {
            lock (gate)
            {
                return ReferenceEquals(outboundTransfer, context) &&
                    !context.IsTerminal &&
                    IsPrimaryRegularNknBulkV6ContextLocked(context);
            }
        }

        var useV6Envelope = context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6;
        if (isPrimaryRegularNknBulkV6)
        {
            LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.Opening, "sender_start");
        }

        try
        {
            var currentTransport = GetTransportOrThrow();
            IFileTransferDataSession? retiredDataSession = null;
            var dataSessionReplaced = false;
            while (dataSession is null)
            {
                RoutePublicationToken? openingPublication = null;
                RuntimeOwnerToken? openingOwner = null;
                long openingDataSessionGeneration = 0;
                lock (gate)
                {
                    if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
                    {
                        return;
                    }

                    if (context.DataSession is { } attachedDataSession &&
                        context.DataSessionGeneration > 0)
                    {
                        dataSession = attachedDataSession;
                        senderRuntimeOwner = context.CurrentRuntimeOwner;
                        runtimePublicationToken = context.CurrentRoutePublicationToken;
                        resumableInstalledPump = context.InstalledOutboundSparsePump;
                    }
                    else if (context.DataSession is null &&
                        context.CurrentRoutePublicationToken is { IsDefault: false } currentPublication &&
                        context.CurrentRuntimeOwner is { IsDefault: false } currentOwner &&
                        currentPublication.RuntimeOwner == currentOwner &&
                        TryValidateRoutePublicationForEmissionLocked(
                            context,
                            "v4_sender_start",
                            "runtime_start_data_session_opening",
                            routeCommitToken: null,
                            requestedToken: currentPublication,
                            out _,
                            out _))
                    {
                        openingPublication = currentPublication;
                        openingOwner = currentOwner;
                        openingDataSessionGeneration = context.DataSessionGeneration;
                    }
                }

                if (dataSession is not null)
                {
                    break;
                }

                if (openingPublication is null || openingOwner is null)
                {
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }

                IFileTransferDataSession openedDataSession;
                try
                {
                    openedDataSession = await currentTransport
                        .OpenFileTransferDataSessionAsync(
                            context.SessionId,
                            context.TransferId,
                            context.LifetimeCts.Token)
                        .ConfigureAwait(false);
                }
                catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
                {
                    throw;
                }
                catch (Exception ex)
                {
                    var openingAuthorityCurrent = false;
                    lock (gate)
                    {
                        openingAuthorityCurrent = ReferenceEquals(outboundTransfer, context) &&
                            !context.IsTerminal &&
                            context.CurrentRoutePublicationToken == openingPublication &&
                            context.CurrentRuntimeOwner == openingOwner;
                    }

                    if (openingAuthorityCurrent)
                    {
                        throw;
                    }

                    LogOutboundSparsePumpInstallRejected(
                        context,
                        null,
                        "data_session_open",
                        $"opening_authority_invalidated_{NormalizeReason(ex.GetType().Name) ?? "failure"}");
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }
                var openedSessionAttached = false;
                lock (gate)
                {
                    var publicationCurrent = ReferenceEquals(outboundTransfer, context) &&
                        !context.IsTerminal &&
                        context.DataSession is null &&
                        context.DataSessionGeneration == openingDataSessionGeneration &&
                        context.CurrentRoutePublicationToken == openingPublication &&
                        context.CurrentRuntimeOwner == openingOwner &&
                        TryValidateRoutePublicationForEmissionLocked(
                            context,
                            "v4_sender_start",
                            "runtime_start_data_session_opened",
                            routeCommitToken: null,
                            requestedToken: openingPublication,
                            out _,
                            out _);
                    if (publicationCurrent &&
                        !ReferenceEquals(
                            context.DataSession,
                            openedDataSession) &&
                        !TryInvalidateRuntimeUnlockRetryLifecycleForScopeReplacementLocked(
                            context,
                            "retry_dispatch_data_session_replaced"))
                    {
                        publicationCurrent = false;
                    }

                    if (publicationCurrent &&
                        !ReferenceEquals(
                            context.DataSession,
                            openedDataSession) &&
                        !TryInvalidateReceiveRecoveryOperationForScopeReplacementLocked(
                            context,
                            "data_session_replaced"))
                    {
                        publicationCurrent = false;
                    }

                    if (publicationCurrent)
                    {
                        if (!ReferenceEquals(context.DataSession, openedDataSession))
                        {
                            dataSessionReplaced = true;
                            retiredDataSession = context.DataSession;
                            InvalidateFallbackTailYieldTransportEpochReauthorizationLocked(
                                context,
                                "data_session_replaced");
                            context.DataSession = openedDataSession;
                            context.DataSessionGeneration = Math.Max(1, context.DataSessionGeneration + 1);
                            context.PendingOutboundSparsePumpInstall = null;
                            context.InstalledOutboundSparsePump = null;
                        }

                        context.PullSessionActive = true;
                        context.PullCurrentPipelineDepth = V4SenderPumpDepth;
                        context.RemoteNextExpectedChunkIndex = 0;
                        context.RemoteGrantedUntilExclusive = 0;
                        context.ChunksAcceptedForTransport = 0;
                        context.BytesAcceptedForTransport = 0;
                        context.V4LastStateEpoch = -1;
                        context.V4LastStateDurableHighestChunkIndex = -1;
                        context.V4TerminalReady = false;
                        context.V4MixedScreenShareTransfer = context.V4MixedScreenShareTransfer || IsV4MixedScreenShareActive();
                        context.SparseSenderPumpLastWakeReason = "startup";
                        context.V4SenderCreditExhaustedSinceUtc = null;
                        SettleAndClearFallbackFrontierRepairContractLocked(
                            context,
                            FallbackFrontierRepairSettlementOutcome.StaleRejected,
                            "v4_sender_startup_reset");
                        context.PullV4SenderPumpRepairQueue.Clear();
                        context.PullV4SenderPumpRepairQueuedChunkIndices.Clear();
                        context.PullV4SenderPumpRepairRequests.Clear();
                        context.PullSentChunkCache.Clear();
                        context.PullSentChunkCacheBytes = 0;
                        runtimePublicationToken = openingPublication;
                        senderRuntimeOwner = openingOwner;
                        dataSession = openedDataSession;
                        openedSessionAttached = true;
                    }
                }

                if (!openedSessionAttached)
                {
                    try
                    {
                        openedDataSession.Dispose();
                    }
                    catch (Exception ex)
                    {
                        LocalOperationalLog.Warn(
                            "FileTransferService",
                            $"event=filetransfer_outbound_sparse_worker_handoff_rejected; install_generation=0; predecessor_install_generation=0; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; stage=data_session_unbound_dispose; decision_reason=unbound_data_session_dispose_failed; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");
                    }
                    await Task.Yield();
                }
            }

            if (retiredDataSession is not null)
            {
                try
                {
                    UnsubscribeDataSessionEvents(retiredDataSession);
                    retiredDataSession.Dispose();
                }
                catch (Exception ex)
                {
                    LocalOperationalLog.Warn(
                        "FileTransferService",
                        $"event=filetransfer_outbound_sparse_worker_handoff_rejected; install_generation=0; predecessor_install_generation=0; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; stage=data_session_retire; decision_reason=retired_data_session_dispose_failed; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");
                }
            }

            if (dataSessionReplaced)
            {
                SubscribeDataSessionEvents(dataSession);
            }

            OutboundSparsePumpRuntime? startupRuntime = null;
            bool startupSessionOpenDispatched;
            bool startupManifestDispatched;
            int startupDispatchedProtocolVersion;
            string? startupDispatchedRoute;
            lock (gate)
            {
                startupSessionOpenDispatched = context.OutboundSparseSessionOpenDispatched;
                startupManifestDispatched = context.OutboundSparseManifestDispatched;
                startupDispatchedProtocolVersion = context.OutboundSparseSessionOpenProtocolVersion;
                startupDispatchedRoute = context.OutboundSparseSessionOpenRoute;
            }

            if (resumableInstalledPump is not null)
            {
                while (startupRuntime is null)
                {
                    OutboundSparsePumpInstall? currentPredecessor;
                    lock (gate)
                    {
                        if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
                        {
                            return;
                        }

                        currentPredecessor = context.InstalledOutboundSparsePump;
                    }

                    if (currentPredecessor is null)
                    {
                        resumableInstalledPump = null;
                        break;
                    }

                    startupRuntime = await TryInstallOutboundSparsePumpAsync(
                            context,
                            currentPredecessor,
                            reusableStream: null,
                            reopenSource: true,
                            reason: "receive_supervisor_restart",
                            installCancellationToken: context.LifetimeCts.Token)
                        .ConfigureAwait(false);
                    if (startupRuntime is null)
                    {
                        await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    }
                }
            }

            if (startupRuntime is null)
            {
                while (startupRuntime is null)
                {
            var startupDataSessionUnavailable = false;
            lock (gate)
            {
                if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
                {
                    return;
                }

                if (context.DataSession is null)
                {
                    startupDataSessionUnavailable = true;
                }
                else if (!ReferenceEquals(context.DataSession, dataSession))
                {
                    dataSession = context.DataSession;
                    runtimePublicationToken = context.CurrentRoutePublicationToken;
                    senderRuntimeOwner = context.CurrentRuntimeOwner;
                    startupPumpInstall = null;
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_outbound_sparse_worker_handoff_required; install_generation=0; predecessor_install_generation=0; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.TerminalGeneration}; data_session_generation={context.DataSessionGeneration}; decision_reason=startup_data_session_rebound");
                }
            }

            if (startupDataSessionUnavailable)
            {
                await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                continue;
            }

            lock (gate)
            {
                if (context.PendingOutboundSparsePumpInstall is { } staleStartupPending &&
                    !IsOutboundSparsePumpInstallCurrentLocked(
                        context,
                        staleStartupPending,
                        dataSession,
                        out var staleStartupReason))
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        staleStartupPending,
                        "startup_restage",
                        staleStartupReason);
                    context.PendingOutboundSparsePumpInstall = null;
                    startupPumpInstall = null;
                }

                if (!TryStageOutboundSparsePumpInstallLocked(
                        context,
                        predecessor: null,
                        reason: "initial_runtime",
                        out startupPumpInstall,
                        out var stageRejection) ||
                    startupPumpInstall is null)
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        startupPumpInstall,
                        "startup_stage",
                        stageRejection);
                }
            }

            if (startupPumpInstall is null)
            {
                await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                continue;
            }

            if (senderPumpStream is null)
            {
                try
                {
                    senderPumpStream = await context.OpenReadStreamAsync(context.LifetimeCts.Token).ConfigureAwait(false);
                    ValidateReadableStream(senderPumpStream);
                    InitializeOutboundSenderRepairCachePolicy(context, senderPumpStream.CanSeek);
                }
                catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
                {
                    throw;
                }
                catch (Exception ex)
                {
                    var sourceAuthorityCurrent = false;
                    lock (gate)
                    {
                        sourceAuthorityCurrent = startupPumpInstall is not null &&
                            IsOutboundSparsePumpInstallCurrentLocked(
                                context,
                                startupPumpInstall,
                                dataSession,
                                out _);
                        if (!sourceAuthorityCurrent &&
                            context.PendingOutboundSparsePumpInstall == startupPumpInstall)
                        {
                            context.PendingOutboundSparsePumpInstall = null;
                        }
                    }

                    if (sourceAuthorityCurrent)
                    {
                        throw;
                    }

                    LogOutboundSparsePumpInstallRejected(
                        context,
                        startupPumpInstall,
                        "startup_source_open",
                        $"install_invalidated_{NormalizeReason(ex.GetType().Name) ?? "failure"}");
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }
            }

            var startupReady = false;
            var startupRejectionReason = "startup_install_missing";
            lock (gate)
            {
                if (startupPumpInstall is not null &&
                    (!IsOutboundSparsePumpInstallCurrentLocked(
                         context,
                         startupPumpInstall,
                         dataSession,
                         out startupRejectionReason) ||
                     context.PendingOutboundSparsePumpInstall != startupPumpInstall))
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        startupPumpInstall,
                        "startup_source_open",
                        startupRejectionReason);
                    if (context.PendingOutboundSparsePumpInstall == startupPumpInstall)
                    {
                        context.PendingOutboundSparsePumpInstall = null;
                    }

                    startupPumpInstall = null;
                }

                if (startupPumpInstall is null &&
                    !TryStageOutboundSparsePumpInstallLocked(
                        context,
                        predecessor: null,
                        reason: "startup_authority_handoff",
                        out startupPumpInstall,
                        out startupRejectionReason))
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        startupPumpInstall,
                        "startup_restage",
                        startupRejectionReason);
                }

                if (startupPumpInstall is not null &&
                    context.PendingOutboundSparsePumpInstall == startupPumpInstall &&
                    IsOutboundSparsePumpInstallCurrentLocked(
                        context,
                        startupPumpInstall,
                        dataSession,
                        out startupRejectionReason))
                {
                    runtimePublicationToken = startupPumpInstall.RoutePublication;
                    senderRuntimeOwner = startupPumpInstall.RuntimeOwner;
                    startupReady = TryPublishRuntimeStartedIfAuthorizedLocked(
                        context,
                        "sender",
                        "v4_sender_start",
                        "runtime_started",
                        routePublicationToken: startupPumpInstall.RoutePublication);
                    if (!startupReady)
                    {
                        startupRejectionReason = "runtime_started_rejected";
                    }
                    else
                    {
                        TryReplayOutboundRuntimeUnlockPendingPreCommitProbeLocked(context, "data_session_attached");
                        RetryOutboundFallbackTailLocalYieldProofIfPendingLocked(context, "data_session_attached");
                    }
                }
            }

            if (!startupReady ||
                startupPumpInstall is null ||
                runtimePublicationToken is not { IsDefault: false } startupPublication ||
                senderRuntimeOwner is null ||
                startupPublication != startupPumpInstall.RoutePublication ||
                startupPublication.RuntimeOwner != senderRuntimeOwner)
            {
                LogOutboundSparsePumpInstallRejected(
                    context,
                    startupPumpInstall,
                    "startup_authority",
                    startupRejectionReason);
                await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                continue;
            }

            useV6Envelope = startupPublication.ProtocolVersion >= FileTransferProtocol.ProtocolVersionV6;
            var sessionOpen = new FileTransferSessionOpenV2
            {
                SessionId = startupPublication.SessionId,
                TransferId = startupPublication.TransferId,
                ProtocolVersion = startupPublication.ProtocolVersion,
                FileTransferRoute = startupPublication.RouteToken,
                SessionRole = FileTransferProtocol.SessionRoleSender,
                ChunkSizeBytes = context.ChunkSizeBytes,
                InitialPipelineDepth = V4SenderPumpDepth,
            };

            if (startupSessionOpenDispatched &&
                !startupManifestDispatched &&
                (startupDispatchedProtocolVersion != sessionOpen.ProtocolVersion ||
                 !string.Equals(
                     startupDispatchedRoute,
                     sessionOpen.FileTransferRoute,
                     StringComparison.Ordinal)))
            {
                var closed = await FailOutboundV4Async(
                        context,
                        dataSession,
                        startupPumpInstall.RuntimeOwner,
                        FileTransferResultCodes.TransportIncompatible,
                        "Outbound sparse startup authority changed route or protocol after session-open dispatch.",
                        notifyPeer: true,
                        requiredSparsePumpInstall: startupPumpInstall)
                    .ConfigureAwait(false);
                receiveSupervisorStopReason = closed
                    ? "startup_authority_incompatible_after_session_open"
                    : "startup_authority_incompatible_rejected";
                if (closed)
                {
                    return;
                }

                await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                continue;
            }

            if (!startupSessionOpenDispatched)
            {
                if (OutboundSparseBootstrapBarrierForTests is { } bootstrapBarrier)
                {
                    await bootstrapBarrier(
                            context.TransferId,
                            context.SessionId,
                            "startup_state")
                        .ConfigureAwait(false);
                }

                if (!TryUpdateOutboundSparseBootstrapStateIfCurrent(
                        context,
                        startupPumpInstall,
                        dataSession,
                        FileTransferTransferState.AwaitingStart,
                        isPrimaryRegularNknBulkV6
                            ? "Starting regular NKN bulk V6 transfer."
                            : "Starting regular NKN V4 transfer.",
                        markManifestDispatched: false,
                        stage: "startup_state",
                        out startupRejectionReason))
                {
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }

                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event={(useV6Envelope ? "filetransfer_v6_sender_started" : "filetransfer_v4_sender_started")}; transfer_id={context.TransferId}; session_id={context.SessionId}; protocol_version={startupPublication.ProtocolVersion}; route={startupPublication.RouteToken}; runtime_profile={FormatFileTransferRouteRuntimeProfile(context.RouteSelection.RuntimeProfile)}; frame_family={FormatFileTransferFrameFamily(context.RouteSelection.FrameFamily)}; bridge_recovery_policy={FormatFileTransferRouteBridgeRecoveryPolicy(context.RouteSelection.BridgeRecoveryPolicy)}; chunk_size_bytes={context.ChunkSizeBytes}; chunk_count={context.ChunkCount}; pipeline_depth={V4SenderPumpDepth}; pending_bytes_limit={V4SenderPumpPendingBytes}");
                if (isPrimaryRegularNknBulkV6)
                {
                    LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.ManifestExchange, "session_open");
                }

                var sessionOpenAuthorized = false;
                lock (gate)
                {
                    sessionOpenAuthorized = context.PendingOutboundSparsePumpInstall == startupPumpInstall &&
                        IsOutboundSparsePumpInstallCurrentLocked(
                            context,
                            startupPumpInstall,
                            dataSession,
                            out startupRejectionReason);
                }

                if (!sessionOpenAuthorized)
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        startupPumpInstall,
                        "session_open",
                        startupRejectionReason);
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }

                try
                {
                    await currentTransport.SendFileTransferSessionOpenAsync(
                            sessionOpen,
                            context.LifetimeCts.Token)
                        .ConfigureAwait(false);
                }
                catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
                {
                    throw;
                }
                catch (Exception ex)
                {
                    var sessionOpenAuthorityCurrent = false;
                    lock (gate)
                    {
                        sessionOpenAuthorityCurrent = context.PendingOutboundSparsePumpInstall == startupPumpInstall &&
                            IsOutboundSparsePumpInstallCurrentLocked(
                                context,
                                startupPumpInstall,
                                dataSession,
                                out _);
                    }

                    if (sessionOpenAuthorityCurrent)
                    {
                        throw;
                    }

                    LogOutboundSparsePumpInstallRejected(
                        context,
                        startupPumpInstall,
                        "session_open_send",
                        $"install_invalidated_{NormalizeReason(ex.GetType().Name) ?? "failure"}");
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }

                if (OutboundSparseBootstrapBarrierForTests is { } sessionOpenCompletionBarrier)
                {
                    await sessionOpenCompletionBarrier(
                            context.TransferId,
                            context.SessionId,
                            "session_open_completion")
                        .ConfigureAwait(false);
                }

                var sessionOpenCompletionCurrent = false;
                lock (gate)
                {
                    sessionOpenCompletionCurrent =
                        context.PendingOutboundSparsePumpInstall == startupPumpInstall &&
                        IsOutboundSparsePumpInstallCurrentLocked(
                            context,
                            startupPumpInstall,
                            dataSession,
                            out startupRejectionReason);
                    if (sessionOpenCompletionCurrent)
                    {
                        context.OutboundSparseSessionOpenDispatched = true;
                        context.OutboundSparseSessionOpenProtocolVersion = sessionOpen.ProtocolVersion;
                        context.OutboundSparseSessionOpenRoute = sessionOpen.FileTransferRoute;
                    }
                }

                if (!sessionOpenCompletionCurrent)
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        startupPumpInstall,
                        "session_open_completion",
                        startupRejectionReason);
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }

                startupSessionOpenDispatched = true;
                startupDispatchedProtocolVersion = sessionOpen.ProtocolVersion;
                startupDispatchedRoute = sessionOpen.FileTransferRoute;
                LogTransferInfo(
                    "filetransfer_session_opened",
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    sessionId: context.SessionId,
                    reason: FormatFileTransferSessionOpenReason(sessionOpen.SessionRole, sessionOpen.ProtocolVersion, sessionOpen.ChunkSizeBytes, sessionOpen.InitialPipelineDepth, context.RouteSelection),
                    routeSelection: context.RouteSelection);
            }

            if (!startupManifestDispatched)
            {
                var manifest = CreateOutboundV4ManifestFrame(context, useV6Envelope);

                if (!await SendOutboundV4PrePumpFrameWithTunaActivationPauseRetryAsync(
                        context,
                        dataSession,
                        manifest,
                        frameKind: "manifest",
                        payloadBytes: 0,
                        requiredInstall: startupPumpInstall).ConfigureAwait(false))
                {
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }

                if (OutboundSparseBootstrapBarrierForTests is { } manifestCompletionBarrier)
                {
                    await manifestCompletionBarrier(
                            context.TransferId,
                            context.SessionId,
                            "manifest_completion")
                        .ConfigureAwait(false);
                }

                if (!TryUpdateOutboundSparseBootstrapStateIfCurrent(
                        context,
                        startupPumpInstall,
                        dataSession,
                        FileTransferTransferState.Sending,
                        useV6Envelope
                            ? "Waiting for V6 receiver state."
                            : "Waiting for V4 receiver state.",
                        markManifestDispatched: true,
                        stage: "manifest_completion",
                        out startupRejectionReason))
                {
                    await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                    continue;
                }

                startupManifestDispatched = true;
                LogPullBinaryFrameSent(context.TransferId, context.SessionId, manifest, payloadBytes: 0);
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v4_manifest_sent; transfer_id={context.TransferId}; session_id={context.SessionId}; file_size_bytes={context.FileSizeBytes}; chunk_size_bytes={context.ChunkSizeBytes}; chunk_count={context.ChunkCount}");
                if (isPrimaryRegularNknBulkV6)
                {
                    LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.AwaitingReceiverState, "manifest_sent");
                }
            }

            if (OutboundSparseBootstrapBarrierForTests is { } startupCommitBarrier)
            {
                await startupCommitBarrier(
                        context.TransferId,
                        context.SessionId,
                        "startup_commit")
                    .ConfigureAwait(false);
            }

            var restartStartupForDataSessionReplacement = false;
            lock (gate)
            {
                if (!ReferenceEquals(outboundTransfer, context) ||
                    context.IsTerminal)
                {
                    receiveSupervisorStopReason = context.IsTerminal
                        ? "transfer_terminal"
                        : "startup_context_replaced";
                    return;
                }

                if (!ReferenceEquals(context.DataSession, dataSession))
                {
                    if (context.DataSession is null)
                    {
                        restartStartupForDataSessionReplacement = true;
                    }
                    else
                    {
                        dataSession = context.DataSession;
                        runtimePublicationToken = context.CurrentRoutePublicationToken;
                        senderRuntimeOwner = context.CurrentRuntimeOwner;
                        startupPumpInstall = null;
                        restartStartupForDataSessionReplacement = true;
                    }
                }

                if (!restartStartupForDataSessionReplacement &&
                    context.PendingOutboundSparsePumpInstall is { } stalePending &&
                    !IsOutboundSparsePumpInstallCurrentLocked(
                        context,
                        stalePending,
                        dataSession,
                        out var staleReason))
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        stalePending,
                        "startup_commit",
                        staleReason);
                    context.PendingOutboundSparsePumpInstall = null;
                }

                if (!restartStartupForDataSessionReplacement)
                {
                    startupPumpInstall = context.PendingOutboundSparsePumpInstall;
                }
            }

            if (restartStartupForDataSessionReplacement)
            {
                await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                continue;
            }

            startupRuntime = await TryInstallOutboundSparsePumpAsync(
                    context,
                    predecessor: null,
                    reusableStream: senderPumpStream,
                    reopenSource: false,
                    reason: startupPumpInstall is null ? "startup_authority_handoff" : "initial_runtime",
                    installCancellationToken: context.LifetimeCts.Token)
                .ConfigureAwait(false);
            if (startupRuntime is null)
            {
                await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                continue;
            }
            }
            }

            senderPumpInstall = startupRuntime.Install;
            startupPumpInstall = startupRuntime.Install;
            senderRuntimeOwner = startupRuntime.Install.RuntimeOwner;
            senderPumpStream = startupRuntime.Stream;
            dataSession = startupRuntime.DataSession;
            senderPumpCancellation = startupRuntime.Cancellation;
            senderPumpTask = startupRuntime.PumpTask;

            if (OutboundSparsePostInstallBarrierForTests is { } postInstallBarrier)
            {
                await postInstallBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
            }

            if (context.UserPaused)
            {
                await SendOutboundV4PauseControlAsync(context, "user_paused_initial").ConfigureAwait(false);
                await SendOutboundV4PauseStateAsync(context, "user_paused_initial").ConfigureAwait(false);
            }

            async Task<OutboundSparsePumpRuntime?> InstallCurrentPumpAsync(
                string reason,
                bool reopenSource,
                bool previousPumpAlreadyObserved,
                CancellationToken installCancellationToken)
            {
                var previousTask = senderPumpTask;
                var previousStream = senderPumpStream;
                var previousCancellation = senderPumpCancellation;
                var previousTaskStillRunning = previousTask is { IsCompleted: false };
                if (previousTaskStillRunning)
                {
                    try
                    {
                        previousCancellation?.Cancel();
                    }
                    catch (ObjectDisposedException)
                    {
                    }
                }

                OutboundSparsePumpInstall? predecessor;
                lock (gate)
                {
                    if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
                    {
                        return null;
                    }

                    predecessor = context.InstalledOutboundSparsePump;
                }

                // The install attempt owns the retired pump resources from this point. Clearing
                // the active slots before its first await lets the receive supervisor continue
                // independently while the source is reopened and the descriptor is revalidated.
                senderPumpTask = null;
                senderPumpStream = null;
                senderPumpCancellation = null;

                var replacement = await TryInstallOutboundSparsePumpAsync(
                        context,
                        predecessor,
                        previousStream,
                        reopenSource || previousTaskStillRunning,
                        reason,
                        installCancellationToken)
                    .ConfigureAwait(false);

                var replacementReusesPreviousStream = replacement is not null &&
                    ReferenceEquals(previousStream, replacement.Stream);
                if (previousStream is not null && !replacementReusesPreviousStream)
                {
                    if (previousTask is not null &&
                        previousCancellation is not null &&
                        previousTaskStillRunning &&
                        !previousPumpAlreadyObserved)
                    {
                        _ = DisposeRetiredOutboundSparsePumpAsync(
                            previousTask,
                            previousStream,
                            previousCancellation);
                    }
                    else
                    {
                        await DisposeOutboundSparsePumpStreamDiagnosticOnlyAsync(previousStream).ConfigureAwait(false);
                        try
                        {
                            previousCancellation?.Dispose();
                        }
                        catch (ObjectDisposedException)
                        {
                        }
                    }
                }
                else if (previousCancellation is not null &&
                         !ReferenceEquals(previousCancellation, replacement?.Cancellation))
                {
                    try
                    {
                        previousCancellation.Dispose();
                    }
                    catch (ObjectDisposedException)
                    {
                    }
                }

                if (replacement is null)
                {
                    return null;
                }

                return replacement;
            }

            var nextPumpInstallAttemptUtc = DateTimeOffset.MinValue;
            void StartCurrentPumpInstall(
                string reason,
                bool reopenSource,
                bool previousPumpAlreadyObserved)
            {
                if (pendingPumpInstallTask is not null ||
                    DateTimeOffset.UtcNow < nextPumpInstallAttemptUtc)
                {
                    return;
                }

                pendingPumpInstallCancellation = CancellationTokenSource.CreateLinkedTokenSource(
                    context.LifetimeCts.Token);
                pendingPumpInstallTask = InstallCurrentPumpAsync(
                    reason,
                    reopenSource,
                    previousPumpAlreadyObserved,
                    pendingPumpInstallCancellation.Token);
                lock (gate)
                {
                    pendingPumpInstallDescriptor = context.PendingOutboundSparsePumpInstall;
                }
            }

            async Task<OutboundSparsePumpRuntime?> CompletePendingPumpInstallAsync()
            {
                if (pendingPumpInstallTask is null)
                {
                    return null;
                }

                var completingTask = pendingPumpInstallTask;
                var completingCancellation = pendingPumpInstallCancellation;
                var completingDescriptor = pendingPumpInstallDescriptor;
                OutboundSparsePumpRuntime? replacement = null;
                try
                {
                    replacement = await completingTask.ConfigureAwait(false);
                }
                catch
                {
                    lock (gate)
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            completingDescriptor,
                            "install_task",
                            "install_task_failed");
                        if (context.PendingOutboundSparsePumpInstall == completingDescriptor)
                        {
                            context.PendingOutboundSparsePumpInstall = null;
                        }
                    }
                }

                try
                {
                    completingCancellation?.Dispose();
                }
                catch (ObjectDisposedException)
                {
                }

                if (ReferenceEquals(pendingPumpInstallTask, completingTask))
                {
                    pendingPumpInstallTask = null;
                    pendingPumpInstallCancellation = null;
                    pendingPumpInstallDescriptor = null;
                }

                if (replacement is null)
                {
                    nextPumpInstallAttemptUtc = DateTimeOffset.UtcNow.AddMilliseconds(PullSessionReceivePollDelayMs);
                    return null;
                }

                senderPumpInstall = replacement.Install;
                senderRuntimeOwner = replacement.Install.RuntimeOwner;
                senderPumpStream = replacement.Stream;
                dataSession = replacement.DataSession;
                senderPumpCancellation = replacement.Cancellation;
                senderPumpTask = replacement.PumpTask;
                nextPumpInstallAttemptUtc = DateTimeOffset.MinValue;
                return replacement;
            }

            async Task RetirePendingReceiveAsync(string rejectionReason)
            {
                if (pendingReceiveTask is null)
                {
                    return;
                }

                var retiredReceiveTask = pendingReceiveTask;
                var retiredReceiveCancellation = pendingReceiveCancellation;
                var retiredReceiveInstall = pendingReceiveInstall;
                var retiredReceiveDataSessionGeneration = pendingReceiveDataSessionGeneration;
                try
                {
                    retiredReceiveCancellation?.Cancel();
                }
                catch (ObjectDisposedException)
                {
                }

                pendingReceiveTask = null;
                pendingReceiveCancellation = null;
                pendingReceiveInstall = null;
                pendingReceiveRuntimeOwner = null;
                pendingReceiveDataSession = null;
                pendingReceiveDataSessionGeneration = 0;
                await ObserveRetiredOutboundSparseReceiveAsync(
                        context,
                        retiredReceiveTask,
                        retiredReceiveInstall,
                        retiredReceiveDataSessionGeneration,
                        retiredReceiveCancellation,
                        rejectionReason)
                    .ConfigureAwait(false);
            }

            void StartSessionGenerationReceiveIfNeeded()
            {
                if (pendingReceiveTask is not null)
                {
                    return;
                }

                IFileTransferDataSession? receiveDataSessionToStart = null;
                OutboundSparsePumpInstall? receiveInstallToStart = null;
                RuntimeOwnerToken? receiveRuntimeOwnerToStart = null;
                long receiveDataSessionGenerationToStart = 0;
                lock (gate)
                {
                    if (!ReferenceEquals(outboundTransfer, context) ||
                        context.IsTerminal ||
                        context.ActiveOutboundSparseReceiveSupervisorGeneration != receiveSupervisorGeneration ||
                        context.DataSession is null ||
                        context.DataSessionGeneration <= 0)
                    {
                        return;
                    }

                    receiveDataSessionToStart = context.DataSession;
                    receiveDataSessionGenerationToStart = context.DataSessionGeneration;
                    if (context.InstalledOutboundSparsePump is { } installedReceive &&
                        IsOutboundSparsePumpInstallCurrentLocked(
                            context,
                            installedReceive,
                            receiveDataSessionToStart,
                            out _))
                    {
                        receiveInstallToStart = installedReceive;
                    }
                    else if (context.PendingOutboundSparsePumpInstall is { } pendingReceive &&
                             IsOutboundSparsePumpInstallCurrentLocked(
                                 context,
                                 pendingReceive,
                                 receiveDataSessionToStart,
                                 out _))
                    {
                        receiveInstallToStart = pendingReceive;
                    }

                    receiveRuntimeOwnerToStart =
                        receiveInstallToStart?.RuntimeOwner ?? context.CurrentRuntimeOwner;
                }

                var receiveCancellationToStart = CancellationTokenSource.CreateLinkedTokenSource(
                    context.LifetimeCts.Token);
                Task<FileTransferReceivedDataFrame> receiveTaskToStart;
                try
                {
                    receiveTaskToStart = receiveDataSessionToStart
                        .ReceiveWithMetadataAsync(receiveCancellationToStart.Token)
                        .AsTask();
                }
                catch
                {
                    receiveCancellationToStart.Dispose();
                    throw;
                }

                pendingReceiveInstall = receiveInstallToStart;
                pendingReceiveRuntimeOwner = receiveRuntimeOwnerToStart;
                pendingReceiveDataSession = receiveDataSessionToStart;
                pendingReceiveDataSessionGeneration = receiveDataSessionGenerationToStart;
                pendingReceiveCancellation = receiveCancellationToStart;
                pendingReceiveTask = receiveTaskToStart;
            }

            while (true)
            {
                try
                {
                context.LifetimeCts.Token.ThrowIfCancellationRequested();
                IFileTransferDataSession? currentDataSession;
                var pumpInstallCurrent = false;
                var pendingInstallInvalidated = false;
                var pendingReceiveInvalidated = false;
                var pendingReceiveRejectionReason = "receive_install_replaced";
                lock (gate)
                {
                    if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
                    {
                        receiveSupervisorStopReason = context.IsTerminal
                            ? "transfer_terminal"
                            : "transfer_context_replaced";
                        return;
                    }

                    currentDataSession = context.DataSession;
                    pumpInstallCurrent = senderPumpInstall is not null &&
                        IsOutboundSparsePumpInstallCurrentLocked(
                            context,
                            senderPumpInstall,
                            currentDataSession,
                            out _);
                    if (pendingPumpInstallTask is { IsCompleted: false } &&
                        pendingPumpInstallDescriptor is not null &&
                        !IsOutboundSparsePumpInstallCurrentLocked(
                            context,
                            pendingPumpInstallDescriptor,
                            currentDataSession,
                            out _))
                    {
                        pendingInstallInvalidated = true;
                        if (context.PendingOutboundSparsePumpInstall == pendingPumpInstallDescriptor)
                        {
                            context.PendingOutboundSparsePumpInstall = null;
                        }
                    }

                    if (pendingReceiveTask is not null &&
                        !IsOutboundSparseReceiveSessionCurrentLocked(
                            context,
                            pendingReceiveDataSession,
                            pendingReceiveDataSessionGeneration,
                            receiveSupervisorGeneration,
                            out pendingReceiveRejectionReason))
                    {
                        pendingReceiveInvalidated = true;
                    }
                }

                if (pendingReceiveInvalidated)
                {
                    await RetirePendingReceiveAsync(pendingReceiveRejectionReason).ConfigureAwait(false);
                }

                if (pendingInstallInvalidated && pendingPumpInstallTask is not null)
                {
                    var retiredInstallTask = pendingPumpInstallTask;
                    var retiredInstallCancellation = pendingPumpInstallCancellation;
                    pendingPumpInstallTask = null;
                    pendingPumpInstallCancellation = null;
                    pendingPumpInstallDescriptor = null;
                    try
                    {
                        retiredInstallCancellation?.Cancel();
                    }
                    catch (ObjectDisposedException)
                    {
                    }

                    _ = DisposeRetiredOutboundSparsePumpInstallAsync(
                        context,
                        receiveSupervisorGeneration,
                        retiredInstallTask,
                        retiredInstallCancellation);
                    nextPumpInstallAttemptUtc = DateTimeOffset.MinValue;
                }

                if (currentDataSession is null)
                {
                    receiveSupervisorStopReason = "data_session_missing";
                    return;
                }

                if (!ReferenceEquals(dataSession, currentDataSession))
                {
                    await RetirePendingReceiveAsync("data_session_replaced").ConfigureAwait(false);
                    dataSession = currentDataSession;
                    pumpInstallCurrent = false;
                }

                if (senderPumpTask is not null && !pumpInstallCurrent)
                {
                    StartCurrentPumpInstall(
                        "coordinator_authority_handoff",
                        reopenSource: true,
                        previousPumpAlreadyObserved: false);
                }

                if (senderPumpTask is null && pendingPumpInstallTask is null)
                {
                    bool installRequired;
                    lock (gate)
                    {
                        installRequired = ReferenceEquals(outboundTransfer, context) &&
                            !context.IsTerminal &&
                            (senderPumpInstall is null ||
                             !IsOutboundSparsePumpInstallCurrentLocked(
                                 context,
                                 senderPumpInstall,
                                 dataSession,
                                 out _) ||
                             HasOutboundSparsePumpWorkLocked(context));
                    }

                    if (installRequired)
                    {
                        StartCurrentPumpInstall(
                            senderPumpInstall is null ? "initial_runtime" : "queued_sparse_runtime_work",
                            reopenSource: senderPumpStream is null,
                            previousPumpAlreadyObserved: true);
                    }
                }

                StartSessionGenerationReceiveIfNeeded();

                var pollTask = Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token);
                var waitTasks = new List<Task>(4) { pollTask };
                if (pendingReceiveTask is not null)
                {
                    waitTasks.Add(pendingReceiveTask);
                }

                if (pendingPumpInstallTask is not null)
                {
                    waitTasks.Add(pendingPumpInstallTask);
                }

                if (senderPumpTask is not null)
                {
                    waitTasks.Add(senderPumpTask);
                }

                var completed = await Task.WhenAny(waitTasks).ConfigureAwait(false);
                if (pendingReceiveTask is { IsCompleted: true })
                {
                    completed = pendingReceiveTask;
                }
                else if (pendingPumpInstallTask is { IsCompleted: true })
                {
                    completed = pendingPumpInstallTask;
                }
                else if (senderPumpTask is { IsCompleted: true })
                {
                    completed = senderPumpTask;
                }

                if (pendingPumpInstallTask is not null && completed == pendingPumpInstallTask)
                {
                    await CompletePendingPumpInstallAsync().ConfigureAwait(false);
                    continue;
                }

                if (senderPumpTask is not null && completed == senderPumpTask)
                {
                    if (IsCurrentPrimaryRegularNknBulkV6())
                    {
                        LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.Finalizing, "sender_pump_completed");
                    }

                    Exception? pumpFailure = null;
                    try
                    {
                        await senderPumpTask.ConfigureAwait(false);
                    }
                    catch (Exception ex)
                    {
                        pumpFailure = ex;
                    }

                    if (pumpFailure is OperationCanceledException && context.LifetimeCts.IsCancellationRequested)
                    {
                        receiveSupervisorStopReason = "lifetime_cancelled";
                        return;
                    }

                    var completedInstall = senderPumpInstall;
                    bool completedInstallCurrent;
                    lock (gate)
                    {
                        completedInstallCurrent = completedInstall is not null &&
                            IsOutboundSparsePumpInstallCurrentLocked(
                                context,
                                completedInstall,
                                dataSession,
                                out _);
                    }

                    if (!completedInstallCurrent)
                    {
                        StartCurrentPumpInstall(
                            "stale_pump_completion",
                            reopenSource: true,
                            previousPumpAlreadyObserved: true);
                        continue;
                    }

                    if (pumpFailure is not null)
                    {
                        if (OutboundSparseFailureDeferralBarrierForTests is { } failureDeferralBarrier)
                        {
                            await failureDeferralBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                        }

                        var deferred =
                            TryDeferCurrentPostTunaFallbackReceiveRecoveryPayloadHoldIfCurrent(
                                context,
                                "sender_pump",
                                pumpFailure,
                                completedInstall,
                                dataSession) ||
                            pumpFailure switch
                        {
                            OperationCanceledException canceled =>
                                TryDeferOutboundPostTunaFallbackDataSessionCancellationIfCurrent(
                                    context,
                                    "sender_pump",
                                    canceled,
                                    completedInstall,
                                    dataSession) ||
                                TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
                                    context,
                                    "sender_pump",
                                    canceled,
                                    completedInstall,
                                    dataSession),
                            _ => TryDeferOutboundPostTunaFallbackTransportSendFailureIfCurrent(
                                     context,
                                     "sender_pump",
                                     pumpFailure,
                                     completedInstall,
                                     dataSession) ||
                                 TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
                                     context,
                                     "sender_pump",
                                     pumpFailure,
                                     completedInstall,
                                     dataSession),
                        };
                        if (deferred)
                        {
                            StartCurrentPumpInstall(
                                "current_pump_recovery",
                                reopenSource: true,
                                previousPumpAlreadyObserved: true);
                            continue;
                        }

                        var errorCode = ClassifyOutboundFailureErrorCode(pumpFailure, StreamReadFailedErrorCode);
                        var failedCurrentPump = await FailOutboundV4Async(
                                context,
                                dataSession,
                                completedInstall?.RuntimeOwner,
                                errorCode,
                                ClassifyOutboundFailureStatusMessage(pumpFailure, errorCode),
                                notifyPeer: true,
                                requiredSparsePumpInstall: completedInstall)
                            .ConfigureAwait(false);
                        if (!failedCurrentPump)
                        {
                            StartCurrentPumpInstall(
                                "stale_pump_failure",
                                reopenSource: true,
                                previousPumpAlreadyObserved: true);
                            continue;
                        }

                        receiveSupervisorStopReason = "current_pump_failed";
                        return;
                    }

                    if (IsCurrentPrimaryRegularNknBulkV6())
                    {
                        FileTransferTransferState? terminalState;
                        lock (gate)
                        {
                            terminalState = ReferenceEquals(outboundTransfer, context)
                                ? context.State
                                : null;
                        }

                        if (terminalState == FileTransferTransferState.Completed)
                        {
                            LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.Completed, "sender_pump_completed");
                        }
                        else if (terminalState == FileTransferTransferState.Failed)
                        {
                            LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.Failed, "sender_pump_completed");
                        }
                    }

                    if (ShouldKeepOutboundV4ReceiveLoopAliveAfterSenderPumpCompleted(context))
                    {
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_v4_receive_loop_kept_alive_after_sender_pump_completed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; reason=session_scoped_sparse_runtime");
                        senderPumpTask = null;
                        senderPumpCancellation?.Dispose();
                        senderPumpCancellation = null;
                        continue;
                    }

                    receiveSupervisorStopReason = "sender_pump_completed";
                    return;
                }

                if (completed != pendingReceiveTask)
                {
                    if (await HandlePausedOutboundTransportAsync(context).ConfigureAwait(false))
                    {
                        await StopOutboundSparseSenderPumpAsync(context, senderPumpTask).ConfigureAwait(false);
                        return;
                    }

                    if (TryGetOutboundV4PeerSilenceFailure(context, out var silenceStatus, out var feedbackStateRefreshRequest))
                    {
                        ForceLogOutboundV4SenderPumpSummary(context);
                        await TransitionOutboundToTerminalAsync(
                            context,
                            FileTransferTransferState.Failed,
                            errorCode: DisconnectedErrorCode,
                            statusMessage: silenceStatus,
                            notifyPeer: false,
                            cancelReason: null,
                            ct: CancellationToken.None).ConfigureAwait(false);
                        await StopOutboundSparseSenderPumpAsync(context, senderPumpTask).ConfigureAwait(false);
                        return;
                    }

                    if (feedbackStateRefreshRequest is not null)
                    {
                        if (IsCurrentPrimaryRegularNknBulkV6() &&
                            IsPrimaryRegularNknBulkV6CheckpointSyncRequest(feedbackStateRefreshRequest))
                        {
                            LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.CheckpointSyncRequested, "feedback_stale");
                            QueueOutboundPrimaryRegularNknBulkV6CheckpointSync(
                                context,
                                dataSession,
                                feedbackStateRefreshRequest);
                        }
                        else
                        {
                            if (IsCurrentPrimaryRegularNknBulkV6())
                            {
                                LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.StateRefreshRequested, "feedback_stale");
                            }

                            QueueOutboundV4SparseRuntimeStateRefreshIfCurrent(
                                context,
                                dataSession,
                                feedbackStateRefreshRequest,
                                "state_refresh_send_queued",
                                senderPumpInstall,
                                senderPumpInstall?.RuntimeOwner,
                                dataSession,
                                senderPumpInstall?.DataSessionGeneration ?? 0);
                        }
                    }

                    continue;
                }

                FileTransferReceivedDataFrame received;
                var completedReceiveInstall = pendingReceiveInstall;
                var completedReceiveRuntimeOwner = pendingReceiveRuntimeOwner;
                var completedReceiveDataSession = pendingReceiveDataSession;
                var completedReceiveDataSessionGeneration = pendingReceiveDataSessionGeneration;
                var completedReceiveCancellation = pendingReceiveCancellation;
                try
                {
                    received = await pendingReceiveTask.ConfigureAwait(false);
                }
                catch (Exception ex)
                {
                    pendingReceiveTask = null;
                    pendingReceiveCancellation = null;
                    pendingReceiveInstall = null;
                    pendingReceiveRuntimeOwner = null;
                    pendingReceiveDataSession = null;
                    pendingReceiveDataSessionGeneration = 0;
                    try
                    {
                        completedReceiveCancellation?.Dispose();
                    }
                    catch (ObjectDisposedException)
                    {
                    }
                    if (ex is OperationCanceledException && context.LifetimeCts.IsCancellationRequested)
                    {
                        throw;
                    }

                    bool receiveSessionCurrent;
                    bool receiveAuthorityCurrent;
                    RuntimeOwnerToken? currentReceiveRuntimeOwner;
                    var receiveRejection = "accepted";
                    lock (gate)
                    {
                        receiveSessionCurrent = ReferenceEquals(outboundTransfer, context) &&
                            !context.IsTerminal &&
                            ReferenceEquals(context.DataSession, completedReceiveDataSession) &&
                            context.DataSessionGeneration == completedReceiveDataSessionGeneration;
                        currentReceiveRuntimeOwner = ReferenceEquals(outboundTransfer, context)
                            ? context.CurrentRuntimeOwner
                            : null;
                        receiveAuthorityCurrent = receiveSessionCurrent &&
                            IsOutboundSparseReceiveResultCurrentLocked(
                                context,
                                completedReceiveInstall,
                                completedReceiveRuntimeOwner,
                                completedReceiveDataSession,
                                completedReceiveDataSessionGeneration,
                                out receiveRejection);
                        if (!receiveSessionCurrent && string.Equals(receiveRejection, "accepted", StringComparison.Ordinal))
                        {
                            receiveRejection = context.IsTerminal
                                ? "transfer_terminal"
                                : !ReferenceEquals(context.DataSession, completedReceiveDataSession)
                                    ? "data_session_replaced"
                                    : "data_session_generation_mismatch";
                        }
                    }

                    if (!receiveSessionCurrent)
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            completedReceiveInstall,
                            "receive_failure",
                            receiveRejection);

                        await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                        continue;
                    }

                    if (!receiveAuthorityCurrent)
                    {
                        if (completedReceiveRuntimeOwner is not null &&
                            completedReceiveRuntimeOwner != currentReceiveRuntimeOwner)
                        {
                            var staleErrorCode = ClassifyOutboundFailureErrorCode(ex, StreamReadFailedErrorCode);
                            await FailOutboundV4Async(
                                    context,
                                    completedReceiveDataSession,
                                    completedReceiveRuntimeOwner,
                                    staleErrorCode,
                                    ClassifyOutboundFailureStatusMessage(ex, staleErrorCode),
                                    notifyPeer: false)
                                .ConfigureAwait(false);
                        }
                        else
                        {
                            LogOutboundSparsePumpInstallRejected(
                                context,
                                completedReceiveInstall,
                                "receive_failure",
                                receiveRejection);
                        }

                        await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                        continue;
                    }

                    if (OutboundSparseFailureDeferralBarrierForTests is { } failureDeferralBarrier)
                    {
                        await failureDeferralBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                    }

                    var deferred =
                        TryDeferCurrentPostTunaFallbackReceiveRecoveryPayloadHoldIfCurrent(
                            context,
                            "receive_loop",
                            ex,
                            completedReceiveInstall,
                            completedReceiveDataSession) ||
                        ex switch
                    {
                        OperationCanceledException canceled =>
                            TryDeferOutboundPostTunaFallbackDataSessionCancellationIfCurrent(
                                context,
                                "receive_loop",
                                canceled,
                                completedReceiveInstall,
                                completedReceiveDataSession) ||
                            TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
                                context,
                                "receive_loop",
                                canceled,
                                completedReceiveInstall,
                                completedReceiveDataSession),
                        _ => TryDeferOutboundPostTunaFallbackTransportSendFailureIfCurrent(
                                 context,
                                 "receive_loop",
                                 ex,
                                 completedReceiveInstall,
                                 completedReceiveDataSession) ||
                             TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
                                 context,
                                 "receive_loop",
                                 ex,
                                 completedReceiveInstall,
                                 completedReceiveDataSession),
                    };
                    if (deferred)
                    {
                        await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                        continue;
                    }

                    var errorCode = ClassifyOutboundFailureErrorCode(ex, StreamReadFailedErrorCode);
                    var failedCurrentReceive = await FailOutboundV4Async(
                            context,
                            dataSession,
                            completedReceiveRuntimeOwner ?? currentReceiveRuntimeOwner,
                            errorCode,
                            ClassifyOutboundFailureStatusMessage(ex, errorCode),
                            notifyPeer: true,
                            requiredSparsePumpInstall: completedReceiveInstall)
                        .ConfigureAwait(false);
                    if (!failedCurrentReceive)
                    {
                        await Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token).ConfigureAwait(false);
                        continue;
                    }

                    receiveSupervisorStopReason = "current_receive_failed";
                    return;
                }

                if (OutboundSparseReceiveCompletionBarrierForTests is { } receiveCompletionBarrier)
                {
                    await receiveCompletionBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                }

                var frame = received.Frame;
                pendingReceiveTask = null;
                pendingReceiveCancellation = null;
                pendingReceiveInstall = null;
                pendingReceiveRuntimeOwner = null;
                pendingReceiveDataSession = null;
                pendingReceiveDataSessionGeneration = 0;
                try
                {
                    completedReceiveCancellation?.Dispose();
                }
                catch (ObjectDisposedException)
                {
                }
                // Keep transport draining while a sender descriptor/source reopen is pending.
                // Only the session/supervisor generation authorizes receive issuance; frame
                // dispatch below still requires the exact current pending-or-installed tuple.
                StartSessionGenerationReceiveIfNeeded();
                bool receiveResultCurrent;
                string receiveResultRejection;
                lock (gate)
                {
                    receiveResultCurrent = IsOutboundSparseReceiveResultCurrentLocked(
                        context,
                        completedReceiveInstall,
                        completedReceiveRuntimeOwner,
                        completedReceiveDataSession,
                        completedReceiveDataSessionGeneration,
                        out receiveResultRejection);
                    if (!receiveResultCurrent &&
                        CanRebindOutboundSparseReceiveFrameAcrossInstall(frame) &&
                        TryResolveOutboundSparseReceiveDispatchInstallLocked(
                            context,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration,
                            receiveSupervisorGeneration,
                            out var dispatchInstall,
                            out var dispatchRuntimeOwner,
                            out receiveResultRejection))
                    {
                        receiveResultCurrent = true;
                        completedReceiveInstall = dispatchInstall;
                        completedReceiveRuntimeOwner = dispatchRuntimeOwner;
                    }
                }

                if (!receiveResultCurrent &&
                    CanRebindOutboundSparseReceiveFrameAcrossInstall(frame))
                {
                    StartCurrentPumpInstall(
                        "frontier_receive_authority_gap",
                        reopenSource: true,
                        previousPumpAlreadyObserved: false);
                    lock (gate)
                    {
                        var receiveSessionCurrent = IsOutboundSparseReceiveSessionCurrentLocked(
                            context,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration,
                            receiveSupervisorGeneration,
                            out receiveResultRejection);
                        if (receiveSessionCurrent &&
                            TryResolveOutboundSparseReceiveDispatchInstallLocked(
                                context,
                                completedReceiveDataSession,
                                completedReceiveDataSessionGeneration,
                                receiveSupervisorGeneration,
                                out var currentDispatchInstall,
                                out var currentDispatchRuntimeOwner,
                                out receiveResultRejection))
                        {
                            completedReceiveInstall = currentDispatchInstall;
                            completedReceiveRuntimeOwner = currentDispatchRuntimeOwner;
                            receiveResultCurrent = true;
                        }
                    }
                }

                if (!receiveResultCurrent)
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        completedReceiveInstall,
                        "receive_result",
                        receiveResultRejection);
                    LogPullDataFrameIgnored(
                        context.TransferId,
                        context.SessionId,
                        frame,
                        "stale_outbound_sparse_receive_descriptor");
                    continue;
                }

                LogPullDataFrameReceived(context.TransferId, context.SessionId, frame);

                if (!IsFrameForContext(context, frame))
                {
                    LogPullDataFrameIgnored(context.TransferId, context.SessionId, frame, "session_or_transfer_mismatch_v4");
                    continue;
                }

                if (frame is FileTransferRuntimeUnlockPreCommitProbeFrame or
                    FileTransferRuntimeUnlockPreCommitProbeAckFrame)
                {
                    if (completedReceiveInstall is null ||
                        completedReceiveRuntimeOwner is not { } receiveRuntimeOwner ||
                        completedReceiveDataSession is not { } receiveDataSession)
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            completedReceiveInstall,
                            "precommit_probe_receive",
                            "receive_authority_missing");
                        LogRuntimeUnlockPreCommitProbeIgnored(
                            FileTransferDirection.Outbound,
                            context.TransferId,
                            context.SessionId,
                            (FileTransferRuntimeUnlockPreCommitProbeFrameBase)frame,
                            received.TransportKind,
                            "stale_outbound_sparse_receive_authority_missing");
                        continue;
                    }

                    await TryHandleOutboundSparseRuntimeUnlockPreCommitProbeDataFrameAsync(
                            context.SessionId,
                            context.TransferId,
                            frame,
                            received.TransportKind,
                            receiveDataSession,
                            context,
                            completedReceiveInstall,
                            receiveRuntimeOwner,
                            completedReceiveDataSessionGeneration,
                            receiveSupervisorGeneration)
                        .ConfigureAwait(false);
                    continue;
                }

                if (OutboundSparseReceiveDispatchBarrierForTests is { } receiveDispatchBarrier)
                {
                    await receiveDispatchBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                }

                lock (gate)
                {
                    receiveResultCurrent = IsOutboundSparseReceiveResultCurrentLocked(
                        context,
                        completedReceiveInstall,
                        completedReceiveRuntimeOwner,
                        completedReceiveDataSession,
                        completedReceiveDataSessionGeneration,
                        out receiveResultRejection);
                    if (!receiveResultCurrent &&
                        CanRebindOutboundSparseReceiveFrameAcrossInstall(frame) &&
                        TryResolveOutboundSparseReceiveDispatchInstallLocked(
                            context,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration,
                            receiveSupervisorGeneration,
                            out var dispatchInstall,
                            out var dispatchRuntimeOwner,
                            out receiveResultRejection))
                    {
                        receiveResultCurrent = true;
                        completedReceiveInstall = dispatchInstall;
                        completedReceiveRuntimeOwner = dispatchRuntimeOwner;
                    }
                }

                if (!receiveResultCurrent)
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        completedReceiveInstall,
                        "receive_dispatch",
                        receiveResultRejection);
                    LogPullDataFrameIgnored(
                        context.TransferId,
                        context.SessionId,
                        frame,
                        "stale_outbound_sparse_receive_dispatch");
                    continue;
                }

                var fallbackProofHandled = false;
                if (!ShouldAcceptSparseCreditRuntimeDataFrame(context, frame))
                {
                    fallbackProofHandled = TryPromoteOutboundFileTunaV4FallbackFromPeerV6Proof(
                            context,
                            frame,
                            out var promotedSnapshot,
                            completedReceiveInstall,
                            completedReceiveRuntimeOwner,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration);
                    if (fallbackProofHandled && promotedSnapshot is not null)
                    {
                        RaiseTransferChanged(promotedSnapshot);
                    }

                    if (fallbackProofHandled)
                    {
                        // The proof is retained across the owner transition and is applied once
                        // the successor sparse-pump descriptor is installed. The receive result
                        // still carries the retired regular-V4 descriptor and cannot dispatch it.
                        continue;
                    }
                }

                if (!ShouldAcceptSparseCreditRuntimeDataFrame(context, frame))
                {
                    SessionFileTransferSnapshot? legacyProofSnapshot = null;
                    if (frame is FileTransferStateFrameV4 legacyState)
                    {
                        lock (gate)
                        {
                            if (ReferenceEquals(outboundTransfer, context) &&
                                !context.IsTerminal &&
                                IsOutboundSparseReceiveResultCurrentLocked(
                                    context,
                                    completedReceiveInstall,
                                    completedReceiveRuntimeOwner,
                                    completedReceiveDataSession,
                                    completedReceiveDataSessionGeneration,
                                    out _) &&
                                TryRecoverOutboundV6RegularNknEpochFromLegacyV4PeerStateLocked(
                                    context,
                                    legacyState,
                                    received.TransportKind,
                                    "regular_nkn_legacy_v4_state_proof"))
                            {
                                legacyProofSnapshot = CreateSnapshotLocked();
                            }
                        }
                    }

                    if (legacyProofSnapshot is not null)
                    {
                        RaiseTransferChanged(legacyProofSnapshot);
                        TouchOutboundV6PeerLiveness(
                            context,
                            "regular_nkn_legacy_v4_state_proof",
                            completedReceiveInstall,
                            completedReceiveRuntimeOwner,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration);
                        SignalOutboundSparseSenderPump(
                            context,
                            completedReceiveInstall,
                            completedReceiveRuntimeOwner,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration);
                    }

                    LogPullDataFrameIgnored(
                        context.TransferId,
                        context.SessionId,
                        frame,
                        completedReceiveInstall!.RoutePublication.ProtocolVersion >= FileTransferProtocol.ProtocolVersionV6
                            ? "protocol_not_v6"
                            : "protocol_not_v4");
                    continue;
                }

                lock (gate)
                {
                    if (ReferenceEquals(outboundTransfer, context) &&
                        !context.IsTerminal &&
                        IsOutboundSparseReceiveResultCurrentLocked(
                            context,
                            completedReceiveInstall,
                            completedReceiveRuntimeOwner,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration,
                            out _))
                    {
                        var now = DateTimeOffset.UtcNow;
                        context.PullV4LastPeerFrameReceivedUtc = now;
                        context.PullV4PeerSilenceDeferralUtc = null;
                        context.PullV4PeerSilenceDeferralCount = 0;
                        context.V6LastPeerLivenessUtc = now;
                        if (frame is FileTransferReceiverStateFrameV6)
                        {
                            context.V6RegularNknStateRefreshFailureCount = 0;
                            if (IsCurrentPrimaryRegularNknBulkV6())
                            {
                                context.V6RegularNknCheckpointSyncFailureCount = 0;
                            }
                        }
                    }
                }

                switch (frame)
                {
                    case FileTransferTransportEpochFrameV6 handoff:
                        ApplyOutboundV6HandoffFrame(context, handoff, completedReceiveInstall, completedReceiveRuntimeOwner, completedReceiveDataSession, completedReceiveDataSessionGeneration);
                        SignalOutboundSparseSenderPump(context, completedReceiveInstall, completedReceiveRuntimeOwner, completedReceiveDataSession, completedReceiveDataSessionGeneration);
                        break;
                    case FileTransferFrontierRequestFrameV6 repairRequest:
                        if (OutboundSparseFrontierApplyBarrierForTests is { } frontierApplyBarrier)
                        {
                            await frontierApplyBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                        }

                        ApplyOutboundV6RepairRequestCore(
                            context,
                            repairRequest,
                            received.TransportKind,
                            completedReceiveInstall,
                            completedReceiveRuntimeOwner,
                            completedReceiveDataSession,
                            completedReceiveDataSessionGeneration,
                            receiveSupervisorGeneration);
                        break;
                    case FileTransferRepairProofFrameV6 repairProof:
                        ApplyOutboundV6RepairProof(context, repairProof, completedReceiveInstall, completedReceiveRuntimeOwner, completedReceiveDataSession, completedReceiveDataSessionGeneration);
                        SignalOutboundSparseSenderPump(context, completedReceiveInstall, completedReceiveRuntimeOwner, completedReceiveDataSession, completedReceiveDataSessionGeneration);
                        break;
                    case FileTransferTransportProbeFrameV6 probe:
                        lock (gate)
                        {
                            receiveResultCurrent = IsOutboundSparseReceiveResultCurrentLocked(
                                context,
                                completedReceiveInstall,
                                completedReceiveRuntimeOwner,
                                completedReceiveDataSession,
                                completedReceiveDataSessionGeneration,
                                out receiveResultRejection);
                        }

                        if (!receiveResultCurrent)
                        {
                            LogOutboundSparsePumpInstallRejected(
                                context,
                                completedReceiveInstall,
                                "probe_ack_dispatch",
                                receiveResultRejection);
                            break;
                        }

                        await HandleReceivedV6TransportProbeFrameAsync(
                            context.SessionId,
                            context.TransferId,
                            FileTransferDirection.Outbound,
                            probe,
                            received.TransportKind).ConfigureAwait(false);
                        break;
                    case FileTransferFallbackTailYieldFrameV6 yield:
                        ApplyOutboundFallbackTailYieldProofFromReceive(context, yield, completedReceiveInstall, completedReceiveRuntimeOwner, completedReceiveDataSession, completedReceiveDataSessionGeneration);
                        break;
                    case FileTransferPauseControlFrameV4 pauseControl:
                        LogPullDataFrameIgnored(context.TransferId, context.SessionId, pauseControl, "lifecycle_data_frame_ignored_phase2");
                        break;
                    case FileTransferStateFrameV4 state:
                        await ApplyOutboundV4StateAsync(context, state, completedReceiveInstall, completedReceiveRuntimeOwner, completedReceiveDataSession, completedReceiveDataSessionGeneration).ConfigureAwait(false);
                        if (IsCurrentPrimaryRegularNknBulkV6() &&
                            state is FileTransferReceiverStateFrameV6)
                        {
                            if (state is FileTransferReceiverStateFrameV6 receiverState &&
                                string.Equals(receiverState.RecoveryMode, V6RegularNknCheckpointSyncRecoveryMode, StringComparison.Ordinal))
                            {
                                LogPrimaryRegularNknBulkV6CheckpointReceived(context, receiverState);
                            }

                            LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.CreditGranted, "receiver_state");
                            LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.SendingBulk, "receiver_state");
                        }

                        SignalOutboundSparseSenderPump(context, completedReceiveInstall, completedReceiveRuntimeOwner, completedReceiveDataSession, completedReceiveDataSessionGeneration);
                        break;
                    case FileTransferCompleteFrameV4 complete:
                        if (await TryHandleOutboundLifecycleCompleteDataFrameAsync(
                                context,
                                complete,
                                completedReceiveInstall,
                                completedReceiveRuntimeOwner,
                                completedReceiveDataSession,
                                completedReceiveDataSessionGeneration).ConfigureAwait(false))
                        {
                            return;
                        }

                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_lifecycle_data_frame_ignored; kind=complete; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason=metadata_mismatch; file_size_bytes={complete.FileSizeBytes}");
                        break;
                    case FileTransferCancelFrameV4 cancel:
                    {
                        var reason = NormalizeReason(cancel.Reason);
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_lifecycle_priority_received; kind=cancel; transfer_id={context.TransferId}; session_id={context.SessionId}; direction=outbound; reason={FormatProtocolLogValue(reason ?? CanceledReason)}; path=redundant_data_frame");
                        var canceledCurrentReceive = await TransitionOutboundToTerminalAsync(
                                context,
                                FileTransferTransferState.Canceled,
                                errorCode: FileTransferResultCodes.CanceledRemote,
                                statusMessage: reason ?? "Transfer canceled by peer.",
                                notifyPeer: false,
                                cancelReason: null,
                                ct: CancellationToken.None,
                                requiredSparsePumpInstall: completedReceiveInstall)
                            .ConfigureAwait(false);
                        if (canceledCurrentReceive)
                        {
                            return;
                        }

                        break;
                    }
                    case FileTransferErrorFrameV4 error:
                        if (await TryHandleOutboundLifecycleErrorDataFrameAsync(
                                context,
                                error,
                                completedReceiveInstall,
                                completedReceiveRuntimeOwner,
                                completedReceiveDataSession,
                                completedReceiveDataSessionGeneration).ConfigureAwait(false))
                        {
                            return;
                        }

                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_lifecycle_data_frame_ignored; kind=error; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason=phase2_control_required; error_code={NormalizeErrorCode(error.ErrorCode) ?? InvalidStateErrorCode}");
                        break;
                    default:
                        LogPullDataFrameIgnored(context.TransferId, context.SessionId, frame, "unexpected_outbound_frame_v4");
                        break;
                }
                }
                catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
                {
                    receiveSupervisorStopReason = "lifetime_cancelled";
                    return;
                }
                catch (Exception ex)
                {
                    var failedInstall = pendingReceiveInstall ?? senderPumpInstall;
                    var failedDataSession = pendingReceiveDataSession ?? dataSession;
                    var failureCurrent = false;
                    lock (gate)
                    {
                        failureCurrent = failedInstall is not null &&
                            failedDataSession is not null &&
                            IsOutboundSparsePumpInstallCurrentLocked(
                                context,
                                failedInstall,
                                failedDataSession,
                                out _);
                    }

                    if (failureCurrent &&
                        OutboundSparseFailureDeferralBarrierForTests is { } failureDeferralBarrier)
                    {
                        await failureDeferralBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                    }

                    if (failureCurrent &&
                        (TryDeferCurrentPostTunaFallbackReceiveRecoveryPayloadHoldIfCurrent(
                             context,
                             "outbound_supervisor_iteration",
                             ex,
                             failedInstall,
                             failedDataSession) ||
                         TryDeferOutboundPostTunaFallbackTransportSendFailureIfCurrent(
                             context,
                             "outbound_supervisor_iteration",
                             ex,
                             failedInstall,
                             failedDataSession) ||
                         TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
                             context,
                             "outbound_supervisor_iteration",
                             ex,
                             failedInstall,
                             failedDataSession)))
                    {
                        StartCurrentPumpInstall(
                            "current_transport_failure_deferred",
                            reopenSource: true,
                            previousPumpAlreadyObserved: false);
                        continue;
                    }

                    var errorCode = ClassifyOutboundFailureErrorCode(ex, StreamReadFailedErrorCode);
                    var failedCurrentInstall = await FailOutboundV4Async(
                            context,
                            failedDataSession,
                            failedInstall?.RuntimeOwner,
                            errorCode,
                            ClassifyOutboundFailureStatusMessage(ex, errorCode),
                            notifyPeer: true,
                            requiredSparsePumpInstall: failedInstall)
                        .ConfigureAwait(false);
                    if (failedCurrentInstall)
                    {
                        receiveSupervisorStopReason = "current_outer_failure";
                        return;
                    }

                    LogOutboundSparsePumpInstallRejected(
                        context,
                        failedInstall,
                        "supervisor_iteration_failure",
                        "install_invalidated");
                    StartCurrentPumpInstall(
                        "stale_outer_failure",
                        reopenSource: true,
                        previousPumpAlreadyObserved: false);
                }
            }
        }
        catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
        {
            receiveSupervisorStopReason = "lifetime_cancelled";
            if (IsCurrentPrimaryRegularNknBulkV6())
            {
                LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.Cancelled, "lifetime_cancelled");
            }
        }
        catch (Exception ex)
        {
            if (IsCurrentPrimaryRegularNknBulkV6())
            {
                LogPrimaryRegularNknBulkV6State(context, PrimaryRegularNknBulkV6State.Failed, "exception");
            }

            var failedInstall = senderPumpInstall ?? startupPumpInstall;
            var failureCurrent = false;
            lock (gate)
            {
                failureCurrent = failedInstall is not null &&
                    dataSession is not null &&
                    IsOutboundSparsePumpInstallCurrentLocked(
                        context,
                        failedInstall,
                        dataSession,
                        out _);
            }

            if (failureCurrent &&
                OutboundSparseFailureDeferralBarrierForTests is { } failureDeferralBarrier)
            {
                await failureDeferralBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
            }

            if (failureCurrent &&
                (TryDeferCurrentPostTunaFallbackReceiveRecoveryPayloadHoldIfCurrent(
                     context,
                     "outbound_loop",
                     ex,
                     failedInstall,
                     dataSession) ||
                 TryDeferOutboundPostTunaFallbackTransportSendFailureIfCurrent(
                     context,
                     "outbound_loop",
                     ex,
                     failedInstall,
                     dataSession) ||
                 TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
                     context,
                     "outbound_loop",
                     ex,
                     failedInstall,
                     dataSession)))
            {
                receiveSupervisorStopReason = "outer_failure_deferred";
                restartSupervisorAfterCleanup = true;
            }
            else
            {
                var errorCode = ClassifyOutboundFailureErrorCode(ex, StreamReadFailedErrorCode);
                var failedCurrentInstall = await FailOutboundV4Async(
                        context,
                        dataSession,
                        failedInstall?.RuntimeOwner ?? senderRuntimeOwner,
                        errorCode,
                        ClassifyOutboundFailureStatusMessage(ex, errorCode),
                        notifyPeer: true,
                        requiredSparsePumpInstall: failedInstall)
                    .ConfigureAwait(false);
                receiveSupervisorStopReason = failedCurrentInstall
                    ? "outer_failure"
                    : "outer_failure_install_invalidated";
                restartSupervisorAfterCleanup = !failedCurrentInstall;
            }
        }
        finally
        {
            if (pendingReceiveTask is not null)
            {
                try
                {
                    pendingReceiveCancellation?.Cancel();
                }
                catch (ObjectDisposedException)
                {
                }

                await ObserveRetiredOutboundSparseReceiveAsync(
                        context,
                        pendingReceiveTask,
                        pendingReceiveInstall,
                        pendingReceiveDataSessionGeneration,
                        pendingReceiveCancellation)
                    .ConfigureAwait(false);
                pendingReceiveTask = null;
                pendingReceiveCancellation = null;
            }

            if (receiveSupervisorGeneration > 0)
            {
                lock (gate)
                {
                    if (ReferenceEquals(outboundTransfer, context) &&
                        context.ActiveOutboundSparseReceiveSupervisorGeneration == receiveSupervisorGeneration)
                    {
                        context.ActiveOutboundSparseReceiveSupervisorGeneration = 0;
                        context.PendingOutboundSparsePumpInstall = null;
                        if (context.IsTerminal)
                        {
                            context.InstalledOutboundSparsePump = null;
                        }
                    }
                }
            }

            if (pendingPumpInstallTask is not null)
            {
                try
                {
                    pendingPumpInstallCancellation?.Cancel();
                }
                catch (ObjectDisposedException)
                {
                }

                _ = DisposeRetiredOutboundSparsePumpInstallAsync(
                    context,
                    receiveSupervisorGeneration,
                    pendingPumpInstallTask,
                    pendingPumpInstallCancellation);
                pendingPumpInstallTask = null;
                pendingPumpInstallCancellation = null;
                pendingPumpInstallDescriptor = null;
            }

            try
            {
                senderPumpCancellation?.Cancel();
            }
            catch (ObjectDisposedException)
            {
            }

            if (senderPumpTask is not null &&
                senderPumpStream is not null &&
                senderPumpCancellation is not null)
            {
                _ = DisposeRetiredOutboundSparsePumpAsync(
                    senderPumpTask,
                    senderPumpStream,
                    senderPumpCancellation);
                senderPumpTask = null;
                senderPumpStream = null;
                senderPumpCancellation = null;
            }

            if (senderPumpStream is not null)
            {
                await DisposeOutboundSparsePumpStreamDiagnosticOnlyAsync(senderPumpStream).ConfigureAwait(false);
            }

            try
            {
                senderPumpCancellation?.Dispose();
            }
            catch (ObjectDisposedException)
            {
            }
            if (receiveSupervisorGeneration > 0)
            {
                string tuple;
                var terminal = false;
                lock (gate)
                {
                    terminal = !ReferenceEquals(outboundTransfer, context) || context.IsTerminal;
                    tuple = senderPumpInstall is null
                        ? $"install_generation=0; predecessor_install_generation=0; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.TerminalGeneration}; data_session_generation={context.DataSessionGeneration}"
                        : FormatOutboundSparsePumpInstallTuple(senderPumpInstall);
                }

                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_outbound_sparse_receive_supervisor_stopped; {tuple}; receive_supervisor_generation={receiveSupervisorGeneration}; terminal={(terminal ? 1 : 0)}; decision_reason={FormatProtocolLogValue(receiveSupervisorStopReason)}");
            }
        }

        if (restartSupervisorAfterCleanup)
        {
            var restartAuthorized = false;
            lock (gate)
            {
                restartAuthorized = ReferenceEquals(outboundTransfer, context) &&
                    !context.IsTerminal &&
                    SupportsOutboundSparsePumpInstall(context) &&
                    context.DataSession is not null &&
                    context.DataSessionGeneration > 0;
            }

            if (restartAuthorized)
            {
                _ = Task.Run(
                    async () =>
                    {
                        try
                        {
                            await Task.Delay(
                                    PullSessionReceivePollDelayMs,
                                    context.LifetimeCts.Token)
                                .ConfigureAwait(false);
                            await RunOutboundSparseCreditSenderAsync(context, runtimeKind).ConfigureAwait(false);
                        }
                        catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
                        {
                        }
                        catch (Exception restartException)
                        {
                            LocalOperationalLog.Warn(
                                "FileTransferService",
                                $"event=filetransfer_outbound_sparse_worker_handoff_rejected; install_generation=0; predecessor_install_generation=0; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; stage=receive_supervisor_restart; decision_reason=restart_failed; error={FormatProtocolLogValue(restartException.GetType().Name)}; message={FormatProtocolLogValue(restartException.Message)}");
                        }
                    },
                    CancellationToken.None);
            }
        }

    }

    private static FileTransferReceiveRecoveryRequest AttachOutboundSparsePumpInstallRecoveryAuthorityLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall? install,
        FileTransferReceiveRecoveryRequest request,
        string authorityReason)
    {
        if (install is null)
        {
            return AttachFallbackLegAuthority(context, request, authorityReason);
        }

        var publication = install.RoutePublication;
        var leg = context.CurrentTransferLeg;
        return request with
        {
            RouteToken = publication.RouteToken,
            ProtocolVersion = publication.ProtocolVersion,
            LiveRouteEpoch = publication.LiveRouteEpoch,
            TransferLegGeneration = install.LegGeneration,
            BridgeRecoveryGeneration = leg?.BridgeRecoveryGeneration ?? 0,
            TransportEpoch = leg?.TransportEpochId ?? 0,
            CheckpointRequestId = leg?.CheckpointRequestId,
            AuthorityReason = authorityReason,
        };
    }

    private bool TryDeferOutboundPostTunaFallbackDataSessionCancellation(
        OutboundTransferContext context,
        string source,
        OperationCanceledException ex)
        => TryDeferOutboundPostTunaFallbackDataSessionCancellationIfCurrent(
            context,
            source,
            ex,
            requiredInstall: null,
            requiredDataSession: null);

    private bool TryDeferOutboundPostTunaFallbackDataSessionCancellationIfCurrent(
        OutboundTransferContext context,
        string source,
        OperationCanceledException ex,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession? requiredDataSession)
    {
        SessionFileTransferSnapshot? snapshot;
        var now = DateTimeOffset.UtcNow;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.LifetimeCts.IsCancellationRequested ||
                (requiredInstall is not null &&
                 !IsOutboundSparsePumpInstallCurrentLocked(
                     context,
                     requiredInstall,
                     requiredDataSession,
                     out _)) ||
                !IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(context))
            {
                return false;
            }

            if (!context.PullTransportPaused)
            {
                context.PullTransportPaused = true;
                context.PullTransportPausedSinceUtc = now;
                context.PullTransportPauseReason = "post_tuna_fallback_bridge_restart";
                context.PullTransportLastPauseReason = context.PullTransportPauseReason;
                context.PullTransportResumeRequestPending = true;
            }

            context.PullTransportGraceDeadlineUtc = now.AddSeconds(5);
            context.StatusMessage = "Waiting for network recovery.";
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_bridge_restart_cancelled_send";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_bridge_restart_cancelled_send";
            snapshot = CreateSnapshotLocked();
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_data_session_cancellation_deferred; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; recovery_active={(context.PullPostTunaRecoveryActive ? 1 : 0)}; rebind_generation={context.PullTransportRebindGeneration}; transport_paused={(context.PullTransportPaused ? 1 : 0)}; error={FormatProtocolLogValue(ex.GetType().Name)}");
        RaiseTransferChanged(snapshot);
        SignalOutboundSparseSenderPump(
            context,
            requiredInstall,
            requiredInstall?.RuntimeOwner,
            requiredDataSession,
            requiredInstall?.DataSessionGeneration ?? 0);
        return true;
    }

    private bool TryDeferOutboundRegularNknV4RecoveryTransportSendFailure(
        OutboundTransferContext context,
        string source,
        Exception ex)
        => TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
            context,
            source,
            ex,
            requiredInstall: null,
            requiredDataSession: null);

    private bool TryDeferOutboundRegularNknV4RecoveryTransportSendFailureIfCurrent(
        OutboundTransferContext context,
        string source,
        Exception ex,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession? requiredDataSession)
    {
        if (!IsRecoverableRegularNknV4RecoveryTransportSendException(ex))
        {
            return false;
        }

        SessionFileTransferSnapshot? snapshot;
        FileTransferReceiveRecoveryRequest recoveryRequest;
        var now = DateTimeOffset.UtcNow;
        var recoveryReason = "regular_v4_receive_stall_recovery_send_failure";
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.LifetimeCts.IsCancellationRequested ||
                (requiredInstall is not null &&
                 !IsOutboundSparsePumpInstallCurrentLocked(
                     context,
                     requiredInstall,
                     requiredDataSession,
                     out _)) ||
                !IsOutboundRegularNknV4RecoverySendDeferrableLocked(context))
            {
                return false;
            }

            if (!context.PullTransportPaused)
            {
                context.PullTransportPaused = true;
                context.PullTransportPausedSinceUtc = now;
                context.PullTransportPauseReason = "receive_stall_recovery";
                context.PullTransportLastPauseReason = context.PullTransportPauseReason;
                context.PullTransportResumeRequestPending = true;
            }

            context.PullTransportGraceDeadlineUtc = now.AddSeconds(5);
            context.StatusMessage = "Waiting for network recovery.";
            context.SparseSenderPumpLastWakeReason = "regular_v4_receive_stall_recovery_send_failure";
            context.V6SenderPumpLastWakeReason = "regular_v4_receive_stall_recovery_send_failure";
            MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(context, recoveryReason);
            snapshot = CreateSnapshotLocked();
            recoveryRequest = AttachOutboundSparsePumpInstallRecoveryAuthorityLocked(
                context,
                requiredInstall,
                new FileTransferReceiveRecoveryRequest(
                    context.SessionId,
                    context.TransferId,
                    FileTransferDirection.Outbound,
                    recoveryReason)
                {
                    RouteToken = FileTransferRouteResolver.RegularNknV4FastToken,
                    ProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
                    AuthorityReason = recoveryReason,
                },
                recoveryReason);
        }

        TryRequestFileTransferReceiveRecoveryIfCurrent(
            recoveryRequest,
            requiredInstall,
            requiredDataSession);

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_regular_v4_recovery_transport_send_failure_deferred; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; reason={FormatProtocolLogValue(recoveryReason)}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; transport_paused={(context.PullTransportPaused ? 1 : 0)}; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");
        RaiseTransferChanged(snapshot);
        SignalOutboundSparseSenderPump(
            context,
            requiredInstall,
            requiredInstall?.RuntimeOwner,
            requiredDataSession,
            requiredInstall?.DataSessionGeneration ?? 0);
        return true;
    }

    private static bool IsOutboundRegularNknV4RecoverySendDeferrableLocked(OutboundTransferContext context)
    {
        if (!context.RouteRuntime.UsesRegularNknV4FastRuntime ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4 ||
            context.UserPaused ||
            context.PeerPaused ||
            !context.PullSourceCanSeek ||
            context.RemoteNextExpectedChunkIndex >= context.ChunkCount)
        {
            return false;
        }

        var acceptedUntil = ResolveOutboundRepairAcceptedUntilExclusiveLocked(context);
        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var hasFrontierLag = acceptedUntil > remoteFrontier;
        var hasRecoveryReplay =
            context.PullRegularNknV4PeerSilenceSafetyReplayCount > 0 ||
            context.PullV4SenderPumpRepairQueue.Count > 0 ||
            context.PullV4SenderPumpRepairQueuedChunkIndices.Count > 0 ||
            context.PullTransportResumeRequestPending;
        var recoveryPauseActive = ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context);
        var receiveRecoveryFresh =
            context.V6LastReceiveRecoveryRequestedUtc is { } lastReceiveRecovery &&
            DateTimeOffset.UtcNow - lastReceiveRecovery < CurrentV6SenderRequestFeedbackStallRecoveryCooldown;
        return hasFrontierLag && (hasRecoveryReplay || recoveryPauseActive || receiveRecoveryFresh);
    }

    private static bool IsRecoverableRegularNknV4RecoveryTransportSendException(Exception ex)
    {
        if (ex is OperationCanceledException)
        {
            return true;
        }

        return IsTransportDisconnected(ex);
    }

    private bool TryDeferOutboundPostTunaFallbackTransportSendFailure(
        OutboundTransferContext context,
        string source,
        Exception ex)
        => TryDeferOutboundPostTunaFallbackTransportSendFailureIfCurrent(
            context,
            source,
            ex,
            requiredInstall: null,
            requiredDataSession: null);

    private static FileTransferDataSessionSubmissionUnavailableException?
        FindDataSessionSubmissionUnavailableException(Exception exception)
    {
        for (Exception? current = exception; current is not null; current = current.InnerException)
        {
            if (current is FileTransferDataSessionSubmissionUnavailableException unavailable)
            {
                return unavailable;
            }
        }

        return null;
    }

    private static bool TryBindPostTunaFallbackReceiveRecoveryPayloadHoldLocked(
        OutboundTransferContext context,
        FileTransferReceiveRecoveryOperation operation,
        DateTimeOffset immutableDeadlineUtc,
        OutboundSparsePumpInstall requiredInstall,
        IFileTransferDataSession requiredDataSession,
        FileTransferReceiveRecoverySubmissionFailureObservation observation,
        out OutboundPostTunaFallbackReceiveRecoveryPayloadHold hold)
    {
        hold = default!;
        if (immutableDeadlineUtc <= DateTimeOffset.UtcNow ||
            observation.Authority != operation.Authority ||
            !IsPostTunaFallbackReceiveRecoveryPayloadScopeCurrentLocked(
                context,
                operation,
                requiredInstall,
                requiredDataSession))
        {
            return false;
        }

        var dataSessionIdentity = CreateReceiveRecoveryDataSessionIdentity(
            context.TransferId,
            requiredDataSession,
            requiredInstall.DataSessionGeneration);
        if (context.CurrentPostTunaFallbackReceiveRecoveryPayloadHold is { } current)
        {
            if (current.Authority != operation.Authority ||
                current.PumpInstall != requiredInstall ||
                !ReferenceEquals(current.DataSession, requiredDataSession) ||
                !string.Equals(
                    current.DataSessionIdentity,
                    dataSessionIdentity,
                    StringComparison.Ordinal) ||
                current.ImmutableDeadlineUtc != immutableDeadlineUtc)
            {
                if (current.Authority == operation.Authority ||
                    current.PumpInstall != requiredInstall ||
                    !ReferenceEquals(current.DataSession, requiredDataSession) ||
                    !TryClearPostTunaFallbackReceiveRecoveryPayloadHoldLocked(
                        context,
                        current))
                {
                    return false;
                }
            }
            else
            {
                current.PhysicalSendLeaseGenerations.Add(
                    observation.PhysicalSendLeaseGeneration);
                hold = current;
                return true;
            }
        }

        const string submissionEpochPauseReason =
            "post_tuna_fallback_receive_recovery_submission_epoch_transition";
        var ownsTransportPause =
            !context.PullTransportPaused ||
            string.Equals(
                context.PullTransportPauseReason,
                "post_tuna_fallback_bridge_restart",
                StringComparison.Ordinal) ||
            string.Equals(
                context.PullTransportPauseReason,
                submissionEpochPauseReason,
                StringComparison.Ordinal);
        if (ownsTransportPause)
        {
            context.PullTransportPaused = true;
            context.PullTransportPausedSinceUtc ??= DateTimeOffset.UtcNow;
            context.PullTransportPauseReason = submissionEpochPauseReason;
            context.PullTransportLastPauseReason = submissionEpochPauseReason;
            context.PullTransportResumeRequestPending = true;
        }

        hold = new OutboundPostTunaFallbackReceiveRecoveryPayloadHold
        {
            HoldGeneration = checked(
                ++context.LastPostTunaFallbackReceiveRecoveryPayloadHoldGeneration),
            Authority = operation.Authority,
            ImmutableDeadlineUtc = immutableDeadlineUtc,
            PumpInstall = requiredInstall,
            DataSession = requiredDataSession,
            DataSessionIdentity = dataSessionIdentity,
            OwnsTransportPause = ownsTransportPause,
        };
        hold.PhysicalSendLeaseGenerations.Add(
            observation.PhysicalSendLeaseGeneration);
        context.CurrentPostTunaFallbackReceiveRecoveryPayloadHold = hold;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_recovery_submission_hold_bound; decision_status=Accepted; decision_reason=exact_receive_recovery_operation_owned_submission_hold; authority_effect=hold_bound; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; hold_generation={hold.HoldGeneration}; receive_recovery_operation_authority_id={FormatProtocolLogValue(operation.Authority.AuthorityId.ToString())}; receive_recovery_operation_generation={operation.Authority.OperationGeneration}; pump_install_generation={requiredInstall.InstallGeneration}; physical_send_lease_generation={observation.PhysicalSendLeaseGeneration}; immutable_deadline_utc_ms={immutableDeadlineUtc.ToUnixTimeMilliseconds()}; route={FormatProtocolLogValue(observation.RuntimeOwner.RouteToken)}; protocol_version={observation.RuntimeOwner.ProtocolVersion}; live_route_epoch={observation.RuntimeOwner.LiveRouteEpoch}; runtime_generation={observation.RuntimeOwner.RuntimeGeneration}; route_publication_generation={observation.RoutePublication.PublicationGeneration}; terminal_generation={observation.TerminalGeneration}; leg_generation={observation.LegGeneration}; transport_epoch={observation.TransportEpoch}; bridge_recovery_generation={observation.BridgeRecoveryGeneration}; checkpoint_request_id={FormatProtocolLogValue(observation.Authority.ExecutionCommand.CheckpointRequestId ?? "(none)")}; data_session_generation={observation.DataSessionGeneration}; owns_transport_pause={(ownsTransportPause ? 1 : 0)}");
        return true;
    }

    private static bool TryClearPostTunaFallbackReceiveRecoveryPayloadHoldLocked(
        OutboundTransferContext context,
        OutboundPostTunaFallbackReceiveRecoveryPayloadHold requiredHold)
    {
        if (!ReferenceEquals(
                context.CurrentPostTunaFallbackReceiveRecoveryPayloadHold,
                requiredHold))
        {
            return false;
        }

        context.CurrentPostTunaFallbackReceiveRecoveryPayloadHold = null;
        foreach (var leaseGeneration in requiredHold.PhysicalSendLeaseGenerations)
        {
            context.ReceiveRecoverySubmissionFailureObservations.Remove(
                leaseGeneration);
        }

        const string submissionEpochPauseReason =
            "post_tuna_fallback_receive_recovery_submission_epoch_transition";
        if (requiredHold.OwnsTransportPause &&
            context.PullTransportPaused &&
            string.Equals(
                context.PullTransportPauseReason,
                submissionEpochPauseReason,
                StringComparison.Ordinal))
        {
            context.PullTransportLastPauseReason =
                context.PullTransportPauseReason;
            context.PullTransportPaused = false;
            context.PullTransportPausedSinceUtc = null;
            context.PullTransportPauseReason = null;
            context.PullTransportResumeRequestPending = false;
        }

        return true;
    }

    private bool TryDeferCurrentPostTunaFallbackRecoverySubmissionFailure(
        OutboundTransferContext context,
        Exception exception,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession requiredDataSession,
        long physicalSendLeaseGeneration,
        string repairRequestKey,
        out FileTransferReceiveRecoverySubmissionFailureDisposition disposition)
    {
        disposition = FileTransferReceiveRecoverySubmissionFailureDisposition.Rejected;
        var unavailable = FindDataSessionSubmissionUnavailableException(exception);
        if (unavailable is null || !unavailable.RecoveryBarrierActive || requiredInstall is null)
        {
            return false;
        }

        FileTransferReceiveRecoveryOperation operation;
        DateTimeOffset immutableDeadlineUtc = default;
        FileTransferReceiveRecoverySubmissionFailureObservation observation;
        long holdGeneration = 0;
        var now = DateTimeOffset.UtcNow;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.LifetimeCts.IsCancellationRequested ||
                context.RouteSelection.Route != FileTransferRoute.PostTunaFallbackV6 ||
                context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV6 ||
                context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V6 ||
                !ReferenceEquals(context.DataSession, requiredDataSession) ||
                !IsOutboundSparsePumpInstallCurrentLocked(
                    context,
                    requiredInstall,
                    requiredDataSession,
                    out _))
            {
                return false;
            }

            var state = CreateCoordinatorStateLocked(context);
            if (!context.ReceiveRecoverySubmissionFailureObservations.TryGetValue(
                    physicalSendLeaseGeneration,
                    out observation!))
            {
                if (!TryCreateReceiveRecoverySubmissionFailureObservationLocked(
                        context,
                        requiredInstall,
                        requiredDataSession,
                        physicalSendLeaseGeneration,
                        repairRequestKey,
                        unavailable,
                        now,
                        out observation))
                {
                    return false;
                }

                context.ReceiveRecoverySubmissionFailureObservations[
                    physicalSendLeaseGeneration] = observation;
            }

            if (observation.RejectionReason != unavailable.Reason ||
                !string.Equals(observation.RejectionStage, unavailable.Stage, StringComparison.Ordinal) ||
                !string.Equals(observation.RejectionChannel, unavailable.Channel, StringComparison.Ordinal) ||
                observation.ExpectedSubmissionEpoch != unavailable.ExpectedSubmissionEpoch ||
                observation.CurrentSubmissionEpoch != unavailable.CurrentSubmissionEpoch ||
                observation.ExpectedProcessEpoch != unavailable.ExpectedProcessEpoch ||
                observation.CurrentProcessEpoch != unavailable.CurrentProcessEpoch)
            {
                return false;
            }

            disposition = FileTransferCoordinator.ClassifyReceiveRecoverySubmissionFailure(
                state,
                observation,
                now,
                out operation,
                out immutableDeadlineUtc,
                out var classificationReason);
            var classificationEnvelope =
                RecordReceiveRecoveryAttemptSnapshotLocked(
                    context,
                    state,
                    nameof(FileTransferCoordinator.ClassifyReceiveRecoverySubmissionFailure),
                    disposition.ToString(),
                    classificationReason,
                    observation,
                    observation.Authority);
            if (disposition == FileTransferReceiveRecoverySubmissionFailureDisposition.Rejected)
            {
                context.ReceiveRecoverySubmissionFailureObservations.Remove(
                    physicalSendLeaseGeneration);
                LogPostTunaFallbackRecoverySubmissionFailureFinalized(
                    context,
                    observation,
                    operation,
                    disposition,
                    now,
                    pumpHandoff: false,
                    classificationReason);
                return false;
            }

            if (disposition == FileTransferReceiveRecoverySubmissionFailureDisposition
                    .CompletedProvenLateChildRetirement)
            {
                context.ReceiveRecoverySubmissionFailureObservations.Remove(
                    physicalSendLeaseGeneration);
                context.SparseSenderPumpLastWakeReason =
                    "post_tuna_fallback_recovery_late_submission_child_retired";
                context.V6SenderPumpLastWakeReason =
                    "post_tuna_fallback_recovery_late_submission_child_retired";
                LogPostTunaFallbackRecoverySubmissionFailureFinalized(
                    context,
                    observation,
                    operation,
                    disposition,
                    now,
                    pumpHandoff: true,
                    classificationReason);
                return true;
            }

            if (!TryBindPostTunaFallbackReceiveRecoveryPayloadHoldLocked(
                    context,
                    operation,
                    immutableDeadlineUtc,
                    requiredInstall,
                    requiredDataSession,
                    observation,
                    out var hold))
            {
                return false;
            }

            EnqueueReceiveRecoveryAttemptAuthorityEffect(
                context,
                classificationEnvelope,
                "payload_hold_bound");

            context.ReceiveRecoverySubmissionFailureObservations.Remove(
                physicalSendLeaseGeneration);
            holdGeneration = hold.HoldGeneration;
            context.SparseSenderPumpLastWakeReason =
                "post_tuna_fallback_recovery_submission_failure_deferred";
            context.V6SenderPumpLastWakeReason =
                "post_tuna_fallback_recovery_submission_failure_deferred";
            context.StatusMessage = "Waiting for network recovery.";
            LogPostTunaFallbackRecoverySubmissionFailureFinalized(
                context,
                observation,
                operation,
                disposition,
                now,
                pumpHandoff: false,
                classificationReason);
        }

        var authorityObservation = operation.Authority.Observation;
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_recovery_submission_failure_deferred; decision_status=Accepted; decision_reason=current_post_tuna_fallback_recovery_submission_epoch_failure_deferred; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; hold_generation={holdGeneration}; receive_recovery_operation_authority_id={FormatProtocolLogValue(operation.Authority.AuthorityId.ToString())}; receive_recovery_operation_generation={operation.Authority.OperationGeneration}; physical_send_lease_generation={physicalSendLeaseGeneration}; repair_request_key={FormatProtocolLogValue(repairRequestKey)}; typed_rejection_reason={FormatProtocolLogValue(unavailable.Reason.ToString())}; rejection_stage={FormatProtocolLogValue(unavailable.Stage)}; rejection_channel={FormatProtocolLogValue(unavailable.Channel)}; expected_submission_epoch={unavailable.ExpectedSubmissionEpoch}; current_submission_epoch={unavailable.CurrentSubmissionEpoch}; expected_process_epoch={unavailable.ExpectedProcessEpoch}; current_process_epoch={unavailable.CurrentProcessEpoch}; recovery_barrier_active=1; immutable_deadline_utc_ms={immutableDeadlineUtc.ToUnixTimeMilliseconds()}; route={FormatProtocolLogValue(authorityObservation.RouteToken)}; protocol_version={authorityObservation.ProtocolVersion}; live_route_epoch={authorityObservation.LiveRouteEpoch}; runtime_generation={authorityObservation.RuntimeOwner.RuntimeGeneration}; route_publication_generation={authorityObservation.RoutePublication.PublicationGeneration}; terminal_generation={authorityObservation.TerminalGeneration}; leg_generation={authorityObservation.LegGeneration}; transport_epoch={authorityObservation.TransportEpoch}; bridge_recovery_generation={authorityObservation.BridgeRecoveryGeneration}; bridge_decision_generation={operation.Authority.BridgeRecoveryDecision.BridgeDecisionGeneration}; checkpoint_request_id={FormatProtocolLogValue(operation.Authority.ExecutionCommand.CheckpointRequestId ?? "(none)")}; data_session_generation={authorityObservation.DataSessionGeneration}");
        return true;
    }

    private bool TryCreateReceiveRecoverySubmissionFailureObservationLocked(
        OutboundTransferContext context,
        OutboundSparsePumpInstall requiredInstall,
        IFileTransferDataSession requiredDataSession,
        long physicalSendLeaseGeneration,
        string repairRequestKey,
        FileTransferDataSessionSubmissionUnavailableException unavailable,
        DateTimeOffset observedUtc,
        out FileTransferReceiveRecoverySubmissionFailureObservation observation)
    {
        observation = default!;
        var state = CreateCoordinatorStateLocked(context);
        if (!FileTransferCoordinator.TryGetCurrentReceiveRecoveryPayloadSubmissionHold(
                state,
                out var operation,
                out _) ||
            !FileTransferCoordinator.TryGetReceiveRecoveryLivenessDeferral(
                state,
                out var livenessOperation,
                out _,
                out var immutableDeadlineUtc) ||
            livenessOperation.Authority != operation.Authority ||
            immutableDeadlineUtc <= observedUtc ||
            context.CurrentTransferLeg is not { } leg)
        {
            return false;
        }

        var authorityObservation = operation.Authority.Observation;
        var dataSessionIdentity = CreateReceiveRecoveryDataSessionIdentity(
            context.TransferId,
            requiredDataSession,
            requiredInstall.DataSessionGeneration);
        if (authorityObservation.Direction != FileTransferDirection.Outbound ||
            authorityObservation.Route != FileTransferRoute.PostTunaFallbackV6 ||
            authorityObservation.ProtocolVersion != FileTransferProtocol.ProtocolVersionV6 ||
            authorityObservation.RuntimeOwner != requiredInstall.RuntimeOwner ||
            authorityObservation.RoutePublication != requiredInstall.RoutePublication ||
            authorityObservation.TerminalGeneration != requiredInstall.TerminalGeneration ||
            authorityObservation.LegGeneration != requiredInstall.LegGeneration ||
            authorityObservation.TransportEpoch != leg.TransportEpochId ||
            authorityObservation.BridgeRecoveryGeneration != leg.BridgeRecoveryGeneration ||
            authorityObservation.DataSessionGeneration != requiredInstall.DataSessionGeneration ||
            !string.Equals(
                authorityObservation.DataSessionIdentity,
                dataSessionIdentity,
                StringComparison.Ordinal))
        {
            return false;
        }

        observation = new FileTransferReceiveRecoverySubmissionFailureObservation(
            operation.Authority,
            physicalSendLeaseGeneration,
            requiredInstall.RuntimeOwner,
            requiredInstall.RoutePublication,
            requiredInstall.TerminalGeneration,
            requiredInstall.LegGeneration,
            leg.TransportEpochId,
            leg.BridgeRecoveryGeneration,
            dataSessionIdentity,
            requiredInstall.DataSessionGeneration,
            string.Equals(repairRequestKey, "(none)", StringComparison.Ordinal)
                ? OutboundPhysicalSendKind.PostTunaFallbackV6Payload.ToString()
                : OutboundPhysicalSendKind.PostTunaFallbackV6Repair.ToString(),
            repairRequestKey,
            unavailable.Reason,
            unavailable.Stage,
            unavailable.Channel,
            unavailable.ExpectedSubmissionEpoch,
            unavailable.CurrentSubmissionEpoch,
            unavailable.ExpectedProcessEpoch,
            unavailable.CurrentProcessEpoch,
            unavailable.RecoveryBarrierActive,
            observedUtc.ToUnixTimeMilliseconds());
        return !observation.IsDefault;
    }

    private static void LogPostTunaFallbackRecoverySubmissionFailureFinalized(
        OutboundTransferContext context,
        FileTransferReceiveRecoverySubmissionFailureObservation observation,
        FileTransferReceiveRecoveryOperation operation,
        FileTransferReceiveRecoverySubmissionFailureDisposition disposition,
        DateTimeOffset handledUtc,
        bool pumpHandoff,
        string reason)
        => LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_recovery_submission_failure_finalized; decision_status={(disposition == FileTransferReceiveRecoverySubmissionFailureDisposition.Rejected ? "Rejected" : "Accepted")}; disposition={FormatProtocolLogValue(disposition.ToString())}; decision_reason={FormatProtocolLogValue(reason)}; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; receive_recovery_operation_authority_id={FormatProtocolLogValue(observation.Authority.AuthorityId.ToString())}; receive_recovery_operation_generation={observation.Authority.OperationGeneration}; physical_send_lease_generation={observation.PhysicalSendLeaseGeneration}; send_kind={FormatProtocolLogValue(observation.SendKind)}; repair_request_key={FormatProtocolLogValue(observation.RepairRequestKey)}; typed_rejection_reason={FormatProtocolLogValue(observation.RejectionReason.ToString())}; rejection_stage={FormatProtocolLogValue(observation.RejectionStage)}; rejection_channel={FormatProtocolLogValue(observation.RejectionChannel)}; expected_submission_epoch={observation.ExpectedSubmissionEpoch}; current_submission_epoch={observation.CurrentSubmissionEpoch}; expected_process_epoch={observation.ExpectedProcessEpoch}; current_process_epoch={observation.CurrentProcessEpoch}; recovery_barrier_active={(observation.RecoveryBarrierActive ? 1 : 0)}; observed_utc_ms={observation.ObservedUtcMs}; handled_utc_ms={handledUtc.ToUnixTimeMilliseconds()}; operation_state={FormatProtocolLogValue(operation.ExecutionState.ToString())}; proof_identity={FormatProtocolLogValue(operation.ReceiveProof?.ProofIdentity ?? "(none)")}; pump_handoff={(pumpHandoff ? 1 : 0)}; route={FormatProtocolLogValue(observation.RuntimeOwner.RouteToken)}; protocol_version={observation.RuntimeOwner.ProtocolVersion}; live_route_epoch={observation.RuntimeOwner.LiveRouteEpoch}; runtime_generation={observation.RuntimeOwner.RuntimeGeneration}; route_publication_generation={observation.RoutePublication.PublicationGeneration}; terminal_generation={observation.TerminalGeneration}; leg_generation={observation.LegGeneration}; transport_epoch={observation.TransportEpoch}; bridge_recovery_generation={observation.BridgeRecoveryGeneration}; checkpoint_request_id={FormatProtocolLogValue(observation.Authority.ExecutionCommand.CheckpointRequestId ?? "(none)")}; data_session_generation={observation.DataSessionGeneration}");

    private bool TryDeferOutboundPostTunaFallbackTransportSendFailureIfCurrent(
        OutboundTransferContext context,
        string source,
        Exception ex,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession? requiredDataSession)
    {
        if (!IsRecoverablePostTunaFallbackTransportSendException(ex))
        {
            return false;
        }

        SessionFileTransferSnapshot? snapshot;
        FileTransferReceiveRecoveryRequest recoveryRequest;
        var now = DateTimeOffset.UtcNow;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.LifetimeCts.IsCancellationRequested ||
                context.CurrentPostTunaFallbackReceiveRecoveryPayloadHold is not null ||
                (requiredInstall is not null &&
                 !IsOutboundSparsePumpInstallCurrentLocked(
                     context,
                     requiredInstall,
                     requiredDataSession,
                     out _)) ||
                !IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(context))
            {
                return false;
            }

            if (!context.PullTransportPaused)
            {
                context.PullTransportPaused = true;
                context.PullTransportPausedSinceUtc = now;
                context.PullTransportPauseReason = "post_tuna_fallback_bridge_restart";
                context.PullTransportLastPauseReason = context.PullTransportPauseReason;
                context.PullTransportResumeRequestPending = true;
            }

            context.PullTransportGraceDeadlineUtc = now.AddSeconds(5);
            context.StatusMessage = "Waiting for network recovery.";
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_bridge_restart_send_failure";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_bridge_restart_send_failure";
            snapshot = CreateSnapshotLocked();
            const string recoveryReason = "post_tuna_fallback_bridge_restart_send_failure";
            recoveryRequest = AttachOutboundSparsePumpInstallRecoveryAuthorityLocked(
                context,
                requiredInstall,
                new FileTransferReceiveRecoveryRequest(
                    context.SessionId,
                    context.TransferId,
                    FileTransferDirection.Outbound,
                    recoveryReason),
                recoveryReason);
        }

        TryRequestFileTransferReceiveRecoveryIfCurrent(
            recoveryRequest,
            requiredInstall,
            requiredDataSession);

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_transport_send_failure_deferred; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; reason=post_tuna_fallback_bridge_restart_send_failure; recovery_active={(context.PullPostTunaRecoveryActive ? 1 : 0)}; rebind_generation={context.PullTransportRebindGeneration}; transport_paused={(context.PullTransportPaused ? 1 : 0)}; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");
        RaiseTransferChanged(snapshot);
        SignalOutboundSparseSenderPump(
            context,
            requiredInstall,
            requiredInstall?.RuntimeOwner,
            requiredDataSession,
            requiredInstall?.DataSessionGeneration ?? 0);
        return true;
    }

    private static bool IsRecoverablePostTunaFallbackTransportSendException(Exception ex)
    {
        if (ex is OperationCanceledException)
        {
            return true;
        }

        return IsTransportDisconnected(ex);
    }

    private bool TryGetOutboundV4PeerSilenceFailure(
        OutboundTransferContext context,
        out string statusMessage,
        out FileTransferFrontierRequestFrameV6? feedbackStateRefreshRequest)
    {
        statusMessage = "Receiver stopped responding.";
        feedbackStateRefreshRequest = null;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.UserPaused ||
                context.PeerPaused ||
                context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6)
            {
                return false;
            }

            if (context.PullTransportPaused &&
                !IsTunaFallbackTransportPauseReason(context.PullTransportPauseReason))
            {
                return false;
            }

            var lastPeerFrameUtc = context.PullV4LastPeerFrameReceivedUtc ??
                context.PullTransportRebindStartedUtc ??
                context.PullTransportLastSafetyReplayUtc;
            if (lastPeerFrameUtc is null)
            {
                return false;
            }

            var postFallback = IsOutboundPostTunaRecoveryActiveLocked(context);
            var silence = DateTimeOffset.UtcNow - lastPeerFrameUtc.Value;
            var timeout = ResolveV4PeerSilenceTimeout(postFallback);
            var hasUnacknowledgedData =
                context.ChunksAcceptedForTransport > context.RemoteNextExpectedChunkIndex ||
                context.BytesAcceptedForTransport > context.BytesTransferred ||
                context.PullV4SenderPumpRepairRequests.Count > 0;
            if (!hasUnacknowledgedData)
            {
                return false;
            }

            var isPrimaryRegularNknBulkV6 =
                !postFallback &&
                IsPrimaryRegularNknBulkV6ContextLocked(context);
            var isDiagnosticV6SparseRuntimePrimaryRegularNkn =
                !postFallback &&
                !isPrimaryRegularNknBulkV6 &&
                ShouldUseV6RegularNknSparseRuntime(context) &&
                IsOutboundV6PrimaryRegularNknWithoutTunaRecoveryLocked(context);
            var isPostTunaFallbackSparseRuntime =
                postFallback &&
                ShouldUsePostTunaFallbackV6SparseRuntimeLocked(context);
            if (isPrimaryRegularNknBulkV6)
            {
                TryPrepareOutboundPrimaryRegularNknBulkV6CheckpointSyncLocked(
                    context,
                    silence,
                    out feedbackStateRefreshRequest);
            }
            else if (isDiagnosticV6SparseRuntimePrimaryRegularNkn ||
                     isPostTunaFallbackSparseRuntime)
            {
                TryPrepareOutboundV4SparseRuntimeReceiveRecoveryLocked(
                    context,
                    silence,
                    out feedbackStateRefreshRequest);
            }

            if (silence < timeout)
            {
                return false;
            }

            var reason = postFallback
                ? "post_tuna_fallback_peer_silence"
                : "peer_silence";
            if (isPrimaryRegularNknBulkV6)
            {
                MaybeLogOutboundPrimaryRegularNknBulkV6PeerSilenceDeferralLocked(context, reason, silence, timeout);
                return false;
            }

            if (isDiagnosticV6SparseRuntimePrimaryRegularNkn)
            {
                MaybeLogOutboundV4SparseRuntimePeerSilenceDeferralLocked(context, reason, silence, timeout);
                return false;
            }

            if (isPostTunaFallbackSparseRuntime)
            {
                MaybeLogOutboundPostTunaFallbackPeerSilenceDeferralLocked(context, reason, silence, timeout);
                MaybeQueueOutboundV4StalledRebindSafetyReplayLocked(context, reason);
                return false;
            }

            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v4_peer_feedback_timeout; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={reason}; rebind_generation={context.PullTransportRebindGeneration}; silence_ms={(long)Math.Max(0, silence.TotalMilliseconds)}; timeout_ms={(long)timeout.TotalMilliseconds}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; bytes_transferred={context.BytesTransferred}; bytes_accepted_for_transport={context.BytesAcceptedForTransport}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}");
            return true;
        }
    }

    private void TryPrepareOutboundV4SparseRuntimeReceiveRecoveryLocked(
        OutboundTransferContext context,
        TimeSpan feedbackSilence,
        out FileTransferFrontierRequestFrameV6? stateRefreshRequest)
    {
        stateRefreshRequest = null;
        var now = DateTimeOffset.UtcNow;
        if (feedbackSilence < CurrentV6SenderRequestFeedbackStallRecoveryDelay ||
            context.V6RegularNknLastStateRefreshRequestedUtc is { } lastRefresh &&
            now - lastRefresh < CurrentV6RegularNknSparseRuntimeStateRefreshCooldown)
        {
            return;
        }

        var transportEpoch = ResolveOutboundV6SparseRuntimeStateRefreshTransportEpoch(context);
        var epochState = context.V6TransportEpoch is null ? "none" : FormatV6TransportEpochState(context.V6TransportEpoch.State);
        var transportBacklogChunks = Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex);
        var creditCeiling = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
        var availableCreditChunks = Math.Max(0, creditCeiling - context.ChunksAcceptedForTransport);
        var inFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames);
        var queuedRepairChunkCount = context.PullV4SenderPumpRepairQueue.Sum(static repair => repair.ChunkIndices.Count);
        var staleCreditRecoveryDelay = CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay;
        if (ShouldSuppressOutboundFallbackCheckpointRequestForDeliveryRecoveryLocked(
                context,
                "v4_sparse_runtime_receive_recovery",
                out var requestSuppressionReason,
                out var requestDeliveryRecoveryAgeMs,
                out var requestDeliveryRecoveryRemainingMs))
        {
            context.PullTransportResumeRequestPending = true;
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_checkpoint_delivery_recovery_pending";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_checkpoint_delivery_recovery_pending";
            LogOutboundFallbackCheckpointRequestSuppressedForDeliveryRecovery(
                context,
                "v4_sparse_runtime_receive_recovery",
                requestSuppressionReason,
                requestDeliveryRecoveryAgeMs,
                requestDeliveryRecoveryRemainingMs);
            return;
        }

        if (ShouldForcePostTunaFallbackStaleInflightRecoveryLocked(
                context,
                feedbackSilence,
                transportBacklogChunks,
                availableCreditChunks,
                inFlightFrames))
        {
            var staleInFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames);
            var staleInFlightBytes = Math.Max(0, context.PullSenderPipelineCurrentInFlightBytes);
            context.PullSenderPipelineCurrentInFlightFrames = 0;
            context.PullSenderPipelineCurrentInFlightBytes = 0;
            context.PullSenderPipelineFailedFramesRecent += staleInFlightFrames;
            context.PullSenderPipelineFailedFramesTotal += staleInFlightFrames;
            context.V6EpochLivenessDeferralCount++;
            context.V6EpochLivenessDeferralUtc = now;
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_stale_inflight_recovery";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_stale_inflight_recovery";

            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_post_tuna_fallback_stale_inflight_repair_recovery_forced; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason=sender_pipeline_in_flight_stale; deferral_count={context.V6EpochLivenessDeferralCount}; feedback_silence_ms={(long)feedbackSilence.TotalMilliseconds}; recovery_delay_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryDelay.TotalMilliseconds}; stale_credit_recovery_delay_ms={(long)staleCreditRecoveryDelay.TotalMilliseconds}; transport_epoch={transportEpoch}; epoch_state={FormatProtocolLogValue(epochState)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; stale_in_flight_frames={staleInFlightFrames}; stale_in_flight_bytes={staleInFlightBytes}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}; queued_repair_chunk_count={queuedRepairChunkCount}; state_refresh_failure_count={context.V6RegularNknStateRefreshFailureCount}; rebind_generation={context.PullTransportRebindGeneration}");

            stateRefreshRequest = CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
                context,
                now,
                feedbackSilence,
                transportEpoch,
                epochState,
                transportBacklogChunks,
                availableCreditChunks,
                creditCeiling,
                0,
                queuedRepairChunkCount,
                "feedback_stalled_with_stale_inflight",
                V6RegularNknStateRefreshStaleInflightPriority);
            return;
        }

        if (ShouldForcePostTunaFallbackStaleCreditRecoveryLocked(
                context,
                feedbackSilence,
                transportBacklogChunks,
                availableCreditChunks))
        {
            var previousCreditCeiling = creditCeiling;
            var previousRemoteGrantedUntilExclusive = context.RemoteGrantedUntilExclusive;
            var clampedGrant = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunksAcceptedForTransport);
            context.RemoteGrantedUntilExclusive = clampedGrant;
            creditCeiling = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
            context.V6EpochLivenessDeferralCount++;
            context.V6EpochLivenessDeferralUtc = now;
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_stale_credit_recovery";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_stale_credit_recovery";
            ActivateOutboundV4PostRebindFrontierOnlyRepairLocked(
                context,
                Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, Math.Max(0, context.ChunkCount - 1)),
                "post_tuna_fallback_stale_credit");

            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_post_tuna_fallback_stale_credit_recovery_forced; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason=receiver_credit_stale; deferral_count={context.V6EpochLivenessDeferralCount}; feedback_silence_ms={(long)feedbackSilence.TotalMilliseconds}; recovery_delay_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryDelay.TotalMilliseconds}; stale_credit_recovery_delay_ms={(long)staleCreditRecoveryDelay.TotalMilliseconds}; transport_epoch={transportEpoch}; epoch_state={FormatProtocolLogValue(epochState)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; previous_available_credit_chunks={availableCreditChunks}; available_credit_chunks={Math.Max(0, creditCeiling - context.ChunksAcceptedForTransport)}; previous_credit_ceiling_chunk_index={previousCreditCeiling}; credit_ceiling_chunk_index={creditCeiling}; previous_remote_credit_until_chunk_index_exclusive={previousRemoteGrantedUntilExclusive}; remote_credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}; queued_repair_chunk_count={queuedRepairChunkCount}; state_refresh_failure_count={context.V6RegularNknStateRefreshFailureCount}; rebind_generation={context.PullTransportRebindGeneration}");

            stateRefreshRequest = CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
                context,
                now,
                feedbackSilence,
                transportEpoch,
                epochState,
                transportBacklogChunks,
                availableCreditChunks,
                previousCreditCeiling,
                inFlightFrames,
                queuedRepairChunkCount,
                "feedback_stalled_with_stale_credit",
                V6RegularNknStateRefreshStaleCreditPriority);
            return;
        }

        if (ShouldForcePostTunaFallbackTailReconciliationLocked(
                context,
                feedbackSilence,
                transportBacklogChunks,
                availableCreditChunks,
                inFlightFrames,
                queuedRepairChunkCount))
        {
            if (TryGetCurrentCoordinatorProtectedFallbackCheckpointDeliveryLocked(
                    context,
                    out var protectedCommand,
                    out var protectedDeliveryState))
            {
                if (context.V6LastFeedbackStallRecoverySuppressedUtc is null ||
                    now - context.V6LastFeedbackStallRecoverySuppressedUtc.Value >=
                    TimeSpan.FromMilliseconds(
                        V6SenderRequestFeedbackStallRecoverySuppressedLogIntervalMs))
                {
                    context.V6LastFeedbackStallRecoverySuppressedUtc = now;
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_receive_recovery_fallback_checkpoint_tail_reconciliation_decided; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; recovery_operation_authority_id={FormatProtocolLogValue(protectedCommand.Binding.ParentAuthority.AuthorityId.ToString())}; recovery_operation_generation={protectedCommand.Binding.ParentAuthority.OperationGeneration}; effective_checkpoint_request_id={FormatProtocolLogValue(protectedCommand.Binding.EffectiveCheckpointRequestId)}; checkpoint_binding_generation={protectedCommand.Binding.BindingGeneration}; checkpoint_delivery_generation={protectedCommand.DeliveryGeneration}; frame_fingerprint={FormatProtocolLogValue(protectedCommand.Binding.FrameIdentity.Sha256)}; transport_epoch={protectedCommand.Binding.TransportEpoch}; delivery_state={protectedDeliveryState}; status=held; policy=coordinator_peer_proof_terminal; outcome=preserved; decision_reason={(protectedDeliveryState == "delivered" ? "filetransfer_receive_recovery_fallback_checkpoint_peer_proof_required" : "filetransfer_receive_recovery_fallback_checkpoint_delivery_terminal_receipt_required")}");
                }
                return;
            }

            context.V6EpochLivenessDeferralCount++;
            context.V6EpochLivenessDeferralUtc = now;
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_tail_reconciliation";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_tail_reconciliation";

            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_fallback_tail_zero_credit_breaker; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason=tail_reconciliation_zero_credit; deferral_count={context.V6EpochLivenessDeferralCount}; feedback_silence_ms={(long)feedbackSilence.TotalMilliseconds}; recovery_delay_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryDelay.TotalMilliseconds}; stale_credit_recovery_delay_ms={(long)staleCreditRecoveryDelay.TotalMilliseconds}; transport_epoch={transportEpoch}; epoch_state={FormatProtocolLogValue(epochState)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; in_flight_frames={inFlightFrames}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}; queued_repair_chunk_count={queuedRepairChunkCount}; state_refresh_failure_count={context.V6RegularNknStateRefreshFailureCount}; rebind_generation={context.PullTransportRebindGeneration}");
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_fallback_tail_stale_frontier_retired; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentTransferLeg?.LiveRouteEpochId ?? context.CurrentLiveRouteEpoch?.EpochId ?? 0}; transport_epoch={transportEpoch}; retired_remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; reason=tail_reconciliation_zero_credit");

            stateRefreshRequest = CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
                context,
                now,
                feedbackSilence,
                transportEpoch,
                epochState,
                transportBacklogChunks,
                availableCreditChunks,
                creditCeiling,
                inFlightFrames,
                queuedRepairChunkCount,
                "post_tuna_fallback_tail_reconciliation",
                V6RegularNknStateRefreshTailReconciliationPriority);
            return;
        }

        if (availableCreditChunks > 0 || inFlightFrames > 0)
        {
            context.V6EpochLivenessDeferralCount++;
            context.V6EpochLivenessDeferralUtc = now;
            context.V6SenderPumpLastWakeReason = "v4_sparse_runtime_feedback_stalled_deferred";
            if (context.V6LastFeedbackStallRecoverySuppressedUtc is null ||
                now - context.V6LastFeedbackStallRecoverySuppressedUtc.Value >= TimeSpan.FromMilliseconds(V6SenderRequestFeedbackStallRecoverySuppressedLogIntervalMs))
            {
                context.V6LastFeedbackStallRecoverySuppressedUtc = now;
                var reason = availableCreditChunks > 0 ? "normal_credit_available" : "sender_pipeline_in_flight";
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v4_sparse_runtime_sender_feedback_stale_receive_recovery_deferred; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; deferral_count={context.V6EpochLivenessDeferralCount}; feedback_silence_ms={(long)feedbackSilence.TotalMilliseconds}; recovery_delay_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryDelay.TotalMilliseconds}; stale_credit_recovery_delay_ms={(long)staleCreditRecoveryDelay.TotalMilliseconds}; transport_epoch={transportEpoch}; epoch_state={FormatProtocolLogValue(epochState)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; in_flight_frames={inFlightFrames}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}; queued_repair_chunk_count={queuedRepairChunkCount}; rebind_generation={context.PullTransportRebindGeneration}");
            }

            if (feedbackSilence >= staleCreditRecoveryDelay)
            {
                stateRefreshRequest = CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
                    context,
                    now,
                    feedbackSilence,
                    transportEpoch,
                    epochState,
                    transportBacklogChunks,
                    availableCreditChunks,
                    creditCeiling,
                    inFlightFrames,
                    queuedRepairChunkCount,
                    availableCreditChunks > 0 ? "feedback_stalled_with_credit" : "feedback_stalled_with_inflight");
            }

            return;
        }

        stateRefreshRequest = CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
            context,
            now,
            feedbackSilence,
            transportEpoch,
            epochState,
            transportBacklogChunks,
            availableCreditChunks,
            creditCeiling,
            inFlightFrames,
            queuedRepairChunkCount,
            "feedback_stalled_no_credit");
    }

    private static bool ShouldForcePostTunaFallbackStaleInflightRecoveryLocked(
        OutboundTransferContext context,
        TimeSpan feedbackSilence,
        int transportBacklogChunks,
        int availableCreditChunks,
        int inFlightFrames)
        => context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           context.PullPostTunaRecoveryActive &&
           transportBacklogChunks > 0 &&
           availableCreditChunks <= 0 &&
           inFlightFrames > 0 &&
           feedbackSilence >= CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay &&
           context.V6RegularNknStateRefreshFailureCount >= V6PostTunaFallbackStaleInflightRecoveryMinStateRefreshFailures;

    private static bool ShouldForcePostTunaFallbackStaleCreditRecoveryLocked(
        OutboundTransferContext context,
        TimeSpan feedbackSilence,
        int transportBacklogChunks,
        int availableCreditChunks)
        => context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           context.PullPostTunaRecoveryActive &&
           transportBacklogChunks > 0 &&
           availableCreditChunks > 0 &&
           feedbackSilence >= CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay &&
           context.V6RegularNknStateRefreshFailureCount >= V6PostTunaFallbackStaleCreditRecoveryMinStateRefreshFailures;

    private static bool ShouldForcePostTunaFallbackTailReconciliationLocked(
        OutboundTransferContext context,
        TimeSpan feedbackSilence,
        int transportBacklogChunks,
        int availableCreditChunks,
        int inFlightFrames,
        int queuedRepairChunkCount)
        => context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           context.PullPostTunaRecoveryActive &&
           availableCreditChunks <= 0 &&
           (transportBacklogChunks > 0 ||
            inFlightFrames > 0 ||
            queuedRepairChunkCount > 0 ||
            context.PullV4SenderPumpRepairRequests.Count > 0) &&
           feedbackSilence >= CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay &&
           (context.V6RegularNknStateRefreshFailureCount >= Math.Min(
                V6PostTunaFallbackStaleInflightRecoveryMinStateRefreshFailures,
                V6PostTunaFallbackStaleCreditRecoveryMinStateRefreshFailures) ||
            context.V6RegularNknStateRefreshSequence >= V6PostTunaFallbackTailReconciliationMinStateRefreshAttempts);

    private bool TryPrepareOutboundPostTunaFallbackLiveCheckpointTailReconciliationLocked(
        OutboundTransferContext context,
        out FileTransferFrontierRequestFrameV6? stateRefreshRequest)
    {
        stateRefreshRequest = null;
        if (!context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
            !context.PullPostTunaRecoveryActive ||
            context.CurrentTransferLeg is not { State: FileTransferLegState.RecoveryActive, CanSendData: true } leg ||
            !IsCurrentPostTunaFallbackLeg(leg) ||
            !IsV6TransportHandoffBlockingTail(context.V6TransportHandoff) ||
            context.PostTunaFallbackLiveCheckpointStallCount < V6PostTunaFallbackLiveCheckpointTailStallThreshold)
        {
            return false;
        }

        if (TryGetCurrentCoordinatorProtectedFallbackCheckpointDeliveryLocked(
                context,
                out _,
                out _))
        {
            return false;
        }

        var now = DateTimeOffset.UtcNow;
        if (context.V6RegularNknLastStateRefreshRequestedUtc is { } lastRefresh &&
            now - lastRefresh < CurrentV6RegularNknSparseRuntimeStateRefreshCooldown)
        {
            return false;
        }

        var committed = Math.Clamp(leg.ProvenCommittedChunkIndex, 0, Math.Max(0, context.ChunkCount));
        var highestObserved = Math.Max(-1, leg.ProvenHighestObservedChunkIndex);
        if (highestObserved - committed < V6PostTunaFallbackLiveCheckpointTailGapChunks)
        {
            return false;
        }

        var transportEpoch = context.V6TransportEpoch?.EpochId ?? context.V6TransportHandoff?.EpochId ?? leg.TransportEpochId;
        var epochState = context.V6TransportEpoch is null ? "none" : FormatV6TransportEpochState(context.V6TransportEpoch.State);
        var transportBacklogChunks = Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex);
        var creditCeiling = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
        var availableCreditChunks = Math.Max(0, creditCeiling - context.ChunksAcceptedForTransport);
        var inFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames);
        var queuedRepairChunkCount = context.PullV4SenderPumpRepairQueue.Sum(static repair => repair.ChunkIndices.Count);
        if (ShouldSuppressOutboundFallbackCheckpointRequestForDeliveryRecoveryLocked(
                context,
                "post_tuna_fallback_live_checkpoint_tail_reconciliation",
                out var requestSuppressionReason,
                out var requestDeliveryRecoveryAgeMs,
                out var requestDeliveryRecoveryRemainingMs))
        {
            context.PullTransportResumeRequestPending = true;
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_checkpoint_delivery_recovery_pending";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_checkpoint_delivery_recovery_pending";
            LogOutboundFallbackCheckpointRequestSuppressedForDeliveryRecovery(
                context,
                "post_tuna_fallback_live_checkpoint_tail_reconciliation",
                requestSuppressionReason,
                requestDeliveryRecoveryAgeMs,
                requestDeliveryRecoveryRemainingMs);
            return false;
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_fallback_live_checkpoint_tail_stall_detected; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; leg_generation={leg.Generation}; live_route_epoch={leg.LiveRouteEpochId}; transport_epoch={transportEpoch}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; proven_committed_chunk={committed}; proven_highest_observed_chunk={highestObserved}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; stall_count={context.PostTunaFallbackLiveCheckpointStallCount}; required_stall_count={V6PostTunaFallbackLiveCheckpointTailStallThreshold}; gap_chunks={highestObserved - committed}; required_gap_chunks={V6PostTunaFallbackLiveCheckpointTailGapChunks}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; in_flight_frames={inFlightFrames}; queued_repair_chunk_count={queuedRepairChunkCount}; reason=live_checkpoint_tail_stalled");
        stateRefreshRequest = CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
            context,
            now,
            TimeSpan.Zero,
            transportEpoch,
            epochState,
            transportBacklogChunks,
            availableCreditChunks,
            creditCeiling,
            inFlightFrames,
            queuedRepairChunkCount,
            "post_tuna_fallback_live_checkpoint_tail_stalled",
            V6RegularNknStateRefreshTailReconciliationPriority);
        context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_live_checkpoint_tail_reconciliation";
        context.V6SenderPumpLastWakeReason = "post_tuna_fallback_live_checkpoint_tail_reconciliation";
        return true;
    }

    private FileTransferFrontierRequestFrameV6 CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
        OutboundTransferContext context,
        DateTimeOffset now,
        TimeSpan feedbackSilence,
        long transportEpoch,
        string epochState,
        int transportBacklogChunks,
        int availableCreditChunks,
        int creditCeiling,
        int inFlightFrames,
        int queuedRepairChunkCount,
        string refreshReason,
        string priority = V6RegularNknStateRefreshPriority)
    {
        context.V6RegularNknLastStateRefreshRequestedUtc = now;
        context.V6EpochLivenessDeferralCount++;
        context.V6EpochLivenessDeferralUtc = now;
        context.V6SenderPumpLastWakeReason = "v4_sparse_runtime_state_refresh_requested";
        var sequence = ++context.V6RegularNknStateRefreshSequence;
        var tailReconciliationRequested = string.Equals(
            priority,
            V6RegularNknStateRefreshTailReconciliationPriority,
            StringComparison.Ordinal);
        var currentFallbackLeg = IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg)
            ? context.CurrentTransferLeg
            : null;
        var tailReconciliationCanReuseCurrentOwner =
            tailReconciliationRequested &&
            currentFallbackLeg is not null &&
            (string.IsNullOrWhiteSpace(currentFallbackLeg.CheckpointRequestId) ||
             string.Equals(
                 currentFallbackLeg.CheckpointPriority,
                 V6RegularNknStateRefreshTailReconciliationPriority,
                 StringComparison.Ordinal));
        if (currentFallbackLeg is not null && transportEpoch > 0)
        {
            if (tailReconciliationCanReuseCurrentOwner && currentFallbackLeg.TransportEpochId > 0)
            {
                transportEpoch = currentFallbackLeg.TransportEpochId;
            }
            else
            {
                AdoptOutboundFallbackLegTransportEpochLocked(context, transportEpoch, refreshReason);
                currentFallbackLeg = IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg)
                    ? context.CurrentTransferLeg
                    : null;
            }
        }

        var tailReconciliationNeedsFreshLeg =
            tailReconciliationRequested &&
            currentFallbackLeg is not null &&
            !string.IsNullOrWhiteSpace(currentFallbackLeg.CheckpointRequestId) &&
            !string.Equals(
                currentFallbackLeg.CheckpointPriority,
                V6RegularNknStateRefreshTailReconciliationPriority,
                StringComparison.Ordinal);
        if (tailReconciliationNeedsFreshLeg)
        {
            StartOutboundPostTunaRecoveryCoreLocked(
                context,
                "tail_reconciliation_forced",
                forceNewGeneration: true);
            currentFallbackLeg = IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg)
                ? context.CurrentTransferLeg
                : null;
            transportEpoch = ResolveOutboundFallbackCurrentTransportEpochLocked(context, transportEpoch);
            if (currentFallbackLeg is not null && transportEpoch > 0)
            {
                AdoptOutboundFallbackLegTransportEpochLocked(context, transportEpoch, refreshReason);
                currentFallbackLeg = IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg)
                    ? context.CurrentTransferLeg
                    : null;
            }
        }

        var reusePendingFallbackCheckpoint =
            currentFallbackLeg is not null &&
            !string.IsNullOrWhiteSpace(currentFallbackLeg.CheckpointRequestId);
        var requestId = reusePendingFallbackCheckpoint
            ? currentFallbackLeg!.CheckpointRequestId!
            : $"v6-regular-nkn-state-refresh:{sequence}";
        var requestPriority = reusePendingFallbackCheckpoint
            ? currentFallbackLeg!.CheckpointPriority ?? priority
            : priority;
        var refreshHintChunkIndex = context.ChunkCount > 0
            ? Math.Min(Math.Max(0, context.RemoteNextExpectedChunkIndex), context.ChunkCount - 1)
            : 0;
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v6_regular_nkn_state_refresh_requested; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(refreshReason)}; request_sequence={sequence}; request_id={FormatProtocolLogValue(requestId)}; priority={FormatProtocolLogValue(requestPriority)}; requested_priority={FormatProtocolLogValue(priority)}; reused_pending_checkpoint={(reusePendingFallbackCheckpoint ? 1 : 0)}; feedback_silence_ms={(long)feedbackSilence.TotalMilliseconds}; refresh_cooldown_ms={(long)CurrentV6RegularNknSparseRuntimeStateRefreshCooldown.TotalMilliseconds}; stale_credit_recovery_delay_ms={(long)CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay.TotalMilliseconds}; transport_epoch={transportEpoch}; epoch_state={FormatProtocolLogValue(epochState)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; refresh_hint_chunk_index={refreshHintChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; in_flight_frames={inFlightFrames}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}; queued_repair_chunk_count={queuedRepairChunkCount}; rebind_generation={context.PullTransportRebindGeneration}");
        if (string.Equals(requestPriority, V6RegularNknStateRefreshTailReconciliationPriority, StringComparison.Ordinal))
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_fallback_tail_reconciliation_requested; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_sequence={sequence}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; live_route_epoch={context.CurrentTransferLeg?.LiveRouteEpochId ?? context.CurrentLiveRouteEpoch?.EpochId ?? 0}; transport_epoch={transportEpoch}; checkpoint_request_id={FormatProtocolLogValue(requestId)}; reused_pending_checkpoint={(reusePendingFallbackCheckpoint ? 1 : 0)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; refresh_hint_chunk_index={refreshHintChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; in_flight_frames={inFlightFrames}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}; queued_repair_chunk_count={queuedRepairChunkCount}; reason={FormatProtocolLogValue(refreshReason)}");
        }

        var request = new FileTransferFrontierRequestFrameV6
        {
            SessionId = context.SessionId,
            TransferId = context.TransferId,
            TransportEpoch = transportEpoch,
            RepairRequestId = requestId,
            MissingRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = refreshHintChunkIndex,
                    ChunkCount = 1,
                },
            ],
            Priority = requestPriority,
            RecoveryMode = V6RegularNknStateRefreshRecoveryMode,
        };
        return request;
    }

    private static void TryPrepareOutboundPrimaryRegularNknBulkV6CheckpointSyncLocked(
        OutboundTransferContext context,
        TimeSpan feedbackSilence,
        out FileTransferFrontierRequestFrameV6? checkpointSyncRequest)
    {
        checkpointSyncRequest = null;
        var now = DateTimeOffset.UtcNow;
        if (feedbackSilence < CurrentV6SenderRequestFeedbackStallRecoveryDelay ||
            context.V6RegularNknLastCheckpointSyncRequestedUtc is { } lastRefresh &&
            now - lastRefresh < CurrentV6RegularNknSparseRuntimeStateRefreshCooldown)
        {
            return;
        }

        var creditCeiling = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
        var availableCreditChunks = Math.Max(0, creditCeiling - context.ChunksAcceptedForTransport);
        var transportBacklogChunks = Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex);
        var inFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames);
        if (availableCreditChunks > 0 || inFlightFrames > 0)
        {
            context.V6EpochLivenessDeferralCount++;
            context.V6EpochLivenessDeferralUtc = now;
            context.V6SenderPumpLastWakeReason = "primary_regular_nkn_bulk_v6_feedback_stalled_deferred";
            if (context.V6LastFeedbackStallRecoverySuppressedUtc is null ||
                now - context.V6LastFeedbackStallRecoverySuppressedUtc.Value >= TimeSpan.FromMilliseconds(V6SenderRequestFeedbackStallRecoverySuppressedLogIntervalMs))
            {
                context.V6LastFeedbackStallRecoverySuppressedUtc = now;
                var reason = availableCreditChunks > 0 ? "checkpoint_credit_available" : "checkpoint_sender_pipeline_in_flight";
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_recovery_deferred; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; deferral_count={context.V6EpochLivenessDeferralCount}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; stale_credit_recovery_delay_ms={(long)CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay.TotalMilliseconds}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; in_flight_frames={inFlightFrames}; rebind_generation={context.PullTransportRebindGeneration}");
            }

            if (feedbackSilence < CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay)
            {
                return;
            }
        }

        checkpointSyncRequest = CreateOutboundPrimaryRegularNknBulkV6CheckpointSyncRequestLocked(
            context,
            now,
            feedbackSilence,
            transportBacklogChunks,
            availableCreditChunks,
            creditCeiling,
            inFlightFrames,
            availableCreditChunks > 0
                ? "feedback_stalled_with_credit"
                : inFlightFrames > 0
                    ? "feedback_stalled_with_inflight"
                    : "feedback_stalled_no_credit");
    }

    private static FileTransferFrontierRequestFrameV6 CreateOutboundPrimaryRegularNknBulkV6CheckpointSyncRequestLocked(
        OutboundTransferContext context,
        DateTimeOffset now,
        TimeSpan feedbackSilence,
        int transportBacklogChunks,
        int availableCreditChunks,
        int creditCeiling,
        int inFlightFrames,
        string reason)
    {
        context.V6RegularNknLastCheckpointSyncRequestedUtc = now;
        context.V6EpochLivenessDeferralCount++;
        context.V6EpochLivenessDeferralUtc = now;
        context.V6SenderPumpLastWakeReason = "primary_regular_nkn_bulk_v6_checkpoint_sync_requested";
        var sequence = ++context.V6RegularNknCheckpointSyncSequence;
        var checkpointHintChunkIndex = context.ChunkCount > 0
            ? Math.Min(Math.Max(0, context.RemoteNextExpectedChunkIndex), context.ChunkCount - 1)
            : 0;
        var request = new FileTransferFrontierRequestFrameV6
        {
            SessionId = context.SessionId,
            TransferId = context.TransferId,
            TransportEpoch = context.PullTransportRebindGeneration,
            RepairRequestId = $"{V6RegularNknCheckpointSyncRequestPrefix}{sequence}",
            MissingRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = checkpointHintChunkIndex,
                    ChunkCount = 1,
                },
            ],
            Priority = V6RegularNknCheckpointSyncPriority,
            RecoveryMode = V6RegularNknCheckpointSyncRecoveryMode,
        };
        LogPrimaryRegularNknBulkV6CheckpointRequestPrepared(
            context,
            request,
            reason,
            feedbackSilence,
            transportBacklogChunks,
            availableCreditChunks,
            inFlightFrames);
        return request;
    }

    private void QueueOutboundPrimaryRegularNknBulkV6CheckpointSync(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request)
    {
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                !IsPrimaryRegularNknBulkV6ContextLocked(context))
            {
                return;
            }

            if (context.V6RegularNknCheckpointSyncSendInFlight > 0)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_request_send_skipped; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; reason=send_in_flight; in_flight={context.V6RegularNknCheckpointSyncSendInFlight}");
                return;
            }

            context.V6RegularNknCheckpointSyncSendInFlight++;
        }

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_request_send_queued; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; timeout_ms={V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs}");
        _ = SendOutboundPrimaryRegularNknBulkV6CheckpointSyncAsync(context, dataSession, request);
    }

    private async Task SendOutboundPrimaryRegularNknBulkV6CheckpointSyncAsync(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request)
    {
        var signalSenderPumpAfterSend = false;
        try
        {
            using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(context.LifetimeCts.Token);
            timeoutCts.CancelAfter(TimeSpan.FromMilliseconds(V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs));
            await dataSession.SendAsync(request, timeoutCts.Token).ConfigureAwait(false);
            LogPullBinaryFrameSent(context.TransferId, context.SessionId, request, payloadBytes: 0);
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_request_sent; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; transport_epoch={request.TransportEpoch}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}");
        }
        catch (OperationCanceledException) when (!context.LifetimeCts.IsCancellationRequested)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_request_send_timeout; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; timeout_ms={V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs}");
            RequestOutboundPrimaryRegularNknBulkV6CheckpointReceiveRecovery(
                context,
                request,
                "checkpoint_sync_send_timeout");
        }
        catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_request_send_suppressed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; reason=lifetime_cancelled");
        }
        catch (Exception ex)
        {
            var terminal = false;
            lock (gate)
            {
                terminal = !ReferenceEquals(outboundTransfer, context) || context.IsTerminal;
            }

            var eventName = terminal
                ? "filetransfer_primary_regular_nkn_bulk_v6_checkpoint_request_send_suppressed"
                : "filetransfer_primary_regular_nkn_bulk_v6_checkpoint_request_send_failed";
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event={eventName}; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; reason={FormatProtocolLogValue(ex.Message)}; terminal={(terminal ? 1 : 0)}");
            if (!terminal)
            {
                RequestOutboundPrimaryRegularNknBulkV6CheckpointReceiveRecovery(
                    context,
                    request,
                    "checkpoint_sync_send_failed");
            }
        }
        finally
        {
            lock (gate)
            {
                if (ReferenceEquals(outboundTransfer, context) &&
                    context.V6RegularNknCheckpointSyncSendInFlight > 0)
                {
                    context.V6RegularNknCheckpointSyncSendInFlight--;
                    signalSenderPumpAfterSend =
                        context.V6RegularNknCheckpointSyncSendInFlight == 0 &&
                        string.Equals(
                            context.SparseSenderPumpLastWakeReason,
                            "primary_regular_nkn_bulk_v6_checkpoint_recovery_deferred",
                            StringComparison.Ordinal);
                }
            }

            if (signalSenderPumpAfterSend)
            {
                SignalOutboundSparseSenderPump(context);
            }
        }
    }

    private void RequestOutboundPrimaryRegularNknBulkV6CheckpointReceiveRecovery(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason)
    {
        FileTransferReceiveRecoveryRequest? recoveryRequest = null;
        var signalSenderPump = false;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                !IsPrimaryRegularNknBulkV6ContextLocked(context))
            {
                return;
            }

            var now = DateTimeOffset.UtcNow;
            if (context.V6LastReceiveRecoveryRequestedUtc is { } lastRecovery &&
                now - lastRecovery < CurrentV6SenderRequestFeedbackStallRecoveryCooldown)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_receive_recovery_suppressed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; suppression_reason=recovery_cooldown; cooldown_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryCooldown.TotalMilliseconds}; last_recovery_age_ms={(long)Math.Max(0, (now - lastRecovery).TotalMilliseconds)}; failure_count={context.V6RegularNknCheckpointSyncFailureCount}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");
                return;
            }

            context.V6RegularNknCheckpointSyncFailureCount++;
            context.V6EpochLivenessDeferralCount++;
            context.V6EpochLivenessDeferralUtc = now;
            context.PullTransportResumeRequestPending = true;

            var feedbackSilence = context.PullV4LastPeerFrameReceivedUtc is { } lastPeerFrame
                ? now - lastPeerFrame
                : TimeSpan.Zero;
            var transportBacklogChunks = Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex);
            var creditCeiling = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
            var availableCreditChunks = Math.Max(0, creditCeiling - context.ChunksAcceptedForTransport);
            if (context.BridgeRecoveryPolicy == FileTransferBridgeRecoveryPolicy.PrimaryRegularNknQuietRecovery &&
                context.V6RegularNknCheckpointSyncFailureCount < V6RegularNknCheckpointSyncFailuresBeforeBridgeRecovery)
            {
                context.SparseSenderPumpLastWakeReason = "primary_regular_nkn_bulk_v6_checkpoint_recovery_deferred";
                signalSenderPump = true;
                LogPrimaryRegularNknBulkV6FrontierFeedbackFailedRecoverable(
                    context,
                    request,
                    reason,
                    "defer_bridge_recovery",
                    context.V6RegularNknCheckpointSyncFailureCount,
                    feedbackSilence,
                    transportBacklogChunks,
                    availableCreditChunks);
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_receive_recovery_suppressed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; suppression_reason=quiet_policy_first_failure; failure_count={context.V6RegularNknCheckpointSyncFailureCount}; required_failure_count={V6RegularNknCheckpointSyncFailuresBeforeBridgeRecovery}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");
            }
            else
            {
                context.V6LastReceiveRecoveryRequestedUtc = now;
                context.SparseSenderPumpLastWakeReason = "primary_regular_nkn_bulk_v6_checkpoint_receive_recovery";
                LogPrimaryRegularNknBulkV6FrontierFeedbackFailedRecoverable(
                    context,
                    request,
                    reason,
                    "request_bridge_recovery",
                    context.V6RegularNknCheckpointSyncFailureCount,
                    feedbackSilence,
                    transportBacklogChunks,
                    availableCreditChunks);
                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_primary_regular_nkn_bulk_v6_checkpoint_receive_recovery_requested; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; failure_count={context.V6RegularNknCheckpointSyncFailureCount}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");

                recoveryRequest = AttachFallbackLegAuthority(
                    context,
                    new FileTransferReceiveRecoveryRequest(
                        context.SessionId,
                        context.TransferId,
                        FileTransferDirection.Outbound,
                        "primary_regular_nkn_bulk_v6_checkpoint_sync_failed"),
                    "primary_regular_nkn_bulk_v6_checkpoint_sync_failed",
                    request.RepairRequestId,
                    request.TransportEpoch);
            }
        }

        if (signalSenderPump)
        {
            SignalOutboundSparseSenderPump(context);
        }

        if (recoveryRequest is not null)
        {
            TryRequestFileTransferReceiveRecovery(recoveryRequest);
        }
    }

    private static bool IsV6RegularNknStateRefreshRequest(FileTransferFrontierRequestFrameV6 request)
        => string.Equals(request.RecoveryMode, V6RegularNknStateRefreshRecoveryMode, StringComparison.Ordinal) ||
           (request.RepairRequestId?.StartsWith("v6-regular-nkn-state-refresh:", StringComparison.Ordinal) ?? false);

    private static FileTransferFrontierRequestFrameV6 NormalizeOutboundPostTunaFallbackStateRefreshRequestForCurrentLegLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string source)
    {
        if (!IsV6RegularNknStateRefreshRequest(request) ||
            !context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
            !context.PullPostTunaRecoveryActive ||
            !IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg))
        {
            return request;
        }

        var leg = context.CurrentTransferLeg!;
        var expectedTransportEpoch = leg.TransportEpochId > 0
            ? leg.TransportEpochId
            : request.TransportEpoch;
        var transportEpochChanged = expectedTransportEpoch > 0 && request.TransportEpoch != expectedTransportEpoch;

        if (!transportEpochChanged)
        {
            return request;
        }

        var normalized = request with
        {
            TransportEpoch = transportEpochChanged ? expectedTransportEpoch : request.TransportEpoch,
        };

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_clean_fallback_state_refresh_request_restamped; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; leg_generation={leg.Generation}; live_route_epoch={leg.LiveRouteEpochId}; previous_transport_epoch={request.TransportEpoch}; transport_epoch={normalized.TransportEpoch}; previous_checkpoint_request_id={FormatProtocolLogValue(request.RepairRequestId ?? "(none)")}; checkpoint_request_id={FormatProtocolLogValue(normalized.RepairRequestId ?? "(none)")}; priority={FormatProtocolLogValue(normalized.Priority ?? "(none)")}; reason=current_clean_fallback_leg_authority");
        return normalized;
    }

    private void QueueOutboundV4SparseRuntimeStateRefresh(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request,
        string source = "state_refresh_send_queued")
        => QueueOutboundV4SparseRuntimeStateRefreshIfCurrent(
            context,
            dataSession,
            request,
            source,
            requiredReceiveInstall: null,
            requiredReceiveRuntimeOwner: null,
            requiredReceiveDataSession: null,
            requiredReceiveDataSessionGeneration: 0);

    private void QueueOutboundV4SparseRuntimeStateRefreshIfCurrent(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request,
        string source,
        OutboundSparsePumpInstall? requiredReceiveInstall,
        RuntimeOwnerToken? requiredReceiveRuntimeOwner,
        IFileTransferDataSession? requiredReceiveDataSession,
        long requiredReceiveDataSessionGeneration,
        FileTransferReceiveRecoveryFallbackCheckpointResumeReservation?
            resumeReservation = null)
    {
        TryQueueOutboundV4SparseRuntimeStateRefreshIfCurrentCore(
            context,
            dataSession,
            request,
            source,
            requiredReceiveInstall,
            requiredReceiveRuntimeOwner,
            requiredReceiveDataSession,
            requiredReceiveDataSessionGeneration,
            resumeReservation,
            routeTransitionFallbackCheckpointDispatch: null);
    }

    private bool TryDispatchOutboundFileTransferRouteTransitionFallbackCheckpoint(
        OutboundTransferContext context,
        OutboundFileTransferRouteTransitionFallbackCheckpointDispatchBinding
            dispatch)
        => TryQueueOutboundV4SparseRuntimeStateRefreshIfCurrentCore(
            context,
            dispatch.DataSession,
            request: null,
            source: "route_transition_fallback_checkpoint_dispatch",
            requiredReceiveInstall: null,
            requiredReceiveRuntimeOwner: null,
            requiredReceiveDataSession: null,
            requiredReceiveDataSessionGeneration: 0,
            resumeReservation: null,
            routeTransitionFallbackCheckpointDispatch: dispatch);

    private bool TryQueueOutboundV4SparseRuntimeStateRefreshIfCurrentCore(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6? request,
        string source,
        OutboundSparsePumpInstall? requiredReceiveInstall,
        RuntimeOwnerToken? requiredReceiveRuntimeOwner,
        IFileTransferDataSession? requiredReceiveDataSession,
        long requiredReceiveDataSessionGeneration,
        FileTransferReceiveRecoveryFallbackCheckpointResumeReservation?
            resumeReservation,
        OutboundFileTransferRouteTransitionFallbackCheckpointDispatchBinding?
            routeTransitionFallbackCheckpointDispatch)
    {
        FileTransferReceiveRecoveryRequest? recoveryRequest = null;
        OutboundSparsePumpInstall? retainedReplayInstall = null;
        IFileTransferDataSession? retainedReplayDataSession = null;
        long sendGeneration;
        var reusedPendingCheckpointForSend = false;
        var deferredUntilResume = false;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                (requiredReceiveDataSession is not null &&
                 !ReferenceEquals(dataSession, requiredReceiveDataSession)) ||
                (resumeReservation is null &&
                 requiredReceiveDataSession is not null &&
                 !IsOutboundSparseReceiveResultCurrentLocked(
                     context,
                     requiredReceiveInstall,
                     requiredReceiveRuntimeOwner,
                     requiredReceiveDataSession,
                     requiredReceiveDataSessionGeneration,
                     out _)))
            {
                return false;
            }

            if (routeTransitionFallbackCheckpointDispatch is { } dispatch)
            {
                if (!TryValidateOutboundFileTransferRouteTransitionFallbackCheckpointDispatchLocked(
                        context,
                        dispatch,
                        out var dispatchRejectionReason))
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_route_transition_fallback_checkpoint_dispatch_ignored; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; authority_id={FormatProtocolLogValue(dispatch.Authority.AuthorityId.ToString())}; transition_generation={dispatch.Authority.TransitionGeneration}; checkpoint_request_id={FormatProtocolLogValue(dispatch.CheckpointLease.CheckpointRequestId)}; checkpoint_generation={dispatch.CheckpointLease.CheckpointGeneration}; checkpoint_lease_generation={dispatch.CheckpointLease.LeaseGeneration}; decision_reason={FormatProtocolLogValue(dispatchRejectionReason)}; authority_effect=none");
                    return false;
                }

                if (context.V6RegularNknStateRefreshSendInFlight > 0 &&
                    string.Equals(
                        context.V6RegularNknStateRefreshActiveRequestId,
                        dispatch.CheckpointLease.CheckpointRequestId,
                        StringComparison.Ordinal))
                {
                    return true;
                }

                var committed = Math.Clamp(
                    context.RemoteNextExpectedChunkIndex,
                    0,
                    Math.Max(0, context.ChunkCount));
                request = CreateOutboundV4SparseRuntimeStateRefreshRequestLocked(
                    context,
                    DateTimeOffset.UtcNow,
                    TimeSpan.Zero,
                    dispatch.CheckpointLease.TransportEpoch,
                    context.V6TransportEpoch is null
                        ? "none"
                        : FormatV6TransportEpochState(
                            context.V6TransportEpoch.State),
                    transportBacklogChunks: 0,
                    availableCreditChunks: 0,
                    creditCeiling: committed,
                    inFlightFrames: 0,
                    queuedRepairChunkCount: 0,
                    refreshReason:
                        "filetransfer_route_transition_fallback_checkpoint_dispatch",
                    priority: V6RegularNknStateRefreshPriority);
                context.SparseSenderPumpLastWakeReason =
                    "post_tuna_fallback_checkpoint_requested";
                context.V6SenderPumpLastWakeReason =
                    "post_tuna_fallback_checkpoint_requested";
            }

            if (request is null)
            {
                return false;
            }

            request = NormalizeOutboundPostTunaFallbackStateRefreshRequestForCurrentLegLocked(
                context,
                request,
                "queue_state_refresh");
            request = BindOutboundPostTunaFallbackStateRefreshCorrelationToReceiveRecoveryLocked(
                context,
                request);

            if (ShouldSuppressOutboundFallbackCheckpointSendForDeliveryRecoveryLocked(
                    context,
                    request,
                    out var suppressionReason,
                    out var deliveryRecoveryAgeMs,
                    out var deliveryRecoveryRemainingMs))
            {
                context.PullTransportResumeRequestPending = true;
                context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_checkpoint_delivery_recovery_pending";
                context.V6SenderPumpLastWakeReason = "post_tuna_fallback_checkpoint_delivery_recovery_pending";
                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_fallback_checkpoint_send_suppressed_until_recovery; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; request_id={FormatProtocolLogValue(request.RepairRequestId ?? "(none)")}; priority={FormatProtocolLogValue(request.Priority ?? "(none)")}; transport_epoch={request.TransportEpoch}; suppression_reason={FormatProtocolLogValue(suppressionReason)}; pending_request_id={FormatProtocolLogValue(context.V6RegularNknFallbackCheckpointDeliveryRecoveryRequestId ?? "(none)")}; pending_reason={FormatProtocolLogValue(context.V6RegularNknFallbackCheckpointDeliveryRecoveryReason ?? "(none)")}; delivery_recovery_age_ms={deliveryRecoveryAgeMs}; delivery_recovery_remaining_ms={deliveryRecoveryRemainingMs}; recovery_cooldown_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryCooldown.TotalMilliseconds}; failure_count={context.V6RegularNknStateRefreshFailureCount}; rebind_generation={context.PullTransportRebindGeneration}");
                var pendingRetainedReplayMatchesRequest =
                    TryCapturePendingOutboundFileTransferRouteTransitionRetainedReplayLocked(
                        context,
                        out _,
                        out var pendingReplayDataSession,
                        out var pendingReplayDispatch) &&
                    ReferenceEquals(pendingReplayDataSession, dataSession) &&
                    string.Equals(
                        pendingReplayDispatch.CheckpointLease.CheckpointRequestId,
                        request.RepairRequestId,
                        StringComparison.Ordinal);
                if (routeTransitionFallbackCheckpointDispatch is not null ||
                    pendingRetainedReplayMatchesRequest)
                {
                    DeferOutboundPostTunaFallbackStateRefreshAfterRecoveryLocked(
                        context,
                        request,
                        "route_transition_fallback_checkpoint_delivery_recovery_pending");
                }

                return false;
            }

            if (ShouldCoalesceOutboundFallbackCheckpointStateRefreshSendLocked(
                    context,
                    request,
                    source))
            {
                return false;
            }

            if (context.V6RegularNknStateRefreshSendInFlight > 0)
            {
                if (TryRetireOutboundPostTunaFallbackStaleStateRefreshSendLocked(
                        context,
                        request,
                        DateTimeOffset.UtcNow))
                {
                    recoveryRequest = AttachFallbackLegAuthority(
                        context,
                        new FileTransferReceiveRecoveryRequest(
                            context.SessionId,
                            context.TransferId,
                            FileTransferDirection.Outbound,
                            "post_tuna_fallback_stale_state_refresh_send_retired"),
                        "post_tuna_fallback_stale_state_refresh_send_retired",
                        request.RepairRequestId,
                        request.TransportEpoch);
                    DeferOutboundPostTunaFallbackStateRefreshAfterRecoveryLocked(
                        context,
                        request,
                        "post_tuna_fallback_stale_state_refresh_send_retired");
                    deferredUntilResume = true;
                }
                else
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v6_regular_nkn_state_refresh_send_skipped; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; reason=send_in_flight; in_flight={context.V6RegularNknStateRefreshSendInFlight}; active_generation={context.V6RegularNknStateRefreshActiveSendGeneration}; active_request_id={FormatProtocolLogValue(context.V6RegularNknStateRefreshActiveRequestId ?? "(none)")}");
                    return false;
                }
            }

            if (deferredUntilResume)
            {
                sendGeneration = 0;
            }
            else
            {
                reusedPendingCheckpointForSend =
                    IsCurrentPostTunaFallbackLegCheckpointPending(context.CurrentTransferLeg) &&
                    !string.IsNullOrWhiteSpace(context.CurrentTransferLeg!.CheckpointRequestId) &&
                    !string.IsNullOrWhiteSpace(request.RepairRequestId) &&
                    string.Equals(context.CurrentTransferLeg.CheckpointRequestId, request.RepairRequestId, StringComparison.Ordinal);

                if (!MarkOutboundFallbackCheckpointRequestedLocked(
                        context,
                        request,
                        source))
                {
                    return false;
                }

                sendGeneration = ++context.V6RegularNknStateRefreshSendGeneration;
                context.V6RegularNknStateRefreshSendInFlight = 1;
                context.V6RegularNknStateRefreshActiveSendGeneration = sendGeneration;
                context.V6RegularNknStateRefreshActiveRequestId = request.RepairRequestId;
                context.V6RegularNknStateRefreshActivePriority = request.Priority;
                context.V6RegularNknStateRefreshActiveStartedUtc = DateTimeOffset.UtcNow;
                context.V6RegularNknStateRefreshActiveReusedPendingCheckpoint = reusedPendingCheckpointForSend;
                if (TryCapturePendingOutboundFileTransferRouteTransitionRetainedReplayLocked(
                        context,
                        out var pendingReplayInstall,
                        out var pendingReplayDataSession,
                        out var pendingReplayDispatch) &&
                    ReferenceEquals(pendingReplayDataSession, dataSession) &&
                    string.Equals(
                        request.RepairRequestId,
                        pendingReplayDispatch.CheckpointLease
                            .CheckpointRequestId,
                        StringComparison.Ordinal) &&
                    string.Equals(
                        context.V6RegularNknStateRefreshActiveRequestId,
                        pendingReplayDispatch.CheckpointLease
                            .CheckpointRequestId,
                        StringComparison.Ordinal))
                {
                    retainedReplayInstall = pendingReplayInstall;
                    retainedReplayDataSession = pendingReplayDataSession;
                }
            }
        }

        if (deferredUntilResume)
        {
            if (recoveryRequest is not null)
            {
                if (requiredReceiveInstall is not null)
                {
                    TryRequestFileTransferReceiveRecoveryIfCurrent(
                        recoveryRequest,
                        requiredReceiveInstall,
                        requiredReceiveDataSession);
                }
                else
                {
                    TryRequestFileTransferReceiveRecovery(recoveryRequest);
                }
            }

            return false;
        }

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v6_regular_nkn_state_refresh_send_queued; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; generation={sendGeneration}; priority={FormatProtocolLogValue(request.Priority)}; timeout_ms={V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs}; source={FormatProtocolLogValue(source)}; reused_pending_checkpoint={(reusedPendingCheckpointForSend ? 1 : 0)}");
        _ = requiredReceiveInstall is not null && requiredReceiveDataSession is not null
            ? SendOutboundV4SparseRuntimeStateRefreshIfCurrentAsync(
                context,
                dataSession,
                request,
                sendGeneration,
                requiredReceiveInstall,
                requiredReceiveDataSession,
                resumeReservation)
            : SendOutboundV4SparseRuntimeStateRefreshAsync(
                context,
                dataSession,
                request,
                sendGeneration);
        if (retainedReplayInstall is { } replayInstall &&
            retainedReplayDataSession is { } replayDataSession)
        {
            _ = TryApplyOutboundCommittedFileTransferRouteTransitionRetainedFrameCoreAsync(
                context,
                replayInstall,
                replayDataSession,
                request.RepairRequestId);
        }
        if (recoveryRequest is not null)
        {
            if (requiredReceiveInstall is not null)
            {
                TryRequestFileTransferReceiveRecoveryIfCurrent(
                    recoveryRequest,
                    requiredReceiveInstall,
                    requiredReceiveDataSession);
            }
            else
            {
                TryRequestFileTransferReceiveRecovery(recoveryRequest);
            }
        }

        return true;
    }

    private bool TryDeferCurrentPostTunaFallbackReceiveRecoveryPayloadHoldIfCurrent(
        OutboundTransferContext context,
        string source,
        Exception exception,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession? requiredDataSession)
    {
        var unavailable = FindDataSessionSubmissionUnavailableException(exception);
        if ((unavailable is null || !unavailable.RecoveryBarrierActive) &&
            exception is not OperationCanceledException &&
            !IsTransportDisconnected(exception))
        {
            return false;
        }

        OutboundPostTunaFallbackReceiveRecoveryPayloadHold hold;
        FileTransferReceiveRecoveryOperation operation;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.LifetimeCts.IsCancellationRequested ||
                requiredInstall is null ||
                requiredDataSession is null ||
                context.CurrentPostTunaFallbackReceiveRecoveryPayloadHold is not { } current ||
                current.PumpInstall != requiredInstall ||
                !ReferenceEquals(current.DataSession, requiredDataSession) ||
                current.ImmutableDeadlineUtc <= DateTimeOffset.UtcNow ||
                !TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                    context,
                    out operation,
                    out _) ||
                operation.Authority != current.Authority ||
                !IsPostTunaFallbackReceiveRecoveryPayloadScopeCurrentLocked(
                    context,
                    operation,
                    requiredInstall,
                    requiredDataSession))
            {
                return false;
            }

            hold = current;
            context.SparseSenderPumpLastWakeReason =
                $"receive_recovery_execution_payload_hold:{operation.Authority.OperationGeneration}:post_tuna_fallback";
            context.V6SenderPumpLastWakeReason =
                "post_tuna_fallback_recovery_submission_failure_deferred";
            context.StatusMessage = "Waiting for network recovery.";
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_recovery_submission_supervisor_deferred; decision_status=Accepted; decision_reason=exact_receive_recovery_payload_hold_current; authority_effect=none; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; source={FormatProtocolLogValue(source)}; hold_generation={hold.HoldGeneration}; receive_recovery_operation_authority_id={FormatProtocolLogValue(operation.Authority.AuthorityId.ToString())}; receive_recovery_operation_generation={operation.Authority.OperationGeneration}; pump_install_generation={requiredInstall.InstallGeneration}; immutable_deadline_utc_ms={hold.ImmutableDeadlineUtc.ToUnixTimeMilliseconds()}; typed_rejection_reason={FormatProtocolLogValue(unavailable?.Reason.ToString() ?? "(none)")}; rejection_stage={FormatProtocolLogValue(unavailable?.Stage ?? "(none)")}; rejection_channel={FormatProtocolLogValue(unavailable?.Channel ?? "(none)")}; route={FormatProtocolLogValue(operation.Authority.Observation.RouteToken)}; protocol_version={operation.Authority.Observation.ProtocolVersion}; live_route_epoch={operation.Authority.Observation.LiveRouteEpoch}; runtime_generation={operation.Authority.Observation.RuntimeOwner.RuntimeGeneration}; route_publication_generation={operation.Authority.Observation.RoutePublication.PublicationGeneration}; terminal_generation={operation.Authority.Observation.TerminalGeneration}; leg_generation={operation.Authority.Observation.LegGeneration}; transport_epoch={operation.Authority.Observation.TransportEpoch}; bridge_recovery_generation={operation.Authority.Observation.BridgeRecoveryGeneration}; checkpoint_request_id={FormatProtocolLogValue(operation.Authority.ExecutionCommand.CheckpointRequestId ?? "(none)")}; data_session_generation={operation.Authority.Observation.DataSessionGeneration}");
        return true;
    }

    private static bool ShouldCoalesceOutboundFallbackCheckpointStateRefreshSendLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string source)
    {
        var leg = context.CurrentTransferLeg;
        if (!IsCurrentPostTunaFallbackLegCheckpointPending(leg) ||
            string.IsNullOrWhiteSpace(leg!.CheckpointRequestId) ||
            string.IsNullOrWhiteSpace(request.RepairRequestId))
        {
            return false;
        }

        if (leg.TransportEpochId > 0 &&
            request.TransportEpoch > 0 &&
            request.TransportEpoch != leg.TransportEpochId)
        {
            return false;
        }

        var sameCheckpointOwner = string.Equals(leg.CheckpointRequestId, request.RepairRequestId, StringComparison.Ordinal);
        var tailReconciliationOwner =
            sameCheckpointOwner &&
            (string.Equals(leg.CheckpointPriority, V6RegularNknStateRefreshTailReconciliationPriority, StringComparison.Ordinal) ||
             string.Equals(request.Priority, V6RegularNknStateRefreshTailReconciliationPriority, StringComparison.Ordinal));
        if (tailReconciliationOwner &&
            context.V6RegularNknStateRefreshSendInFlight <= 0)
        {
            return false;
        }

        if (sameCheckpointOwner &&
            context.V6RegularNknStateRefreshSendInFlight <= 0 &&
            !string.Equals(source, "state_refresh_send_queued", StringComparison.Ordinal))
        {
            return false;
        }

        var samePriority =
            string.IsNullOrWhiteSpace(leg.CheckpointPriority) ||
            string.IsNullOrWhiteSpace(request.Priority) ||
            string.Equals(leg.CheckpointPriority, request.Priority, StringComparison.Ordinal);
        var coalesceReason = sameCheckpointOwner
            ? samePriority
                ? "same_checkpoint_owner_pending"
                : "same_checkpoint_owner_priority_changed"
            : "checkpoint_owner_pending_different_request";

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_fallback_checkpoint_request_coalesced; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; source={FormatProtocolLogValue(source)}; reason={coalesceReason}; leg_id={FormatProtocolLogValue(leg.LegId)}; leg_generation={leg.Generation}; route={leg.RouteSelection.TelemetryToken}; protocol_version={leg.ProtocolVersion}; live_route_epoch={leg.LiveRouteEpochId}; transport_epoch={leg.TransportEpochId}; checkpoint_request_id={FormatProtocolLogValue(leg.CheckpointRequestId)}; requested_checkpoint_request_id={FormatProtocolLogValue(request.RepairRequestId)}; request_transport_epoch={request.TransportEpoch}; priority={FormatProtocolLogValue(request.Priority ?? "(none)")}; state={FormatFileTransferLegState(leg.State)}; can_send_data={(leg.CanSendData ? 1 : 0)}");
        return true;
    }

    private void DeferOutboundPostTunaFallbackStateRefreshAfterRecoveryLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason)
    {
        if (!MarkOutboundFallbackCheckpointRequestedLocked(context, request, reason))
        {
            return;
        }

        var now = DateTimeOffset.UtcNow;
        var replacementCount = context.V6RegularNknDeferredStateRefreshRequest is null
            ? context.V6RegularNknDeferredStateRefreshReplaceCount
            : context.V6RegularNknDeferredStateRefreshReplaceCount + 1;
        context.V6RegularNknDeferredStateRefreshRequest = request;
        context.V6RegularNknDeferredStateRefreshReason = reason;
        context.V6RegularNknDeferredStateRefreshCreatedUtc = now;
        context.V6RegularNknDeferredStateRefreshReplaceCount = replacementCount;
        context.PullTransportResumeRequestPending = true;
        context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_state_refresh_deferred_until_resume";
        context.V6SenderPumpLastWakeReason = "post_tuna_fallback_state_refresh_deferred_until_resume";

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_state_refresh_deferred_until_resume; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; priority={FormatProtocolLogValue(request.Priority)}; deferred_replace_count={replacementCount}; failure_count={context.V6RegularNknStateRefreshFailureCount}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex)}; available_credit_chunks={Math.Max(0, Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount) - context.ChunksAcceptedForTransport)}; rebind_generation={context.PullTransportRebindGeneration}");
    }

    private void QueueDeferredOutboundPostTunaFallbackStateRefreshAfterResume(
        OutboundTransferContext context,
        string resumeReason,
        FileTransferReceiveRecoveryFallbackCheckpointResumeTrigger resumeTrigger)
    {
        IFileTransferDataSession? dataSession = null;
        OutboundSparsePumpInstall? stateRefreshInstall = null;
        FileTransferFrontierRequestFrameV6? request = null;
        string deferredReason = "(none)";
        DateTimeOffset? deferredUtc = null;
        int replaceCount = 0;
        var discardReason = string.Empty;
        FileTransferReceiveRecoveryFallbackCheckpointResumeReservation?
            resumeReservation = null;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal)
            {
                return;
            }

            if (context.V6RegularNknDeferredStateRefreshRequest is null)
            {
                return;
            }

            if (!context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
                context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
                !context.PullPostTunaRecoveryActive)
            {
                discardReason = "fallback_no_longer_active";
            }
            else if (context.DataSession is null)
            {
                discardReason = "data_session_missing";
            }
            else if (!context.DataSession.IsAvailable)
            {
                return;
            }
            else if (context.InstalledOutboundSparsePump is not { } installedPump ||
                     !IsOutboundSparsePumpInstallCurrentLocked(
                         context,
                         installedPump,
                         context.DataSession,
                         out _))
            {
                return;
            }
            else if (context.V6RegularNknStateRefreshSendInFlight > 0)
            {
                return;
            }
            else if (!IsCurrentOutboundFallbackCheckpointOwnerLocked(
                         context,
                         context.V6RegularNknDeferredStateRefreshRequest,
                         out var ownerReason,
                         out var ownerLeg))
            {
                discardReason = ownerReason;
                LogFileTransferFallbackCheckpointExchangeRetired(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    ownerLeg,
                    context.V6RegularNknDeferredStateRefreshRequest.RepairRequestId,
                    ownerLeg?.Generation ?? 0,
                    ownerLeg?.CheckpointRequestId,
                    ownerReason);
            }

            if (string.IsNullOrEmpty(discardReason) &&
                FileTransferCoordinator
                    .TryGetReceiveRecoveryFallbackCheckpointDeliveryCommand(
                        CreateCoordinatorStateLocked(context),
                        out var heldCommand,
                        out _) &&
                heldCommand.Binding.FrameIdentity.Matches(
                    context.V6RegularNknDeferredStateRefreshRequest) &&
                context.CoordinatorPersistentState.FileTransferReceiveRecovery
                    .LastFallbackCheckpointDeliveryReceipt is
                    {
                        State:
                            FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                                .Held,
                    } heldReceipt &&
                heldReceipt.Command == heldCommand)
            {
                var resumeEvidence =
                    new FileTransferReceiveRecoveryFallbackCheckpointResumeEvidence(
                        heldCommand,
                        resumeTrigger,
                        DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
                var resumeDecision = FileTransferCoordinator
                    .ReserveReceiveRecoveryFallbackCheckpointDeliveryResume(
                        CreateCoordinatorStateLocked(context),
                        resumeEvidence);
                if (resumeDecision.Status !=
                    FileTransferReceiveRecoveryTransitionStatus.Accepted ||
                    resumeDecision.FallbackCheckpointResumeReservation is not
                        { } acceptedReservation)
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_resume_decided; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; recovery_operation_authority_id={FormatProtocolLogValue(heldCommand.Binding.ParentAuthority.AuthorityId.ToString())}; recovery_operation_generation={heldCommand.Binding.ParentAuthority.OperationGeneration}; effective_checkpoint_request_id={FormatProtocolLogValue(heldCommand.Binding.EffectiveCheckpointRequestId)}; checkpoint_binding_generation={heldCommand.Binding.BindingGeneration}; checkpoint_delivery_generation={heldCommand.DeliveryGeneration}; frame_fingerprint={FormatProtocolLogValue(heldCommand.Binding.FrameIdentity.Sha256)}; trigger={resumeTrigger.ToString().ToLowerInvariant()}; physical_epoch={heldCommand.Binding.TransportEpoch}; outcome={resumeDecision.Status.ToString().ToLowerInvariant()}; decision_reason={FormatProtocolLogValue(resumeDecision.Reason)}");
                    return;
                }

                _ = AdoptCoordinatorStateLocked(
                    context,
                    resumeDecision.State,
                    "ReceiveRecoveryFallbackCheckpointResumeReserved",
                    resumeDecision.Status.ToString(),
                    resumeDecision.Reason);
                resumeReservation = acceptedReservation;
            }

            if (!string.IsNullOrEmpty(discardReason))
            {
                request = context.V6RegularNknDeferredStateRefreshRequest;
                deferredReason = context.V6RegularNknDeferredStateRefreshReason ?? "(none)";
                deferredUtc = context.V6RegularNknDeferredStateRefreshCreatedUtc;
                replaceCount = context.V6RegularNknDeferredStateRefreshReplaceCount;
                ClearOutboundV6RegularNknDeferredStateRefreshLocked(context);
            }
            else
            {
                dataSession = context.DataSession;
                stateRefreshInstall = context.InstalledOutboundSparsePump;
                request = context.V6RegularNknDeferredStateRefreshRequest;
                deferredReason = context.V6RegularNknDeferredStateRefreshReason ?? "(none)";
                deferredUtc = context.V6RegularNknDeferredStateRefreshCreatedUtc;
                replaceCount = context.V6RegularNknDeferredStateRefreshReplaceCount;
                ClearOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
                    context,
                    "deferred_state_refresh_replay_after_resume");
                ClearOutboundV6RegularNknDeferredStateRefreshLocked(context);
                if (resumeReservation is null)
                {
                    request = NormalizeOutboundPostTunaFallbackStateRefreshRequestForCurrentLegLocked(
                        context,
                        request,
                        "deferred_replay");
                }
                context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_deferred_state_refresh_replayed";
                context.V6SenderPumpLastWakeReason = "post_tuna_fallback_deferred_state_refresh_replayed";
            }
        }

        if (!string.IsNullOrEmpty(discardReason))
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_post_tuna_fallback_state_refresh_deferred_discarded; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(discardReason)}; resume_reason={FormatProtocolLogValue(resumeReason)}; deferred_reason={FormatProtocolLogValue(deferredReason)}; request_id={FormatProtocolLogValue(request?.RepairRequestId ?? "(none)")}; deferred_age_ms={FormatNullableDurationMs(deferredUtc, DateTimeOffset.UtcNow)}; deferred_replace_count={replaceCount}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}");
            return;
        }

        if (dataSession is null ||
            stateRefreshInstall is null ||
            request is null)
        {
            return;
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_state_refresh_deferred_replayed; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(resumeReason)}; deferred_reason={FormatProtocolLogValue(deferredReason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; priority={FormatProtocolLogValue(request.Priority)}; deferred_age_ms={FormatNullableDurationMs(deferredUtc, DateTimeOffset.UtcNow)}; deferred_replace_count={replaceCount}; rebind_generation={context.PullTransportRebindGeneration}");
        if (resumeReservation is { } reservation)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_resume_decided; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; recovery_operation_authority_id={FormatProtocolLogValue(reservation.Command.Binding.ParentAuthority.AuthorityId.ToString())}; recovery_operation_generation={reservation.Command.Binding.ParentAuthority.OperationGeneration}; effective_checkpoint_request_id={FormatProtocolLogValue(reservation.Command.Binding.EffectiveCheckpointRequestId)}; checkpoint_binding_generation={reservation.Command.Binding.BindingGeneration}; checkpoint_delivery_generation={reservation.Command.DeliveryGeneration}; frame_fingerprint={FormatProtocolLogValue(reservation.Command.Binding.FrameIdentity.Sha256)}; trigger={reservation.Trigger.ToString().ToLowerInvariant()}; physical_epoch={reservation.Command.Binding.TransportEpoch}; outcome=accepted; decision_reason=filetransfer_receive_recovery_fallback_checkpoint_resume_reserved");
        }

        QueueOutboundV4SparseRuntimeStateRefreshIfCurrent(
            context,
            dataSession,
            request,
            "deferred_replay",
            stateRefreshInstall,
            stateRefreshInstall.RuntimeOwner,
            dataSession,
            stateRefreshInstall.DataSessionGeneration,
            resumeReservation);
    }

    private static bool
        TryGetCurrentCoordinatorProtectedFallbackCheckpointDeliveryLocked(
            OutboundTransferContext context,
            out FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand
                command,
            out string deliveryState)
    {
        command = null!;
        deliveryState = "none";
        var recovery =
            context.CoordinatorPersistentState.FileTransferReceiveRecovery;
        if (recovery.CurrentOperation is not { } operation ||
            recovery.CurrentFallbackCheckpointBinding is not
                {
                    State:
                        FileTransferReceiveRecoveryFallbackCheckpointBindingState
                            .Pending,
                } binding ||
            binding.ParentAuthority != operation.Authority)
        {
            return false;
        }

        if (recovery.PendingFallbackCheckpointDeliveryCommand is
                { } pending &&
            pending.Binding == binding)
        {
            command = pending;
            deliveryState = recovery.LastFallbackCheckpointDeliveryReceipt is
                {
                    State:
                        FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                            .Held,
                } held &&
                held.Command == pending
                    ? "held"
                    : "pending";
            return true;
        }

        if (recovery.LastFallbackCheckpointDeliveryReceipt is
                {
                    State:
                        FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                            .Delivered,
                } delivered &&
            delivered.Command.Binding == binding)
        {
            command = delivered.Command;
            deliveryState = "delivered";
            return true;
        }

        return false;
    }

    private static bool ShouldSuppressOutboundFallbackCheckpointSendForDeliveryRecoveryLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        out string reason,
        out long recoveryAgeMs,
        out long remainingMs)
    {
        reason = string.Empty;
        recoveryAgeMs = 0;
        remainingMs = 0;

        if (!context.V6RegularNknFallbackCheckpointDeliveryRecoveryPending)
        {
            return false;
        }

        if (!IsV6RegularNknStateRefreshRequest(request) ||
            !context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
            !context.PullPostTunaRecoveryActive ||
            !IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg))
        {
            ClearOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
                context,
                "fallback_no_longer_active");
            return false;
        }

        var now = DateTimeOffset.UtcNow;
        var startedUtc = context.V6RegularNknFallbackCheckpointDeliveryRecoveryStartedUtc ??
                         context.V6LastReceiveRecoveryRequestedUtc ??
                         now;
        var elapsed = now - startedUtc;
        recoveryAgeMs = (long)Math.Max(0, elapsed.TotalMilliseconds);
        var cooldownMs = (long)CurrentV6SenderRequestFeedbackStallRecoveryCooldown.TotalMilliseconds;
        remainingMs = Math.Max(0, cooldownMs - recoveryAgeMs);

        if (elapsed >= CurrentV6SenderRequestFeedbackStallRecoveryCooldown &&
            !TryGetCurrentCoordinatorProtectedFallbackCheckpointDeliveryLocked(
                context,
                out _,
                out _))
        {
            ClearOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
                context,
                "recovery_window_elapsed");
            return false;
        }

        reason = "checkpoint_delivery_recovery_pending";
        return true;
    }

    private static bool ShouldSuppressOutboundFallbackCheckpointRequestForDeliveryRecoveryLocked(
        OutboundTransferContext context,
        string source,
        out string reason,
        out long recoveryAgeMs,
        out long remainingMs)
    {
        reason = string.Empty;
        recoveryAgeMs = 0;
        remainingMs = 0;

        if (!context.V6RegularNknFallbackCheckpointDeliveryRecoveryPending)
        {
            return false;
        }

        if (!context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
            !context.PullPostTunaRecoveryActive ||
            !IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg))
        {
            ClearOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
                context,
                "fallback_no_longer_active");
            return false;
        }

        var now = DateTimeOffset.UtcNow;
        var startedUtc = context.V6RegularNknFallbackCheckpointDeliveryRecoveryStartedUtc ??
                         context.V6LastReceiveRecoveryRequestedUtc ??
                         now;
        var elapsed = now - startedUtc;
        recoveryAgeMs = (long)Math.Max(0, elapsed.TotalMilliseconds);
        var cooldownMs = (long)CurrentV6SenderRequestFeedbackStallRecoveryCooldown.TotalMilliseconds;
        remainingMs = Math.Max(0, cooldownMs - recoveryAgeMs);

        if (elapsed >= CurrentV6SenderRequestFeedbackStallRecoveryCooldown &&
            !TryGetCurrentCoordinatorProtectedFallbackCheckpointDeliveryLocked(
                context,
                out _,
                out _))
        {
            ClearOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
                context,
                "recovery_window_elapsed");
            return false;
        }

        reason = "checkpoint_delivery_recovery_pending";
        return true;
    }

    private static void LogOutboundFallbackCheckpointRequestSuppressedForDeliveryRecovery(
        OutboundTransferContext context,
        string source,
        string suppressionReason,
        long deliveryRecoveryAgeMs,
        long deliveryRecoveryRemainingMs)
    {
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_fallback_checkpoint_request_suppressed_until_recovery; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; source={FormatProtocolLogValue(source)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; live_route_epoch={context.CurrentTransferLeg?.LiveRouteEpochId ?? context.CurrentLiveRouteEpoch?.EpochId ?? 0}; transport_epoch={context.CurrentTransferLeg?.TransportEpochId ?? context.V6TransportEpoch?.EpochId ?? 0}; suppression_reason={FormatProtocolLogValue(suppressionReason)}; pending_request_id={FormatProtocolLogValue(context.V6RegularNknFallbackCheckpointDeliveryRecoveryRequestId ?? "(none)")}; pending_reason={FormatProtocolLogValue(context.V6RegularNknFallbackCheckpointDeliveryRecoveryReason ?? "(none)")}; delivery_recovery_age_ms={deliveryRecoveryAgeMs}; delivery_recovery_remaining_ms={deliveryRecoveryRemainingMs}; recovery_cooldown_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryCooldown.TotalMilliseconds}; failure_count={context.V6RegularNknStateRefreshFailureCount}; rebind_generation={context.PullTransportRebindGeneration}");
    }

    private static string FormatNullableDurationMs(DateTimeOffset? sinceUtc, DateTimeOffset nowUtc)
        => sinceUtc is { } since
            ? ((long)Math.Max(0, (nowUtc - since).TotalMilliseconds)).ToString(CultureInfo.InvariantCulture)
            : "-1";

    private static void ClearOutboundV6RegularNknDeferredStateRefreshLocked(OutboundTransferContext context)
    {
        context.V6RegularNknDeferredStateRefreshRequest = null;
        context.V6RegularNknDeferredStateRefreshReason = null;
        context.V6RegularNknDeferredStateRefreshCreatedUtc = null;
        context.V6RegularNknDeferredStateRefreshReplaceCount = 0;
    }

    private bool IsOutboundSparseStateRefreshInstallCurrentLocked(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        OutboundSparsePumpInstall requiredInstall,
        IFileTransferDataSession? requiredDataSession,
        out string rejectionReason)
    {
        if (requiredDataSession is null ||
            !ReferenceEquals(dataSession, requiredDataSession))
        {
            rejectionReason = "data_session_replaced";
            return false;
        }

        if (context.InstalledOutboundSparsePump != requiredInstall)
        {
            rejectionReason = "install_generation_mismatch";
            return false;
        }

        return IsOutboundSparsePumpInstallCurrentLocked(
            context,
            requiredInstall,
            requiredDataSession,
            out rejectionReason);
    }

    private bool TryValidateOutboundSparseStateRefreshInstall(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        OutboundSparsePumpInstall requiredInstall,
        IFileTransferDataSession? requiredDataSession,
        string stage)
    {
        lock (gate)
        {
            if (IsOutboundSparseStateRefreshInstallCurrentLocked(
                    context,
                    dataSession,
                    requiredInstall,
                    requiredDataSession,
                    out var rejectionReason))
            {
                return true;
            }

            LogOutboundSparsePumpInstallRejected(
                context,
                requiredInstall,
                stage,
                rejectionReason);
            return false;
        }
    }

    private bool IsOutboundReceiveRecoveryFallbackCheckpointResumeCurrentLocked(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request,
        FileTransferReceiveRecoveryFallbackCheckpointResumeReservation
            reservation,
        out FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand command,
        out string rejectionReason)
    {
        command = reservation.Command;
        rejectionReason = "accepted";
        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal)
        {
            rejectionReason = "transfer_not_current";
            return false;
        }

        if (!ReferenceEquals(context.DataSession, dataSession))
        {
            rejectionReason = "data_session_replaced";
            return false;
        }

        var recovery =
            context.CoordinatorPersistentState.FileTransferReceiveRecovery;
        if (recovery.PendingFallbackCheckpointResumeReservation is not
                { } currentReservation ||
            currentReservation != reservation)
        {
            rejectionReason = "resume_reservation_not_current";
            return false;
        }

        if (!FileTransferCoordinator
                .TryGetReceiveRecoveryFallbackCheckpointDeliveryCommand(
                    CreateCoordinatorStateLocked(context),
                    out var currentCommand,
                    out rejectionReason) ||
            currentCommand != reservation.Command)
        {
            if (string.Equals(rejectionReason, "accepted", StringComparison.Ordinal))
            {
                rejectionReason = "checkpoint_delivery_command_not_current";
            }

            return false;
        }

        if (!currentCommand.Binding.FrameIdentity.Matches(request))
        {
            rejectionReason = "checkpoint_frame_identity_mismatch";
            return false;
        }

        command = currentCommand;
        return true;
    }

    private static long GetOutboundSparseInstallGeneration(
        OutboundTransferContext context)
        => context.InstalledOutboundSparsePump?.InstallGeneration ?? 0;

    private void LogOutboundReceiveRecoveryFallbackCheckpointPostSendDecision(
        OutboundTransferContext context,
        FileTransferReceiveRecoveryFallbackCheckpointResumeReservation
            reservation,
        OutboundSparsePumpInstall? capturedInstall,
        long currentInstallGeneration,
        string outcome,
        string reason)
        => LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_receive_recovery_fallback_checkpoint_command_scoped_post_send_decided; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; recovery_operation_authority_id={FormatProtocolLogValue(reservation.Command.Binding.ParentAuthority.AuthorityId.ToString())}; recovery_operation_generation={reservation.Command.Binding.ParentAuthority.OperationGeneration}; effective_checkpoint_request_id={FormatProtocolLogValue(reservation.Command.Binding.EffectiveCheckpointRequestId)}; checkpoint_binding_generation={reservation.Command.Binding.BindingGeneration}; checkpoint_delivery_generation={reservation.Command.DeliveryGeneration}; frame_fingerprint={FormatProtocolLogValue(reservation.Command.Binding.FrameIdentity.Sha256)}; reservation_observed_utc_ms={reservation.ObservedUtcMs}; physical_epoch={reservation.Command.Binding.TransportEpoch}; captured_sparse_install_generation={capturedInstall?.InstallGeneration ?? 0}; current_sparse_install_generation={currentInstallGeneration}; validation_mode=coordinator_resume_reservation; receipt_outcome={FormatProtocolLogValue(outcome)}; decision_reason={FormatProtocolLogValue(reason)}");

    private Task SendOutboundV4SparseRuntimeStateRefreshAsync(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request,
        long sendGeneration)
        => SendOutboundV4SparseRuntimeStateRefreshCoreAsync(
            context,
            dataSession,
            request,
            sendGeneration,
            requiredInstall: null,
            requiredDataSession: null);

    private Task SendOutboundV4SparseRuntimeStateRefreshIfCurrentAsync(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request,
        long sendGeneration,
        OutboundSparsePumpInstall requiredInstall,
        IFileTransferDataSession requiredDataSession,
        FileTransferReceiveRecoveryFallbackCheckpointResumeReservation?
            resumeReservation = null)
        => SendOutboundV4SparseRuntimeStateRefreshCoreAsync(
            context,
            dataSession,
            request,
            sendGeneration,
            requiredInstall,
            requiredDataSession,
            resumeReservation);

    private async Task SendOutboundV4SparseRuntimeStateRefreshCoreAsync(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferFrontierRequestFrameV6 request,
        long sendGeneration,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession? requiredDataSession,
        FileTransferReceiveRecoveryFallbackCheckpointResumeReservation?
            resumeReservation = null)
    {
        var retiredSendObserved = false;
        FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand?
            checkpointDeliveryCommand = null;
        OutboundSparsePumpInstall? retainedReplayInstall = null;
        IFileTransferDataSession? retainedReplayDataSession = null;
        string? retainedReplayQueuedCheckpointRequestId = null;
        try
        {
            using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(context.LifetimeCts.Token);
            timeoutCts.CancelAfter(TimeSpan.FromMilliseconds(V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs));
            if (requiredInstall is not null &&
                OutboundSparseStateRefreshPreSendBarrierForTests is { } preSendBarrier)
            {
                await preSendBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
            }

            FileTransferControlPlaneDeliveryRequest? controlPlaneRequest = null;
            lock (gate)
            {
                if (resumeReservation is null &&
                    requiredInstall is not null &&
                    !IsOutboundSparseStateRefreshInstallCurrentLocked(
                        context,
                        dataSession,
                        requiredInstall,
                        requiredDataSession,
                        out var installRejectionReason))
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        requiredInstall,
                        "state_refresh_pre_send",
                        installRejectionReason);
                    return;
                }

                if (resumeReservation is null &&
                    TryObserveRetiredOutboundV4SparseRuntimeStateRefreshSendLocked(
                        context,
                        request,
                        sendGeneration,
                        "pre_send"))
                {
                    retiredSendObserved = true;
                    return;
                }

                if (resumeReservation is { } reservation)
                {
                    if (!IsOutboundReceiveRecoveryFallbackCheckpointResumeCurrentLocked(
                            context,
                            dataSession,
                            request,
                            reservation,
                            out var reservedCommand,
                            out var reservationRejectionReason))
                    {
                        LogOutboundReceiveRecoveryFallbackCheckpointPostSendDecision(
                            context,
                            reservation,
                            requiredInstall,
                            GetOutboundSparseInstallGeneration(context),
                            "rejected_before_send",
                            reservationRejectionReason);
                        return;
                    }

                    checkpointDeliveryCommand = reservedCommand;
                }
                else if (FileTransferCoordinator
                    .TryGetReceiveRecoveryFallbackCheckpointDeliveryCommand(
                        CreateCoordinatorStateLocked(context),
                        out var currentCheckpointDeliveryCommand,
                        out _) &&
                    currentCheckpointDeliveryCommand.Binding.FrameIdentity
                        .Matches(request))
                {
                    checkpointDeliveryCommand =
                        currentCheckpointDeliveryCommand;
                }
                else if (IsV6RegularNknStateRefreshRequest(request) &&
                         context.CoordinatorPersistentState
                             .FileTransferReceiveRecovery
                             .CurrentFallbackCheckpointBinding is not null)
                {
                    return;
                }

                if (ReferenceEquals(outboundTransfer, context) &&
                    !context.IsTerminal &&
                    checkpointDeliveryCommand is null &&
                    ShouldUseFallbackControlPlaneForOutboundFrame(context, request))
                {
                    controlPlaneRequest = CreateOutboundControlPlaneDeliveryRequestLocked(
                        context,
                        FileTransferControlPlaneKind.FallbackCheckpointRequest,
                        request,
                        "post_tuna_fallback_state_refresh");
                }
            }

            if (controlPlaneRequest is not null)
            {
                if (!await SendOutboundFallbackControlPlaneOrDataSessionAsync(
                        context,
                        dataSession,
                        controlPlaneRequest,
                        timeoutCts.Token)
                    .ConfigureAwait(false))
                {
                    return;
                }
            }
            else
            {
                await dataSession.SendAsync(request, timeoutCts.Token).ConfigureAwait(false);
            }

            var commandScopedReceiptApplied = false;
            if (resumeReservation is { } completedReservation)
            {
                lock (gate)
                {
                    var currentInstallGeneration =
                        GetOutboundSparseInstallGeneration(context);
                    if (!IsOutboundReceiveRecoveryFallbackCheckpointResumeCurrentLocked(
                            context,
                            dataSession,
                            request,
                            completedReservation,
                            out var currentCommand,
                            out var reservationRejectionReason) ||
                        checkpointDeliveryCommand is null ||
                        currentCommand != checkpointDeliveryCommand)
                    {
                        if (string.Equals(
                                reservationRejectionReason,
                                "accepted",
                                StringComparison.Ordinal))
                        {
                            reservationRejectionReason =
                                "checkpoint_delivery_command_changed";
                        }
                        LogOutboundReceiveRecoveryFallbackCheckpointPostSendDecision(
                            context,
                            completedReservation,
                            requiredInstall,
                            currentInstallGeneration,
                            "rejected",
                            reservationRejectionReason);
                        return;
                    }

                    commandScopedReceiptApplied =
                        ApplyOutboundReceiveRecoveryFallbackCheckpointDeliveryReceiptLocked(
                            context,
                            currentCommand,
                            FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                                .Delivered,
                            "fallback_checkpoint_control_delivered");
                    LogOutboundReceiveRecoveryFallbackCheckpointPostSendDecision(
                        context,
                        completedReservation,
                        requiredInstall,
                        currentInstallGeneration,
                        commandScopedReceiptApplied ? "applied" : "rejected",
                        commandScopedReceiptApplied
                            ? "fallback_checkpoint_delivery_delivered"
                            : "fallback_checkpoint_delivery_receipt_rejected");
                    if (!commandScopedReceiptApplied)
                    {
                        return;
                    }
                }
            }
            else if (requiredInstall is not null &&
                !TryValidateOutboundSparseStateRefreshInstall(
                    context,
                    dataSession,
                    requiredInstall,
                    requiredDataSession,
                    "state_refresh_sent"))
            {
                return;
            }

            if (resumeReservation is null &&
                TryObserveRetiredOutboundV4SparseRuntimeStateRefreshSend(
                    context,
                    request,
                    sendGeneration,
                    "sent"))
            {
                retiredSendObserved = true;
                return;
            }

            var reusedPendingCheckpoint = false;
            var sentOutcomeCurrent = false;
            lock (gate)
            {
                sentOutcomeCurrent = ReferenceEquals(outboundTransfer, context) &&
                    !context.IsTerminal &&
                    (commandScopedReceiptApplied ||
                     requiredInstall is null ||
                     IsOutboundSparseStateRefreshInstallCurrentLocked(
                         context,
                         dataSession,
                         requiredInstall,
                         requiredDataSession,
                         out _));
                if (sentOutcomeCurrent &&
                    context.V6RegularNknStateRefreshActiveSendGeneration == sendGeneration &&
                    string.Equals(context.V6RegularNknStateRefreshActiveRequestId, request.RepairRequestId, StringComparison.Ordinal))
                {
                    reusedPendingCheckpoint = context.V6RegularNknStateRefreshActiveReusedPendingCheckpoint;
                }
            }

            if (!sentOutcomeCurrent)
            {
                if (requiredInstall is not null)
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        requiredInstall,
                        "state_refresh_sent_outcome",
                        "install_no_longer_current");
                }

                return;
            }

            LogPullBinaryFrameSent(context.TransferId, context.SessionId, request, payloadBytes: 0);

            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v6_regular_nkn_state_refresh_sent; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; generation={sendGeneration}; reused_pending_checkpoint={(reusedPendingCheckpoint ? 1 : 0)}; transport_epoch={request.TransportEpoch}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}");
            if (checkpointDeliveryCommand is not null &&
                !commandScopedReceiptApplied)
            {
                ApplyOutboundReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                    context,
                    checkpointDeliveryCommand,
                    FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                        .Delivered,
                    "fallback_checkpoint_control_delivered");
            }
        }
        catch (OperationCanceledException) when (!context.LifetimeCts.IsCancellationRequested)
        {
            if (checkpointDeliveryCommand is not null &&
                TryHoldOutboundReceiveRecoveryFallbackCheckpointDelivery(
                    context,
                    request,
                    checkpointDeliveryCommand,
                    "fallback_checkpoint_delivery_barrier_not_ready"))
            {
                return;
            }
            if (requiredInstall is not null &&
                !TryValidateOutboundSparseStateRefreshInstall(
                    context,
                    dataSession,
                    requiredInstall,
                    requiredDataSession,
                    "state_refresh_timeout"))
            {
                return;
            }

            if (TryObserveRetiredOutboundV4SparseRuntimeStateRefreshSend(
                    context,
                    request,
                    sendGeneration,
                    "timeout"))
            {
                retiredSendObserved = true;
                return;
            }

            var activationDeferred = requiredInstall is not null
                ? TryDeferOutboundPostTunaFallbackStateRefreshForTunaActivationIfCurrent(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_timeout",
                    null,
                    requiredInstall,
                    requiredDataSession)
                : TryDeferOutboundPostTunaFallbackStateRefreshForTunaActivation(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_timeout",
                    null);
            if (activationDeferred)
            {
                return;
            }

            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v6_regular_nkn_state_refresh_send_timeout; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; generation={sendGeneration}; timeout_ms={V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs}");
            if (requiredInstall is not null)
            {
                RequestOutboundPostTunaFallbackStateRefreshReceiveRecoveryIfCurrent(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_timeout",
                    requiredInstall,
                    requiredDataSession);
            }
            else
            {
                RequestOutboundPostTunaFallbackStateRefreshReceiveRecovery(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_timeout");
            }
        }
        catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
        {
        }
        catch (Exception ex)
        {
            if (checkpointDeliveryCommand is not null &&
                TryHoldOutboundReceiveRecoveryFallbackCheckpointDelivery(
                    context,
                    request,
                    checkpointDeliveryCommand,
                    "fallback_checkpoint_delivery_barrier_not_ready"))
            {
                return;
            }
            if (requiredInstall is not null &&
                !TryValidateOutboundSparseStateRefreshInstall(
                    context,
                    dataSession,
                    requiredInstall,
                    requiredDataSession,
                    "state_refresh_failed"))
            {
                return;
            }

            if (TryObserveRetiredOutboundV4SparseRuntimeStateRefreshSend(
                    context,
                    request,
                    sendGeneration,
                    "failed"))
            {
                retiredSendObserved = true;
                return;
            }

            var activationDeferred = requiredInstall is not null
                ? TryDeferOutboundPostTunaFallbackStateRefreshForTunaActivationIfCurrent(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_failed",
                    ex,
                    requiredInstall,
                    requiredDataSession)
                : TryDeferOutboundPostTunaFallbackStateRefreshForTunaActivation(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_failed",
                    ex);
            if (activationDeferred)
            {
                return;
            }

            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v6_regular_nkn_state_refresh_send_failed; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; generation={sendGeneration}; reason={FormatProtocolLogValue(ex.Message)}");
            if (requiredInstall is not null)
            {
                RequestOutboundPostTunaFallbackStateRefreshReceiveRecoveryIfCurrent(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_failed",
                    requiredInstall,
                    requiredDataSession);
            }
            else
            {
                RequestOutboundPostTunaFallbackStateRefreshReceiveRecovery(
                    context,
                    request,
                    "post_tuna_fallback_state_refresh_send_failed");
            }
        }
        finally
        {
            lock (gate)
            {
                if (ReferenceEquals(outboundTransfer, context) &&
                    context.V6RegularNknStateRefreshActiveSendGeneration == sendGeneration &&
                    context.V6RegularNknStateRefreshSendInFlight > 0)
                {
                    context.V6RegularNknStateRefreshSendInFlight--;
                    if (context.V6RegularNknStateRefreshSendInFlight <= 0)
                    {
                        context.V6RegularNknStateRefreshActiveSendGeneration = 0;
                        context.V6RegularNknStateRefreshActiveRequestId = null;
                        context.V6RegularNknStateRefreshActivePriority = null;
                        context.V6RegularNknStateRefreshActiveStartedUtc = null;
                        context.V6RegularNknStateRefreshActiveReusedPendingCheckpoint = false;
                    }
                }
                else if (!retiredSendObserved &&
                         ReferenceEquals(outboundTransfer, context) &&
                         context.V6RegularNknStateRefreshRetiredSendGeneration == sendGeneration)
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v6_regular_nkn_state_refresh_retired_send_observed; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; generation={sendGeneration}; outcome=finally; retired_request_id={FormatProtocolLogValue(context.V6RegularNknStateRefreshRetiredRequestId ?? "(none)")}; active_generation={context.V6RegularNknStateRefreshActiveSendGeneration}; active_request_id={FormatProtocolLogValue(context.V6RegularNknStateRefreshActiveRequestId ?? "(none)")}");
                }

                if (ReferenceEquals(outboundTransfer, context) &&
                    context.V6RegularNknStateRefreshSendInFlight <= 0 &&
                    TryCapturePendingOutboundFileTransferRouteTransitionRetainedReplayLocked(
                        context,
                        out var pendingReplayInstall,
                        out var pendingReplayDataSession,
                        out var pendingReplayDispatch))
                {
                    retainedReplayInstall = pendingReplayInstall;
                    retainedReplayDataSession = pendingReplayDataSession;
                    retainedReplayQueuedCheckpointRequestId = string.Equals(
                        request.RepairRequestId,
                        pendingReplayDispatch.CheckpointLease
                            .CheckpointRequestId,
                        StringComparison.Ordinal)
                            ? request.RepairRequestId
                            : null;
                }
            }

            if (retainedReplayInstall is { } replayInstall &&
                retainedReplayDataSession is { } replayDataSession)
            {
                _ = TryApplyOutboundCommittedFileTransferRouteTransitionRetainedFrameCoreAsync(
                    context,
                    replayInstall,
                    replayDataSession,
                    retainedReplayQueuedCheckpointRequestId);
            }
        }
    }

    private bool TryHoldOutboundReceiveRecoveryFallbackCheckpointDelivery(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand command,
        string reason)
    {
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                !FileTransferCoordinator
                    .TryGetReceiveRecoveryFallbackCheckpointDeliveryCommand(
                        CreateCoordinatorStateLocked(context),
                        out var current,
                        out _) ||
                current != command)
            {
                return false;
            }

            if (!ApplyOutboundReceiveRecoveryFallbackCheckpointDeliveryReceiptLocked(
                    context,
                    command,
                    FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                        .Held,
                    reason))
            {
                return false;
            }

            context.V6RegularNknDeferredStateRefreshRequest = request;
            context.V6RegularNknDeferredStateRefreshReason = reason;
            context.V6RegularNknDeferredStateRefreshCreatedUtc ??=
                DateTimeOffset.UtcNow;
            context.PullTransportResumeRequestPending = true;
            return true;
        }
    }

    private void ApplyOutboundReceiveRecoveryFallbackCheckpointDeliveryReceipt(
        OutboundTransferContext context,
        FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand command,
        FileTransferReceiveRecoveryFallbackCheckpointDeliveryState state,
        string reason)
    {
        lock (gate)
        {
            ApplyOutboundReceiveRecoveryFallbackCheckpointDeliveryReceiptLocked(
                context,
                command,
                state,
                reason);
        }
    }

    private bool ApplyOutboundReceiveRecoveryFallbackCheckpointDeliveryReceiptLocked(
        OutboundTransferContext context,
        FileTransferReceiveRecoveryFallbackCheckpointDeliveryCommand command,
        FileTransferReceiveRecoveryFallbackCheckpointDeliveryState state,
        string reason)
    {
        if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
        {
            return false;
        }

        var receipt =
            new FileTransferReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                command,
                state,
                command.Binding.FrameIdentity.Sha256,
                reason);
        var previousReceipt = context.CoordinatorPersistentState
            .FileTransferReceiveRecovery
            .LastFallbackCheckpointDeliveryReceipt;
        var decision = FileTransferCoordinator
            .ApplyReceiveRecoveryFallbackCheckpointDeliveryReceipt(
                CreateCoordinatorStateLocked(context),
                receipt,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        if (decision.Status ==
            FileTransferReceiveRecoveryTransitionStatus.Rejected)
        {
            return false;
        }

        _ = AdoptCoordinatorStateLocked(
            context,
            decision.State,
            "ReceiveRecoveryFallbackCheckpointDeliveryReceiptApplied",
            decision.Status.ToString(),
            decision.Reason);
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; recovery_operation_authority_id={FormatProtocolLogValue(command.Binding.ParentAuthority.AuthorityId.ToString())}; recovery_operation_generation={command.Binding.ParentAuthority.OperationGeneration}; root_checkpoint_request_id={FormatProtocolLogValue(command.Binding.ParentCheckpointRequestId ?? "(none)")}; effective_checkpoint_request_id={FormatProtocolLogValue(command.Binding.EffectiveCheckpointRequestId)}; checkpoint_binding_generation={command.Binding.BindingGeneration}; checkpoint_delivery_generation={command.DeliveryGeneration}; frame_fingerprint={FormatProtocolLogValue(command.Binding.FrameIdentity.Sha256)}; delivery_state={state.ToString().ToLowerInvariant()}; decision_status={decision.Status.ToString().ToLowerInvariant()}; decision_reason={FormatProtocolLogValue(decision.Reason)}");
        var lifecycleEvent = state switch
        {
            FileTransferReceiveRecoveryFallbackCheckpointDeliveryState.Held =>
                "filetransfer_receive_recovery_fallback_checkpoint_delivery_held",
            FileTransferReceiveRecoveryFallbackCheckpointDeliveryState.Delivered
                when previousReceipt is
                {
                    State:
                        FileTransferReceiveRecoveryFallbackCheckpointDeliveryState
                            .Held,
                } heldReceipt &&
                heldReceipt.Command == command =>
                "filetransfer_receive_recovery_fallback_checkpoint_delivery_resumed",
            _ => null,
        };
        if (lifecycleEvent is not null)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event={lifecycleEvent}; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; recovery_operation_authority_id={FormatProtocolLogValue(command.Binding.ParentAuthority.AuthorityId.ToString())}; recovery_operation_generation={command.Binding.ParentAuthority.OperationGeneration}; root_checkpoint_request_id={FormatProtocolLogValue(command.Binding.ParentCheckpointRequestId ?? "(none)")}; effective_checkpoint_request_id={FormatProtocolLogValue(command.Binding.EffectiveCheckpointRequestId)}; checkpoint_binding_generation={command.Binding.BindingGeneration}; checkpoint_delivery_generation={command.DeliveryGeneration}; frame_fingerprint={FormatProtocolLogValue(command.Binding.FrameIdentity.Sha256)}; physical_epoch={command.Binding.TransportEpoch}; hold_state={state.ToString().ToLowerInvariant()}; outcome={decision.Status.ToString().ToLowerInvariant()}; decision_reason={FormatProtocolLogValue(decision.Reason)}");
        }
        return true;
    }

    private bool TryRetireOutboundPostTunaFallbackStaleStateRefreshSendLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        DateTimeOffset now)
    {
        var staleInflightRequest = IsPostTunaFallbackStaleInflightStateRefreshRequest(request);
        var staleCreditRequest = IsPostTunaFallbackStaleCreditStateRefreshRequest(request);
        var tailReconciliationRequest = IsPostTunaFallbackTailReconciliationStateRefresh(request);
        if ((!staleInflightRequest && !staleCreditRequest && !tailReconciliationRequest) ||
            !context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
            !context.PullPostTunaRecoveryActive ||
            context.V6RegularNknStateRefreshSendInFlight <= 0 ||
            context.V6RegularNknStateRefreshFailureCount < Math.Min(
                V6PostTunaFallbackStaleInflightRecoveryMinStateRefreshFailures,
                V6PostTunaFallbackStaleCreditRecoveryMinStateRefreshFailures))
        {
            return false;
        }

        var activeStartedUtc = context.V6RegularNknStateRefreshActiveStartedUtc;
        var activeAgeMs = activeStartedUtc is { } started
            ? (long)Math.Max(0, (now - started).TotalMilliseconds)
            : -1;
        var activeGeneration = context.V6RegularNknStateRefreshActiveSendGeneration;
        var activeRequestId = context.V6RegularNknStateRefreshActiveRequestId ?? "(none)";
        var activePriority = context.V6RegularNknStateRefreshActivePriority ?? "(none)";
        var activeTimedOut = activeAgeMs < 0 ||
            activeAgeMs >= V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs;
        var activeWasStaleInflight = string.Equals(
            context.V6RegularNknStateRefreshActivePriority,
            V6RegularNknStateRefreshStaleInflightPriority,
            StringComparison.Ordinal);
        var retireReason = activeTimedOut
            ? "state_refresh_send_timeout_elapsed"
            : activeWasStaleInflight
                ? "stale_inflight_state_refresh_superseded"
                : tailReconciliationRequest
                    ? "tail_reconciliation_forced"
                : staleCreditRequest
                    ? "stale_credit_recovery_forced"
                    : "stale_inflight_recovery_forced";

        var retiredCheckpointRequestId = context.V6RegularNknStateRefreshActiveRequestId;
        if (!string.IsNullOrWhiteSpace(retiredCheckpointRequestId))
        {
            RetireOutboundFallbackCheckpointExchangeLocked(
                context,
                retiredCheckpointRequestId,
                retireReason);
        }

        context.V6RegularNknStateRefreshRetiredSendGeneration = activeGeneration;
        context.V6RegularNknStateRefreshRetiredRequestId = retiredCheckpointRequestId;
        context.V6RegularNknStateRefreshRetiredSendCount++;
        context.V6RegularNknStateRefreshSendInFlight = 0;
        context.V6RegularNknStateRefreshActiveSendGeneration = 0;
        context.V6RegularNknStateRefreshActiveRequestId = null;
        context.V6RegularNknStateRefreshActivePriority = null;
        context.V6RegularNknStateRefreshActiveStartedUtc = null;
        context.V6RegularNknStateRefreshActiveReusedPendingCheckpoint = false;
        context.PullTransportResumeRequestPending = true;
        context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_stale_state_refresh_retired";
        context.V6SenderPumpLastWakeReason = "post_tuna_fallback_stale_state_refresh_retired";

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_state_refresh_send_inflight_retired; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(retireReason)}; retired_generation={activeGeneration}; retired_request_id={FormatProtocolLogValue(activeRequestId)}; retired_priority={FormatProtocolLogValue(activePriority)}; replacement_request_id={FormatProtocolLogValue(request.RepairRequestId)}; replacement_priority={FormatProtocolLogValue(request.Priority)}; active_age_ms={activeAgeMs}; timeout_ms={V6RegularNknSparseRuntimeStateRefreshSendTimeoutMs}; retired_send_count={context.V6RegularNknStateRefreshRetiredSendCount}; failure_count={context.V6RegularNknStateRefreshFailureCount}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex)}; available_credit_chunks={Math.Max(0, Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount) - context.ChunksAcceptedForTransport)}; rebind_generation={context.PullTransportRebindGeneration}");
        return true;
    }

    private bool TryObserveRetiredOutboundV4SparseRuntimeStateRefreshSend(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        long sendGeneration,
        string outcome)
    {
        lock (gate)
        {
            return TryObserveRetiredOutboundV4SparseRuntimeStateRefreshSendLocked(
                context,
                request,
                sendGeneration,
                outcome);
        }
    }

    private bool TryObserveRetiredOutboundV4SparseRuntimeStateRefreshSendLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        long sendGeneration,
        string outcome)
    {
        if (!ReferenceEquals(outboundTransfer, context) ||
            sendGeneration <= 0)
        {
            return false;
        }

        var staleGeneration =
            context.V6RegularNknStateRefreshRetiredSendGeneration >= sendGeneration ||
            sendGeneration < context.V6RegularNknStateRefreshSendGeneration ||
            context.V6RegularNknStateRefreshActiveSendGeneration > 0 &&
            sendGeneration < context.V6RegularNknStateRefreshActiveSendGeneration;
        if (!staleGeneration)
        {
            return false;
        }

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v6_regular_nkn_state_refresh_retired_send_observed; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; generation={sendGeneration}; outcome={FormatProtocolLogValue(outcome)}; retired_request_id={FormatProtocolLogValue(context.V6RegularNknStateRefreshRetiredRequestId ?? "(none)")}; active_generation={context.V6RegularNknStateRefreshActiveSendGeneration}; active_request_id={FormatProtocolLogValue(context.V6RegularNknStateRefreshActiveRequestId ?? "(none)")}");
        return true;
    }

    private bool TryDeferOutboundPostTunaFallbackStateRefreshForTunaActivation(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason,
        Exception? ex)
        => TryDeferOutboundPostTunaFallbackStateRefreshForTunaActivationIfCurrent(
            context,
            request,
            reason,
            ex,
            requiredInstall: null,
            requiredDataSession: null);

    private bool TryDeferOutboundPostTunaFallbackStateRefreshForTunaActivationIfCurrent(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason,
        Exception? ex,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession? requiredDataSession)
    {
        var signalSenderPump = false;
        var suppressActivationPause = false;
        var shouldDefer = false;
        var pauseReason = "tuna_activation_negotiating";
        long feedbackSilenceMs = 0;
        var transportBacklogChunks = 0;
        var availableCreditChunks = 0;
        var creditCeiling = 0;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                (requiredInstall is not null &&
                 (requiredDataSession is null ||
                  !IsOutboundSparseStateRefreshInstallCurrentLocked(
                      context,
                      requiredDataSession,
                      requiredInstall,
                      requiredDataSession,
                      out _))) ||
                !IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(context))
            {
                return false;
            }

            shouldDefer =
                ShouldPauseOutboundV4SenderPumpForTunaActivationNegotiationLocked(context) ||
                IsTunaActivationNegotiationTransportPauseReason(context.PullTransportPauseReason) ||
                IsTunaActivationNegotiationTransportPauseReason(context.PullTransportLastPauseReason) ||
                IsTunaActivationNegotiationDataSessionUnavailableException(ex);
            if (!shouldDefer)
            {
                return false;
            }

            var now = DateTimeOffset.UtcNow;
            pauseReason = context.PullTransportPauseReason ??
                context.PullTransportLastPauseReason ??
                pauseReason;
            feedbackSilenceMs = context.PullV4LastPeerFrameReceivedUtc is { } lastPeerFrame
                ? (long)Math.Max(0, (now - lastPeerFrame).TotalMilliseconds)
                : 0;
            transportBacklogChunks = Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex);
            creditCeiling = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
            availableCreditChunks = Math.Max(0, creditCeiling - context.ChunksAcceptedForTransport);
            if (ShouldSuppressTunaActivationPauseForPostTunaFallbackLocked(context))
            {
                suppressActivationPause = true;
                if (IsTunaActivationNegotiationTransportPauseReason(context.PullTransportPauseReason))
                {
                    context.PullTransportPaused = false;
                    context.PullTransportPausedSinceUtc = null;
                    context.PullTransportGraceDeadlineUtc = null;
                    context.PullTransportPauseReason = null;
                    context.PullTransportResumeRequestPending = false;
                }

                context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_tuna_activation_pause_suppressed";
                context.V6SenderPumpLastWakeReason = "post_tuna_fallback_tuna_activation_pause_suppressed";
                signalSenderPump = true;
            }

            if (!suppressActivationPause)
            {
                context.V6EpochLivenessDeferralCount++;
                context.V6EpochLivenessDeferralUtc = now;
                context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_state_refresh_deferred_for_tuna_activation";
                context.V6SenderPumpLastWakeReason = "post_tuna_fallback_state_refresh_deferred_for_tuna_activation";
                MarkOutboundV4SenderPumpTransportPausedLocked(context);
                signalSenderPump = true;
            }
        }

        if (suppressActivationPause)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_post_tuna_fallback_state_refresh_tuna_activation_pause_suppressed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; pause_reason={FormatProtocolLogValue(pauseReason)}; error={FormatProtocolLogValue(ex?.GetType().Name ?? "OperationCanceledException")}; message={FormatProtocolLogValue(ex?.Message ?? "send canceled or timed out during tuna activation")}; feedback_silence_ms={feedbackSilenceMs}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");
        }
        else
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_post_tuna_fallback_state_refresh_deferred_for_tuna_activation; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; pause_reason={FormatProtocolLogValue(pauseReason)}; error={FormatProtocolLogValue(ex?.GetType().Name ?? "OperationCanceledException")}; message={FormatProtocolLogValue(ex?.Message ?? "send canceled or timed out during tuna activation")}; feedback_silence_ms={feedbackSilenceMs}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");
        }

        if (signalSenderPump)
        {
            SignalOutboundSparseSenderPump(
                context,
                requiredInstall,
                requiredInstall?.RuntimeOwner,
                requiredDataSession,
                requiredInstall?.DataSessionGeneration ?? 0);
        }

        return !suppressActivationPause;
    }

    private void RequestOutboundPostTunaFallbackStateRefreshReceiveRecovery(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason)
        => RequestOutboundPostTunaFallbackStateRefreshReceiveRecoveryIfCurrent(
            context,
            request,
            reason,
            requiredInstall: null,
            requiredDataSession: null);

    private void RequestOutboundPostTunaFallbackStateRefreshReceiveRecoveryIfCurrent(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason,
        OutboundSparsePumpInstall? requiredInstall,
        IFileTransferDataSession? requiredDataSession)
    {
        FileTransferReceiveRecoveryRequest? recoveryRequest = null;
        var signalSenderPump = false;
        var staleInflightEscalation = IsPostTunaFallbackStaleInflightStateRefreshRequest(request);
        var staleCreditEscalation = IsPostTunaFallbackStaleCreditStateRefreshRequest(request);
        var tailReconciliationEscalation = IsPostTunaFallbackTailReconciliationStateRefresh(request);
        var stateRefreshSendTimeout = string.Equals(
            reason,
            "post_tuna_fallback_state_refresh_send_timeout",
            StringComparison.Ordinal);
        var bypassRecoveryCooldown = staleInflightEscalation || staleCreditEscalation || tailReconciliationEscalation || stateRefreshSendTimeout;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                (requiredInstall is not null &&
                 (requiredDataSession is null ||
                  !IsOutboundSparseStateRefreshInstallCurrentLocked(
                      context,
                      requiredDataSession,
                      requiredInstall,
                      requiredDataSession,
                      out _))) ||
                !IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(context))
            {
                return;
            }

            var now = DateTimeOffset.UtcNow;
            var feedbackSilence = context.PullV4LastPeerFrameReceivedUtc is { } lastPeerFrame
                ? now - lastPeerFrame
                : TimeSpan.Zero;
            var transportBacklogChunks = Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex);
            var creditCeiling = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
            var availableCreditChunks = Math.Max(0, creditCeiling - context.ChunksAcceptedForTransport);

            context.V6RegularNknStateRefreshFailureCount++;
            context.V6EpochLivenessDeferralCount++;
            context.V6EpochLivenessDeferralUtc = now;
            context.PullTransportResumeRequestPending = true;
            context.SparseSenderPumpLastWakeReason = "post_tuna_fallback_state_refresh_receive_recovery";
            context.V6SenderPumpLastWakeReason = "post_tuna_fallback_state_refresh_receive_recovery";
            var stateRefreshSendFailed = string.Equals(
                reason,
                "post_tuna_fallback_state_refresh_send_failed",
                StringComparison.Ordinal);
            string? checkpointRequestIdForRecovery = request.RepairRequestId;
            if (stateRefreshSendTimeout || stateRefreshSendFailed)
            {
                if (!TryPreserveOutboundPostTunaFallbackCheckpointAfterSendFailureLocked(
                        context,
                        request,
                        reason,
                        stateRefreshSendTimeout))
                {
                    TryRetireOutboundFallbackCheckpointRequestLocked(context, request.RepairRequestId, reason);
                    checkpointRequestIdForRecovery = null;
                }
            }

            MaybeQueueOutboundV4StalledRebindSafetyReplayLocked(context, reason);
            signalSenderPump = true;

            if (!bypassRecoveryCooldown &&
                context.V6LastReceiveRecoveryRequestedUtc is { } lastRecovery &&
                now - lastRecovery < CurrentV6SenderRequestFeedbackStallRecoveryCooldown)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_post_tuna_fallback_state_refresh_receive_recovery_suppressed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; suppression_reason=recovery_cooldown; cooldown_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryCooldown.TotalMilliseconds}; last_recovery_age_ms={(long)Math.Max(0, (now - lastRecovery).TotalMilliseconds)}; failure_count={context.V6RegularNknStateRefreshFailureCount}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");
                recoveryRequest = null;
            }
            else if (!bypassRecoveryCooldown &&
                     context.PullV4LastPeerFrameReceivedUtc.HasValue &&
                     feedbackSilence < CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay &&
                     transportBacklogChunks > 0)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_post_tuna_fallback_state_refresh_receive_recovery_deferred; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; suppression_reason=fresh_peer_progress; stale_credit_recovery_delay_ms={(long)CurrentV6RegularNknSparseRuntimeStaleCreditReceiveRecoveryDelay.TotalMilliseconds}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; failure_count={context.V6RegularNknStateRefreshFailureCount}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");
                recoveryRequest = null;
            }
            else
            {
                context.V6LastReceiveRecoveryRequestedUtc = now;
                var recoveryReason = staleInflightEscalation
                    ? "post_tuna_fallback_stale_inflight_repair_failed"
                    : staleCreditEscalation
                        ? "post_tuna_fallback_stale_credit_repair_failed"
                    : tailReconciliationEscalation
                        ? "post_tuna_fallback_tail_reconciliation_failed"
                    : "post_tuna_fallback_state_refresh_failed";
                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_post_tuna_fallback_state_refresh_receive_recovery_requested; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; request_id={FormatProtocolLogValue(request.RepairRequestId)}; stale_inflight_recovery={(staleInflightEscalation ? 1 : 0)}; stale_credit_recovery={(staleCreditEscalation ? 1 : 0)}; tail_reconciliation={(tailReconciliationEscalation ? 1 : 0)}; state_refresh_send_timeout={(stateRefreshSendTimeout ? 1 : 0)}; recovery_reason={FormatProtocolLogValue(recoveryReason)}; failure_count={context.V6RegularNknStateRefreshFailureCount}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; highest_accepted_chunk_index={Math.Max(-1, context.ChunksAcceptedForTransport - 1)}; transport_backlog_chunks={transportBacklogChunks}; available_credit_chunks={availableCreditChunks}; credit_ceiling_chunk_index={creditCeiling}; rebind_generation={context.PullTransportRebindGeneration}; bridge_recovery_policy={FormatFileTransferBridgeRecoveryPolicy(context.BridgeRecoveryPolicy)}");

                recoveryRequest = AttachOutboundSparsePumpInstallRecoveryAuthorityLocked(
                    context,
                    requiredInstall,
                    new FileTransferReceiveRecoveryRequest(
                        context.SessionId,
                        context.TransferId,
                        FileTransferDirection.Outbound,
                        recoveryReason),
                    recoveryReason) with
                {
                    CheckpointRequestId = checkpointRequestIdForRecovery,
                    TransportEpoch = request.TransportEpoch,
                };
            }
        }

        if (signalSenderPump)
        {
            SignalOutboundSparseSenderPump(
                context,
                requiredInstall,
                requiredInstall?.RuntimeOwner,
                requiredDataSession,
                requiredInstall?.DataSessionGeneration ?? 0);
        }

        if (recoveryRequest is not null)
        {
            if (requiredInstall is not null)
            {
                TryRequestFileTransferReceiveRecoveryIfCurrent(
                    recoveryRequest,
                    requiredInstall,
                    requiredDataSession);
            }
            else
            {
                TryRequestFileTransferReceiveRecovery(recoveryRequest);
            }
        }
    }

    private static bool IsPostTunaFallbackStaleInflightStateRefreshRequest(FileTransferFrontierRequestFrameV6 request)
        => string.Equals(request.Priority, V6RegularNknStateRefreshStaleInflightPriority, StringComparison.Ordinal);

    private static bool IsPostTunaFallbackStaleCreditStateRefreshRequest(FileTransferFrontierRequestFrameV6 request)
        => string.Equals(request.Priority, V6RegularNknStateRefreshStaleCreditPriority, StringComparison.Ordinal);

    private static bool IsPostTunaFallbackTailReconciliationStateRefresh(FileTransferFrontierRequestFrameV6 request)
        => string.Equals(request.Priority, V6RegularNknStateRefreshTailReconciliationPriority, StringComparison.Ordinal);

    private static long ResolveOutboundV6SparseRuntimeStateRefreshTransportEpoch(OutboundTransferContext context)
        => context.RouteRuntime.UsesPostTunaFallbackV6Runtime
            ? ResolveOutboundFallbackCurrentTransportEpochLocked(context)
            : context.V6TransportEpoch?.EpochId ??
              context.V6TransportHandoff?.EpochId ??
              Math.Max(0, context.PullTransportRebindGeneration);

    private static bool TryPreserveOutboundPostTunaFallbackTailCheckpointAfterSendFailureLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason,
        bool stateRefreshSendTimeout)
    {
        var leg = context.CurrentTransferLeg;
        if (!IsCurrentPostTunaFallbackTailReconciliationCheckpointPending(leg) ||
            !string.Equals(leg!.CheckpointRequestId, request.RepairRequestId, StringComparison.Ordinal))
        {
            return false;
        }

        if (context.V6RegularNknStateRefreshFailureCount >=
            V6PostTunaFallbackTailCheckpointSendFailurePreserveLimit)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_fallback_tail_checkpoint_delivery_failure_limit_reached; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; leg_id={FormatProtocolLogValue(leg.LegId)}; leg_generation={leg.Generation}; route={leg.RouteSelection.TelemetryToken}; protocol_version={leg.ProtocolVersion}; live_route_epoch={leg.LiveRouteEpochId}; transport_epoch={leg.TransportEpochId}; checkpoint_request_id={FormatProtocolLogValue(leg.CheckpointRequestId ?? "(none)")}; request_transport_epoch={request.TransportEpoch}; state={FormatFileTransferLegState(leg.State)}; can_send_data={(leg.CanSendData ? 1 : 0)}; reason={FormatProtocolLogValue(reason)}; state_refresh_send_timeout={(stateRefreshSendTimeout ? 1 : 0)}; failure_count={context.V6RegularNknStateRefreshFailureCount}; preserve_limit={V6PostTunaFallbackTailCheckpointSendFailurePreserveLimit}");
            MarkOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
                context,
                leg,
                request,
                reason,
                stateRefreshSendTimeout);
            return false;
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_fallback_tail_checkpoint_preserved_after_send_failure; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; leg_id={FormatProtocolLogValue(leg.LegId)}; leg_generation={leg.Generation}; route={leg.RouteSelection.TelemetryToken}; protocol_version={leg.ProtocolVersion}; live_route_epoch={leg.LiveRouteEpochId}; transport_epoch={leg.TransportEpochId}; checkpoint_request_id={FormatProtocolLogValue(leg.CheckpointRequestId ?? "(none)")}; request_transport_epoch={request.TransportEpoch}; state={FormatFileTransferLegState(leg.State)}; can_send_data={(leg.CanSendData ? 1 : 0)}; reason={FormatProtocolLogValue(reason)}; state_refresh_send_timeout={(stateRefreshSendTimeout ? 1 : 0)}");
        return true;
    }

    private static bool TryPreserveOutboundPostTunaFallbackCheckpointAfterSendFailureLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        string reason,
        bool stateRefreshSendTimeout)
    {
        if (TryPreserveOutboundPostTunaFallbackTailCheckpointAfterSendFailureLocked(
                context,
                request,
                reason,
                stateRefreshSendTimeout))
        {
            return true;
        }

        var leg = context.CurrentTransferLeg;
        if (IsCurrentPostTunaFallbackTailReconciliationCheckpointPending(leg) &&
            string.Equals(leg!.CheckpointRequestId, request.RepairRequestId, StringComparison.Ordinal))
        {
            return false;
        }

        if (!IsCurrentPostTunaFallbackLegCheckpointPending(leg) ||
            !string.Equals(leg!.CheckpointRequestId, request.RepairRequestId, StringComparison.Ordinal))
        {
            return false;
        }

        if (context.V6RegularNknStateRefreshFailureCount >=
            V6PostTunaFallbackCheckpointSendFailurePreserveLimit)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_fallback_checkpoint_delivery_failure_limit_reached; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; leg_id={FormatProtocolLogValue(leg.LegId)}; leg_generation={leg.Generation}; route={leg.RouteSelection.TelemetryToken}; protocol_version={leg.ProtocolVersion}; live_route_epoch={leg.LiveRouteEpochId}; transport_epoch={leg.TransportEpochId}; checkpoint_request_id={FormatProtocolLogValue(leg.CheckpointRequestId ?? "(none)")}; request_transport_epoch={request.TransportEpoch}; priority={FormatProtocolLogValue(leg.CheckpointPriority ?? "(none)")}; state={FormatFileTransferLegState(leg.State)}; can_send_data={(leg.CanSendData ? 1 : 0)}; reason={FormatProtocolLogValue(reason)}; state_refresh_send_timeout={(stateRefreshSendTimeout ? 1 : 0)}; failure_count={context.V6RegularNknStateRefreshFailureCount}; preserve_limit={V6PostTunaFallbackCheckpointSendFailurePreserveLimit}");
            MarkOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
                context,
                leg,
                request,
                reason,
                stateRefreshSendTimeout);
            return false;
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_fallback_checkpoint_preserved_after_send_failure; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; leg_id={FormatProtocolLogValue(leg.LegId)}; leg_generation={leg.Generation}; route={leg.RouteSelection.TelemetryToken}; protocol_version={leg.ProtocolVersion}; live_route_epoch={leg.LiveRouteEpochId}; transport_epoch={leg.TransportEpochId}; checkpoint_request_id={FormatProtocolLogValue(leg.CheckpointRequestId ?? "(none)")}; request_transport_epoch={request.TransportEpoch}; priority={FormatProtocolLogValue(leg.CheckpointPriority ?? "(none)")}; state={FormatFileTransferLegState(leg.State)}; can_send_data={(leg.CanSendData ? 1 : 0)}; reason={FormatProtocolLogValue(reason)}; state_refresh_send_timeout={(stateRefreshSendTimeout ? 1 : 0)}");
        return true;
    }

    private static void MarkOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
        OutboundTransferContext context,
        FileTransferLeg leg,
        FileTransferFrontierRequestFrameV6 request,
        string reason,
        bool stateRefreshSendTimeout)
    {
        var wasPending = context.V6RegularNknFallbackCheckpointDeliveryRecoveryPending;
        var previousRequestId = context.V6RegularNknFallbackCheckpointDeliveryRecoveryRequestId;
        context.V6RegularNknFallbackCheckpointDeliveryRecoveryPending = true;
        context.V6RegularNknFallbackCheckpointDeliveryRecoveryStartedUtc = DateTimeOffset.UtcNow;
        context.V6RegularNknFallbackCheckpointDeliveryRecoveryReason = reason;
        context.V6RegularNknFallbackCheckpointDeliveryRecoveryRequestId = request.RepairRequestId;

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_fallback_checkpoint_delivery_recovery_pending; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; leg_id={FormatProtocolLogValue(leg.LegId)}; leg_generation={leg.Generation}; route={leg.RouteSelection.TelemetryToken}; protocol_version={leg.ProtocolVersion}; live_route_epoch={leg.LiveRouteEpochId}; transport_epoch={leg.TransportEpochId}; checkpoint_request_id={FormatProtocolLogValue(leg.CheckpointRequestId ?? "(none)")}; request_id={FormatProtocolLogValue(request.RepairRequestId ?? "(none)")}; previous_request_id={FormatProtocolLogValue(previousRequestId ?? "(none)")}; already_pending={(wasPending ? 1 : 0)}; priority={FormatProtocolLogValue(leg.CheckpointPriority ?? request.Priority ?? "(none)")}; reason={FormatProtocolLogValue(reason)}; state_refresh_send_timeout={(stateRefreshSendTimeout ? 1 : 0)}; failure_count={context.V6RegularNknStateRefreshFailureCount}; recovery_cooldown_ms={(long)CurrentV6SenderRequestFeedbackStallRecoveryCooldown.TotalMilliseconds}");
    }

    private static void ClearOutboundFallbackCheckpointDeliveryRecoveryPendingLocked(
        OutboundTransferContext context,
        string reason)
    {
        if (!context.V6RegularNknFallbackCheckpointDeliveryRecoveryPending)
        {
            return;
        }

        var requestId = context.V6RegularNknFallbackCheckpointDeliveryRecoveryRequestId;
        var pendingReason = context.V6RegularNknFallbackCheckpointDeliveryRecoveryReason;
        var ageMs = FormatNullableDurationMs(
            context.V6RegularNknFallbackCheckpointDeliveryRecoveryStartedUtc,
            DateTimeOffset.UtcNow);

        context.V6RegularNknFallbackCheckpointDeliveryRecoveryPending = false;
        context.V6RegularNknFallbackCheckpointDeliveryRecoveryStartedUtc = null;
        context.V6RegularNknFallbackCheckpointDeliveryRecoveryReason = null;
        context.V6RegularNknFallbackCheckpointDeliveryRecoveryRequestId = null;

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_fallback_checkpoint_delivery_recovery_cleared; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; request_id={FormatProtocolLogValue(requestId ?? "(none)")}; pending_reason={FormatProtocolLogValue(pendingReason ?? "(none)")}; reason={FormatProtocolLogValue(reason)}; pending_age_ms={ageMs}; failure_count={context.V6RegularNknStateRefreshFailureCount}");
    }

    private static bool IsPostTunaFallbackTailReconciliationStateRefresh(FileTransferReceiverStateFrameV6 state)
        => string.Equals(state.Priority, V6RegularNknStateRefreshTailReconciliationPriority, StringComparison.Ordinal);

    private static void MaybeLogOutboundV4SparseRuntimePeerSilenceDeferralLocked(
        OutboundTransferContext context,
        string reason,
        TimeSpan silence,
        TimeSpan timeout)
    {
        var now = DateTimeOffset.UtcNow;
        if (context.PullV4PeerSilenceDeferralUtc is { } lastLog &&
            now - lastLog < TimeSpan.FromSeconds(10))
        {
            context.PullV4PeerSilenceDeferralCount++;
            return;
        }

        context.PullV4PeerSilenceDeferralUtc = now;
        context.PullV4PeerSilenceDeferralCount++;
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_peer_feedback_timeout_deferred_for_v6_regular_nkn_sparse_runtime; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={reason}; deferral_count={context.PullV4PeerSilenceDeferralCount}; silence_ms={(long)Math.Max(0, silence.TotalMilliseconds)}; timeout_ms={(long)timeout.TotalMilliseconds}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; bytes_transferred={context.BytesTransferred}; bytes_accepted_for_transport={context.BytesAcceptedForTransport}; pending_repair_count={context.PullV4SenderPumpRepairRequests.Count}");
    }

