    private static TimeSpan ResolveV4PeerSilenceTimeout(bool postFallback)
        => V4PeerSilenceTimeoutOverrideForTests ??
           (postFallback ? PullV4PostFallbackPeerSilenceTimeout : PullV4PeerSilenceTimeout);

    private static bool IsOutboundPostTunaRecoveryActiveLocked(OutboundTransferContext context)
        => context.PullPostTunaRecoveryActive ||
           context.PullTransportRebindGeneration > 0 ||
           IsRecoveredV6TunaFallbackEpochLocked(context.LastRecoveredV6TransportEpochKind, context.LastRecoveredV6TransportTargetTransport);

    private static bool IsInboundPostTunaRecoveryActiveLocked(InboundTransferContext context)
        => context.PullPostTunaRecoveryActive ||
           context.PullTransportRebindGeneration > 0 ||
           IsRecoveredV6TunaFallbackEpochLocked(context.LastRecoveredV6TransportEpochKind, context.LastRecoveredV6TransportTargetTransport);

    private static bool IsOutboundFileTunaV4PostTunaRecoveryActiveLocked(OutboundTransferContext context)
        => context.RouteRuntime.UsesFileTunaV4Runtime &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           IsOutboundPostTunaRecoveryActiveLocked(context);

    private static bool IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(OutboundTransferContext context)
        => IsCurrentPostTunaFallbackV6RouteOwner(context) &&
           IsOutboundPostTunaRecoveryActiveLocked(context);

    private static bool HasCurrentOutboundPostTunaFallbackFrontierRepairAuthorityLocked(OutboundTransferContext context)
        => IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(context) &&
           IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg);

    private static bool IsCurrentRegularV4FrontierRepairLeg(FileTransferLeg? leg)
        => leg is not null &&
           string.Equals(leg.RouteSelection.TelemetryToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) &&
           leg.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;

    private static bool IsCurrentFileTunaV4FrontierRepairLeg(FileTransferLeg? leg)
        => leg is not null &&
           string.Equals(leg.RouteSelection.TelemetryToken, FileTransferRouteResolver.FileTunaV4Token, StringComparison.Ordinal) &&
           leg.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;

    private static bool IsCurrentV4FrontierRepairLeg(FileTransferLeg? leg)
        => IsCurrentRegularV4FrontierRepairLeg(leg) ||
           IsCurrentFileTunaV4FrontierRepairLeg(leg);

    private static bool IsV4FrontierRepairRouteToken(string? routeToken)
        => string.Equals(routeToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) ||
           string.Equals(routeToken, FileTransferRouteResolver.FileTunaV4Token, StringComparison.Ordinal);

    private static FileTransferTransportKind ResolveV4FrontierRepairTargetTransport(string routeToken)
        => string.Equals(routeToken, FileTransferRouteResolver.FileTunaV4Token, StringComparison.Ordinal)
            ? FileTransferTransportKind.Tuna
            : string.Equals(routeToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal)
                ? FileTransferTransportKind.RegularNkn
                : FileTransferTransportKind.Unknown;

    private static bool IsCurrentRegularV4FrontierRepairRuntime(OutboundTransferContext context)
        => context.RouteRuntime.UsesRegularNknV4FastRuntime &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           IsCurrentRegularV4FrontierRepairLeg(context.CurrentTransferLeg);

    private static bool IsCurrentRegularV4FrontierRepairRuntime(InboundTransferContext context)
        => context.RouteRuntime.UsesRegularNknV4FastRuntime &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           IsCurrentRegularV4FrontierRepairLeg(context.CurrentTransferLeg);

    private static bool IsCurrentV4FrontierRepairRuntime(OutboundTransferContext context)
        => context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           IsCurrentV4FrontierRepairLeg(context.CurrentTransferLeg) &&
           ((context.RouteRuntime.UsesRegularNknV4FastRuntime && IsCurrentRegularV4FrontierRepairLeg(context.CurrentTransferLeg)) ||
            (context.RouteRuntime.UsesFileTunaV4Runtime && IsCurrentFileTunaV4FrontierRepairLeg(context.CurrentTransferLeg)));

    private static bool IsCurrentV4FrontierRepairRuntime(InboundTransferContext context)
        => context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           IsCurrentV4FrontierRepairLeg(context.CurrentTransferLeg) &&
           ((context.RouteRuntime.UsesRegularNknV4FastRuntime && IsCurrentRegularV4FrontierRepairLeg(context.CurrentTransferLeg)) ||
            (context.RouteRuntime.UsesFileTunaV4Runtime && IsCurrentFileTunaV4FrontierRepairLeg(context.CurrentTransferLeg)));

    private static bool IsCurrentV4FrontierRepairPublicationToken(
        RoutePublicationToken token,
        FileTransferLeg? leg)
    {
        if (leg is null ||
            token.ProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            !IsV4FrontierRepairRouteToken(token.RouteToken) ||
            !string.Equals(token.RouteToken, leg.RouteSelection.TelemetryToken, StringComparison.Ordinal) ||
            token.LegGeneration != leg.Generation ||
            token.TargetProtocolVersion != FileTransferProtocol.ProtocolVersionV4)
        {
            return false;
        }

        var expectedTransport = ResolveV4FrontierRepairTargetTransport(token.RouteToken);
        return token.TargetTransport == expectedTransport ||
               token.TargetTransport == FileTransferTransportKind.Unknown;
    }

    private static bool ShouldLogRegularV4FrontierRepairProof(
        RepairReplayKind repairKind,
        FileTransferLeg? leg,
        bool frontierRepair)
        => frontierRepair &&
           (repairKind == RepairReplayKind.V4Repair ||
            repairKind == RepairReplayKind.PeerSilenceReplay ||
            (repairKind == RepairReplayKind.TransportRebindSafetyReplay &&
             IsCurrentFileTunaV4FrontierRepairLeg(leg))) &&
           IsCurrentV4FrontierRepairLeg(leg);

    private static bool IsQueuedV4FrontierRepair(PullV4QueuedRepairSend repairSend)
        => repairSend.FrontierRepair ||
           repairSend.FrontierTailRepair ||
           repairSend.FirstStartChunkIndex == repairSend.RemoteNextExpectedChunkIndex;

    private static RegularV4FrontierRepairContract? CreateRegularV4FrontierRepairContract(
        OutboundTransferContext context,
        RepairReplayDecision? repairDecision,
        string repairKey,
        int frontierChunkIndex,
        int durableReceivedHighestChunkIndex,
        int pendingRepairCount,
        string decisionReason,
        string pressureReason,
        out string rejectionReason)
    {
        rejectionReason = "repair_replay_decision_missing";
        if (repairDecision is not { } decision)
        {
            return null;
        }

        var bindingDecision = FileTransferCoordinator.StageRegularV4FrontierRepairPressureBinding(
            CreateCoordinatorStateLocked(context),
            decision,
            new RegularV4FrontierRepairAuthorityRequest(
                repairKey,
                frontierChunkIndex,
                durableReceivedHighestChunkIndex,
                pendingRepairCount,
                decisionReason,
                Math.Max(0, durableReceivedHighestChunkIndex - frontierChunkIndex + 1)),
            pressureReason);
        _ = AdoptCoordinatorStateLocked(context, bindingDecision);
        if (bindingDecision.Status == RegularV4FrontierRepairPressureBindingDecisionStatus.Rejected ||
            bindingDecision.Binding is not { } binding)
        {
            rejectionReason = bindingDecision.Reason;
            return null;
        }

        return CreateRegularV4FrontierRepairContract(decision, binding.Authority);
    }

    private static RegularV4FrontierRepairContract? CreateRegularV4FrontierRepairContract(
        InboundTransferContext context,
        RepairReplayDecision? repairDecision,
        string repairKey,
        int frontierChunkIndex,
