                repairKey,
                frontierChunkIndex,
                durableReceivedHighestChunkIndex,
                pendingRepairCount,
                decisionReason,
                Math.Max(0, durableReceivedHighestChunkIndex - frontierChunkIndex + 1)),
            pressureReason);
        _ = AdoptCoordinatorStateLocked(context, bindingDecision);
        if (bindingDecision.Status == RegularV4FrontierRepairPressureBindingDecisionStatus.Rejected ||
            bindingDecision.Binding is not { } binding)
        {
            rejectionReason = bindingDecision.Reason;
            return null;
        }

        return CreateRegularV4FrontierRepairContract(decision, binding.Authority);
    }

    private static RegularV4FrontierRepairContract CreateRegularV4FrontierRepairContract(
        RepairReplayDecision decision,
        FileTransferRegularV4FrontierRepairAuthority authority)
    {
        return new RegularV4FrontierRepairContract
        {
            RepairDecision = decision,
            Authority = authority,
            Lifecycle = new FileTransferAuthorityLifecycle<FileTransferRegularV4FrontierRepairSettlementOutcome>(
                authority.AuthorityId),
        };
    }

    private static bool TryGetPendingOrInstalledRegularV4FrontierRepairPressure(
        FileTransferCoordinatorState state,
        FileTransferAuthorityId authorityId,
        out RegularV4FrontierRepairPressureBinding binding,
        out FileTransferRegularV4FrontierRepairPressureInstallCommand command)
    {
        if (FileTransferCoordinator.TryGetPendingRegularV4FrontierRepairPressureInstall(
                state,
                authorityId,
                out var pending,
                out var pendingCommand))
        {
            binding = pending;
            command = pendingCommand;
            return true;
        }

        if (FileTransferCoordinator.TryGetInstalledRegularV4FrontierRepairPressureInstall(
                state,
                authorityId,
                out var installed,
                out var installedCommand,
                out _))
        {
            binding = installed;
            command = installedCommand;
            return true;
        }

        binding = default;
        command = default!;
        return false;
    }

    private static bool TryGetInstalledRegularV4FrontierRepairPressure(
        FileTransferCoordinatorState state,
        FileTransferAuthorityId authorityId,
        out RegularV4FrontierRepairPressureBinding binding,
        out FileTransferRegularV4FrontierRepairPressureInstallCommand command,
        out FileTransferRegularV4FrontierRepairPressureInstallReceipt receipt)
    {
        if (FileTransferCoordinator.TryGetInstalledRegularV4FrontierRepairPressureInstall(
                state,
                authorityId,
                out var installed,
                out var installedCommand,
                out var installedReceipt))
        {
            binding = installed;
            command = installedCommand;
            receipt = installedReceipt;
            return true;
        }

        binding = default;
        command = default!;
        receipt = default!;
        return false;
    }

    private static long GetRegularV4FrontierRepairPressureInstallGeneration(
        FileTransferCoordinatorState state,
        RegularV4FrontierRepairContract? contract)
    {
        if (contract is null)
        {
            return 0;
        }

        if (FileTransferCoordinator.TryGetPendingRegularV4FrontierRepairPressureInstall(
                state,
                contract.Authority.AuthorityId,
                out var pending,
                out _))
        {
            return pending.InstallGeneration;
        }

        if (FileTransferCoordinator.TryGetInstalledRegularV4FrontierRepairPressureInstall(
                state,
                contract.Authority.AuthorityId,
                out var installed,
                out _,
                out _))
        {
            return installed.InstallGeneration;
        }

        var pressure = FileTransferCoordinator.GetRegularV4FrontierRepairPressureSubstate(state);
        if (pressure.RetainedPredecessorBinding is { } retained &&
            retained.Authority.AuthorityId == contract.Authority.AuthorityId)
        {
            return retained.InstallGeneration;
        }

        return 0;
    }

    private static bool IsRegularV4FrontierRepairContractCurrent(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
        => FileTransferCoordinator.IsRepairReplayDecisionCurrent(
            CreateCoordinatorStateLocked(context),
            contract.RepairDecision,
            out rejectionReason);

    private static bool IsRegularV4FrontierRepairContractCurrent(
        InboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
        => FileTransferCoordinator.IsRepairReplayDecisionCurrent(
            CreateCoordinatorStateLocked(context),
            contract.RepairDecision,
            out rejectionReason);

    private bool IsRegularV4FrontierRepairPressureInstallScopeCurrentLocked(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
    {
        if (!ReferenceEquals(outboundTransfer, context))
        {
            rejectionReason = "transfer_context_replaced";
            return false;
        }

        if (!ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, contract))
        {
            rejectionReason = "repair_contract_replaced";
            return false;
        }

        if (!IsRegularV4FrontierRepairContractCurrent(context, contract, out rejectionReason))
        {
            return false;
        }

        return IsRegularV4FrontierRepairPressureInstallAuthorityScopeCurrent(
            context.IsTerminal,
            IsCurrentV4FrontierRepairRuntime(context),
            context.SessionId,
            context.TransferId,
            FileTransferDirection.Outbound,
            context.CurrentRuntimeOwner,
            context.CurrentRoutePublicationToken,
            context.CurrentTransferLeg,
            context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ?? 0,
            context.DataSession is not null,
            context.DataSessionGeneration,
            contract,
            out rejectionReason);
    }

    private bool IsRegularV4FrontierRepairPressureInstallScopeCurrentLocked(
        InboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
    {
        if (!ReferenceEquals(inboundTransfer, context))
        {
            rejectionReason = "transfer_context_replaced";
            return false;
        }

        if (!ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, contract))
        {
            rejectionReason = "repair_contract_replaced";
            return false;
        }

        if (!IsRegularV4FrontierRepairContractCurrent(context, contract, out rejectionReason))
        {
            return false;
        }

        return IsRegularV4FrontierRepairPressureInstallAuthorityScopeCurrent(
            context.IsTerminal,
            IsCurrentV4FrontierRepairRuntime(context),
            context.SessionId,
            context.TransferId,
            FileTransferDirection.Inbound,
            context.CurrentRuntimeOwner,
            context.CurrentRoutePublicationToken,
            context.CurrentTransferLeg,
            context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ?? 0,
            context.DataSession is not null,
            context.DataSessionGeneration,
            contract,
            out rejectionReason);
    }

    private static bool IsRegularV4FrontierRepairPressureInstallAuthorityScopeCurrent(
        bool terminal,
        bool runtimeCurrent,
        string sessionId,
        string transferId,
        FileTransferDirection direction,
        RuntimeOwnerToken? currentOwner,
        RoutePublicationToken? currentPublication,
        FileTransferLeg? currentLeg,
        int currentBridgeDecisionGeneration,
        bool dataSessionPresent,
        long dataSessionGeneration,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        var authority = contract.Authority;
        if (terminal || contract.Lifecycle.IsSettled)
        {
            rejectionReason = "transfer_terminal_or_contract_settled";
            return false;
        }

        if (!runtimeCurrent)
        {
            rejectionReason = "regular_v4_runtime_replaced";
            return false;
        }

        if (!string.Equals(sessionId, authority.SessionId, StringComparison.Ordinal) ||
            !string.Equals(transferId, authority.TransferId, StringComparison.Ordinal) ||
            authority.Direction != direction)
        {
            rejectionReason = "transfer_identity_mismatch";
            return false;
        }

        if (currentOwner is not { IsDefault: false } owner ||
            !string.Equals(owner.SessionId, authority.SessionId, StringComparison.Ordinal) ||
            !string.Equals(owner.TransferId, authority.TransferId, StringComparison.Ordinal) ||
            owner.Direction != authority.Direction ||
            !string.Equals(owner.RouteToken, authority.RouteToken, StringComparison.Ordinal) ||
            owner.ProtocolVersion != authority.ProtocolVersion ||
            owner.LiveRouteEpoch != authority.LiveRouteEpoch ||
            owner.RuntimeGeneration != authority.RuntimeGeneration ||
            owner.TerminalGeneration != authority.TerminalGeneration)
        {
            rejectionReason = "runtime_owner_mismatch";
            return false;
        }

        if (currentPublication is not { IsDefault: false } publication ||
            !string.Equals(publication.SessionId, authority.SessionId, StringComparison.Ordinal) ||
            !string.Equals(publication.TransferId, authority.TransferId, StringComparison.Ordinal) ||
            publication.Direction != authority.Direction ||
            !string.Equals(publication.RouteToken, authority.RouteToken, StringComparison.Ordinal) ||
            publication.ProtocolVersion != authority.ProtocolVersion ||
            publication.LiveRouteEpoch != authority.LiveRouteEpoch ||
            publication.RuntimeGeneration != authority.RuntimeGeneration ||
            publication.TerminalGeneration != authority.TerminalGeneration ||
            publication.LegGeneration != authority.LegGeneration ||
            publication.PublicationGeneration != authority.RoutePublicationGeneration ||
            publication.RouteCommitGeneration != authority.RouteCommitGeneration ||
            publication.TargetTransport != authority.TargetTransport)
        {
            rejectionReason = "route_publication_mismatch";
            return false;
        }

        if (currentLeg is not { } leg ||
            leg.Generation != authority.LegGeneration ||
            leg.ProtocolVersion != authority.ProtocolVersion ||
            leg.LiveRouteEpochId != authority.LiveRouteEpoch ||
            leg.TransportEpochId != authority.TransportEpoch ||
            leg.BridgeRecoveryGeneration != authority.BridgeRecoveryGeneration ||
            !string.Equals(leg.RouteSelection.TelemetryToken, authority.RouteToken, StringComparison.Ordinal))
        {
            rejectionReason = "transfer_leg_mismatch";
            return false;
        }

        if (currentBridgeDecisionGeneration != authority.BridgeDecisionGeneration)
        {
            rejectionReason = "bridge_decision_generation_mismatch";
            return false;
        }

        if (!dataSessionPresent)
        {
            rejectionReason = "data_session_generation_mismatch";
            return false;
        }

        return true;
    }

    private static RegularV4FrontierRepairScheduledDispatch CreateRegularV4FrontierRepairScheduledDispatch(
        PullV4QueuedRepairSend repairSend,
        RepairReplayKind repairReplayKind)
        => new(
            repairSend.RepairRequestKey,
            repairReplayKind,
            repairSend.FirstStartChunkIndex,
            repairSend.LastEndChunkExclusive,
            repairSend.ChunkIndices.ToImmutableArray());

    private static bool IsRegularV4FrontierRepairScheduledDispatchMatch(
        RegularV4FrontierRepairScheduledDispatch scheduledDispatch,
        PullV4QueuedRepairSend repairSend,
        RepairReplayKind repairReplayKind)
        => string.Equals(scheduledDispatch.RepairKey, repairSend.RepairRequestKey, StringComparison.Ordinal) &&
           scheduledDispatch.RepairReplayKind == repairReplayKind &&
           scheduledDispatch.StartChunkIndex == repairSend.FirstStartChunkIndex &&
           scheduledDispatch.EndChunkExclusive == repairSend.LastEndChunkExclusive &&
           scheduledDispatch.ChunkIndices.SequenceEqual(repairSend.ChunkIndices);

    private static bool TryBindRegularV4FrontierRepairScheduledDispatch(
        RegularV4FrontierRepairContract contract,
        PullV4QueuedRepairSend repairSend,
        RepairReplayKind repairReplayKind,
        out string rejectionReason)
    {
        if (contract.ScheduledDispatch is not { } scheduledDispatch)
        {
            contract.ScheduledDispatch = CreateRegularV4FrontierRepairScheduledDispatch(
                repairSend,
                repairReplayKind);
            rejectionReason = "accepted";
            return true;
        }

        if (IsRegularV4FrontierRepairScheduledDispatchMatch(
                scheduledDispatch,
                repairSend,
                repairReplayKind))
        {
            rejectionReason = "idempotent";
            return true;
        }

        rejectionReason = "scheduled_repair_range_mismatch";
        return false;
    }

    private bool TryValidateOutboundRegularV4FrontierRepairContractLocked(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
    {
        if (!IsRegularV4FrontierRepairPressureInstallScopeCurrentLocked(
                context,
                contract,
                out rejectionReason))
        {
            return false;
        }

        var state = CreateCoordinatorStateLocked(context);
        if (!TryGetInstalledRegularV4FrontierRepairPressure(
                state,
                contract.Authority.AuthorityId,
                out var installedBinding,
                out _,
                out var installReceipt) ||
            installedBinding.State != RegularV4FrontierRepairPressureBindingState.Installed ||
            installedBinding.InstallGeneration <= 0 ||
            installedBinding.Authority != contract.Authority)
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_binding_not_installed";
            return false;
        }

        if (installReceipt.InstallGeneration != installedBinding.InstallGeneration)
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_install_generation_mismatch";
            return false;
        }

        if (!IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                contract,
                contract.Authority.PredecessorAuthorityId,
                installedBinding.PressureReason,
                installReceipt,
                out rejectionReason))
        {
            return false;
        }

        rejectionReason = "accepted";
        return true;
    }

    private bool TryValidateOutboundRegularV4FrontierRepairDispatchLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend repairSend,
        RepairReplayKind repairReplayKind,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
    {
        if (!TryValidateOutboundRegularV4FrontierRepairContractLocked(
                context,
                contract,
                out rejectionReason))
        {
            return false;
        }

        if (contract.ScheduledDispatch is not { } scheduledDispatch)
        {
            rejectionReason = "scheduled_repair_range_missing";
            return false;
        }

        if (!IsRegularV4FrontierRepairScheduledDispatchMatch(
                scheduledDispatch,
                repairSend,
                repairReplayKind))
        {
            rejectionReason = "scheduled_repair_range_mismatch";
            return false;
        }

        if (repairSend.RuntimeOwner != context.CurrentRuntimeOwner ||
            repairSend.RuntimeOwner != contract.RepairDecision.RuntimeOwner)
        {
            rejectionReason = "repair_runtime_owner_mismatch";
            return false;
        }

        if (contract.RepairDecision.RepairKind != repairReplayKind)
        {
            rejectionReason = "repair_replay_kind_mismatch";
            return false;
        }

        if (!string.Equals(repairSend.RepairRequestKey, contract.Authority.RepairKey, StringComparison.Ordinal))
        {
            rejectionReason = "repair_request_key_mismatch";
            return false;
        }

        if (repairSend.ChunkIndices.Count == 0 ||
            repairSend.FirstStartChunkIndex < 0 ||
            repairSend.LastEndChunkExclusive <= repairSend.FirstStartChunkIndex ||
            repairSend.ChunkIndices.Any(chunkIndex =>
                chunkIndex < repairSend.FirstStartChunkIndex ||
                chunkIndex >= repairSend.LastEndChunkExclusive) ||
            repairSend.ChunkIndices.Distinct().Count() != repairSend.ChunkIndices.Count)
        {
            rejectionReason = "scheduled_repair_range_mismatch";
            return false;
        }

        if (contract.Authority.FrontierChunkIndex != repairSend.RemoteNextExpectedChunkIndex)
        {
            rejectionReason = "repair_frontier_mismatch";
            return false;
        }

        if (repairReplayKind == RepairReplayKind.PeerSilenceReplay)
        {
            if (repairSend.RangeCount != 1 ||
                contract.Authority.PendingRepairCount != repairSend.ChunkIndices.Count ||
                repairSend.ChunkIndices[0] != repairSend.FirstStartChunkIndex ||
                repairSend.ChunkIndices[^1] + 1 != repairSend.LastEndChunkExclusive ||
                repairSend.ChunkIndices.Where((chunkIndex, index) =>
                    chunkIndex != repairSend.FirstStartChunkIndex + index).Any())
            {
                rejectionReason = "peer_silence_scheduled_range_mismatch";
                return false;
            }
        }
        else if (contract.Authority.PendingRepairCount != repairSend.RequestedChunkCount)
        {
            rejectionReason = "scheduled_repair_chunk_count_mismatch";
            return false;
        }

        rejectionReason = "accepted";
        return true;
    }

    private bool TryValidateOutboundRegularV4FrontierRepairSubmissionLocked(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        RegularV4FrontierRepairScheduledDispatch scheduledDispatch,
        out string rejectionReason)
    {
        if (!TryValidateOutboundRegularV4FrontierRepairContractLocked(
                context,
                contract,
                out rejectionReason))
        {
            return false;
        }

        if (!ReferenceEquals(contract.ScheduledDispatch, scheduledDispatch))
        {
            rejectionReason = "scheduled_repair_range_replaced";
            return false;
        }

        rejectionReason = "accepted";
        return true;
    }

    private static FileTransferRegularV4FrontierRepairAuthority? GetCurrentRegularV4FrontierRepairAuthority(
        OutboundTransferContext context,
        string? repairKey = null)
    {
        var contract = context.CurrentRegularV4FrontierRepairContract;
        return contract is not null &&
               !contract.Lifecycle.IsSettled &&
               (string.IsNullOrWhiteSpace(repairKey) ||
                 string.Equals(contract.Authority.RepairKey, repairKey, StringComparison.Ordinal)) &&
               IsRegularV4FrontierRepairContractCurrent(context, contract, out _) &&
               IsCoordinatorInstalledRegularV4FrontierRepairPressureCurrent(
                   CreateCoordinatorStateLocked(context),
                   contract)
            ? contract.Authority
            : null;
    }

    private static FileTransferRegularV4FrontierRepairAuthority? GetCurrentRegularV4FrontierRepairAuthority(
        InboundTransferContext context,
        string? repairKey = null)
    {
        var contract = context.CurrentRegularV4FrontierRepairContract;
        return contract is not null &&
               !contract.Lifecycle.IsSettled &&
               (string.IsNullOrWhiteSpace(repairKey) ||
                 string.Equals(contract.Authority.RepairKey, repairKey, StringComparison.Ordinal)) &&
               IsRegularV4FrontierRepairContractCurrent(context, contract, out _) &&
               IsCoordinatorInstalledRegularV4FrontierRepairPressureCurrent(
                   CreateCoordinatorStateLocked(context),
                   contract)
            ? contract.Authority
            : null;
    }

    private static bool IsCoordinatorInstalledRegularV4FrontierRepairPressureCurrent(
        FileTransferCoordinatorState state,
        RegularV4FrontierRepairContract contract)
    {
        if (!TryGetInstalledRegularV4FrontierRepairPressure(
                state,
                contract.Authority.AuthorityId,
                out var binding,
                out _,
                out var receipt) ||
            binding.State != RegularV4FrontierRepairPressureBindingState.Installed ||
            binding.InstallGeneration <= 0 ||
            binding.Authority != contract.Authority)
        {
            return false;
        }

        return IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
            contract,
            contract.Authority.PredecessorAuthorityId,
            binding.PressureReason,
            receipt,
            out _);
    }

    private bool TryMarkRegularV4FrontierRepairDispatched(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract)
    {
        var pressureInstallPredecessorAuthorityId = contract.Authority.PredecessorAuthorityId;
        var pressureInstallRejectionReason =
            "regular_v4_frontier_repair_pressure_binding_not_installed";
        if (!TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                contract.Authority.AuthorityId,
                out var binding,
                out _,
                out var installReceipt) ||
            !IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                contract,
                pressureInstallPredecessorAuthorityId,
                binding.PressureReason,
                installReceipt,
                out pressureInstallRejectionReason))
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_frontier_repair_dispatch_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(contract.Authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(pressureInstallPredecessorAuthorityId?.ToString() ?? "(none)")}; repair_request_key={FormatProtocolLogValue(contract.Authority.RepairKey)}; decision_reason={FormatProtocolLogValue(pressureInstallRejectionReason)}");
            return false;
        }

        if (contract.Lifecycle.TryMarkDispatched())
        {
            contract.DispatchedUtc = DateTimeOffset.UtcNow;
            return true;
        }

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_frontier_repair_dispatch_duplicate_ignored; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(contract.Authority.AuthorityId.ToString())}; repair_request_key={FormatProtocolLogValue(contract.Authority.RepairKey)}; decision_reason=dispatch_already_observed_or_settled");
        return false;
    }

    private bool TrySettleRegularV4FrontierRepairContract(
        RegularV4FrontierRepairContract? contract,
        FileTransferRegularV4FrontierRepairSettlementOutcome outcome,
        int requestedChunkCount,
        string decisionReason,
        FileTransferAuthorityId? successorAuthorityId = null,
        bool notifyObserver = true)
    {
        if (contract is null)
        {
            return false;
        }

        var pressureInstallPredecessorAuthorityId = contract.Authority.PredecessorAuthorityId;
        var pressureInstallRejectionReason =
            "regular_v4_frontier_repair_pressure_binding_not_installed";
        if (!TryGetInstalledRegularV4FrontierRepairPressureForContract(
                contract,
                out var installedBinding,
                out var installedReceipt) ||
            !IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                contract,
                pressureInstallPredecessorAuthorityId,
                installedBinding.PressureReason,
                installedReceipt,
                out pressureInstallRejectionReason))
        {
            if (outcome is
                FileTransferRegularV4FrontierRepairSettlementOutcome.AuthorityRejected or
                FileTransferRegularV4FrontierRepairSettlementOutcome.TerminalRejected or
                FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected or
                FileTransferRegularV4FrontierRepairSettlementOutcome.TransferTerminal)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_regular_v4_frontier_repair_pressure_install_retirement_retry_requested; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(contract.Authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(pressureInstallPredecessorAuthorityId?.ToString() ?? "(none)")}; install_kind={(pressureInstallPredecessorAuthorityId is null ? "initial" : "successor")}; repair_request_key={FormatProtocolLogValue(contract.Authority.RepairKey)}; retirement_outcome={FormatProtocolLogValue(outcome.ToString())}; decision_reason={FormatProtocolLogValue(pressureInstallRejectionReason)}");
                if (!TryRetryRegularV4FrontierRepairPressureInstallForSettlement(contract) ||
                    !TryGetInstalledRegularV4FrontierRepairPressureForContract(
                        contract,
                        out installedBinding,
                        out installedReceipt) ||
                    !IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                        contract,
                        pressureInstallPredecessorAuthorityId,
                        installedBinding.PressureReason,
                        installedReceipt,
                        out pressureInstallRejectionReason))
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_regular_v4_frontier_repair_settlement_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(contract.Authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(pressureInstallPredecessorAuthorityId?.ToString() ?? "(none)")}; install_kind={(pressureInstallPredecessorAuthorityId is null ? "initial" : "successor")}; repair_request_key={FormatProtocolLogValue(contract.Authority.RepairKey)}; attempted_outcome={FormatProtocolLogValue(outcome.ToString())}; decision_reason={FormatProtocolLogValue(pressureInstallRejectionReason)}");
                    return false;
                }
            }
            else
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_regular_v4_frontier_repair_settlement_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(contract.Authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(pressureInstallPredecessorAuthorityId?.ToString() ?? "(none)")}; install_kind={(pressureInstallPredecessorAuthorityId is null ? "initial" : "successor")}; repair_request_key={FormatProtocolLogValue(contract.Authority.RepairKey)}; attempted_outcome={FormatProtocolLogValue(outcome.ToString())}; decision_reason={FormatProtocolLogValue(pressureInstallRejectionReason)}");
                return false;
            }
        }

        var authority = contract.Authority;

        var settlement = new FileTransferRegularV4FrontierRepairSettlement(
            authority.SessionId,
            authority.TransferId,
            authority.Direction,
            authority.RouteToken,
            authority.ProtocolVersion,
            authority.LiveRouteEpoch,
            authority.RuntimeGeneration,
            authority.TerminalGeneration,
            authority.LegGeneration,
            authority.TransportEpoch,
            authority.BridgeRecoveryGeneration,
            authority.BridgeDecisionGeneration,
            authority.RoutePublicationGeneration,
            authority.RouteCommitGeneration,
            authority.RepairKey,
            authority.FrontierChunkIndex,
            authority.DurableReceivedHighestChunkIndex,
            Math.Max(0, requestedChunkCount),
            authority.DecisionGeneration,
            string.IsNullOrWhiteSpace(decisionReason) ? authority.DecisionReason : decisionReason,
            outcome,
            authority.TargetTransport)
        {
            AuthorityId = authority.AuthorityId,
            SuccessorAuthorityId = successorAuthorityId is { IsDefault: false }
                ? successorAuthorityId
                : null,
        };

        var settlingInstalledBinding =
            installedBinding.State == RegularV4FrontierRepairPressureBindingState.Installed;
        var settlingRetainedPredecessor =
            installedBinding.State ==
                RegularV4FrontierRepairPressureBindingState.RetainedPredecessor &&
            outcome == FileTransferRegularV4FrontierRepairSettlementOutcome.Superseded &&
            successorAuthorityId is { IsDefault: false };
        if ((!settlingInstalledBinding && !settlingRetainedPredecessor) ||
            installedBinding.Authority != authority ||
            installedReceipt.InstallGeneration != installedBinding.InstallGeneration)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_frontier_repair_settlement_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(pressureInstallPredecessorAuthorityId?.ToString() ?? "(none)")}; install_kind={(pressureInstallPredecessorAuthorityId is null ? "initial" : "successor")}; repair_request_key={FormatProtocolLogValue(authority.RepairKey)}; attempted_outcome={FormatProtocolLogValue(outcome.ToString())}; decision_reason=coordinator_pressure_binding_not_installed");
            return false;
        }

        if (!TryApplyRegularV4FrontierRepairPressureSettlementLocked(
                settlement,
                out var settlementApplyReason))
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_frontier_repair_settlement_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(pressureInstallPredecessorAuthorityId?.ToString() ?? "(none)")}; install_kind={(pressureInstallPredecessorAuthorityId is null ? "initial" : "successor")}; repair_request_key={FormatProtocolLogValue(authority.RepairKey)}; attempted_outcome={FormatProtocolLogValue(outcome.ToString())}; decision_reason={FormatProtocolLogValue(settlementApplyReason)}");
            return false;
        }

        if (!contract.Lifecycle.TrySettle(outcome, decisionReason, successorAuthorityId))
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_frontier_repair_settlement_duplicate_ignored; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; successor_authority_id={FormatProtocolLogValue(successorAuthorityId?.ToString() ?? "(none)")}; repair_request_key={FormatProtocolLogValue(authority.RepairKey)}; attempted_outcome={FormatProtocolLogValue(outcome.ToString())}; settled_outcome={FormatProtocolLogValue(contract.Lifecycle.SettlementOutcome?.ToString() ?? "(none)")}; decision_reason={FormatProtocolLogValue(decisionReason)}");
            return false;
        }

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_frontier_repair_contract_settled; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; successor_authority_id={FormatProtocolLogValue(successorAuthorityId?.ToString() ?? "(none)")}; repair_request_key={FormatProtocolLogValue(authority.RepairKey)}; settlement_outcome={FormatProtocolLogValue(outcome.ToString())}; dispatch_observed={(contract.Lifecycle.DispatchObserved ? 1 : 0)}; decision_reason={FormatProtocolLogValue(decisionReason)}");
        if (!notifyObserver)
        {
            return true;
        }

        IFileTransferRegularV4FrontierRepairSettlementObserver? observer;
        lock (gate)
        {
            observer = transport as IFileTransferRegularV4FrontierRepairSettlementObserver;
        }

        lock (gate)
        {
            RecordCoordinatorIssuedRegularV4RecoverySettlementLocked(settlement);
        }

        if (observer is not null)
        {
            _ = Task.Run(() => observer.ObserveRegularV4FrontierRepairSettlement(settlement));
        }

        return true;
    }

    private bool TryApplyRegularV4FrontierRepairPressureSettlementLocked(
        FileTransferRegularV4FrontierRepairSettlement settlement,
        out string rejectionReason)
    {
        lock (gate)
        {
            var state = settlement.Direction == FileTransferDirection.Outbound
                ? outboundTransfer is { } outbound &&
                  string.Equals(outbound.SessionId, settlement.SessionId, StringComparison.Ordinal) &&
                  string.Equals(outbound.TransferId, settlement.TransferId, StringComparison.Ordinal)
                    ? CreateCoordinatorStateLocked(outbound)
                    : null
                : inboundTransfer is { } inbound &&
                  string.Equals(inbound.SessionId, settlement.SessionId, StringComparison.Ordinal) &&
                  string.Equals(inbound.TransferId, settlement.TransferId, StringComparison.Ordinal)
                    ? CreateCoordinatorStateLocked(inbound)
                    : null;
            if (state is null)
            {
                rejectionReason = "regular_v4_frontier_repair_pressure_settlement_context_missing";
                return false;
            }

            var prepared = FileTransferCoordinator.PrepareRegularV4FrontierRepairPressureSettlement(
                state,
                settlement);
            if (settlement.Direction == FileTransferDirection.Outbound &&
                outboundTransfer is { } preparedOutbound)
            {
                _ = AdoptCoordinatorStateLocked(preparedOutbound, prepared);
            }
            else if (settlement.Direction == FileTransferDirection.Inbound &&
                     inboundTransfer is { } preparedInbound)
            {
                _ = AdoptCoordinatorStateLocked(preparedInbound, prepared);
            }
            if (prepared.Status == RegularV4FrontierRepairPressureBindingDecisionStatus.Idempotent)
            {
                rejectionReason = prepared.Reason;
                return true;
            }

            if (prepared.Status != RegularV4FrontierRepairPressureBindingDecisionStatus.Accepted ||
                prepared.SettlementCommand is not { } command)
            {
                rejectionReason = prepared.Reason;
                return false;
            }

            if (transport is not IFileTransferRegularV4FrontierRepairPressureInstallBridge bridge)
            {
                rejectionReason = "regular_v4_frontier_repair_pressure_settlement_bridge_missing";
                return false;
            }

            FileTransferRegularV4FrontierRepairPressureSettlementApplyReceipt receipt;
            try
            {
                receipt = bridge.ApplyRegularV4FrontierRepairPressureSettlement(command);
            }
            catch (Exception ex)
            {
                rejectionReason =
                    $"regular_v4_frontier_repair_pressure_settlement_bridge_failed_{NormalizeReason(ex.GetType().Name)}";
                return false;
            }

            var committed = FileTransferCoordinator.CommitRegularV4FrontierRepairPressureSettlement(
                state,
                receipt);
            if (settlement.Direction == FileTransferDirection.Outbound && outboundTransfer is { } currentOutbound)
            {
                _ = AdoptCoordinatorStateLocked(currentOutbound, committed);
            }
            else if (settlement.Direction == FileTransferDirection.Inbound && inboundTransfer is { } currentInbound)
            {
                _ = AdoptCoordinatorStateLocked(currentInbound, committed);
            }

            if (committed.Status == RegularV4FrontierRepairPressureBindingDecisionStatus.Rejected)
            {
                rejectionReason = committed.Reason;
                return false;
            }

            LogRegularV4FrontierRepairPressureBinding(
                "filetransfer_regular_v4_frontier_repair_pressure_binding_retired",
                prepared.Binding!.Value.Authority,
                prepared.Binding,
                "settlement",
                committed.Reason);
            rejectionReason = committed.Reason;
            return true;
        }
    }

    private bool TryRetryRegularV4FrontierRepairPressureInstallForSettlement(
        RegularV4FrontierRepairContract contract)
    {
        lock (gate)
        {
            if (contract.Authority.Direction == FileTransferDirection.Outbound &&
                outboundTransfer is { } outbound &&
                FindPendingRegularV4FrontierRepairPressureInstallContractLocked(
                    outbound,
                    contract.Authority.AuthorityId) is { } outboundContract &&
                ReferenceEquals(outboundContract, contract))
            {
                return TryRetryRegularV4FrontierRepairPressureInstallLocked(outbound, contract);
            }

            if (contract.Authority.Direction == FileTransferDirection.Inbound &&
                inboundTransfer is { } inbound &&
                FindPendingRegularV4FrontierRepairPressureInstallContractLocked(
                    inbound,
                    contract.Authority.AuthorityId) is { } inboundContract &&
                ReferenceEquals(inboundContract, contract))
            {
                return TryRetryRegularV4FrontierRepairPressureInstallLocked(inbound, contract);
            }

            return false;
        }
    }

    private bool TryGetInstalledRegularV4FrontierRepairPressureForContract(
        RegularV4FrontierRepairContract contract,
        out RegularV4FrontierRepairPressureBinding binding,
        out FileTransferRegularV4FrontierRepairPressureInstallReceipt receipt)
    {
        lock (gate)
        {
            var state = contract.Authority.Direction switch
            {
                FileTransferDirection.Outbound
                    when outboundTransfer is { } outbound &&
                         string.Equals(
                             outbound.SessionId,
                             contract.Authority.SessionId,
                             StringComparison.Ordinal) &&
                         string.Equals(
                             outbound.TransferId,
                             contract.Authority.TransferId,
                             StringComparison.Ordinal)
                    => CreateCoordinatorStateLocked(outbound),
                FileTransferDirection.Inbound
                    when inboundTransfer is { } inbound &&
                         string.Equals(
                             inbound.SessionId,
                             contract.Authority.SessionId,
                             StringComparison.Ordinal) &&
                         string.Equals(
                             inbound.TransferId,
                             contract.Authority.TransferId,
                             StringComparison.Ordinal)
                    => CreateCoordinatorStateLocked(inbound),
                _ => null,
            };
            if (state is not null &&
                TryGetInstalledRegularV4FrontierRepairPressure(
                    state,
                    contract.Authority.AuthorityId,
                    out binding,
                    out _,
                    out receipt))
            {
                return true;
            }

            if (state is not null)
            {
                var pressure =
                    FileTransferCoordinator.GetRegularV4FrontierRepairPressureSubstate(state);
                if (pressure.RetainedPredecessorBinding is { } retained &&
                    pressure.RetainedPredecessorInstallReceipt is { } retainedReceipt &&
                    retained.Authority == contract.Authority &&
                    retainedReceipt.Authority == contract.Authority &&
                    retainedReceipt.InstallGeneration == retained.InstallGeneration &&
                    string.Equals(
                        retainedReceipt.PressureReason,
                        retained.PressureReason,
                        StringComparison.Ordinal))
                {
                    binding = retained;
                    receipt = retainedReceipt;
                    return true;
                }
            }
        }

        binding = default;
        receipt = default!;
        return false;
    }

    private RegularV4FrontierRepairContract? FindRegularV4FrontierRepairContractForAuthority(
        FileTransferDirection direction,
        string sessionId,
        string transferId,
        FileTransferAuthorityId authorityId)
    {
        lock (gate)
        {
            if (direction == FileTransferDirection.Outbound &&
                outboundTransfer is { } outbound &&
                string.Equals(outbound.SessionId, sessionId, StringComparison.Ordinal) &&
                string.Equals(outbound.TransferId, transferId, StringComparison.Ordinal))
            {
                if (outbound.CurrentRegularV4FrontierRepairContract is { } current &&
                    current.Authority.AuthorityId == authorityId)
                {
                    return current;
                }

                if (outbound.CurrentRegularV4FrontierRepairContract?.PredecessorLifecycleContract is
                        { } currentPredecessor &&
                    currentPredecessor.Authority.AuthorityId == authorityId)
                {
                    return currentPredecessor;
                }

                if (outbound.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract is
                        { } missingDispatch &&
                    missingDispatch.Authority.AuthorityId == authorityId)
                {
                    return missingDispatch;
                }

                return outbound.PullV4SenderPumpRepairRequests.Values
                    .Select(static candidate => candidate.RegularV4RepairContract)
                    .FirstOrDefault(candidate =>
                        candidate?.Authority.AuthorityId == authorityId);
            }

            if (direction == FileTransferDirection.Inbound &&
                inboundTransfer is { } inbound &&
                string.Equals(inbound.SessionId, sessionId, StringComparison.Ordinal) &&
                string.Equals(inbound.TransferId, transferId, StringComparison.Ordinal))
            {
                if (inbound.CurrentRegularV4FrontierRepairContract is { } current &&
                    current.Authority.AuthorityId == authorityId)
                {
                    return current;
                }

                var retained = new[]
                {
                    inbound.V4RegularFrontierRepairProjection?.SourceContract,
                    inbound.V4RegularFrontierRepairProjectionRefreshSource?.Projection.SourceContract,
                    inbound.V4RegularFrontierRepairSettledStalledContract,
                }.FirstOrDefault(candidate =>
                    candidate?.Authority.AuthorityId == authorityId);
                if (retained is not null)
                {
                    return retained;
                }

                return inbound.V4ReceiverRepairRequests.Values
                    .Select(static candidate => candidate.RegularV4RepairContract)
                    .FirstOrDefault(candidate =>
                        candidate?.Authority.AuthorityId == authorityId);
            }
        }

        return null;
    }

    private static RegularV4FrontierRepairContract?
        FindPendingRegularV4FrontierRepairPressureInstallContractLocked(
            OutboundTransferContext context,
            FileTransferAuthorityId authorityId)
    {
        if (!FileTransferCoordinator.TryGetPendingRegularV4FrontierRepairPressureInstall(
                CreateCoordinatorStateLocked(context),
                authorityId,
                out _,
                out _))
        {
            return null;
        }

        static bool Matches(
            RegularV4FrontierRepairContract? contract,
            FileTransferAuthorityId expectedAuthorityId)
            => contract is { Lifecycle.IsSettled: false } &&
               contract.Authority.AuthorityId == expectedAuthorityId;

        if (Matches(context.CurrentRegularV4FrontierRepairContract, authorityId))
        {
            return context.CurrentRegularV4FrontierRepairContract;
        }

        if (Matches(context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract, authorityId))
        {
            return context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract;
        }

        foreach (var repairState in context.PullV4SenderPumpRepairRequests.Values)
        {
            if (Matches(repairState.RegularV4RepairContract, authorityId))
            {
                return repairState.RegularV4RepairContract;
            }
        }

        return null;
    }

    private static RegularV4FrontierRepairContract?
        FindPendingRegularV4FrontierRepairPressureInstallContractLocked(
            InboundTransferContext context,
            FileTransferAuthorityId authorityId)
    {
        if (!FileTransferCoordinator.TryGetPendingRegularV4FrontierRepairPressureInstall(
                CreateCoordinatorStateLocked(context),
                authorityId,
                out _,
                out _))
        {
            return null;
        }

        static bool Matches(
            RegularV4FrontierRepairContract? contract,
            FileTransferAuthorityId expectedAuthorityId)
            => contract is { Lifecycle.IsSettled: false } &&
               contract.Authority.AuthorityId == expectedAuthorityId;

        if (Matches(context.CurrentRegularV4FrontierRepairContract, authorityId))
        {
            return context.CurrentRegularV4FrontierRepairContract;
        }

        if (Matches(context.V4RegularFrontierRepairProjection?.SourceContract, authorityId))
        {
            return context.V4RegularFrontierRepairProjection!.SourceContract;
        }

        if (Matches(
                context.V4RegularFrontierRepairProjectionRefreshSource?.Projection.SourceContract,
                authorityId))
        {
            return context.V4RegularFrontierRepairProjectionRefreshSource!.Projection.SourceContract;
        }

        if (Matches(context.V4RegularFrontierRepairSettledStalledContract, authorityId))
        {
            return context.V4RegularFrontierRepairSettledStalledContract;
        }

        foreach (var repairState in context.V4ReceiverRepairRequests.Values)
        {
            if (Matches(repairState.RegularV4RepairContract, authorityId))
            {
                return repairState.RegularV4RepairContract;
            }
        }

        return null;
    }

    private bool TryRetireRegularV4FrontierRepairPressureForScopeReplacementLocked(
        OutboundTransferContext context,
        string reason,
        FileTransferRegularV4FrontierRepairSettlementOutcome currentOutcome =
            FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected)
    {
        if (!TryInvalidatePendingOnlyRegularV4FrontierRepairPressureForDataSessionReplacementLocked(
                context,
                reason,
                out var invalidatedPendingSettlement))
        {
            return false;
        }

        if (invalidatedPendingSettlement is { } pendingSettlement)
        {
            pendingSettlement = pendingSettlement with { Outcome = currentOutcome };
            SettleRegularV4FrontierRepairContractsForDataSessionReplacementLocked(
                context,
                pendingSettlement);
        }

        var pressure = FileTransferCoordinator.GetRegularV4FrontierRepairPressureSubstate(
            CreateCoordinatorStateLocked(context));
        if (!TryRetireRegularV4FrontierRepairPressureBindingsLocked(
                pressure.RetainedPredecessorBinding,
                pressure.InstalledBinding,
                reason,
                currentOutcome,
                settlement =>
                    SettleRegularV4FrontierRepairContractsForDataSessionReplacementLocked(
                        context,
                        settlement)))
        {
            return false;
        }

        pressure = FileTransferCoordinator.GetRegularV4FrontierRepairPressureSubstate(
            CreateCoordinatorStateLocked(context));
        return pressure.PendingBinding is null &&
               pressure.InstalledBinding is null &&
               pressure.RetainedPredecessorBinding is null;
    }

