        return pressure.PendingBinding is null &&
               pressure.InstalledBinding is { } installed &&
               installed.Authority == pending.Authority &&
               installed.InstallGeneration == pending.InstallGeneration &&
               (installedPredecessor is null ||
                pressure.RetainedPredecessorBinding is { } retained &&
                retained.Authority == installedPredecessor.Value.Authority &&
                retained.InstallGeneration == installedPredecessor.Value.InstallGeneration);
    }

    private bool TryRetireRegularV4FrontierRepairPressureBindingsLocked(
        RegularV4FrontierRepairPressureBinding? retainedPredecessor,
        RegularV4FrontierRepairPressureBinding? installed,
        string reason,
        FileTransferRegularV4FrontierRepairSettlementOutcome currentOutcome,
        Action<FileTransferRegularV4FrontierRepairSettlement> settlementCommitted)
    {
        if (retainedPredecessor is { } predecessor)
        {
            if (installed is not { } successor)
            {
                LogRegularV4FrontierRepairPressureBinding(
                    "filetransfer_regular_v4_frontier_repair_pressure_binding_invalidation_rejected",
                    predecessor.Authority,
                    predecessor,
                    NormalizeReason(reason) ?? "scope_replacement",
                    "regular_v4_frontier_repair_pressure_successor_binding_missing");
                return false;
            }

            var predecessorSettlement =
                CreateRegularV4FrontierRepairPressureScopeReplacementSettlement(
                        predecessor,
                        FileTransferRegularV4FrontierRepairSettlementOutcome.Superseded,
                        reason,
                        successor.Authority.AuthorityId);
            if (!TryApplyRegularV4FrontierRepairPressureSettlementLocked(
                    predecessorSettlement,
                    out var predecessorRejectionReason))
            {
                LogRegularV4FrontierRepairPressureBinding(
                    "filetransfer_regular_v4_frontier_repair_pressure_binding_invalidation_rejected",
                    predecessor.Authority,
                    predecessor,
                    NormalizeReason(reason) ?? "scope_replacement",
                    predecessorRejectionReason);
                return false;
            }

            settlementCommitted(predecessorSettlement);
        }

        var current = installed;
        if (current is null)
        {
            return true;
        }

        var currentSettlement =
            CreateRegularV4FrontierRepairPressureScopeReplacementSettlement(
                    current.Value,
                    currentOutcome,
                    reason);
        if (!TryApplyRegularV4FrontierRepairPressureSettlementLocked(
                currentSettlement,
                out var rejectionReason))
        {
            LogRegularV4FrontierRepairPressureBinding(
                "filetransfer_regular_v4_frontier_repair_pressure_binding_invalidation_rejected",
                current.Value.Authority,
                current,
                NormalizeReason(reason) ?? "scope_replacement",
                rejectionReason);
            return false;
        }

        settlementCommitted(currentSettlement);
        return true;
    }

    private static FileTransferRegularV4FrontierRepairSettlement
        CreateRegularV4FrontierRepairPressureScopeReplacementSettlement(
            RegularV4FrontierRepairPressureBinding binding,
            FileTransferRegularV4FrontierRepairSettlementOutcome outcome,
            string reason,
            FileTransferAuthorityId? successorAuthorityId = null)
    {
        var authority = binding.Authority;
        return new FileTransferRegularV4FrontierRepairSettlement(
            authority.SessionId,
            authority.TransferId,
            authority.Direction,
            authority.RouteToken,
            authority.ProtocolVersion,
            authority.LiveRouteEpoch,
            authority.RuntimeGeneration,
            authority.TerminalGeneration,
            authority.LegGeneration,
            authority.TransportEpoch,
            authority.BridgeRecoveryGeneration,
            authority.BridgeDecisionGeneration,
            authority.RoutePublicationGeneration,
            authority.RouteCommitGeneration,
            authority.RepairKey,
            authority.FrontierChunkIndex,
            authority.DurableReceivedHighestChunkIndex,
            authority.PendingRepairCount,
            authority.DecisionGeneration,
            NormalizeReason(reason) ?? "data_session_replaced",
            outcome,
            authority.TargetTransport)
        {
            AuthorityId = authority.AuthorityId,
            SuccessorAuthorityId = successorAuthorityId is { IsDefault: false }
                ? successorAuthorityId
                : null,
        };
    }

    private static void SettleRegularV4FrontierRepairContractsForDataSessionReplacementLocked(
        OutboundTransferContext context,
        FileTransferRegularV4FrontierRepairSettlement settlement)
    {
        SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
            context.CurrentRegularV4FrontierRepairContract?.PredecessorLifecycleContract,
            settlement);

        var currentSettled = SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
            context.CurrentRegularV4FrontierRepairContract,
            settlement);
        if (currentSettled &&
            context.CurrentRegularV4FrontierRepairContract?.Authority.AuthorityId == settlement.AuthorityId)
        {
            context.CurrentRegularV4FrontierRepairContract = null;
        }

        if (context.PendingRegularV4FrontierRepairPressureInstallRetry?.AuthorityId ==
            settlement.AuthorityId)
        {
            context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
        }

        var missingDispatchSettled = SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
            context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract,
            settlement);
        if (missingDispatchSettled &&
            context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract?.Authority.AuthorityId ==
            settlement.AuthorityId)
        {
            context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract = null;
        }
    }

    private static void SettleRegularV4FrontierRepairContractsForDataSessionReplacementLocked(
        InboundTransferContext context,
        FileTransferRegularV4FrontierRepairSettlement settlement)
    {
        var currentSettled = SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
            context.CurrentRegularV4FrontierRepairContract,
            settlement);
        if (currentSettled &&
            context.CurrentRegularV4FrontierRepairContract?.Authority.AuthorityId == settlement.AuthorityId)
        {
            context.CurrentRegularV4FrontierRepairContract = null;
        }

        SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
            context.V4RegularFrontierRepairProjection?.SourceContract,
            settlement);
        SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
            context.V4RegularFrontierRepairProjectionRefreshSource?.Projection.SourceContract,
            settlement);
        var stalledSettled = SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
            context.V4RegularFrontierRepairSettledStalledContract,
            settlement);
        if (stalledSettled &&
            context.V4RegularFrontierRepairSettledStalledContract?.Authority.AuthorityId == settlement.AuthorityId)
        {
            context.V4RegularFrontierRepairSettledStalledContract = null;
            context.V4RegularFrontierRepairSettledStalledAuthorityId = null;
        }
    }

    private static bool SettleRegularV4FrontierRepairContractLifecycleForDataSessionReplacement(
        RegularV4FrontierRepairContract? contract,
        FileTransferRegularV4FrontierRepairSettlement settlement)
    {
        if (contract is null)
        {
            return false;
        }

        if (contract.Authority.AuthorityId == settlement.AuthorityId)
        {
            contract.Lifecycle.TrySettle(
                settlement.Outcome,
                settlement.DecisionReason,
                settlement.SuccessorAuthorityId);
            return true;
        }

        return false;
    }

    private void RecordCoordinatorIssuedRegularV4RecoverySettlementLocked(
        FileTransferRegularV4FrontierRepairSettlement settlement)
    {
        if (settlement.Direction == FileTransferDirection.Outbound &&
            outboundTransfer is { } outbound &&
            string.Equals(outbound.SessionId, settlement.SessionId, StringComparison.Ordinal) &&
            string.Equals(outbound.TransferId, settlement.TransferId, StringComparison.Ordinal) &&
            outbound.CurrentRepairReplayDecision is { } outboundRepair &&
            outboundRepair.AuthorityId == settlement.AuthorityId &&
            outboundRepair.RepairGeneration == settlement.DecisionGeneration)
        {
            return;
        }

        if (settlement.Direction == FileTransferDirection.Inbound &&
            inboundTransfer is { } inbound &&
            string.Equals(inbound.SessionId, settlement.SessionId, StringComparison.Ordinal) &&
            string.Equals(inbound.TransferId, settlement.TransferId, StringComparison.Ordinal) &&
            inbound.CurrentRepairReplayDecision is { } inboundRepair &&
            inboundRepair.AuthorityId == settlement.AuthorityId &&
            inboundRepair.RepairGeneration == settlement.DecisionGeneration)
        {
        }
    }

    private bool SettleAndClearRegularV4FrontierRepairContractLocked(
        OutboundTransferContext context,
        FileTransferRegularV4FrontierRepairSettlementOutcome outcome,
        string reason)
    {
        var contract = context.CurrentRegularV4FrontierRepairContract;
        if (contract is not null && !contract.Lifecycle.IsSettled)
        {
            if (!SettlePendingRegularV4FrontierRepairPressureInstallPredecessor(
                contract,
                outcome,
                reason) ||
                !TrySettleRegularV4FrontierRepairContract(
                contract,
                outcome,
                contract.Authority.PendingRepairCount,
                reason))
            {
                return false;
            }

        }

        context.CurrentRegularV4FrontierRepairContract = null;
        context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract = null;
        context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
        return true;
    }

    private bool SettleAndClearRegularV4FrontierRepairContractLocked(
        InboundTransferContext context,
        FileTransferRegularV4FrontierRepairSettlementOutcome outcome,
        string reason)
    {
        var contract = context.CurrentRegularV4FrontierRepairContract;
        if (contract is not null && !contract.Lifecycle.IsSettled)
        {
            if (!SettlePendingRegularV4FrontierRepairPressureInstallPredecessor(
                contract,
                outcome,
                reason) ||
                !TrySettleRegularV4FrontierRepairContract(
                contract,
                outcome,
                contract.Authority.PendingRepairCount,
                reason))
            {
                return false;
            }

        }

        context.CurrentRegularV4FrontierRepairContract = null;
        context.V4RegularFrontierRepairSettledStalledContract = null;
        context.V4RegularFrontierRepairSettledStalledAuthorityId = null;
        if (outcome is
            FileTransferRegularV4FrontierRepairSettlementOutcome.TransferTerminal or
            FileTransferRegularV4FrontierRepairSettlementOutcome.TerminalRejected)
        {
            ClearInboundRegularV4FrontierRepairProjectionLocked(
                context,
                reason,
                requireFreshProjection: false);
        }

        return true;
    }

    private bool SettlePendingRegularV4FrontierRepairPressureInstallPredecessor(
        RegularV4FrontierRepairContract contract,
        FileTransferRegularV4FrontierRepairSettlementOutcome outcome,
        string reason)
    {
        if (contract.Authority.PredecessorAuthorityId is not { IsDefault: false } predecessorAuthorityId)
        {
            return true;
        }

        var predecessorContract = FindRegularV4FrontierRepairContractForAuthority(
            contract.Authority.Direction,
            contract.Authority.SessionId,
            contract.Authority.TransferId,
            predecessorAuthorityId);
        if (predecessorContract is not { Lifecycle.IsSettled: false } ||
            TryGetInstalledRegularV4FrontierRepairPressureForContract(
                contract,
                out var binding,
                out var receipt) &&
            IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                contract,
                predecessorContract.Authority.AuthorityId,
                binding.PressureReason,
                receipt,
                out _))
        {
            return true;
        }

        return TrySettleRegularV4FrontierRepairContract(
            predecessorContract,
            outcome,
            predecessorContract.Authority.PendingRepairCount,
            reason);
    }

    private static RuntimeUnlockRetryDispatchAuthorityRequest?
        GetPendingRuntimeUnlockRetryDispatchAuthorityRequest(
            OutboundTransferContext context)
        => context.CoordinatorPersistentState.RuntimeUnlockRetryLifecycle
            .PendingAttempt?.Request;

    private static bool IsOutboundNormalToTunaActivationProofPendingLocked(OutboundTransferContext context)
    {
        if (context.V6TransportEpoch is { } epoch &&
            IsV6TransportEpochUnresolved(epoch) &&
            epoch.Kind == FileTransferTransportHandoffKind.NormalToTunaActivation &&
            epoch.TargetTransport == FileTransferTransportKind.Tuna)
        {
            return true;
        }

        return context.V6TransportHandoff is { } handoff &&
               IsV6TransportHandoffBlockingTail(handoff) &&
               handoff.Kind == FileTransferTransportHandoffKind.NormalToTunaActivation &&
               handoff.TargetTransport == FileTransferTransportKind.Tuna;
    }

    private static bool IsInboundFileTunaV4PostTunaRecoveryActiveLocked(InboundTransferContext context)
        => context.RouteRuntime.UsesFileTunaV4Runtime &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           IsInboundPostTunaRecoveryActiveLocked(context);

    private static int GetOutboundPostTunaRecoveryGenerationLocked(OutboundTransferContext context)
        => context.PullTransportRebindGeneration > 0
            ? context.PullTransportRebindGeneration
            : context.PullPostTunaRecoveryGeneration > 0
                ? context.PullPostTunaRecoveryGeneration
                : IsRecoveredV6TunaFallbackEpochLocked(context.LastRecoveredV6TransportEpochKind, context.LastRecoveredV6TransportTargetTransport)
                    ? (int)Math.Min(int.MaxValue, Math.Max(0, context.LastRecoveredV6TransportEpoch))
                    : 0;

    private static int GetInboundPostTunaRecoveryGenerationLocked(InboundTransferContext context)
        => context.PullTransportRebindGeneration > 0
            ? context.PullTransportRebindGeneration
            : context.PullPostTunaRecoveryGeneration > 0
                ? context.PullPostTunaRecoveryGeneration
                : IsRecoveredV6TunaFallbackEpochLocked(context.LastRecoveredV6TransportEpochKind, context.LastRecoveredV6TransportTargetTransport)
                    ? (int)Math.Min(int.MaxValue, Math.Max(0, context.LastRecoveredV6TransportEpoch))
                    : 0;

    private static bool IsRecoveredV6TunaFallbackEpochLocked(
        FileTransferTransportHandoffKind handoffKind,
        FileTransferTransportKind targetTransport)
        => handoffKind == FileTransferTransportHandoffKind.TunaToNormalFallback &&
           targetTransport == FileTransferTransportKind.RegularNkn;

    private static bool IsDedicatedV6TransportEpochKind(
        FileTransferTransportHandoffKind handoffKind,
        FileTransferTransportKind targetTransport)
        => handoffKind is FileTransferTransportHandoffKind.NormalToTunaActivation
               or FileTransferTransportHandoffKind.TunaToNormalFallback
               or FileTransferTransportHandoffKind.TunaRestart ||
           targetTransport == FileTransferTransportKind.Tuna;

    private static bool ShouldSuppressLegacyV6HandoffForDedicatedV6EpochLocked(
        OutboundTransferContext context,
        long transportEpoch)
    {
        if (transportEpoch <= 0)
        {
            return false;
        }

        if (context.V6TransportEpoch is { } current &&
            current.EpochId == transportEpoch &&
            IsDedicatedV6TransportEpochKind(current.Kind, current.TargetTransport))
        {
            return true;
        }

        return context.LastRecoveredV6TransportEpoch == transportEpoch &&
               IsDedicatedV6TransportEpochKind(
                   context.LastRecoveredV6TransportEpochKind,
                   context.LastRecoveredV6TransportTargetTransport);
    }

    private static void LogLegacyV6HandoffSuppressedForDedicatedV6Epoch(
        OutboundTransferContext context,
        long transportEpoch,
        string frameType,
        string reason)
    {
        var handoffKind = context.V6TransportEpoch is { EpochId: var currentEpoch } current && currentEpoch == transportEpoch
            ? current.Kind
            : context.LastRecoveredV6TransportEpochKind;
        var targetTransport = context.V6TransportEpoch is { EpochId: var currentEpochForTarget } currentForTarget && currentEpochForTarget == transportEpoch
            ? currentForTarget.TargetTransport
            : context.LastRecoveredV6TransportTargetTransport;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v6_legacy_handoff_suppressed_for_epoch; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={frameType}; transport_epoch={transportEpoch}; reason={FormatProtocolLogValue(reason)}; handoff_kind={FormatFileTransferTransportHandoffKind(handoffKind)}; target_transport={FormatFileTransferTransportKind(targetTransport)}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}");
    }

    private void MarkInboundV4PeerFrameReceived(InboundTransferContext context)
    {
        lock (gate)
        {
            if (ReferenceEquals(inboundTransfer, context) && !context.IsTerminal)
            {
                var now = DateTimeOffset.UtcNow;
                context.PullV4LastPeerFrameReceivedUtc = now;
                context.PullV4PeerSilenceDeferralUtc = null;
                context.PullV4PeerSilenceDeferralCount = 0;
                context.V6LastPeerLivenessUtc = now;
            }
        }
    }

    private bool TryGetInboundV4PeerSilenceFailure(
        InboundTransferContext context,
        out string statusMessage)
    {
        statusMessage = "Sender stopped responding.";
        lock (gate)
        {
            if (!ReferenceEquals(inboundTransfer, context) ||
                context.IsTerminal ||
                context.UserPaused ||
                context.PeerPaused ||
                !context.PullSessionActive ||
                !context.PullManifestReceived ||
                context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6)
            {
                return false;
            }

            if (context.PullTransportPaused &&
                !IsTunaFallbackTransportPauseReason(context.PullTransportPauseReason))
            {
                return false;
            }

            var lastPeerFrameUtc = context.PullV4LastPeerFrameReceivedUtc ??
                context.PullLastProgressUtc ??
                context.LastUsefulBulkProgressUtc ??
                context.PullTransportRebindStartedUtc;
            if (lastPeerFrameUtc is null)
            {
                return false;
            }

            var postFallback = IsInboundPostTunaRecoveryActiveLocked(context);
            var silence = DateTimeOffset.UtcNow - lastPeerFrameUtc.Value;
            var timeout = ResolveV4PeerSilenceTimeout(postFallback);
            if (silence < timeout)
            {
                return false;
            }

            var reason = postFallback
                ? "post_tuna_fallback_peer_silence"
                : "peer_silence";
            if (postFallback &&
                ShouldUsePostTunaFallbackV6SparseRuntimeLocked(context))
            {
                MaybeLogInboundPostTunaFallbackPeerSilenceDeferralLocked(context, reason, silence, timeout);
                return false;
            }

            if (!postFallback &&
                ShouldUseV6RegularNknSparseRuntime(context) &&
                IsInboundV6PrimaryRegularNknWithoutTunaRecoveryLocked(context))
            {
                MaybeLogInboundV4SparseRuntimePeerSilenceDeferralLocked(context, reason, silence, timeout);
                return false;
            }

            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v4_peer_receive_timeout; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={reason}; rebind_generation={context.PullTransportRebindGeneration}; silence_ms={(long)Math.Max(0, silence.TotalMilliseconds)}; timeout_ms={(long)timeout.TotalMilliseconds}; committed_chunk={context.NextChunkIndex}; highest_received_chunk={context.PullHighestReceivedChunkIndex}; bytes_transferred={context.BytesTransferred}; missing_range_count={(context.NextChunkIndex <= context.PullHighestReceivedChunkIndex ? 1 : 0)}");
            return true;
        }
    }

    private static void MaybeLogInboundV4SparseRuntimePeerSilenceDeferralLocked(
        InboundTransferContext context,
        string reason,
        TimeSpan silence,
        TimeSpan timeout)
    {
        var now = DateTimeOffset.UtcNow;
        if (context.PullV4PeerSilenceDeferralUtc is { } lastLog &&
            now - lastLog < TimeSpan.FromSeconds(10))
        {
            context.PullV4PeerSilenceDeferralCount++;
            return;
        }

        context.PullV4PeerSilenceDeferralUtc = now;
        context.PullV4PeerSilenceDeferralCount++;
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_peer_receive_timeout_deferred_for_v6_regular_nkn_sparse_runtime; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={reason}; deferral_count={context.PullV4PeerSilenceDeferralCount}; silence_ms={(long)Math.Max(0, silence.TotalMilliseconds)}; timeout_ms={(long)timeout.TotalMilliseconds}; committed_chunk={context.NextChunkIndex}; highest_received_chunk={context.PullHighestReceivedChunkIndex}; bytes_transferred={context.BytesTransferred}; missing_range_count={(context.NextChunkIndex <= context.PullHighestReceivedChunkIndex ? 1 : 0)}");
    }

    private static void MaybeLogInboundPostTunaFallbackPeerSilenceDeferralLocked(
        InboundTransferContext context,
        string reason,
        TimeSpan silence,
        TimeSpan timeout)
    {
        var now = DateTimeOffset.UtcNow;
        if (context.PullV4PeerSilenceDeferralUtc is { } lastLog &&
            now - lastLog < TimeSpan.FromSeconds(10))
        {
            context.PullV4PeerSilenceDeferralCount++;
            return;
        }

        context.PullV4PeerSilenceDeferralUtc = now;
        context.PullV4PeerSilenceDeferralCount++;
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_post_tuna_fallback_peer_receive_timeout_deferred; direction=inbound; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; deferral_count={context.PullV4PeerSilenceDeferralCount}; silence_ms={(long)Math.Max(0, silence.TotalMilliseconds)}; timeout_ms={(long)timeout.TotalMilliseconds}; rebind_generation={context.PullTransportRebindGeneration}; committed_chunk={context.NextChunkIndex}; highest_received_chunk={context.PullHighestReceivedChunkIndex}; bytes_transferred={context.BytesTransferred}; missing_range_count={(context.NextChunkIndex <= context.PullHighestReceivedChunkIndex ? 1 : 0)}");
    }

    private static bool ShouldUsePostTunaFallbackV6SparseRuntimeLocked(OutboundTransferContext context)
        => context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           (context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.RouteRuntime.UsesV6SparsePump);

    private static bool ShouldUsePostTunaFallbackV6SparseRuntimeLocked(InboundTransferContext context)
        => context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           (context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.RouteRuntime.UsesV6SparsePump);

    private static bool ShouldUsePostTunaFallbackV6FeedbackEnvelope(InboundTransferContext context)
        => context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.RouteRuntime.UsesV6FeedbackEnvelope;

    private static bool ShouldPauseOutboundV4SenderPumpForV6RegularNknSparseRuntimeLocked(OutboundTransferContext context)
        => context.PullTransportPaused &&
           ShouldUseV6RegularNknSparseRuntime(context) &&
           IsOutboundV6PrimaryRegularNknWithoutTunaRecoveryLocked(context);

    private static bool ShouldPauseOutboundV4SenderPumpForTunaActivationNegotiationLocked(OutboundTransferContext context)
        => context.PullTransportPaused &&
           IsTunaActivationNegotiationTransportPauseReason(context.PullTransportPauseReason) &&
           !ShouldSuppressTunaActivationPauseForPostTunaFallbackLocked(context);

    private static bool ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(OutboundTransferContext context)
        => context.PullTransportPaused &&
           context.RouteRuntime.UsesRegularNknV4FastRuntime &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           IsRegularNknV4RecoveryTransportPauseReason(context.PullTransportPauseReason);

    private static bool IsPostTunaFallbackReceiveRecoveryPayloadScopeCurrentLocked(
        OutboundTransferContext context,
        FileTransferReceiveRecoveryOperation operation,
        OutboundSparsePumpInstall requiredInstall,
        IFileTransferDataSession requiredDataSession)
    {
        if (!ReferenceEquals(context.DataSession, requiredDataSession) ||
            context.CurrentTransferLeg is not { } leg ||
            context.InstalledOutboundSparsePump != requiredInstall ||
            context.DataSessionGeneration != requiredInstall.DataSessionGeneration ||
            context.CurrentRuntimeOwner != requiredInstall.RuntimeOwner ||
            context.CurrentRoutePublicationToken != requiredInstall.RoutePublication ||
            context.TerminalGeneration != requiredInstall.TerminalGeneration ||
            leg.Generation != requiredInstall.LegGeneration)
        {
            return false;
        }

        var observation = operation.Authority.Observation;
        return observation.Direction == FileTransferDirection.Outbound &&
               observation.Route == FileTransferRoute.PostTunaFallbackV6 &&
               observation.ProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
               observation.RuntimeOwner == requiredInstall.RuntimeOwner &&
               observation.RoutePublication == requiredInstall.RoutePublication &&
               observation.TerminalGeneration == requiredInstall.TerminalGeneration &&
               observation.LegGeneration == requiredInstall.LegGeneration &&
               observation.TransportEpoch == leg.TransportEpochId &&
               observation.BridgeRecoveryGeneration == leg.BridgeRecoveryGeneration &&
               observation.DataSessionGeneration == requiredInstall.DataSessionGeneration &&
               string.Equals(
                   observation.DataSessionIdentity,
                   CreateReceiveRecoveryDataSessionIdentity(
                       context.TransferId,
                       requiredDataSession,
                       requiredInstall.DataSessionGeneration),
                   StringComparison.Ordinal);
    }

    private static bool TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
        OutboundTransferContext context,
        out FileTransferReceiveRecoveryOperation operation,
        out string reason)
    {
        operation = default;
        reason = "filetransfer_receive_recovery_execution_not_active";
        var regularV4 = context.RouteRuntime.UsesRegularNknV4FastRuntime &&
                        context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
                        context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4;
        var postTunaFallbackV6 =
            context.RouteSelection.Route == FileTransferRoute.PostTunaFallbackV6 &&
            context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
            context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
            context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V6;
        if ((!regularV4 && !postTunaFallbackV6) ||
            !FileTransferCoordinator.TryGetReceiveRecoveryPayloadSubmissionHold(
                CreateCoordinatorStateLocked(context),
                out operation,
                out reason))
        {
            return false;
        }

        if (regularV4)
        {
            return true;
        }

        if (operation.ExecutionState is not
                (FileTransferReceiveRecoveryExecutionState.Issued or
                 FileTransferReceiveRecoveryExecutionState.Running) &&
            operation is not
            {
                ExecutionState: FileTransferReceiveRecoveryExecutionState.Completed,
                ExecutionReceipt.Outcome:
                    FileTransferBridgeRecoveryExecutionOutcome.Completed,
                ClosureState: FileTransferReceiveRecoveryClosureState.Retained,
                ReceiveProof: null,
            })
        {
            operation = default;
            reason = "filetransfer_receive_recovery_payload_hold_not_active";
            return false;
        }

        if (context.InstalledOutboundSparsePump is not { } install ||
            context.DataSession is not { } dataSession ||
            !IsPostTunaFallbackReceiveRecoveryPayloadScopeCurrentLocked(
                context,
                operation,
                install,
                dataSession))
        {
            operation = default;
            reason = "filetransfer_receive_recovery_payload_hold_pump_scope_not_current";
            return false;
        }

        return true;
    }

    private static void MarkOutboundPayloadSubmissionHeldForReceiveRecoveryLocked(
        OutboundTransferContext context,
        FileTransferReceiveRecoveryOperation operation,
        string stage,
        string reason,
        RegularV4FrontierRepairContract? repairContract = null,
        string? repairRequestKey = null)
    {
        var wakeReason =
            $"receive_recovery_execution_payload_hold:{operation.Authority.OperationGeneration}:{repairContract?.Authority.AuthorityId.ToString() ?? repairRequestKey ?? "(normal)"}";
        var shouldLog = !string.Equals(
            context.SparseSenderPumpLastWakeReason,
            wakeReason,
            StringComparison.Ordinal);
        context.SparseSenderPumpLastWakeReason = wakeReason;
        if (!shouldLog)
        {
            return;
        }

        var authority = operation.Authority;
        var observation = authority.Observation;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_bridge_recovery_payload_submission_held; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; direction=outbound; stage={FormatProtocolLogValue(stage)}; recovery_operation_generation={authority.OperationGeneration}; recovery_operation_authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; recovery_execution_state={operation.ExecutionState}; execution_receipt_observed_utc_ms={operation.ExecutionReceiptObservedUtcMs}; closure_state={operation.ClosureState}; closure_generation={operation.ClosureGeneration}; proof_identity={FormatProtocolLogValue(operation.ReceiveProof?.ProofIdentity ?? "(none)")}; proof_observed_utc_ms={operation.ReceiveProof?.ObservedUtcMs ?? 0}; bridge_decision_generation={authority.BridgeRecoveryDecision.BridgeDecisionGeneration}; recovery_liveness_lease_generation={authority.RecoveryLivenessLease?.LeaseGeneration ?? 0}; route={FormatProtocolLogValue(observation.RouteToken)}; protocol_version={observation.ProtocolVersion}; live_route_epoch={observation.LiveRouteEpoch}; runtime_generation={observation.RuntimeOwner.RuntimeGeneration}; terminal_generation={observation.TerminalGeneration}; leg_generation={observation.LegGeneration}; transport_epoch={observation.TransportEpoch}; bridge_recovery_generation={observation.BridgeRecoveryGeneration}; route_publication_generation={observation.RoutePublication.PublicationGeneration}; data_session_generation={observation.DataSessionGeneration}; repair_authority_id={FormatProtocolLogValue(repairContract?.Authority.AuthorityId.ToString() ?? "(none)")}; repair_install_generation={GetRegularV4FrontierRepairPressureInstallGeneration(CreateCoordinatorStateLocked(context), repairContract)}; repair_request_key={FormatProtocolLogValue(repairRequestKey ?? "(none)")}; decision_reason={FormatProtocolLogValue(reason)}");
    }

    private static bool IsRegularNknV4RecoveryTransportPauseReason(string? reason)
    {
        var normalized = NormalizeReason(reason);
        return normalized is "receive_stall_recovery" or
            "transport_recovered_unproven" or
            "transport_probe_unproven";
    }

    private static bool ShouldSuppressTunaActivationPauseForPostTunaFallbackLocked(OutboundTransferContext context)
        => context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6;

    private static bool ShouldSuppressTunaActivationPauseForPostTunaFallbackLocked(InboundTransferContext context)
        => context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6;

    private static bool ShouldPauseOutboundV4SenderPumpForFileTunaV4PostTunaRecoveryLocked(OutboundTransferContext context)
        => context.PullTransportPaused &&
           IsOutboundFileTunaV4PostTunaRecoveryActiveLocked(context) &&
           IsTunaFallbackTransportPauseReason(context.PullTransportPauseReason);

    private static bool IsFileTunaV4PostTunaRecoveryActiveLocked(OutboundTransferContext context)
        => context.RouteRuntime.UsesFileTunaV4Runtime &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4 &&
           context.PullPostTunaRecoveryActive;

    private static bool ShouldBlockOutboundV4NormalSendAheadForFileTunaV4PostTunaRecoveryLocked(OutboundTransferContext context)
        => IsFileTunaV4PostTunaRecoveryActiveLocked(context) &&
           context.PullTransportFrontierOnlyRepairActive;

    private static bool ShouldPauseOutboundV4SenderPumpForTransportPauseLocked(OutboundTransferContext context)
        => ShouldPauseOutboundV4SenderPumpForV6RegularNknSparseRuntimeLocked(context) ||
           ShouldPauseOutboundV4SenderPumpForTunaActivationNegotiationLocked(context) ||
           ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context) ||
           ShouldPauseOutboundV4SenderPumpForFileTunaV4PostTunaRecoveryLocked(context);

    private bool ClearOutboundV4RepairWorkForTunaActivationPauseLocked(
        OutboundTransferContext context,
        string reason)
    {
        if (!TryRetireRegularV4FrontierRepairPressureForScopeReplacementLocked(
                context,
                $"tuna_activation_pause_{reason}") ||
            !SettleAndClearRegularV4FrontierRepairContractLocked(
                context,
                FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
                $"tuna_activation_pause_{reason}"))
        {
            return false;
        }

        SettleAndClearFallbackFrontierRepairContractLocked(
            context,
            FallbackFrontierRepairSettlementOutcome.StaleRejected,
            $"tuna_activation_pause_{reason}");
        var queuedRepairItemCount = context.PullV4SenderPumpRepairQueue.Count;
        var queuedRepairChunkCount = context.PullV4SenderPumpRepairQueue.Sum(static repair => repair.ChunkIndices.Count);
        var queuedRepairIndexCount = context.PullV4SenderPumpRepairQueuedChunkIndices.Count;
        var queuedStateClearedCount = 0;

        if (queuedRepairItemCount > 0)
        {
            context.PullV4SenderPumpRepairQueue.Clear();
        }

        if (queuedRepairIndexCount > 0)
        {
            context.PullV4SenderPumpRepairQueuedChunkIndices.Clear();
        }

        foreach (var repairState in context.PullV4SenderPumpRepairRequests.Values)
        {
            if (!repairState.Queued)
            {
                continue;
            }

            repairState.Queued = false;
            repairState.QueuedUtc = null;
            repairState.SuppressedCount++;
            queuedStateClearedCount++;
        }

        if (queuedRepairItemCount == 0 &&
            queuedRepairChunkCount == 0 &&
            queuedRepairIndexCount == 0 &&
            queuedStateClearedCount == 0)
        {
            return true;
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_repair_queue_retired_for_tuna_activation_barrier; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; queued_repair_item_count={queuedRepairItemCount}; queued_repair_chunk_count={queuedRepairChunkCount}; queued_repair_index_count={queuedRepairIndexCount}; queued_state_cleared_count={queuedStateClearedCount}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}");
        return true;
    }

    private static bool ShouldAllowOutboundV4RepairWhileTransportPausedLocked(OutboundTransferContext context)
    {
        if (!context.PullTransportPaused ||
            context.PullV4SenderPumpRepairQueue.Count == 0)
        {
            return false;
        }

        if (ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context))
        {
            return !TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                context,
                out _,
                out _);
        }

        if (!IsTunaFallbackRepairDrainTransportPauseReason(context.PullTransportPauseReason))
        {
            return false;
        }

        return ShouldUseV6RegularNknSparseRuntime(context) ||
            ShouldPauseOutboundV4SenderPumpForFileTunaV4PostTunaRecoveryLocked(context);
    }

    private static bool ShouldAllowOutboundV4RepairSendWhileTransportPausedLocked(
        OutboundTransferContext context,
        bool repairSend)
        => repairSend &&
           context.PullTransportPaused &&
           ((ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context) &&
             !TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                 context,
                 out _,
                 out _)) ||
            (IsTunaFallbackRepairDrainTransportPauseReason(context.PullTransportPauseReason) &&
             (ShouldUseV6RegularNknSparseRuntime(context) ||
              ShouldPauseOutboundV4SenderPumpForFileTunaV4PostTunaRecoveryLocked(context))));

    private static bool ShouldBlockOutboundV4TransportSendForTransportPauseLocked(
        OutboundTransferContext context,
        bool repairSend)
        => TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
               context,
               out _,
               out _) ||
           (ShouldPauseOutboundV4SenderPumpForTransportPauseLocked(context) &&
            !ShouldAllowOutboundV4RepairSendWhileTransportPausedLocked(context, repairSend));

    private static bool ShouldInterruptOutboundV4TransportSendOnPumpSignal(OutboundTransferContext context)
        => context.RouteRuntime.UsesFileTunaV4Runtime ||
           context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
           ShouldPauseOutboundV4SenderPumpForTunaActivationNegotiationLocked(context) ||
           ShouldUseV6RegularNknSparseRuntime(context);

    private static bool IsTunaActivationNegotiationDataSessionUnavailableException(Exception? ex)
    {
        if (ex is null)
        {
            return false;
        }

        if (ex is InvalidOperationException &&
            ex.Message.Contains("File-transfer data session is unavailable", StringComparison.OrdinalIgnoreCase) &&
            ex.Message.Contains("tuna_activation_negotiating", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (ex is AggregateException aggregate)
        {
            return aggregate.InnerExceptions.Any(IsTunaActivationNegotiationDataSessionUnavailableException);
        }

        return IsTunaActivationNegotiationDataSessionUnavailableException(ex.InnerException);
    }

    private static bool IsRequiredTunaBulkUnavailableForTunaFallback(Exception? ex, out string reason)
    {
        reason = string.Empty;
        if (ex is null)
        {
            return false;
        }

        if (ex is FileTransferRequiredTunaBulkUnavailableException unavailable &&
            IsRequiredTunaBulkUnavailableFallbackReason(unavailable.Reason))
        {
            reason = unavailable.Reason;
            return true;
        }

        if (ex is AggregateException aggregate)
        {
            foreach (var inner in aggregate.InnerExceptions)
            {
                if (IsRequiredTunaBulkUnavailableForTunaFallback(inner, out reason))
                {
                    return true;
                }
            }

            return false;
        }

        return IsRequiredTunaBulkUnavailableForTunaFallback(ex.InnerException, out reason);
    }

    private static bool IsRequiredTunaBulkUnavailableFallbackReason(string? reason)
    {
        var normalized = NormalizeReason(reason);
        return normalized is "header_switch_off" or
            "remote_header_switch_off" or
            "runtime_disabled" or
            "wallet_unlinked" or
            "cap_reached" or
            "listener_exit" or
            "listener_exited" or
            "sidecar_exit" or
            "sidecar_exited" or
            "ipc_disconnect" or
            "send_failure" or
            "remote_closed" or
            "remote_remote_closed" or
            "sidecar_remote_closed" or
            "remote_sidecar_remote_closed" or
            "tuna_fallback_to_nkn" or
            "tuna_unavailable_before_send" or
            "tuna_send_invalidated_after_queue" or
            "tuna_send_rejected" or
            "tuna_send_failed" or
            "transport_disconnected" or
            "transport_recovered_unproven" or
            "transport_probe_unproven" ||
            normalized?.StartsWith("header_switch_off_", StringComparison.OrdinalIgnoreCase) == true ||
            normalized?.StartsWith("remote_header_switch_off_", StringComparison.OrdinalIgnoreCase) == true ||
            normalized?.StartsWith("helper_switch_off_", StringComparison.OrdinalIgnoreCase) == true;
    }

    private static bool IsRecentRecoveredTunaActivationCancellationLocked(
        OutboundTransferContext context,
        bool dataSessionAvailable,
        Exception ex)
    {
        if (ex is not OperationCanceledException ||
            !dataSessionAvailable ||
            !IsTunaActivationNegotiationTransportPauseReason(context.PullTransportLastPauseReason) ||
            context.PullTransportLastResumeUtc is not { } lastResumeUtc)
        {
            return false;
        }

        var age = DateTimeOffset.UtcNow - lastResumeUtc;
        return age >= TimeSpan.Zero &&
            age <= TimeSpan.FromMilliseconds(TunaActivationSendCancellationRecoveryWindowMs);
    }

    private bool TryDeferOutboundV4SendForTunaActivationPauseLocked(
        OutboundTransferContext context,
        bool dataSessionAvailable,
        Exception sendException,
        out string pauseReason,
        out int rebindGeneration,
        out bool activationPauseStarted,
        out bool activationPauseAlreadyRecovered)
    {
        pauseReason = context.PullTransportPauseReason ?? "tuna_activation_negotiating";
        rebindGeneration = context.PullTransportRebindGeneration;
        activationPauseStarted = false;
        activationPauseAlreadyRecovered = false;

        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal)
        {
            return false;
        }

        var alreadyPausedForActivation = ShouldPauseOutboundV4SenderPumpForTunaActivationNegotiationLocked(context);
        var explicitActivationUnavailable = IsTunaActivationNegotiationDataSessionUnavailableException(sendException);
        var recentRecoveredActivationCancellation = IsRecentRecoveredTunaActivationCancellationLocked(
            context,
            dataSessionAvailable,
            sendException);
        if (!alreadyPausedForActivation && !explicitActivationUnavailable && !recentRecoveredActivationCancellation)
        {
            return false;
        }

        if (!alreadyPausedForActivation &&
            dataSessionAvailable &&
            (explicitActivationUnavailable || recentRecoveredActivationCancellation))
        {
            activationPauseAlreadyRecovered = true;
            pauseReason = "tuna_activation_negotiating";
            context.SparseSenderPumpLastWakeReason = "tuna_activation_send_canceled_after_resume";
            return true;
        }

        if (!alreadyPausedForActivation)
        {
            activationPauseStarted = TryPauseOutboundTransportLocked(
                context,
                "tuna_activation_negotiating",
                requiresResumeRequest: false);
        }

        pauseReason = context.PullTransportPauseReason ?? pauseReason;
        rebindGeneration = context.PullTransportRebindGeneration;
        MarkOutboundV4SenderPumpTransportPausedLocked(context);
        return true;
    }

    private bool TryDeferOutboundV4SendForFileTunaFallbackHandoffLocked(
        OutboundTransferContext context,
        Exception sendException,
        out string pauseReason,
        out int rebindGeneration)
    {
        pauseReason = "transport_paused";
        rebindGeneration = context.PullTransportRebindGeneration;

        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal ||
            context.RouteSelection.Route != FileTransferRoute.FileTunaV4 ||
            !context.RouteRuntime.UsesFileTunaV4Runtime ||
            !IsRequiredTunaBulkUnavailableForTunaFallback(sendException, out var fallbackReason))
        {
            return false;
        }

        pauseReason = fallbackReason;
        if (!context.PullTransportPaused)
        {
            _ = TryPauseOutboundTransportLocked(
                context,
                fallbackReason,
                requiresResumeRequest: true);
        }
        else if (string.IsNullOrWhiteSpace(context.PullTransportPauseReason))
        {
            context.PullTransportPauseReason = fallbackReason;
            context.PullTransportLastPauseReason = fallbackReason;
        }

        pauseReason = context.PullTransportPauseReason ?? pauseReason;
        rebindGeneration = context.PullTransportRebindGeneration;
        MarkOutboundV4SenderPumpTransportPausedLocked(
            context,
            "filetransfer_v4_sender_pump_paused_for_file_tuna_v4_fallback_handoff");
        return true;
    }

    private async Task<bool> SendOutboundV4PrePumpFrameWithTunaActivationPauseRetryAsync(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferDataFrame frame,
        string frameKind,
        int payloadBytes,
        OutboundSparsePumpInstall requiredInstall)
    {
        var loggedDeferred = false;
        while (true)
        {
            context.LifetimeCts.Token.ThrowIfCancellationRequested();
            Task? waitForSignal = null;
            string pauseReason = "tuna_activation_negotiating";

            lock (gate)
            {
                var installRejection = !ReferenceEquals(outboundTransfer, context)
                    ? "transfer_context_replaced"
                    : context.IsTerminal
                        ? "transfer_terminal"
                        : "accepted";
                var installCurrent = ReferenceEquals(outboundTransfer, context) &&
                    !context.IsTerminal &&
                    IsOutboundSparsePumpInstallCurrentLocked(
                        context,
                        requiredInstall,
                        dataSession,
                        out installRejection);
                if (!installCurrent)
                {
                    if (!string.Equals(installRejection, "accepted", StringComparison.Ordinal))
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            requiredInstall,
                            $"{frameKind}_send",
                            installRejection);
                    }

                    return false;
                }

                if (ShouldPauseOutboundV4SenderPumpForTunaActivationNegotiationLocked(context))
                {
                    pauseReason = context.PullTransportPauseReason ?? pauseReason;
                    MarkOutboundV4SenderPumpTransportPausedLocked(context);
                    waitForSignal = context.ResetAndGetSparseSenderPumpSignalTask();
                }
            }

            if (waitForSignal is not null)
            {
                if (!loggedDeferred)
                {
                    loggedDeferred = true;
                    LocalOperationalLog.Warn(
                        "FileTransferService",
                        $"event=filetransfer_v4_pre_pump_send_deferred_for_tuna_activation_pause; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_kind={FormatProtocolLogValue(frameKind)}; frame_type={frame.Type}; payload_bytes={payloadBytes}; reason={FormatProtocolLogValue(pauseReason)}; rebind_generation={context.PullTransportRebindGeneration}; error=none; message=already_paused");
                }

                await WaitForOutboundV4TransportPauseSignalAsync(context, waitForSignal).ConfigureAwait(false);
                continue;
            }

            try
            {
                FileTransferDataPathSendAuthority? sendAuthority;
                lock (gate)
                {
                    if (!IsOutboundSparsePumpInstallCurrentLocked(
                            context,
                            requiredInstall,
                            dataSession,
                            out var sendRejection))
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            requiredInstall,
                            $"{frameKind}_send",
                            sendRejection);
                        return false;
                    }

                    sendAuthority = CreateDataPathSendAuthority(
                        requiredInstall.RoutePublication,
                        requiredInstall.RoutePublication.Reason);
                }

                if (sendAuthority is not null &&
                    dataSession is IFileTransferDataPathAuthoritySession authoritySession)
                {
                    await authoritySession
                        .SendAsync(frame, sendAuthority, context.LifetimeCts.Token)
                        .ConfigureAwait(false);
                }
                else
                {
                    await dataSession.SendAsync(frame, context.LifetimeCts.Token).ConfigureAwait(false);
                }

                return true;
            }
            catch (Exception ex) when (ex is InvalidOperationException or OperationCanceledException)
            {
                bool deferred;
                bool activationPauseStarted;
                var rebindGeneration = 0;
                lock (gate)
                {
                    if (!IsOutboundSparsePumpInstallCurrentLocked(
                            context,
                            requiredInstall,
                            dataSession,
                            out var sendRejection))
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            requiredInstall,
                            $"{frameKind}_send_failure",
                            sendRejection);
                        return false;
                    }

                    deferred = TryDeferOutboundV4SendForTunaActivationPauseLocked(
                        context,
                        dataSession.IsAvailable,
                        ex,
                        out pauseReason,
                        out rebindGeneration,
                        out activationPauseStarted,
                        out var activationPauseAlreadyRecovered);
                    if (deferred)
                    {
                        waitForSignal = activationPauseAlreadyRecovered
                            ? null
                            : context.ResetAndGetSparseSenderPumpSignalTask();
                    }
                }

                if (!deferred)
                {
                    throw;
                }

                if (activationPauseStarted)
                {
                    LogTransportPaused(FileTransferDirection.Outbound, context.TransferId, context.SessionId, pauseReason);
                    ScheduleOutboundV4TransportPauseControlRetry(context, paused: true, pauseReason);
                }

                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_v4_pre_pump_send_deferred_for_tuna_activation_pause; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_kind={FormatProtocolLogValue(frameKind)}; frame_type={frame.Type}; payload_bytes={payloadBytes}; reason={FormatProtocolLogValue(pauseReason)}; rebind_generation={rebindGeneration}; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");
                loggedDeferred = true;

                if (waitForSignal is not null)
                {
                    await WaitForOutboundV4TransportPauseSignalAsync(context, waitForSignal).ConfigureAwait(false);
                }
            }
        }
    }

    private static async Task WaitForOutboundV4TransportPauseSignalAsync(
        OutboundTransferContext context,
        Task waitForSignal)
        => await Task.WhenAny(
                waitForSignal,
                Task.Delay(PullSessionReceivePollDelayMs, context.LifetimeCts.Token))
            .ConfigureAwait(false);

    private static bool IsTunaFallbackRepairDrainTransportPauseReason(string? pauseReason)
    {
        var reason = NormalizeReason(pauseReason);
        return IsTunaFallbackTransportPauseReason(reason) ||
            reason is "remote_closed" or
            "remote_remote_closed" or
            "sidecar_remote_closed" or
            "tuna_fallback_to_nkn" or
            "transport_disconnected" ||
            reason?.Contains("sidecar", StringComparison.OrdinalIgnoreCase) == true ||
            reason?.Contains("tuna", StringComparison.OrdinalIgnoreCase) == true;
    }

    private void MarkOutboundV4SenderPumpTransportPausedLocked(OutboundTransferContext context)
    {
        var eventName = ShouldPauseOutboundV4SenderPumpForV6RegularNknSparseRuntimeLocked(context)
            ? "filetransfer_v4_sender_pump_transport_paused_for_v6_regular_nkn_sparse_runtime"
            : ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context)
                ? "filetransfer_v4_sender_pump_transport_paused_for_regular_v4_receive_stall_recovery"
            : "filetransfer_v4_sender_pump_transport_paused";
        MarkOutboundV4SenderPumpTransportPausedLocked(context, eventName);
    }

    private static string ResolveOutboundV4PendingSendsAbandonedForTransportPauseEventName(OutboundTransferContext context)
        => ShouldPauseOutboundV4SenderPumpForV6RegularNknSparseRuntimeLocked(context)
            ? "filetransfer_v4_pending_transport_sends_abandoned_for_v6_regular_nkn_sparse_runtime"
            : ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context)
                ? "filetransfer_v4_pending_transport_sends_abandoned_for_regular_v4_receive_stall_recovery"
                : "filetransfer_v4_pending_transport_sends_abandoned_for_transport_pause";

    private void MarkOutboundV4SenderPumpTransportPausedLocked(OutboundTransferContext context, string eventName)
    {
        context.PullSenderSendWaitCountRecent++;
        context.PullSenderSendWaitCountTotal++;
        context.PullSenderFeedCreditWaitStartedUtc ??= DateTimeOffset.UtcNow;
        context.V4SenderCreditExhaustedSinceUtc ??= DateTimeOffset.UtcNow;
        var shouldLog = !string.Equals(context.SparseSenderPumpLastWakeReason, "transport_paused", StringComparison.Ordinal);
        context.SparseSenderPumpLastWakeReason = "transport_paused";
        MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: false);
        if (shouldLog)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event={eventName}; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(context.PullTransportPauseReason ?? "transport_paused")}; rebind_generation={context.PullTransportRebindGeneration}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; bytes_transferred={context.BytesTransferred}; bytes_accepted_for_transport={context.BytesAcceptedForTransport}; pending_repair_count={context.PullV4SenderPumpRepairQueue.Sum(static repair => repair.ChunkIndices.Count)}");
        }
    }

    private async Task RunOutboundV4SenderPumpAsync(
        OutboundTransferContext context,
        Stream stream,
        IFileTransferDataSession dataSession,
        CancellationToken pumpCancellationToken = default,
        OutboundSparsePumpInstall? pumpInstall = null)
    {
        using var pumpLifetime = CancellationTokenSource.CreateLinkedTokenSource(
            context.LifetimeCts.Token,
            pumpCancellationToken);
        var pumpToken = pumpLifetime.Token;
        while (true)
        {
            pumpToken.ThrowIfCancellationRequested();
            if (OutboundSparseSenderPumpNormalCompletionForTests?.Invoke(
                    context.TransferId,
                    context.SessionId) == true)
            {
                return;
            }

            PullV4QueuedRepairSend? repairSend = null;
            List<int>? chunkIndicesToSend = null;
            FileTransferFrontierRequestFrameV6? tailStateRefreshRequest = null;
            Task? waitForSignal = null;
            bool completeFromTerminalReady = false;
            lock (gate)
            {
                if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
                {
                    return;
                }

                if (pumpInstall is not null &&
                    !IsOutboundSparsePumpInstallCurrentLocked(
                        context,
                        pumpInstall,
                        dataSession,
                        out _))
                {
                    return;
                }

                var transportPaused = ShouldPauseOutboundV4SenderPumpForTransportPauseLocked(context);
                var allowPausedRepair = transportPaused &&
                    ShouldAllowOutboundV4RepairWhileTransportPausedLocked(context);
                var receiveRecoveryPayloadHold =
                    TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                        context,
                        out var receiveRecoveryOperation,
                        out var receiveRecoveryHoldReason);
                if (ShouldCompleteOutboundV4FromTerminalReadyStateLocked(context))
                {
                    completeFromTerminalReady = true;
                    MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: true);
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v4_terminal_ready_completion_inferred; transfer_id={context.TransferId}; session_id={context.SessionId}; protocol_version={context.NegotiatedDataProtocolVersion}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunk_count={context.ChunkCount}; bytes_acknowledged_by_receiver={context.BytesAcknowledgedByReceiver}; file_size_bytes={context.FileSizeBytes}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}");
                }
                else if (receiveRecoveryPayloadHold)
                {
                    MarkOutboundPayloadSubmissionHeldForReceiveRecoveryLocked(
                        context,
                        receiveRecoveryOperation,
                        "sender_pump_selection",
                        receiveRecoveryHoldReason,
                        context.PullV4SenderPumpRepairQueue.Count > 0
                            ? context.PullV4SenderPumpRepairQueue.Peek()
                                .RegularV4RepairContract
                            : null,
                        context.PullV4SenderPumpRepairQueue.Count > 0
                            ? context.PullV4SenderPumpRepairQueue.Peek()
                                .RepairRequestKey
                            : null);
                    waitForSignal = context.ResetAndGetSparseSenderPumpSignalTask();
                }
                else if (context.UserPaused || context.PeerPaused || (transportPaused && !allowPausedRepair))
                {
                    if (transportPaused)
                    {
                        MarkOutboundV4SenderPumpTransportPausedLocked(context);
                    }
                    else
                    {
                        MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: false);
                    }

                    waitForSignal = context.ResetAndGetSparseSenderPumpSignalTask();
                }
                else if (context.PullV4SenderPumpRepairQueue.Count > 0)
                {
                    while (context.PullV4SenderPumpRepairQueue.Count > 0 && repairSend is null)
                    {
                        var queuedRepair = context.PullV4SenderPumpRepairQueue.Dequeue();
                        foreach (var chunkIndex in queuedRepair.ChunkIndices)
                        {
                            context.PullV4SenderPumpRepairQueuedChunkIndices.Remove(chunkIndex);
                        }

                        repairSend = RevalidateQueuedV4RepairSendLocked(context, queuedRepair);
                        if (repairSend is null)
                        {
                            if (context.PullV4SenderPumpRepairRequests.TryGetValue(queuedRepair.RepairRequestKey, out var skippedRepairState) &&
                                (queuedRepair.FallbackFrontierRepairContract is null ||
                                 ReferenceEquals(
                                     skippedRepairState.FallbackFrontierRepairContract,
                                     queuedRepair.FallbackFrontierRepairContract)))
                            {
                                skippedRepairState.Queued = false;
                                skippedRepairState.QueuedUtc = null;
                                skippedRepairState.LastSentUtc = DateTimeOffset.UtcNow;
                            }

                            continue;
                        }

                        if (context.PullV4SenderPumpRepairRequests.TryGetValue(repairSend.RepairRequestKey, out var repairState))
                        {
                            repairState.Queued = false;
                            repairState.QueuedUtc = null;
                            repairState.InFlight = true;
                        }
                    }
                }
                else if (!context.V4TerminalReady)
                {
                    if (ShouldBlockOutboundV4NormalSendAheadForFileTunaV4PostTunaRecoveryLocked(context))
                    {
                        MaybeQueueOutboundV4StalledRebindSafetyReplayLocked(context, "file_tuna_v4_post_tuna_frontier_repair_wait");
                        if (context.PullV4SenderPumpRepairQueue.Count == 0)
                        {
                            context.PullSenderSendWaitCountRecent++;
                            context.PullSenderSendWaitCountTotal++;
                            context.PullSenderFeedCreditWaitStartedUtc ??= DateTimeOffset.UtcNow;
                            context.V4SenderCreditExhaustedSinceUtc ??= DateTimeOffset.UtcNow;
                            context.SparseSenderPumpLastWakeReason = "file_tuna_v4_post_tuna_frontier_repair_wait";
                            MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: false);
                            waitForSignal = context.ResetAndGetSparseSenderPumpSignalTask();
                        }
                    }
                    else if (IsV6TransportHandoffBlockingTail(context.V6TransportHandoff))
                    {
                        var now = DateTimeOffset.UtcNow;
                        if (context.V6TransportHandoff is { State: not V6TransportHandoffState.Recovered } handoff &&
                            now - GetV6TransportHandoffActivityUtc(handoff) >= V6TransportHandoffWaitingTimeout &&
                            !HasOutboundV4RepairWorkInProgressLocked(context))
                        {
                            TrySetV6TransportHandoffState(
                                handoff,
                                FileTransferDirection.Outbound,
                                context.TransferId,
                                context.SessionId,
                                V6TransportHandoffState.WaitingForRegularNkn,
                                "proof_timeout",
                                context.RemoteNextExpectedChunkIndex,
                                Math.Max(-1, context.ChunksAcceptedForTransport - 1));
                            context.StatusMessage = "Waiting for regular NKN";
                        }

                        context.PullSenderSendWaitCountRecent++;
                        context.PullSenderSendWaitCountTotal++;
                        context.PullSenderFeedCreditWaitStartedUtc ??= DateTimeOffset.UtcNow;
                        context.V4SenderCreditExhaustedSinceUtc ??= DateTimeOffset.UtcNow;
                        context.SparseSenderPumpLastWakeReason = "v6_handoff_tail_blocked";
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_v6_tail_blocked_until_frontier_proof; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; transport_epoch={context.V6TransportHandoff!.EpochId}; state={FormatV6TransportHandoffState(context.V6TransportHandoff.State)}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; repair_queue_depth={context.PullV4SenderPumpRepairQueue.Count}");
                        if (!TryPrepareOutboundPostTunaFallbackLiveCheckpointTailReconciliationLocked(
                                context,
                                out tailStateRefreshRequest))
                        {
                            MaybeQueueOutboundV4StalledRebindSafetyReplayLocked(context, "v6_handoff_tail_blocked");
                        }
                        MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: false);
                        waitForSignal = context.ResetAndGetSparseSenderPumpSignalTask();
                    }
                    else
                    {
                        var startChunk = context.ChunksAcceptedForTransport;
                        var grantedUntilExclusive = Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount);
                        if (grantedUntilExclusive > startChunk)
                        {
                            if (context.PullSenderFeedCreditWaitStartedUtc is not null)
                            {
                                context.PullSenderFeedCreditWaitMsRecent += (long)Math.Max(
                                    0,
                                    (DateTimeOffset.UtcNow - context.PullSenderFeedCreditWaitStartedUtc.Value).TotalMilliseconds);
                                context.PullSenderFeedCreditWaitStartedUtc = null;
                            }

                            context.V4SenderCreditExhaustedSinceUtc = null;

                            var maxNormalChunksThisPass = Math.Max(
                                1,
                                (int)Math.Ceiling(V4SenderPumpPendingBytes / (double)Math.Max(1, context.ChunkSizeBytes)));
                            var chunkCountThisPass = Math.Min(
                                grantedUntilExclusive - startChunk,
                                Math.Min(maxNormalChunksThisPass, V4NormalSendQuantumChunks));
                            chunkIndicesToSend = Enumerable.Range(startChunk, chunkCountThisPass).ToList();
                        }
                        else
                        {
                            if (MaybeQueueOutboundFileTunaV4PostTunaFrontierReplayLocked(
                                    context,
                                    "file_tuna_v4_post_tuna_sender_wait"))
                            {
                                continue;
                            }

                            MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(
                                context,
                                "regular_v4_sender_wait");
                            if (context.PullV4SenderPumpRepairQueue.Count > 0)
                            {
                                continue;
                            }

                            context.PullSenderSendWaitCountRecent++;
                            context.PullSenderSendWaitCountTotal++;
                            context.PullSenderFeedCreditWaitStartedUtc ??= DateTimeOffset.UtcNow;
                            context.V4SenderCreditExhaustedSinceUtc ??= DateTimeOffset.UtcNow;
                            MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: false);
                            waitForSignal = context.ResetAndGetSparseSenderPumpSignalTask();
                        }
                    }
                }
                else
                {
                    MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: false);
                    waitForSignal = context.ResetAndGetSparseSenderPumpSignalTask();
                }
            }

            if (completeFromTerminalReady)
            {
                if (OutboundSparseTerminalCompletionBarrierForTests is { } terminalCompletionBarrier)
                {
                    await terminalCompletionBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                }

                await TransitionOutboundToTerminalAsync(
                    context,
                    FileTransferTransferState.Completed,
                    errorCode: null,
                    statusMessage: "Transfer complete.",
                    notifyPeer: false,
                    cancelReason: null,
                    ct: CancellationToken.None,
                    requiredSparsePumpInstall: pumpInstall).ConfigureAwait(false);
                return;
            }

            if (tailStateRefreshRequest is not null)
            {
                if (OutboundSparseTailReconciliationQueueBarrierForTests is { } tailReconciliationQueueBarrier)
                {
                    await tailReconciliationQueueBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                }

                QueueOutboundV4SparseRuntimeStateRefreshIfCurrent(
                    context,
                    dataSession,
                    tailStateRefreshRequest,
                    "tail_reconciliation",
                    pumpInstall,
                    pumpInstall?.RuntimeOwner,
                    dataSession,
                    pumpInstall?.DataSessionGeneration ?? 0);
                continue;
            }

            if (repairSend is not null)
            {
                var repairDelivered = true;
                FileTransferReceiveRecoveryOperation? receiveRecoveryHoldOperation = null;
                string? receiveRecoveryHoldStage = null;
                string? receiveRecoveryHoldReason = null;
                FileTransferDataPathSendAuthority? repairSendAuthority = null;
                RepairReplayDecision? repairReplayDecisionForDispatch = null;
                FileTransferLeg? repairReplayLegForDispatch = null;
                var logFallbackFrontierRepairDispatchProof = false;
                FallbackFrontierRepairContract? fallbackFrontierContractForDispatch = null;
                FileTransferRegularV4FrontierRepairAuthority? regularV4RepairAuthorityForDispatch = null;
                RegularV4FrontierRepairContract? regularV4RepairContractForDispatch = null;
                RegularV4FrontierRepairScheduledDispatch? regularV4ScheduledDispatchForDispatch = null;
                IReadOnlyList<int> repairChunkIndicesForDispatch = repairSend.ChunkIndices;
                long regularV4RepairInstallGenerationForDispatch = 0;
                var logRegularV4FrontierRepairDispatchProof = false;
                if (repairSend.ChunkIndices.Count > 0)
                {
                    var staleRuntimeOwner = false;
                    var repairReplayKind = ResolveRepairReplayKind(repairSend);
                    lock (gate)
                    {
                        if (ReferenceEquals(outboundTransfer, context))
                        {
                            if (repairSend.FallbackFrontierRepairContract is { } ambiguousFallbackContract &&
                                repairSend.RegularV4RepairContract is { } ambiguousRegularContract)
                            {
                                TrySettleFallbackFrontierRepairContract(
                                    ambiguousFallbackContract,
                                    FallbackFrontierRepairSettlementOutcome.StaleRejected,
                                    "repair_dispatch_contract_ambiguous");
                                TrySettleRegularV4FrontierRepairContract(
                                    ambiguousRegularContract,
                                    FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
                                    repairSend.RequestedChunkCount,
                                    "repair_dispatch_contract_ambiguous");
                                LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                                    FileTransferDirection.Outbound,
                                    context.TransferId,
                                    context.SessionId,
                                    context.CurrentTransferLeg,
                                    repairSend.RepairRequestKey,
                                    "v4_repair_send",
                                    "send",
                                    "repair_dispatch_contract_ambiguous",
                                    repairSend.RemoteNextExpectedChunkIndex,
                                    Math.Max(-1, repairSend.RemoteNextExpectedChunkIndex - 1),
                                    repairSend.RequestedChunkCount,
                                    ambiguousRegularContract.Authority,
                                    GetRegularV4FrontierRepairPressureInstallGeneration(
                                        CreateCoordinatorStateLocked(context),
                                        ambiguousRegularContract),
                                    repairSend.FirstStartChunkIndex,
                                    repairSend.LastEndChunkExclusive,
                                    "ambiguous_attached_contracts");
                                MarkOutboundV4QueuedRepairSuppressedLocked(context, repairSend);
                                staleRuntimeOwner = true;
                            }
                            else if (repairSend.FallbackFrontierRepairContract is { } forwardedFallbackContract)
                            {
                                if (!TryValidateOutboundFallbackFrontierDispatchLocked(
                                        context,
                                        forwardedFallbackContract,
                                        out var fallbackContractRejectionReason))
                                {
                                    TrySettleFallbackFrontierRepairContract(
                                        forwardedFallbackContract,
                                        FallbackFrontierRepairSettlementOutcome.StaleRejected,
                                        fallbackContractRejectionReason);
                                    MarkOutboundV4QueuedRepairSuppressedLocked(context, repairSend);
                                    staleRuntimeOwner = true;
                                }
                                else
                                {
                                    fallbackFrontierContractForDispatch = forwardedFallbackContract;
                                    context.V4SenderPumpLastRepairRequestKey =
                                        forwardedFallbackContract.Authority.CanonicalRepairKey;
                                }
                            }
                            else if (repairSend.RegularV4RepairContract is { } attachedRegularContract)
                            {
                                regularV4RepairContractForDispatch = attachedRegularContract;
                                if (!TryValidateOutboundRegularV4FrontierRepairDispatchLocked(
                                        context,
                                        repairSend,
                                        repairReplayKind,
                                        regularV4RepairContractForDispatch,
                                        out var contractRejectionReason))
                                {
                                    LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                                        FileTransferDirection.Outbound,
                                        context.TransferId,
                                        context.SessionId,
                                        context.CurrentTransferLeg,
                                        repairSend.RepairRequestKey,
                                        "v4_repair_send",
                                        "send",
                                        contractRejectionReason,
                                        repairSend.RemoteNextExpectedChunkIndex,
                                        Math.Max(-1, repairSend.RemoteNextExpectedChunkIndex - 1),
                                        repairSend.RequestedChunkCount,
                                        regularV4RepairContractForDispatch.Authority,
                                        GetRegularV4FrontierRepairPressureInstallGeneration(
                                            CreateCoordinatorStateLocked(context),
                                            regularV4RepairContractForDispatch),
                                        repairSend.FirstStartChunkIndex,
                                        repairSend.LastEndChunkExclusive,
                                        "attached_installed_contract");
                                    TrySettleRegularV4FrontierRepairContract(
                                        regularV4RepairContractForDispatch,
                                        FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
                                        repairSend.RequestedChunkCount,
                                        contractRejectionReason);
                                    MarkOutboundV4QueuedRepairSuppressedLocked(context, repairSend);
                                    staleRuntimeOwner = true;
                                }
                                else
                                {
                                    regularV4RepairAuthorityForDispatch = regularV4RepairContractForDispatch.Authority;
                                    regularV4RepairInstallGenerationForDispatch =
                                        GetRegularV4FrontierRepairPressureInstallGeneration(
                                            CreateCoordinatorStateLocked(context),
                                            regularV4RepairContractForDispatch);
                                    regularV4ScheduledDispatchForDispatch =
                                        regularV4RepairContractForDispatch.ScheduledDispatch;
                                    repairChunkIndicesForDispatch =
                                        regularV4ScheduledDispatchForDispatch!.ChunkIndices;
                                    logRegularV4FrontierRepairDispatchProof = true;
                                    context.V4SenderPumpLastRepairRequestKey = repairSend.RepairRequestKey;
                                }
                            }
                            else if (repairSend.CoordinatorBackedRegularV4PeerSilenceReplay)
                            {
                                RegularV4FrontierRepairContract? missingAttachedContract = null;
                                if (repairReplayKind == RepairReplayKind.PeerSilenceReplay &&
                                    context.CurrentRegularV4FrontierRepairContract is { } currentContract &&
                                    TryValidateOutboundRegularV4FrontierRepairDispatchLocked(
                                        context,
                                        repairSend,
                                        repairReplayKind,
                                        currentContract,
                                        out _))
                                {
                                    missingAttachedContract = currentContract;
                                    TrySettleRegularV4FrontierRepairContract(
                                        currentContract,
                                        FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
                                        repairSend.RequestedChunkCount,
                                        "repair_authority_missing");
                                }

                                LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                                    FileTransferDirection.Outbound,
                                    context.TransferId,
                                    context.SessionId,
                                    context.CurrentTransferLeg,
                                    repairSend.RepairRequestKey,
                                    "v4_repair_send",
                                    "send",
                                    "repair_authority_missing",
                                    repairSend.RemoteNextExpectedChunkIndex,
                                    Math.Max(-1, repairSend.RemoteNextExpectedChunkIndex - 1),
                                    repairSend.RequestedChunkCount,
                                    authority: missingAttachedContract?.Authority,
                                    installGeneration:
                                        GetRegularV4FrontierRepairPressureInstallGeneration(
                                            CreateCoordinatorStateLocked(context),
                                            missingAttachedContract),
                                    scheduledStartChunkIndex: repairSend.FirstStartChunkIndex,
                                    scheduledEndChunkExclusive: repairSend.LastEndChunkExclusive,
                                    dispatchAuthoritySource: "attached_installed_contract_missing");
                                MarkOutboundV4QueuedRepairSuppressedLocked(context, repairSend);
                                staleRuntimeOwner = true;
                            }
                            else if (!TryAuthorizeRepairReplayLocked(
                                    context,
                                    repairSend.RuntimeOwner,
                                    repairReplayKind,
                                    "v4_repair_send",
                                    repairSend.DeliveryEscalationReason,
                                    context.CurrentTransferLeg,
                                    context.CurrentTransferLeg?.TransportEpochId,
                                    context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                                    null,
                                    out var repairReplayDecision))
                            {
                                if (ShouldLogFallbackFrontierRepairProof(repairReplayKind, context.CurrentTransferLeg, repairSend.RepairRequestKey))
                                {
                                    LogFileTransferFallbackFrontierRepairAuthorityRejected(
                                        FileTransferDirection.Outbound,
                                        context.TransferId,
                                        context.SessionId,
                                        context.CurrentTransferLeg,
                                        repairSend.RepairRequestKey,
                                        "v4_repair_send",
                                        "send",
                                        "coordinator_authority_rejected",
                                        repairReplayKind);
                                }

                                if (ShouldLogRegularV4FrontierRepairProof(
                                        repairReplayKind,
                                        context.CurrentTransferLeg,
                                        IsQueuedV4FrontierRepair(repairSend)))
                                {
                                    LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                                        FileTransferDirection.Outbound,
                                        context.TransferId,
                                        context.SessionId,
                                        context.CurrentTransferLeg,
                                        repairSend.RepairRequestKey,
                                        "v4_repair_send",
                                        "send",
                                        "coordinator_authority_rejected",
                                        repairSend.RemoteNextExpectedChunkIndex,
                                        Math.Max(-1, repairSend.RemoteNextExpectedChunkIndex - 1),
                                        repairSend.RequestedChunkCount);
                                }

                                MarkOutboundV4QueuedRepairSuppressedLocked(context, repairSend);
                                staleRuntimeOwner = true;
                            }
                            else
                            {
                                if (repairReplayDecision is { } grantedDecision &&
                                    ShouldLogFallbackFrontierRepairProof(repairReplayKind, context.CurrentTransferLeg, repairSend.RepairRequestKey))
                                {
                                    repairReplayDecisionForDispatch = grantedDecision;
                                    repairReplayLegForDispatch = context.CurrentTransferLeg;
                                    logFallbackFrontierRepairDispatchProof = true;
                                    LogFileTransferFallbackFrontierRepairAuthorityGranted(
                                        FileTransferDirection.Outbound,
                                        context.TransferId,
                                        context.SessionId,
                                        grantedDecision,
                                        context.CurrentTransferLeg,
                                        repairSend.RepairRequestKey,
                                        "v4_repair_send",
                                        "send",
                                        repairSend.RangeCount,
                                        repairSend.RequestedChunkCount,
                                        repairSend.ChunkIndices.Count);
                                }

                                context.V4SenderPumpLastRepairRequestKey = repairSend.RepairRequestKey;
                            }
                        }
                    }

                    if (staleRuntimeOwner)
                    {
                        continue;
                    }

                    repairDelivered = await SendChunkIndicesV4Async(
                        context,
                        stream,
                        dataSession,
                        repairChunkIndicesForDispatch,
                        repairSend: true,
                        repairRequestKey: repairSend.RepairRequestKey,
                        protocolRepairRequestId: repairSend.ProtocolRepairRequestId,
                        protocolPriority: repairSend.ProtocolPriority,
                        protocolRecoveryMode: repairSend.ProtocolRecoveryMode,
                        repairDeliveryMode: repairSend.DeliveryMode,
                        repairDeliveryReason: repairSend.DeliveryEscalationReason,
                        fallbackFrontierRepairContract: fallbackFrontierContractForDispatch,
                        regularV4FrontierRepairContract: regularV4RepairContractForDispatch,
                        regularV4ScheduledDispatch: regularV4ScheduledDispatchForDispatch,
                        observeSendAuthority: authority => repairSendAuthority ??= authority,
                        observeReceiveRecoveryHold: (operation, stage, reason) =>
                        {
                            receiveRecoveryHoldOperation ??= operation;
                            receiveRecoveryHoldStage ??= stage;
                            receiveRecoveryHoldReason ??= reason;
                        },
                        pumpInstall: pumpInstall,
                        pumpCancellationToken: pumpToken).ConfigureAwait(false);
                }

                if (pumpInstall is not null &&
                    OutboundSparseRepairContinuationBarrierForTests is { } repairContinuationBarrier)
                {
                    await repairContinuationBarrier(
                            context.TransferId,
                            context.SessionId,
                            "repair_send_completion")
                        .ConfigureAwait(false);
                }

                var sentUtc = DateTimeOffset.UtcNow;
                var pumpCompletionCurrent = false;
                var fallbackRepairCompletionCurrent = true;
                var regularV4RepairCompletionCurrent = true;
                var regularV4DispatchMarked = false;
                lock (gate)
                {
                    pumpCompletionCurrent = IsOutboundSparsePumpContinuationCurrentLocked(
                        context,
                        pumpInstall,
                        dataSession);
                    if (pumpCompletionCurrent && ReferenceEquals(outboundTransfer, context))
                    {
                        var fallbackCompletionRejectionReason = context.IsTerminal
                            ? "legacy_sparse_pump_completion_after_terminal"
                            : "legacy_sparse_pump_contract_rejected";
                        if (repairSend.FallbackFrontierRepairContract is { } completedFallbackContract &&
                            (context.IsTerminal ||
                             !TryValidateOutboundFallbackFrontierDispatchLocked(
                                 context,
                                 completedFallbackContract,
                                 out fallbackCompletionRejectionReason)))
                        {
                            fallbackRepairCompletionCurrent = false;
                            TrySettleFallbackFrontierRepairContract(
                                completedFallbackContract,
                                context.IsTerminal
                                    ? FallbackFrontierRepairSettlementOutcome.TerminalRejected
                                    : FallbackFrontierRepairSettlementOutcome.StaleRejected,
                                fallbackCompletionRejectionReason);
                        }

                        var regularCompletionRejectionReason = context.IsTerminal
                            ? "regular_v4_sparse_pump_completion_after_terminal"
                            : "regular_v4_sparse_pump_contract_rejected";
                        if (repairSend.RegularV4RepairContract is { } completedRegularContract &&
                            (context.IsTerminal ||
                             !TryValidateOutboundRegularV4FrontierRepairDispatchLocked(
                                  context,
                                  repairSend,
                                  ResolveRepairReplayKind(repairSend),
                                  completedRegularContract,
                                  out regularCompletionRejectionReason)))
                        {
                            regularV4RepairCompletionCurrent = false;
                            TrySettleRegularV4FrontierRepairContract(
                                completedRegularContract,
                                context.IsTerminal
                                    ? FileTransferRegularV4FrontierRepairSettlementOutcome.TerminalRejected
                                    : FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
                                repairSend.RequestedChunkCount,
                                regularCompletionRejectionReason);
                        }

                        if (regularV4RepairCompletionCurrent &&
                            repairDelivered &&
                            repairSend.RegularV4RepairContract is { } currentRegularContract)
                        {
                            regularV4DispatchMarked = TryMarkRegularV4FrontierRepairDispatched(
                                context,
                                currentRegularContract);
                            if (regularV4DispatchMarked)
                            {
                                TryAdvanceOutboundRegularV4PeerSilenceReplayCursorLocked(
                                    context,
                                    repairSend,
                                    currentRegularContract);
                            }
                        }

                        if (context.PullV4SenderPumpRepairRequests.TryGetValue(repairSend.RepairRequestKey, out var repairState) &&
                            regularV4RepairCompletionCurrent &&
                            (repairSend.FallbackFrontierRepairContract is null ||
                             ReferenceEquals(
                                 repairState.FallbackFrontierRepairContract,
                                 repairSend.FallbackFrontierRepairContract)))
                        {
                            repairState.InFlight = false;
                            if (fallbackRepairCompletionCurrent && repairDelivered)
                            {
                                repairState.LastSentUtc = sentUtc;
                                repairState.SentCount++;
                                repairState.LastSentRemoteFrontierChunkIndex = repairSend.RemoteNextExpectedChunkIndex;
                            }
                            else if (ShouldRecordFailedPostTunaFallbackExactFrontierRepairAttemptLocked(context, repairSend))
                            {
                                repairState.LastSentUtc = sentUtc;
                                repairState.SentCount = Math.Max(1, repairState.SentCount);
                                repairState.LastSentRemoteFrontierChunkIndex = repairSend.RemoteNextExpectedChunkIndex;
                                LocalOperationalLog.Warn(
                                    "FileTransferService",
                                    $"event=filetransfer_v4_repair_attempt_recorded_after_deferred_send; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairSend.RepairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(repairSend.ProtocolRepairRequestId ?? "(none)")}; reason=post_tuna_fallback_exact_frontier_deferred; first_start_chunk_index={repairSend.FirstStartChunkIndex}; last_end_chunk_exclusive={repairSend.LastEndChunkExclusive}; remote_next_expected_chunk_index={repairSend.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={repairSend.ChunksAcceptedForTransport}");
                            }
                        }
                    }
                }

                if (!pumpCompletionCurrent)
                {
                    LogOutboundSparsePumpInstallRejected(
                        context,
                        pumpInstall,
                        "repair_send_completion",
                        "install_no_longer_current");
                    continue;
                }

                if (!fallbackRepairCompletionCurrent)
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v4_repair_pump_completion_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(repairSend.FallbackFrontierRepairContract?.Authority.AuthorityId.ToString() ?? "(none)")}; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={FormatProtocolLogValue(repairSend.RepairRequestKey)}; decision_reason=late_or_stale_pump_completion");
                    continue;
                }

                if (!regularV4RepairCompletionCurrent)
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_regular_v4_repair_pump_completion_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(repairSend.RegularV4RepairContract?.Authority.AuthorityId.ToString() ?? "(none)")}; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={FormatProtocolLogValue(repairSend.RepairRequestKey)}; decision_reason=late_or_stale_pump_completion");
                    continue;
                }

                if (!repairDelivered &&
                    receiveRecoveryHoldOperation is null)
                {
                    lock (gate)
                    {
                        if (IsOutboundSparsePumpContinuationCurrentLocked(
                                context,
                                pumpInstall,
                                dataSession) &&
                            TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                                context,
                                out var operation,
                                out var holdReason))
                        {
                            receiveRecoveryHoldOperation = operation;
                            receiveRecoveryHoldStage =
                                "repair_completion";
                            receiveRecoveryHoldReason = holdReason;
                        }
                    }
                }

                if (!repairDelivered &&
                    receiveRecoveryHoldOperation is { } heldOperation)
                {
                    var restoredForReceiveRecovery = false;
                    lock (gate)
                    {
                        if (IsOutboundSparsePumpContinuationCurrentLocked(
                                context,
                                pumpInstall,
                                dataSession))
                        {
                            restoredForReceiveRecovery =
                                TryRestoreOutboundV4RepairHeldForReceiveRecoveryLocked(
                                    context,
                                    repairSend,
                                    heldOperation,
                                    receiveRecoveryHoldStage ??
                                        "physical_submission",
                                    receiveRecoveryHoldReason ??
                                        "filetransfer_receive_recovery_execution_current");
                        }
                    }

                    if (restoredForReceiveRecovery)
                    {
                        continue;
                    }
                }

                if (!repairDelivered)
                {
                    var regularV4PeerSilenceRepair =
                        ResolveRepairReplayKind(repairSend) == RepairReplayKind.PeerSilenceReplay;
                    var requeuedRegularV4PeerSilenceRepair = false;
                    var requeuedRegularV4PeerSilenceRepairChunkCount = 0;
                    var requeueSettlementObserved = false;
                    FileTransferRegularV4FrontierRepairAuthority? successorRegularV4RepairAuthority = null;
                    RuntimeUnlockRetryDispatchAuthorityRequest? pendingRuntimeUnlockRetryRequest = null;
                    lock (gate)
                    {
                        if (regularV4PeerSilenceRepair &&
                            IsOutboundSparsePumpContinuationCurrentLocked(
                                context,
                                pumpInstall,
                                dataSession))
                        {
                            pendingRuntimeUnlockRetryRequest =
                                GetPendingRuntimeUnlockRetryDispatchAuthorityRequest(context);
                        }
                    }
                    var pendingRuntimeUnlockRetryDispatch = pendingRuntimeUnlockRetryRequest is not null;
                    var requeuedFallbackFrontierRepair = false;
                    var requeuedFallbackFrontierRepairChunkCount = 0;
                    FallbackFrontierRepairContract? successorFallbackFrontierContract = null;

                    if (repairSend.FallbackFrontierRepairContract is not null)
                    {
                        lock (gate)
                        {
                            if (IsOutboundSparsePumpContinuationCurrentLocked(
                                    context,
                                    pumpInstall,
                                    dataSession))
                            {
                                requeuedFallbackFrontierRepair =
                                    TryRequeueOutboundFallbackFrontierV4RetryLocked(
                                        context,
                                        repairSend,
                                        out successorFallbackFrontierContract,
                                        out requeuedFallbackFrontierRepairChunkCount);
                            }
                        }
                    }

                    if (pendingRuntimeUnlockRetryRequest is { } pendingRetryRequest &&
                        regularV4RepairContractForDispatch is { } pendingReleaseContract)
                    {
                        lock (gate)
                        {
                            if (IsOutboundSparsePumpContinuationCurrentLocked(
                                    context,
                                    pumpInstall,
                                    dataSession))
                            {
                                requeueSettlementObserved = TrySettleRegularV4FrontierRepairContract(
                                    pendingReleaseContract,
                                    FileTransferRegularV4FrontierRepairSettlementOutcome.MissingDispatch,
                                    repairSend.RequestedChunkCount,
                                    "regular_v4_frontier_repair_missing_dispatch");
                            }
                        }
                        pendingRuntimeUnlockRetryDispatch = requeueSettlementObserved;
                    }

                    var deferredEventName = IsFileTunaV4PostTunaRecoveryActiveLocked(context)
                        ? "filetransfer_v4_repair_send_deferred_for_file_tuna_v4_post_tuna_recovery"
                        : regularV4PeerSilenceRepair
                            ? "filetransfer_v4_repair_send_deferred_for_regular_v4_peer_silence_repair"
                            : "filetransfer_v4_repair_send_deferred_for_v6_regular_nkn_sparse_runtime";
                    if (logRegularV4FrontierRepairDispatchProof && regularV4RepairAuthorityForDispatch is { } regularDeferredAuthority)
                    {
                        LogFileTransferRegularV4FrontierRepairSendDeferred(
                            FileTransferDirection.Outbound,
                            context.TransferId,
                            context.SessionId,
                            regularDeferredAuthority,
                            repairSend.ProtocolRepairRequestId ?? "(none)",
                            "send",
                            repairSend.ChunkIndices.Count,
                            repairSend.RemoteNextExpectedChunkIndex,
                            repairSend.ChunksAcceptedForTransport,
                            deferredEventName,
                            repairSend.DeliveryMode,
                            repairSend.DeliveryEscalationReason);
                        if (regularV4PeerSilenceRepair)
                        {
                            LogFileTransferRegularV4FrontierRepairMissingDispatch(
                                FileTransferDirection.Outbound,
                                context.TransferId,
                                context.SessionId,
                                regularDeferredAuthority,
                                repairSend.ProtocolRepairRequestId ?? "(none)",
                                "send",
                                repairSend.ChunkIndices.Count,
                                repairSend.RemoteNextExpectedChunkIndex,
                                repairSend.ChunksAcceptedForTransport,
                                pendingRuntimeUnlockRetryDispatch
                                    ? "send_deferred_runtime_unlock_arbitration"
                                    : "send_deferred_successor_decision_pending");
                        }
                    }

                    if (regularV4PeerSilenceRepair && !pendingRuntimeUnlockRetryDispatch)
                    {
                        lock (gate)
                        {
                            if (IsOutboundSparsePumpContinuationCurrentLocked(
                                    context,
                                    pumpInstall,
                                    dataSession))
                            {
                                requeuedRegularV4PeerSilenceRepair =
                                    TryRequeueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(
                                        context,
                                        repairSend,
                                        out requeuedRegularV4PeerSilenceRepairChunkCount,
                                        out successorRegularV4RepairAuthority,
                                        out requeueSettlementObserved);
                            }
                        }
                    }

                    if (logRegularV4FrontierRepairDispatchProof && regularV4RepairAuthorityForDispatch is { } currentDeferredAuthority)
                    {
                        if (requeuedRegularV4PeerSilenceRepair && successorRegularV4RepairAuthority is { } successorAuthority)
                        {
                            LogFileTransferRegularV4FrontierRepairSuccessorAuthorized(
                                FileTransferDirection.Outbound,
                                context.TransferId,
                                context.SessionId,
                                currentDeferredAuthority,
                                successorAuthority,
                                repairSend.ChunkIndices.Count,
                                requeuedRegularV4PeerSilenceRepairChunkCount,
                                "send_timeout_successor_authorized");
                            var observeSuccessorCurrent = false;
                            lock (gate)
                            {
                                observeSuccessorCurrent = IsOutboundSparsePumpContinuationCurrentLocked(
                                    context,
                                    pumpInstall,
                                    dataSession);
                            }

                            if (observeSuccessorCurrent)
                            {
                                ObserveRegularV4FrontierRepairDispatchBlocker(
                                    context,
                                    successorAuthority,
                                    requeuedRegularV4PeerSilenceRepairChunkCount,
                                    "regular_v4_frontier_repair_successor_authorized");
                            }
                        }
                        else if (!requeueSettlementObserved)
                        {
                            if (regularV4PeerSilenceRepair)
                            {
                                lock (gate)
                                {
                                    if (IsOutboundSparsePumpContinuationCurrentLocked(
                                            context,
                                            pumpInstall,
                                            dataSession))
                                    {
                                        TrySettleRegularV4FrontierRepairContract(
                                            regularV4RepairContractForDispatch,
                                            FileTransferRegularV4FrontierRepairSettlementOutcome.MissingDispatch,
                                            repairSend.RequestedChunkCount,
                                            "regular_v4_frontier_repair_missing_dispatch");
                                    }
                                }
                            }
                        }
                    }

                    LocalOperationalLog.Warn(
                        "FileTransferService",
                        $"event={deferredEventName}; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairSend.RepairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(repairSend.ProtocolRepairRequestId ?? "(none)")}; range_count={repairSend.RangeCount}; requested_chunk_count={repairSend.RequestedChunkCount}; scheduled_chunk_count={repairSend.ChunkIndices.Count}; repair_delivery_mode={FormatV4RepairDeliveryMode(repairSend.DeliveryMode)}; repair_delivery_escalation_reason={repairSend.DeliveryEscalationReason}; first_start_chunk_index={repairSend.FirstStartChunkIndex}; last_end_chunk_exclusive={repairSend.LastEndChunkExclusive}; remote_next_expected_chunk_index={repairSend.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={repairSend.ChunksAcceptedForTransport}; fallback_successor_authority_id={FormatProtocolLogValue(successorFallbackFrontierContract?.Authority.AuthorityId.ToString() ?? "(none)")}; fallback_requeued_chunk_count={requeuedFallbackFrontierRepairChunkCount}; fallback_successor_requeued={(requeuedFallbackFrontierRepair ? 1 : 0)}");
                    if (requeuedRegularV4PeerSilenceRepair)
                    {
                        LocalOperationalLog.Warn(
                            "FileTransferService",
                            $"event=filetransfer_regular_v4_peer_silence_safety_replay_requeued_after_send_timeout; transfer_id={context.TransferId}; session_id={context.SessionId}; predecessor_repair_request_key={repairSend.RepairRequestKey}; successor_repair_request_key={FormatProtocolLogValue(successorRegularV4RepairAuthority?.RepairKey ?? "(none)")}; requeued_chunk_count={requeuedRegularV4PeerSilenceRepairChunkCount}; first_start_chunk_index={repairSend.FirstStartChunkIndex}; last_end_chunk_exclusive={repairSend.LastEndChunkExclusive}; remote_next_expected_chunk_index={repairSend.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={repairSend.ChunksAcceptedForTransport}");
                    }

                    continue;
                }

                var fileTunaV4PostTunaRepairProved = false;
                var fileTunaV4PostTunaRebindGeneration = 0;
                lock (gate)
                {
                    if (IsOutboundSparsePumpContinuationCurrentLocked(
                            context,
                            pumpInstall,
                            dataSession) &&
                        ShouldPauseOutboundV4SenderPumpForFileTunaV4PostTunaRecoveryLocked(context))
                    {
                        context.PullTransportPaused = false;
                        context.PullTransportPausedSinceUtc = null;
                        context.PullTransportGraceDeadlineUtc = null;
                        context.PullTransportPauseReason = null;
                        context.PullTransportResumeRequestPending = false;
                        context.SparseSenderPumpLastWakeReason = "file_tuna_v4_post_tuna_repair_proved";
                        fileTunaV4PostTunaRepairProved = true;
                        fileTunaV4PostTunaRebindGeneration = context.PullTransportRebindGeneration;
                    }
                }

                if (fileTunaV4PostTunaRepairProved)
                {
                    LogTransportResumed(
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        "file_tuna_v4_post_tuna_repair_proved",
                        requiresResumeRequest: false);
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_file_tuna_v4_post_tuna_recovery_cleanup_completed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; proof=file_transfer_v4_repair_sent; rebind_generation={fileTunaV4PostTunaRebindGeneration}; repair_request_key={repairSend.RepairRequestKey}; sent_chunk_count={repairSend.ChunkIndices.Count}");
                }

                if (logFallbackFrontierRepairDispatchProof && repairReplayDecisionForDispatch is { } dispatchDecision)
                {
                    LogFileTransferFallbackFrontierRepairDispatched(
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        dispatchDecision,
                        repairReplayLegForDispatch,
                        repairSend.RepairRequestKey,
                        repairSend.ProtocolRepairRequestId ?? "(none)",
                        "send",
                        repairSend.ChunkIndices.Count,
                        repairSend.RemoteNextExpectedChunkIndex,
                        repairSend.ChunksAcceptedForTransport);
                }

                if (logRegularV4FrontierRepairDispatchProof && regularV4RepairAuthorityForDispatch is { } regularDispatchAuthority)
                {
                    if (regularV4DispatchMarked)
                    {
                        LogFileTransferRegularV4FrontierRepairDispatched(
                            FileTransferDirection.Outbound,
                            context.TransferId,
                            context.SessionId,
                            regularDispatchAuthority,
                            repairSend.ProtocolRepairRequestId ?? "(none)",
                            "send",
                            repairSend.ChunkIndices.Count,
                            repairSend.RemoteNextExpectedChunkIndex,
                            repairSend.ChunksAcceptedForTransport,
                            regularV4RepairInstallGenerationForDispatch,
                            repairSend.FirstStartChunkIndex,
                            repairSend.LastEndChunkExclusive,
                            "attached_installed_contract");
                    }
                }

                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v4_repair_sent; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairSend.RepairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(repairSend.ProtocolRepairRequestId ?? "(none)")}; range_count={repairSend.RangeCount}; requested_chunk_count={repairSend.RequestedChunkCount}; sent_chunk_count={repairSend.ChunkIndices.Count}; sent_chunk_indices={FormatV4ChunkIndicesForLog(repairSend.ChunkIndices)}; transport_sent_chunk_count={repairSend.ChunkIndices.Count * V4RepairBatchSendAttempts}; repair_batch_send_attempt_count={V4RepairBatchSendAttempts}; repair_delivery_mode={FormatV4RepairDeliveryMode(repairSend.DeliveryMode)}; repair_delivery_escalation_reason={repairSend.DeliveryEscalationReason}; first_start_chunk_index={repairSend.FirstStartChunkIndex}; last_end_chunk_exclusive={repairSend.LastEndChunkExclusive}; frontier_tail_repair={(repairSend.FrontierTailRepair ? 1 : 0)}; credit_exhausted_time_ms_at_repair={repairSend.CreditExhaustedTimeMsAtDecision}; remote_next_expected_chunk_index={repairSend.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={repairSend.ChunksAcceptedForTransport}; skipped_obsolete_count={repairSend.SkippedObsoleteCount}; skipped_future_count={repairSend.SkippedFutureCount}; skipped_out_of_bounds_count={repairSend.SkippedOutOfBoundsCount}; sent_unix_ms={sentUtc.ToUnixTimeMilliseconds()}; receiver_proof_status=pending{FormatV4DataPathAuthoritySuffix(context, "filetransfer_v4_repair_sent", repairSendAuthority)}");
                continue;
            }

            if (chunkIndicesToSend is not null)
            {
                await SendChunkIndicesV4Async(
                    context,
                    stream,
                    dataSession,
                    chunkIndicesToSend,
                    repairSend: false,
                    pumpInstall: pumpInstall,
                    pumpCancellationToken: pumpToken).ConfigureAwait(false);
                continue;
            }

            if (waitForSignal is not null)
            {
                var completed = await Task.WhenAny(waitForSignal, Task.Delay(PullSessionReceivePollDelayMs, pumpToken)).ConfigureAwait(false);
                if (completed != waitForSignal)
                {
                    if (pumpInstall is not null &&
                        OutboundSparseRepairContinuationBarrierForTests is { } idleContinuationBarrier)
                    {
                        await idleContinuationBarrier(
                                context.TransferId,
                                context.SessionId,
                                "idle_delay")
                            .ConfigureAwait(false);
                    }

                    var idleContinuationCurrent = false;
                    lock (gate)
                    {
                        idleContinuationCurrent = IsOutboundSparsePumpContinuationCurrentLocked(
                            context,
                            pumpInstall,
                            dataSession);
                        if (idleContinuationCurrent)
                        {
                            if (TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                                    context,
                                    out var heldOperation,
                                    out var holdReason))
                            {
                                MarkOutboundPayloadSubmissionHeldForReceiveRecoveryLocked(
                                    context,
                                    heldOperation,
                                    "sender_pump_idle",
                                    holdReason,
                                    context.PullV4SenderPumpRepairQueue.Count > 0
                                        ? context.PullV4SenderPumpRepairQueue.Peek()
                                            .RegularV4RepairContract
                                        : null,
                                    context.PullV4SenderPumpRepairQueue.Count > 0
                                        ? context.PullV4SenderPumpRepairQueue.Peek()
                                            .RepairRequestKey
                                        : null);
                            }
                            else
                            {
                                if (TrySettleOutboundRegularV4FrontierRepairStalledLocked(
                                        context,
                                        DateTimeOffset.UtcNow,
                                        "regular_v4_frontier_repair_dispatch_stalled"))
                                {
                                    context.SparseSenderPumpLastWakeReason = "regular_v4_frontier_repair_settled_stalled";
                                    continue;
                                }

                                var transportPaused = ShouldPauseOutboundV4SenderPumpForTransportPauseLocked(context);
                                var allowPausedRepair = transportPaused &&
                                    ShouldAllowOutboundV4RepairWhileTransportPausedLocked(context);
                                if (!transportPaused || allowPausedRepair)
                                {
                                    MaybeQueueOutboundV4StalledRebindSafetyReplayLocked(context, "post_fallback_sender_wait");
                                    MaybeQueueOutboundFileTunaV4PostTunaFrontierReplayLocked(
                                        context,
                                        "file_tuna_v4_post_tuna_sender_wait");
                                    MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(context, "regular_v4_sender_wait");
                                }
                            }

                            MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: false);
                        }
                    }

                    if (!idleContinuationCurrent)
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            pumpInstall,
                            "idle_delay",
                            "install_no_longer_current");
                        return;
                    }
                }
            }
        }
    }

    private static bool ShouldUseSparseSenderTerminalReadyCompletion(OutboundTransferContext context)
        => context.RouteRuntime.UsesV4SparsePump ||
           ShouldUseV6SparseCreditEnvelope(context);

    private static bool ShouldCompleteOutboundV4FromTerminalReadyStateLocked(OutboundTransferContext context)
        => ShouldUseSparseSenderTerminalReadyCompletion(context) &&
           context.V4TerminalReady &&
           context.RemoteNextExpectedChunkIndex >= context.ChunkCount &&
           context.ChunksAcceptedForTransport >= context.ChunkCount &&
           Math.Max(context.BytesAcknowledgedByReceiver, context.BytesTransferred) >= context.FileSizeBytes &&
           context.PullSenderPipelineCurrentInFlightFrames <= 0;

    private void MaybeQueueOutboundV4StalledRebindSafetyReplayLocked(
        OutboundTransferContext context,
        string reason)
    {
        var recoveryGeneration = GetOutboundPostTunaRecoveryGenerationLocked(context);
        var allowFileTunaV4PostTunaReplay =
            context.RouteRuntime.UsesFileTunaV4Runtime &&
            context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
            context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4;
        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal ||
            context.UserPaused ||
            context.PeerPaused ||
            recoveryGeneration <= 0 ||
            (!context.PullPostTunaRecoveryActive && recoveryGeneration <= context.LastRecoveredV6TransportHandoffEpoch) ||
            (!allowFileTunaV4PostTunaReplay &&
                context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6) ||
            !context.PullSourceCanSeek ||
            context.RemoteNextExpectedChunkIndex >= context.ChunkCount)
        {
            return;
        }

        var now = DateTimeOffset.UtcNow;
        if (context.PullTransportLastSafetyReplayGeneration == context.PullTransportRebindGeneration &&
            context.PullTransportLastSafetyReplayUtc is { } lastReplayUtc &&
            now - lastReplayUtc < PullTransportRebindSafetyReplayRearmCooldown)
        {
            return;
        }

        QueueOutboundV4TransportRebindSafetyReplayLocked(context, reason, allowRepeatForSameGeneration: true);
    }

    private bool IsOutboundRegularV4PeerSilenceReplayCursorCurrentLocked(
        OutboundTransferContext context,
        OutboundRegularV4PeerSilenceReplayCursor cursor,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (!ReferenceEquals(outboundTransfer, context))
        {
            rejectionReason = "transfer_context_replaced";
            return false;
        }

        if (context.IsTerminal)
        {
            rejectionReason = "transfer_terminal";
            return false;
        }

        if (!context.RouteRuntime.UsesRegularNknV4FastRuntime ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4)
        {
            rejectionReason = "regular_v4_runtime_replaced";
            return false;
        }

        if (context.CurrentRuntimeOwner is not { IsDefault: false } owner ||
            owner != cursor.RuntimeOwner)
        {
            rejectionReason = "runtime_owner_replaced";
            return false;
        }

        if (context.CurrentRoutePublicationToken is not { IsDefault: false } publication ||
            publication != cursor.RoutePublication)
        {
            rejectionReason = "route_publication_replaced";
            return false;
        }

        if (context.CurrentTransferLeg is not { } leg ||
            context.TerminalGeneration != cursor.TerminalGeneration ||
            leg.Generation != cursor.LegGeneration ||
            leg.TransportEpochId != cursor.TransportEpoch ||
            leg.BridgeRecoveryGeneration != cursor.BridgeRecoveryGeneration ||
            (context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ?? 0) != cursor.BridgeDecisionGeneration ||
            context.DataSessionGeneration != cursor.DataSessionGeneration)
        {
            rejectionReason = "runtime_scope_replaced";
            return false;
        }

        return true;
    }

    private static string FormatOutboundRegularV4PeerSilenceReplayCursorTuple(
        OutboundRegularV4PeerSilenceReplayCursor cursor)
    {
        var owner = cursor.RuntimeOwner;
        var publication = cursor.RoutePublication;
        return $"cursor_generation={cursor.CursorGeneration}; session_id={FormatProtocolLogValue(owner.SessionId)}; transfer_id={FormatProtocolLogValue(owner.TransferId)}; direction=outbound; route={FormatProtocolLogValue(publication.RouteToken)}; protocol_version={publication.ProtocolVersion}; live_route_epoch={publication.LiveRouteEpoch}; runtime_generation={publication.RuntimeGeneration}; terminal_generation={cursor.TerminalGeneration}; leg_generation={cursor.LegGeneration}; transport_epoch={cursor.TransportEpoch}; bridge_recovery_generation={cursor.BridgeRecoveryGeneration}; bridge_decision_generation={cursor.BridgeDecisionGeneration}; route_publication_generation={publication.PublicationGeneration}; route_commit_generation={publication.RouteCommitGeneration ?? 0}; data_session_generation={cursor.DataSessionGeneration}; peer_frontier_chunk_index={cursor.PeerFrontierChunkIndex}; dispatch_proven_end_chunk_exclusive={cursor.DispatchProvenEndChunkIndex}; proving_authority_id={FormatProtocolLogValue(cursor.ProvingAuthorityId?.ToString() ?? "(none)")}; proving_repair_request_key={FormatProtocolLogValue(cursor.ProvingRepairKey ?? "(none)")}; proving_decision_generation={cursor.ProvingDecisionGeneration}";
    }

    private static void ResetOutboundRegularV4PeerSilenceReplayCursorLocked(
        OutboundTransferContext context,
        OutboundRegularV4PeerSilenceReplayCursor cursor,
        int nextPeerFrontierChunkIndex,
        string reason)
    {
        if (context.OutboundRegularV4PeerSilenceReplayCursor != cursor)
        {
            return;
        }

        context.OutboundRegularV4PeerSilenceReplayCursor = null;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_peer_silence_replay_cursor_reset; {FormatOutboundRegularV4PeerSilenceReplayCursorTuple(cursor)}; next_peer_frontier_chunk_index={nextPeerFrontierChunkIndex}; decision_reason={FormatProtocolLogValue(reason)}");
    }

    private OutboundRegularV4PeerSilenceReplayCursor? GetCurrentOutboundRegularV4PeerSilenceReplayCursorLocked(
        OutboundTransferContext context,
        int peerFrontierChunkIndex)
    {
        if (context.OutboundRegularV4PeerSilenceReplayCursor is not { } cursor)
        {
            return null;
        }

        if (!IsOutboundRegularV4PeerSilenceReplayCursorCurrentLocked(context, cursor, out var rejectionReason))
        {
            ResetOutboundRegularV4PeerSilenceReplayCursorLocked(
                context,
                cursor,
                peerFrontierChunkIndex,
                rejectionReason);
            return null;
        }

        if (cursor.PeerFrontierChunkIndex != peerFrontierChunkIndex)
        {
            ResetOutboundRegularV4PeerSilenceReplayCursorLocked(
                context,
                cursor,
                peerFrontierChunkIndex,
                "peer_frontier_advanced");
            return null;
        }

        return cursor;
    }

    private OutboundRegularV4PeerSilenceReplayCursor? RetainOutboundRegularV4PeerSilenceReplayCursorLocked(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        int peerFrontierChunkIndex,
        int scheduledStartChunkIndex,
        int scheduledEndChunkExclusive,
        string reason)
    {
        var cursor = GetCurrentOutboundRegularV4PeerSilenceReplayCursorLocked(context, peerFrontierChunkIndex);
        if (cursor is null)
        {
            if (contract.RepairDecision.RoutePublicationToken is not { IsDefault: false } publication)
            {
                return null;
            }

            var owner = contract.RepairDecision.RuntimeOwner;
            if (owner.IsDefault)
            {
                return null;
            }

            var cursorGeneration = Math.Max(
                1,
                context.LastOutboundRegularV4PeerSilenceReplayCursorGeneration + 1);
            cursor = new OutboundRegularV4PeerSilenceReplayCursor(
                cursorGeneration,
                owner,
                publication,
                contract.Authority.TerminalGeneration,
                contract.Authority.LegGeneration,
                contract.Authority.TransportEpoch,
                contract.Authority.BridgeRecoveryGeneration,
                contract.Authority.BridgeDecisionGeneration,
                context.DataSessionGeneration,
                peerFrontierChunkIndex,
                peerFrontierChunkIndex,
                ProvingAuthorityId: null,
                ProvingRepairKey: null,
                ProvingDecisionGeneration: 0);
            context.LastOutboundRegularV4PeerSilenceReplayCursorGeneration = cursorGeneration;
            context.OutboundRegularV4PeerSilenceReplayCursor = cursor;
        }

        var authority = contract.Authority;
        var installGeneration = GetRegularV4FrontierRepairPressureInstallGeneration(
            CreateCoordinatorStateLocked(context),
            contract);
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_peer_silence_replay_cursor_retained; {FormatOutboundRegularV4PeerSilenceReplayCursorTuple(cursor)}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(authority.PredecessorAuthorityId?.ToString() ?? "(none)")}; install_generation={installGeneration}; repair_generation={authority.DecisionGeneration}; repair_request_key={FormatProtocolLogValue(authority.RepairKey)}; scheduled_start_chunk_index={scheduledStartChunkIndex}; scheduled_end_chunk_exclusive={scheduledEndChunkExclusive}; dispatch_authority_source=attached_installed_contract; dispatch_observed={(contract.Lifecycle.DispatchObserved ? 1 : 0)}; settlement_outcome={FormatProtocolLogValue(contract.Lifecycle.SettlementOutcome?.ToString() ?? "(none)")}; decision_reason={FormatProtocolLogValue(reason)}");
        return cursor;
    }

    private bool TryAdvanceOutboundRegularV4PeerSilenceReplayCursorLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend repairSend,
        RegularV4FrontierRepairContract contract)
    {
        if (ResolveRepairReplayKind(repairSend) != RepairReplayKind.PeerSilenceReplay ||
            !contract.Lifecycle.DispatchObserved ||
            !ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, contract))
        {
            return false;
        }

        var peerFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var cursor = GetCurrentOutboundRegularV4PeerSilenceReplayCursorLocked(context, peerFrontier);
        if (cursor is null ||
            contract.RepairDecision.RuntimeOwner != cursor.RuntimeOwner ||
            contract.RepairDecision.RoutePublicationToken != cursor.RoutePublication)
        {
            return false;
        }

        var chunkIndices = repairSend.ChunkIndices;
        var contiguous = chunkIndices.Count == repairSend.RequestedChunkCount &&
                         chunkIndices.Count > 0 &&
                         chunkIndices[0] == cursor.DispatchProvenEndChunkIndex &&
                         repairSend.FirstStartChunkIndex == cursor.DispatchProvenEndChunkIndex &&
                         repairSend.LastEndChunkExclusive == cursor.DispatchProvenEndChunkIndex + chunkIndices.Count;
        for (var index = 1; contiguous && index < chunkIndices.Count; index++)
        {
            contiguous = chunkIndices[index] == chunkIndices[index - 1] + 1;
        }

        if (!contiguous)
        {
            RetainOutboundRegularV4PeerSilenceReplayCursorLocked(
                context,
                contract,
                peerFrontier,
                repairSend.FirstStartChunkIndex,
                repairSend.LastEndChunkExclusive,
                "dispatch_coverage_not_contiguous_from_cursor");
            return false;
        }

        var cursorGeneration = Math.Max(
            cursor.CursorGeneration + 1,
            context.LastOutboundRegularV4PeerSilenceReplayCursorGeneration + 1);
        var advanced = cursor with
        {
            CursorGeneration = cursorGeneration,
            DispatchProvenEndChunkIndex = repairSend.LastEndChunkExclusive,
            ProvingAuthorityId = contract.Authority.AuthorityId,
            ProvingRepairKey = contract.Authority.RepairKey,
            ProvingDecisionGeneration = contract.Authority.DecisionGeneration,
        };
        context.LastOutboundRegularV4PeerSilenceReplayCursorGeneration = cursorGeneration;
        context.OutboundRegularV4PeerSilenceReplayCursor = advanced;
        var installGeneration = GetRegularV4FrontierRepairPressureInstallGeneration(
            CreateCoordinatorStateLocked(context),
            contract);
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_peer_silence_replay_cursor_advanced; {FormatOutboundRegularV4PeerSilenceReplayCursorTuple(advanced)}; authority_id={FormatProtocolLogValue(contract.Authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(contract.Authority.PredecessorAuthorityId?.ToString() ?? "(none)")}; install_generation={installGeneration}; repair_generation={contract.Authority.DecisionGeneration}; repair_request_key={FormatProtocolLogValue(contract.Authority.RepairKey)}; dispatched_start_chunk_index={repairSend.FirstStartChunkIndex}; dispatched_end_chunk_exclusive={repairSend.LastEndChunkExclusive}; dispatched_chunk_count={chunkIndices.Count}; dispatch_authority_source=attached_installed_contract; decision_reason=dispatch_observed_contiguous_range");
        return true;
    }

    private bool TryResumePendingOutboundRegularV4FrontierRepairPressureInstallLocked(
        OutboundTransferContext context,
        out bool handled)
    {
        handled = false;
        if (context.PendingRegularV4FrontierRepairPressureInstallRetry is not { } executionIdentity ||
            executionIdentity.DataSessionGeneration != context.DataSessionGeneration ||
            context.CurrentRegularV4FrontierRepairContract is not
                { Lifecycle.IsSettled: false } stagedContract ||
            stagedContract.Authority.AuthorityId != executionIdentity.AuthorityId ||
            !FileTransferCoordinator.TryGetPendingRegularV4FrontierRepairPressureInstall(
                CreateCoordinatorStateLocked(context),
                executionIdentity.AuthorityId,
                out var pendingBinding,
                out _) ||
            pendingBinding.InstallGeneration != executionIdentity.InstallGeneration ||
            CreatePendingRegularV4FrontierRepairSend(context, stagedContract) is not { } repairSend)
        {
            return false;
        }

        if (stagedContract.Authority.PredecessorAuthorityId is null)
        {
            handled = true;
            if (!IsRegularV4FrontierRepairPressureInstallScopeCurrentLocked(
                    context,
                    stagedContract,
                    out _) ||
                !TryRetryRegularV4FrontierRepairPressureInstallLocked(context, stagedContract))
            {
                if (context.IsTerminal ||
                    !ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, stagedContract))
                {
                    context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
                }

                return false;
            }

            if (!TryCompleteOutboundInitialRegularV4FrontierRepairPressureInstallLocked(
                    context,
                    repairSend,
                    "pressure_install_retry"))
            {
                return false;
            }

            context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
            return true;
        }

        handled = true;
        var predecessorContract = FindRegularV4FrontierRepairContractForAuthority(
            stagedContract.Authority.Direction,
            stagedContract.Authority.SessionId,
            stagedContract.Authority.TransferId,
            stagedContract.Authority.PredecessorAuthorityId!.Value);
        if (predecessorContract is null ||
            !IsRegularV4FrontierRepairPressureInstallScopeCurrentLocked(
                context,
                stagedContract,
                out _))
        {
            context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
            return false;
        }

        repairSend = repairSend with
        {
            RegularV4RepairContract = predecessorContract,
        };
        var settlementObserved = false;
        var requeued = TryRequeueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(
            context,
            repairSend,
            out var requeuedChunkCount,
            out var successorAuthority,
            out settlementObserved);
        if (requeued && successorAuthority is { } installedSuccessorAuthority)
        {
            LogFileTransferRegularV4FrontierRepairSuccessorAuthorized(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                predecessorContract.Authority,
                installedSuccessorAuthority,
                repairSend.ChunkIndices.Count,
                requeuedChunkCount,
                "send_timeout_successor_pressure_install_retry_authorized");
            context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
        }
        else if (context.IsTerminal ||
                 !ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, stagedContract))
        {
            context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
        }

        return requeued;
    }

    private static PullV4QueuedRepairSend? CreatePendingRegularV4FrontierRepairSend(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract)
    {
        if (contract.ScheduledDispatch is not { } scheduled ||
            scheduled.ChunkIndices.IsDefaultOrEmpty)
        {
            return null;
        }

        var chunkIndices = scheduled.ChunkIndices.ToList();
        var deliveryReason = scheduled.RepairReplayKind switch
        {
            RepairReplayKind.PeerSilenceReplay => "regular_v4_peer_silence_safety_replay",
            RepairReplayKind.TransportRebindSafetyReplay => "file_tuna_v4_post_tuna_frontier_replay",
            _ => "first_send",
        };
        return new PullV4QueuedRepairSend(
            chunkIndices,
            RangeCount: 1,
            RequestedChunkCount: chunkIndices.Count,
            FirstStartChunkIndex: scheduled.StartChunkIndex,
            LastEndChunkExclusive: scheduled.EndChunkExclusive,
            RemoteNextExpectedChunkIndex: contract.Authority.FrontierChunkIndex,
            ChunksAcceptedForTransport: context.ChunksAcceptedForTransport,
            SkippedObsoleteCount: 0,
            SkippedFutureCount: Math.Max(0, contract.Authority.PendingRepairCount - chunkIndices.Count),
            SkippedOutOfBoundsCount: 0,
            RepairRequestKey: scheduled.RepairKey,
            ProtocolRepairRequestId: null,
            ProtocolPriority: null,
            ProtocolRecoveryMode: null,
            FrontierRepair: true,
            FrontierTailRepair: scheduled.StartChunkIndex == contract.Authority.FrontierChunkIndex,
            EmergencyCreditRepair: false,
            DeliveryMode: FileTransferV4RepairDeliveryMode.ControlBulkRedundant,
            DeliveryEscalationReason: deliveryReason,
            CreditExhaustedTimeMsAtDecision: -1,
            RuntimeOwner: contract.RepairDecision.RuntimeOwner,
            RegularV4RepairContract: contract,
            CoordinatorBackedRegularV4PeerSilenceReplay:
                scheduled.RepairReplayKind == RepairReplayKind.PeerSilenceReplay);
    }

    private static bool RetainPendingRegularV4FrontierRepairPressureInstallRetry(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract)
    {
        if (!FileTransferCoordinator.TryGetPendingRegularV4FrontierRepairPressureInstall(
                CreateCoordinatorStateLocked(context),
                contract.Authority.AuthorityId,
                out var pendingBinding,
                out _))
        {
            return false;
        }

        var identity = new RegularV4FrontierRepairPressureInstallExecutionIdentity(
            contract.Authority.AuthorityId,
            pendingBinding.InstallGeneration,
            context.DataSessionGeneration);
        if (context.PendingRegularV4FrontierRepairPressureInstallRetry is null)
        {
            context.PendingRegularV4FrontierRepairPressureInstallRetry = identity;
            return true;
        }

        return context.PendingRegularV4FrontierRepairPressureInstallRetry == identity;
    }

    private bool TryCompleteOutboundInitialRegularV4FrontierRepairPressureInstallLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend repairSend,
        string reason)
    {
        if (repairSend.RegularV4RepairContract is not { } contract ||
            !ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, contract) ||
            contract.Authority.PredecessorAuthorityId is not null ||
            !TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                contract.Authority.AuthorityId,
                out var installedBinding,
                out _,
                out _) ||
            installedBinding.State != RegularV4FrontierRepairPressureBindingState.Installed ||
            installedBinding.Authority != contract.Authority ||
            contract.Lifecycle.IsSettled ||
            repairSend.RuntimeOwner != context.CurrentRuntimeOwner ||
            repairSend.ChunkIndices.Count == 0 ||
            contract.ScheduledDispatch is not { } scheduledDispatch ||
            !IsRegularV4FrontierRepairScheduledDispatchMatch(
                scheduledDispatch,
                repairSend,
                ResolveRepairReplayKind(repairSend)) ||
            repairSend.ChunkIndices.Any(context.PullV4SenderPumpRepairQueuedChunkIndices.Contains))
        {
            return false;
        }

        if (ResolveRepairReplayKind(repairSend) == RepairReplayKind.PeerSilenceReplay)
        {
            var replayOrdinal = context.PullRegularNknV4PeerSilenceSafetyReplayCount + 1;
            var expectedRepairKey =
                $"regular_v4_peer_silence_safety_replay:{repairSend.RemoteNextExpectedChunkIndex}:{repairSend.FirstStartChunkIndex}:{repairSend.ChunkIndices.Count}:{replayOrdinal}";
            if (!string.Equals(repairSend.RepairRequestKey, expectedRepairKey, StringComparison.Ordinal) ||
                !string.Equals(contract.Authority.RepairKey, expectedRepairKey, StringComparison.Ordinal) ||
                contract.Authority.FrontierChunkIndex != repairSend.RemoteNextExpectedChunkIndex ||
                contract.Authority.PendingRepairCount != repairSend.ChunkIndices.Count)
            {
                return false;
            }

            LogFileTransferRegularV4FrontierRepairAuthorityGranted(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                contract.Authority,
                "regular_v4_peer_silence_safety_replay",
                "schedule",
                repairSend.RangeCount,
                repairSend.RequestedChunkCount,
                repairSend.ChunkIndices.Count,
                installedBinding.InstallGeneration,
                repairSend.FirstStartChunkIndex,
                repairSend.LastEndChunkExclusive,
                "attached_installed_contract");

            foreach (var chunkIndex in repairSend.ChunkIndices)
            {
                context.PullV4SenderPumpRepairQueuedChunkIndices.Add(chunkIndex);
            }

            context.PullRegularNknV4LastPeerSilenceSafetyReplayUtc = DateTimeOffset.UtcNow;
            context.PullRegularNknV4LastPeerSilenceSafetyReplayFrontierChunkIndex =
                repairSend.RemoteNextExpectedChunkIndex;
            context.PullRegularNknV4LastPeerSilenceSafetyReplayEndChunkIndex =
                repairSend.LastEndChunkExclusive;
            context.PullRegularNknV4PeerSilenceSafetyReplayCount = replayOrdinal;
            RetainOutboundRegularV4PeerSilenceReplayCursorLocked(
                context,
                contract,
                repairSend.RemoteNextExpectedChunkIndex,
                repairSend.FirstStartChunkIndex,
                repairSend.LastEndChunkExclusive,
                "repair_authorized_without_dispatch_proof");
            context.PullV4SenderPumpRepairQueue.Enqueue(repairSend);
            context.SparseSenderPumpLastWakeReason = "regular_v4_peer_silence_safety_replay";
            context.SignalSparseSenderPump();
            var lastPeerFrameUtc = context.PullV4LastPeerFrameReceivedUtc ?? context.PullV4LastGrantReceivedUtc;
            var feedbackSilence = lastPeerFrameUtc is null
                ? TimeSpan.MaxValue
                : DateTimeOffset.UtcNow - lastPeerFrameUtc.Value;
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_regular_v4_peer_silence_safety_replay_started; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; replay_ordinal={replayOrdinal}; remote_next_expected_chunk_index={repairSend.RemoteNextExpectedChunkIndex}; replay_start_chunk_index={repairSend.FirstStartChunkIndex}; replay_end_chunk_exclusive={repairSend.LastEndChunkExclusive}; requested_chunk_count={repairSend.RequestedChunkCount}; scheduled_chunk_count={repairSend.ChunkIndices.Count}; frontier_lag_chunks={Math.Max(0, repairSend.ChunksAcceptedForTransport - repairSend.RemoteNextExpectedChunkIndex)}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; replay_byte_cap={PullTransportRebindSafetyReplayMaxBytes}; replay_chunk_cap={PullTransportRebindSafetyReplayMaxChunks}; wrapped_to_frontier={(repairSend.PeerSilenceReplayWrappedToFrontier ? 1 : 0)}");
            return true;
        }

        if (!string.Equals(
                repairSend.DeliveryEscalationReason,
                "file_tuna_v4_post_tuna_frontier_replay",
                StringComparison.Ordinal))
        {
            return false;
        }

        var fileTunaReplayOrdinal = context.PullFileTunaV4PostTunaFrontierReplayCount + 1;
        var expectedFileTunaRepairKey =
            $"file_tuna_v4_post_tuna_frontier_replay:{context.PullFileTunaV4PostTunaReactivationGeneration}:{repairSend.RemoteNextExpectedChunkIndex}:{fileTunaReplayOrdinal}";
        if (!string.Equals(repairSend.RepairRequestKey, expectedFileTunaRepairKey, StringComparison.Ordinal) ||
            !string.Equals(contract.Authority.RepairKey, expectedFileTunaRepairKey, StringComparison.Ordinal) ||
            contract.Authority.FrontierChunkIndex != repairSend.RemoteNextExpectedChunkIndex ||
            contract.Authority.PendingRepairCount != repairSend.ChunkIndices.Count)
        {
            return false;
        }

        LogFileTransferRegularV4FrontierRepairAuthorityGranted(
            FileTransferDirection.Outbound,
            context.TransferId,
            context.SessionId,
            contract.Authority,
            "file_tuna_v4_post_tuna_frontier_replay",
            "schedule",
            repairSend.RangeCount,
            repairSend.RequestedChunkCount,
            repairSend.ChunkIndices.Count,
            installedBinding.InstallGeneration,
            repairSend.FirstStartChunkIndex,
            repairSend.LastEndChunkExclusive,
            "attached_installed_contract");

        foreach (var chunkIndex in repairSend.ChunkIndices)
        {
            context.PullV4SenderPumpRepairQueuedChunkIndices.Add(chunkIndex);
        }

        context.PullFileTunaV4PostTunaLastFrontierReplayUtc = DateTimeOffset.UtcNow;
        context.PullFileTunaV4PostTunaLastFrontierReplayChunkIndex = repairSend.RemoteNextExpectedChunkIndex;
        context.PullFileTunaV4PostTunaLastFrontierReplayEndChunkIndex = repairSend.LastEndChunkExclusive;
        context.PullFileTunaV4PostTunaFrontierReplayCount = fileTunaReplayOrdinal;
        context.PullV4SenderPumpRepairQueue.Enqueue(repairSend);
        context.SparseSenderPumpLastWakeReason = "file_tuna_v4_post_tuna_frontier_replay";
        context.SignalSparseSenderPump();
        var fileTunaLastPeerFrameUtc = context.PullV4LastPeerFrameReceivedUtc ?? context.PullV4LastGrantReceivedUtc;
        var fileTunaFeedbackSilence = fileTunaLastPeerFrameUtc is null
            ? TimeSpan.MaxValue
            : DateTimeOffset.UtcNow - fileTunaLastPeerFrameUtc.Value;
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_post_reactivation_frontier_replay_started; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; reactivation_generation={context.PullFileTunaV4PostTunaReactivationGeneration}; replay_ordinal={fileTunaReplayOrdinal}; remote_next_expected_chunk_index={repairSend.RemoteNextExpectedChunkIndex}; replay_start_chunk_index={repairSend.FirstStartChunkIndex}; replay_end_chunk_exclusive={repairSend.LastEndChunkExclusive}; requested_chunk_count={repairSend.RequestedChunkCount}; scheduled_chunk_count={repairSend.ChunkIndices.Count}; chunks_accepted_for_transport={repairSend.ChunksAcceptedForTransport}; remote_credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; feedback_silence_ms={(long)Math.Max(0, fileTunaFeedbackSilence.TotalMilliseconds)}; repair_request_key={repairSend.RepairRequestKey}");
        return true;
    }

    private bool MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(
        OutboundTransferContext context,
        string reason)
    {
        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal ||
            context.UserPaused ||
            context.PeerPaused ||
            !context.RouteRuntime.UsesRegularNknV4FastRuntime ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4 ||
            !context.PullSourceCanSeek ||
            context.RemoteNextExpectedChunkIndex >= context.ChunkCount)
        {
            return false;
        }

        var pendingInstallResumed = TryResumePendingOutboundRegularV4FrontierRepairPressureInstallLocked(
            context,
            out var pendingInstallHandled);
        if (pendingInstallHandled)
        {
            return pendingInstallResumed;
        }

        if (GetCurrentRegularV4FrontierRepairAuthority(context) is { } currentAuthority)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_peer_silence_safety_replay_skipped; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; skip_reason=current_authority_pending; repair_request_key={FormatProtocolLogValue(currentAuthority.RepairKey)}; decision_generation={currentAuthority.DecisionGeneration}");
            return false;
        }

        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var acceptedUntil = ResolveOutboundRepairAcceptedUntilExclusiveLocked(context);
        var frontierLagChunks = Math.Max(0, acceptedUntil - remoteFrontier);
        if (acceptedUntil <= remoteFrontier ||
            frontierLagChunks < PullV4RegularNknControlFeedbackPressureMinFrontierLagChunks)
        {
            return false;
        }

        var now = DateTimeOffset.UtcNow;
        var lastPeerFrameUtc = context.PullV4LastPeerFrameReceivedUtc ?? context.PullV4LastGrantReceivedUtc;
        var minSilence = TimeSpan.FromMilliseconds(PullControlChatterWindowMs * 2L);
        var feedbackSilence = lastPeerFrameUtc is null ? TimeSpan.MaxValue : now - lastPeerFrameUtc.Value;
        if (feedbackSilence < minSilence)
        {
            return false;
        }

        if (context.PullRegularNknV4PeerSilenceMissingDispatchFrontierChunkIndex == remoteFrontier &&
            context.PullRegularNknV4PeerSilenceMissingDispatchAcceptedUntilExclusive >= acceptedUntil)
        {
            var settledRepairKey = string.IsNullOrWhiteSpace(context.PullRegularNknV4PeerSilenceMissingDispatchRepairKey)
                ? $"regular_v4_peer_silence_safety_replay:{remoteFrontier}:settled"
                : context.PullRegularNknV4PeerSilenceMissingDispatchRepairKey!;
            var stallAgeMs = context.PullRegularNknV4PeerSilenceMissingDispatchUtc is { } settledUtc
                ? (long)Math.Max(0, (now - settledUtc).TotalMilliseconds)
                : 0;
            TryLogRegularV4PeerSilenceMissingDispatchSettledStalledLocked(
                context,
                settledRepairKey,
                "peer_silence_replay_missing_dispatch_settled",
                remoteFrontier,
                Math.Max(-1, remoteFrontier - 1),
                Math.Max(1, frontierLagChunks),
                Math.Max(1, context.PullRegularNknV4PeerSilenceSafetyReplayCount),
                stallAgeMs);
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_peer_silence_safety_replay_skipped; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; skip_reason=missing_dispatch_already_settled; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={acceptedUntil}; frontier_lag_chunks={frontierLagChunks}; previous_repair_request_key={FormatProtocolLogValue(settledRepairKey)}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}");
            return false;
        }

        if (context.PullRegularNknV4LastPeerSilenceSafetyReplayUtc is { } lastReplayUtc &&
            now - lastReplayUtc < PullTransportRebindSafetyReplayRearmCooldown)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_peer_silence_safety_replay_skipped; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; skip_reason=rearm_cooldown; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={acceptedUntil}; frontier_lag_chunks={frontierLagChunks}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; rearm_cooldown_ms={(long)PullTransportRebindSafetyReplayRearmCooldown.TotalMilliseconds}");
            return false;
        }

        var replayCursor = GetCurrentOutboundRegularV4PeerSilenceReplayCursorLocked(context, remoteFrontier);
        var replayStartChunkIndex = replayCursor?.DispatchProvenEndChunkIndex ?? remoteFrontier;
        var wrappedToFrontier = false;
        if (replayStartChunkIndex >= acceptedUntil)
        {
            wrappedToFrontier = replayCursor is not null &&
                                replayCursor.DispatchProvenEndChunkIndex > remoteFrontier;
            if (wrappedToFrontier)
            {
                ResetOutboundRegularV4PeerSilenceReplayCursorLocked(
                    context,
                    replayCursor!,
                    remoteFrontier,
                    "dispatch_proven_sweep_wrapped_to_frontier");
                replayCursor = null;
            }

            replayStartChunkIndex = remoteFrontier;
        }

        if (replayCursor is { } retainedCursor &&
            context.PullRegularNknV4LastPeerSilenceSafetyReplayFrontierChunkIndex == remoteFrontier &&
            context.PullRegularNknV4LastPeerSilenceSafetyReplayEndChunkIndex > retainedCursor.DispatchProvenEndChunkIndex &&
            context.PullRegularNknV4LastPeerSilenceSafetyReplayEndChunkIndex < acceptedUntil)
        {
            var previousContract = context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract;
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_regular_v4_peer_silence_replay_range_rotation_rejected; {FormatOutboundRegularV4PeerSilenceReplayCursorTuple(retainedCursor)}; authority_id={FormatProtocolLogValue(previousContract?.Authority.AuthorityId.ToString() ?? "(none)")}; predecessor_authority_id={FormatProtocolLogValue(previousContract?.Authority.PredecessorAuthorityId?.ToString() ?? "(none)")}; repair_generation={previousContract?.Authority.DecisionGeneration ?? 0}; repair_request_key={FormatProtocolLogValue(previousContract?.Authority.RepairKey ?? "(none)")}; attempted_start_chunk_index={context.PullRegularNknV4LastPeerSilenceSafetyReplayEndChunkIndex}; retained_start_chunk_index={replayStartChunkIndex}; chunks_accepted_for_transport={acceptedUntil}; dispatch_observed={(previousContract?.Lifecycle.DispatchObserved == true ? 1 : 0)}; settlement_outcome={FormatProtocolLogValue(previousContract?.Lifecycle.SettlementOutcome?.ToString() ?? "(none)")}; decision_reason=scheduled_end_not_dispatch_proven");
        }

        var maxChunksByBytes = Math.Max(1, PullTransportRebindSafetyReplayMaxBytes / Math.Max(1, context.ChunkSizeBytes));
        var replayChunkCount = Math.Min(
            acceptedUntil - replayStartChunkIndex,
            Math.Min(PullTransportRebindSafetyReplayMaxChunks, maxChunksByBytes));
        if (replayChunkCount <= 0)
        {
            return false;
        }

        var replayEndExclusive = replayStartChunkIndex + replayChunkCount;
        var chunkIndices = new List<int>(replayChunkCount);
        for (var chunkIndex = replayStartChunkIndex; chunkIndex < replayEndExclusive; chunkIndex++)
        {
            if (!context.PullV4SenderPumpRepairQueuedChunkIndices.Contains(chunkIndex))
            {
                chunkIndices.Add(chunkIndex);
            }
        }
        if (chunkIndices.Count == 0)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_peer_silence_safety_replay_skipped; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; skip_reason=chunks_already_queued; remote_next_expected_chunk_index={remoteFrontier}; replay_start_chunk_index={replayStartChunkIndex}; replay_end_chunk_exclusive={replayEndExclusive}; frontier_lag_chunks={frontierLagChunks}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}");
            return false;
        }

        if (!TryAuthorizeRepairReplayLocked(
                context,
                context.CurrentRuntimeOwner,
                RepairReplayKind.PeerSilenceReplay,
                "regular_v4_peer_silence_safety_replay",
                reason,
                context.CurrentTransferLeg,
                context.CurrentTransferLeg?.TransportEpochId,
                context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                null,
                out var replayDecision) ||
            replayDecision is not { } peerSilenceReplayDecision)
        {
            return false;
        }

        var replayOrdinal = context.PullRegularNknV4PeerSilenceSafetyReplayCount + 1;
        var repairKey = $"regular_v4_peer_silence_safety_replay:{remoteFrontier}:{replayStartChunkIndex}:{chunkIndices.Count}:{replayOrdinal}";
        var regularContract = CreateRegularV4FrontierRepairContract(
            context,
            peerSilenceReplayDecision,
            repairKey,
            remoteFrontier,
            Math.Max(-1, remoteFrontier - 1),
            chunkIndices.Count,
            peerSilenceReplayDecision.Reason,
            "regular_v4_peer_silence_safety_replay",
            out var regularContractRejectionReason);
        if (regularContract is null)
        {
            LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                context.CurrentTransferLeg,
                repairKey,
                "regular_v4_peer_silence_safety_replay",
                "schedule",
                regularContractRejectionReason,
                remoteFrontier,
                Math.Max(-1, remoteFrontier - 1),
                chunkIndices.Count);
            return false;
        }

        context.CurrentRegularV4FrontierRepairContract = regularContract;
        var queuedRepair = new PullV4QueuedRepairSend(
            chunkIndices,
            RangeCount: 1,
            RequestedChunkCount: replayChunkCount,
            FirstStartChunkIndex: replayStartChunkIndex,
            LastEndChunkExclusive: replayEndExclusive,
            RemoteNextExpectedChunkIndex: remoteFrontier,
            ChunksAcceptedForTransport: acceptedUntil,
            SkippedObsoleteCount: 0,
            SkippedFutureCount: replayChunkCount - chunkIndices.Count,
            SkippedOutOfBoundsCount: 0,
            RepairRequestKey: repairKey,
            ProtocolRepairRequestId: null,
            ProtocolPriority: null,
            ProtocolRecoveryMode: null,
            FrontierRepair: replayStartChunkIndex == remoteFrontier,
            FrontierTailRepair: replayStartChunkIndex == remoteFrontier,
            EmergencyCreditRepair: false,
            DeliveryMode: FileTransferV4RepairDeliveryMode.ControlBulkRedundant,
            DeliveryEscalationReason: "regular_v4_peer_silence_safety_replay",
            CreditExhaustedTimeMsAtDecision: -1,
            RuntimeOwner: context.CurrentRuntimeOwner,
            RegularV4RepairContract: regularContract,
            PeerSilenceReplayWrappedToFrontier: wrappedToFrontier,
            CoordinatorBackedRegularV4PeerSilenceReplay: true);
        if (!TryBindRegularV4FrontierRepairScheduledDispatch(
                regularContract,
                queuedRepair,
                RepairReplayKind.PeerSilenceReplay,
                out _))
        {
            return false;
        }

        if (!TryInstallRegularV4FrontierRepairPressureLocked(
                context,
                regularContract,
                predecessorContract: null,
                frontierLagChunks,
                chunkIndices.Count,
                "regular_v4_peer_silence_safety_replay",
                "outbound_peer_silence_initial"))
        {
            _ = RetainPendingRegularV4FrontierRepairPressureInstallRetry(
                context,
                regularContract);
            return false;
        }

        return TryCompleteOutboundInitialRegularV4FrontierRepairPressureInstallLocked(
            context,
            queuedRepair,
            reason);
    }

    private bool MaybeQueueOutboundFileTunaV4PostTunaFrontierReplayLocked(
        OutboundTransferContext context,
        string reason)
    {
        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal ||
            context.UserPaused ||
            context.PeerPaused ||
            !context.RouteRuntime.UsesFileTunaV4Runtime ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4 ||
            context.PullFileTunaV4PostTunaReactivationGeneration <= 0 ||
            !context.PullSourceCanSeek ||
            context.RemoteNextExpectedChunkIndex >= context.ChunkCount)
        {
            return false;
        }

        var pendingInstallResumed = TryResumePendingOutboundRegularV4FrontierRepairPressureInstallLocked(
            context,
            out var pendingInstallHandled);
        if (pendingInstallHandled)
        {
            return pendingInstallResumed;
        }

        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var acceptedUntil = ResolveOutboundRepairAcceptedUntilExclusiveLocked(context);
        if (acceptedUntil <= remoteFrontier)
        {
            return false;
        }

        if (HasOutboundV4RepairWorkInProgressLocked(context))
        {
            return false;
        }

        var now = DateTimeOffset.UtcNow;
        var lastPeerFrameUtc = context.PullV4LastPeerFrameReceivedUtc ?? context.PullV4LastGrantReceivedUtc;
        var minSilence = TimeSpan.FromMilliseconds(PullControlChatterWindowMs * 2L);
        var feedbackSilence = lastPeerFrameUtc is null ? TimeSpan.MaxValue : now - lastPeerFrameUtc.Value;
        if (feedbackSilence < minSilence)
        {
            return false;
        }

        if (context.PullFileTunaV4PostTunaLastFrontierReplayUtc is { } lastReplayUtc &&
            now - lastReplayUtc < PullTransportRebindSafetyReplayRearmCooldown)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_post_reactivation_frontier_replay_skipped; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; skip_reason=rearm_cooldown; reactivation_generation={context.PullFileTunaV4PostTunaReactivationGeneration}; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={acceptedUntil}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}; rearm_cooldown_ms={(long)PullTransportRebindSafetyReplayRearmCooldown.TotalMilliseconds}");
            return false;
        }

        var replayChunkCount = Math.Min(
            V4PostFallbackEmergencyFrontierRepairChunks,
            Math.Max(0, acceptedUntil - remoteFrontier));
        if (replayChunkCount <= 0)
        {
            return false;
        }

        var replayEndExclusive = remoteFrontier + replayChunkCount;
        var chunkIndices = new List<int>(replayChunkCount);
        for (var chunkIndex = remoteFrontier; chunkIndex < replayEndExclusive; chunkIndex++)
        {
            if (!context.PullV4SenderPumpRepairQueuedChunkIndices.Contains(chunkIndex))
            {
                chunkIndices.Add(chunkIndex);
            }
        }

        if (chunkIndices.Count == 0)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_post_reactivation_frontier_replay_skipped; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; skip_reason=chunks_already_queued; reactivation_generation={context.PullFileTunaV4PostTunaReactivationGeneration}; remote_next_expected_chunk_index={remoteFrontier}; replay_start_chunk_index={remoteFrontier}; replay_end_chunk_exclusive={replayEndExclusive}; feedback_silence_ms={(long)Math.Max(0, feedbackSilence.TotalMilliseconds)}");
            return false;
        }

        if (!TryAuthorizeRepairReplayLocked(
                context,
                context.CurrentRuntimeOwner,
                RepairReplayKind.TransportRebindSafetyReplay,
                "file_tuna_v4_post_tuna_frontier_replay",
                reason,
                context.CurrentTransferLeg,
                context.CurrentTransferLeg?.TransportEpochId,
                context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                null,
                out var replayDecision) ||
            replayDecision is not { } fileTunaReplayDecision)
        {
            return false;
        }

        var replayOrdinal = context.PullFileTunaV4PostTunaFrontierReplayCount + 1;
        var repairKey = $"file_tuna_v4_post_tuna_frontier_replay:{context.PullFileTunaV4PostTunaReactivationGeneration}:{remoteFrontier}:{replayOrdinal}";
        var fileTunaContract = CreateRegularV4FrontierRepairContract(
            context,
            fileTunaReplayDecision,
            repairKey,
            remoteFrontier,
            Math.Max(-1, remoteFrontier - 1),
            chunkIndices.Count,
            fileTunaReplayDecision.Reason,
            "file_tuna_v4_post_tuna_frontier_replay",
            out var fileTunaContractRejectionReason);
        if (fileTunaContract is null)
        {
            LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                context.CurrentTransferLeg,
                repairKey,
                "file_tuna_v4_post_tuna_frontier_replay",
                "schedule",
                fileTunaContractRejectionReason,
                remoteFrontier,
                Math.Max(-1, remoteFrontier - 1),
                chunkIndices.Count);
            return false;
        }

        context.CurrentRegularV4FrontierRepairContract = fileTunaContract;
        var queuedRepair = new PullV4QueuedRepairSend(
            chunkIndices,
            RangeCount: 1,
            RequestedChunkCount: replayChunkCount,
            FirstStartChunkIndex: remoteFrontier,
            LastEndChunkExclusive: replayEndExclusive,
            RemoteNextExpectedChunkIndex: remoteFrontier,
            ChunksAcceptedForTransport: acceptedUntil,
            SkippedObsoleteCount: 0,
            SkippedFutureCount: replayChunkCount - chunkIndices.Count,
            SkippedOutOfBoundsCount: 0,
            RepairRequestKey: repairKey,
            ProtocolRepairRequestId: null,
            ProtocolPriority: null,
            ProtocolRecoveryMode: null,
            FrontierRepair: true,
            FrontierTailRepair: true,
            EmergencyCreditRepair: false,
            DeliveryMode: FileTransferV4RepairDeliveryMode.ControlBulkRedundant,
            DeliveryEscalationReason: "file_tuna_v4_post_tuna_frontier_replay",
            CreditExhaustedTimeMsAtDecision: context.V4SenderCreditExhaustedSinceUtc is null
                ? 0
                : (long)Math.Max(0, (now - context.V4SenderCreditExhaustedSinceUtc.Value).TotalMilliseconds),
            RuntimeOwner: context.CurrentRuntimeOwner,
            RegularV4RepairContract: fileTunaContract);
        if (!TryBindRegularV4FrontierRepairScheduledDispatch(
                fileTunaContract,
                queuedRepair,
                RepairReplayKind.TransportRebindSafetyReplay,
                out _))
        {
            return false;
        }

        if (!TryInstallRegularV4FrontierRepairPressureLocked(
                context,
                fileTunaContract,
                predecessorContract: null,
                Math.Max(0, acceptedUntil - remoteFrontier),
                chunkIndices.Count,
                "file_tuna_v4_post_tuna_frontier_replay",
                "outbound_file_tuna_replay_initial"))
        {
            _ = RetainPendingRegularV4FrontierRepairPressureInstallRetry(
                context,
                fileTunaContract);
            return false;
        }

        return TryCompleteOutboundInitialRegularV4FrontierRepairPressureInstallLocked(
            context,
            queuedRepair,
            reason);
    }

    private bool TryRestoreOutboundV4RepairHeldForReceiveRecoveryLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend repairSend,
        FileTransferReceiveRecoveryOperation heldOperation,
        string stage,
        string reason)
    {
        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal ||
            repairSend.ChunkIndices.Count == 0)
        {
            return false;
        }

        var recovery = context.CoordinatorPersistentState
            .FileTransferReceiveRecovery;
        var retainedOperation =
            recovery.CurrentOperation is { } current &&
            current.Authority == heldOperation.Authority
                ? current
                : recovery.LastTerminalOperation is { } terminal &&
                  terminal.Authority == heldOperation.Authority
                    ? terminal
                    : (FileTransferReceiveRecoveryOperation?)null;
        if (retainedOperation is null ||
            repairSend.RuntimeOwner != context.CurrentRuntimeOwner ||
            repairSend.RegularV4RepairContract is { } regularContract &&
            !TryValidateOutboundRegularV4FrontierRepairDispatchLocked(
                context,
                repairSend,
                ResolveRepairReplayKind(repairSend),
                regularContract,
                out _))
        {
            return false;
        }

        var exactAlreadyQueued = context.PullV4SenderPumpRepairQueue.Any(
            queued =>
                string.Equals(
                    queued.RepairRequestKey,
                    repairSend.RepairRequestKey,
                    StringComparison.Ordinal) &&
                ReferenceEquals(
                    queued.RegularV4RepairContract,
                    repairSend.RegularV4RepairContract) &&
                queued.ChunkIndices.SequenceEqual(repairSend.ChunkIndices));
        if (!exactAlreadyQueued)
        {
            if (repairSend.ChunkIndices.Any(
                    context.PullV4SenderPumpRepairQueuedChunkIndices.Contains))
            {
                return false;
            }

            foreach (var chunkIndex in repairSend.ChunkIndices)
            {
                context.PullV4SenderPumpRepairQueuedChunkIndices.Add(chunkIndex);
            }

            context.PullV4SenderPumpRepairQueue.Enqueue(repairSend);
        }

        if (context.PullV4SenderPumpRepairRequests.TryGetValue(
                repairSend.RepairRequestKey,
                out var repairState))
        {
            repairState.InFlight = false;
            repairState.Queued = true;
            repairState.QueuedUtc ??= DateTimeOffset.UtcNow;
        }

        if (TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                context,
                out var currentHold,
                out var currentHoldReason) &&
            currentHold.Authority == heldOperation.Authority)
        {
            MarkOutboundPayloadSubmissionHeldForReceiveRecoveryLocked(
                context,
                currentHold,
                stage,
                currentHoldReason,
                repairSend.RegularV4RepairContract,
                repairSend.RepairRequestKey);
        }
        return true;
    }

    private bool TryRequeueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend repairSend,
        out int requeuedChunkCount,
        out FileTransferRegularV4FrontierRepairAuthority? successorAuthority,
        out bool settlementObserved)
    {
        requeuedChunkCount = 0;
        successorAuthority = null;
        settlementObserved = false;
        if (context.IsTerminal ||
            context.UserPaused ||
            context.PeerPaused)
        {
            return false;
        }

        if (ResolveRepairReplayKind(repairSend) != RepairReplayKind.PeerSilenceReplay)
        {
            return false;
        }

        if (repairSend.RuntimeOwner is not { } queuedOwner)
        {
            RejectMissingRuntimeOwnerActionLocked(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                context.CurrentRuntimeOwner,
                "regular_v4_peer_silence_safety_replay",
                "requeue_after_send_timeout");
            return false;
        }

        if (!FileTransferCoordinator.IsRuntimeOwnerCurrent(
                CreateCoordinatorStateLocked(context),
                queuedOwner,
                out var ownerRejectionReason))
        {
            RejectStaleRuntimeOwnerUpdateLocked(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                context.CurrentRuntimeOwner,
                queuedOwner,
                "regular_v4_peer_silence_safety_replay",
                "requeue_after_send_timeout",
                ownerRejectionReason);
            return false;
        }

        if (!context.RouteRuntime.UsesRegularNknV4FastRuntime ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4)
        {
            return false;
        }

        var revalidatedRepair = RevalidateQueuedV4RepairSendLocked(context, repairSend);
        if (revalidatedRepair is null)
        {
            return false;
        }

        var requeued = new List<int>(repairSend.ChunkIndices.Count);
        foreach (var chunkIndex in revalidatedRepair.ChunkIndices)
        {
            if (!context.PullV4SenderPumpRepairQueuedChunkIndices.Contains(chunkIndex))
            {
                requeued.Add(chunkIndex);
            }
        }

        if (requeued.Count == 0)
        {
            return false;
        }

        var firstStartChunkIndex = requeued.Min();
        var lastEndChunkExclusive = requeued.Max() + 1;
        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var acceptedUntil = ResolveOutboundRepairAcceptedUntilExclusiveLocked(context);
        if (context.PullRegularNknV4PeerSilenceMissingDispatchFrontierChunkIndex == remoteFrontier &&
            context.PullRegularNknV4PeerSilenceMissingDispatchAcceptedUntilExclusive >= acceptedUntil)
        {
            var settledRepairKey = string.IsNullOrWhiteSpace(context.PullRegularNknV4PeerSilenceMissingDispatchRepairKey)
                ? repairSend.RepairRequestKey
                : context.PullRegularNknV4PeerSilenceMissingDispatchRepairKey!;
            var stallAgeMs = context.PullRegularNknV4PeerSilenceMissingDispatchUtc is { } settledUtc
                ? (long)Math.Max(0, (DateTimeOffset.UtcNow - settledUtc).TotalMilliseconds)
                : 0;
            settlementObserved = TryLogRegularV4PeerSilenceMissingDispatchSettledStalledLocked(
                context,
                settledRepairKey,
                "peer_silence_requeue_missing_dispatch_settled",
                remoteFrontier,
                Math.Max(-1, remoteFrontier - 1),
                Math.Max(1, requeued.Count),
                Math.Max(1, context.PullRegularNknV4PeerSilenceSafetyReplayCount),
                stallAgeMs);
            return false;
        }

        var replayOrdinal = context.PullRegularNknV4PeerSilenceSafetyReplayCount + 1;
        var repairKey = $"regular_v4_peer_silence_safety_replay:{remoteFrontier}:{firstStartChunkIndex}:{requeued.Count}:{replayOrdinal}";
        if (repairSend.RegularV4RepairContract is not { } predecessorContract)
        {
            return false;
        }

        var currentContract = context.CurrentRegularV4FrontierRepairContract;
        if (currentContract is null || currentContract.Lifecycle.IsSettled)
        {
            settlementObserved = true;
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_frontier_repair_successor_pressure_install_retry_discarded; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(currentContract?.Authority.AuthorityId.ToString() ?? "(none)")}; predecessor_authority_id={FormatProtocolLogValue(predecessorContract.Authority.AuthorityId.ToString())}; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; retained_repair_request_key={FormatProtocolLogValue(currentContract?.Authority.RepairKey ?? "(none)")}; current_repair_request_key={FormatProtocolLogValue(repairKey)}; decision_reason=current_predecessor_not_active");
            return false;
        }

        RegularV4FrontierRepairContract? regularContract = null;
        if (!ReferenceEquals(currentContract, predecessorContract))
        {
            var stagedSuccessor = currentContract;
            if (stagedSuccessor.Authority.PredecessorAuthorityId !=
                    predecessorContract.Authority.AuthorityId ||
                !string.Equals(stagedSuccessor.Authority.RepairKey, repairKey, StringComparison.Ordinal) ||
                stagedSuccessor.Authority.FrontierChunkIndex != remoteFrontier ||
                stagedSuccessor.Authority.DurableReceivedHighestChunkIndex != Math.Max(-1, remoteFrontier - 1) ||
                stagedSuccessor.Authority.PendingRepairCount != requeued.Count)
            {
                settlementObserved = true;
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_regular_v4_frontier_repair_successor_pressure_install_retry_discarded; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(stagedSuccessor.Authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(predecessorContract.Authority.AuthorityId.ToString())}; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; retained_repair_request_key={FormatProtocolLogValue(stagedSuccessor.Authority.RepairKey)}; current_repair_request_key={FormatProtocolLogValue(repairKey)}; retained_frontier_chunk_index={stagedSuccessor.Authority.FrontierChunkIndex}; current_frontier_chunk_index={remoteFrontier}; retained_pending_repair_count={stagedSuccessor.Authority.PendingRepairCount}; current_pending_repair_count={requeued.Count}; decision_reason=retained_successor_install_boundary_mismatch");
                return false;
            }

            regularContract = stagedSuccessor;
        }
        else
        {
            if (!TryAuthorizeRepairReplayLocked(
                    context,
                    repairSend.RuntimeOwner,
                    RepairReplayKind.PeerSilenceReplay,
                    "regular_v4_peer_silence_safety_replay",
                    "requeue_after_send_timeout",
                    context.CurrentTransferLeg,
                    context.CurrentTransferLeg?.TransportEpochId,
                    context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                    null,
                    out var replayDecision,
                    predecessorAuthorityId: predecessorContract.Authority.AuthorityId) ||
                replayDecision is not { } peerSilenceReplayDecision)
            {
                return false;
            }

            regularContract = CreateRegularV4FrontierRepairContract(
                context,
                peerSilenceReplayDecision,
                repairKey,
                remoteFrontier,
                Math.Max(-1, remoteFrontier - 1),
                requeued.Count,
                peerSilenceReplayDecision.Reason,
                "regular_v4_frontier_repair_successor_authorized",
                out var regularContractRejectionReason);
            if (regularContract is null)
            {
                LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    context.CurrentTransferLeg,
                    repairKey,
                    "regular_v4_peer_silence_safety_replay",
                    "requeue",
                    regularContractRejectionReason,
                    remoteFrontier,
                    Math.Max(-1, remoteFrontier - 1),
                    requeued.Count);
                return false;
            }

            regularContract.PredecessorLifecycleContract = predecessorContract;
            context.CurrentRegularV4FrontierRepairContract = regularContract;
        }

        var regularAuthority = regularContract.Authority;
        var successorRepair = revalidatedRepair with
        {
            ChunkIndices = requeued,
            RequestedChunkCount = requeued.Count,
            FirstStartChunkIndex = firstStartChunkIndex,
            LastEndChunkExclusive = lastEndChunkExclusive,
            RemoteNextExpectedChunkIndex = remoteFrontier,
            ChunksAcceptedForTransport = acceptedUntil,
            RepairRequestKey = repairKey,
            FrontierTailRepair = firstStartChunkIndex == remoteFrontier,
            RegularV4RepairContract = regularContract,
        };
        if (!TryBindRegularV4FrontierRepairScheduledDispatch(
                regularContract,
                successorRepair,
                RepairReplayKind.PeerSilenceReplay,
                out _))
        {
            settlementObserved = true;
            return false;
        }

        if (!TryInstallRegularV4FrontierRepairPressureLocked(
                context,
                regularContract,
                predecessorContract,
                Math.Max(0, regularAuthority.DurableReceivedHighestChunkIndex - regularAuthority.FrontierChunkIndex + 1),
                requeued.Count,
                "regular_v4_frontier_repair_successor_authorized",
                "outbound_peer_silence_timeout_successor"))
        {
            _ = RetainPendingRegularV4FrontierRepairPressureInstallRetry(
                context,
                regularContract);
            settlementObserved = true;
            return false;
        }

        if (!TrySettleRegularV4FrontierRepairContract(
            predecessorContract,
            FileTransferRegularV4FrontierRepairSettlementOutcome.Superseded,
            repairSend.RequestedChunkCount,
            "send_timeout_successor_authorized",
            regularAuthority.AuthorityId))
        {
            settlementObserved = true;
            return false;
        }

        LogFileTransferRegularV4FrontierRepairAuthorityGranted(
            FileTransferDirection.Outbound,
            context.TransferId,
            context.SessionId,
            regularAuthority,
            "regular_v4_peer_silence_safety_replay",
            "requeue",
            rangeCount: 1,
            requestedChunkCount: requeued.Count,
            scheduledChunkCount: requeued.Count,
            installGeneration: GetRegularV4FrontierRepairPressureInstallGeneration(
                CreateCoordinatorStateLocked(context),
                regularContract),
            scheduledStartChunkIndex: requeued[0],
            scheduledEndChunkExclusive: requeued[^1] + 1,
            dispatchAuthoritySource: "attached_installed_contract");

        foreach (var chunkIndex in requeued)
        {
            context.PullV4SenderPumpRepairQueuedChunkIndices.Add(chunkIndex);
        }

        context.PullRegularNknV4PeerSilenceSafetyReplayCount = replayOrdinal;
        context.PullRegularNknV4PeerSilenceMissingDispatchFrontierChunkIndex = remoteFrontier;
        context.PullRegularNknV4PeerSilenceMissingDispatchAcceptedUntilExclusive = acceptedUntil;
        context.PullRegularNknV4PeerSilenceMissingDispatchRepairKey = repairKey;
        context.PullRegularNknV4PeerSilenceMissingDispatchUtc = DateTimeOffset.UtcNow;
        context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract = regularContract;
        context.PullRegularNknV4PeerSilenceMissingDispatchSettledStalledRepairKey = null;
        context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
        RetainOutboundRegularV4PeerSilenceReplayCursorLocked(
            context,
            regularContract,
            remoteFrontier,
            firstStartChunkIndex,
            lastEndChunkExclusive,
            "send_timeout_successor_authorized_without_dispatch_proof");
        successorAuthority = regularAuthority;
        context.PullV4SenderPumpRepairQueue.Enqueue(successorRepair);
        context.SparseSenderPumpLastWakeReason = "regular_v4_peer_silence_safety_replay_retry";
        context.SignalSparseSenderPump();
        requeuedChunkCount = requeued.Count;
        return true;
    }

    private bool TryLogRegularV4PeerSilenceMissingDispatchSettledStalledLocked(
        OutboundTransferContext context,
        string repairRequestKey,
        string reason,
        int frontierChunkIndex,
        int durableReceivedHighestChunkIndex,
        int requestedChunkCount,
        int attemptCount,
        long frontierStallAgeMs)
    {
        if (string.Equals(
                context.PullRegularNknV4PeerSilenceMissingDispatchSettledStalledRepairKey,
                repairRequestKey,
                StringComparison.Ordinal))
        {
            return false;
        }

        context.PullRegularNknV4PeerSilenceMissingDispatchSettledStalledRepairKey = repairRequestKey;
        LogFileTransferRegularV4FrontierRepairStalled(
            FileTransferDirection.Outbound,
            context.TransferId,
            context.SessionId,
            context.CurrentTransferLeg,
            repairRequestKey,
            reason,
            frontierChunkIndex,
            durableReceivedHighestChunkIndex,
            requestedChunkCount,
            attemptCount,
            frontierStallAgeMs);

        var leg = context.CurrentTransferLeg;
        var routeToken = leg?.RouteSelection.TelemetryToken ?? FileTransferRouteResolver.RegularNknV4FastToken;
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_regular_v4_frontier_repair_settled_stalled; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; repair_request_key={FormatProtocolLogValue(repairRequestKey)}; route={FormatProtocolLogValue(routeToken)}; protocol_version={leg?.ProtocolVersion ?? FileTransferProtocol.ProtocolVersionV4}; live_route_epoch={leg?.LiveRouteEpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.TerminalGeneration}; leg_generation={leg?.Generation ?? 0}; transport_epoch={leg?.TransportEpochId ?? 0}; bridge_recovery_generation={leg?.BridgeRecoveryGeneration ?? 0}; route_publication_generation={context.LastRoutePublicationGeneration}; target_transport={FormatFileTransferTransportKind(ResolveV4FrontierRepairTargetTransport(routeToken))}; reason={FormatProtocolLogValue(reason)}; frontier_chunk_index={frontierChunkIndex}; durable_received_highest_chunk_index={durableReceivedHighestChunkIndex}; requested_chunk_count={requestedChunkCount}; attempt_count={attemptCount}; frontier_stall_age_ms={frontierStallAgeMs}; settlement=stalled; decision_reason=regular_v4_frontier_repair_missing_dispatch_settled");
        var settlementContract = context.PullRegularNknV4PeerSilenceMissingDispatchSettlementContract;
        if (settlementContract is null ||
            !string.Equals(settlementContract.Authority.RepairKey, repairRequestKey, StringComparison.Ordinal))
        {
            LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                context.CurrentTransferLeg,
                repairRequestKey,
                "regular_v4_peer_silence_safety_replay",
                "settlement",
                "repair_settlement_authority_missing",
                frontierChunkIndex,
                durableReceivedHighestChunkIndex,
                requestedChunkCount);
            return true;
        }

        TrySettleRegularV4FrontierRepairContract(
            settlementContract,
            FileTransferRegularV4FrontierRepairSettlementOutcome.SettledStalled,
            requestedChunkCount,
            "regular_v4_frontier_repair_missing_dispatch_settled");
        return true;
    }

    private void ApplyOutboundV4State(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state)
        => ApplyOutboundV4StateAsync(context, state).GetAwaiter().GetResult();

    private async Task<RetainedPeerProofApplicationResult> ApplyOutboundV4StateAsync(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        OutboundSparsePumpInstall? receiveInstall = null,
        RuntimeOwnerToken? receiveRuntimeOwner = null,
        IFileTransferDataSession? receiveDataSession = null,
        long receiveDataSessionGeneration = 0)
    {
        var stateWireFingerprint =
            CreateFileTransferV4StateWireFingerprint(state);
        SessionFileTransferSnapshot? snapshot = null;
        var applicationResult = new RetainedPeerProofApplicationResult(
            RetainedPeerProofApplicationStatus.Held,
            "state_application_pending");
        var shouldEnqueueRepairs = false;
        var shouldSignalSenderPump = false;
        var suppressFallbackTailRepairEnqueue = false;
        FileTransferFrontierRequestFrameV6? fallbackCheckpointReissueRequest = null;
        IFileTransferDataSession? fallbackCheckpointReissueDataSession = null;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                (receiveDataSession is not null &&
                 !IsOutboundSparseReceiveResultCurrentLocked(
                     context,
                     receiveInstall,
                     receiveRuntimeOwner,
                     receiveDataSession,
                     receiveDataSessionGeneration,
                     out _)))
            {
                return new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Rejected,
                    "state_receive_scope_stale");
            }

            var currentPostTunaFallbackReceiverState = false;
            var currentPostTunaFallbackCheckpointProof = false;
            if (state is FileTransferReceiverStateFrameV6 receiverState)
            {
                var currentPostTunaFallbackCheckpointRequestId = context.CurrentTransferLeg?.CheckpointRequestId;
                currentPostTunaFallbackCheckpointProof =
                    context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
                    IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg) &&
                    !string.IsNullOrWhiteSpace(currentPostTunaFallbackCheckpointRequestId) &&
                    string.Equals(receiverState.RepairRequestId, currentPostTunaFallbackCheckpointRequestId, StringComparison.Ordinal) &&
                    IsPostTunaFallbackCheckpointProofReceiverState(receiverState);
                if (!TryAcceptOutboundFallbackCheckpointAndPrepareReissueLocked(
                        context,
                        receiverState,
                        "receiver_state_sparse_runtime",
                        out var checkpointReissueRequest))
                {
                    return new RetainedPeerProofApplicationResult(
                        RetainedPeerProofApplicationStatus.Rejected,
                        "fallback_checkpoint_not_accepted");
                }

                TryResumeOutboundRuntimeUnlockAfterFallbackSurvivalProofLocked(
                    context,
                    "fallback_checkpoint_accepted");

                if (checkpointReissueRequest is not null)
                {
                    fallbackCheckpointReissueRequest = checkpointReissueRequest;
                    fallbackCheckpointReissueDataSession = context.DataSession;
                }

                currentPostTunaFallbackReceiverState =
                    context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
                    IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg);
                var currentPostTunaFallbackProgressProof = false;
                if (currentPostTunaFallbackReceiverState)
                {
                    var currentLeg = context.CurrentTransferLeg;
                    var currentTransportEpoch = currentLeg?.TransportEpochId ?? 0;
                    var normalizedFallbackCommitted = Math.Clamp(
                        receiverState.ContiguousCommittedChunkIndex,
                        0,
                        context.ChunkCount);
                    var fallbackTransportMatches =
                        receiverState.TransportEpoch <= 0 ||
                        currentTransportEpoch <= 0 ||
                        receiverState.TransportEpoch == currentTransportEpoch;
                    currentPostTunaFallbackProgressProof =
                        fallbackTransportMatches &&
                        normalizedFallbackCommitted >= context.RemoteNextExpectedChunkIndex &&
                        receiverState.DurableReceivedHighestChunkIndex >= Math.Max(-1, normalizedFallbackCommitted - 1);
                }

                if (currentPostTunaFallbackReceiverState &&
                    (currentPostTunaFallbackCheckpointProof || currentPostTunaFallbackProgressProof) &&
                    state.Epoch < context.V4LastStateEpoch)
                {
                    var previousEpochFloor = context.V4LastStateEpoch;
                    context.V4LastStateEpoch = Math.Max(-1, state.Epoch - 1);
                    var resetReason = currentPostTunaFallbackCheckpointProof
                        ? "current_fallback_checkpoint"
                        : "current_fallback_receiver_state";
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_fallback_state_epoch_floor_reset; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; previous_epoch={previousEpochFloor}; state_epoch={state.Epoch}; new_previous_epoch={context.V4LastStateEpoch}; transport_epoch={receiverState.TransportEpoch}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; reason={resetReason}");
                }
            }

            var previousEpoch = context.V4LastStateEpoch;
            var previousRemoteNext = context.RemoteNextExpectedChunkIndex;
            var previousGrant = context.RemoteGrantedUntilExclusive;
            var receiverProgressChanged = UpdateOutboundReceiverAcknowledgedProgressFromV4StateLocked(context, state);
            context.PullV4StateReceivedCountTotal++;
            if (state.Epoch < previousEpoch)
            {
                applicationResult = new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Idempotent,
                    "state_epoch_stale");
                context.PullV4StateStaleCountTotal++;
                var staleCommitted = Math.Clamp(state.ContiguousCommittedChunkIndex, 0, context.ChunkCount);
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v4_state_received; transfer_id={context.TransferId}; session_id={context.SessionId}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.CurrentRuntimeOwner?.TerminalGeneration ?? 0}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; transport_epoch={context.CurrentTransferLeg?.TransportEpochId ?? 0}; bridge_recovery_generation={context.CurrentTransferLeg?.BridgeRecoveryGeneration ?? 0}; route_publication_generation={context.CurrentRoutePublicationToken?.PublicationGeneration ?? 0}; route_commit_generation={context.CurrentRoutePublicationToken?.RouteCommitGeneration ?? 0}; data_session_generation={context.DataSessionGeneration}; epoch={state.Epoch}; previous_epoch={previousEpoch}; stale=1; applied=0; v4_state_wire_fingerprint={stateWireFingerprint}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; missing_range_count={state.MissingRanges.Count}; projected_ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(state.MissingRanges))}; terminal_ready={(state.TerminalReady ? 1 : 0)}");
                if (IsStrictFallbackFrontierRuntime(context) && state.MissingRanges.Count > 0)
                {
                    LogOutboundPostTunaFallbackRebindStateReplaySuppressedLocked(
                        context,
                        state,
                        stateWireFingerprint,
                        "stale",
                        "stale_receiver_state_evidence_only");
                }

                if (state.MissingRanges.Count > 0)
                {
                    if (ShouldEnqueueRepairOnlyForRebindStateLocked(context, state, staleCommitted))
                    {
                        if (!TrySuppressRetiredFallbackTailOwnerUpdateLocked(
                                context,
                                context.CurrentTransferLeg,
                                "v4_receiver_state",
                                "enqueue_stale_frontier_repair",
                                "stale_frontier_rebind"))
                        {
                            shouldEnqueueRepairs = true;
                            ActivateOutboundV4PostRebindFrontierOnlyRepairLocked(
                                context,
                                context.RemoteNextExpectedChunkIndex,
                                "stale_frontier_rebind");
                            QueueOutboundV4TransportRebindSafetyReplayLocked(context, "stale_frontier_rebind", allowRepeatForSameGeneration: true);
                            LocalOperationalLog.Info(
                                "FileTransferService",
                                $"event=filetransfer_rebind_duplicate_state_repair_enqueued; transfer_id={context.TransferId}; session_id={context.SessionId}; state_kind=stale; epoch={state.Epoch}; previous_epoch={previousEpoch}; stale_contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; current_remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; missing_range_count={state.MissingRanges.Count}");
                        }
                    }
                    else
                    {
                        var reason = staleCommitted == context.RemoteNextExpectedChunkIndex
                        ? "stale_epoch"
                        : "frontier_moved";
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_v4_stale_state_missing_ranges_suppressed; transfer_id={context.TransferId}; session_id={context.SessionId}; epoch={state.Epoch}; reason={reason}; stale_contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; current_remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; missing_range_count={state.MissingRanges.Count}");
                    }
                }

                if (receiverProgressChanged)
                {
                    snapshot = CreateSnapshotLocked();
                }
            }
            else
            {
                var normalizedCommitted = Math.Clamp(state.ContiguousCommittedChunkIndex, 0, context.ChunkCount);
                var frameCredit = Math.Clamp(state.CreditUntilChunkIndexExclusive, normalizedCommitted, context.ChunkCount);
                var currentPostTunaFallbackV6State =
                    context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
                    context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
                    IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg);
                var shouldDiscardPostTunaFallbackStaleTail =
                    currentPostTunaFallbackV6State &&
                    !IsOutboundNormalToTunaActivationProofPendingLocked(context);
                var shouldApplyPostTunaFallbackStaleTailClamp =
                    shouldDiscardPostTunaFallbackStaleTail &&
                    currentPostTunaFallbackCheckpointProof;
                var normalizedCredit = shouldApplyPostTunaFallbackStaleTailClamp
                    ? frameCredit
                    : frameCredit < context.RemoteGrantedUntilExclusive
                        ? Math.Max(context.ChunksAcceptedForTransport, frameCredit)
                        : Math.Max(context.RemoteGrantedUntilExclusive, frameCredit);
                if (state.Epoch == previousEpoch)
                {
                    applicationResult = new RetainedPeerProofApplicationResult(
                        RetainedPeerProofApplicationStatus.Idempotent,
                        "state_epoch_duplicate");
                    context.PullV4StateDuplicateCountTotal++;
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v4_state_received; transfer_id={context.TransferId}; session_id={context.SessionId}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.CurrentRuntimeOwner?.TerminalGeneration ?? 0}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; transport_epoch={context.CurrentTransferLeg?.TransportEpochId ?? 0}; bridge_recovery_generation={context.CurrentTransferLeg?.BridgeRecoveryGeneration ?? 0}; route_publication_generation={context.CurrentRoutePublicationToken?.PublicationGeneration ?? 0}; route_commit_generation={context.CurrentRoutePublicationToken?.RouteCommitGeneration ?? 0}; data_session_generation={context.DataSessionGeneration}; epoch={state.Epoch}; previous_epoch={previousEpoch}; duplicate=1; applied=0; v4_state_wire_fingerprint={stateWireFingerprint}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; missing_range_count={state.MissingRanges.Count}; projected_ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(state.MissingRanges))}; terminal_ready={(state.TerminalReady ? 1 : 0)}");
                    if (IsStrictFallbackFrontierRuntime(context) && state.MissingRanges.Count > 0)
                    {
                        LogOutboundPostTunaFallbackRebindStateReplaySuppressedLocked(
                            context,
                            state,
                            stateWireFingerprint,
                            "duplicate",
                            "duplicate_receiver_state_evidence_only");
                    }

                    if (ShouldEnqueueRepairOnlyForRebindStateLocked(context, state, normalizedCommitted))
                    {
                        if (!TrySuppressRetiredFallbackTailOwnerUpdateLocked(
                                context,
                                context.CurrentTransferLeg,
                                "v4_receiver_state",
                                "enqueue_duplicate_frontier_repair",
                                "duplicate_frontier_rebind"))
                        {
                            ActivateOutboundV4PostRebindFrontierOnlyRepairLocked(
                                context,
                                context.RemoteNextExpectedChunkIndex,
                                "duplicate_frontier_rebind");
                            QueueOutboundV4TransportRebindSafetyReplayLocked(context, "duplicate_frontier_rebind", allowRepeatForSameGeneration: true);
                            LocalOperationalLog.Info(
                                "FileTransferService",
                                $"event=filetransfer_rebind_duplicate_state_repair_enqueued; transfer_id={context.TransferId}; session_id={context.SessionId}; state_kind=duplicate; epoch={state.Epoch}; previous_epoch={previousEpoch}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; current_remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; missing_range_count={state.MissingRanges.Count}");
                            EnqueueV4RepairsFromState(context, state);
                        }
                    }
                    else if (TryRebindOutboundRegularNknV4AcceptedFrontierFromRecoveryStateLocked(
                                 context,
                                 state,
                                 "duplicate_receiver_state"))
                    {
                        snapshot = CreateSnapshotLocked();
                    }

                    if (receiverProgressChanged)
                    {
                        snapshot = CreateSnapshotLocked();
                    }
                }
                else
                {
                    applicationResult = new RetainedPeerProofApplicationResult(
                        RetainedPeerProofApplicationStatus.Applied,
                        "state_epoch_applied");
                    context.PullV4StateAppliedCountTotal++;
                    var normalizedPauseReason = NormalizeReason(state.TransferPauseReason);
                    var peerPauseChanged = state.TransferPaused != context.PeerPaused ||
                        !string.Equals(normalizedPauseReason, context.PeerPauseReason, StringComparison.Ordinal);

                    context.V4LastStateEpoch = Math.Max(context.V4LastStateEpoch, state.Epoch);
                    context.V4LastStateDurableHighestChunkIndex = Math.Max(
                        context.V4LastStateDurableHighestChunkIndex,
                        Math.Clamp(
                            state.DurableReceivedHighestChunkIndex,
                            -1,
                            Math.Max(-1, context.ChunkCount - 1)));
                    context.RemoteNextExpectedChunkIndex = Math.Max(context.RemoteNextExpectedChunkIndex, normalizedCommitted);
                    context.RemoteGrantedUntilExclusive = normalizedCredit;
                    if (shouldApplyPostTunaFallbackStaleTailClamp &&
                        context.ChunksAcceptedForTransport > normalizedCredit)
                    {
                        var previousAcceptedForFallbackClamp = context.ChunksAcceptedForTransport;
                        var previousBytesAcceptedForFallbackClamp = context.BytesAcceptedForTransport;
                        context.ChunksAcceptedForTransport = normalizedCredit;
                        context.BytesAcceptedForTransport = context.ChunksAcceptedForTransport >= context.ChunkCount
                            ? context.FileSizeBytes
                            : Math.Min(
                                context.FileSizeBytes,
                                (long)context.ChunksAcceptedForTransport * Math.Max(1, context.ChunkSizeBytes));
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_post_tuna_fallback_v4_state_credit_clamped; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; state_epoch={state.Epoch}; previous_chunks_accepted_for_transport={previousAcceptedForFallbackClamp}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; previous_bytes_accepted_for_transport={previousBytesAcceptedForFallbackClamp}; bytes_accepted_for_transport={context.BytesAcceptedForTransport}; previous_credit_until_chunk_index_exclusive={previousGrant}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; effective_credit_until_chunk_index_exclusive={normalizedCredit}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; repair_request_id={FormatProtocolLogValue((state as FileTransferReceiverStateFrameV6)?.RepairRequestId ?? "(none)")}; reason=discard_stale_prefallback_tail");
                    }
                    else if (shouldDiscardPostTunaFallbackStaleTail &&
                             context.ChunksAcceptedForTransport > frameCredit)
                    {
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_post_tuna_fallback_v4_state_credit_clamp_suppressed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; state_epoch={state.Epoch}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; bytes_accepted_for_transport={context.BytesAcceptedForTransport}; previous_credit_until_chunk_index_exclusive={previousGrant}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; preserved_credit_until_chunk_index_exclusive={normalizedCredit}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; repair_request_id={FormatProtocolLogValue((state as FileTransferReceiverStateFrameV6)?.RepairRequestId ?? "(none)")}; reason=current_fallback_tail_not_checkpoint_owner");
                    }

                    context.ChunksTransferred = Math.Max(context.ChunksTransferred, context.RemoteNextExpectedChunkIndex);
                    context.BytesTransferred = Math.Max(context.BytesTransferred, Math.Min(context.FileSizeBytes, state.BytesCommitted));
                    context.BytesAcknowledgedByReceiver = Math.Max(context.BytesAcknowledgedByReceiver, context.BytesTransferred);
                    context.V4TerminalReady |= state.TerminalReady;
                    UpdateOutboundV6TransportHandoffFromStateLocked(context, state);
                    var suppressRepairsForAcceptedTail =
                        TryCompleteOutboundV6TransportEpochWhenPeerCaughtUpToAcceptedTailLocked(context, state);
                    UpdateOutboundV4PostRebindFrontierOnlyRecoveryLocked(context, state);
                    if (currentPostTunaFallbackV6State &&
                        state is FileTransferReceiverStateFrameV6 fallbackReceiverState)
                    {
                        var fallbackReceiverAdvancedFrontier = context.RemoteNextExpectedChunkIndex > previousRemoteNext;
                        var fallbackStateRequestsFrontierGap = OutboundV6ReceiverStateRequestsCurrentFrontierLocked(
                            context,
                            fallbackReceiverState,
                            fallbackReceiverAdvancedFrontier);
                        var fallbackTailYielded = TryMarkOutboundFallbackTailQuiescentOrTerminalLocked(
                            context,
                            fallbackReceiverState,
                            fallbackStateRequestsFrontierGap,
                            "receiver_state_sparse_runtime",
                            out var fallbackTerminalProofConsumed);
                        if (fallbackTerminalProofConsumed)
                        {
                            suppressFallbackTailRepairEnqueue = true;
                            context.State = FileTransferTransferState.AwaitingCompletion;
                            context.StatusMessage = "Waiting for receiver verification.";
                        }
                        else if (fallbackTailYielded)
                        {
                            suppressFallbackTailRepairEnqueue = true;
                        }
                    }

                    var regularV4RecoveryFrontierRebound =
                        TryRebindOutboundRegularNknV4AcceptedFrontierFromRecoveryStateLocked(
                            context,
                            state,
                            "applied_receiver_state");
                    if (context.RemoteNextExpectedChunkIndex > previousRemoteNext)
                    {
                        ClearObsoleteOutboundV4RepairWorkAfterFrontierAdvanceLocked(
                            context,
                            previousRemoteNext,
                            context.RemoteNextExpectedChunkIndex);
                    }

                    if (peerPauseChanged)
                    {
                        context.PeerPaused = state.TransferPaused;
                        context.PeerPauseReason = normalizedPauseReason;
                        context.PeerPausedSinceUtc = state.TransferPaused ? DateTimeOffset.UtcNow : null;
                        if (!state.TransferPaused)
                        {
                            ResetOutboundV4AcceptedForPeerResumeLocked(context);
                        }
                    }

                    context.SparseSenderPumpLastWakeReason = peerPauseChanged
                        ? state.TransferPaused
                            ? "peer_user_paused"
                            : "peer_user_resumed"
                        : regularV4RecoveryFrontierRebound
                            ? "regular_v4_receive_recovery_frontier_rebind"
                            : state.TerminalReady
                            ? "state_terminal_ready"
                            : state.MissingRanges.Count > 0
                                ? "state_missing_ranges"
                                : normalizedCredit > previousGrant
                                    ? "state_credit"
                                    : normalizedCredit < previousGrant
                                        ? "state_credit_reduced"
                                        : "state_progress";
                    context.PullV4LastGrantReceivedUtc = DateTimeOffset.UtcNow;
                    TrimSenderRepairCacheLocked(context, context.RemoteNextExpectedChunkIndex);
                    foreach (var chunkIndex in context.SentAwaitingAck.Keys.Where(chunkIndex => chunkIndex < context.RemoteNextExpectedChunkIndex).ToArray())
                    {
                        context.SentAwaitingAck.Remove(chunkIndex);
                    }

                    if (!context.UserPaused && !context.PeerPaused)
                    {
                        context.StatusMessage = context.V4TerminalReady
                            ? "Waiting for receiver verification."
                            : "Receiver granted V4 transfer credit.";
                    }
                    else if (context.PeerPaused && !context.UserPaused)
                    {
                        context.StatusMessage = "Peer paused transfer.";
                    }

                    MaybeObserveRegularV4ControlFeedbackPressureFromStateLocked(context, state);
                    LogOutboundV4StateReceivedLocked(
                        context,
                        state,
                        stateWireFingerprint,
                        previousEpoch,
                        previousRemoteNext,
                        previousGrant,
                        applied: true,
                        stale: false,
                        duplicate: false);
                    snapshot = CreateSnapshotLocked();
                    shouldEnqueueRepairs = !suppressRepairsForAcceptedTail && !suppressFallbackTailRepairEnqueue;
                    shouldSignalSenderPump =
                        state.TerminalReady &&
                        ShouldUseSparseSenderTerminalReadyCompletion(context);
                }
            }
        }

        if (OutboundSparseStateApplyBarrierForTests is { } stateApplyBarrier)
        {
            await stateApplyBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
        }

        var sideEffectsCurrent = false;
        lock (gate)
        {
            sideEffectsCurrent = ReferenceEquals(outboundTransfer, context) &&
                !context.IsTerminal &&
                (receiveDataSession is null ||
                 IsOutboundSparseReceiveResultCurrentLocked(
                     context,
                     receiveInstall,
                     receiveRuntimeOwner,
                     receiveDataSession,
                     receiveDataSessionGeneration,
                     out _));
            if (!sideEffectsCurrent)
            {
                snapshot = null;
                shouldSignalSenderPump = false;
                applicationResult = new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Rejected,
                    "state_receive_scope_replaced_during_apply");
            }
            else if (shouldEnqueueRepairs)
            {
                EnqueueV4RepairsFromReceiveState(
                    context,
                    state,
                    receiveInstall,
                    receiveRuntimeOwner,
                    receiveDataSession,
                    receiveDataSessionGeneration);
                shouldEnqueueRepairs = false;
            }
        }

        if (sideEffectsCurrent && fallbackCheckpointReissueRequest is not null)
        {
            if (fallbackCheckpointReissueDataSession is not null)
            {
                QueueOutboundV4SparseRuntimeStateRefreshIfCurrent(
                    context,
                    fallbackCheckpointReissueDataSession,
                    fallbackCheckpointReissueRequest,
                    "checkpoint_reissue",
                    receiveInstall,
                    receiveRuntimeOwner,
                    receiveDataSession,
                    receiveDataSessionGeneration);
            }
            else
            {
                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_fallback_checkpoint_reissue_skipped; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; reason=data_session_missing; checkpoint_request_id={FormatProtocolLogValue(fallbackCheckpointReissueRequest.RepairRequestId ?? "(none)")}; transport_epoch={fallbackCheckpointReissueRequest.TransportEpoch}");
            }
        }

        if (snapshot is not null)
        {
            RaiseTransferChanged(snapshot);
            MaybeLogProgressMilestone(context, FileTransferDirection.Outbound);
        }

        if (sideEffectsCurrent && shouldSignalSenderPump)
        {
            SignalOutboundSparseSenderPump(
                context,
                receiveInstall,
                receiveRuntimeOwner,
                receiveDataSession,
                receiveDataSessionGeneration);
        }

        return applicationResult;
    }

    private bool TryRebindOutboundRegularNknV4AcceptedFrontierFromRecoveryStateLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        string source)
    {
        if (!context.RouteRuntime.UsesRegularNknV4FastRuntime ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4 ||
            state.TerminalReady ||
            context.UserPaused ||
            context.PeerPaused ||
            !context.PullSourceCanSeek ||
            context.RemoteNextExpectedChunkIndex >= context.ChunkCount)
        {
            return false;
        }

        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var acceptedBefore = Math.Clamp(context.ChunksAcceptedForTransport, 0, context.ChunkCount);
        var frontierLagChunks = Math.Max(0, acceptedBefore - remoteFrontier);
        if (frontierLagChunks <= 0 ||
            (acceptedBefore < context.ChunkCount &&
             frontierLagChunks < PullV4RegularNknControlFeedbackPressureMinFrontierLagChunks))
        {
            return false;
        }

        var now = DateTimeOffset.UtcNow;
        var receiveRecoveryFresh =
            context.V6LastReceiveRecoveryRequestedUtc is { } lastReceiveRecovery &&
            now - lastReceiveRecovery < CurrentV6SenderRequestFeedbackStallRecoveryCooldown;
        var feedbackPressureFresh =
            context.PullV4LastRegularNknControlFeedbackPressureObservedUtc is { } lastFeedbackPressure &&
            now - lastFeedbackPressure < TimeSpan.FromMilliseconds(PullControlChatterWindowMs * 4L);
        var replayOrRecoveryActive =
            context.PullRegularNknV4PeerSilenceSafetyReplayCount > 0 ||
            context.PullV4SenderPumpRepairQueue.Count > 0 ||
            context.PullV4SenderPumpRepairQueuedChunkIndices.Count > 0 ||
            context.PullTransportResumeRequestPending ||
            ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context);
        if (state.MissingRanges.Count > 0)
        {
            LogOutboundRegularNknV4FrontierRebindRejectedLocked(
                context,
                state,
                source,
                "would_make_requested_repair_future",
                remoteFrontier,
                acceptedBefore,
                frontierLagChunks,
                receiveRecoveryFresh,
                feedbackPressureFresh,
                replayOrRecoveryActive);
            return false;
        }

        if (feedbackPressureFresh &&
            !receiveRecoveryFresh &&
            !replayOrRecoveryActive)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_feedback_pressure_frontier_rebind_suppressed; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; state_epoch={state.Epoch}; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={acceptedBefore}; frontier_lag_chunks={frontierLagChunks}; credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; missing_range_count={state.MissingRanges.Count}; reason=feedback_pressure_only");
            context.PullV4LastRegularNknControlFeedbackPressureObservedUtc = null;
            return false;
        }

        if (!receiveRecoveryFresh)
        {
            var reason = replayOrRecoveryActive
                ? "stale_liveness_recovery"
                : feedbackPressureFresh
                    ? "feedback_pressure_only"
                    : "no_current_receive_recovery_authority";
            LogOutboundRegularNknV4FrontierRebindRejectedLocked(
                context,
                state,
                source,
                reason,
                remoteFrontier,
                acceptedBefore,
                frontierLagChunks,
                receiveRecoveryFresh,
                feedbackPressureFresh,
                replayOrRecoveryActive);
            if (feedbackPressureFresh)
            {
                context.PullV4LastRegularNknControlFeedbackPressureObservedUtc = null;
            }

            return false;
        }

        if (!TryAuthorizeRepairReplayLocked(
                context,
                context.CurrentRuntimeOwner,
                RepairReplayKind.TransportRebindSafetyReplay,
                "regular_v4_receive_recovery_frontier_rebind",
                source,
                context.CurrentTransferLeg,
                context.CurrentTransferLeg?.TransportEpochId,
                context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                null,
                out _))
        {
            return false;
        }

        var bytesAcceptedBefore = context.BytesAcceptedForTransport;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_receive_recovery_frontier_rebind; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; state_epoch={state.Epoch}; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_before={acceptedBefore}; bytes_accepted_before={bytesAcceptedBefore}; frontier_lag_chunks={frontierLagChunks}; receive_recovery_fresh={(receiveRecoveryFresh ? 1 : 0)}; feedback_pressure_fresh={(feedbackPressureFresh ? 1 : 0)}; replay_or_recovery_active={(replayOrRecoveryActive ? 1 : 0)}; credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; missing_range_count={state.MissingRanges.Count}");

        ResetOutboundV4AcceptedAfterPauseLocked(
            context,
            "regular_v4_receive_recovery_frontier_rebind");
        if (feedbackPressureFresh)
        {
            context.PullV4LastRegularNknControlFeedbackPressureObservedUtc = null;
        }

        return Math.Clamp(context.ChunksAcceptedForTransport, 0, context.ChunkCount) < acceptedBefore;
    }

    private static void LogOutboundRegularNknV4FrontierRebindRejectedLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        string source,
        string reason,
        int remoteFrontier,
        int acceptedBefore,
        int frontierLagChunks,
        bool receiveRecoveryFresh,
        bool feedbackPressureFresh,
        bool replayOrRecoveryActive)
    {
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_frontier_rebind_rejected; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; reason={FormatProtocolLogValue(reason)}; state_epoch={state.Epoch}; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={acceptedBefore}; frontier_lag_chunks={frontierLagChunks}; receive_recovery_fresh={(receiveRecoveryFresh ? 1 : 0)}; feedback_pressure_fresh={(feedbackPressureFresh ? 1 : 0)}; replay_or_recovery_active={(replayOrRecoveryActive ? 1 : 0)}; missing_range_count={state.MissingRanges.Count}; transport_paused={(context.PullTransportPaused ? 1 : 0)}; transport_pause_reason={FormatProtocolLogValue(context.PullTransportPauseReason ?? "(none)")}");
    }

    private void MaybeObserveRegularV4ControlFeedbackPressureFromStateLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state)
    {
        if (state.MissingRanges.Count <= 0 &&
            context.PullV4SenderPumpRepairRequests.Count <= 0)
        {
            return;
        }

        var pendingRepairCount = 0;
        foreach (var range in state.MissingRanges)
        {
            pendingRepairCount += Math.Max(0, range.ChunkCount);
        }

        var availableCreditChunks = Math.Max(
            0,
            Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount) - context.ChunksAcceptedForTransport);
        var creditExhaustedTimeMs = context.V4SenderCreditExhaustedSinceUtc is null || availableCreditChunks > 0 || context.V4TerminalReady
            ? 0
            : (long)Math.Max(0, (DateTimeOffset.UtcNow - context.V4SenderCreditExhaustedSinceUtc.Value).TotalMilliseconds);
        MaybeObserveRegularV4ControlFeedbackPressure(
            context,
            creditExhaustedTimeMs,
            availableCreditChunks,
            pendingRepairCount);
    }

    private static bool UpdateOutboundReceiverAcknowledgedProgressFromV4StateLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state)
    {
        var receiverBytes = Math.Clamp(state.BytesCommitted, 0L, Math.Max(0L, context.FileSizeBytes));
        var previousVisibleBytes = Math.Max(context.BytesAcknowledgedByReceiver, context.BytesTransferred);
        if (receiverBytes <= previousVisibleBytes)
        {
            return false;
        }

        context.BytesAcknowledgedByReceiver = receiverBytes;
        context.BytesTransferred = Math.Max(context.BytesTransferred, receiverBytes);
        return true;
    }

    private void ActivateOutboundV4PostRebindFrontierOnlyRepairLocked(
        OutboundTransferContext context,
        int frontierChunkIndex,
        string reason)
    {
        var recoveryGeneration = GetOutboundPostTunaRecoveryGenerationLocked(context);
        if (recoveryGeneration <= 0 ||
            frontierChunkIndex < 0 ||
            frontierChunkIndex >= context.ChunkCount)
        {
            return;
        }

        if (TrySuppressRetiredFallbackTailOwnerUpdateLocked(
                context,
                context.CurrentTransferLeg,
                "v4_post_rebind_frontier_only_repair",
                "activate_frontier_only_repair",
                reason))
        {
            return;
        }

        if (context.PullTransportFrontierOnlyRepairActive)
        {
            var activeStart = context.PullTransportFrontierOnlyRepairStartChunkIndex;
            if (activeStart >= 0 && frontierChunkIndex >= activeStart)
            {
                TryMarkOutboundFallbackTailRepairTimeoutLocked(context, activeStart, reason);
                return;
            }
        }

        var previousStart = context.PullTransportFrontierOnlyRepairStartChunkIndex;
        context.PullTransportFrontierOnlyRepairActive = true;
        context.PullTransportFrontierOnlyRepairStartChunkIndex = frontierChunkIndex;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_transport_rebind_frontier_only_started; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(reason)}; rebind_generation={recoveryGeneration}; frontier_chunk_index={frontierChunkIndex}; previous_frontier_only_start_chunk_index={previousStart}; stable_advance_required_chunks={PullTransportRebindFrontierOnlyStableAdvanceChunks}");
    }

    private static void UpdateOutboundV4PostRebindFrontierOnlyRecoveryLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state)
    {
        var recoveryGeneration = GetOutboundPostTunaRecoveryGenerationLocked(context);
        if (!context.PullTransportFrontierOnlyRepairActive ||
            recoveryGeneration <= 0)
        {
            return;
        }

        var activeStart = Math.Max(0, context.PullTransportFrontierOnlyRepairStartChunkIndex);
        var advancedChunks = context.RemoteNextExpectedChunkIndex - activeStart;
        if (advancedChunks < PullTransportRebindFrontierOnlyStableAdvanceChunks)
        {
            return;
        }

        context.PullTransportFrontierOnlyRepairActive = false;
        context.PullTransportFrontierOnlyRepairStartChunkIndex = -1;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_transport_rebind_frontier_only_recovered; transfer_id={context.TransferId}; session_id={context.SessionId}; rebind_generation={recoveryGeneration}; active_start_chunk_index={activeStart}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; advanced_chunks={advancedChunks}; missing_range_count={state.MissingRanges.Count}");
    }

    private void UpdateOutboundV6TransportHandoffFromStateLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state)
    {
        if (context.V6TransportHandoff is null)
        {
            return;
        }

        var handoff = context.V6TransportHandoff;
        if (handoff.EpochId <= context.LastRecoveredV6TransportHandoffEpoch &&
            !IsV6TransportHandoffBlockingTail(handoff))
        {
            return;
        }

        if (handoff.State == V6TransportHandoffState.Recovered)
        {
            CompleteOutboundV6TransportHandoffLocked(
                context,
                "recovered_state_observed",
                context.RemoteNextExpectedChunkIndex,
                state.DurableReceivedHighestChunkIndex);
            return;
        }

        var v6State = state as FileTransferReceiverStateFrameV6;
        if (v6State is not null &&
            v6State.TransportEpoch > 0 &&
            v6State.TransportEpoch != handoff.EpochId)
        {
            if (!TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
                    context,
                    v6State.TransportEpoch,
                    FileTransferProtocol.ReceiverStateFrameTypeV6,
                    "peer_state_epoch_conflict",
                    Math.Clamp(v6State.ContiguousCommittedChunkIndex, 0, context.ChunkCount),
                    v6State.DurableReceivedHighestChunkIndex,
                    requireFrontierEvidence: v6State.MissingRanges.Count > 0))
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v6_recovery_frame_ignored; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={FileTransferProtocol.ReceiverStateFrameTypeV6}; reason=stale_or_mismatched_epoch; frame_transport_epoch={v6State.TransportEpoch}; current_transport_epoch={handoff.EpochId}");
                return;
            }

            handoff = context.V6TransportHandoff!;
        }

        handoff.LastProofUtc = DateTimeOffset.UtcNow;
        if (TryCompleteOutboundV6HandoffWhenPeerCaughtUpToAcceptedTailLocked(context, state, handoff))
        {
            return;
        }

        var frontierMissing = state.MissingRanges.Any(range =>
            range.StartChunkIndex <= context.RemoteNextExpectedChunkIndex &&
            context.RemoteNextExpectedChunkIndex < range.StartChunkIndex + range.ChunkCount);
        if (context.RemoteNextExpectedChunkIndex <= handoff.StartingCommittedChunkIndex || frontierMissing)
        {
            TrySetV6TransportHandoffState(
                handoff,
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                V6TransportHandoffState.FrontierRepairOnly,
                frontierMissing ? "frontier_missing_state" : "state_proof",
                context.RemoteNextExpectedChunkIndex,
                state.DurableReceivedHighestChunkIndex);
            return;
        }

        var frontierLagChunks = Math.Max(
            0,
            state.DurableReceivedHighestChunkIndex - context.RemoteNextExpectedChunkIndex + 1);
        if (state.MissingRanges.Count > 0 || frontierLagChunks > 0)
        {
            TrySetV6TransportHandoffState(
                handoff,
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                V6TransportHandoffState.BackfillRepair,
                state.MissingRanges.Count > 0
                    ? "frontier_proof_with_backfill"
                    : "frontier_proof_with_sparse_backfill",
                context.RemoteNextExpectedChunkIndex,
                state.DurableReceivedHighestChunkIndex);
            return;
        }

        if (context.RemoteNextExpectedChunkIndex != handoff.LastObservedCommittedChunkIndex ||
            state.DurableReceivedHighestChunkIndex != handoff.LastObservedHighestChunkIndex)
        {
            handoff.DurableProgressSamples++;
            handoff.LastObservedCommittedChunkIndex = context.RemoteNextExpectedChunkIndex;
            handoff.LastObservedHighestChunkIndex = state.DurableReceivedHighestChunkIndex;
        }

        if (context.RemoteNextExpectedChunkIndex >= context.ChunkCount ||
            handoff.DurableProgressSamples >= 2)
        {
            CompleteOutboundV6TransportHandoffLocked(
                context,
                "durable_frontier_progress",
                context.RemoteNextExpectedChunkIndex,
                state.DurableReceivedHighestChunkIndex);
        }
    }

    private bool TryCompleteOutboundV6HandoffWhenPeerCaughtUpToAcceptedTailLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        TransportHandoffEpoch handoff)
    {
        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var acceptedUntil = ResolveOutboundRepairAcceptedUntilExclusiveLocked(context);
        if (remoteFrontier < acceptedUntil ||
            state.DurableReceivedHighestChunkIndex >= acceptedUntil)
        {
            return false;
        }

        foreach (var range in state.MissingRanges)
        {
            var start = Math.Clamp(range.StartChunkIndex, 0, context.ChunkCount);
            var end = Math.Clamp(range.StartChunkIndex + range.ChunkCount, start, context.ChunkCount);
            if (start < acceptedUntil && end > start)
            {
                return false;
            }
        }

        CompleteOutboundV6TransportHandoffLocked(
            context,
            "frontier_caught_up_to_accepted_tail",
            remoteFrontier,
            state.DurableReceivedHighestChunkIndex);
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v6_handoff_tail_caught_up_to_accepted; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; transport_epoch={handoff.EpochId}; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={acceptedUntil}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; missing_range_count={state.MissingRanges.Count}");
        return true;
    }

    private static bool ShouldEnqueueRepairOnlyForRebindStateLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        int normalizedCommitted)
    {
        if (IsStrictFallbackFrontierRuntime(context) ||
            !IsOutboundPostTunaRecoveryActiveLocked(context) ||
            state.MissingRanges.Count == 0 ||
            context.IsTerminal)
        {
            return false;
        }

        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        if (normalizedCommitted != remoteFrontier)
        {
            return false;
        }

        foreach (var range in state.MissingRanges)
        {
            var start = Math.Clamp(range.StartChunkIndex, 0, context.ChunkCount);
            var end = Math.Clamp(range.StartChunkIndex + range.ChunkCount, start, context.ChunkCount);
            if (start <= remoteFrontier && remoteFrontier < end)
            {
                return true;
            }

            if (start == remoteFrontier)
            {
                return true;
            }
        }

        return false;
    }

    private static void LogOutboundPostTunaFallbackRebindStateReplaySuppressedLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        string stateWireFingerprint,
        string stateKind,
        string decisionReason)
    {
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_rebind_state_replay_suppressed; authority_effect=none; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; state_kind={stateKind}; decision_reason={decisionReason}; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.CurrentRuntimeOwner?.TerminalGeneration ?? 0}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; transport_epoch={context.CurrentTransferLeg?.TransportEpochId ?? 0}; bridge_recovery_generation={context.CurrentTransferLeg?.BridgeRecoveryGeneration ?? 0}; checkpoint_request_id={FormatProtocolLogValue(context.CurrentTransferLeg?.CheckpointRequestId ?? "(none)")}; route_publication_generation={context.CurrentRoutePublicationToken?.PublicationGeneration ?? 0}; route_commit_generation={context.CurrentRoutePublicationToken?.RouteCommitGeneration ?? 0}; data_session_identity={FormatProtocolLogValue(context.DataSession?.GetType().Name ?? "(none)")}; data_session_generation={context.DataSessionGeneration}; rebind_generation={GetOutboundPostTunaRecoveryGenerationLocked(context)}; epoch={state.Epoch}; v4_state_wire_fingerprint={stateWireFingerprint}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; missing_range_count={state.MissingRanges.Count}; projected_ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(state.MissingRanges))}");
    }

    private static IReadOnlyList<FileTransferRangeV4> ClampV6HandoffFrontierRepairRangesForSend(
        IReadOnlyList<FileTransferRangeV4> ranges,
        int frontierChunkIndex,
        int chunkCount)
    {
        if (ranges.Count == 0 ||
            frontierChunkIndex < 0 ||
            frontierChunkIndex >= chunkCount)
        {
            return ranges;
        }

        foreach (var range in ranges)
        {
            var start = Math.Clamp(range.StartChunkIndex, 0, chunkCount);
            var end = Math.Clamp(range.StartChunkIndex + range.ChunkCount, start, chunkCount);
            if (start <= frontierChunkIndex && frontierChunkIndex < end)
            {
                return
                [
                    new FileTransferRangeV4
                    {
                        StartChunkIndex = frontierChunkIndex,
                        ChunkCount = V4PostFallbackEmergencyFrontierRepairChunks,
                    },
                ];
            }
        }

        return ranges;
    }

    private static bool IsOutboundPostFallbackExactFrontierRepairRequiredLocked(
        OutboundTransferContext context,
        int frontierChunkIndex)
    {
        if (!HasCurrentOutboundPostTunaFallbackFrontierRepairAuthorityLocked(context) ||
            frontierChunkIndex < 0 ||
            frontierChunkIndex >= context.ChunkCount)
        {
            return false;
        }

        return IsV6TransportHandoffBlockingTail(context.V6TransportHandoff) ||
               context.PullTransportFrontierOnlyRepairActive;
    }

    private static bool ShouldClampOutboundV6HandoffFrontierRepairRangeForSendLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        int frontierChunkIndex)
    {
        if (IsOutboundV6BackfillRepairRequestLocked(context, state))
        {
            return false;
        }

        if (ShouldPreserveOutboundPostFallbackSparseFrontierBackfillRangeLocked(context, state, frontierChunkIndex))
        {
            return false;
        }

        if (state is FileTransferReceiverStateFrameV6 v6State &&
            IsOutboundPostTunaRecoveryActiveLocked(context))
        {
            return !ShouldUseCurrentOutboundFallbackCheckpointRepairWindowLocked(
                context,
                v6State,
                frontierChunkIndex);
        }

        return IsOutboundPostFallbackExactFrontierRepairRequiredLocked(context, frontierChunkIndex);
    }

    private static bool ShouldUseCurrentOutboundFallbackCheckpointRepairWindowLocked(
        OutboundTransferContext context,
        FileTransferReceiverStateFrameV6 state,
        int frontierChunkIndex)
    {
        if (!IsOutboundPostTunaRecoveryActiveLocked(context) ||
            !context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV6 ||
            context.CurrentTransferLeg is not { } leg ||
            !IsCurrentPostTunaFallbackLeg(leg) ||
            leg.State != FileTransferLegState.RecoveryActive ||
            !leg.CanSendData ||
            string.IsNullOrWhiteSpace(state.RepairRequestId) ||
            string.IsNullOrWhiteSpace(context.LastOutboundFallbackCheckpointRepairRequestId) ||
            !string.Equals(state.SessionId, context.SessionId, StringComparison.Ordinal) ||
            !string.Equals(state.TransferId, context.TransferId, StringComparison.Ordinal) ||
            !string.Equals(state.RepairRequestId, context.LastOutboundFallbackCheckpointRepairRequestId, StringComparison.Ordinal) ||
            state.TransportEpoch <= 0 ||
            state.TransportEpoch != leg.TransportEpochId ||
            state.TransportEpoch != context.LastOutboundFallbackCheckpointRepairTransportEpoch ||
            leg.Generation != context.LastOutboundFallbackCheckpointRepairLegGeneration ||
            leg.LiveRouteEpochId != context.LastOutboundFallbackCheckpointRepairLiveRouteEpoch ||
            !string.Equals(state.RecoveryMode, V6RegularNknStateRefreshRecoveryMode, StringComparison.Ordinal) ||
            frontierChunkIndex < 0 ||
            frontierChunkIndex >= context.ChunkCount ||
            state.DurableReceivedHighestChunkIndex <= frontierChunkIndex)
        {
            return false;
        }

        foreach (var range in state.MissingRanges)
        {
            var start = Math.Clamp(range.StartChunkIndex, 0, context.ChunkCount);
            var end = Math.Clamp(range.StartChunkIndex + range.ChunkCount, start, context.ChunkCount);
            if (start <= frontierChunkIndex &&
                frontierChunkIndex < end &&
                end - frontierChunkIndex > V4PostFallbackEmergencyFrontierRepairChunks)
            {
                return true;
            }
        }

        return false;
    }

    private static bool ShouldPreserveOutboundPostFallbackSparseFrontierBackfillRangeLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        int frontierChunkIndex)
    {
        if (state is FileTransferReceiverStateFrameV6)
        {
            // Explicit V6 backfill requests are handled before this helper. Other post-Tuna
            // fallback frontier proofs must stay exact-frontier to avoid repair amplification.
            return false;
        }

        if (!IsOutboundPostTunaRecoveryActiveLocked(context) ||
            frontierChunkIndex < 0 ||
            frontierChunkIndex >= context.ChunkCount ||
            state.DurableReceivedHighestChunkIndex <= frontierChunkIndex)
        {
            return false;
        }

        foreach (var range in state.MissingRanges)
        {
            var start = Math.Clamp(range.StartChunkIndex, 0, context.ChunkCount);
            var end = Math.Clamp(range.StartChunkIndex + range.ChunkCount, start, context.ChunkCount);
            if (start <= frontierChunkIndex &&
                frontierChunkIndex < end &&
                end - frontierChunkIndex > V4PostFallbackEmergencyFrontierRepairChunks)
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsOutboundV6BackfillRepairRequestLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state)
        => state is FileTransferReceiverStateFrameV6 v6State &&
           string.Equals(v6State.Priority, "backfill", StringComparison.OrdinalIgnoreCase) &&
           string.Equals(v6State.RecoveryMode, FormatV6TransportHandoffState(V6TransportHandoffState.BackfillRepair), StringComparison.OrdinalIgnoreCase) &&
           context.V6TransportHandoff?.State == V6TransportHandoffState.BackfillRepair;

    private static bool IsOutboundPeerV6TransportEpochUsableLocked(
        OutboundTransferContext context,
        long transportEpoch)
    {
        if (transportEpoch <= 0)
        {
            return false;
        }

        if (context.V6TransportHandoff is { } handoff &&
            handoff.EpochId == transportEpoch &&
            handoff.State != V6TransportHandoffState.Recovered)
        {
            return true;
        }

        return transportEpoch > context.LastRecoveredV6TransportHandoffEpoch;
    }

    private static bool TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
        OutboundTransferContext context,
        long peerTransportEpoch,
        string frameType,
        string reason,
        int peerCommittedChunkIndex,
        int peerHighestObservedChunkIndex,
        bool requireFrontierEvidence)
    {
        if (peerTransportEpoch <= 0 ||
            context.V6TransportHandoff is not { } current ||
            current.EpochId == peerTransportEpoch ||
            !IsV6TransportHandoffBlockingTail(current))
        {
            return false;
        }

        var clampedPeerCommitted = Math.Clamp(peerCommittedChunkIndex, 0, context.ChunkCount);
        var peerHighest = Math.Max(-1, peerHighestObservedChunkIndex);
        var currentFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var hasFrontierEvidence = !requireFrontierEvidence ||
                                  (clampedPeerCommitted <= currentFrontier &&
                                   peerHighest >= currentFrontier);
        if (!hasFrontierEvidence)
        {
            return false;
        }

        var previousEpoch = current.EpochId;
        var previousState = current.State;
        context.V6TransportHandoff = new TransportHandoffEpoch
        {
            EpochId = peerTransportEpoch,
            Kind = current.Kind,
            SourceTransport = current.SourceTransport,
            TargetTransport = current.TargetTransport,
            Direction = FileTransferDirection.Outbound,
            Reason = string.IsNullOrWhiteSpace(current.Reason) ? reason : current.Reason,
            StartedUtc = current.StartedUtc,
            TargetReadyUtc = current.TargetReadyUtc ?? DateTimeOffset.UtcNow,
            StartingCommittedChunkIndex = Math.Min(current.StartingCommittedChunkIndex, clampedPeerCommitted),
            StartingHighestObservedChunkIndex = Math.Max(current.StartingHighestObservedChunkIndex, peerHighest),
            LastProofUtc = DateTimeOffset.UtcNow,
            State = V6TransportHandoffState.FrontierRepairOnly,
            LastObservedCommittedChunkIndex = clampedPeerCommitted,
            LastObservedHighestChunkIndex = peerHighest,
            LastRepairRequestId = current.LastRepairRequestId,
            LastStateChangeLogUtc = DateTimeOffset.UtcNow,
        };
        context.PullTransportRebindGeneration = Math.Max(
            context.PullTransportRebindGeneration,
            (int)Math.Min(int.MaxValue, peerTransportEpoch));
        context.SparseSenderPumpLastWakeReason = "v6_handoff_epoch_reconciled";
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v6_handoff_epoch_conflict; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={frameType}; action=adopt_peer_epoch; reason={FormatProtocolLogValue(reason)}; previous_transport_epoch={previousEpoch}; peer_transport_epoch={peerTransportEpoch}; last_recovered_transport_epoch={context.LastRecoveredV6TransportHandoffEpoch}; previous_state={FormatV6TransportHandoffState(previousState)}; state={FormatV6TransportHandoffState(context.V6TransportHandoff.State)}; committed_chunk={clampedPeerCommitted}; highest_observed_chunk={peerHighest}; target_transport={FormatFileTransferTransportKind(context.V6TransportHandoff.TargetTransport)}");
        return true;
    }

    private static bool TryReopenOutboundRecoveredV6TransportHandoffEpochLocked(
        OutboundTransferContext context,
        long peerTransportEpoch,
        string frameType,
        string reason,
        int peerCommittedChunkIndex,
        int peerHighestObservedChunkIndex,
        bool requireFrontierEvidence)
    {
        if (peerTransportEpoch <= 0 ||
            peerTransportEpoch > context.LastRecoveredV6TransportHandoffEpoch ||
            context.V6TransportHandoff is not null)
        {
            return false;
        }

        var clampedPeerCommitted = Math.Clamp(peerCommittedChunkIndex, 0, context.ChunkCount);
        var peerHighest = Math.Max(-1, peerHighestObservedChunkIndex);
        var currentFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var hasFrontierEvidence = !requireFrontierEvidence ||
                                  (clampedPeerCommitted <= currentFrontier &&
                                   peerHighest >= currentFrontier);
        if (!hasFrontierEvidence)
        {
            return false;
        }

        var now = DateTimeOffset.UtcNow;
        context.V6TransportHandoff = new TransportHandoffEpoch
        {
            EpochId = peerTransportEpoch,
            Kind = FileTransferTransportHandoffKind.RegularNknRecovery,
            SourceTransport = FileTransferTransportKind.Unknown,
            TargetTransport = FileTransferTransportKind.RegularNkn,
            Direction = FileTransferDirection.Outbound,
            Reason = reason,
            StartedUtc = now,
            TargetReadyUtc = now,
            StartingCommittedChunkIndex = Math.Min(currentFrontier, clampedPeerCommitted),
            StartingHighestObservedChunkIndex = Math.Max(Math.Max(-1, context.ChunksAcceptedForTransport - 1), peerHighest),
            LastProofUtc = now,
            State = V6TransportHandoffState.FrontierRepairOnly,
            LastObservedCommittedChunkIndex = clampedPeerCommitted,
            LastObservedHighestChunkIndex = peerHighest,
            LastStateChangeLogUtc = now,
        };
        context.PullTransportRebindGeneration = Math.Max(
            context.PullTransportRebindGeneration,
            (int)Math.Min(int.MaxValue, peerTransportEpoch));
        context.SparseSenderPumpLastWakeReason = "v6_handoff_reopened_recovered_epoch";
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v6_handoff_epoch_reopened; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={frameType}; reason={FormatProtocolLogValue(reason)}; peer_transport_epoch={peerTransportEpoch}; last_recovered_transport_epoch={context.LastRecoveredV6TransportHandoffEpoch}; state={FormatV6TransportHandoffState(context.V6TransportHandoff.State)}; committed_chunk={clampedPeerCommitted}; highest_observed_chunk={peerHighest}; current_frontier_chunk={currentFrontier}; target_transport={FormatFileTransferTransportKind(context.V6TransportHandoff.TargetTransport)}");
        return true;
    }

    private static bool ShouldIgnoreOutboundPostYieldFallbackRecoveryFrameLocked(
        OutboundTransferContext context,
        long transportEpoch,
        string frameType,
        string reason)
    {
        if (!IsPostYieldFallbackTailOwnerRetiredAndYieldedLocked(context, context.CurrentTransferLeg))
        {
            return false;
        }

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_post_tuna_fallback_late_recovery_ignored_after_yield; direction=outbound; transfer_id={context.TransferId}; session_id={FormatProtocolLogValue(context.SessionId)}; frame_type={FormatProtocolLogValue(frameType)}; reason={FormatProtocolLogValue(reason)}; transport_epoch={transportEpoch}; last_recovered_transport_epoch={context.LastRecoveredV6TransportHandoffEpoch}; leg_generation={context.CurrentTransferLeg!.Generation}; live_route_epoch={context.CurrentTransferLeg.LiveRouteEpochId}; leg_state={FormatFileTransferLegState(context.CurrentTransferLeg.State)}; can_send_data={(context.CurrentTransferLeg.CanSendData ? 1 : 0)}; runtime_unlock_activation_window_granted={(context.RuntimeUnlockActivationWindowGranted ? 1 : 0)}");
        return true;
    }

    private void ApplyOutboundV6HandoffFrame(
        OutboundTransferContext context,
        FileTransferTransportEpochFrameV6 handoff,
        OutboundSparsePumpInstall? receiveInstall = null,
        RuntimeOwnerToken? receiveRuntimeOwner = null,
        IFileTransferDataSession? receiveDataSession = null,
        long receiveDataSessionGeneration = 0)
    {
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                (receiveDataSession is not null &&
                 !IsOutboundSparseReceiveResultCurrentLocked(
                     context,
                     receiveInstall,
                     receiveRuntimeOwner,
                     receiveDataSession,
                     receiveDataSessionGeneration,
                     out _)) ||
                handoff.TransportEpoch <= 0)
            {
                return;
            }

            if (ShouldIgnoreOutboundPostYieldFallbackRecoveryFrameLocked(
                    context,
                    handoff.TransportEpoch,
                    FileTransferProtocol.TransportEpochFrameTypeV6,
                    "peer_handoff_after_fallback_yield"))
            {
                return;
            }

            if (!IsOutboundPeerV6TransportEpochUsableLocked(context, handoff.TransportEpoch) &&
                !TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
                    context,
                    handoff.TransportEpoch,
                    FileTransferProtocol.TransportEpochFrameTypeV6,
                    "peer_handoff_epoch_conflict",
                    context.RemoteNextExpectedChunkIndex,
                    Math.Max(-1, context.ChunksAcceptedForTransport - 1),
                    requireFrontierEvidence: false))
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v6_recovery_frame_ignored; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={FileTransferProtocol.TransportEpochFrameTypeV6}; reason=recovered_epoch; frame_transport_epoch={handoff.TransportEpoch}; last_recovered_transport_epoch={context.LastRecoveredV6TransportHandoffEpoch}");
                return;
            }

            if (context.V6TransportHandoff is null)
            {
                context.V6TransportHandoff = new TransportHandoffEpoch
                {
                    EpochId = handoff.TransportEpoch,
                    Kind = FileTransferTransportHandoffKind.RegularNknRecovery,
                    SourceTransport = FileTransferTransportKind.Unknown,
                    TargetTransport = FileTransferTransportKind.RegularNkn,
                    Direction = FileTransferDirection.Outbound,
                    Reason = "peer_handoff",
                    StartedUtc = DateTimeOffset.UtcNow,
                    StartingCommittedChunkIndex = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount),
                    StartingHighestObservedChunkIndex = Math.Max(-1, context.ChunksAcceptedForTransport - 1),
                    LastObservedCommittedChunkIndex = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount),
                    LastObservedHighestChunkIndex = Math.Max(-1, context.ChunksAcceptedForTransport - 1),
                    State = V6TransportHandoffState.TransportProofPending,
                };
                LogV6TransportHandoffEpochStarted(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    context.V6TransportHandoff);
            }

            if (context.V6TransportHandoff.EpochId != handoff.TransportEpoch &&
                !TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
                    context,
                    handoff.TransportEpoch,
                    FileTransferProtocol.TransportEpochFrameTypeV6,
                    "peer_handoff_epoch_conflict",
                    context.RemoteNextExpectedChunkIndex,
                    Math.Max(-1, context.ChunksAcceptedForTransport - 1),
                    requireFrontierEvidence: false))
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v6_recovery_frame_ignored; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={FileTransferProtocol.TransportEpochFrameTypeV6}; reason=stale_or_mismatched_epoch; frame_transport_epoch={handoff.TransportEpoch}; current_transport_epoch={context.V6TransportHandoff.EpochId}");
                return;
            }

            if (context.V6TransportHandoff.State == V6TransportHandoffState.Recovered)
            {
                return;
            }

            TrySetV6TransportHandoffState(
                context.V6TransportHandoff,
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                V6TransportHandoffState.FrontierRepairOnly,
                "peer_handoff",
                context.RemoteNextExpectedChunkIndex,
                Math.Max(-1, context.ChunksAcceptedForTransport - 1));
        }
    }

    private void ApplyOutboundV6RepairRequest(OutboundTransferContext context, FileTransferFrontierRequestFrameV6 repairRequest)
        => ApplyOutboundV6RepairRequestCore(context, repairRequest, FileTransferTransportKind.Unknown);

    private RetainedPeerProofApplicationResult ApplyOutboundV6RepairRequestCore(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 repairRequest,
        FileTransferTransportKind receivedTransportKind,
        OutboundSparsePumpInstall? receiveInstall = null,
        RuntimeOwnerToken? receiveRuntimeOwner = null,
        IFileTransferDataSession? receiveDataSession = null,
        long receiveDataSessionGeneration = 0,
        long receiveSupervisorGeneration = 0)
    {
        var rawFirstStartChunkIndex = repairRequest.MissingRanges.Count > 0
            ? repairRequest.MissingRanges[0].StartChunkIndex
            : -1;
        var rawFirstChunkCount = repairRequest.MissingRanges.Count > 0
            ? repairRequest.MissingRanges[0].ChunkCount
            : 0;
        if (repairRequest.MissingRanges.Count == 0)
        {
            LogOutboundV6FrontierRequestReceiveDispatch(
                context,
                repairRequest,
                receivedTransportKind,
                "attempted",
                "empty_v6_frontier_request",
                rawFirstStartChunkIndex,
                rawFirstChunkCount,
                repairRequest.MissingRanges.Count);
            LogOutboundV6FrontierRequestReceiveDispatch(
                context,
                repairRequest,
                receivedTransportKind,
                "rejected",
                "empty_v6_frontier_request",
                rawFirstStartChunkIndex,
                rawFirstChunkCount,
                repairRequest.MissingRanges.Count);
            return new RetainedPeerProofApplicationResult(
                RetainedPeerProofApplicationStatus.Rejected,
                "empty_v6_frontier_request");
        }

        var first = repairRequest.MissingRanges[0];
        var syntheticState = new FileTransferReceiverStateFrameV6
        {
            SessionId = repairRequest.SessionId,
            TransferId = repairRequest.TransferId,
            Epoch = Math.Max(0, Environment.TickCount & 0x3fffffff),
            ContiguousCommittedChunkIndex = Math.Max(0, first.StartChunkIndex),
            DurableReceivedHighestChunkIndex = Math.Max(first.StartChunkIndex, first.StartChunkIndex + first.ChunkCount - 1),
            CreditUntilChunkIndexExclusive = Math.Max(first.StartChunkIndex + first.ChunkCount, first.StartChunkIndex + 1),
            MissingRanges = repairRequest.MissingRanges,
            BytesCommitted = 0,
            TransportEpoch = repairRequest.TransportEpoch,
            RepairRequestId = repairRequest.RepairRequestId,
            Priority = repairRequest.Priority,
            RecoveryMode = repairRequest.RecoveryMode,
        };
        FallbackFrontierRepairContract? fallbackFrontierContract = null;
        var fallbackFrontierContractNewlyIssued = false;
        var repairDispatchScheduled = false;
        lock (gate)
        {
            LogOutboundV6FrontierRequestReceiveDispatch(
                context,
                repairRequest,
                receivedTransportKind,
                "attempted",
                "core_receive",
                first.StartChunkIndex,
                first.ChunkCount,
                repairRequest.MissingRanges.Count);
            var receiveAuthorityCurrent = receiveDataSession is null ||
                IsOutboundSparseReceiveResultCurrentLocked(
                    context,
                    receiveInstall,
                    receiveRuntimeOwner,
                    receiveDataSession,
                    receiveDataSessionGeneration,
                    out _);
            if (!receiveAuthorityCurrent &&
                receiveDataSession is not null &&
                receiveSupervisorGeneration > 0 &&
                TryResolveOutboundSparseReceiveDispatchInstallLocked(
                    context,
                    receiveDataSession,
                    receiveDataSessionGeneration,
                    receiveSupervisorGeneration,
                    out var currentDispatchInstall,
                    out var currentDispatchRuntimeOwner,
                    out _))
            {
                receiveInstall = currentDispatchInstall;
                receiveRuntimeOwner = currentDispatchRuntimeOwner;
                receiveAuthorityCurrent = true;
            }

            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                !receiveAuthorityCurrent)
            {
                LogOutboundV6FrontierRequestReceiveDispatch(
                    context,
                    repairRequest,
                    receivedTransportKind,
                    "rejected",
                    context.IsTerminal ? "transfer_terminal" : "stale_outbound_context",
                    first.StartChunkIndex,
                    first.ChunkCount,
                    repairRequest.MissingRanges.Count);
                return new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Rejected,
                    context.IsTerminal ? "transfer_terminal" : "stale_outbound_context");
            }

            // A receive can stay active while a replacement sender stream is being reopened.
            // Preserve the frame, but do not let it mutate repair/frontier state or claim an
            // authoritative Core dispatch until that exact pending descriptor is committed.
            if (receiveInstall is not null &&
                context.PendingOutboundSparsePumpInstall == receiveInstall &&
                context.InstalledOutboundSparsePump != receiveInstall)
            {
                StageOutboundSparseFrontierDispatchProofLocked(
                    context,
                    receiveInstall,
                    repairRequest,
                    receivedTransportKind,
                    first.StartChunkIndex,
                    first.ChunkCount,
                    repairRequest.MissingRanges.Count);
                LogOutboundV6FrontierRequestReceiveDispatch(
                    context,
                    repairRequest,
                    receivedTransportKind,
                    "staged",
                    "pending_sender_install",
                    first.StartChunkIndex,
                    first.ChunkCount,
                    repairRequest.MissingRanges.Count,
                    receiveInstall);
                return new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Held,
                    "pending_sender_install");
            }

            if (IsFallbackFrontierRouteRuntime(context) &&
                !IsStrictFallbackFrontierRuntime(context))
            {
                LogAuthorizedFallbackFrontierReceiveRejected(
                    context,
                    repairRequest,
                    receivedTransportKind,
                    "fallback_runtime_owner_or_leg_missing");
                return new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Rejected,
                    "fallback_runtime_owner_or_leg_missing");
            }

            var strictFallbackFrontierRuntime = IsStrictFallbackFrontierRuntime(context);
            var receivingDataSession = receiveDataSession ?? context.DataSession;
            var receivingDataSessionGeneration = receiveDataSession is null
                ? context.DataSessionGeneration
                : receiveDataSessionGeneration;
            var receivingDataSessionIdentity =
                CreateReceiveRecoveryDataSessionIdentity(
                    context.TransferId,
                    receivingDataSession,
                    receivingDataSessionGeneration);
            var postYieldFallbackTailOwnerRetired =
                IsPostYieldFallbackTailOwnerRetiredAndYieldedLocked(context, context.CurrentTransferLeg);
            if (!strictFallbackFrontierRuntime &&
                ShouldIgnoreOutboundPostYieldFallbackRecoveryFrameLocked(
                    context,
                    repairRequest.TransportEpoch,
                    FileTransferProtocol.FrontierRequestFrameTypeV6,
                    "peer_repair_request_after_fallback_yield"))
            {
                LogOutboundV6FrontierRequestReceiveDispatch(
                    context,
                    repairRequest,
                    receivedTransportKind,
                    "rejected",
                    "peer_repair_request_after_fallback_yield",
                    first.StartChunkIndex,
                    first.ChunkCount,
                    repairRequest.MissingRanges.Count);
                return new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Rejected,
                    "peer_repair_request_after_fallback_yield");
            }

            var allowEpochlessPostTunaFallbackFrontier =
                !strictFallbackFrontierRuntime &&
                IsEpochlessOutboundPostTunaFallbackV6FrontierRequestLocked(context, repairRequest, first);
            if (repairRequest.TransportEpoch <= 0 && !allowEpochlessPostTunaFallbackFrontier)
            {
                LogOutboundV6FrontierRequestReceiveDispatch(
                    context,
                    repairRequest,
                    receivedTransportKind,
                    "rejected",
                    "missing_transport_epoch",
                    first.StartChunkIndex,
                    first.ChunkCount,
                    repairRequest.MissingRanges.Count);
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v6_recovery_frame_ignored; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={FileTransferProtocol.FrontierRequestFrameTypeV6}; reason=missing_transport_epoch; frame_transport_epoch={repairRequest.TransportEpoch}; route={context.RouteSelection.TelemetryToken}; recovery_mode={FormatProtocolLogValue(repairRequest.RecoveryMode ?? "(none)")}; first_start_chunk_index={first.StartChunkIndex}; requested_chunk_count={first.ChunkCount}");
                return new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Rejected,
                    "missing_transport_epoch");
            }

            var isBackfillRequest = string.Equals(repairRequest.Priority, "backfill", StringComparison.OrdinalIgnoreCase);
            var repairReplayKind = IsV6RegularNknFrontierStallMode(repairRequest.RecoveryMode) || allowEpochlessPostTunaFallbackFrontier
                ? RepairReplayKind.FrontierStallRepair
                : RepairReplayKind.V6Repair;
            if (strictFallbackFrontierRuntime)
            {
                if (!TryAcceptOutboundFallbackFrontierRepairLocked(
                        context,
                        repairRequest,
                        receivedTransportKind,
                        receivingDataSessionIdentity,
                        receivingDataSessionGeneration,
                        out fallbackFrontierContract,
                        out _,
                        out var acceptance,
                        out var authorityRejectionReason) ||
                    fallbackFrontierContract is null)
                {
                    if (string.Equals(
                            authorityRejectionReason,
                            "checkpoint_pending_frontier_request_retained",
                            StringComparison.Ordinal) ||
                        string.Equals(
                            authorityRejectionReason,
                            "hold_idempotent",
                            StringComparison.Ordinal))
                    {
                        var idempotent = string.Equals(
                            authorityRejectionReason,
                            "hold_idempotent",
                            StringComparison.Ordinal);
                        LogOutboundV6FrontierRequestReceiveDispatch(
                            context,
                            repairRequest,
                            receivedTransportKind,
                            idempotent ? "coalesced" : "staged",
                            authorityRejectionReason,
                            first.StartChunkIndex,
                            first.ChunkCount,
                            repairRequest.MissingRanges.Count,
                            receiveInstall);
                        return new RetainedPeerProofApplicationResult(
                            idempotent
                                ? RetainedPeerProofApplicationStatus.Idempotent
                                : RetainedPeerProofApplicationStatus.Held,
                            authorityRejectionReason);
                    }

                    LogAuthorizedFallbackFrontierReceiveRejected(
                        context,
                        repairRequest,
                        receivedTransportKind,
                        authorityRejectionReason);
                    return new RetainedPeerProofApplicationResult(
                        RetainedPeerProofApplicationStatus.Rejected,
                        authorityRejectionReason);
                }

                if (acceptance == FallbackFrontierRepairAcceptance.ExactDuplicate)
                {
                    LogAuthorizedFallbackFrontierReceiveCoalesced(
                        context,
                        repairRequest,
                        fallbackFrontierContract,
                        receivedTransportKind,
                        authorityRejectionReason);
                    return new RetainedPeerProofApplicationResult(
                        RetainedPeerProofApplicationStatus.Idempotent,
                        authorityRejectionReason);
                }

                fallbackFrontierContractNewlyIssued =
                    acceptance == FallbackFrontierRepairAcceptance.NewContract;
                if (acceptance == FallbackFrontierRepairAcceptance.ActiveAlias)
                {
                    LogAuthorizedFallbackFrontierReceiveCoalesced(
                        context,
                        repairRequest,
                        fallbackFrontierContract,
                        receivedTransportKind,
                        authorityRejectionReason);
                }
            }
            else if (!TryAuthorizeRepairReplayLocked(
                         context,
                         context.CurrentRuntimeOwner,
                         repairReplayKind,
                         "v6_repair_request",
                         repairRequest.RepairRequestId ?? repairRequest.RecoveryMode ?? "frontier_request",
                         context.CurrentTransferLeg,
                         context.CurrentTransferLeg?.TransportEpochId,
                         context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                         null,
                         out _))
            {
                LogOutboundV6FrontierRequestReceiveDispatch(
                    context,
                    repairRequest,
                    receivedTransportKind,
                    "rejected",
                    "repair_replay_authority_rejected",
                    first.StartChunkIndex,
                    first.ChunkCount,
                    repairRequest.MissingRanges.Count);
                return new RetainedPeerProofApplicationResult(
                    RetainedPeerProofApplicationStatus.Rejected,
                    "repair_replay_authority_rejected");
            }

            if (allowEpochlessPostTunaFallbackFrontier)
            {
                ActivateOutboundV4PostRebindFrontierOnlyRepairLocked(
                    context,
                    Math.Clamp(first.StartChunkIndex, 0, context.ChunkCount),
                    "epochless_post_tuna_frontier_request");
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v6_epochless_post_tuna_fallback_frontier_request_accepted; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; repair_request_id={FormatProtocolLogValue(repairRequest.RepairRequestId ?? "(none)")}; recovery_mode={FormatProtocolLogValue(repairRequest.RecoveryMode ?? "(none)")}; first_start_chunk_index={first.StartChunkIndex}; requested_chunk_count={first.ChunkCount}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; rebind_generation={GetOutboundPostTunaRecoveryGenerationLocked(context)}");
            }
            else
            {
                var coordinatorFallbackTailYieldCurrent =
                    context.CurrentTransferLeg is { } fallbackLeg &&
                    GetCurrentFallbackTailYieldOperation(context) is
                    { Decision: var fallbackTailYieldDecision } &&
                    TryValidateOutboundFallbackTailYieldDecisionLocked(
                        context,
                        fallbackLeg,
                        fallbackTailYieldDecision,
                        out _);
                var suppressLegacyHandoff =
                    postYieldFallbackTailOwnerRetired ||
                    coordinatorFallbackTailYieldCurrent ||
                    ShouldSuppressLegacyV6HandoffForDedicatedV6EpochLocked(
                        context,
                        repairRequest.TransportEpoch);
                if (!suppressLegacyHandoff &&
                    !IsOutboundPeerV6TransportEpochUsableLocked(context, repairRequest.TransportEpoch) &&
                    !TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
                        context,
                        repairRequest.TransportEpoch,
                        FileTransferProtocol.FrontierRequestFrameTypeV6,
                        "peer_repair_request_epoch_conflict",
                        first.StartChunkIndex,
                        first.StartChunkIndex + first.ChunkCount - 1,
                        requireFrontierEvidence: true) &&
                    !TryReopenOutboundRecoveredV6TransportHandoffEpochLocked(
                        context,
                        repairRequest.TransportEpoch,
                        FileTransferProtocol.FrontierRequestFrameTypeV6,
                        "peer_repair_request_after_recovered_epoch",
                        first.StartChunkIndex,
                        first.StartChunkIndex + first.ChunkCount - 1,
                        requireFrontierEvidence: true))
                {
                    LogOutboundV6FrontierRequestReceiveDispatch(
                        context,
                        repairRequest,
                        receivedTransportKind,
                        "rejected",
                        "recovered_epoch",
                        first.StartChunkIndex,
                        first.ChunkCount,
                        repairRequest.MissingRanges.Count);
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v6_recovery_frame_ignored; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={FileTransferProtocol.FrontierRequestFrameTypeV6}; reason=recovered_epoch; frame_transport_epoch={repairRequest.TransportEpoch}; last_recovered_transport_epoch={context.LastRecoveredV6TransportHandoffEpoch}");
                    return new RetainedPeerProofApplicationResult(
                        RetainedPeerProofApplicationStatus.Rejected,
                        "recovered_epoch");
                }

                if (suppressLegacyHandoff)
                {
                    LogLegacyV6HandoffSuppressedForDedicatedV6Epoch(
                        context,
                        repairRequest.TransportEpoch,
                        FileTransferProtocol.FrontierRequestFrameTypeV6,
                        "dedicated_v6_transport_epoch");
                }
                else if (context.V6TransportHandoff is null)
                {
                    context.PullTransportRebindGeneration = Math.Max(context.PullTransportRebindGeneration, (int)Math.Min(int.MaxValue, repairRequest.TransportEpoch));
                    context.V6TransportHandoff = new TransportHandoffEpoch
                    {
                        EpochId = repairRequest.TransportEpoch,
                        Kind = FileTransferTransportHandoffKind.RegularNknRecovery,
                        SourceTransport = FileTransferTransportKind.Unknown,
                        TargetTransport = FileTransferTransportKind.RegularNkn,
                        Direction = FileTransferDirection.Outbound,
                        Reason = "peer_repair_request",
                        StartedUtc = DateTimeOffset.UtcNow,
                        StartingCommittedChunkIndex = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount),
                        StartingHighestObservedChunkIndex = Math.Max(-1, context.ChunksAcceptedForTransport - 1),
                        LastObservedCommittedChunkIndex = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount),
                        LastObservedHighestChunkIndex = Math.Max(-1, context.ChunksAcceptedForTransport - 1),
                        State = V6TransportHandoffState.TransportProofPending,
                    };
                    LogV6TransportHandoffEpochStarted(
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        context.V6TransportHandoff);
                }

                if (!suppressLegacyHandoff &&
                    context.V6TransportHandoff is { } legacyHandoff &&
                    legacyHandoff.EpochId != repairRequest.TransportEpoch)
                {
                    if (!TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
                            context,
                            repairRequest.TransportEpoch,
                            FileTransferProtocol.FrontierRequestFrameTypeV6,
                            "peer_repair_request_epoch_conflict",
                            first.StartChunkIndex,
                            first.StartChunkIndex + first.ChunkCount - 1,
                            requireFrontierEvidence: true))
                    {
                        LogOutboundV6FrontierRequestReceiveDispatch(
                            context,
                            repairRequest,
                            receivedTransportKind,
                            "rejected",
                            "stale_or_mismatched_epoch",
                            first.StartChunkIndex,
                            first.ChunkCount,
                            repairRequest.MissingRanges.Count);
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_v6_recovery_frame_ignored; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; frame_type={FileTransferProtocol.FrontierRequestFrameTypeV6}; reason=stale_or_mismatched_epoch; frame_transport_epoch={repairRequest.TransportEpoch}; current_transport_epoch={context.V6TransportHandoff.EpochId}");
                        return new RetainedPeerProofApplicationResult(
                            RetainedPeerProofApplicationStatus.Rejected,
                            "stale_or_mismatched_epoch");
                    }
                }

                if (!suppressLegacyHandoff)
                {
                    MarkV6TransportHandoffPeerActivity(context.V6TransportHandoff);
                    var requestedState =
                        isBackfillRequest ||
                        string.Equals(repairRequest.RecoveryMode, FormatV6TransportHandoffState(V6TransportHandoffState.BackfillRepair), StringComparison.OrdinalIgnoreCase)
                            ? V6TransportHandoffState.BackfillRepair
                            : V6TransportHandoffState.FrontierRepairOnly;
                    TrySetV6TransportHandoffState(
                        context.V6TransportHandoff,
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        requestedState,
                        "repair_request",
                        context.RemoteNextExpectedChunkIndex,
                        Math.Max(-1, context.ChunksAcceptedForTransport - 1));
                }
            }

            if (!isBackfillRequest)
            {
                AdvanceOutboundV4SparseRemoteFrontierFromV6FrontierRequestLocked(
                    context,
                    repairRequest,
                    first);
            }

            EnqueueAuthorizedV4RepairsFromState(
                context,
                syntheticState,
                fallbackFrontierContract,
                fallbackFrontierContractNewlyIssued,
                dispatchScheduled: out repairDispatchScheduled);
            LogOutboundV6FrontierRequestReceiveDispatch(
                context,
                repairRequest,
                receivedTransportKind,
                repairDispatchScheduled ? "dispatched" : "rejected",
                repairDispatchScheduled
                    ? "queued_for_legacy_sender_repair"
                    : "legacy_sender_repair_not_scheduled",
                first.StartChunkIndex,
                first.ChunkCount,
                repairRequest.MissingRanges.Count,
                receiveInstall);
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v6_frontier_repair_requested; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; transport_epoch={repairRequest.TransportEpoch}; repair_request_id={FormatProtocolLogValue(repairRequest.RepairRequestId ?? "(none)")}; priority={FormatProtocolLogValue(repairRequest.Priority ?? "(none)")}; first_start_chunk_index={first.StartChunkIndex}; requested_chunk_count={first.ChunkCount}; range_count={repairRequest.MissingRanges.Count}");
        }

        return repairDispatchScheduled
            ? new RetainedPeerProofApplicationResult(
                RetainedPeerProofApplicationStatus.Applied,
                "frontier_request_dispatched")
            : new RetainedPeerProofApplicationResult(
                RetainedPeerProofApplicationStatus.Rejected,
                "legacy_sender_repair_not_scheduled");
    }

    private static bool IsEpochlessOutboundPostTunaFallbackV6FrontierRequestLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        FileTransferRangeV4 firstRange)
    {
        if (request.TransportEpoch > 0 ||
            !IsOutboundPostTunaFallbackV6LiveSparseRecoveryActiveLocked(context) ||
            firstRange.StartChunkIndex < 0 ||
            firstRange.StartChunkIndex >= context.ChunkCount)
        {
            return false;
        }

        if (string.Equals(request.Priority, "backfill", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (string.IsNullOrWhiteSpace(request.RecoveryMode))
        {
            return true;
        }

        return IsV6RegularNknFrontierStallMode(request.RecoveryMode) ||
               string.Equals(
                   request.RecoveryMode,
                   FormatV6TransportHandoffState(V6TransportHandoffState.FrontierRepairOnly),
                   StringComparison.OrdinalIgnoreCase);
    }

    private void AdvanceOutboundV4SparseRemoteFrontierFromV6FrontierRequestLocked(
        OutboundTransferContext context,
        FileTransferFrontierRequestFrameV6 request,
        FileTransferRangeV4 firstRange)
    {
        var inferredRemoteFrontier = Math.Clamp(firstRange.StartChunkIndex, 0, context.ChunkCount);
        if (inferredRemoteFrontier <= context.RemoteNextExpectedChunkIndex)
        {
            return;
        }

        var previousRemoteFrontier = context.RemoteNextExpectedChunkIndex;
        context.RemoteNextExpectedChunkIndex = inferredRemoteFrontier;
        context.RemoteGrantedUntilExclusive = Math.Max(context.RemoteGrantedUntilExclusive, context.RemoteNextExpectedChunkIndex);
        context.ChunksTransferred = Math.Max(context.ChunksTransferred, context.RemoteNextExpectedChunkIndex);
        context.BytesTransferred = Math.Max(
            context.BytesTransferred,
            context.RemoteNextExpectedChunkIndex >= context.ChunkCount
                ? context.FileSizeBytes
                : Math.Min(context.FileSizeBytes, (long)context.RemoteNextExpectedChunkIndex * Math.Max(1, context.ChunkSizeBytes)));
        context.BytesAcknowledgedByReceiver = Math.Max(context.BytesAcknowledgedByReceiver, context.BytesTransferred);

        foreach (var chunkIndex in context.SentAwaitingAck.Keys.Where(chunkIndex => chunkIndex < context.RemoteNextExpectedChunkIndex).ToArray())
        {
            context.SentAwaitingAck.Remove(chunkIndex);
        }

        TrimSenderRepairCacheLocked(context, context.RemoteNextExpectedChunkIndex);
        ClearObsoleteOutboundV4RepairWorkAfterFrontierAdvanceLocked(
            context,
            previousRemoteFrontier,
            context.RemoteNextExpectedChunkIndex);
        MaybeReleaseOutboundV6PostTunaFallbackNormalSendAheadFreezeLocked(
            context,
            previousRemoteFrontier,
            "frontier_request_progress");

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v6_frontier_request_advanced_remote_frontier; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; transport_epoch={request.TransportEpoch}; repair_request_id={FormatProtocolLogValue(request.RepairRequestId ?? "(none)")}; previous_remote_frontier_chunk_index={previousRemoteFrontier}; inferred_remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}");
    }

    private void ApplyOutboundV6RepairProof(
        OutboundTransferContext context,
        FileTransferRepairProofFrameV6 repairProof,
        OutboundSparsePumpInstall? receiveInstall = null,
        RuntimeOwnerToken? receiveRuntimeOwner = null,
        IFileTransferDataSession? receiveDataSession = null,
        long receiveDataSessionGeneration = 0)
    {
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                (receiveDataSession is not null &&
                 !IsOutboundSparseReceiveResultCurrentLocked(
                     context,
                     receiveInstall,
                     receiveRuntimeOwner,
                     receiveDataSession,
                     receiveDataSessionGeneration,
                     out _)) ||
                repairProof.TransportEpoch <= 0)
            {
                return;
            }

            if (ShouldIgnoreOutboundPostYieldFallbackRecoveryFrameLocked(
                    context,
                    repairProof.TransportEpoch,
                    FileTransferProtocol.RepairProofFrameTypeV6,
                    "peer_repair_proof_after_fallback_yield"))
            {
                return;
            }

            if (!IsOutboundPeerV6TransportEpochUsableLocked(context, repairProof.TransportEpoch) &&
                !TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
                    context,
                    repairProof.TransportEpoch,
                    FileTransferProtocol.RepairProofFrameTypeV6,
                    "peer_repair_proof_epoch_conflict",
                    repairProof.CommittedChunkIndex,
                    Math.Max(context.ChunksAcceptedForTransport - 1, repairProof.CommittedChunkIndex - 1),
                    requireFrontierEvidence: false))
            {
                return;
            }

            if (context.V6TransportHandoff is null)
            {
                return;
            }

            if (context.V6TransportHandoff.EpochId != repairProof.TransportEpoch &&
                !TryAdoptOutboundPeerV6TransportHandoffEpochLocked(
                    context,
                    repairProof.TransportEpoch,
                    FileTransferProtocol.RepairProofFrameTypeV6,
                    "peer_repair_proof_epoch_conflict",
                    repairProof.CommittedChunkIndex,
                    Math.Max(context.ChunksAcceptedForTransport - 1, repairProof.CommittedChunkIndex - 1),
                    requireFrontierEvidence: false))
            {
                return;
            }

            TrySetV6TransportHandoffState(
                context.V6TransportHandoff,
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                repairProof.CommittedChunkIndex > context.V6TransportHandoff.StartingCommittedChunkIndex
                    ? V6TransportHandoffState.BackfillRepair
                    : V6TransportHandoffState.FrontierRepairOnly,
                "repair_proof",
                repairProof.CommittedChunkIndex,
                Math.Max(context.ChunksAcceptedForTransport - 1, repairProof.CommittedChunkIndex - 1));
        }
    }

    private void LogOutboundV4StateReceivedLocked(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        string stateWireFingerprint,
        int previousEpoch,
        int previousRemoteNext,
        int previousGrant,
        bool applied,
        bool stale,
        bool duplicate)
    {
        var availableCreditChunks = Math.Max(0, context.RemoteGrantedUntilExclusive - context.ChunksAcceptedForTransport);
        var metadataState = state as FileTransferReceiverStateFrameV6;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v4_state_received; transfer_id={context.TransferId}; session_id={context.SessionId}; direction=outbound; route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.CurrentRuntimeOwner?.TerminalGeneration ?? 0}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; transport_epoch={context.CurrentTransferLeg?.TransportEpochId ?? 0}; bridge_recovery_generation={context.CurrentTransferLeg?.BridgeRecoveryGeneration ?? 0}; route_publication_generation={context.CurrentRoutePublicationToken?.PublicationGeneration ?? 0}; route_commit_generation={context.CurrentRoutePublicationToken?.RouteCommitGeneration ?? 0}; data_session_generation={context.DataSessionGeneration}; epoch={state.Epoch}; previous_epoch={previousEpoch}; applied={(applied ? 1 : 0)}; stale={(stale ? 1 : 0)}; duplicate={(duplicate ? 1 : 0)}; v4_state_wire_fingerprint={stateWireFingerprint}; repair_request_id={FormatProtocolLogValue(metadataState?.RepairRequestId ?? "(none)")}; priority={FormatProtocolLogValue(metadataState?.Priority ?? "(none)")}; recovery_mode={FormatProtocolLogValue(metadataState?.RecoveryMode ?? "(none)")}; previous_contiguous_committed_chunk_index={previousRemoteNext}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; previous_credit_until_chunk_index_exclusive={previousGrant}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; effective_credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; available_credit_chunks={availableCreditChunks}; available_credit_bytes={availableCreditChunks * (long)Math.Max(1, context.ChunkSizeBytes)}; missing_range_count={state.MissingRanges.Count}; projected_ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(state.MissingRanges))}; bytes_committed={state.BytesCommitted}; receiver_memory_pressure={(state.ReceiverMemoryPressure ? 1 : 0)}; receiver_disk_pressure={(state.ReceiverDiskPressure ? 1 : 0)}; terminal_ready={(state.TerminalReady ? 1 : 0)}");
        if (IsPrimaryRegularNknFrontierRepairTransactionId(metadataState?.RepairRequestId))
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_primary_regular_nkn_frontier_repair_transaction_received; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; request_id={FormatProtocolLogValue(metadataState?.RepairRequestId)}; epoch={state.Epoch}; applied={(applied ? 1 : 0)}; stale={(stale ? 1 : 0)}; duplicate={(duplicate ? 1 : 0)}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; requested_missing_range_start={(state.MissingRanges.Count == 0 ? -1 : state.MissingRanges[0].StartChunkIndex)}; requested_missing_range_count={(state.MissingRanges.Count == 0 ? 0 : state.MissingRanges[0].ChunkCount)}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}");
        }
    }

    private void ApplyOutboundV4PauseControl(OutboundTransferContext context, FileTransferPauseControlFrameV4 pauseControl)
    {
        SessionFileTransferSnapshot? snapshot = null;
        var receivedEventName = pauseControl is FileTransferPauseControlFrameV6
            ? "filetransfer_v6_pause_control_received"
            : "filetransfer_v4_pause_control_received";
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
            {
                return;
            }

            if (pauseControl.Epoch < context.PeerV4LastPauseControlEpoch)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event={receivedEventName}; transfer_id={context.TransferId}; session_id={context.SessionId}; direction=Outbound; epoch={pauseControl.Epoch}; previous_epoch={context.PeerV4LastPauseControlEpoch}; stale=1; applied=0; peer_paused={(pauseControl.Paused ? 1 : 0)}");
                return;
            }

            var normalizedReason = NormalizeReason(pauseControl.Reason);
            var changed = pauseControl.Paused != context.PeerPaused ||
                !string.Equals(normalizedReason, context.PeerPauseReason, StringComparison.Ordinal);
            if (pauseControl.Epoch == context.PeerV4LastPauseControlEpoch && !changed)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event={receivedEventName}; transfer_id={context.TransferId}; session_id={context.SessionId}; direction=Outbound; epoch={pauseControl.Epoch}; previous_epoch={context.PeerV4LastPauseControlEpoch}; duplicate=1; applied=0; peer_paused={(pauseControl.Paused ? 1 : 0)}");
                return;
            }

            var previousEpoch = context.PeerV4LastPauseControlEpoch;
            context.PeerV4LastPauseControlEpoch = Math.Max(context.PeerV4LastPauseControlEpoch, pauseControl.Epoch);
            context.PeerPaused = pauseControl.Paused;
            context.PeerPauseReason = normalizedReason;
            context.PeerPausedSinceUtc = pauseControl.Paused ? DateTimeOffset.UtcNow : null;
            if (pauseControl.Paused)
            {
                context.ResetV6SenderPipelineCancellation();
            }
            else
            {
                ResetOutboundV4AcceptedForPeerResumeLocked(context);
            }

            context.SparseSenderPumpLastWakeReason = pauseControl.Paused
                ? "peer_pause_control_paused"
                : "peer_pause_control_resumed";
            if (!context.UserPaused)
            {
                context.StatusMessage = context.PeerPaused
                    ? "Peer paused transfer."
                    : GetOutboundResumeStatusMessage(context.State);
            }

            snapshot = CreateSnapshotLocked();
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event={receivedEventName}; transfer_id={context.TransferId}; session_id={context.SessionId}; direction=Outbound; epoch={pauseControl.Epoch}; previous_epoch={previousEpoch}; stale=0; applied=1; peer_paused={(pauseControl.Paused ? 1 : 0)}; pause_reason={FormatProtocolLogValue(normalizedReason ?? "(none)")}");
        }

        if (snapshot is not null)
        {
            RaiseTransferChanged(snapshot);
        }
    }

    private void EnqueueV4RepairsFromState(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state)
        => EnqueueV4RepairsFromReceiveState(
            context,
            state,
            requiredReceiveInstall: null,
            requiredReceiveRuntimeOwner: null,
            requiredReceiveDataSession: null,
            requiredReceiveDataSessionGeneration: 0);

    private void EnqueueV4RepairsFromReceiveState(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        OutboundSparsePumpInstall? requiredReceiveInstall,
        RuntimeOwnerToken? requiredReceiveRuntimeOwner,
        IFileTransferDataSession? requiredReceiveDataSession,
        long requiredReceiveDataSessionGeneration)
        => EnqueueAuthorizedV4RepairsFromState(
            context,
            state,
            fallbackFrontierContract: null,
            fallbackFrontierContractNewlyIssued: false,
            dispatchScheduled: out _,
            requiredReceiveInstall: requiredReceiveInstall,
            requiredReceiveRuntimeOwner: requiredReceiveRuntimeOwner,
            requiredReceiveDataSession: requiredReceiveDataSession,
            requiredReceiveDataSessionGeneration: requiredReceiveDataSessionGeneration);

    private static bool HasExactOutstandingOutboundRegularV4RepairLocked(
        OutboundTransferContext context,
        RepairReplayKind repairKind,
        string repairRequestKey,
        int frontierChunkIndex,
        int durableReceivedHighestChunkIndex,
        int requestedChunkCount,
        out RegularV4FrontierRepairContract? contract,
        out V4SenderRepairRequestState? repairState)
    {
        contract = context.CurrentRegularV4FrontierRepairContract;
        repairState = null;
        if (repairKind != RepairReplayKind.V4Repair ||
            !IsCurrentV4FrontierRepairRuntime(context) ||
            contract is null ||
            contract.Lifecycle.IsSettled ||
            !IsRegularV4FrontierRepairContractCurrent(context, contract, out _) ||
            !string.Equals(contract.Authority.RepairKey, repairRequestKey, StringComparison.Ordinal) ||
            contract.Authority.FrontierChunkIndex != frontierChunkIndex ||
            contract.Authority.DurableReceivedHighestChunkIndex != durableReceivedHighestChunkIndex ||
            contract.Authority.PendingRepairCount != requestedChunkCount ||
            contract.RepairDecision.RepairKind != repairKind ||
            !context.PullV4SenderPumpRepairRequests.TryGetValue(repairRequestKey, out repairState) ||
            !ReferenceEquals(repairState.RegularV4RepairContract, contract))
        {
            return false;
        }

        return repairState.Queued ||
               repairState.InFlight ||
               (contract.Lifecycle.DispatchObserved && contract.DispatchedUtc is not null);
    }

    private static bool TryGetExactPendingOutboundRegularV4InitialPressureInstallLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend candidate,
        RepairReplayKind repairKind,
        out PullV4QueuedRepairSend? pendingRepair,
        out RegularV4FrontierRepairContract? pendingContract)
    {
        pendingContract = context.CurrentRegularV4FrontierRepairContract;
        pendingRepair = pendingContract is null
            ? null
            : CreatePendingRegularV4FrontierRepairSend(context, pendingContract);
        if (context.PendingRegularV4FrontierRepairPressureInstallRetry is not { } executionIdentity ||
            executionIdentity.DataSessionGeneration != context.DataSessionGeneration ||
            pendingRepair is null ||
            pendingContract is null ||
            executionIdentity.AuthorityId != pendingContract.Authority.AuthorityId ||
            !ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, pendingContract) ||
            pendingContract.Lifecycle.IsSettled ||
            pendingContract.Authority.PredecessorAuthorityId is not null ||
            !FileTransferCoordinator.TryGetPendingRegularV4FrontierRepairPressureInstall(
                CreateCoordinatorStateLocked(context),
                pendingContract.Authority.AuthorityId,
                out var pendingBinding,
                out var pendingCommand) ||
            pendingBinding.InstallGeneration != executionIdentity.InstallGeneration ||
            pendingBinding.Authority != pendingContract.Authority ||
            pendingContract.RepairDecision.RepairKind != repairKind ||
            !string.Equals(
                pendingCommand.Pressure.Reason,
                "regular_v4_sender_frontier_repair_due",
                StringComparison.Ordinal) ||
            !string.Equals(pendingRepair.DeliveryEscalationReason, "first_send", StringComparison.Ordinal) ||
            !string.Equals(pendingRepair.RepairRequestKey, candidate.RepairRequestKey, StringComparison.Ordinal) ||
            pendingRepair.RangeCount != candidate.RangeCount ||
            pendingRepair.RequestedChunkCount != candidate.RequestedChunkCount ||
            pendingRepair.FirstStartChunkIndex != candidate.FirstStartChunkIndex ||
            pendingRepair.LastEndChunkExclusive != candidate.LastEndChunkExclusive ||
            pendingRepair.RemoteNextExpectedChunkIndex != candidate.RemoteNextExpectedChunkIndex ||
            pendingRepair.RuntimeOwner != candidate.RuntimeOwner ||
            !pendingRepair.ChunkIndices.SequenceEqual(candidate.ChunkIndices) ||
            !IsRegularV4FrontierRepairContractCurrent(context, pendingContract, out _) ||
            !string.Equals(
                pendingContract.Authority.RepairKey,
                candidate.RepairRequestKey,
                StringComparison.Ordinal) ||
            pendingContract.Authority.FrontierChunkIndex != candidate.RemoteNextExpectedChunkIndex ||
            pendingContract.Authority.PendingRepairCount != candidate.RequestedChunkCount)
        {
            pendingRepair = null;
            pendingContract = null;
            return false;
        }

        return true;
    }

    private void EnqueueAuthorizedV4RepairsFromState(
        OutboundTransferContext context,
        FileTransferStateFrameV4 state,
        FallbackFrontierRepairContract? fallbackFrontierContract,
        bool fallbackFrontierContractNewlyIssued,
        out bool dispatchScheduled,
        OutboundSparsePumpInstall? requiredReceiveInstall = null,
        RuntimeOwnerToken? requiredReceiveRuntimeOwner = null,
        IFileTransferDataSession? requiredReceiveDataSession = null,
        long requiredReceiveDataSessionGeneration = 0)
    {
        dispatchScheduled = false;
        if (requiredReceiveDataSession is not null)
        {
            lock (gate)
            {
                if (!IsOutboundSparseReceiveResultCurrentLocked(
                        context,
                        requiredReceiveInstall,
                        requiredReceiveRuntimeOwner,
                        requiredReceiveDataSession,
                        requiredReceiveDataSessionGeneration,
                        out _))
                {
                    return;
                }
            }
        }

        if (state.MissingRanges.Count == 0)
        {
            return;
        }

        var fileTunaV4PostTunaRecovery = IsOutboundFileTunaV4PostTunaRecoveryActiveLocked(context);
        var maxRepairChunks = fileTunaV4PostTunaRecovery
            ? V4PostFallbackEmergencyFrontierRepairChunks
            : ResolveV4RepairRequestMaxChunksForSend(context, state);
        var normalizedInputRanges = NormalizeV4MissingRangesForSend(state.MissingRanges, context.ChunkCount, maxRepairChunks);
        var postRebindFrontierRepair = HasCurrentOutboundPostTunaFallbackFrontierRepairAuthorityLocked(context) &&
            normalizedInputRanges.Any(range =>
                range.StartChunkIndex <= state.ContiguousCommittedChunkIndex &&
                state.ContiguousCommittedChunkIndex < range.StartChunkIndex + range.ChunkCount);
        if (postRebindFrontierRepair &&
            TrySuppressRetiredFallbackTailOwnerUpdateLocked(
                context,
                context.CurrentTransferLeg,
                "v4_receiver_state_repair",
                "enqueue_frontier_repair",
                "post_yield_receiver_state"))
        {
            return;
        }

        if (fallbackFrontierContract is null && IsStrictFallbackFrontierRuntime(context))
        {
            var retainedAuthority = context.CurrentFallbackFrontierRepairContract?.Authority;
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_fallback_frontier_receiver_state_evidence_only; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(retainedAuthority?.AuthorityId.ToString() ?? "(none)")}; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; live_route_epoch={context.CurrentLiveRouteEpoch?.EpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.CurrentRuntimeOwner?.TerminalGeneration ?? 0}; leg_generation={context.CurrentTransferLeg?.Generation ?? 0}; transport_epoch={(state as FileTransferReceiverStateFrameV6)?.TransportEpoch ?? 0}; bridge_recovery_generation={context.CurrentTransferLeg?.BridgeRecoveryGeneration ?? 0}; checkpoint_request_id={FormatProtocolLogValue(context.CurrentTransferLeg?.CheckpointRequestId ?? "(none)")}; repair_request_id={FormatProtocolLogValue((state as FileTransferReceiverStateFrameV6)?.RepairRequestId ?? "(none)")}; missing_range_count={state.MissingRanges.Count}; decision_reason=receiver_state_cannot_grant_fallback_frontier_authority");
            return;
        }

        var normalizedRanges = SelectV4RepairRangesForSend(
            normalizedInputRanges,
            state.ContiguousCommittedChunkIndex,
            maxRepairChunks,
            frontierExclusive: postRebindFrontierRepair);
        if (fileTunaV4PostTunaRecovery &&
            postRebindFrontierRepair &&
            normalizedRanges.Count > 0)
        {
            normalizedRanges =
            [
                new FileTransferRangeV4
                {
                    StartChunkIndex = state.ContiguousCommittedChunkIndex,
                    ChunkCount = V4PostFallbackEmergencyFrontierRepairChunks,
                },
            ];
        }
        else if (postRebindFrontierRepair &&
            ShouldClampOutboundV6HandoffFrontierRepairRangeForSendLocked(context, state, state.ContiguousCommittedChunkIndex))
        {
            normalizedRanges = ClampV6HandoffFrontierRepairRangesForSend(
                normalizedRanges,
                state.ContiguousCommittedChunkIndex,
                context.ChunkCount);
        }

        if (normalizedRanges.Count == 0)
        {
            return;
        }

        var requestedChunkIndices = new List<int>(maxRepairChunks);
        foreach (var range in normalizedRanges)
        {
            for (var chunkIndex = range.StartChunkIndex;
                 chunkIndex < range.StartChunkIndex + range.ChunkCount &&
                 requestedChunkIndices.Count < maxRepairChunks;
                 chunkIndex++)
            {
                requestedChunkIndices.Add(chunkIndex);
            }
        }

        var requestedChunkCount = normalizedRanges.Sum(static range => range.ChunkCount);
        var firstStart = normalizedRanges[0].StartChunkIndex;
        var lastEndExclusive = normalizedRanges[^1].StartChunkIndex + normalizedRanges[^1].ChunkCount;
        var emergencyCreditRepair = postRebindFrontierRepair &&
            normalizedRanges.Count == 1 &&
            firstStart == state.ContiguousCommittedChunkIndex &&
            requestedChunkCount <= V4PostFallbackEmergencyFrontierRepairChunks;
        var v6BackfillEmergencyCreditRepair = IsOutboundV6BackfillRepairRequestLocked(context, state) &&
            postRebindFrontierRepair &&
            firstStart == state.ContiguousCommittedChunkIndex &&
            lastEndExclusive > firstStart + V4PostFallbackEmergencyFrontierRepairChunks;
        var allowEmergencyCreditRepair = emergencyCreditRepair || v6BackfillEmergencyCreditRepair;
        var emergencyCreditEndExclusive = v6BackfillEmergencyCreditRepair
            ? Math.Min(context.ChunkCount, lastEndExclusive)
            : firstStart + V4PostFallbackEmergencyFrontierRepairChunks;
        var chunkIndices = FilterRepairChunkIndicesForSend(
            context,
            requestedChunkIndices,
            allowEmergencyCreditRepair,
            emergencyCreditEndExclusive,
            out var stats);
        var protocolRepairRequestId = state is FileTransferReceiverStateFrameV6 v6StateForRepair ? v6StateForRepair.RepairRequestId : null;
        var protocolPriority = state is FileTransferReceiverStateFrameV6 v6StateForPriority ? v6StateForPriority.Priority : null;
        var protocolRecoveryMode = state is FileTransferReceiverStateFrameV6 v6StateForRecoveryMode ? v6StateForRecoveryMode.RecoveryMode : null;
        var rangeRepairRequestKey = CreateV4RepairRequestKey(
            context.TransferId,
            firstStart,
            requestedChunkCount,
            state.ContiguousCommittedChunkIndex,
            state.DurableReceivedHighestChunkIndex,
            normalizedRanges);
        var postFallbackExactFrontierRepair =
            postRebindFrontierRepair &&
            !IsOutboundV6BackfillRepairRequestLocked(context, state) &&
            firstStart == state.ContiguousCommittedChunkIndex &&
            requestedChunkCount <= V4PostFallbackEmergencyFrontierRepairChunks;
        var postFallbackCurrentCheckpointRepairWindow =
            postRebindFrontierRepair &&
            state is FileTransferReceiverStateFrameV6 v6CheckpointRepairState &&
            ShouldUseCurrentOutboundFallbackCheckpointRepairWindowLocked(
                context,
                v6CheckpointRepairState,
                state.ContiguousCommittedChunkIndex);
        var useProtocolRepairRequestKey =
            !string.IsNullOrWhiteSpace(protocolRepairRequestId) &&
            !postFallbackExactFrontierRepair &&
            !postFallbackCurrentCheckpointRepairWindow &&
            (ShouldUsePrimaryRegularNknBulkV6RepairProfileLocked(context) &&
                IsPrimaryRegularNknFrontierRepairTransactionId(protocolRepairRequestId) ||
             context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
                IsOutboundPostTunaRecoveryActiveLocked(context) &&
                state is FileTransferReceiverStateFrameV6 { TransportEpoch: > 0 });
        var repairRequestKey = fallbackFrontierContract?.Authority.CanonicalRepairKey ??
            (useProtocolRepairRequestKey
                ? protocolRepairRequestId!
                : rangeRepairRequestKey);
        var frontierRepair = firstStart == state.ContiguousCommittedChunkIndex;
        var frontierTailRepair = normalizedRanges.Count == 1 &&
            firstStart == state.ContiguousCommittedChunkIndex &&
            state.DurableReceivedHighestChunkIndex < state.ContiguousCommittedChunkIndex;
        var queuedRepair = new PullV4QueuedRepairSend(
            chunkIndices,
            normalizedRanges.Count,
            requestedChunkCount,
            firstStart,
            lastEndExclusive,
            stats.RemoteNextExpectedChunkIndex,
            stats.ChunksAcceptedForTransport,
            stats.SkippedObsoleteCount,
            stats.SkippedFutureCount,
            stats.SkippedOutOfBoundsCount,
            repairRequestKey,
            protocolRepairRequestId,
            protocolPriority,
            protocolRecoveryMode,
            frontierRepair,
            frontierTailRepair,
            emergencyCreditRepair,
            FileTransferV4RepairDeliveryMode.BulkOnly,
            "first_send",
            -1,
            RuntimeOwner: context.CurrentRuntimeOwner,
            FallbackFrontierRepairContract: fallbackFrontierContract);

        var scheduleRepairReplayKind = ResolveRepairReplayKind(queuedRepair);
        var shouldLogFallbackFrontierRepairProof = fallbackFrontierContract is null &&
            ShouldLogFallbackFrontierRepairProof(scheduleRepairReplayKind, context.CurrentTransferLeg, repairRequestKey);
        var shouldLogRegularV4FrontierRepairProof =
            ShouldLogRegularV4FrontierRepairProof(scheduleRepairReplayKind, context.CurrentTransferLeg, frontierRepair);
        if (fallbackFrontierContract is null &&
            shouldLogRegularV4FrontierRepairProof &&
            frontierRepair &&
            HasExactOutstandingOutboundRegularV4RepairLocked(
                context,
                scheduleRepairReplayKind,
                repairRequestKey,
                stats.RemoteNextExpectedChunkIndex,
                Math.Max(-1, stats.RemoteNextExpectedChunkIndex - 1),
                requestedChunkCount,
                out var outstandingRegularContract,
                out var outstandingRegularRepairState))
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_repair_suppressed; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(protocolRepairRequestId ?? "(none)")}; reason=current_authority_work_outstanding; epoch={state.Epoch}; range_count={normalizedRanges.Count}; requested_chunk_count={requestedChunkCount}; scheduled_chunk_count=0; first_start_chunk_index={firstStart}; last_end_chunk_exclusive={lastEndExclusive}; frontier_tail_repair={(frontierTailRepair ? 1 : 0)}; remote_next_expected_chunk_index={stats.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={stats.ChunksAcceptedForTransport}; authority_id={FormatProtocolLogValue(outstandingRegularContract!.Authority.AuthorityId.ToString())}; repair_generation={outstandingRegularContract.Authority.DecisionGeneration}; queued={(outstandingRegularRepairState!.Queued ? 1 : 0)}; in_flight={(outstandingRegularRepairState.InFlight ? 1 : 0)}; dispatch_observed={(outstandingRegularContract.Lifecycle.DispatchObserved ? 1 : 0)}; decision_reason=exact_projection_idempotent");
            return;
        }

        RepairReplayDecision? fallbackScheduleDecisionForSettlement = null;
        FileTransferRegularV4FrontierRepairAuthority? regularScheduleAuthorityForSettlement = null;
        RegularV4FrontierRepairContract? regularScheduleContractForSettlement = null;
        RepairReplayDecision? scheduleRepairDecision = null;
        RegularV4FrontierRepairContract? pendingInitialPressureContract = null;
        var hasPendingInitialPressureInstall = fallbackFrontierContract is null &&
            shouldLogRegularV4FrontierRepairProof &&
            TryGetExactPendingOutboundRegularV4InitialPressureInstallLocked(
                context,
                queuedRepair,
                scheduleRepairReplayKind,
                out _,
                out pendingInitialPressureContract);
        if (fallbackFrontierContract is null &&
            !hasPendingInitialPressureInstall &&
            !TryAuthorizeRepairReplayLocked(
                context,
                queuedRepair.RuntimeOwner,
                scheduleRepairReplayKind,
                "v4_repair_schedule",
                repairRequestKey,
                context.CurrentTransferLeg,
                context.CurrentTransferLeg?.TransportEpochId,
                context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                null,
                out scheduleRepairDecision))
        {
            if (shouldLogFallbackFrontierRepairProof)
            {
                LogFileTransferFallbackFrontierRepairAuthorityRejected(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    context.CurrentTransferLeg,
                    repairRequestKey,
                    "v4_repair_schedule",
                    "schedule",
                    "coordinator_authority_rejected",
                    scheduleRepairReplayKind);
            }

            if (shouldLogRegularV4FrontierRepairProof)
            {
                LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    context.CurrentTransferLeg,
                    repairRequestKey,
                    "v4_repair_schedule",
                    "schedule",
                    "coordinator_authority_rejected",
                    stats.RemoteNextExpectedChunkIndex,
                    Math.Max(-1, stats.RemoteNextExpectedChunkIndex - 1),
                    requestedChunkCount);
            }

            return;
        }

        if (scheduleRepairDecision is { } scheduleDecision &&
            shouldLogFallbackFrontierRepairProof)
        {
            fallbackScheduleDecisionForSettlement = scheduleDecision;
            LogFileTransferFallbackFrontierRepairAuthorityGranted(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                scheduleDecision,
                context.CurrentTransferLeg,
                repairRequestKey,
                "v4_repair_schedule",
                "schedule",
                normalizedRanges.Count,
                requestedChunkCount,
                chunkIndices.Count);
        }

        if (hasPendingInitialPressureInstall &&
            pendingInitialPressureContract is { } retainedInitialPressureContract)
        {
            if (!TryRetryRegularV4FrontierRepairPressureInstallLocked(
                    context,
                    retainedInitialPressureContract))
            {
                return;
            }

            regularScheduleContractForSettlement = retainedInitialPressureContract;
            regularScheduleAuthorityForSettlement = retainedInitialPressureContract.Authority;
            queuedRepair = queuedRepair with { RegularV4RepairContract = retainedInitialPressureContract };
            context.PendingRegularV4FrontierRepairPressureInstallRetry = null;
            LogFileTransferRegularV4FrontierRepairAuthorityGranted(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                retainedInitialPressureContract.Authority,
                "v4_repair_schedule",
                "schedule",
                normalizedRanges.Count,
                requestedChunkCount,
                chunkIndices.Count,
                GetRegularV4FrontierRepairPressureInstallGeneration(
                    CreateCoordinatorStateLocked(context),
                    retainedInitialPressureContract),
                firstStart,
                lastEndExclusive,
                "attached_installed_contract");
        }
        else if (scheduleRepairDecision is { } regularScheduleDecision &&
            shouldLogRegularV4FrontierRepairProof)
        {
            var regularContract = CreateRegularV4FrontierRepairContract(
                context,
                regularScheduleDecision,
                repairRequestKey,
                stats.RemoteNextExpectedChunkIndex,
                Math.Max(-1, stats.RemoteNextExpectedChunkIndex - 1),
                requestedChunkCount,
                regularScheduleDecision.Reason,
                "regular_v4_sender_frontier_repair_due",
                out var regularContractRejectionReason);
            if (regularContract is { } contract)
            {
                var authority = contract.Authority;
                context.CurrentRegularV4FrontierRepairContract = contract;
                var pendingQueuedRepair = queuedRepair with { RegularV4RepairContract = contract };
                if (!TryBindRegularV4FrontierRepairScheduledDispatch(
                        contract,
                        pendingQueuedRepair,
                        scheduleRepairReplayKind,
                        out _))
                {
                    return;
                }
                if (!TryInstallRegularV4FrontierRepairPressureLocked(
                        context,
                        contract,
                        predecessorContract: null,
                        Math.Max(0, stats.ChunksAcceptedForTransport - stats.RemoteNextExpectedChunkIndex),
                        Math.Max(1, requestedChunkCount),
                        "regular_v4_sender_frontier_repair_due",
                        "outbound_repair_schedule_initial"))
                {
                    _ = RetainPendingRegularV4FrontierRepairPressureInstallRetry(
                        context,
                        contract);
                    return;
                }
                regularScheduleContractForSettlement = contract;
                regularScheduleAuthorityForSettlement = authority;
                LogFileTransferRegularV4FrontierRepairAuthorityGranted(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    authority,
                    "v4_repair_schedule",
                    "schedule",
                    normalizedRanges.Count,
                    requestedChunkCount,
                    chunkIndices.Count,
                    GetRegularV4FrontierRepairPressureInstallGeneration(
                        CreateCoordinatorStateLocked(context),
                        contract),
                    firstStart,
                    lastEndExclusive,
                    "attached_installed_contract");
            }
            else
            {
                LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    context.CurrentTransferLeg,
                    repairRequestKey,
                    "v4_repair_schedule",
                    "schedule",
                    regularContractRejectionReason,
                    stats.RemoteNextExpectedChunkIndex,
                    Math.Max(-1, stats.RemoteNextExpectedChunkIndex - 1),
                    requestedChunkCount);
                return;
            }
        }

        if (regularScheduleContractForSettlement is { } scheduledContract)
        {
            queuedRepair = queuedRepair with { RegularV4RepairContract = scheduledContract };
        }

        if (chunkIndices.Count == 0)
        {
            if (fallbackFrontierContractNewlyIssued)
            {
                TrySettleFallbackFrontierRepairContract(
                    fallbackFrontierContract,
                    FallbackFrontierRepairSettlementOutcome.MissingDispatch,
                    "no_schedulable_repair_chunks");
            }

            if (shouldLogFallbackFrontierRepairProof)
            {
                LogFileTransferFallbackFrontierRepairStalled(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    context.CurrentTransferLeg,
                    repairRequestKey,
                    "no_schedulable_repair_chunks",
                    firstStart,
                    state.DurableReceivedHighestChunkIndex,
                    requestedChunkCount,
                    1,
                    0);
            }

            if (shouldLogRegularV4FrontierRepairProof)
            {
                LogFileTransferRegularV4FrontierRepairStalled(
                    FileTransferDirection.Outbound,
                    context.TransferId,
                    context.SessionId,
                    context.CurrentTransferLeg,
                    repairRequestKey,
                    "no_schedulable_repair_chunks",
                    stats.RemoteNextExpectedChunkIndex,
                    Math.Max(-1, stats.RemoteNextExpectedChunkIndex - 1),
                    requestedChunkCount,
                    1,
                    0);
            }

            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_repair_scheduled; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(protocolRepairRequestId ?? "(none)")}; epoch={state.Epoch}; range_count={normalizedRanges.Count}; requested_chunk_count={requestedChunkCount}; scheduled_chunk_count=0; scheduled_chunk_indices=(none); first_start_chunk_index={firstStart}; last_end_chunk_exclusive={lastEndExclusive}; frontier_tail_repair={(frontierTailRepair ? 1 : 0)}; post_rebind_frontier_exclusive={(postRebindFrontierRepair ? 1 : 0)}; credit_exhausted_time_ms_at_repair=-1; remote_next_expected_chunk_index={stats.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={stats.ChunksAcceptedForTransport}; skipped_obsolete_count={stats.SkippedObsoleteCount}; skipped_future_count={stats.SkippedFutureCount}; skipped_out_of_bounds_count={stats.SkippedOutOfBoundsCount}");
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_repair_sent; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(protocolRepairRequestId ?? "(none)")}; range_count={queuedRepair.RangeCount}; requested_chunk_count={queuedRepair.RequestedChunkCount}; sent_chunk_count=0; sent_chunk_indices=(none); repair_delivery_mode=bulk_only; repair_delivery_escalation_reason=no_chunks; first_start_chunk_index={queuedRepair.FirstStartChunkIndex}; last_end_chunk_exclusive={queuedRepair.LastEndChunkExclusive}; frontier_tail_repair={(queuedRepair.FrontierTailRepair ? 1 : 0)}; post_rebind_frontier_exclusive={(postRebindFrontierRepair ? 1 : 0)}; credit_exhausted_time_ms_at_repair=-1; remote_next_expected_chunk_index={queuedRepair.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={queuedRepair.ChunksAcceptedForTransport}; skipped_obsolete_count={queuedRepair.SkippedObsoleteCount}; skipped_future_count={queuedRepair.SkippedFutureCount}; skipped_out_of_bounds_count={queuedRepair.SkippedOutOfBoundsCount}; receiver_proof_status=not_applicable{FormatV4DataPathAuthoritySuffix(context, "filetransfer_v4_repair_sent_no_chunks")}");
            return;
        }

        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
            {
                if (fallbackFrontierContractNewlyIssued)
                {
                    TrySettleFallbackFrontierRepairContract(
                        fallbackFrontierContract,
                        context.IsTerminal
                            ? FallbackFrontierRepairSettlementOutcome.TerminalRejected
                            : FallbackFrontierRepairSettlementOutcome.StaleRejected,
                        context.IsTerminal ? "queue_after_terminal" : "queue_for_stale_context");
                }

                return;
            }

            if (requiredReceiveDataSession is not null &&
                !IsOutboundSparseReceiveResultCurrentLocked(
                    context,
                    requiredReceiveInstall,
                    requiredReceiveRuntimeOwner,
                    requiredReceiveDataSession,
                    requiredReceiveDataSessionGeneration,
                    out _))
            {
                return;
            }

            if (fallbackFrontierContract is not null &&
                !TryValidateOutboundFallbackFrontierDispatchLocked(
                    context,
                    fallbackFrontierContract,
                    out var fallbackContractRejectionReason))
            {
                TrySettleFallbackFrontierRepairContract(
                    fallbackFrontierContract,
                    FallbackFrontierRepairSettlementOutcome.StaleRejected,
                    fallbackContractRejectionReason);
                return;
            }

            if (state is FileTransferReceiverStateFrameV6 v6StateForEpochRepair &&
                v6StateForEpochRepair.TransportEpoch > 0)
            {
                MarkOutboundV6EpochRepairRequestPendingLocked(
                    context,
                    v6StateForEpochRepair.TransportEpoch,
                    protocolRepairRequestId ?? repairRequestKey,
                    "v4_sparse_receiver_state");
            }

            if (postRebindFrontierRepair)
            {
                ActivateOutboundV4PostRebindFrontierOnlyRepairLocked(
                    context,
                    state.ContiguousCommittedChunkIndex,
                    "missing_frontier_state");
                if (requestedChunkCount == V4PostFallbackEmergencyFrontierRepairChunks &&
                    IsOutboundPostFallbackExactFrontierRepairRequiredLocked(context, state.ContiguousCommittedChunkIndex))
                {
                    LocalOperationalLog.Warn(
                        "FileTransferService",
                        $"event=filetransfer_v6_exact_frontier_repair_enqueued; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; transport_epoch={context.V6TransportHandoff?.EpochId ?? context.PullTransportRebindGeneration}; state={FormatV6TransportHandoffState(context.V6TransportHandoff?.State ?? V6TransportHandoffState.FrontierRepairOnly)}; frontier_chunk_index={state.ContiguousCommittedChunkIndex}; repair_request_key={repairRequestKey}; source_state_missing_range_count={state.MissingRanges.Count}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}");
                }
            }
            CleanupOutboundV4RepairRequestStateLocked(context, DateTimeOffset.UtcNow);
            var now = DateTimeOffset.UtcNow;
            var senderRepairRepeatIntervalMs = ResolveV4SenderRepairRepeatIntervalMs(context, frontierRepair);
            if (!TryMarkOutboundV4RepairQueuedLocked(context, repairRequestKey, now, senderRepairRepeatIntervalMs, out var repairState, out var suppressionReason, out var lastSentAgeMs))
            {
                if (fallbackFrontierContractNewlyIssued)
                {
                    TrySettleFallbackFrontierRepairContract(
                        fallbackFrontierContract,
                        FallbackFrontierRepairSettlementOutcome.MissingDispatch,
                        $"repair_queue_suppressed_{suppressionReason}");
                }

                if (shouldLogFallbackFrontierRepairProof &&
                    fallbackScheduleDecisionForSettlement is not null)
                {
                    LogFileTransferFallbackFrontierRepairStalled(
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        context.CurrentTransferLeg,
                        repairRequestKey,
                        $"repair_queue_suppressed_{suppressionReason}",
                        firstStart,
                        state.DurableReceivedHighestChunkIndex,
                        requestedChunkCount,
                        repairState.SuppressedCount,
                        lastSentAgeMs);
                }

                if (shouldLogRegularV4FrontierRepairProof &&
                    regularScheduleAuthorityForSettlement is { } regularSuppressedAuthority)
                {
                    LogFileTransferRegularV4FrontierRepairMissingDispatch(
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        regularSuppressedAuthority,
                        protocolRepairRequestId ?? "(none)",
                        "schedule",
                        chunkIndices.Count,
                        stats.RemoteNextExpectedChunkIndex,
                        stats.ChunksAcceptedForTransport,
                        $"repair_queue_suppressed_{suppressionReason}");
                    ObserveRegularV4FrontierRepairDispatchBlocker(
                        context,
                        regularSuppressedAuthority,
                        requestedChunkCount,
                        "regular_v4_frontier_repair_missing_dispatch");
                    TrySettleRegularV4FrontierRepairContract(
                        regularScheduleContractForSettlement,
                        FileTransferRegularV4FrontierRepairSettlementOutcome.MissingDispatch,
                        requestedChunkCount,
                        "regular_v4_frontier_repair_missing_dispatch");
                }

                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v4_repair_suppressed; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(protocolRepairRequestId ?? "(none)")}; reason={suppressionReason}; epoch={state.Epoch}; range_count={normalizedRanges.Count}; requested_chunk_count={requestedChunkCount}; scheduled_chunk_count={chunkIndices.Count}; first_start_chunk_index={firstStart}; last_end_chunk_exclusive={lastEndExclusive}; frontier_tail_repair={(frontierTailRepair ? 1 : 0)}; last_sent_age_ms={lastSentAgeMs}; repair_interval_ms={senderRepairRepeatIntervalMs}; remote_next_expected_chunk_index={stats.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={stats.ChunksAcceptedForTransport}");
                return;
            }

            repairState.FallbackFrontierRepairContract = fallbackFrontierContract;
            if (regularScheduleContractForSettlement is not null)
            {
                repairState.RegularV4RepairContract = regularScheduleContractForSettlement;
            }

            var deliveryDecision = ResolveV4RepairDeliveryDecisionLocked(context, repairState, stats.RemoteNextExpectedChunkIndex, frontierRepair, now);
            var deduped = new List<int>(chunkIndices.Count);
            foreach (var chunkIndex in chunkIndices)
            {
                if (context.PullV4SenderPumpRepairQueuedChunkIndices.Add(chunkIndex))
                {
                    deduped.Add(chunkIndex);
                }
            }

            if (deduped.Count == 0)
            {
                var successorQueuedRepair = queuedRepair with
                {
                    DeliveryMode = deliveryDecision.Mode,
                    DeliveryEscalationReason = deliveryDecision.Reason,
                    CreditExhaustedTimeMsAtDecision = deliveryDecision.CreditExhaustedTimeMs,
                };
                if (fallbackFrontierContractNewlyIssued &&
                    fallbackFrontierContract is not null &&
                    TryTransferQueuedOutboundFallbackFrontierRepairToSuccessorLocked(
                        context,
                        successorQueuedRepair,
                        fallbackFrontierContract,
                        repairState,
                        chunkIndices,
                        out var transferredChunkCount))
                {
                    dispatchScheduled = true;
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v4_repair_scheduled; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(protocolRepairRequestId ?? "(none)")}; epoch={state.Epoch}; range_count={normalizedRanges.Count}; requested_chunk_count={requestedChunkCount}; scheduled_chunk_count={transferredChunkCount}; scheduled_chunk_indices={FormatV4ChunkIndicesForLog(chunkIndices)}; repair_delivery_mode={FormatV4RepairDeliveryMode(deliveryDecision.Mode)}; repair_delivery_escalation_reason=queued_predecessor_rebound; first_start_chunk_index={firstStart}; last_end_chunk_exclusive={lastEndExclusive}; frontier_tail_repair={(frontierTailRepair ? 1 : 0)}; post_rebind_frontier_exclusive={(postRebindFrontierRepair ? 1 : 0)}; credit_exhausted_time_ms_at_repair={deliveryDecision.CreditExhaustedTimeMs}; remote_next_expected_chunk_index={stats.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={stats.ChunksAcceptedForTransport}; skipped_obsolete_count={stats.SkippedObsoleteCount}; skipped_future_count={stats.SkippedFutureCount}; skipped_out_of_bounds_count={stats.SkippedOutOfBoundsCount}");
                    context.SignalSparseSenderPump();
                    return;
                }

                if (context.PullV4SenderPumpRepairRequests.TryGetValue(repairRequestKey, out var queuedState))
                {
                    queuedState.Queued = false;
                    queuedState.QueuedUtc = null;
                }

                if (fallbackFrontierContractNewlyIssued)
                {
                    TrySettleFallbackFrontierRepairContract(
                        fallbackFrontierContract,
                        FallbackFrontierRepairSettlementOutcome.MissingDispatch,
                        "chunks_already_queued_before_dispatch");
                }

                if (shouldLogFallbackFrontierRepairProof &&
                    fallbackScheduleDecisionForSettlement is not null)
                {
                    LogFileTransferFallbackFrontierRepairStalled(
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        context.CurrentTransferLeg,
                        repairRequestKey,
                        "chunks_already_queued_before_dispatch",
                        firstStart,
                        state.DurableReceivedHighestChunkIndex,
                        requestedChunkCount,
                        1,
                        0);
                }

                if (shouldLogRegularV4FrontierRepairProof &&
                    regularScheduleAuthorityForSettlement is { } regularDedupedAuthority)
                {
                    LogFileTransferRegularV4FrontierRepairMissingDispatch(
                        FileTransferDirection.Outbound,
                        context.TransferId,
                        context.SessionId,
                        regularDedupedAuthority,
                        protocolRepairRequestId ?? "(none)",
                        "schedule",
                        0,
                        stats.RemoteNextExpectedChunkIndex,
                        stats.ChunksAcceptedForTransport,
                        "chunks_already_queued");
                    ObserveRegularV4FrontierRepairDispatchBlocker(
                        context,
                        regularDedupedAuthority,
                        requestedChunkCount,
                        "regular_v4_frontier_repair_missing_dispatch");
                    TrySettleRegularV4FrontierRepairContract(
                        regularScheduleContractForSettlement,
                        FileTransferRegularV4FrontierRepairSettlementOutcome.MissingDispatch,
                        requestedChunkCount,
                        "regular_v4_frontier_repair_missing_dispatch");
                }

                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v4_repair_suppressed; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(protocolRepairRequestId ?? "(none)")}; reason=chunks_already_queued; epoch={state.Epoch}; range_count={normalizedRanges.Count}; requested_chunk_count={requestedChunkCount}; scheduled_chunk_count=0; first_start_chunk_index={firstStart}; last_end_chunk_exclusive={lastEndExclusive}; frontier_tail_repair={(frontierTailRepair ? 1 : 0)}; last_sent_age_ms=-1; remote_next_expected_chunk_index={stats.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={stats.ChunksAcceptedForTransport}");
                return;
            }

            var availableCreditChunks = Math.Max(
                0,
                Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount) - context.ChunksAcceptedForTransport);
            MaybeObserveRegularV4ControlFeedbackPressure(
                context,
                deliveryDecision.CreditExhaustedTimeMs,
                availableCreditChunks,
                deduped.Count);

            if (allowEmergencyCreditRepair)
            {
                var emergencyEndExclusive = Math.Min(context.ChunkCount, deduped.Max() + 1);
                if (emergencyEndExclusive > context.ChunksAcceptedForTransport)
                {
                    var previousAccepted = context.ChunksAcceptedForTransport;
                    context.ChunksAcceptedForTransport = emergencyEndExclusive;
                    context.BytesAcceptedForTransport = context.ChunksAcceptedForTransport >= context.ChunkCount
                        ? context.FileSizeBytes
                        : Math.Min(context.FileSizeBytes, (long)context.ChunksAcceptedForTransport * Math.Max(1, context.ChunkSizeBytes));
                    var eventName = v6BackfillEmergencyCreditRepair
                        ? "filetransfer_v6_backfill_repair_credit_granted"
                        : "filetransfer_v4_emergency_frontier_credit_granted";
                    var reason = v6BackfillEmergencyCreditRepair
                        ? "post_fallback_backfill_repair"
                        : "post_fallback_missing_frontier";
                    LocalOperationalLog.Warn(
                        "FileTransferService",
                        $"event={eventName}; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={reason}; rebind_generation={context.PullTransportRebindGeneration}; previous_chunks_accepted_for_transport={previousAccepted}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; emergency_start_chunk_index={firstStart}; emergency_end_chunk_exclusive={emergencyEndExclusive}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; remote_credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; transport_epoch={context.V6TransportHandoff?.EpochId ?? 0}");
                }
            }

            var finalizedQueuedRepair = queuedRepair with
            {
                ChunkIndices = deduped,
                DeliveryMode = deliveryDecision.Mode,
                DeliveryEscalationReason = deliveryDecision.Reason,
                CreditExhaustedTimeMsAtDecision = deliveryDecision.CreditExhaustedTimeMs,
            };
            if (regularScheduleContractForSettlement is { } finalizedRegularContract &&
                !TryBindRegularV4FrontierRepairScheduledDispatch(
                    finalizedRegularContract,
                    finalizedQueuedRepair,
                    ResolveRepairReplayKind(finalizedQueuedRepair),
                    out var scheduledDispatchRejectionReason))
            {
                TrySettleRegularV4FrontierRepairContract(
                    finalizedRegularContract,
                    FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
                    finalizedQueuedRepair.RequestedChunkCount,
                    scheduledDispatchRejectionReason);
                return;
            }

            context.PullV4SenderPumpRepairQueue.Enqueue(finalizedQueuedRepair);
            dispatchScheduled = true;
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_repair_scheduled; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; protocol_repair_request_id={FormatProtocolLogValue(protocolRepairRequestId ?? "(none)")}; epoch={state.Epoch}; range_count={normalizedRanges.Count}; requested_chunk_count={requestedChunkCount}; scheduled_chunk_count={deduped.Count}; scheduled_chunk_indices={FormatV4ChunkIndicesForLog(deduped)}; repair_delivery_mode={FormatV4RepairDeliveryMode(deliveryDecision.Mode)}; repair_delivery_escalation_reason={deliveryDecision.Reason}; first_start_chunk_index={firstStart}; last_end_chunk_exclusive={lastEndExclusive}; frontier_tail_repair={(frontierTailRepair ? 1 : 0)}; post_rebind_frontier_exclusive={(postRebindFrontierRepair ? 1 : 0)}; credit_exhausted_time_ms_at_repair={deliveryDecision.CreditExhaustedTimeMs}; remote_next_expected_chunk_index={stats.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={stats.ChunksAcceptedForTransport}; skipped_obsolete_count={stats.SkippedObsoleteCount}; skipped_future_count={stats.SkippedFutureCount}; skipped_out_of_bounds_count={stats.SkippedOutOfBoundsCount}");
            context.SignalSparseSenderPump();
        }
    }

    private static bool TryTransferQueuedOutboundFallbackFrontierRepairToSuccessorLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend successorTemplate,
        FallbackFrontierRepairContract successor,
        V4SenderRepairRequestState successorState,
        IReadOnlyCollection<int> requestedChunkIndices,
        out int transferredChunkCount)
    {
        transferredChunkCount = 0;
        var successorAuthority = successor.Authority;
        if (requestedChunkIndices.Count == 0 ||
            successorAuthority.PredecessorAuthorityId is not { IsDefault: false } predecessorAuthorityId ||
            !ReferenceEquals(context.CurrentFallbackFrontierRepairContract, successor) ||
            successor.Lifecycle.IsSettled ||
            !IsFallbackFrontierRepairContractCurrent(context, successor, out _))
        {
            return false;
        }

        var requestedChunks = requestedChunkIndices.ToHashSet();
        PullV4QueuedRepairSend? predecessorSend = null;
        V4SenderRepairRequestState? predecessorState = null;
        foreach (var candidate in context.PullV4SenderPumpRepairQueue)
        {
            if (candidate.FallbackFrontierRepairContract is not { } predecessor ||
                predecessor.Authority.AuthorityId != predecessorAuthorityId ||
                predecessor.Lifecycle.SettlementOutcome != FallbackFrontierRepairSettlementOutcome.Superseded ||
                predecessor.Lifecycle.SuccessorAuthorityId != successorAuthority.AuthorityId ||
                !HasSameFallbackFrontierRepairDispatchScope(predecessor.Authority, successorAuthority) ||
                !candidate.ChunkIndices.Any(requestedChunks.Contains) ||
                !context.PullV4SenderPumpRepairRequests.TryGetValue(candidate.RepairRequestKey, out var candidateState) ||
                !candidateState.Queued ||
                candidateState.InFlight ||
                !ReferenceEquals(candidateState.FallbackFrontierRepairContract, predecessor))
            {
                continue;
            }

            if (predecessorSend is not null)
            {
                return false;
            }

            predecessorSend = candidate;
            predecessorState = candidateState;
        }

        if (predecessorSend is null || predecessorState is null)
        {
            return false;
        }

        var transferredChunks = predecessorSend.ChunkIndices
            .Where(requestedChunks.Contains)
            .Distinct()
            .OrderBy(static chunkIndex => chunkIndex)
            .ToList();
        if (transferredChunks.Count != requestedChunks.Count)
        {
            return false;
        }

        var retained = new Queue<PullV4QueuedRepairSend>(context.PullV4SenderPumpRepairQueue.Count);
        while (context.PullV4SenderPumpRepairQueue.Count > 0)
        {
            var queued = context.PullV4SenderPumpRepairQueue.Dequeue();
            if (!ReferenceEquals(queued, predecessorSend))
            {
                retained.Enqueue(queued);
                continue;
            }

            foreach (var chunkIndex in queued.ChunkIndices)
            {
                context.PullV4SenderPumpRepairQueuedChunkIndices.Remove(chunkIndex);
            }

            foreach (var chunkIndex in transferredChunks)
            {
                context.PullV4SenderPumpRepairQueuedChunkIndices.Add(chunkIndex);
            }

            retained.Enqueue(successorTemplate with
            {
                ChunkIndices = transferredChunks,
                RepairRequestKey = successorAuthority.CanonicalRepairKey,
                ProtocolRepairRequestId = successorAuthority.ProtocolRepairRequestId,
                ProtocolPriority = successorAuthority.Priority,
                ProtocolRecoveryMode = successorAuthority.RecoveryMode,
                RuntimeOwner = successorAuthority.RuntimeOwner,
                FallbackFrontierRepairContract = successor,
            });
        }

        while (retained.Count > 0)
        {
            context.PullV4SenderPumpRepairQueue.Enqueue(retained.Dequeue());
        }

        predecessorState.Queued = false;
        predecessorState.QueuedUtc = null;
        successorState.Queued = true;
        successorState.QueuedUtc ??= DateTimeOffset.UtcNow;
        successorState.InFlight = false;
        successorState.FallbackFrontierRepairContract = successor;
        transferredChunkCount = transferredChunks.Count;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_fallback_frontier_repair_successor_dispatch_handoff_decided; {FormatFallbackFrontierRepairAuthorityTuple(successorAuthority)}; predecessor_authority_id={FormatProtocolLogValue(predecessorAuthorityId.ToString())}; predecessor_repair_request_key={FormatProtocolLogValue(predecessorSend.RepairRequestKey)}; predecessor_protocol_repair_request_id={FormatProtocolLogValue(predecessorSend.ProtocolRepairRequestId ?? "(none)")}; successor_repair_request_key={FormatProtocolLogValue(successorAuthority.CanonicalRepairKey)}; successor_protocol_repair_request_id={FormatProtocolLogValue(successorAuthority.ProtocolRepairRequestId)}; transferred_chunk_count={transferredChunkCount}; transferred_chunk_indices={FormatV4ChunkIndicesForLog(transferredChunks)}; result=queued_predecessor_rebound; authority_effect=none; decision_reason=exact_queued_predecessor_dispatch_transferred");
        return true;
    }

    private static bool HasSameFallbackFrontierRepairDispatchScope(
        FallbackFrontierRepairAuthority predecessor,
        FallbackFrontierRepairAuthority successor)
        => string.Equals(predecessor.SessionId, successor.SessionId, StringComparison.Ordinal) &&
           string.Equals(predecessor.TransferId, successor.TransferId, StringComparison.Ordinal) &&
           predecessor.Direction == successor.Direction &&
           predecessor.RuntimeOwner == successor.RuntimeOwner &&
           predecessor.Route == successor.Route &&
           string.Equals(predecessor.RouteToken, successor.RouteToken, StringComparison.Ordinal) &&
           predecessor.ProtocolVersion == successor.ProtocolVersion &&
           predecessor.LiveRouteEpoch == successor.LiveRouteEpoch &&
           predecessor.RuntimeGeneration == successor.RuntimeGeneration &&
           predecessor.TerminalGeneration == successor.TerminalGeneration &&
           predecessor.LegGeneration == successor.LegGeneration &&
           predecessor.TransportEpoch == successor.TransportEpoch &&
           predecessor.BridgeRecoveryGeneration == successor.BridgeRecoveryGeneration &&
           predecessor.BridgeDecisionGeneration == successor.BridgeDecisionGeneration &&
           predecessor.RoutePublicationGeneration == successor.RoutePublicationGeneration &&
           predecessor.RouteCommitGeneration == successor.RouteCommitGeneration &&
           string.Equals(predecessor.CheckpointRequestId, successor.CheckpointRequestId, StringComparison.Ordinal) &&
           predecessor.FrontierChunkIndex == successor.FrontierChunkIndex &&
           predecessor.TargetTransport == successor.TargetTransport;

    private static void CleanupOutboundV4RepairRequestStateLocked(OutboundTransferContext context, DateTimeOffset now)
    {
        foreach (var key in context.PullV4SenderPumpRepairRequests.Keys.ToArray())
        {
            var repairState = context.PullV4SenderPumpRepairRequests[key];
            if (repairState.Queued || repairState.InFlight)
            {
                continue;
            }

            if (repairState.LastSentUtc is null ||
                now - repairState.LastSentUtc.Value >= TimeSpan.FromMilliseconds(V4RepairRequestHistoryRetentionMs))
            {
                context.PullV4SenderPumpRepairRequests.Remove(key);
            }
        }
    }

    private static void MarkOutboundV4QueuedRepairSuppressedLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend queuedRepair)
    {
        foreach (var chunkIndex in queuedRepair.ChunkIndices)
        {
            context.PullV4SenderPumpRepairQueuedChunkIndices.Remove(chunkIndex);
        }

        if (context.PullV4SenderPumpRepairRequests.TryGetValue(queuedRepair.RepairRequestKey, out var repairState) &&
            (queuedRepair.FallbackFrontierRepairContract is null ||
             ReferenceEquals(
                 repairState.FallbackFrontierRepairContract,
                 queuedRepair.FallbackFrontierRepairContract)))
        {
            repairState.Queued = false;
            repairState.QueuedUtc = null;
            repairState.InFlight = false;
            repairState.SuppressedCount++;
        }
    }

    private static RepairReplayKind ResolveRepairReplayKind(PullV4QueuedRepairSend queuedRepair)
    {
        if (queuedRepair.CoordinatorBackedRegularV4PeerSilenceReplay ||
            string.Equals(queuedRepair.DeliveryEscalationReason, "regular_v4_peer_silence_safety_replay", StringComparison.Ordinal))
        {
            return RepairReplayKind.PeerSilenceReplay;
        }

        if (queuedRepair.DeliveryEscalationReason.StartsWith("transport_rebind_", StringComparison.Ordinal) ||
            string.Equals(queuedRepair.DeliveryEscalationReason, "file_tuna_v4_post_tuna_frontier_replay", StringComparison.Ordinal) ||
            queuedRepair.RepairRequestKey.StartsWith("transport_rebind_safety_replay:", StringComparison.Ordinal) ||
            queuedRepair.RepairRequestKey.StartsWith("file_tuna_v4_post_tuna_frontier_replay:", StringComparison.Ordinal))
        {
            return RepairReplayKind.TransportRebindSafetyReplay;
        }

        if (queuedRepair.RepairRequestKey.StartsWith("v6-frontier:", StringComparison.Ordinal) ||
            queuedRepair.RepairRequestKey.StartsWith("v6-state-frontier:", StringComparison.Ordinal) ||
            string.Equals(queuedRepair.ProtocolRecoveryMode, V6RegularNknFrontierRepairTransactionRecoveryMode, StringComparison.Ordinal) ||
            string.Equals(queuedRepair.ProtocolRecoveryMode, V6RegularNknStateRefreshRecoveryMode, StringComparison.Ordinal))
        {
            return RepairReplayKind.FrontierStallRepair;
        }

        return RepairReplayKind.V4Repair;
    }

    private static bool ShouldLogFallbackFrontierRepairProof(
        RepairReplayKind repairKind,
        FileTransferLeg? leg,
        string? repairRequestKey)
        => repairKind == RepairReplayKind.FrontierStallRepair ||
           (
               IsCurrentPostTunaFallbackLeg(leg) &&
               (
                   repairRequestKey?.StartsWith("v6-frontier:", StringComparison.Ordinal) == true ||
                   repairRequestKey?.StartsWith("v6-state-frontier:", StringComparison.Ordinal) == true ||
                   repairRequestKey?.StartsWith("transport_rebind_safety_replay:", StringComparison.Ordinal) == true
               )
           );

    private static bool HasOutboundV4RepairWorkInProgressLocked(OutboundTransferContext context)
    {
        if (context.PullV4SenderPumpRepairQueue.Count > 0 ||
            context.PullV4SenderPumpRepairQueuedChunkIndices.Count > 0)
        {
            return true;
        }

        return context.PullV4SenderPumpRepairRequests.Values.Any(static state => state.Queued || state.InFlight);
    }

    private static bool TryMarkOutboundV4RepairQueuedLocked(
        OutboundTransferContext context,
        string repairRequestKey,
        DateTimeOffset now,
        int repairRepeatIntervalMs,
        out V4SenderRepairRequestState repairState,
        out string suppressionReason,
        out long lastSentAgeMs)
    {
        suppressionReason = "(none)";
        lastSentAgeMs = -1;
        if (!context.PullV4SenderPumpRepairRequests.TryGetValue(repairRequestKey, out var existingRepairState))
        {
            repairState = new V4SenderRepairRequestState { Queued = true, QueuedUtc = now };
            context.PullV4SenderPumpRepairRequests[repairRequestKey] = repairState;
            return true;
        }

        repairState = existingRepairState;
        if (repairState.Queued)
        {
            if (TryRetireStalePostTunaFallbackExactFrontierQueuedRepairLocked(
                    context,
                    repairRequestKey,
                    repairState,
                    now,
                    repairRepeatIntervalMs,
                    "repair_queue_request"))
            {
                repairState.Queued = true;
                repairState.QueuedUtc = now;
                return true;
            }

            suppressionReason = "queued";
            repairState.SuppressedCount++;
            return false;
        }

        if (repairState.InFlight)
        {
            suppressionReason = "in_flight";
            repairState.SuppressedCount++;
            return false;
        }

        if (repairState.LastSentUtc is not null)
        {
            lastSentAgeMs = (long)Math.Max(0, (now - repairState.LastSentUtc.Value).TotalMilliseconds);
            if (lastSentAgeMs < repairRepeatIntervalMs)
            {
                suppressionReason = "recently_sent";
                repairState.SuppressedCount++;
                return false;
            }
        }

        repairState.Queued = true;
        repairState.QueuedUtc = now;
        return true;
    }

    private static bool TryRetireStalePostTunaFallbackExactFrontierQueuedRepairLocked(
        OutboundTransferContext context,
        string repairRequestKey,
        V4SenderRepairRequestState repairState,
        DateTimeOffset now,
        int repairRepeatIntervalMs,
        string source)
    {
        if (!context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
            !context.PullPostTunaRecoveryActive ||
            !context.PullTransportFrontierOnlyRepairActive ||
            repairState is not { Queued: true, InFlight: false } ||
            repairState.QueuedUtc is not { } queuedUtc)
        {
            return false;
        }

        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var canonicalContract = repairState.FallbackFrontierRepairContract;
        var canonicalExactRepair = canonicalContract is not null &&
            ReferenceEquals(context.CurrentFallbackFrontierRepairContract, canonicalContract) &&
            !canonicalContract.Lifecycle.IsSettled &&
            canonicalContract.Authority.SourceKind == FallbackFrontierRepairSourceKind.PeerRequest &&
            canonicalContract.Authority.FrontierChunkIndex == remoteFrontier &&
            string.Equals(
                canonicalContract.Authority.CanonicalRepairKey,
                repairRequestKey,
                StringComparison.Ordinal) &&
            IsFallbackFrontierRepairContractCurrent(context, canonicalContract, out _);
        var legacyExactRepair = repairRequestKey == $"{remoteFrontier}:1:{remoteFrontier}:1";
        if (remoteFrontier < 0 ||
            remoteFrontier >= context.ChunkCount ||
            (!canonicalExactRepair && !legacyExactRepair))
        {
            return false;
        }

        var staleAfterMs = Math.Max(repairRepeatIntervalMs * 4L, PullControlChatterWindowMs);
        var queuedAgeMs = (long)Math.Max(0, (now - queuedUtc).TotalMilliseconds);
        if (queuedAgeMs < staleAfterMs)
        {
            return false;
        }

        var removedRepairItemCount = 0;
        var removedRepairChunkCount = 0;
        var retained = new Queue<PullV4QueuedRepairSend>(context.PullV4SenderPumpRepairQueue.Count);
        while (context.PullV4SenderPumpRepairQueue.Count > 0)
        {
            var queuedRepair = context.PullV4SenderPumpRepairQueue.Dequeue();
            if (string.Equals(queuedRepair.RepairRequestKey, repairRequestKey, StringComparison.Ordinal))
            {
                removedRepairItemCount++;
                removedRepairChunkCount += queuedRepair.ChunkIndices.Count;
                foreach (var chunkIndex in queuedRepair.ChunkIndices)
                {
                    context.PullV4SenderPumpRepairQueuedChunkIndices.Remove(chunkIndex);
                }

                continue;
            }

            retained.Enqueue(queuedRepair);
        }

        while (retained.Count > 0)
        {
            context.PullV4SenderPumpRepairQueue.Enqueue(retained.Dequeue());
        }

        var removedQueuedFrontierChunk = context.PullV4SenderPumpRepairQueuedChunkIndices.Remove(remoteFrontier) ? 1 : 0;
        repairState.Queued = false;
        repairState.QueuedUtc = null;
        repairState.SuppressedCount++;

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_queued_repair_stale_retired; direction=sender; transfer_id={context.TransferId}; session_id={context.SessionId}; source={FormatProtocolLogValue(source)}; reason=post_tuna_fallback_exact_frontier_not_sent; repair_request_key={repairRequestKey}; queued_age_ms={queuedAgeMs}; stale_after_ms={staleAfterMs}; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; removed_repair_item_count={removedRepairItemCount}; removed_repair_chunk_count={removedRepairChunkCount}; removed_queued_frontier_chunk={removedQueuedFrontierChunk}");
        return true;
    }

    private static bool ShouldRecordFailedPostTunaFallbackExactFrontierRepairAttemptLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend repairSend)
    {
        if (!context.RouteRuntime.UsesPostTunaFallbackV6Runtime ||
            context.NegotiatedDataProtocolVersion < FileTransferProtocol.ProtocolVersionV6 ||
            !context.PullPostTunaRecoveryActive ||
            !context.PullTransportFrontierOnlyRepairActive ||
            repairSend.ChunkIndices.Count != 1 ||
            repairSend.FirstStartChunkIndex != repairSend.RemoteNextExpectedChunkIndex ||
            repairSend.LastEndChunkExclusive != repairSend.FirstStartChunkIndex + 1)
        {
            return false;
        }

        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        return remoteFrontier >= 0 &&
               remoteFrontier < context.ChunkCount &&
               repairSend.FirstStartChunkIndex == remoteFrontier &&
               string.Equals(
                   repairSend.RepairRequestKey,
                   $"{remoteFrontier}:1:{remoteFrontier}:1",
                   StringComparison.Ordinal);
    }

    private static (FileTransferV4RepairDeliveryMode Mode, string Reason, long CreditExhaustedTimeMs) ResolveV4RepairDeliveryDecisionLocked(
        OutboundTransferContext context,
        V4SenderRepairRequestState repairState,
        int queuedRemoteFrontierChunkIndex,
        bool frontierRepair,
        DateTimeOffset now)
    {
        var creditStallAgeMs = context.V4SenderCreditExhaustedSinceUtc is null
            ? 0
            : (long)Math.Max(0, (now - context.V4SenderCreditExhaustedSinceUtc.Value).TotalMilliseconds);
        if (repairState.SentCount == 0)
        {
            if (frontierRepair &&
                IsOutboundPostTunaRecoveryActiveLocked(context))
            {
                return (FileTransferV4RepairDeliveryMode.ControlBulkRedundant, "post_fallback_frontier_emergency", creditStallAgeMs);
            }

            if (frontierRepair &&
                ShouldUsePrimaryRegularNknBulkV6RepairProfileLocked(context))
            {
                return (FileTransferV4RepairDeliveryMode.ControlBulkRedundant, "primary_regular_nkn_frontier_first_send", creditStallAgeMs);
            }

            if (frontierRepair &&
                IsV4FileOnlyFastRepairEnabled(context) &&
                creditStallAgeMs >= V4FileOnlyFirstRepairCreditStallEscalationMs)
            {
                return (FileTransferV4RepairDeliveryMode.ControlBulkRedundant, "first_send_credit_stall", creditStallAgeMs);
            }

            return (FileTransferV4RepairDeliveryMode.BulkOnly, "first_send", creditStallAgeMs);
        }

        if (creditStallAgeMs >= V4RepairRedundancyEscalationStallMs)
        {
            return (FileTransferV4RepairDeliveryMode.ControlBulkRedundant, "credit_stall", creditStallAgeMs);
        }

        var currentRemoteFrontier = Math.Max(
            queuedRemoteFrontierChunkIndex,
            Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount));
        if (repairState.LastSentRemoteFrontierChunkIndex >= currentRemoteFrontier)
        {
            return (FileTransferV4RepairDeliveryMode.ControlBulkRedundant, "frontier_not_advanced", creditStallAgeMs);
        }

        return (FileTransferV4RepairDeliveryMode.ControlBulkRedundant, "retry", creditStallAgeMs);
    }

    private static string FormatV4RepairDeliveryMode(FileTransferV4RepairDeliveryMode mode)
        => mode == FileTransferV4RepairDeliveryMode.ControlBulkRedundant
            ? "control_bulk_escalated"
            : "bulk_only";

    private static PullV4QueuedRepairSend? RevalidateQueuedV4RepairSendLocked(
        OutboundTransferContext context,
        PullV4QueuedRepairSend queuedRepair)
    {
        var filtered = new List<int>(queuedRepair.ChunkIndices.Count);
        var skippedObsolete = 0;
        var skippedFuture = 0;
        var skippedOutOfBounds = 0;
        var remoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
        var acceptedUntil = ResolveOutboundRepairAcceptedUntilExclusiveLocked(context);
        foreach (var chunkIndex in queuedRepair.ChunkIndices)
        {
            if (chunkIndex < 0 || chunkIndex >= context.ChunkCount)
            {
                skippedOutOfBounds++;
                continue;
            }

            if (chunkIndex < remoteFrontier)
            {
                skippedObsolete++;
                continue;
            }

            if (chunkIndex >= acceptedUntil &&
                !(queuedRepair.EmergencyCreditRepair && chunkIndex == remoteFrontier))
            {
                skippedFuture++;
                continue;
            }

            filtered.Add(chunkIndex);
        }

        if (filtered.Count == 0)
        {
            if (queuedRepair.FallbackFrontierRepairContract is { } fallbackContract)
            {
                var outcome = remoteFrontier > fallbackContract.Authority.FrontierChunkIndex
                    ? FallbackFrontierRepairSettlementOutcome.ProgressObserved
                    : fallbackContract.Lifecycle.DispatchObserved
                        ? FallbackFrontierRepairSettlementOutcome.SettledStalled
                        : FallbackFrontierRepairSettlementOutcome.MissingDispatch;
                TrySettleFallbackFrontierRepairContract(
                    fallbackContract,
                    outcome,
                    "legacy_sparse_no_schedulable_work_after_revalidation");
            }

            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_repair_suppressed; direction=sender; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={queuedRepair.RepairRequestKey}; reason=obsolete_after_frontier_advance; range_count={queuedRepair.RangeCount}; requested_chunk_count={queuedRepair.RequestedChunkCount}; scheduled_chunk_count=0; first_start_chunk_index={queuedRepair.FirstStartChunkIndex}; last_end_chunk_exclusive={queuedRepair.LastEndChunkExclusive}; frontier_tail_repair={(queuedRepair.FrontierTailRepair ? 1 : 0)}; remote_next_expected_chunk_index={remoteFrontier}; chunks_accepted_for_transport={acceptedUntil}; skipped_obsolete_count={queuedRepair.SkippedObsoleteCount + skippedObsolete}; skipped_future_count={queuedRepair.SkippedFutureCount + skippedFuture}; skipped_out_of_bounds_count={queuedRepair.SkippedOutOfBoundsCount + skippedOutOfBounds}");
            return null;
        }

        return queuedRepair with
        {
            ChunkIndices = filtered,
            RemoteNextExpectedChunkIndex = remoteFrontier,
            ChunksAcceptedForTransport = acceptedUntil,
            SkippedObsoleteCount = queuedRepair.SkippedObsoleteCount + skippedObsolete,
            SkippedFutureCount = queuedRepair.SkippedFutureCount + skippedFuture,
            SkippedOutOfBoundsCount = queuedRepair.SkippedOutOfBoundsCount + skippedOutOfBounds,
        };
    }

    private void ClearObsoleteOutboundV4RepairWorkAfterFrontierAdvanceLocked(
        OutboundTransferContext context,
        int previousRemoteFrontier,
        int remoteFrontier)
    {
        if (remoteFrontier <= previousRemoteFrontier)
        {
            return;
        }

        TrySettleOutboundRegularV4FrontierRepairProgressLocked(
            context,
            previousRemoteFrontier,
            remoteFrontier,
            "regular_v4_remote_frontier_progress");

        TrySettleOutboundFallbackFrontierProgressLocked(
            context,
            previousRemoteFrontier,
            remoteFrontier,
            "legacy_sparse_remote_frontier_progress");

        var removedQueuedChunks = context.PullV4SenderPumpRepairQueuedChunkIndices.RemoveWhere(
            chunkIndex => chunkIndex < remoteFrontier);
        var removedRepairItems = 0;
        var removedRepairChunks = 0;
        var retained = new Queue<PullV4QueuedRepairSend>(context.PullV4SenderPumpRepairQueue.Count);
        while (context.PullV4SenderPumpRepairQueue.Count > 0)
        {
            var queuedRepair = context.PullV4SenderPumpRepairQueue.Dequeue();
            var filtered = queuedRepair.ChunkIndices
                .Where(chunkIndex => chunkIndex >= remoteFrontier)
                .ToList();
            var skippedObsolete = queuedRepair.ChunkIndices.Count - filtered.Count;
            if (filtered.Count == 0)
            {
                removedRepairItems++;
                removedRepairChunks += queuedRepair.ChunkIndices.Count;
                if (context.PullV4SenderPumpRepairRequests.TryGetValue(queuedRepair.RepairRequestKey, out var repairState))
                {
                    repairState.Queued = false;
                    repairState.QueuedUtc = null;
                }

                continue;
            }

            removedRepairChunks += skippedObsolete;
            retained.Enqueue(queuedRepair with
            {
                ChunkIndices = filtered,
                RemoteNextExpectedChunkIndex = remoteFrontier,
                SkippedObsoleteCount = queuedRepair.SkippedObsoleteCount + skippedObsolete,
            });
        }

        while (retained.Count > 0)
        {
            context.PullV4SenderPumpRepairQueue.Enqueue(retained.Dequeue());
        }

        var removedHistoryCount = 0;
        foreach (var pair in context.PullV4SenderPumpRepairRequests.ToArray())
        {
            var repairState = pair.Value;
            if (repairState.Queued || repairState.InFlight)
            {
                continue;
            }

            if (repairState.LastSentRemoteFrontierChunkIndex >= 0 &&
                repairState.LastSentRemoteFrontierChunkIndex < remoteFrontier)
            {
                context.PullV4SenderPumpRepairRequests.Remove(pair.Key);
                removedHistoryCount++;
            }
        }

        if (removedQueuedChunks > 0 ||
            removedRepairItems > 0 ||
            removedRepairChunks > 0 ||
            removedHistoryCount > 0)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_repair_obsolete_after_frontier_advance; direction=sender; transfer_id={context.TransferId}; session_id={context.SessionId}; previous_remote_next_expected_chunk_index={previousRemoteFrontier}; remote_next_expected_chunk_index={remoteFrontier}; removed_queued_chunk_index_count={removedQueuedChunks}; removed_repair_item_count={removedRepairItems}; removed_repair_chunk_count={removedRepairChunks}; removed_history_count={removedHistoryCount}");
        }
    }

    private async Task<bool> SendChunkIndicesV4Async(
        OutboundTransferContext context,
        Stream stream,
        IFileTransferDataSession dataSession,
        IReadOnlyList<int> chunkIndices,
        bool repairSend,
        string repairRequestKey = "(none)",
        string? protocolRepairRequestId = null,
        string? protocolPriority = null,
        string? protocolRecoveryMode = null,
        FileTransferV4RepairDeliveryMode repairDeliveryMode = FileTransferV4RepairDeliveryMode.BulkOnly,
        string repairDeliveryReason = "normal",
        FallbackFrontierRepairContract? fallbackFrontierRepairContract = null,
        RegularV4FrontierRepairContract? regularV4FrontierRepairContract = null,
        RegularV4FrontierRepairScheduledDispatch? regularV4ScheduledDispatch = null,
        Action<FileTransferDataPathSendAuthority?>? observeSendAuthority = null,
        Action<FileTransferReceiveRecoveryOperation, string, string>? observeReceiveRecoveryHold = null,
        OutboundSparsePumpInstall? pumpInstall = null,
        CancellationToken pumpCancellationToken = default)
    {
        if (chunkIndices.Count == 0)
        {
            return true;
        }

        bool IsPumpInstallCurrentLocked()
            => pumpInstall is null ||
               IsOutboundSparsePumpInstallCurrentLocked(
                   context,
                   pumpInstall,
                   dataSession,
                   out _);

        bool IsRegularV4FrontierRepairSubmissionCurrentLocked(out string rejectionReason)
        {
            if (regularV4FrontierRepairContract is null && regularV4ScheduledDispatch is null)
            {
                rejectionReason = "not_applicable";
                return true;
            }

            if (regularV4FrontierRepairContract is null || regularV4ScheduledDispatch is null)
            {
                rejectionReason = "scheduled_repair_range_missing";
                return false;
            }

            if (!regularV4ScheduledDispatch.ChunkIndices.SequenceEqual(chunkIndices))
            {
                rejectionReason = "scheduled_repair_range_mismatch";
                return false;
            }

            return TryValidateOutboundRegularV4FrontierRepairSubmissionLocked(
                context,
                regularV4FrontierRepairContract,
                regularV4ScheduledDispatch,
                out rejectionReason);
        }

        void RejectRegularV4FrontierRepairSubmissionLocked(
            string rejectionReason,
            string stage = "physical_submission")
        {
            if (regularV4FrontierRepairContract is null)
            {
                return;
            }

            TrySettleRegularV4FrontierRepairContract(
                regularV4FrontierRepairContract,
                FileTransferRegularV4FrontierRepairSettlementOutcome.StaleRejected,
                chunkIndices.Count,
                rejectionReason);
            LogFileTransferRegularV4FrontierRepairAuthorityRejected(
                FileTransferDirection.Outbound,
                context.TransferId,
                context.SessionId,
                context.CurrentTransferLeg,
                repairRequestKey,
                "v4_repair_send",
                stage,
                rejectionReason,
                regularV4FrontierRepairContract.Authority.FrontierChunkIndex,
                regularV4FrontierRepairContract.Authority.DurableReceivedHighestChunkIndex,
                regularV4FrontierRepairContract.Authority.PendingRepairCount,
                regularV4FrontierRepairContract.Authority,
                GetRegularV4FrontierRepairPressureInstallGeneration(
                    CreateCoordinatorStateLocked(context),
                    regularV4FrontierRepairContract),
                regularV4ScheduledDispatch?.StartChunkIndex ?? -1,
                regularV4ScheduledDispatch?.EndChunkExclusive ?? -1,
                "attached_installed_contract");
        }

        var sendLifetimeToken = pumpCancellationToken.CanBeCanceled
            ? pumpCancellationToken
            : context.LifetimeCts.Token;
        RuntimeOwnerToken? sourceRuntimeOwner = null;
        RoutePublicationToken? sourceRoutePublication = null;
        FileTransferLeg? sourceLeg = null;
        long sourceDataSessionGeneration = 0;

        bool IsSourceSendScopeCurrentLocked()
            => ReferenceEquals(outboundTransfer, context) &&
               !context.IsTerminal &&
               ReferenceEquals(context.DataSession, dataSession) &&
               context.DataSessionGeneration == sourceDataSessionGeneration &&
               context.CurrentRuntimeOwner == sourceRuntimeOwner &&
               context.CurrentRoutePublicationToken == sourceRoutePublication &&
               context.CurrentTransferLeg == sourceLeg &&
               !FileTransferCoordinator.IsFileTransferRouteTransitionDraining(
                   CreateCoordinatorStateLocked(context),
                   out _);

        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                !IsPumpInstallCurrentLocked())
            {
                return false;
            }

            if (TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                    context,
                    out var receiveRecoveryOperation,
                    out var receiveRecoveryHoldReason))
            {
                MarkOutboundPayloadSubmissionHeldForReceiveRecoveryLocked(
                    context,
                    receiveRecoveryOperation,
                    "send_entry",
                    receiveRecoveryHoldReason,
                    regularV4FrontierRepairContract,
                    repairSend ? repairRequestKey : null);
                observeReceiveRecoveryHold?.Invoke(
                    receiveRecoveryOperation,
                    "send_entry",
                    receiveRecoveryHoldReason);
                return false;
            }

            if (!IsRegularV4FrontierRepairSubmissionCurrentLocked(out var regularContractRejectionReason))
            {
                RejectRegularV4FrontierRepairSubmissionLocked(regularContractRejectionReason);
                return false;
            }

            sourceRuntimeOwner = context.CurrentRuntimeOwner;
            sourceRoutePublication = context.CurrentRoutePublicationToken;
            sourceLeg = context.CurrentTransferLeg;
            sourceDataSessionGeneration = context.DataSessionGeneration;
        }

        var isRegularV4PeerSilenceSafetyRepair =
            repairSend &&
            (regularV4ScheduledDispatch?.RepairReplayKind == RepairReplayKind.PeerSilenceReplay ||
             string.Equals(repairDeliveryReason, "regular_v4_peer_silence_safety_replay", StringComparison.Ordinal));
        var buffer = ArrayPool<byte>.Shared.Rent(context.ChunkSizeBytes);
        try
        {
            var pending = new Queue<PendingV4TransportSend>();
            long pendingRawBytes = 0;
            var stopForTransportPause = false;
            var stopForLiveRouteChange = false;
            var completedWithoutTransportPause = true;
            var transportStopReason = "transport_paused";
            var liveRouteChangeStopReason = "live_route_changed";

            void MarkStopForTransportPauseLocked()
            {
                stopForTransportPause = true;
                completedWithoutTransportPause = false;
                transportStopReason = context.PullTransportPauseReason ?? transportStopReason;
                MarkOutboundV4SenderPumpTransportPausedLocked(context);
            }

            void ObserveReceiveRecoveryPayloadHoldLocked(string stage)
            {
                if (!TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                        context,
                        out var operation,
                        out var holdReason))
                {
                    return;
                }

                MarkOutboundPayloadSubmissionHeldForReceiveRecoveryLocked(
                    context,
                    operation,
                    stage,
                    holdReason,
                    regularV4FrontierRepairContract,
                    repairSend ? repairRequestKey : null);
                observeReceiveRecoveryHold?.Invoke(
                    operation,
                    stage,
                    holdReason);
            }

            void AbandonPendingForTransportPause()
            {
                if (pending.Count == 0)
                {
                    return;
                }

                var abandonedFrameCount = 0;
                long abandonedBytes = 0;
                while (pending.Count > 0)
                {
                    var abandoned = pending.Dequeue();
                    abandonedFrameCount++;
                    abandonedBytes += abandoned.Prepared.RawBytes;
                    abandoned.SendCts?.Cancel();
                    _ = ObserveAbandonedOutboundV4TransportSendAsync(
                        abandoned.SendTask,
                        abandoned.SendCts,
                        context.TransferId,
                        context.SessionId,
                        abandoned.Prepared.StartChunkIndex,
                        abandoned.Prepared.ChunkCount);
                }

                pendingRawBytes = 0;
                lock (gate)
                {
                    if (ReferenceEquals(outboundTransfer, context))
                    {
                        context.PullSenderPipelineCurrentInFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames - abandonedFrameCount);
                        context.PullSenderPipelineCurrentInFlightBytes = Math.Max(0, context.PullSenderPipelineCurrentInFlightBytes - abandonedBytes);
                    }
                }

                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event={ResolveOutboundV4PendingSendsAbandonedForTransportPauseEventName(context)}; transfer_id={context.TransferId}; session_id={context.SessionId}; abandoned_frame_count={abandonedFrameCount}; abandoned_raw_bytes={abandonedBytes}; reason={FormatProtocolLogValue(context.PullTransportPauseReason ?? transportStopReason)}");
            }

            void AbandonPendingForLiveRouteChange()
            {
                if (pending.Count == 0)
                {
                    return;
                }

                var abandonedFrameCount = 0;
                long abandonedBytes = 0;
                while (pending.Count > 0)
                {
                    var abandoned = pending.Dequeue();
                    abandonedFrameCount++;
                    abandonedBytes += abandoned.Prepared.RawBytes;
                    abandoned.SendCts?.Cancel();
                    _ = ObserveAbandonedOutboundV4TransportSendAsync(
                        abandoned.SendTask,
                        abandoned.SendCts,
                        context.TransferId,
                        context.SessionId,
                        abandoned.Prepared.StartChunkIndex,
                        abandoned.Prepared.ChunkCount);
                }

                pendingRawBytes = 0;
                lock (gate)
                {
                    if (ReferenceEquals(outboundTransfer, context))
                    {
                        context.PullSenderPipelineCurrentInFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames - abandonedFrameCount);
                        context.PullSenderPipelineCurrentInFlightBytes = Math.Max(0, context.PullSenderPipelineCurrentInFlightBytes - abandonedBytes);
                    }
                }

                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_v4_pending_transport_sends_abandoned_for_live_route_change; transfer_id={context.TransferId}; session_id={context.SessionId}; abandoned_frame_count={abandonedFrameCount}; abandoned_raw_bytes={abandonedBytes}; reason={FormatProtocolLogValue(liveRouteChangeStopReason)}; current_route={FormatProtocolLogValue(context.RouteSelection.TelemetryToken)}; protocol_version={context.NegotiatedDataProtocolVersion}");
            }

            async Task RetireNextAsync()
            {
                var pendingSend = pending.Dequeue();
                pendingRawBytes = Math.Max(0, pendingRawBytes - pendingSend.Prepared.RawBytes);
                Exception? sendException = null;
                var timedOutForBoundTransport = false;
                var boundSendForTransport =
                    ShouldBoundOutboundV4TransportSend(context) ||
                    isRegularV4PeerSilenceSafetyRepair;
                var abandonedForTransportPause = false;
                var abandonedForLiveRouteChange = false;
                lock (gate)
                {
                    var blockForTransportPause = ShouldBlockOutboundV4TransportSendForTransportPauseLocked(context, repairSend);
                    if (ReferenceEquals(outboundTransfer, context) &&
                        !context.IsTerminal &&
                        blockForTransportPause)
                    {
                        MarkStopForTransportPauseLocked();
                        ObserveReceiveRecoveryPayloadHoldLocked(
                            "pending_send_retirement");
                        abandonedForTransportPause = true;
                    }
                }

                if (abandonedForTransportPause)
                {
                    pendingSend.SendCts?.Cancel();
                    lock (gate)
                    {
                        if (ReferenceEquals(outboundTransfer, context))
                        {
                            context.PullSenderPipelineCurrentInFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames - 1);
                            context.PullSenderPipelineCurrentInFlightBytes = Math.Max(0, context.PullSenderPipelineCurrentInFlightBytes - pendingSend.Prepared.RawBytes);
                        }
                    }

                    _ = ObserveAbandonedOutboundV4TransportSendAsync(
                        pendingSend.SendTask,
                        pendingSend.SendCts,
                        context.TransferId,
                        context.SessionId,
                        pendingSend.Prepared.StartChunkIndex,
                        pendingSend.Prepared.ChunkCount);

                    LocalOperationalLog.Warn(
                        "FileTransferService",
                        $"event=filetransfer_v4_transport_send_abandoned_for_transport_pause; transfer_id={context.TransferId}; session_id={context.SessionId}; start_chunk_index={pendingSend.Prepared.StartChunkIndex}; batch_chunk_count={pendingSend.Prepared.ChunkCount}; raw_bytes={pendingSend.Prepared.RawBytes}; repair_send={(repairSend ? 1 : 0)}; send_attempt={pendingSend.SendAttempt}; send_attempt_count={pendingSend.SendAttemptCount}; reason={FormatProtocolLogValue(transportStopReason)}; repair_request_key={repairRequestKey}; repair_delivery_mode={(repairSend ? FormatV4RepairDeliveryMode(repairDeliveryMode) : "none")}; repair_delivery_escalation_reason={(repairSend ? repairDeliveryReason : "none")}");
                    return;
                }

                try
                {
                    if (boundSendForTransport &&
                        !pendingSend.SendTask.IsCompleted)
                    {
                        var sendTimeout = CurrentV6RegularNknSparseRuntimeV4TransportSendTimeout;
                        var timeoutStarted = Stopwatch.GetTimestamp();
                        while (!pendingSend.SendTask.IsCompleted)
                        {
                            var elapsed = Stopwatch.GetElapsedTime(timeoutStarted);
                            var remaining = sendTimeout - elapsed;
                            if (remaining <= TimeSpan.Zero)
                            {
                                sendLifetimeToken.ThrowIfCancellationRequested();
                                timedOutForBoundTransport = true;
                                break;
                            }

                            var delay = remaining < TimeSpan.FromMilliseconds(PullSessionReceivePollDelayMs)
                                ? remaining
                                : TimeSpan.FromMilliseconds(PullSessionReceivePollDelayMs);
                            var completed = await Task.WhenAny(
                                    pendingSend.SendTask,
                                    Task.Delay(delay, sendLifetimeToken))
                                .ConfigureAwait(false);
                            if (completed == pendingSend.SendTask)
                            {
                                break;
                            }

                            if (!pendingSend.ScheduledRegularNknV4FastRuntime)
                            {
                                continue;
                            }

                            lock (gate)
                            {
                                var blockForTransportPause = ShouldBlockOutboundV4TransportSendForTransportPauseLocked(context, repairSend);
                                if (ReferenceEquals(outboundTransfer, context) &&
                                    !context.IsTerminal &&
                                    blockForTransportPause)
                                {
                                    MarkStopForTransportPauseLocked();
                                    ObserveReceiveRecoveryPayloadHoldLocked(
                                        "pending_send_wait");
                                    abandonedForTransportPause = true;
                                }
                                else if (ReferenceEquals(outboundTransfer, context) &&
                                         !context.IsTerminal &&
                                         !context.RouteRuntime.UsesRegularNknV4FastRuntime)
                                {
                                    stopForLiveRouteChange = true;
                                    completedWithoutTransportPause = false;
                                    liveRouteChangeStopReason = "regular_v4_send_superseded_by_live_route";
                                    context.SparseSenderPumpLastWakeReason = "live_route_changed";
                                    abandonedForLiveRouteChange = true;
                                }
                            }

                            if (abandonedForTransportPause)
                            {
                                pendingSend.SendCts?.Cancel();
                                lock (gate)
                                {
                                    if (ReferenceEquals(outboundTransfer, context))
                                    {
                                        context.PullSenderPipelineCurrentInFlightFrames = Math.Max(0, context.PullSenderPipelineCurrentInFlightFrames - 1);
