                        if (deferredOperation is { } exactDeferredOperation)
                        {
                            observeReceiveRecoveryHold?.Invoke(
                                exactDeferredOperation,
                                "submission_epoch_failure",
                                "post_tuna_fallback_receive_recovery_submission_epoch_transition");
                        }

                        completedWithoutTransportPause = false;
                        stopForTransportPause = true;
                        transportStopReason =
                            lateChildRetired
                                ? "post_tuna_fallback_recovery_late_submission_child_retired"
                                : "post_tuna_fallback_recovery_submission_failure_deferred";
                        return;
                    }

                    var deferredForTransportPause = false;
                    var deferredForFileTunaFallbackHandoff = false;
                    var activationPauseStarted = false;
                    var activationPauseAlreadyRecovered = false;
                    string pauseReason = "transport_paused";
                    int rebindGeneration = 0;
                    var errorCompletionCurrent = false;
                    var errorRegularContractRejected = false;
                    lock (gate)
                    {
                        errorCompletionCurrent = ReferenceEquals(outboundTransfer, context) &&
                            !context.IsTerminal &&
                            IsPumpInstallCurrentLocked();
                        if (errorCompletionCurrent &&
                            !IsRegularV4FrontierRepairSubmissionCurrentLocked(
                                out var regularFailureRejectionReason))
                        {
                            RejectRegularV4FrontierRepairSubmissionLocked(
                                regularFailureRejectionReason,
                                "physical_failure");
                            errorRegularContractRejected = true;
                            errorCompletionCurrent = false;
                        }

                        var blockForTransportPause = ShouldBlockOutboundV4TransportSendForTransportPauseLocked(context, repairSend);
                        if (errorCompletionCurrent &&
                            blockForTransportPause)
                        {
                            deferredForTransportPause = true;
                            pauseReason = context.PullTransportPauseReason ?? pauseReason;
                            rebindGeneration = context.PullTransportRebindGeneration;
                            MarkStopForTransportPauseLocked();
                            ObserveReceiveRecoveryPayloadHoldLocked(
                                "send_error");
                        }
                        else if (errorCompletionCurrent &&
                                 TryDeferOutboundV4SendForTunaActivationPauseLocked(
                                     context,
                                     dataSession.IsAvailable,
                                     sendException,
                                     out pauseReason,
                                     out rebindGeneration,
                                     out activationPauseStarted,
                                     out activationPauseAlreadyRecovered))
                        {
                            deferredForTransportPause = true;
                            stopForTransportPause = true;
                            completedWithoutTransportPause = false;
                            transportStopReason = pauseReason;
                        }
                        else if (errorCompletionCurrent &&
                                 TryDeferOutboundV4SendForFileTunaFallbackHandoffLocked(
                                     context,
                                     sendException,
                                     out pauseReason,
                                     out rebindGeneration))
                        {
                            deferredForTransportPause = true;
                            deferredForFileTunaFallbackHandoff = true;
                            stopForTransportPause = true;
                            completedWithoutTransportPause = false;
                            transportStopReason = pauseReason;
                        }
                    }

                    if (!errorCompletionCurrent)
                    {
                        if (!errorRegularContractRejected)
                        {
                            LogOutboundSparsePumpInstallRejected(
                                context,
                                pumpInstall,
                                "send_failure",
                                "stale_pump_install");
                        }
                        return;
                    }

                    if (deferredForTransportPause)
                    {
                        completedWithoutTransportPause = false;
                        if (activationPauseStarted)
                        {
                            LogTransportPaused(FileTransferDirection.Outbound, context.TransferId, context.SessionId, pauseReason);
                            ScheduleOutboundV4TransportPauseControlRetry(context, paused: true, pauseReason);
                        }

                        var eventName = activationPauseAlreadyRecovered
                            ? "filetransfer_v4_transport_send_failure_deferred_for_recovered_tuna_activation_pause"
                            : deferredForFileTunaFallbackHandoff
                            ? "filetransfer_v4_transport_send_failure_deferred_for_file_tuna_v4_fallback_handoff"
                            : ShouldPauseOutboundV4SenderPumpForV6RegularNknSparseRuntimeLocked(context)
                            ? "filetransfer_v4_transport_send_failure_deferred_for_v6_regular_nkn_sparse_runtime"
                            : ShouldPauseOutboundV4SenderPumpForRegularNknV4ReceiveStallRecoveryLocked(context)
                            ? "filetransfer_v4_transport_send_failure_deferred_for_regular_v4_receive_stall_recovery"
                            : "filetransfer_v4_transport_send_failure_deferred_for_transport_pause";
                        LocalOperationalLog.Warn(
                            "FileTransferService",
                            $"event={eventName}; transfer_id={context.TransferId}; session_id={context.SessionId}; start_chunk_index={pendingSend.Prepared.StartChunkIndex}; batch_chunk_count={pendingSend.Prepared.ChunkCount}; raw_bytes={pendingSend.Prepared.RawBytes}; repair_send={(repairSend ? 1 : 0)}; send_attempt={pendingSend.SendAttempt}; send_attempt_count={pendingSend.SendAttemptCount}; reason={FormatProtocolLogValue(pauseReason)}; rebind_generation={rebindGeneration}; error={FormatProtocolLogValue(sendException.GetType().Name)}; message={FormatProtocolLogValue(sendException.Message)}");
                        return;
                    }

                    if (sendException is OperationCanceledException)
                    {
                        throw new OperationCanceledException(context.LifetimeCts.Token);
                    }

                    throw new InvalidOperationException("File-transfer V4 sender transport send failed.", sendException);
                }

                if (fallbackFrontierRepairContract is not null)
                {
                    var authorizedCompletion = false;
                    var pumpAuthorityCurrent = false;
                    var fallbackCompletionRejectionReason = "legacy_sparse_send_completed_for_stale_context";
                    lock (gate)
                    {
                        pumpAuthorityCurrent = ReferenceEquals(outboundTransfer, context) &&
                            !context.IsTerminal &&
                            IsPumpInstallCurrentLocked();
                        if (pumpAuthorityCurrent &&
                            TryValidateOutboundFallbackFrontierDispatchLocked(
                                context,
                                fallbackFrontierRepairContract,
                                out fallbackCompletionRejectionReason))
                        {
                            authorizedCompletion = true;
                            if (TryMarkFallbackFrontierRepairDispatched(fallbackFrontierRepairContract))
                            {
                                LogFallbackFrontierRepairDispatched(
                                    fallbackFrontierRepairContract,
                                    protocolRepairRequestId ?? fallbackFrontierRepairContract.Authority.ProtocolRepairRequestId,
                                    "legacy_sparse_v4_send",
                                    pendingSend.Prepared.ChunkCount,
                                    context.RemoteNextExpectedChunkIndex,
                                    context.ChunksAcceptedForTransport);
                            }
                        }
                        else if (pumpAuthorityCurrent)
                        {
                            TrySettleFallbackFrontierRepairContract(
                                fallbackFrontierRepairContract,
                                context.IsTerminal
                                    ? FallbackFrontierRepairSettlementOutcome.TerminalRejected
                                    : FallbackFrontierRepairSettlementOutcome.StaleRejected,
                                context.IsTerminal
                                    ? "legacy_sparse_send_completed_after_terminal"
                                    : fallbackCompletionRejectionReason);
                        }
                        else
                        {
                            fallbackCompletionRejectionReason = "stale_pump_install";
                        }
                    }

                    if (!authorizedCompletion)
                    {
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_v4_repair_send_completion_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(fallbackFrontierRepairContract.Authority.AuthorityId.ToString())}; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={FormatProtocolLogValue(fallbackFrontierRepairContract.Authority.CanonicalRepairKey)}; start_chunk_index={pendingSend.Prepared.StartChunkIndex}; batch_chunk_count={pendingSend.Prepared.ChunkCount}; decision_reason={FormatProtocolLogValue(fallbackCompletionRejectionReason)}");
                        return;
                    }
                }

                var progressCompletionCurrent = false;
                var progressRegularContractRejected = false;
                lock (gate)
                {
                    progressCompletionCurrent = ReferenceEquals(outboundTransfer, context) &&
                        !context.IsTerminal &&
                        IsPumpInstallCurrentLocked();
                    if (progressCompletionCurrent &&
                        !IsRegularV4FrontierRepairSubmissionCurrentLocked(
                            out var regularProgressRejectionReason))
                    {
                        RejectRegularV4FrontierRepairSubmissionLocked(
                            regularProgressRejectionReason,
                            "physical_progress");
                        progressRegularContractRejected = true;
                        progressCompletionCurrent = false;
                    }

                    if (!progressCompletionCurrent)
                    {
                        // The completion belongs to a retired sender child. Its transport
                        // observation is not authority to mutate the successor runtime.
                    }
                    else
                    {
                        var startChunkIndex = pendingSend.Prepared.StartChunkIndex;
                        for (var chunkOffset = 0; chunkOffset < pendingSend.Prepared.ChunkCount; chunkOffset++)
                        {
                            var chunkIndex = startChunkIndex + chunkOffset;
                            context.SentAwaitingAck[chunkIndex] = sentUtc;
                            context.LastChunkSentUtc[chunkIndex] = sentUtc;
                            if (!repairSend)
                            {
                                context.ChunksAcceptedForTransport = Math.Max(context.ChunksAcceptedForTransport, chunkIndex + 1);
                            }

                            context.RecentPullChunkSentUtc.Enqueue(sentUtc);
                        }

                        if (!repairSend)
                        {
                            context.BytesAcceptedForTransport = context.ChunksAcceptedForTransport >= context.ChunkCount
                                ? context.FileSizeBytes
                                : Math.Min(context.FileSizeBytes, (long)context.ChunksAcceptedForTransport * context.ChunkSizeBytes);
                        }

                        TrimRecentEvents(context.RecentPullChunkSentUtc, sentUtc);
                        context.PullUsefulPayloadBytesRecent += pendingSend.Prepared.RawBytes;
                        context.PullSenderRawBytesRecent += pendingSend.Prepared.RawBytes;
                        context.PullSenderRawBytesTotal += pendingSend.Prepared.RawBytes;
                        context.PullSenderBatchFramesRecent++;
                        context.PullSenderBatchFramesTotal++;
                        context.PullSenderChunkCountRecent += pendingSend.Prepared.ChunkCount;
                        context.PullSenderChunkCountTotal += pendingSend.Prepared.ChunkCount;
                        if (repairSend)
                        {
                            context.PullSenderRepairRawBytesTotal += pendingSend.Prepared.RawBytes;
                            context.PullSenderRepairBatchFramesTotal++;
                            context.PullSenderRepairChunkCountTotal += pendingSend.Prepared.ChunkCount;
                            context.PullSenderRepairSendCountRecent += pendingSend.Prepared.ChunkCount;
                        }
                        else
                        {
                            context.PullSenderNormalRawBytesTotal += pendingSend.Prepared.RawBytes;
                            context.PullSenderNormalBatchFramesTotal++;
                            context.PullSenderNormalChunkCountTotal += pendingSend.Prepared.ChunkCount;
                        }

                        MaybeLogOutboundV4SenderPumpSummaryLocked(context, sentUtc, force: false);
                    }
                }

                if (!progressCompletionCurrent)
                {
                    if (!progressRegularContractRejected)
                    {
                        LogOutboundSparsePumpInstallRejected(
                            context,
                            pumpInstall,
                            "send_progress",
                            "stale_pump_install");
                    }
                    return;
                }

                LogPullBinaryFrameSent(
                    context.TransferId,
                    context.SessionId,
                    pendingSend.Prepared.Frame,
                    pendingSend.Prepared.RawBytes);

                if (repairSend || FileTransferDiagnosticLogPolicy.TraceEnabled)
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v4_chunk_batch_sent; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; start_chunk_index={pendingSend.Prepared.StartChunkIndex}; batch_chunk_count={pendingSend.Prepared.ChunkCount}; raw_bytes={pendingSend.Prepared.RawBytes}; repair_send={(repairSend ? 1 : 0)}; mixed_screenshare={(IsV4MixedScreenShareActive() ? 1 : 0)}; screen_share_active={(sessionScreenShareActive ? 1 : 0)}; screen_share_degraded={(sessionScreenShareDegraded ? 1 : 0)}; screen_share_observed={(sessionScreenShareObserved ? 1 : 0)}; repair_delivery_mode={(repairSend ? FormatV4RepairDeliveryMode(repairDeliveryMode) : "none")}; repair_delivery_escalation_reason={(repairSend ? repairDeliveryReason : "none")}; repair_batch_send_attempt={pendingSend.SendAttempt}; repair_batch_send_attempt_count={pendingSend.SendAttemptCount}{FormatV4DataPathAuthoritySuffix(context, "filetransfer_v4_chunk_batch_sent", pendingSend.SendAuthority)}");
                }
            }

            async Task<bool> ScheduleAsync(PreparedV4TransportSend prepared, int sendAttempt, int sendAttemptCount)
            {
                if (stopForTransportPause || stopForLiveRouteChange)
                {
                    return false;
                }

                while (pending.Count >= V4SenderPumpDepth ||
                       (pending.Count > 0 && pendingRawBytes + prepared.RawBytes > V4SenderPumpPendingBytes))
                {
                    var slotWaitStarted = Stopwatch.GetTimestamp();
                    await RetireNextAsync().ConfigureAwait(false);
                    if (stopForTransportPause || stopForLiveRouteChange)
                    {
                        return false;
                    }

                    var slotWaitMs = (long)Math.Max(0, Stopwatch.GetElapsedTime(slotWaitStarted).TotalMilliseconds);
                    lock (gate)
                    {
                        if (ReferenceEquals(outboundTransfer, context) && !context.IsTerminal)
                        {
                            context.PullSenderFeedPipelineSlotWaitMsRecent += slotWaitMs;
                        }
                    }
                }

                if (OutboundRegularV4PhysicalSendPreReservationBarrierForTests is { } preReservationBarrier)
                {
                    await preReservationBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
                }

                sendLifetimeToken.ThrowIfCancellationRequested();
                lock (gate)
                {
                    if (TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                            context,
                            out _,
                            out _))
                    {
                        MarkStopForTransportPauseLocked();
                        ObserveReceiveRecoveryPayloadHoldLocked(
                            "pre_reservation");
                        return false;
                    }

                    var blockForTransportPause = ShouldBlockOutboundV4TransportSendForTransportPauseLocked(context, repairSend);
                    if (!IsSourceSendScopeCurrentLocked() ||
                        !IsPumpInstallCurrentLocked() ||
                        context.UserPaused ||
                        context.PeerPaused ||
                        blockForTransportPause)
                    {
                        if (blockForTransportPause)
                        {
                            MarkStopForTransportPauseLocked();
                            ObserveReceiveRecoveryPayloadHoldLocked(
                                "pre_reservation_scope");
                        }

                        return false;
                    }

                    if (fallbackFrontierRepairContract is not null &&
                        !TryValidateOutboundFallbackFrontierDispatchLocked(
                            context,
                            fallbackFrontierRepairContract,
                            out var fallbackContractRejectionReason))
                    {
                        TrySettleFallbackFrontierRepairContract(
                            fallbackFrontierRepairContract,
                            FallbackFrontierRepairSettlementOutcome.StaleRejected,
                            fallbackContractRejectionReason);
                        return false;
                    }

                    if (!IsRegularV4FrontierRepairSubmissionCurrentLocked(
                            out var regularContractRejectionReason))
                    {
                        RejectRegularV4FrontierRepairSubmissionLocked(regularContractRejectionReason);
                        return false;
                    }
                }

                var scheduleStarted = Stopwatch.GetTimestamp();
                Task? sendTask = null;
                CancellationTokenSource? sendCts = null;
                FileTransferDataPathSendAuthority? sendAuthority = null;
                OutboundPhysicalSendLease? physicalSendLease = null;
                Task? physicalCompletionTask = null;
                Task physicalSendObservationTask = Task.CompletedTask;
                string? physicalSendLeaseRejectionReason = null;
                try
                {
                    var sendToken = sendLifetimeToken;
                    if (ShouldBoundOutboundV4TransportSend(context) ||
                        isRegularV4PeerSilenceSafetyRepair ||
                        (context.RouteRuntime.UsesRegularNknV4FastRuntime &&
                         context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
                         context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4))
                    {
                        sendCts = CancellationTokenSource.CreateLinkedTokenSource(sendLifetimeToken);
                        sendToken = sendCts.Token;
                    }

                    IFileTransferDataPathAuthoritySession? authoritySession = null;
                    Exception? sendException = null;
                    lock (gate)
                    {
                        if (TryGetOutboundReceiveRecoveryPayloadSubmissionHoldLocked(
                                context,
                                out _,
                                out _))
                        {
                            ObserveReceiveRecoveryPayloadHoldLocked(
                                "physical_submission");
                            physicalSendLeaseRejectionReason =
                                "filetransfer_receive_recovery_execution_current";
                        }
                        else if (!IsSourceSendScopeCurrentLocked() ||
                            !IsPumpInstallCurrentLocked())
                        {
                            sendException = new OperationCanceledException(sendToken);
                        }
                        else if (!IsRegularV4FrontierRepairSubmissionCurrentLocked(
                                     out var regularContractRejectionReason))
                        {
                            RejectRegularV4FrontierRepairSubmissionLocked(regularContractRejectionReason);
                            physicalSendLeaseRejectionReason = regularContractRejectionReason;
                        }
                        else
                        {
                            sendAuthority = CreateV4DataPathSendAuthorityLocked(context, "v4_transport_send");
                            if (context.RouteSelection.Route == FileTransferRoute.FileTunaV4 &&
                                sendAuthority is null)
                            {
                                sendException = new InvalidOperationException("File Tuna V4 data path authority is missing.");
                            }
                            else if (sendAuthority is not null &&
                                     dataSession is IFileTransferDataPathAuthoritySession candidateAuthoritySession)
                            {
                                authoritySession = candidateAuthoritySession;
                            }
                            else if (context.RouteSelection.Route == FileTransferRoute.FileTunaV4)
                            {
                                sendException = new InvalidOperationException("File Tuna V4 data path authority session is required.");
                            }

                            if (sendException is null &&
                                !TryRegisterOutboundPhysicalSendLeaseLocked(
                                    context,
                                    dataSession,
                                    prepared.StartChunkIndex,
                                    prepared.ChunkCount,
                                    repairSend,
                                    repairRequestKey,
                                    out physicalSendLease,
                                    out physicalSendLeaseRejectionReason))
                            {
                                physicalSendLease = null;
                            }

                            if (sendException is null &&
                                physicalSendLease is not null)
                            {
                                if (dataSession is
                                    IFileTransferPhysicalSendSubmissionSession
                                    physicalSubmissionSession)
                                {
                                    var submission =
                                        physicalSubmissionSession.SubmitPhysicalSend(
                                            prepared.Frame,
                                            sendAuthority,
                                            sendToken);
                                    sendTask = submission.DeliveryTask;
                                    physicalCompletionTask =
                                        submission.PhysicalCompletionTask;
                                }
                                else if (sendAuthority is not null &&
                                         authoritySession is not null)
                                {
                                    sendTask = authoritySession.SendAsync(
                                        prepared.Frame,
                                        sendAuthority,
                                        sendToken);
                                }
                                else
                                {
                                    sendTask = dataSession.SendAsync(
                                        prepared.Frame,
                                        sendToken);
                                }
                            }

                            if (physicalSendLease is not null &&
                                sendTask is not null)
                            {
                                physicalCompletionTask ??= sendTask;
                                physicalSendLease =
                                    BindOutboundPhysicalSendLeaseCompletionLocked(
                                        context,
                                        physicalSendLease,
                                        physicalCompletionTask);
                            }
                        }
                    }

                    if (physicalSendLeaseRejectionReason is not null)
                    {
                        sendCts?.Dispose();
                        return false;
                    }

                    if (sendException is not null)
                    {
                        sendTask = Task.FromException(sendException);
                    }
                    else if (sendTask is null)
                    {
                        sendTask = sendAuthority is not null &&
                                   authoritySession is not null
                            ? authoritySession.SendAsync(
                                prepared.Frame,
                                sendAuthority,
                                sendToken)
                            : dataSession.SendAsync(prepared.Frame, sendToken);
                    }
                }
                catch (Exception ex)
                {
                    sendCts?.Dispose();
                    sendCts = null;
                    sendTask = Task.FromException(ex);
                }

                sendTask ??= Task.FromException(
                    new InvalidOperationException(
                        "File-transfer physical send submission was not created."));

                if (physicalSendLease is not null)
                {
                    _ = ObserveOutboundPhysicalSendLeaseAsync(
                        context,
                        physicalSendLease,
                        physicalCompletionTask ?? sendTask);
                    physicalSendObservationTask = ObserveOutboundPhysicalSendFailureAsync(
                        context,
                        physicalSendLease,
                        sendTask);
                }

                var scheduledUtc = DateTimeOffset.UtcNow;
                var scheduleDurationMs = (long)Math.Max(0, Stopwatch.GetElapsedTime(scheduleStarted).TotalMilliseconds);
                var scheduledRegularNknV4FastRuntime =
                    context.RouteRuntime.UsesRegularNknV4FastRuntime &&
                    context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
                    context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4;
                observeSendAuthority?.Invoke(sendAuthority);
                pending.Enqueue(new PendingV4TransportSend(
                    prepared,
                    sendTask,
                    sendAuthority,
                    sendCts,
                    scheduledUtc,
                    sendAttempt,
                    sendAttemptCount,
                    scheduledRegularNknV4FastRuntime,
                    physicalSendLease?.LeaseGeneration ?? 0,
                    physicalSendObservationTask));
                pendingRawBytes += prepared.RawBytes;

                lock (gate)
                {
                    if (!ReferenceEquals(outboundTransfer, context) ||
                        context.IsTerminal ||
                        !IsPumpInstallCurrentLocked())
                    {
                        return false;
                    }

                    context.PullSenderPipelineConfiguredDepthRecent = V4SenderPumpDepth;
                    context.PullSenderPipelineEffectiveDepthRecent = V4SenderPumpDepth;
                    context.PullSenderPipelineScheduledFramesRecent++;
                    if (repairSend)
                    {
                        context.PullSenderV4RepairScheduledFramesRecent++;
                    }
                    else
                    {
                        context.PullSenderV4NormalScheduledFramesRecent++;
                    }

                    context.PullSenderFeedScheduleDurationMsRecent += scheduleDurationMs;
                    if (context.PullSenderFeedLastScheduleUtc is not null)
                    {
                        context.PullSenderFeedInterScheduleGapMsRecent.Add((long)Math.Max(
                            0,
                            (scheduledUtc - context.PullSenderFeedLastScheduleUtc.Value).TotalMilliseconds));
                    }

                    context.PullSenderFeedLastScheduleUtc = scheduledUtc;
                    context.PullSenderPipelineCurrentInFlightFrames++;
                    context.PullSenderPipelineCurrentInFlightBytes += prepared.RawBytes;
                    context.PullSenderPipelineMaxInFlightFramesRecent = Math.Max(
                        context.PullSenderPipelineMaxInFlightFramesRecent,
                        context.PullSenderPipelineCurrentInFlightFrames);
                    context.PullSenderPipelineMaxInFlightBytesRecent = Math.Max(
                        context.PullSenderPipelineMaxInFlightBytesRecent,
                        context.PullSenderPipelineCurrentInFlightBytes);
                    if (!repairSend)
                    {
                        var scheduledEndExclusive = prepared.StartChunkIndex + prepared.ChunkCount;
                        var acceptedProgressLagBytes = Math.Max(0, scheduledEndExclusive - context.ChunksAcceptedForTransport) *
                            (long)Math.Max(1, context.ChunkSizeBytes);
                        context.PullSenderPipelineMaxAcceptedProgressLagBytesRecent = Math.Max(
                            context.PullSenderPipelineMaxAcceptedProgressLagBytesRecent,
                            acceptedProgressLagBytes);
                    }
                }

                return true;
            }

            var primaryRegularNknFrontierAnchorBarrier =
                repairSend &&
                string.Equals(repairDeliveryReason, "primary_regular_nkn_frontier_first_send", StringComparison.Ordinal) &&
                ShouldUsePrimaryRegularNknBulkV6RepairProfileLocked(context);
            var primaryRegularNknFrontierAnchorBarrierUsed = false;
            var maxRepairBatchSegments = ResolveV4MaxBatchSegments(repairSend: true);

            for (var index = 0; index < chunkIndices.Count; index++)
            {
                sendLifetimeToken.ThrowIfCancellationRequested();
                if (repairSend)
                {
                    var originalIndex = index;
                    var currentRemoteFrontier = 0;
                    lock (gate)
                    {
                        if (!ReferenceEquals(outboundTransfer, context) ||
                            context.IsTerminal ||
                            !IsPumpInstallCurrentLocked())
                        {
                            break;
                        }

                        currentRemoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
                    }

                    while (index < chunkIndices.Count &&
                           chunkIndices[index] < currentRemoteFrontier)
                    {
                        index++;
                    }

                    if (index > originalIndex)
                    {
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_v4_repair_batch_obsolete_before_send; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; skipped_chunk_count={index - originalIndex}; previous_start_chunk_index={chunkIndices[originalIndex]}; next_start_chunk_index={(index < chunkIndices.Count ? chunkIndices[index] : -1)}; remote_next_expected_chunk_index={currentRemoteFrontier}; repair_delivery_mode={FormatV4RepairDeliveryMode(repairDeliveryMode)}; repair_delivery_escalation_reason={repairDeliveryReason}");
                    }

                    if (index >= chunkIndices.Count)
                    {
                        break;
                    }

                }

                lock (gate)
                {
                    var blockForTransportPause = ShouldBlockOutboundV4TransportSendForTransportPauseLocked(context, repairSend);
                    var blockNormalSendAheadForFileTunaV4PostTunaRecovery =
                        !repairSend &&
                        ReferenceEquals(outboundTransfer, context) &&
                        !context.IsTerminal &&
                        ShouldBlockOutboundV4NormalSendAheadForFileTunaV4PostTunaRecoveryLocked(context);
                    if (!ReferenceEquals(outboundTransfer, context) ||
                        context.IsTerminal ||
                        !IsPumpInstallCurrentLocked() ||
                        context.UserPaused ||
                        context.PeerPaused ||
                        blockForTransportPause ||
                        blockNormalSendAheadForFileTunaV4PostTunaRecovery)
                    {
                        if (blockForTransportPause)
                        {
                            MarkStopForTransportPauseLocked();
                            ObserveReceiveRecoveryPayloadHoldLocked(
                                "batch_selection");
                        }
                        else if (blockNormalSendAheadForFileTunaV4PostTunaRecovery)
                        {
                            context.SparseSenderPumpLastWakeReason = "file_tuna_v4_post_tuna_frontier_repair";
                            LocalOperationalLog.Info(
                                "FileTransferService",
                                $"event=filetransfer_v4_normal_send_blocked_for_file_tuna_v4_post_tuna_frontier_repair; transfer_id={context.TransferId}; session_id={context.SessionId}; rebind_generation={context.PullTransportRebindGeneration}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; repair_queue_depth={context.PullV4SenderPumpRepairQueue.Count}");
                        }

                        break;
                    }

                    if (fallbackFrontierRepairContract is not null &&
                        !TryValidateOutboundFallbackFrontierDispatchLocked(
                            context,
                            fallbackFrontierRepairContract,
                            out var fallbackContractRejectionReason))
                    {
                        TrySettleFallbackFrontierRepairContract(
                            fallbackFrontierRepairContract,
                            FallbackFrontierRepairSettlementOutcome.StaleRejected,
                            fallbackContractRejectionReason);
                        break;
                    }
                }

                var batchPrepareStarted = Stopwatch.GetTimestamp();
                var preparedBatch = await TryPrepareChunkBatchV4Async(
                    context,
                    stream,
                    chunkIndices,
                    index,
                    buffer,
                    repairSend,
                    repairRequestKey,
                    protocolRepairRequestId,
                    protocolPriority,
                    protocolRecoveryMode,
                    repairDeliveryMode,
                    fallbackFrontierRepairContract).ConfigureAwait(false);
                var batchPrepareDurationMs = (long)Math.Max(0, Stopwatch.GetElapsedTime(batchPrepareStarted).TotalMilliseconds);
                lock (gate)
                {
                    if (ReferenceEquals(outboundTransfer, context) &&
                        !context.IsTerminal &&
                        IsPumpInstallCurrentLocked())
                    {
                        context.PullSenderFeedBatchFramesPreparedRecent++;
                        context.PullSenderFeedChunkCountPreparedRecent += preparedBatch.ChunkCount;
                        context.PullSenderFeedRawBytesPreparedRecent += preparedBatch.RawBytes;
                        context.PullSenderFeedBatchPrepareDurationMsRecent += batchPrepareDurationMs;
                    }
                }

                if (repairSend)
                {
                    var currentRemoteFrontier = 0;
                    lock (gate)
                    {
                        if (!ReferenceEquals(outboundTransfer, context) ||
                            context.IsTerminal ||
                            !IsPumpInstallCurrentLocked())
                        {
                            break;
                        }

                        currentRemoteFrontier = Math.Clamp(context.RemoteNextExpectedChunkIndex, 0, context.ChunkCount);
                    }

                    var preparedEndExclusive = preparedBatch.StartChunkIndex + preparedBatch.ChunkCount;
                    if (preparedBatch.StartChunkIndex < currentRemoteFrontier)
                    {
                        LocalOperationalLog.Info(
                            "FileTransferService",
                            $"event=filetransfer_v4_repair_batch_obsolete_before_send; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; skipped_chunk_count={preparedBatch.ChunkCount}; previous_start_chunk_index={preparedBatch.StartChunkIndex}; next_start_chunk_index={(index + preparedBatch.ChunkCount < chunkIndices.Count ? chunkIndices[index + preparedBatch.ChunkCount] : -1)}; remote_next_expected_chunk_index={currentRemoteFrontier}; repair_delivery_mode={FormatV4RepairDeliveryMode(repairDeliveryMode)}; repair_delivery_escalation_reason={repairDeliveryReason}; source=prepared_batch_recheck");
                        index += preparedBatch.ChunkCount - 1;
                        continue;
                    }
                }

                var sendAttemptCount = repairSend ? V4RepairBatchSendAttempts : 1;
                for (var sendAttempt = 1; sendAttempt <= sendAttemptCount; sendAttempt++)
                {
                    if (!await ScheduleAsync(preparedBatch, sendAttempt, sendAttemptCount).ConfigureAwait(false))
                    {
                        completedWithoutTransportPause = false;
                        index = chunkIndices.Count;
                        break;
                    }
                }

                if (primaryRegularNknFrontierAnchorBarrier &&
                    !primaryRegularNknFrontierAnchorBarrierUsed &&
                    preparedBatch.StartChunkIndex == chunkIndices[0] &&
                    preparedBatch.ChunkCount <= maxRepairBatchSegments &&
                    index + preparedBatch.ChunkCount < chunkIndices.Count)
                {
                    primaryRegularNknFrontierAnchorBarrierUsed = true;
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_primary_regular_nkn_bulk_v6_frontier_repair_anchor_barrier; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; repair_request_key={repairRequestKey}; anchor_start_chunk_index={preparedBatch.StartChunkIndex}; anchor_chunk_count={preparedBatch.ChunkCount}; remaining_chunk_count={chunkIndices.Count - preparedBatch.ChunkCount}; repair_delivery_mode={FormatV4RepairDeliveryMode(repairDeliveryMode)}; repair_delivery_escalation_reason={repairDeliveryReason}");
                    while (pending.Count > 0)
                    {
                        await RetireNextAsync().ConfigureAwait(false);
                        if (stopForTransportPause || stopForLiveRouteChange)
                        {
                            completedWithoutTransportPause = false;
                            index = chunkIndices.Count;
                            break;
                        }
                    }
                }

                index += preparedBatch.ChunkCount - 1;

            }

            while (pending.Count > 0)
            {
                if (stopForTransportPause)
                {
                    completedWithoutTransportPause = false;
                    AbandonPendingForTransportPause();
                    break;
                }

                if (stopForLiveRouteChange)
                {
                    completedWithoutTransportPause = false;
                    AbandonPendingForLiveRouteChange();
                    break;
                }

                await RetireNextAsync().ConfigureAwait(false);
            }

            return completedWithoutTransportPause &&
                !stopForTransportPause &&
                !stopForLiveRouteChange;
        }
        finally
        {
            Array.Clear(buffer, 0, buffer.Length);
            ArrayPool<byte>.Shared.Return(buffer);
        }
    }

    private static async Task ObserveAbandonedOutboundV4TransportSendAsync(
        Task sendTask,
        CancellationTokenSource? sendCts,
        string transferId,
        string sessionId,
        int startChunkIndex,
        int chunkCount)
    {
        try
        {
            await sendTask.ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_abandoned_transport_send_observed; transfer_id={transferId}; session_id={sessionId}; start_chunk_index={startChunkIndex}; batch_chunk_count={chunkCount}; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");
        }
        finally
        {
            sendCts?.Dispose();
        }
    }

    private async Task<PreparedV4TransportSend> TryPrepareChunkBatchV4Async(
        OutboundTransferContext context,
        Stream stream,
        IReadOnlyList<int> chunkIndices,
        int startListIndex,
        byte[] buffer,
        bool repairSend,
        string repairRequestKey,
        string? protocolRepairRequestId,
        string? protocolPriority,
        string? protocolRecoveryMode,
        FileTransferV4RepairDeliveryMode repairDeliveryMode,
        FallbackFrontierRepairContract? fallbackFrontierRepairContract)
    {
        var startChunkIndex = chunkIndices[startListIndex];
        var expectedChunkIndex = startChunkIndex;
        var totalRawBytes = 0;
        var maxBatchSegments = ResolveV4MaxBatchSegments(repairSend);
        List<byte[]> dataSegments = [];
        for (var index = startListIndex; index < chunkIndices.Count && dataSegments.Count < maxBatchSegments; index++)
        {
            var chunkIndex = chunkIndices[index];
            if (chunkIndex != expectedChunkIndex)
            {
                break;
            }

            var chunkBytes = await LoadChunkBytesForSendAsync(context, stream, chunkIndex, buffer, repairSend).ConfigureAwait(false);
            var candidateRawBytes = totalRawBytes + chunkBytes.Length;
            if (candidateRawBytes > FileTransferProtocol.MaxChunkBatchRawBytesV4 ||
                !CanSerializeChunkBatchV4(
                    context.SessionId,
                    context.TransferId,
                    startChunkIndex,
                    dataSegments,
                    chunkBytes,
                    ShouldUseV6SparseCreditEnvelope(context)))
            {
                if (dataSegments.Count == 0)
                {
                    throw new InvalidOperationException("V4 chunk batch could not fit inside the transport payload budget.");
                }

                break;
            }

            dataSegments.Add(chunkBytes);
            totalRawBytes = candidateRawBytes;
            expectedChunkIndex++;
        }

        var unresolvedV6Epoch = IsV6TransportEpochUnresolved(context.V6TransportEpoch)
            ? context.V6TransportEpoch
            : null;
        var v6TransportEpoch = fallbackFrontierRepairContract?.Authority.TransportEpoch ??
            unresolvedV6Epoch?.EpochId ??
            context.V6TransportHandoff?.EpochId ??
            0;
        var v6RecoveryMode = fallbackFrontierRepairContract?.Authority.RecoveryMode ??
                             protocolRecoveryMode ??
                             (unresolvedV6Epoch is not null
                                 ? FormatV6TransportEpochState(unresolvedV6Epoch.State)
                                 : context.V6TransportHandoff is null
                                     ? null
                                     : FormatV6TransportHandoffState(context.V6TransportHandoff.State));
        var v6Priority = repairSend
            ? fallbackFrontierRepairContract?.Authority.Priority ??
              protocolPriority ??
              (unresolvedV6Epoch is not null
                  ? unresolvedV6Epoch.State == V6TransportEpochState.BackfillRepair
                      ? "backfill"
                      : "frontier"
                  : IsV6TransportHandoffBlockingTail(context.V6TransportHandoff)
                      ? "frontier"
                      : "repair")
            : null;

        FileTransferChunkBatchFrameV4 batch;
        if (ShouldUseV6SparseCreditEnvelope(context))
        {
            batch = new FileTransferChunkBatchFrameV6
            {
                SessionId = context.SessionId,
                TransferId = context.TransferId,
                StartChunkIndex = startChunkIndex,
                ChunkCount = dataSegments.Count,
                DataSegments = dataSegments,
                BatchProfile = repairSend
                    ? ResolveV4RepairBatchProfileName(maxBatchSegments)
                    : ResolveV4BatchProfileName(maxBatchSegments),
                RepairDeliveryMode = repairSend
                    ? repairDeliveryMode
                    : FileTransferV4RepairDeliveryMode.BulkOnly,
                TransportEpoch = v6TransportEpoch,
                BatchId = v6TransportEpoch <= 0
                    ? null
                    : $"v6:{v6TransportEpoch}:{startChunkIndex}:{dataSegments.Count}",
                RepairRequestId = repairSend
                    ? protocolRepairRequestId ??
                      fallbackFrontierRepairContract?.Authority.ProtocolRepairRequestId ??
                      repairRequestKey
                    : null,
                Priority = v6Priority,
                RecoveryMode = v6RecoveryMode,
            };
            _ = FileTransferDataFrameCodec.Serialize(batch);
        }
        else
        {
            batch = new FileTransferChunkBatchFrameV4
            {
                SessionId = context.SessionId,
                TransferId = context.TransferId,
                StartChunkIndex = startChunkIndex,
                ChunkCount = dataSegments.Count,
                DataSegments = dataSegments,
                BatchProfile = repairSend
                    ? ResolveV4RepairBatchProfileName(maxBatchSegments)
                    : ResolveV4BatchProfileName(maxBatchSegments),
                RepairDeliveryMode = repairSend
                    ? repairDeliveryMode
                    : FileTransferV4RepairDeliveryMode.BulkOnly,
                ForceRegularNknBulk = ShouldForceRegularNknBulkForV4Route(context),
            };
            _ = FileTransferDataFrameCodec.SerializeLegacyV4(batch);
        }
        return new PreparedV4TransportSend(batch, startChunkIndex, dataSegments.Count, totalRawBytes);
    }

    private static bool ShouldForceRegularNknBulkForV4Route(OutboundTransferContext context)
        => context.RouteRuntime.UsesRegularNknV4FastRuntime &&
           context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
           context.RouteRuntime.FrameFamily == FileTransferFrameFamily.V4;

    private int ResolveV4MaxBatchSegments(bool repairSend)
    {
        if (!repairSend && IsV4MixedScreenShareActive())
        {
            return sessionScreenShareDegraded
                ? V4MixedScreenShareDegradedBatchSegments
                : V4MixedScreenShareNormalBatchSegments;
        }

        var value = ReleaseOverridePolicy.ReadUnsafeEnvironmentVariable(V4MaxBatchSegmentsEnvironmentVariableName, category: "filetransfer_tuning");
        return int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed)
            ? Math.Clamp(parsed, V4MaxBatchSegmentsMin, V4MaxBatchSegmentsMax)
            : V4MaxBatchSegmentsDefault;
    }

    private static string ResolveV4BatchProfileName(int maxBatchSegments)
        => maxBatchSegments == V4MaxBatchSegmentsDefault
            ? "v4_default_21k"
            : $"v4_default_21k_{maxBatchSegments}x";

    private static string ResolveV4RepairBatchProfileName(int maxBatchSegments)
        => maxBatchSegments == V4MaxBatchSegmentsDefault
            ? "v4_repair_21k"
            : $"v4_repair_21k_{maxBatchSegments}x";

    private static bool CanSerializeChunkBatchV4(
        string sessionId,
        string transferId,
        int startChunkIndex,
        IReadOnlyList<byte[]> existingSegments,
        byte[] candidateSegment,
        bool useV6Envelope = true)
    {
        var candidateSegments = new byte[existingSegments.Count + 1][];
        for (var index = 0; index < existingSegments.Count; index++)
        {
            candidateSegments[index] = existingSegments[index];
        }

        candidateSegments[^1] = candidateSegment;
        try
        {
            FileTransferChunkBatchFrameV4 candidateBatch = useV6Envelope
                ? new FileTransferChunkBatchFrameV6
                {
                    SessionId = sessionId,
                    TransferId = transferId,
                    StartChunkIndex = startChunkIndex,
                    ChunkCount = candidateSegments.Length,
                    DataSegments = candidateSegments,
                }
                : new FileTransferChunkBatchFrameV4
                {
                    SessionId = sessionId,
                    TransferId = transferId,
                    StartChunkIndex = startChunkIndex,
                    ChunkCount = candidateSegments.Length,
                    DataSegments = candidateSegments,
                };
            _ = useV6Envelope
                ? FileTransferDataFrameCodec.Serialize(candidateBatch)
                : FileTransferDataFrameCodec.SerializeLegacyV4(candidateBatch);
            return true;
        }
        catch (InvalidOperationException)
        {
            return false;
        }
    }

    private static IReadOnlyList<FileTransferRangeV4> NormalizeV4MissingRangesForSend(
        IReadOnlyList<FileTransferRangeV4> ranges,
        int chunkCount,
        int maxMissingChunks = FileTransferProtocol.MaxStateMissingChunksV4)
    {
        if (ranges.Count == 0 || chunkCount <= 0)
        {
            return [];
        }

        var normalized = new List<FileTransferRangeV4>();
        var totalChunks = 0;
        foreach (var range in ranges
                     .Where(static range => range.ChunkCount > 0)
                     .OrderBy(static range => range.StartChunkIndex)
                     .ThenBy(static range => range.ChunkCount))
        {
            var start = Math.Clamp(range.StartChunkIndex, 0, chunkCount);
            var endExclusive = Math.Clamp(range.StartChunkIndex + range.ChunkCount, 0, chunkCount);
            if (endExclusive <= start)
            {
                continue;
            }

            if (normalized.Count > 0)
            {
                var previous = normalized[^1];
                var previousEnd = previous.StartChunkIndex + previous.ChunkCount;
                if (start <= previousEnd)
                {
                    var mergedEnd = Math.Max(previousEnd, endExclusive);
                    normalized[^1] = previous with { ChunkCount = mergedEnd - previous.StartChunkIndex };
                    continue;
                }
            }

            var count = endExclusive - start;
            var remaining = maxMissingChunks - totalChunks;
            if (remaining <= 0 || normalized.Count >= FileTransferProtocol.MaxStateMissingRangesV4)
            {
                break;
            }

            if (count > remaining)
            {
                count = remaining;
            }

            normalized.Add(new FileTransferRangeV4 { StartChunkIndex = start, ChunkCount = count });
            totalChunks += count;
        }

        return normalized;
    }

    private static IReadOnlyList<FileTransferRangeV4> SelectV4RepairRangesForSend(
        IReadOnlyList<FileTransferRangeV4> normalizedRanges,
        int remoteFrontier,
        int maxMissingChunks = FileTransferProtocol.MaxStateMissingChunksV4,
        bool frontierExclusive = false)
    {
        if (normalizedRanges.Count <= 1)
        {
            return normalizedRanges;
        }

        var selected = new List<FileTransferRangeV4>(normalizedRanges.Count);
        var selectedChunks = 0;
        foreach (var range in normalizedRanges)
        {
            var rangeEndExclusive = range.StartChunkIndex + range.ChunkCount;
            if (range.StartChunkIndex <= remoteFrontier && remoteFrontier < rangeEndExclusive)
            {
                var frontierCount = Math.Min(
                    rangeEndExclusive - remoteFrontier,
                    maxMissingChunks);
                selected.Add(
                    new FileTransferRangeV4
                    {
                        StartChunkIndex = remoteFrontier,
                        ChunkCount = frontierCount,
                    });
                selectedChunks += frontierCount;
                if (frontierExclusive)
                {
                    return selected;
                }

                break;
            }
        }

        foreach (var range in normalizedRanges)
        {
            if (selectedChunks >= maxMissingChunks)
            {
                break;
            }

            var start = range.StartChunkIndex;
            var endExclusive = range.StartChunkIndex + range.ChunkCount;
            if (start <= remoteFrontier && remoteFrontier < endExclusive)
            {
                start = remoteFrontier + Math.Min(endExclusive - remoteFrontier, maxMissingChunks);
            }

            if (endExclusive <= start)
            {
                continue;
            }

            var count = Math.Min(endExclusive - start, maxMissingChunks - selectedChunks);
            if (count <= 0)
            {
                continue;
            }

            selected.Add(new FileTransferRangeV4 { StartChunkIndex = start, ChunkCount = count });
            selectedChunks += count;
        }

        return selected.Count == 0 ? normalizedRanges : selected;
    }

    private static string FormatV4ChunkIndicesForLog(IReadOnlyList<int> chunkIndices)
        => chunkIndices.Count == 0
            ? "(none)"
            : string.Join(",", chunkIndices.Take(FileTransferProtocol.MaxStateMissingChunksV4));

    private static int ResolveV4RepairRequestMaxChunksForSend(OutboundTransferContext context, FileTransferStateFrameV4 state)
        => state is FileTransferReceiverStateFrameV6 &&
           ShouldUseV6RegularNknSparseRuntime(context) &&
           IsOutboundV6PrimaryRegularNknWithoutTunaRecoveryLocked(context)
            ? V6RegularNknSparseRuntimeRepairBurstMaxChunks
            : FileTransferProtocol.MaxStateMissingChunksV4;

    private static string CreateV4RepairRequestKey(
        string transferId,
        int firstStart,
        int requestedChunkCount,
        int frontier,
        int highestReceived,
        IReadOnlyList<FileTransferRangeV4> ranges)
    {
        _ = transferId;
        _ = frontier;
        _ = highestReceived;
        var rangeText = string.Join(",", ranges.Select(static range => $"{range.StartChunkIndex}:{range.ChunkCount}"));
        return $"{Math.Max(0, firstStart)}:{Math.Max(0, requestedChunkCount)}:{rangeText}";
    }

    private void SignalOutboundSparseSenderPump(
        OutboundTransferContext context,
        OutboundSparsePumpInstall? receiveInstall = null,
        RuntimeOwnerToken? receiveRuntimeOwner = null,
        IFileTransferDataSession? receiveDataSession = null,
        long receiveDataSessionGeneration = 0)
    {
        lock (gate)
        {
            if (ReferenceEquals(outboundTransfer, context) &&
                !context.IsTerminal &&
                (receiveDataSession is null ||
                 IsOutboundSparseReceiveResultCurrentLocked(
                     context,
                     receiveInstall,
                     receiveRuntimeOwner,
                     receiveDataSession,
                     receiveDataSessionGeneration,
                     out _)))
            {
                context.SignalSparseSenderPump();
            }
        }
    }

    private async Task StopOutboundSparseSenderPumpAsync(OutboundTransferContext context, Task? senderPumpTask)
    {
        if (senderPumpTask is null)
        {
            return;
        }

        context.SignalSparseSenderPump();
        try
        {
            await senderPumpTask.ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
        {
        }
    }

    private void ForceLogOutboundV4SenderPumpSummary(OutboundTransferContext context)
    {
        lock (gate)
        {
            if (ReferenceEquals(outboundTransfer, context))
            {
                MaybeLogOutboundV4SenderPumpSummaryLocked(context, DateTimeOffset.UtcNow, force: true);
            }
        }
    }

    private void MaybeLogOutboundV4SenderPumpSummaryLocked(OutboundTransferContext context, DateTimeOffset now, bool force)
    {
        if (!force &&
            context.LastSenderThroughputLogUtc is not null &&
            now - context.LastSenderThroughputLogUtc.Value < TimeSpan.FromMilliseconds(PullControlChatterWindowMs))
        {
            return;
        }

        if (!force &&
            context.PullSenderPipelineScheduledFramesRecent == 0 &&
            context.PullSenderPipelineCompletedFramesRecent == 0 &&
            context.PullSenderSendWaitCountRecent == 0)
        {
            MaybeObserveIdleRegularV4ControlFeedbackPressureLocked(context, now);
            return;
        }

        var availableCreditChunks = Math.Max(0, Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount) - context.ChunksAcceptedForTransport);
        var creditExhaustedTimeMs = context.V4SenderCreditExhaustedSinceUtc is null || availableCreditChunks > 0 || context.V4TerminalReady
            ? 0
            : (long)Math.Max(0, (now - context.V4SenderCreditExhaustedSinceUtc.Value).TotalMilliseconds);
        var pendingRepairCount = context.PullV4SenderPumpRepairQueue.Sum(static repair => repair.ChunkIndices.Count);
        _ = MaybeObserveRegularV4ControlFeedbackPressure(
            context,
            creditExhaustedTimeMs,
            availableCreditChunks,
            pendingRepairCount);
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v4_sender_pump_summary; transfer_id={context.TransferId}; session_id={context.SessionId}; sample_window_ms={PullControlChatterWindowMs}; configured_depth={V4SenderPumpDepth}; effective_depth={V4SenderPumpDepth}; in_flight_frames={context.PullSenderPipelineCurrentInFlightFrames}; in_flight_bytes={context.PullSenderPipelineCurrentInFlightBytes}; scheduled_frames={context.PullSenderPipelineScheduledFramesRecent}; normal_scheduled_frames={context.PullSenderV4NormalScheduledFramesRecent}; repair_scheduled_frames={context.PullSenderV4RepairScheduledFramesRecent}; completed_frames={context.PullSenderPipelineCompletedFramesRecent}; failed_frames={context.PullSenderPipelineFailedFramesRecent}; raw_bytes_sent={context.PullSenderRawBytesRecent}; batch_frames_sent={context.PullSenderBatchFramesRecent}; chunk_count_sent={context.PullSenderChunkCountRecent}; repair_send_count={context.PullSenderRepairSendCountRecent}; send_wait_count={context.PullSenderSendWaitCountRecent}; raw_bytes_sent_total={context.PullSenderRawBytesTotal}; normal_raw_bytes_sent_total={context.PullSenderNormalRawBytesTotal}; repair_raw_bytes_sent_total={context.PullSenderRepairRawBytesTotal}; batch_frames_sent_total={context.PullSenderBatchFramesTotal}; normal_batch_frames_sent_total={context.PullSenderNormalBatchFramesTotal}; repair_batch_frames_sent_total={context.PullSenderRepairBatchFramesTotal}; chunk_count_sent_total={context.PullSenderChunkCountTotal}; normal_chunk_count_sent_total={context.PullSenderNormalChunkCountTotal}; repair_chunk_count_sent_total={context.PullSenderRepairChunkCountTotal}; send_wait_count_total={context.PullSenderSendWaitCountTotal}; failed_frames_total={context.PullSenderPipelineFailedFramesTotal}; credit_exhausted_time_ms={creditExhaustedTimeMs}; available_credit_chunks={availableCreditChunks}; available_credit_bytes={availableCreditChunks * (long)Math.Max(1, context.ChunkSizeBytes)}; next_unsent_chunk_index={context.ChunksAcceptedForTransport}; credit_ceiling_chunk_index={context.RemoteGrantedUntilExclusive}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; terminal_ready={(context.V4TerminalReady ? 1 : 0)}; pump_wake_reason={context.SparseSenderPumpLastWakeReason}; repair_request_key={context.V4SenderPumpLastRepairRequestKey}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; remote_credit_until_chunk_index_exclusive={context.RemoteGrantedUntilExclusive}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; pending_repair_count={pendingRepairCount}; sent_cache_chunk_count={context.PullSentChunkCache.Count}; sent_cache_bytes={context.PullSentChunkCacheBytes}");
        context.LastSenderThroughputLogUtc = now;

        context.PullSenderPipelineScheduledFramesRecent = 0;
        context.PullSenderV4NormalScheduledFramesRecent = 0;
        context.PullSenderV4RepairScheduledFramesRecent = 0;
        context.PullSenderPipelineCompletedFramesRecent = 0;
        context.PullSenderPipelineFailedFramesRecent = 0;
        context.PullSenderRawBytesRecent = 0;
        context.PullSenderBatchFramesRecent = 0;
        context.PullSenderChunkCountRecent = 0;
        context.PullSenderRepairSendCountRecent = 0;
        context.PullSenderSendWaitCountRecent = 0;
    }

    private void MaybeObserveIdleRegularV4ControlFeedbackPressureLocked(OutboundTransferContext context, DateTimeOffset now)
    {
        if (context.PullV4LastRegularNknControlFeedbackPressureObservedUtc is { } lastObserved &&
            now - lastObserved < TimeSpan.FromMilliseconds(PullControlChatterWindowMs))
        {
            return;
        }

        var availableCreditChunks = Math.Max(
            0,
            Math.Min(context.RemoteGrantedUntilExclusive, context.ChunkCount) - context.ChunksAcceptedForTransport);
        var creditExhaustedTimeMs = context.V4SenderCreditExhaustedSinceUtc is null || availableCreditChunks > 0 || context.V4TerminalReady
            ? 0
            : (long)Math.Max(0, (now - context.V4SenderCreditExhaustedSinceUtc.Value).TotalMilliseconds);
        var pendingRepairCount = context.PullV4SenderPumpRepairQueue.Sum(static repair => repair.ChunkIndices.Count);
        _ = MaybeObserveRegularV4ControlFeedbackPressure(
            context,
            creditExhaustedTimeMs,
            availableCreditChunks,
            pendingRepairCount);
    }

    private bool MaybeObserveRegularV4ControlFeedbackPressure(
        OutboundTransferContext context,
        long creditExhaustedTimeMs,
        int availableCreditChunks,
        int pendingRepairCount)
    {
        var now = DateTimeOffset.UtcNow;
        var frontierLagChunks = Math.Max(0, context.ChunksAcceptedForTransport - context.RemoteNextExpectedChunkIndex);
        var activeRepairRequestCount = context.PullV4SenderPumpRepairRequests.Count;
        var effectivePendingRepairCount = Math.Max(pendingRepairCount, activeRepairRequestCount);
        var lastGrantSilenceMs = context.PullV4LastGrantReceivedUtc is null
            ? 0
            : (long)Math.Max(0, (now - context.PullV4LastGrantReceivedUtc.Value).TotalMilliseconds);
        var creditFrontierPressure = availableCreditChunks <= 0 &&
            creditExhaustedTimeMs >= PullV4RegularNknControlFeedbackPressureMinCreditExhaustedMs &&
            (frontierLagChunks >= PullV4RegularNknControlFeedbackPressureMinFrontierLagChunks ||
             effectivePendingRepairCount > 0);
        var remoteFrontierPressure = availableCreditChunks > 0 &&
            frontierLagChunks >= PullV4RegularNknControlFeedbackPressureMinFrontierLagChunks &&
            (effectivePendingRepairCount > 0 ||
             lastGrantSilenceMs >= PullControlChatterWindowMs * 2L);

        if (!IsCurrentV4FrontierRepairRuntime(context) ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.V4TerminalReady ||
            (!creditFrontierPressure && !remoteFrontierPressure))
        {
            return false;
        }

        IFileTransferRegularV4ControlFeedbackPressureObserver? observer;
        lock (gate)
        {
            observer = transport as IFileTransferRegularV4ControlFeedbackPressureObserver;
        }

        if (observer is null)
        {
            return false;
        }

        var routePrefix = IsCurrentFileTunaV4FrontierRepairLeg(context.CurrentTransferLeg)
            ? "file_tuna_v4"
            : "regular_v4";
        var pressureReason = remoteFrontierPressure && !creditFrontierPressure
            ? $"{routePrefix}_sender_remote_frontier_pressure"
            : $"{routePrefix}_credit_frontier_pressure";
        var replayQueued = MaybeQueueOutboundRegularNknV4PeerSilenceSafetyReplayLocked(context, pressureReason);
        if (replayQueued)
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_regular_v4_feedback_pressure_replay_armed; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={FormatProtocolLogValue(pressureReason)}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; remote_next_expected_chunk_index={context.RemoteNextExpectedChunkIndex}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; frontier_lag_chunks={frontierLagChunks}; available_credit_chunks={availableCreditChunks}; pending_repair_count={effectivePendingRepairCount}");
        }

        if (!pressureReason.EndsWith("_sender_remote_frontier_pressure", StringComparison.Ordinal) &&
            context.CurrentRegularV4FrontierRepairContract is { } currentContract &&
            TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                currentContract.Authority.AuthorityId,
                out var installedBinding,
                out _,
                out var installReceipt) &&
            IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                currentContract,
                currentContract.Authority.PredecessorAuthorityId,
                installedBinding.PressureReason,
                installReceipt,
                out _))
        {
            context.PullV4LastRegularNknControlFeedbackPressureObservedUtc = now;
            return true;
        }

        observer.ObserveRegularV4ControlFeedbackPressure(new FileTransferRegularV4ControlFeedbackPressure(
            context.SessionId,
            context.TransferId,
            creditExhaustedTimeMs,
            frontierLagChunks,
            effectivePendingRepairCount,
            pressureReason,
            GetCurrentRegularV4FrontierRepairAuthority(context)));
        context.PullV4LastRegularNknControlFeedbackPressureObservedUtc = now;
        return true;
    }

    private void ObserveRegularV4FrontierRepairDispatchBlocker(
        OutboundTransferContext context,
        FileTransferRegularV4FrontierRepairAuthority authority,
        int pendingRepairCount,
        string reason)
    {
        if (!string.Equals(authority.RouteToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) ||
            authority.ProtocolVersion != FileTransferProtocol.ProtocolVersionV4)
        {
            return;
        }

        lock (gate)
        {
            var rejectionReason = "contract_replaced_or_terminal";
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.CurrentRegularV4FrontierRepairContract is not { } currentContract ||
                currentContract.Authority.AuthorityId != authority.AuthorityId ||
                currentContract.Lifecycle.IsSettled ||
                !IsRegularV4FrontierRepairContractCurrent(context, currentContract, out rejectionReason))
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_regular_v4_frontier_repair_pressure_forward_rejected; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; transfer_id={FormatProtocolLogValue(authority.TransferId)}; session_id={FormatProtocolLogValue(authority.SessionId)}; decision_reason={FormatProtocolLogValue(rejectionReason)}");
                return;
            }

            if (TryGetInstalledRegularV4FrontierRepairPressure(
                    CreateCoordinatorStateLocked(context),
                    currentContract.Authority.AuthorityId,
                    out var installedBinding,
                    out _,
                    out var installReceipt) &&
                IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                    currentContract,
                    currentContract.Authority.PredecessorAuthorityId,
                    installedBinding.PressureReason,
                    installReceipt,
                    out _))
            {
                return;
            }

            if (transport is not IFileTransferRegularV4ControlFeedbackPressureObserver observer)
            {
                return;
            }

            observer.ObserveRegularV4ControlFeedbackPressure(new FileTransferRegularV4ControlFeedbackPressure(
                authority.SessionId,
                authority.TransferId,
                CreditExhaustedTimeMs: 0,
                Math.Max(0, authority.DurableReceivedHighestChunkIndex - authority.FrontierChunkIndex + 1),
                Math.Max(1, pendingRepairCount),
                reason,
                authority));
        }
    }

    private bool TryRegisterOutboundPhysicalSendLeaseLocked(
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        int startChunkIndex,
        int chunkCount,
        bool repairSend,
        string repairRequestKey,
        out OutboundPhysicalSendLease? lease,
        out string? rejectionReason)
    {
        lease = null;
        rejectionReason = null;
        if (!TryResolveOutboundPhysicalSendKindLocked(
                context,
                repairSend,
                out var sendKind))
        {
            return true;
        }

        var coordinatorState = CreateCoordinatorStateLocked(context);
        if (FileTransferCoordinator.IsFileTransferRouteTransitionDraining(
                coordinatorState,
                out var drainingAuthority))
        {
            rejectionReason = drainingAuthority.Kind ==
                              FileTransferRouteTransitionKind.RegularV4ToTunaV4
                ? "regular_v4_to_tuna_transition_draining"
                : "filetransfer_route_transition_draining";
            LogOutboundPhysicalSendLeaseRegistration(
                ResolveOutboundPhysicalSendLeaseEventName(sendKind, rejected: true),
                context,
                dataSession,
                startChunkIndex,
                chunkCount,
                sendKind,
                repairRequestKey,
                leaseGeneration: 0,
                drainingAuthority,
                rejectionReason);
            return false;
        }

        if (!ReferenceEquals(outboundTransfer, context) ||
            context.IsTerminal ||
            !ReferenceEquals(context.DataSession, dataSession) ||
            context.CurrentRuntimeOwner is not { IsDefault: false } runtimeOwner ||
            context.CurrentRoutePublicationToken is not { IsDefault: false } routePublication ||
            context.CurrentTransferLeg is not { } leg ||
            runtimeOwner.Route != context.RouteSelection.Route ||
            runtimeOwner.ProtocolVersion != context.NegotiatedDataProtocolVersion ||
            !FileTransferCoordinator.IsRuntimeOwnerCurrent(
                coordinatorState,
                runtimeOwner,
                out _) ||
            !FileTransferCoordinator.IsRoutePublicationTokenCurrent(
                coordinatorState,
                routePublication,
                out _))
        {
            rejectionReason = "physical_send_scope_missing";
            return false;
        }

        var leaseGeneration = Math.Max(
            1,
            context.LastOutboundPhysicalSendLeaseGeneration + 1);
        context.LastOutboundPhysicalSendLeaseGeneration = leaseGeneration;
        lease = new OutboundPhysicalSendLease(
            leaseGeneration,
            runtimeOwner,
            routePublication,
            context.TerminalGeneration,
            leg.Generation,
            leg.TransportEpochId,
            leg.BridgeRecoveryGeneration,
            dataSession,
            context.DataSessionGeneration,
            startChunkIndex,
            chunkCount,
            sendKind,
            repairRequestKey);
        context.ActiveOutboundPhysicalSendLeases[leaseGeneration] = lease;
        context.OutboundPhysicalSendRegisteredCount++;
        LogOutboundPhysicalSendLeaseRegistration(
            ResolveOutboundPhysicalSendLeaseEventName(sendKind, rejected: false),
            context,
            dataSession,
            startChunkIndex,
            chunkCount,
            sendKind,
            repairRequestKey,
            leaseGeneration,
            transitionAuthority: null,
            "physical_send_lease_registered");
        return true;
    }

    private static OutboundPhysicalSendLease BindOutboundPhysicalSendLeaseCompletionLocked(
        OutboundTransferContext context,
        OutboundPhysicalSendLease lease,
        Task physicalCompletionTask)
    {
        if (!context.ActiveOutboundPhysicalSendLeases.TryGetValue(
                lease.LeaseGeneration,
                out var currentLease))
        {
            return lease;
        }

        if (currentLease.PhysicalCompletionTask is { } existingCompletionTask)
        {
            return ReferenceEquals(existingCompletionTask, physicalCompletionTask)
                ? currentLease
                : lease;
        }

        var boundLease = currentLease with
        {
            PhysicalCompletionTask = physicalCompletionTask,
        };
        context.ActiveOutboundPhysicalSendLeases[boundLease.LeaseGeneration] = boundLease;
        return boundLease;
    }

    private static bool TryResolveOutboundPhysicalSendKindLocked(
        OutboundTransferContext context,
        bool repairSend,
        out OutboundPhysicalSendKind sendKind)
    {
        sendKind = default;
        sendKind = context.RouteSelection.Route switch
        {
            FileTransferRoute.RegularNknV4Fast
                when context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 =>
                repairSend
                    ? OutboundPhysicalSendKind.RegularV4Repair
                    : OutboundPhysicalSendKind.RegularV4Payload,
            FileTransferRoute.FileTunaV4
                when context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 =>
                repairSend
                    ? OutboundPhysicalSendKind.TunaV4Repair
                    : OutboundPhysicalSendKind.TunaV4Payload,
            FileTransferRoute.PostTunaFallbackV6
                when context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV6 =>
                repairSend
                    ? OutboundPhysicalSendKind.PostTunaFallbackV6Repair
                    : OutboundPhysicalSendKind.PostTunaFallbackV6Payload,
            _ => default,
        };
        return sendKind != default;
    }

    private static bool IsRepairOutboundPhysicalSendKind(OutboundPhysicalSendKind sendKind)
        => sendKind is
            OutboundPhysicalSendKind.RegularV4Repair or
            OutboundPhysicalSendKind.TunaV4Repair or
            OutboundPhysicalSendKind.PostTunaFallbackV6Repair;

    private static string ResolveOutboundPhysicalSendLeaseEventName(
        OutboundPhysicalSendKind sendKind,
        bool rejected)
        => sendKind is
                OutboundPhysicalSendKind.RegularV4Payload or
                OutboundPhysicalSendKind.RegularV4Repair
            ? rejected
                ? "filetransfer_regular_v4_physical_send_lease_rejected"
                : "filetransfer_regular_v4_physical_send_lease_registered"
            : rejected
                ? "filetransfer_outbound_physical_send_lease_rejected"
                : "filetransfer_outbound_physical_send_lease_registered";

    private static void LogOutboundPhysicalSendLeaseRegistration(
        string eventName,
        OutboundTransferContext context,
        IFileTransferDataSession dataSession,
        int startChunkIndex,
        int chunkCount,
        OutboundPhysicalSendKind sendKind,
        string repairRequestKey,
        long leaseGeneration,
        FileTransferRouteTransitionAuthority? transitionAuthority,
        string reason)
    {
        var owner = context.CurrentRuntimeOwner;
        var publication = context.CurrentRoutePublicationToken;
        var leg = context.CurrentTransferLeg;
        var genericEventName = eventName.EndsWith(
            "_rejected",
            StringComparison.Ordinal)
            ? "filetransfer_route_transition_physical_send_lease_rejected"
            : "filetransfer_route_transition_physical_send_lease_registered";
        var fields =
            $"direction=outbound; session_id={FormatProtocolLogValue(context.SessionId)}; transfer_id={FormatProtocolLogValue(context.TransferId)}; send_lease_generation={leaseGeneration}; transition_authority_id={FormatProtocolLogValue(transitionAuthority?.AuthorityId.ToString() ?? "(none)")}; transition_generation={transitionAuthority?.TransitionGeneration ?? 0}; source_route={FormatProtocolLogValue(owner?.RouteToken ?? "(none)")}; source_protocol_version={owner?.ProtocolVersion ?? 0}; source_live_route_epoch={owner?.LiveRouteEpoch ?? 0}; source_runtime_generation={owner?.RuntimeGeneration ?? 0}; source_route_publication_generation={publication?.PublicationGeneration ?? 0}; source_terminal_generation={context.TerminalGeneration}; source_leg_generation={leg?.Generation ?? 0}; source_transport_epoch={leg?.TransportEpochId ?? 0}; source_bridge_recovery_generation={leg?.BridgeRecoveryGeneration ?? 0}; source_data_session_generation={context.DataSessionGeneration}; data_session_current={(ReferenceEquals(context.DataSession, dataSession) ? 1 : 0)}; start_chunk_index={startChunkIndex}; chunk_count={chunkCount}; send_kind={FormatProtocolLogValue(sendKind.ToString())}; repair_send={(IsRepairOutboundPhysicalSendKind(sendKind) ? 1 : 0)}; repair_request_key={FormatProtocolLogValue(repairRequestKey)}; decision_reason={FormatProtocolLogValue(reason)}";
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event={genericEventName}; {fields}");
        if (!string.Equals(eventName, genericEventName, StringComparison.Ordinal))
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event={eventName}; {fields}");
        }
    }

    private async Task ObserveOutboundPhysicalSendLeaseAsync(
        OutboundTransferContext context,
        OutboundPhysicalSendLease lease,
        Task physicalCompletionTask)
    {
        lock (gate)
        {
            if (!context.ActiveOutboundPhysicalSendLeases.TryGetValue(
                    lease.LeaseGeneration,
                    out var currentLease))
            {
                return;
            }

            if (currentLease.PhysicalCompletionTask is { } existingCompletionTask)
            {
                if (!ReferenceEquals(existingCompletionTask, physicalCompletionTask))
                {
                    return;
                }

                lease = currentLease;
            }
            else
            {
                lease = currentLease with { PhysicalCompletionTask = physicalCompletionTask };
                context.ActiveOutboundPhysicalSendLeases[lease.LeaseGeneration] = lease;
            }
        }

        try
        {
            await physicalCompletionTask.ConfigureAwait(false);
        }
        catch
        {
            // Delivery status remains observable through the sender pipeline; this observer owns only drain proof.
        }
        finally
        {
            lock (gate)
            {
                if (context.ActiveOutboundPhysicalSendLeases.Remove(lease.LeaseGeneration))
                {
                    context.OutboundPhysicalSendRetiredCount++;
                    LogOutboundPhysicalSendLeaseRetired(context, lease);
                    if (FileTransferCoordinator
                            .GetFileTransferRouteTransitionSubstate(
                                CreateCoordinatorStateLocked(context))
                            .CurrentOperation is
                        {
                            State: FileTransferRouteTransitionState.Draining,
                            Authority: { } transitionAuthority,
                            PauseBindReceipt: { } pauseReceipt,
                            DrainCommand: { } drainCommand,
                        } &&
                        drainCommand.CapturedPhysicalSendLeaseIds.Contains(
                            lease.LeaseGeneration))
                    {
                        EnqueueRouteTransitionAuthorityEffect(
                            context,
                            transitionAuthority,
                            "physical_send_lease_retired",
                            $"lease:{lease.LeaseGeneration}",
                            pauseReceipt.Status.ToString(),
                            pauseReceipt,
                            $"{transitionAuthority.AuthorityId}:pause_bind");
                    }
                    RecheckOutboundFileTransferRouteTransitionAfterPhysicalSendLocked(
                        context,
                        lease);
                }
            }
        }

    }

    private async Task ObserveOutboundPhysicalSendFailureAsync(
        OutboundTransferContext context,
        OutboundPhysicalSendLease lease,
        Task deliveryTask)
    {
        try
        {
            await deliveryTask.ConfigureAwait(false);
            return;
        }
        catch (Exception exception)
        {
            var unavailable = FindDataSessionSubmissionUnavailableException(exception);
            if (unavailable is null || !unavailable.RecoveryBarrierActive)
            {
                return;
            }

            lock (gate)
            {
                if (!ReferenceEquals(outboundTransfer, context) ||
                    context.IsTerminal ||
                    context.InstalledOutboundSparsePump is not { } currentInstall ||
                    currentInstall.RuntimeOwner != lease.RuntimeOwner ||
                    currentInstall.RoutePublication != lease.RoutePublication ||
                    currentInstall.TerminalGeneration != lease.TerminalGeneration ||
                    currentInstall.LegGeneration != lease.LegGeneration ||
                    currentInstall.DataSessionGeneration != lease.DataSessionGeneration ||
                    !ReferenceEquals(lease.DataSession, context.DataSession) ||
                    !TryCreateReceiveRecoverySubmissionFailureObservationLocked(
                        context,
                        currentInstall,
                        lease.DataSession,
                        lease.LeaseGeneration,
                        lease.RepairRequestKey,
                        unavailable,
                        DateTimeOffset.UtcNow,
                        out var observation) ||
                    context.ReceiveRecoverySubmissionFailureObservations.ContainsKey(
                        lease.LeaseGeneration))
                {
                    return;
                }

                context.ReceiveRecoverySubmissionFailureObservations[
                    lease.LeaseGeneration] = observation;
                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_post_tuna_fallback_recovery_submission_failure_observed; decision_status=Accepted; decision_reason=current_post_tuna_fallback_recovery_submission_failure_observed; direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; receive_recovery_operation_authority_id={FormatProtocolLogValue(observation.Authority.AuthorityId.ToString())}; receive_recovery_operation_generation={observation.Authority.OperationGeneration}; physical_send_lease_generation={observation.PhysicalSendLeaseGeneration}; send_kind={FormatProtocolLogValue(observation.SendKind)}; repair_request_key={FormatProtocolLogValue(observation.RepairRequestKey)}; typed_rejection_reason={FormatProtocolLogValue(observation.RejectionReason.ToString())}; rejection_stage={FormatProtocolLogValue(observation.RejectionStage)}; rejection_channel={FormatProtocolLogValue(observation.RejectionChannel)}; expected_submission_epoch={observation.ExpectedSubmissionEpoch}; current_submission_epoch={observation.CurrentSubmissionEpoch}; expected_process_epoch={observation.ExpectedProcessEpoch}; current_process_epoch={observation.CurrentProcessEpoch}; recovery_barrier_active=1; observed_utc_ms={observation.ObservedUtcMs}; route={FormatProtocolLogValue(observation.RuntimeOwner.RouteToken)}; protocol_version={observation.RuntimeOwner.ProtocolVersion}; live_route_epoch={observation.RuntimeOwner.LiveRouteEpoch}; runtime_generation={observation.RuntimeOwner.RuntimeGeneration}; route_publication_generation={observation.RoutePublication.PublicationGeneration}; terminal_generation={observation.TerminalGeneration}; leg_generation={observation.LegGeneration}; transport_epoch={observation.TransportEpoch}; bridge_recovery_generation={observation.BridgeRecoveryGeneration}; checkpoint_request_id={FormatProtocolLogValue(observation.Authority.ExecutionCommand.CheckpointRequestId ?? "(none)")}; data_session_generation={observation.DataSessionGeneration}");
            }
        }
    }

    private static void LogOutboundPhysicalSendLeaseRetired(
        OutboundTransferContext context,
        OutboundPhysicalSendLease lease)
    {
        var fields =
            $"direction=outbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; send_lease_generation={lease.LeaseGeneration}; source_route={FormatProtocolLogValue(lease.RuntimeOwner.RouteToken)}; source_protocol_version={lease.RuntimeOwner.ProtocolVersion}; source_live_route_epoch={lease.RuntimeOwner.LiveRouteEpoch}; source_runtime_generation={lease.RuntimeOwner.RuntimeGeneration}; source_terminal_generation={lease.TerminalGeneration}; source_leg_generation={lease.LegGeneration}; source_transport_epoch={lease.TransportEpoch}; source_bridge_recovery_generation={lease.BridgeRecoveryGeneration}; source_route_publication_generation={lease.RoutePublication.PublicationGeneration}; source_route_commit_generation={lease.RoutePublication.RouteCommitGeneration ?? 0}; source_data_session_generation={lease.DataSessionGeneration}; start_chunk_index={lease.StartChunkIndex}; chunk_count={lease.ChunkCount}; send_kind={FormatProtocolLogValue(lease.SendKind.ToString())}; repair_send={(IsRepairOutboundPhysicalSendKind(lease.SendKind) ? 1 : 0)}; repair_request_key={FormatProtocolLogValue(lease.RepairRequestKey)}; registered_send_count={context.OutboundPhysicalSendRegisteredCount}; retired_send_count={context.OutboundPhysicalSendRetiredCount}; decision_reason=physical_send_task_completed";
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_route_transition_physical_send_lease_retired; {fields}");
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_outbound_physical_send_lease_retired; {fields}");
    }

    private bool TryInstallRegularV4FrontierRepairPressureLocked(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        RegularV4FrontierRepairContract? predecessorContract,
        int frontierLagChunks,
        int pendingRepairCount,
        string pressureReason,
        string installBoundary)
    {
        if (!IsRegularV4FrontierRepairPressureInstallScopeCurrentLocked(
                context,
                contract,
                out var rejectionReason))
        {
            LogRegularV4FrontierRepairPressureInstallScopeRejected(
                contract,
                predecessorContract,
                frontierLagChunks,
                pendingRepairCount,
                pressureReason,
                installBoundary,
                rejectionReason);
            return false;
        }

        if (!TryStageRegularV4FrontierRepairPressureBindingLocked(
                context,
                contract,
                pressureReason,
                installBoundary,
                out var installCommand))
        {
            return false;
        }
        frontierLagChunks = installCommand.Pressure.FrontierLagChunks;
        pendingRepairCount = installCommand.Pressure.PendingRepairCount;
        pressureReason = installCommand.Pressure.Reason;

        if (!TryInstallRegularV4FrontierRepairPressureCoreLocked(
            contract,
            predecessorContract,
            frontierLagChunks,
            pendingRepairCount,
            pressureReason,
            installBoundary,
            installCommand,
            out var installReceipt))
        {
            return false;
        }

        return TryCommitRegularV4FrontierRepairPressureBindingLocked(
            context,
            contract,
            installReceipt,
            installBoundary);
    }

