    private bool TryStageRegularV4FrontierRepairPressureBindingLocked(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        string pressureReason,
        string installBoundary,
        out FileTransferRegularV4FrontierRepairPressureInstallCommand installCommand)
        => TryUseCoordinatorStagedRegularV4FrontierRepairPressureBinding(
            CreateCoordinatorStateLocked(context),
            contract,
            pressureReason,
            installBoundary,
            out installCommand);

    private bool TryStageRegularV4FrontierRepairPressureBindingLocked(
        InboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        string pressureReason,
        string installBoundary,
        out FileTransferRegularV4FrontierRepairPressureInstallCommand installCommand)
        => TryUseCoordinatorStagedRegularV4FrontierRepairPressureBinding(
            CreateCoordinatorStateLocked(context),
            contract,
            pressureReason,
            installBoundary,
            out installCommand);

    private static bool TryUseCoordinatorStagedRegularV4FrontierRepairPressureBinding(
        FileTransferCoordinatorState state,
        RegularV4FrontierRepairContract contract,
        string pressureReason,
        string installBoundary,
        out FileTransferRegularV4FrontierRepairPressureInstallCommand installCommand)
    {
        installCommand = null!;
        var normalizedPressureReason = string.IsNullOrWhiteSpace(pressureReason)
            ? "unknown"
            : pressureReason.Trim();
        if (!TryGetPendingOrInstalledRegularV4FrontierRepairPressure(
                state,
                contract.Authority.AuthorityId,
                out var currentBinding,
                out var currentCommand) ||
            currentBinding.Authority != contract.Authority ||
            !string.Equals(
                currentBinding.PressureReason,
                normalizedPressureReason,
                StringComparison.Ordinal))
        {
            LogRegularV4FrontierRepairPressureBinding(
                "filetransfer_regular_v4_frontier_repair_pressure_binding_invalidated",
                contract.Authority,
                binding: null,
                installBoundary,
                "regular_v4_frontier_repair_pressure_binding_not_current");
            return false;
        }

        installCommand = currentCommand;
        LogRegularV4FrontierRepairPressureBinding(
            "filetransfer_regular_v4_frontier_repair_pressure_binding_staged",
            contract.Authority,
            currentBinding,
            installBoundary,
            currentBinding.State == RegularV4FrontierRepairPressureBindingState.Pending
                ? "regular_v4_frontier_repair_pressure_binding_staged"
                : "regular_v4_frontier_repair_pressure_binding_already_committed");
        return true;
    }

    private bool TryCommitRegularV4FrontierRepairPressureBindingLocked(
        OutboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        FileTransferRegularV4FrontierRepairPressureInstallReceipt receipt,
        string installBoundary)
    {
        var decision = FileTransferCoordinator.CommitRegularV4FrontierRepairPressureBinding(
            CreateCoordinatorStateLocked(context),
            receipt);
        _ = AdoptCoordinatorStateLocked(context, decision);
        return CommitRegularV4FrontierRepairPressureBindingDecision(
            contract,
            decision,
            installBoundary);
    }

    private bool TryCommitRegularV4FrontierRepairPressureBindingLocked(
        InboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        FileTransferRegularV4FrontierRepairPressureInstallReceipt receipt,
        string installBoundary)
    {
        var decision = FileTransferCoordinator.CommitRegularV4FrontierRepairPressureBinding(
            CreateCoordinatorStateLocked(context),
            receipt);
        _ = AdoptCoordinatorStateLocked(context, decision);
        return CommitRegularV4FrontierRepairPressureBindingDecision(
            contract,
            decision,
            installBoundary);
    }

    private static bool CommitRegularV4FrontierRepairPressureBindingDecision(
        RegularV4FrontierRepairContract contract,
        RegularV4FrontierRepairPressureBindingDecision decision,
        string installBoundary)
    {
        if (decision.Status == RegularV4FrontierRepairPressureBindingDecisionStatus.Rejected ||
            decision.Binding is not { } binding ||
            binding.State != RegularV4FrontierRepairPressureBindingState.Installed)
        {
            LogRegularV4FrontierRepairPressureBinding(
                "filetransfer_regular_v4_frontier_repair_pressure_binding_invalidated",
                contract.Authority,
                decision.Binding,
                installBoundary,
                decision.Reason);
            return false;
        }

        LogRegularV4FrontierRepairPressureBinding(
            "filetransfer_regular_v4_frontier_repair_pressure_binding_committed",
            contract.Authority,
            binding,
            installBoundary,
            decision.Reason);
        return true;
    }

    private static void LogRegularV4FrontierRepairPressureBinding(
        string eventName,
        FileTransferRegularV4FrontierRepairAuthority authority,
        RegularV4FrontierRepairPressureBinding? binding,
        string boundary,
        string reason)
    {
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event={eventName}; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(authority.PredecessorAuthorityId?.ToString() ?? "(none)")}; direction={FormatFileTransferDirection(authority.Direction)}; transfer_id={FormatProtocolLogValue(authority.TransferId)}; session_id={FormatProtocolLogValue(authority.SessionId)}; route={FormatProtocolLogValue(authority.RouteToken)}; protocol_version={authority.ProtocolVersion}; live_route_epoch={authority.LiveRouteEpoch}; runtime_generation={authority.RuntimeGeneration}; terminal_generation={authority.TerminalGeneration}; leg_generation={authority.LegGeneration}; transport_epoch={authority.TransportEpoch}; bridge_recovery_generation={authority.BridgeRecoveryGeneration}; bridge_decision_generation={authority.BridgeDecisionGeneration}; route_publication_generation={authority.RoutePublicationGeneration}; route_commit_generation={authority.RouteCommitGeneration ?? 0}; target_transport={FormatFileTransferTransportKind(authority.TargetTransport)}; repair_request_key={FormatProtocolLogValue(authority.RepairKey)}; frontier_chunk_index={authority.FrontierChunkIndex}; durable_received_highest_chunk_index={authority.DurableReceivedHighestChunkIndex}; pending_repair_count={authority.PendingRepairCount}; repair_generation={authority.DecisionGeneration}; authority_decision_reason={FormatProtocolLogValue(authority.DecisionReason)}; install_generation={binding?.InstallGeneration ?? 0}; binding_state={FormatProtocolLogValue(binding?.State.ToString() ?? "(none)")}; pressure_reason={FormatProtocolLogValue(binding?.PressureReason ?? "(none)")}; install_boundary={FormatProtocolLogValue(boundary)}; decision_reason={FormatProtocolLogValue(reason)}");
    }

    private static void LogRegularV4FrontierRepairPressureInstallScopeRejected(
        RegularV4FrontierRepairContract contract,
        RegularV4FrontierRepairContract? predecessorContract,
        int frontierLagChunks,
        int pendingRepairCount,
        string pressureReason,
        string installBoundary,
        string rejectionReason)
    {
        var predecessorAuthorityId =
            predecessorContract?.Authority.AuthorityId ??
            contract.Authority.PredecessorAuthorityId;
        var normalizedPressureReason = string.IsNullOrWhiteSpace(pressureReason)
            ? predecessorAuthorityId is null
                ? "regular_v4_frontier_repair_initial_pressure"
                : "regular_v4_frontier_repair_successor_pressure"
            : pressureReason.Trim();
        LogRegularV4FrontierRepairPressureInstallRequested(
            contract.Authority,
            predecessorAuthorityId,
            Math.Max(0, frontierLagChunks),
            Math.Max(1, pendingRepairCount),
            normalizedPressureReason,
            installBoundary);
        LogRegularV4FrontierRepairPressureInstallDecided(
            contract.Authority,
            predecessorAuthorityId,
            Math.Max(0, frontierLagChunks),
            Math.Max(1, pendingRepairCount),
            normalizedPressureReason,
            installBoundary,
            receipt: null,
            rejectionReason);
    }

    private bool TryInstallRegularV4FrontierRepairPressureCoreLocked(
        RegularV4FrontierRepairContract contract,
        RegularV4FrontierRepairContract? predecessorContract,
        int frontierLagChunks,
        int pendingRepairCount,
        string pressureReason,
        string installBoundary,
        FileTransferRegularV4FrontierRepairPressureInstallCommand installCommand,
        out FileTransferRegularV4FrontierRepairPressureInstallReceipt installReceipt)
    {
        installReceipt = null!;
        var authority = contract.Authority;
        var predecessorAuthorityId =
            predecessorContract?.Authority.AuthorityId ??
            authority.PredecessorAuthorityId;
        var normalizedPressureReason = string.IsNullOrWhiteSpace(pressureReason)
            ? predecessorAuthorityId is null
                ? "regular_v4_frontier_repair_initial_pressure"
                : "regular_v4_frontier_repair_successor_pressure"
            : pressureReason.Trim();

        LogRegularV4FrontierRepairPressureInstallRequested(
            authority,
            predecessorAuthorityId,
            Math.Max(0, frontierLagChunks),
            Math.Max(1, pendingRepairCount),
            normalizedPressureReason,
            installBoundary);

        if (transport is not IFileTransferRegularV4FrontierRepairPressureInstallBridge bridge)
        {
            LogRegularV4FrontierRepairPressureInstallDecided(
                authority,
                predecessorAuthorityId,
                Math.Max(0, frontierLagChunks),
                Math.Max(1, pendingRepairCount),
                normalizedPressureReason,
                installBoundary,
                receipt: null,
                "regular_v4_frontier_repair_pressure_install_bridge_missing");
            return false;
        }

        FileTransferRegularV4FrontierRepairPressureInstallReceipt? receipt;
        try
        {
            receipt = bridge.InstallRegularV4FrontierRepairPressure(installCommand);
        }
        catch (Exception ex)
        {
            LogRegularV4FrontierRepairPressureInstallDecided(
                authority,
                predecessorAuthorityId,
                Math.Max(0, frontierLagChunks),
                Math.Max(1, pendingRepairCount),
                normalizedPressureReason,
                installBoundary,
                receipt: null,
                $"regular_v4_frontier_repair_pressure_install_bridge_failed_{NormalizeReason(ex.GetType().Name)}");
            return false;
        }

        var accepted = IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
            contract,
            predecessorContract?.Authority.AuthorityId,
            normalizedPressureReason,
            receipt,
            out var rejectionReason);
        LogRegularV4FrontierRepairPressureInstallDecided(
            authority,
            predecessorAuthorityId,
            Math.Max(0, frontierLagChunks),
            Math.Max(1, pendingRepairCount),
            normalizedPressureReason,
            installBoundary,
            receipt,
            accepted ? receipt!.Reason : rejectionReason);
        if (accepted)
        {
            installReceipt = receipt!;
        }
        return accepted;
    }

    private static bool IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
        RegularV4FrontierRepairContract contract,
        FileTransferAuthorityId? predecessorAuthorityId,
        string pressureReason,
        FileTransferRegularV4FrontierRepairPressureInstallReceipt? receipt,
        out string rejectionReason)
    {
        rejectionReason = "regular_v4_frontier_repair_pressure_install_receipt_missing";
        if (receipt is null)
        {
            return false;
        }

        var authority = contract.Authority;
        if (contract.Lifecycle.IsSettled)
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_install_contract_settled";
            return false;
        }

        if (predecessorAuthorityId is null)
        {
            if (authority.PredecessorAuthorityId is not null)
            {
                rejectionReason = "regular_v4_frontier_repair_pressure_install_initial_predecessor_invalid";
                return false;
            }
        }
        else if (authority.PredecessorAuthorityId is not { IsDefault: false } authorityPredecessorId ||
                 authorityPredecessorId != predecessorAuthorityId)
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_install_predecessor_mismatch";
            return false;
        }

        if (receipt.Authority != authority)
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_install_authority_mismatch";
            return false;
        }

        if (!string.Equals(receipt.PressureReason, pressureReason, StringComparison.Ordinal))
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_install_reason_mismatch";
            return false;
        }

        if (receipt.InstallGeneration <= 0)
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_install_generation_invalid";
            return false;
        }

        if (receipt.Status is not (
                FileTransferRegularV4FrontierRepairPressureInstallStatus.Installed or
                FileTransferRegularV4FrontierRepairPressureInstallStatus.Idempotent))
        {
            rejectionReason = string.IsNullOrWhiteSpace(receipt.Reason)
                ? "regular_v4_frontier_repair_pressure_install_rejected"
                : receipt.Reason.Trim();
            return false;
        }

        if (string.IsNullOrWhiteSpace(receipt.Reason) ||
            !string.Equals(receipt.Reason, receipt.Reason.Trim(), StringComparison.Ordinal))
        {
            rejectionReason = "regular_v4_frontier_repair_pressure_install_decision_reason_invalid";
            return false;
        }

        rejectionReason = receipt.Reason;
        return true;
    }

