        LocalOperationalLog.Info(
            "FileTransferService",
            $"event={eventName}; {FormatRegularV4FrontierRepairPressureInstallAuthorityTuple(authority, predecessorAuthorityId, frontierLagChunks, pendingRepairCount, pressureReason, installBoundary)}");
    }

