    private static string FormatRegularV4FrontierRepairPressureInstallAuthorityTuple(
        FileTransferRegularV4FrontierRepairAuthority authority,
        FileTransferAuthorityId? predecessorAuthorityId,
        int frontierLagChunks,
        int pendingRepairCount,
        string pressureReason,
        string installBoundary)
        => $"authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(predecessorAuthorityId?.ToString() ?? "(none)")}; install_kind={(predecessorAuthorityId is null ? "initial" : "successor")}; direction={FormatFileTransferDirection(authority.Direction)}; transfer_id={FormatProtocolLogValue(authority.TransferId)}; session_id={FormatProtocolLogValue(authority.SessionId)}; route={FormatProtocolLogValue(authority.RouteToken)}; protocol_version={authority.ProtocolVersion}; live_route_epoch={authority.LiveRouteEpoch}; runtime_generation={authority.RuntimeGeneration}; terminal_generation={authority.TerminalGeneration}; leg_generation={authority.LegGeneration}; transport_epoch={authority.TransportEpoch}; bridge_recovery_generation={authority.BridgeRecoveryGeneration}; bridge_decision_generation={authority.BridgeDecisionGeneration}; route_publication_generation={authority.RoutePublicationGeneration}; route_commit_generation={authority.RouteCommitGeneration ?? 0}; repair_generation={authority.DecisionGeneration}; repair_request_key={FormatProtocolLogValue(authority.RepairKey)}; frontier_chunk_index={authority.FrontierChunkIndex}; durable_received_highest_chunk_index={authority.DurableReceivedHighestChunkIndex}; authority_pending_repair_count={authority.PendingRepairCount}; frontier_lag_chunks={frontierLagChunks}; pending_repair_count={pendingRepairCount}; target_transport={FormatFileTransferTransportKind(authority.TargetTransport)}; pressure_reason={FormatProtocolLogValue(pressureReason)}; install_boundary={FormatProtocolLogValue(installBoundary)}";

    private void MaybeObserveRegularV4ReceiverFrontierRepairPressure(
        InboundTransferContext context,
        int frontierLagChunks,
        int pendingRepairCount)
    {
        if (!IsCurrentV4FrontierRepairRuntime(context) ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            context.IsTerminal ||
            pendingRepairCount <= 0)
        {
            return;
        }

        IFileTransferRegularV4ControlFeedbackPressureObserver? observer;
        lock (gate)
        {
            observer = transport as IFileTransferRegularV4ControlFeedbackPressureObserver;
        }

        if (observer is null)
        {
            return;
        }

        var repairRequestKey = context.V4ReceiverRepairRequests.Values
            .Where(static repair => repair.FrontierRepair)
            .OrderByDescending(static repair => repair.LastRequestedUtc ?? DateTimeOffset.MinValue)
            .Select(static repair => repair.RepairRequestKey)
            .FirstOrDefault() ?? "(none)";
        if (IsInboundRegularV4FrontierRepairSettledStalledLocked(context, repairRequestKey))
        {
            return;
        }

        if (context.CurrentRegularV4FrontierRepairContract is { } currentContract &&
            string.Equals(currentContract.Authority.RepairKey, repairRequestKey, StringComparison.Ordinal) &&
            TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                currentContract.Authority.AuthorityId,
                out var installedBinding,
                out _,
                out var installReceipt) &&
            IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                currentContract,
                currentContract.Authority.PredecessorAuthorityId,
                installedBinding.PressureReason,
                installReceipt,
                out _))
        {
            return;
        }

        var pressureReason = IsCurrentFileTunaV4FrontierRepairLeg(context.CurrentTransferLeg)
            ? "file_tuna_v4_receiver_frontier_repair_due"
            : "regular_v4_receiver_frontier_repair_due";
        observer.ObserveRegularV4ControlFeedbackPressure(new FileTransferRegularV4ControlFeedbackPressure(
            context.SessionId,
            context.TransferId,
            CreditExhaustedTimeMs: 0,
            Math.Max(0, frontierLagChunks),
            pendingRepairCount,
            pressureReason,
            GetCurrentRegularV4FrontierRepairAuthority(context, repairRequestKey)));
    }

    private bool TrySettleInboundRegularV4FrontierRepairStalledLocked(
        InboundTransferContext context,
        string repairRequestKey,
        string reason,
        int frontierChunkIndex,
        int durableReceivedHighestChunkIndex,
        int requestedChunkCount,
        int attemptCount,
        long frontierStallAgeMs)
    {
        if (!IsCurrentRegularV4FrontierRepairRuntime(context) ||
            string.IsNullOrWhiteSpace(repairRequestKey))
        {
            return false;
        }

        var retainedProjection = context.V4RegularFrontierRepairProjection is { } candidateProjection &&
                                 IsInboundRegularV4FrontierRepairProjectionScopeCurrentLocked(context, candidateProjection, out _) &&
                                 !candidateProjection.SourceContract.Lifecycle.IsSettled
            ? candidateProjection
            : null;
        context.V4ReceiverRepairRequests.TryGetValue(repairRequestKey, out var stalledRepairState);
        var currentAttempt = context.CurrentRegularV4FrontierRepairContract is { Lifecycle.IsSettled: false } candidateAttempt &&
                             IsRegularV4FrontierRepairContractCurrent(context, candidateAttempt, out _)
            ? candidateAttempt
            : null;
        var stalledRepairContract = currentAttempt ??
                                    (stalledRepairState?.RegularV4RepairContract is { Lifecycle.IsSettled: false } stateContract &&
                                     IsRegularV4FrontierRepairContractCurrent(context, stateContract, out _)
                                        ? stateContract
                                        : null) ??
                                    retainedProjection?.SourceContract;
        var stalledRepairContractNewlyIssued = false;
        if (stalledRepairContract is null &&
            TryAuthorizeRepairReplayLocked(
                context,
                context.CurrentRuntimeOwner,
                RepairReplayKind.V4Repair,
                "regular_v4_frontier_repair_liveness",
                reason,
                context.CurrentTransferLeg,
                context.CurrentTransferLeg?.TransportEpochId,
                context.CurrentTransferLeg?.BridgeRecoveryGeneration,
                null,
                out var stalledRepairDecision) &&
            stalledRepairDecision is { } stalledDecision)
        {
            stalledRepairContract = CreateRegularV4FrontierRepairContract(
                context,
                stalledDecision,
                repairRequestKey,
                frontierChunkIndex,
                durableReceivedHighestChunkIndex,
                requestedChunkCount,
                "regular_v4_frontier_repair_liveness_settled_stalled",
                "regular_v4_frontier_repair_liveness_settled_stalled",
                out _);
            stalledRepairContractNewlyIssued = stalledRepairContract is not null;
        }

        if (stalledRepairContract is null ||
            stalledRepairContract.Lifecycle.IsSettled)
        {
            return false;
        }

        if (stalledRepairContractNewlyIssued)
        {
            context.CurrentRegularV4FrontierRepairContract = stalledRepairContract;
        }

        if (!TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                stalledRepairContract.Authority.AuthorityId,
                out var stalledBinding,
                out _,
                out _) ||
            stalledBinding.State != RegularV4FrontierRepairPressureBindingState.Installed ||
            stalledBinding.Authority != stalledRepairContract.Authority)
        {
            var pressureInstalled = stalledRepairContractNewlyIssued
                ? TryInstallRegularV4FrontierRepairPressureLocked(
                    context,
                    stalledRepairContract,
                    predecessorContract: null,
                    Math.Max(0, durableReceivedHighestChunkIndex - frontierChunkIndex + 1),
                    Math.Max(1, requestedChunkCount),
                    "regular_v4_frontier_repair_liveness_settled_stalled",
                    "inbound_liveness_initial")
                : TryRetryRegularV4FrontierRepairPressureInstallLocked(
                    context,
                    stalledRepairContract);
            if (!pressureInstalled)
            {
                return false;
            }
        }

        var settlementRepairKey = stalledRepairContract.Authority.RepairKey;
        var settlementRequestedChunkCount = Math.Max(0, stalledRepairContract.Authority.PendingRepairCount);
        if (IsInboundRegularV4FrontierRepairSettledStalledLocked(context, settlementRepairKey) ||
            !TrySettleRegularV4FrontierRepairContract(
                stalledRepairContract,
                FileTransferRegularV4FrontierRepairSettlementOutcome.SettledStalled,
                settlementRequestedChunkCount,
                "regular_v4_frontier_repair_liveness_settled_stalled"))
        {
            return false;
        }

        context.V4RegularFrontierRepairSettledStalledRepairKey = settlementRepairKey;
        context.V4RegularFrontierRepairSettledStalledAuthorityId = stalledRepairContract.Authority.AuthorityId;
        context.V4RegularFrontierRepairSettledStalledContract = stalledRepairContract;
        context.CurrentRegularV4FrontierRepairContract = stalledRepairContract;
        context.V4RegularFrontierRepairSettledStalledUtc = DateTimeOffset.UtcNow;
        LogFileTransferRegularV4FrontierRepairStalled(
            FileTransferDirection.Inbound,
            context.TransferId,
            context.SessionId,
            context.CurrentTransferLeg,
            settlementRepairKey,
            reason,
            frontierChunkIndex,
            durableReceivedHighestChunkIndex,
            settlementRequestedChunkCount,
            attemptCount,
            frontierStallAgeMs);
        var leg = context.CurrentTransferLeg;
        var routeToken = leg?.RouteSelection.TelemetryToken ?? "(none)";
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_regular_v4_frontier_repair_settled_stalled; direction=inbound; transfer_id={FormatProtocolLogValue(context.TransferId)}; session_id={FormatProtocolLogValue(context.SessionId)}; repair_request_key={FormatProtocolLogValue(settlementRepairKey)}; observed_repair_request_key={FormatProtocolLogValue(repairRequestKey)}; reason={FormatProtocolLogValue(reason)}; decision_reason=regular_v4_frontier_repair_liveness_settled_stalled; settlement=stalled; route={FormatProtocolLogValue(routeToken)}; protocol_version={leg?.ProtocolVersion ?? 0}; live_route_epoch={leg?.LiveRouteEpochId ?? 0}; runtime_generation={context.CurrentRuntimeOwner?.RuntimeGeneration ?? 0}; terminal_generation={context.CurrentRuntimeOwner?.TerminalGeneration ?? 0}; leg_generation={leg?.Generation ?? 0}; transport_epoch={leg?.TransportEpochId ?? 0}; bridge_recovery_generation={leg?.BridgeRecoveryGeneration ?? 0}; route_publication_generation={context.LastRoutePublicationGeneration}; target_transport={FormatFileTransferTransportKind(ResolveV4FrontierRepairTargetTransport(routeToken))}; frontier_chunk_index={frontierChunkIndex}; durable_received_highest_chunk_index={durableReceivedHighestChunkIndex}; requested_chunk_count={settlementRequestedChunkCount}; observed_requested_chunk_count={requestedChunkCount}; attempt_count={attemptCount}; frontier_stall_age_ms={frontierStallAgeMs}");

        return true;
    }

    private static bool IsInboundRegularV4FrontierRepairSettledStalledLocked(
        InboundTransferContext context,
        string? repairRequestKey)
    {
        if (string.IsNullOrWhiteSpace(repairRequestKey) ||
            !string.Equals(
                context.V4RegularFrontierRepairSettledStalledRepairKey,
                repairRequestKey,
                StringComparison.Ordinal) ||
            context.V4RegularFrontierRepairSettledStalledAuthorityId is not { IsDefault: false } ||
            context.V4RegularFrontierRepairSettledStalledContract is not { } contract ||
            !string.Equals(contract.Authority.RepairKey, repairRequestKey, StringComparison.Ordinal))
        {
            return false;
        }

        return FileTransferCoordinator.IsRepairReplayDecisionCurrent(
            CreateCoordinatorStateLocked(context),
            contract.RepairDecision,
            out _);
    }

    private static string BuildInboundRegularV4FrontierRepairSettlementAuthorityKeyLocked(
        InboundTransferContext context,
        string repairRequestKey)
    {
        var leg = context.CurrentTransferLeg;
        var owner = context.CurrentRuntimeOwner;
        var tokenMaybe = context.CurrentRoutePublicationToken;
        var hasToken = tokenMaybe is { IsDefault: false };
        var token = tokenMaybe.GetValueOrDefault();
        var routeToken = hasToken
            ? token.RouteToken
            : leg?.RouteSelection.TelemetryToken ?? context.RouteSelection.TelemetryToken;
        var protocolVersion = hasToken
            ? token.ProtocolVersion
            : leg?.ProtocolVersion ?? context.NegotiatedDataProtocolVersion;
        var liveRouteEpoch = hasToken
            ? token.LiveRouteEpoch
            : leg?.LiveRouteEpochId ?? context.LastLiveRouteEpochId;
        var runtimeGeneration = hasToken
            ? token.RuntimeGeneration
            : owner?.RuntimeGeneration ?? 0;
        var terminalGeneration = hasToken
            ? token.TerminalGeneration
            : owner?.TerminalGeneration ?? 0;
        var legGeneration = hasToken
            ? token.LegGeneration
            : leg?.Generation ?? 0;
        var routePublicationGeneration = hasToken
            ? token.PublicationGeneration
            : context.LastRoutePublicationGeneration;
        var bridgeDecisionGeneration =
            context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ??
            context.LastBridgeRecoveryDecisionGeneration;
        return string.Join(
            '|',
            context.SessionId,
            context.TransferId,
            FileTransferDirection.Inbound.ToString(),
            routeToken,
            protocolVersion.ToString(CultureInfo.InvariantCulture),
            liveRouteEpoch.ToString(CultureInfo.InvariantCulture),
            runtimeGeneration.ToString(CultureInfo.InvariantCulture),
            terminalGeneration.ToString(CultureInfo.InvariantCulture),
            legGeneration.ToString(CultureInfo.InvariantCulture),
            (leg?.TransportEpochId ?? 0).ToString(CultureInfo.InvariantCulture),
            (leg?.BridgeRecoveryGeneration ?? 0).ToString(CultureInfo.InvariantCulture),
            bridgeDecisionGeneration.ToString(CultureInfo.InvariantCulture),
            routePublicationGeneration.ToString(CultureInfo.InvariantCulture),
            string.IsNullOrWhiteSpace(repairRequestKey) ? "(none)" : repairRequestKey);
    }

    private static bool ShouldLogV4EfficiencySummary(OutboundTransferContext context)
        => context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 ||
           context.PullSenderRawBytesTotal > 0 ||
           context.PullSenderBatchFramesTotal > 0;

    private static bool ShouldLogV4EfficiencySummary(InboundTransferContext context)
        => context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 ||
           context.PullReceiverRawBatchBytesTotal > 0 ||
           context.PullReceiverAcceptedRawBytesTotal > 0;

    private static long ComputeEfficiencyPermille(long numerator, long denominator)
        => denominator <= 0
            ? -1
            : (numerator * 1000L + denominator / 2L) / denominator;

    private static void LogV4EfficiencySummary(
        OutboundTransferContext context,
        FileTransferTransferState terminalState)
    {
        if (!ShouldLogV4EfficiencySummary(context))
        {
            return;
        }

        var fileSizeBytes = Math.Max(0L, context.FileSizeBytes);
        var rawToFilePermille = ComputeEfficiencyPermille(context.PullSenderRawBytesTotal, fileSizeBytes);
        var normalToFilePermille = ComputeEfficiencyPermille(context.PullSenderNormalRawBytesTotal, fileSizeBytes);
        var repairToFilePermille = ComputeEfficiencyPermille(context.PullSenderRepairRawBytesTotal, fileSizeBytes);
        var repairToRawPermille = ComputeEfficiencyPermille(context.PullSenderRepairRawBytesTotal, context.PullSenderRawBytesTotal);
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v4_efficiency_summary; direction=outbound; transfer_id={context.TransferId}; session_id={context.SessionId}; terminal_state={terminalState.ToString().ToLowerInvariant()}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; runtime_profile={FormatFileTransferRouteRuntimeProfile(context.RouteSelection.RuntimeProfile)}; frame_family={FormatFileTransferFrameFamily(context.RouteSelection.FrameFamily)}; bridge_recovery_policy={FormatFileTransferRouteBridgeRecoveryPolicy(context.RouteSelection.BridgeRecoveryPolicy)}; file_size_bytes={fileSizeBytes}; bytes_acknowledged_by_receiver={context.BytesAcknowledgedByReceiver}; bytes_transferred={context.BytesTransferred}; chunks_accepted_for_transport={context.ChunksAcceptedForTransport}; remote_frontier_chunk_index={context.RemoteNextExpectedChunkIndex}; raw_bytes_sent_total={context.PullSenderRawBytesTotal}; normal_raw_bytes_sent_total={context.PullSenderNormalRawBytesTotal}; repair_raw_bytes_sent_total={context.PullSenderRepairRawBytesTotal}; raw_to_file_permille={rawToFilePermille}; normal_to_file_permille={normalToFilePermille}; repair_to_file_permille={repairToFilePermille}; repair_to_raw_permille={repairToRawPermille}; batch_frames_sent_total={context.PullSenderBatchFramesTotal}; normal_batch_frames_sent_total={context.PullSenderNormalBatchFramesTotal}; repair_batch_frames_sent_total={context.PullSenderRepairBatchFramesTotal}; chunk_count_sent_total={context.PullSenderChunkCountTotal}; normal_chunk_count_sent_total={context.PullSenderNormalChunkCountTotal}; repair_chunk_count_sent_total={context.PullSenderRepairChunkCountTotal}; send_wait_count_total={context.PullSenderSendWaitCountTotal}; failed_frames_total={context.PullSenderPipelineFailedFramesTotal}; receiver_state_received_total={context.PullV4StateReceivedCountTotal}; receiver_state_applied_total={context.PullV4StateAppliedCountTotal}; receiver_state_duplicate_total={context.PullV4StateDuplicateCountTotal}; receiver_state_stale_total={context.PullV4StateStaleCountTotal}; pending_repair_count={context.PullV4SenderPumpRepairQueue.Sum(static repair => repair.ChunkIndices.Count)}; sent_cache_chunk_count={context.PullSentChunkCache.Count}; sent_cache_bytes={context.PullSentChunkCacheBytes}");
    }

    private static void LogV4EfficiencySummary(
        InboundTransferContext context,
        FileTransferTransferState terminalState)
    {
        if (!ShouldLogV4EfficiencySummary(context))
        {
            return;
        }

        var fileSizeBytes = Math.Max(0L, context.FileSizeBytes);
        var rawToFilePermille = ComputeEfficiencyPermille(context.PullReceiverRawBatchBytesTotal, fileSizeBytes);
        var acceptedToFilePermille = ComputeEfficiencyPermille(context.PullReceiverAcceptedRawBytesTotal, fileSizeBytes);
        var duplicateToRawPermille = ComputeEfficiencyPermille(context.PullReceiverDuplicateOrStaleRawBytesTotal, context.PullReceiverRawBatchBytesTotal);
        var acceptedToRawPermille = ComputeEfficiencyPermille(context.PullReceiverAcceptedRawBytesTotal, context.PullReceiverRawBatchBytesTotal);
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v4_efficiency_summary; direction=inbound; transfer_id={context.TransferId}; session_id={context.SessionId}; terminal_state={terminalState.ToString().ToLowerInvariant()}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; runtime_profile={FormatFileTransferRouteRuntimeProfile(context.RouteSelection.RuntimeProfile)}; frame_family={FormatFileTransferFrameFamily(context.RouteSelection.FrameFamily)}; bridge_recovery_policy={FormatFileTransferRouteBridgeRecoveryPolicy(context.RouteSelection.BridgeRecoveryPolicy)}; file_size_bytes={fileSizeBytes}; bytes_transferred={context.BytesTransferred}; sparse_bytes_written={context.ReceiverSparseBytesWritten}; next_chunk_index={context.NextChunkIndex}; highest_received_chunk_index={context.PullHighestReceivedChunkIndex}; raw_batch_bytes_received_total={context.PullReceiverRawBatchBytesTotal}; raw_batch_frames_received_total={context.PullReceiverRawBatchFramesTotal}; accepted_raw_bytes_received_total={context.PullReceiverAcceptedRawBytesTotal}; duplicate_or_stale_raw_bytes_received_total={context.PullReceiverDuplicateOrStaleRawBytesTotal}; raw_to_file_permille={rawToFilePermille}; accepted_to_file_permille={acceptedToFilePermille}; duplicate_or_stale_to_raw_permille={duplicateToRawPermille}; accepted_to_raw_permille={acceptedToRawPermille}; chunk_count_received_total={context.PullReceiverChunkCountTotal}; accepted_chunk_count_total={context.PullReceiverAcceptedChunkCountTotal}; duplicate_or_stale_chunk_count_total={context.PullReceiverDuplicateOrStaleChunkCountTotal}; repair_overlap_chunk_count_total={context.PullReceiverRepairOverlapChunkCountTotal}; repair_accepted_chunk_count_total={context.PullReceiverRepairAcceptedChunkCountTotal}; repair_duplicate_or_stale_chunk_count_total={context.PullReceiverRepairDuplicateOrStaleChunkCountTotal}; repair_duplicate_or_stale_raw_bytes_total={context.PullReceiverRepairDuplicateOrStaleRawBytesTotal}; sparse_write_batch_count_total={context.PullReceiverSparseWriteBatchCountTotal}; sparse_write_duration_ms_total={context.PullReceiverSparseWriteDurationMsTotal}; receiver_state_sent_total={context.PullV4StateSentCountTotal}; repair_request_count_total={context.PullV4RepairRequestCountTotal}; repair_requested_chunk_count_total={context.PullV4RepairRequestedChunkCountTotal}; repair_suppressed_count_total={context.PullV4RepairSuppressedCountTotal}; frontier_tail_repair_request_count_total={context.PullV4FrontierTailRepairRequestCountTotal}; frontier_stall_suppressed_count_total={context.V4FrontierStallSuppressedCountTotal}; pending_repair_request_count={context.V4ReceiverRepairRequests.Count}; pending_write_chunk_count={context.ReceiverSparseChunksPendingWrite.Count}; pending_bytes={context.BufferedBytes}");
    }

    private async Task<bool> FailOutboundV4Async(
        OutboundTransferContext context,
        IFileTransferDataSession? dataSession,
        RuntimeOwnerToken? runtimeOwner,
        string errorCode,
        string statusMessage,
        bool notifyPeer,
        OutboundSparsePumpInstall? requiredSparsePumpInstall = null)
    {
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) || context.IsTerminal)
            {
                return false;
            }

            if (!TryAuthorizeRuntimeOwnerActionLocked(
                    context,
                    runtimeOwner,
                    FileTransferCoordinatorActionKind.ProgressMutation,
                    "v4_sender_failed",
                    errorCode,
                    out _))
            {
                return false;
            }
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_sender_failed; transfer_id={context.TransferId}; session_id={context.SessionId}; error_code={errorCode}; reason={FormatProtocolLogValue(statusMessage)}");

        if (requiredSparsePumpInstall is not null &&
            OutboundSparseFailureAuthorizationBarrierForTests is { } failureAuthorizationBarrier)
        {
            await failureAuthorizationBarrier(context.TransferId, context.SessionId).ConfigureAwait(false);
        }

        return await TransitionOutboundToTerminalAsync(
            context,
            FileTransferTransferState.Failed,
            errorCode: errorCode,
            statusMessage: statusMessage,
            notifyPeer: notifyPeer,
            cancelReason: null,
            ct: CancellationToken.None,
            requiredSparsePumpInstall: requiredSparsePumpInstall).ConfigureAwait(false);
    }

    private async Task<bool> SendOutboundV4PauseStateAsync(OutboundTransferContext context, string reason)
    {
        FileTransferStateFrameV4? state;
        IFileTransferDataSession? dataSession;
        lock (gate)
        {
            if (!ReferenceEquals(outboundTransfer, context) ||
                context.IsTerminal ||
                context.DataSession is null)
            {
                return false;
            }

            state = CreateOutboundV4PauseStateLocked(context, reason);
            dataSession = context.DataSession;
        }

        try
        {
            using var timeout = new CancellationTokenSource(TimeSpan.FromMilliseconds(LifecyclePrioritySendTimeoutMs));
            await dataSession.SendAsync(state, timeout.Token).ConfigureAwait(false);
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_pause_state_sent; transfer_id={state.TransferId}; session_id={state.SessionId}; reason={reason}; epoch={state.Epoch}; transfer_paused={(state.TransferPaused ? 1 : 0)}; pause_reason={FormatProtocolLogValue(state.TransferPauseReason ?? "(none)")}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}");
            return true;
        }
        catch (OperationCanceledException)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v4_pause_state_send_failed; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={reason}; transfer_paused={(state.TransferPaused ? 1 : 0)}; error=timeout");
            return false;
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v4_pause_state_send_failed; transfer_id={context.TransferId}; session_id={context.SessionId}; reason={reason}; transfer_paused={(state.TransferPaused ? 1 : 0)}; error={FormatProtocolLogValue(ex.Message)}");
            return false;
        }
    }

