                state.MissingRanges.Count > 0)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_primary_regular_nkn_frontier_repair_transaction_state_sent; direction=inbound; transfer_id={state.TransferId}; session_id={state.SessionId}; request_id={FormatProtocolLogValue(metadataState?.RepairRequestId)}; epoch={state.Epoch}; start_chunk_index={state.MissingRanges[0].StartChunkIndex}; requested_chunk_count={state.MissingRanges[0].ChunkCount}; committed_frontier_chunk_index={state.ContiguousCommittedChunkIndex}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; frontier_stall_age_ms={frontierStallAgeMs}");
            }
            LogPrimaryRegularNknBulkV6CheckpointSent(context, state, reason, sent: true);
            return true;
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            if (proofStateSendCapture is not null)
            {
                var proofActivationUnavailable =
                    IsTunaActivationNegotiationDataSessionUnavailableException(
                        ex);
                lock (gate)
                {
                    if (proofStatePublicationCommand is { } command &&
                        ReferenceEquals(inboundTransfer, context) &&
                        !context.IsTerminal &&
                        FileTransferCoordinator
                            .IsReceiveRecoveryProofStatePublicationCommandCurrent(
                                CreateCoordinatorStateLocked(context),
                                command) &&
                        ((context.PullTransportPaused &&
                          IsTunaActivationNegotiationTransportPauseReason(
                              context.PullTransportPauseReason)) ||
                         proofActivationUnavailable))
                    {
                        HoldReceiveRecoveryProofStatePublicationForTunaActivationPause(
                            context,
                            command,
                            proofStateSendCapture,
                            context.PullTransportPaused
                                ? context.PullTransportPauseReason ??
                                  "tuna_activation_negotiating"
                                : "tuna_activation_negotiating",
                            "physical_submission_race");
                        return false;
                    }
                }

                proofStateSendCapture.Outcome =
                    FileTransferReceiveRecoveryProofStatePublicationOutcome
                        .Rejected;
                proofStateSendCapture.Reason =
                    $"filetransfer_receive_recovery_proof_state_send_failed_{NormalizeReason(ex.GetType().Name)}";
                return false;
            }

            string? pauseReason = null;
            var explicitActivationUnavailable = IsTunaActivationNegotiationDataSessionUnavailableException(ex);
            lock (gate)
            {
                if (ReferenceEquals(inboundTransfer, context) &&
                    !context.IsTerminal &&
                    (context.PullTransportPaused &&
                     IsTunaActivationNegotiationTransportPauseReason(context.PullTransportPauseReason) ||
                     explicitActivationUnavailable))
                {
                    pauseReason = context.PullTransportPaused &&
                                  IsTunaActivationNegotiationTransportPauseReason(context.PullTransportPauseReason)
                        ? context.PullTransportPauseReason
                        : "tuna_activation_negotiating";
                    context.TunaActivationBarrierStateSendSuppressedCount++;
                }
            }

            if (pauseReason is not null)
            {
                LocalOperationalLog.Info(
                    "FileTransferService",
                    $"event=filetransfer_v4_state_send_deferred_for_tuna_activation_transport_pause; direction=inbound; transfer_id={state.TransferId}; session_id={state.SessionId}; state_reason={FormatProtocolLogValue(reason)}; pause_reason={FormatProtocolLogValue(pauseReason)}; explicit_activation_unavailable={(explicitActivationUnavailable ? 1 : 0)}; epoch={state.Epoch}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; missing_range_count={state.MissingRanges.Count}; bytes_committed={state.BytesCommitted}; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");
                return false;
            }

            if (TryDeferInboundRegularNknV4ReceiverStateSendFailureForRecovery(context, state, reason, ex))
            {
                return false;
            }

            await TransitionInboundToTerminalAsync(
                context,
                FileTransferTransferState.Failed,
                errorCode: InvalidStateErrorCode,
                statusMessage: ex.Message,
                sendError: true,
                errorMessage: "Could not send V4 receiver state.",
                cancelReason: null,
                ct: CancellationToken.None).ConfigureAwait(false);
            return false;
        }
    }

    private static string CreateFileTransferV4StateWireFingerprint(
        FileTransferStateFrameV4 state)
    {
        using var bytes = new MemoryStream();
        using (var writer = new BinaryWriter(
                   bytes,
                   System.Text.Encoding.UTF8,
                   leaveOpen: true))
        {
            writer.Write("filetransfer_v4_state_wire_v1");
            writer.Write(state.Kind ?? string.Empty);
            writer.Write(state.Type ?? string.Empty);
            writer.Write(state.SessionId ?? string.Empty);
            writer.Write(state.TransferId ?? string.Empty);
            writer.Write(state.Epoch);
            writer.Write(state.ContiguousCommittedChunkIndex);
            writer.Write(state.DurableReceivedHighestChunkIndex);
            writer.Write(state.CreditUntilChunkIndexExclusive);
            writer.Write(state.MissingRanges.Count);
            foreach (var range in state.MissingRanges)
            {
                writer.Write(range.StartChunkIndex);
                writer.Write(range.ChunkCount);
            }

            writer.Write(state.BytesCommitted);
            writer.Write(state.ReceiverMemoryPressure);
            writer.Write(state.ReceiverDiskPressure);
            writer.Write(state.TerminalReady);
            writer.Write(state.TransferPaused);
            writer.Write(state.TransferPauseReason ?? string.Empty);
            if (state is FileTransferReceiverStateFrameV6 metadata)
            {
                writer.Write(true);
                writer.Write(metadata.TransportEpoch);
                writer.Write(metadata.BatchId ?? string.Empty);
                writer.Write(metadata.RepairRequestId ?? string.Empty);
                writer.Write(metadata.Priority ?? string.Empty);
                writer.Write(metadata.RecoveryMode ?? string.Empty);
            }
            else
            {
                writer.Write(false);
            }
        }

        var hex = Convert.ToHexString(
            SHA256.HashData(bytes.GetBuffer().AsSpan(0, checked((int)bytes.Length))));
        return
            $"v4sf1-{hex[..16]}.{hex[16..32]}.{hex[32..48]}.{hex[48..64]}";
    }

    private bool TryDeferInboundRegularNknV4ReceiverStateSendFailureForRecovery(
        InboundTransferContext context,
        FileTransferStateFrameV4 state,
        string reason,
        Exception ex)
    {
        if (!IsRecoverableRegularNknV4RecoveryTransportSendException(ex) ||
            state.TerminalReady)
        {
            return false;
        }

        SessionFileTransferSnapshot? snapshot;
        IFileTransferRegularV4ControlFeedbackPressureObserver? pressureObserver;
        var recoveryReason = "regular_v4_receiver_state_send_failure";
        var now = DateTimeOffset.UtcNow;
        int frontierLagChunks;
        int pendingRepairCount;
        lock (gate)
        {
            if (!ReferenceEquals(inboundTransfer, context) ||
                context.IsTerminal ||
                context.LifetimeCts.IsCancellationRequested ||
                !context.RouteRuntime.UsesRegularNknV4FastRuntime ||
                context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4 ||
                context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
                context.UserPaused ||
                context.PeerPaused ||
                !context.PullManifestReceived ||
                context.NextChunkIndex >= context.ChunkCount)
            {
                return false;
            }

            frontierLagChunks = Math.Max(
                0,
                Math.Max(context.PullHighestReceivedChunkIndex + 1, state.DurableReceivedHighestChunkIndex + 1) -
                state.ContiguousCommittedChunkIndex);
            pendingRepairCount = 0;
            foreach (var range in state.MissingRanges)
            {
                pendingRepairCount += Math.Max(0, range.ChunkCount);
            }

            if (!context.PullTransportPaused)
            {
                context.PullTransportPaused = true;
                context.PullTransportPausedSinceUtc = now;
                context.PullTransportPauseReason = recoveryReason;
                context.PullTransportResumeRequestPending = true;
            }

            context.PullTransportGraceDeadlineUtc = now.AddSeconds(5);
            context.StatusMessage = "Waiting for network recovery.";
            pressureObserver = transport as IFileTransferRegularV4ControlFeedbackPressureObserver;
            snapshot = CreateSnapshotLocked();
        }

        pressureObserver?.ObserveRegularV4ControlFeedbackPressure(
            new FileTransferRegularV4ControlFeedbackPressure(
                context.SessionId,
                context.TransferId,
                CreditExhaustedTimeMs: 0,
                frontierLagChunks,
                pendingRepairCount,
                recoveryReason,
                GetCurrentRegularV4FrontierRepairAuthority(context)));

        TryRequestFileTransferReceiveRecovery(
            new FileTransferReceiveRecoveryRequest(
                context.SessionId,
                context.TransferId,
                FileTransferDirection.Inbound,
                recoveryReason)
            {
                RouteToken = FileTransferRouteResolver.RegularNknV4FastToken,
                ProtocolVersion = FileTransferProtocol.ProtocolVersionV4,
                AuthorityReason = recoveryReason,
            });

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_regular_v4_receiver_state_send_failure_deferred; direction=inbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; reason={FormatProtocolLogValue(recoveryReason)}; state_reason={FormatProtocolLogValue(reason)}; epoch={state.Epoch}; contiguous_committed_chunk_index={state.ContiguousCommittedChunkIndex}; durable_received_highest_chunk_index={state.DurableReceivedHighestChunkIndex}; credit_until_chunk_index_exclusive={state.CreditUntilChunkIndexExclusive}; missing_range_count={state.MissingRanges.Count}; frontier_lag_chunks={frontierLagChunks}; pending_repair_count={pendingRepairCount}; transport_paused=1; error={FormatProtocolLogValue(ex.GetType().Name)}; message={FormatProtocolLogValue(ex.Message)}");

        RaiseTransferChanged(snapshot);
        return true;
    }

    private static bool ShouldCoalesceInboundRegularV4FrontierRepairStateLocked(
        InboundTransferContext context,
        FileTransferStateFrameV4 state,
        string reason,
        DateTimeOffset now)
    {
        if (!string.Equals(reason, "frontier_stall_repair_due", StringComparison.Ordinal) ||
            state.MissingRanges.Count == 0 ||
            context.V4LastRegularFrontierRepairStartChunkIndex < 0)
        {
            return false;
        }

        var firstRange = state.MissingRanges[0];
        return context.RouteRuntime.UsesRegularNknV4FastRuntime &&
               context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
               !context.PullPostTunaRecoveryActive &&
               context.V6TransportHandoff is null &&
               context.V4LastRegularFrontierRepairStartChunkIndex == firstRange.StartChunkIndex &&
               context.V4LastRegularFrontierRepairChunkCount == firstRange.ChunkCount &&
               context.V4LastRegularFrontierRepairCommittedChunkIndex == state.ContiguousCommittedChunkIndex &&
               context.V4LastRegularFrontierRepairDurableHighestChunkIndex == state.DurableReceivedHighestChunkIndex &&
               context.V4LastRegularFrontierRepairCreditUntilChunkIndexExclusive == state.CreditUntilChunkIndexExclusive &&
               context.V4LastStateSentUtc is { } lastSentUtc &&
               now - lastSentUtc < TimeSpan.FromMilliseconds(V4RepairRedundancyEscalationStallMs);
    }

    private static void RememberInboundRegularV4FrontierRepairStateLocked(
        InboundTransferContext context,
        FileTransferStateFrameV4 state)
    {
        if (state.MissingRanges.Count == 0)
        {
            return;
        }

        var firstRange = state.MissingRanges[0];
        context.V4LastRegularFrontierRepairStartChunkIndex = firstRange.StartChunkIndex;
        context.V4LastRegularFrontierRepairChunkCount = firstRange.ChunkCount;
        context.V4LastRegularFrontierRepairCommittedChunkIndex = state.ContiguousCommittedChunkIndex;
        context.V4LastRegularFrontierRepairDurableHighestChunkIndex = state.DurableReceivedHighestChunkIndex;
        context.V4LastRegularFrontierRepairCreditUntilChunkIndexExclusive = state.CreditUntilChunkIndexExclusive;
    }

    private static bool ShouldClampInboundV4CreditForTransportRebind(
        InboundTransferContext context,
        FileTransferStateFrameV4 state,
        int frontierLagChunks)
    {
        if (!IsInboundV4PostRebindFrontierRecoveryActive(context, frontierLagChunks))
        {
            return false;
        }

        var frontierChunkIndex = state.ContiguousCommittedChunkIndex;
        if (state.MissingRanges.Count == 0)
        {
            return true;
        }

        return state.MissingRanges.Any(range =>
            range.StartChunkIndex <= frontierChunkIndex &&
            range.StartChunkIndex + range.ChunkCount > frontierChunkIndex);
    }

    private static bool TryComputeInboundRegularV4FrontierRepairCreditCap(
        InboundTransferContext context,
        FileTransferStateFrameV4 state,
        out int advertisedCreditUntilChunkIndexExclusive,
        out int repairCreditCapChunkIndexExclusive)
    {
        advertisedCreditUntilChunkIndexExclusive = state.CreditUntilChunkIndexExclusive;
        repairCreditCapChunkIndexExclusive = state.CreditUntilChunkIndexExclusive;

        if (!context.RouteRuntime.UsesRegularNknV4FastRuntime ||
            context.RouteRuntime.FrameFamily != FileTransferFrameFamily.V4 ||
            context.NegotiatedDataProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            IsInboundPostTunaRecoveryActiveLocked(context) ||
            state.MissingRanges.Count == 0 ||
            state.ContiguousCommittedChunkIndex >= context.ChunkCount)
        {
            return false;
        }

        var frontierChunkIndex = state.ContiguousCommittedChunkIndex;
        foreach (var range in state.MissingRanges)
        {
            if (range.ChunkCount <= 0)
            {
                continue;
            }

            var rangeEndExclusive = range.StartChunkIndex + range.ChunkCount;
            if (range.StartChunkIndex > frontierChunkIndex ||
                rangeEndExclusive <= frontierChunkIndex)
            {
                continue;
            }

            repairCreditCapChunkIndexExclusive = Math.Clamp(
                rangeEndExclusive,
                frontierChunkIndex,
                context.ChunkCount);
            advertisedCreditUntilChunkIndexExclusive = repairCreditCapChunkIndexExclusive;
            return state.CreditUntilChunkIndexExclusive > advertisedCreditUntilChunkIndexExclusive;
        }

        return false;
    }

    private static bool IsInboundV4PostRebindFrontierRecoveryActive(
        InboundTransferContext context,
        int frontierLagChunks)
        => IsInboundPostTunaRecoveryActiveLocked(context) &&
           (context.PullPostTunaRecoveryActive || !context.PullTransportRebindRecoveredLogged) &&
           frontierLagChunks > 0;

    private async Task SendInboundV4TerminalReadyStateBestEffortAsync(InboundTransferContext context)
    {
        var transferId = context.TransferId;
        var sessionId = context.SessionId;
        var sendTask = SendInboundSparseCreditStateAsync(context, "terminal_ready", terminalReady: true);
        try
        {
            if (sendTask.IsCompleted)
            {
                await sendTask.ConfigureAwait(false);
                return;
            }

            var completedTask = await Task.WhenAny(
                sendTask,
                Task.Delay(V4TerminalReadyStateBestEffortTimeoutMs, context.LifetimeCts.Token)).ConfigureAwait(false);
            if (completedTask == sendTask)
            {
                await sendTask.ConfigureAwait(false);
                return;
            }
        }
        catch (OperationCanceledException) when (context.LifetimeCts.IsCancellationRequested)
        {
            return;
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v4_terminal_ready_state_send_failed; transfer_id={transferId}; session_id={sessionId}; reason={FormatProtocolLogValue(ex.Message)}");
            return;
        }

        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_terminal_ready_state_send_deferred; transfer_id={transferId}; session_id={sessionId}; timeout_ms={V4TerminalReadyStateBestEffortTimeoutMs}");
        _ = ObserveInboundV4TerminalReadyStateSendAsync(sendTask, transferId, sessionId);
    }

    private static async Task ObserveInboundV4TerminalReadyStateSendAsync(Task<bool> sendTask, string transferId, string sessionId)
    {
        try
        {
            await sendTask.ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v4_terminal_ready_state_send_observe_failed; transfer_id={transferId}; session_id={sessionId}; reason={FormatProtocolLogValue(ex.Message)}");
        }
    }

    private static bool ShouldSuppressInboundV4StateLocked(
        InboundTransferContext context,
        FileTransferStateFrameV4 state,
        string reason,
        bool terminalReady,
        bool requireMissingRange,
        DateTimeOffset now)
    {
        if (!string.Equals(reason, "chunk_batch_committed", StringComparison.Ordinal) ||
            terminalReady ||
            requireMissingRange ||
            (state.MissingRanges.Count > 0 &&
             !IsInboundRegularV4FrontierRepairProjectionStateLocked(context, state, out _)) ||
            context.V4LastStateSentUtc is null)
        {
            return false;
        }

        var creditAdvance = state.CreditUntilChunkIndexExclusive - context.V4LastStateCreditUntilChunkIndexExclusive;
        var frontierAdvance = state.ContiguousCommittedChunkIndex - context.V4LastStateContiguousCommittedChunkIndex;
        var durableHighestAdvance = state.DurableReceivedHighestChunkIndex - context.V4LastStateDurableHighestChunkIndex;
        var bytesCommittedAdvance = state.BytesCommitted - context.V4LastStateBytesCommitted;
        var bytesCommittedCanDriveStateCadence = ShouldUseInboundV4BytesCommittedForStateCadenceLocked(context);
        var progressMinChunks = ResolveInboundV4StateProgressMinChunks(context);
        var progressMinBytes = progressMinChunks * (long)Math.Max(1, context.ChunkSizeBytes);
        if (creditAdvance >= progressMinChunks ||
            frontierAdvance >= progressMinChunks ||
            (bytesCommittedCanDriveStateCadence && bytesCommittedAdvance >= progressMinBytes))
        {
            return false;
        }

        var stateAgeMs = (long)Math.Max(0, (now - context.V4LastStateSentUtc.Value).TotalMilliseconds);
        if (stateAgeMs >= V4StateProgressMaxDelayMs &&
            (creditAdvance > 0 ||
             frontierAdvance > 0 ||
             durableHighestAdvance > 0 ||
             (bytesCommittedCanDriveStateCadence && bytesCommittedAdvance > 0)))
        {
            return false;
        }

        return true;
    }

    private static bool ShouldUseInboundV4BytesCommittedForStateCadenceLocked(InboundTransferContext context)
        => ShouldAdvertiseInboundV4SparseWrittenProgressLocked(context);

    private static int ResolveInboundV4StateProgressMinChunks(InboundTransferContext context)
        => ShouldAdvertiseInboundV4SparseWrittenProgressLocked(context)
            ? V6ReceiverStateProgressMinCommittedChunks
            : V4StateProgressCreditMinChunks;

    private async Task MaybeSendInboundSparseCreditFrontierStallStateAsync(InboundTransferContext context)
    {
        var shouldSend = false;
        lock (gate)
        {
            if (ReferenceEquals(inboundTransfer, context) &&
                !context.IsTerminal &&
                context.PullManifestReceived &&
                context.ReceiverSparseWriteActive &&
                ShouldSendInboundV4FrontierStallStateLocked(context, DateTimeOffset.UtcNow))
            {
                if (ShouldUsePostTunaFallbackV6FeedbackEnvelope(context) &&
                    TrySuppressRetiredFallbackTailOwnerUpdateLocked(
                        context,
                        context.CurrentTransferLeg,
                        "inbound_frontier_stall",
                        "send_receiver_state",
                        "frontier_stall_repair_due"))
                {
                    return;
                }

                shouldSend = true;
            }
        }

        if (shouldSend)
        {
            var stateSent = await SendInboundSparseCreditStateAsync(
                context,
                "frontier_stall_repair_due",
                terminalReady: false,
                requireMissingRange: true).ConfigureAwait(false);
            if (!stateSent &&
                TrySuppressInboundV4FollowupRepairForTunaActivationBarrier(
                    context,
                    "frontier_stall_repair_due",
                    ShouldUsePostTunaFallbackV6FeedbackEnvelope(context) ? "frontier_request" : "repair_request"))
            {
                return;
            }

            if (ShouldUsePostTunaFallbackV6FeedbackEnvelope(context))
            {
                await SendInboundV6FrontierRequestAsync(context, "frontier_stall_repair_due", forceSend: true).ConfigureAwait(false);
            }
            else
            {
                await SendInboundV6RepairRequestAsync(context, "frontier_stall_repair_due").ConfigureAwait(false);
            }
        }
    }

    private bool TrySuppressInboundV4FollowupRepairForTunaActivationBarrier(
        InboundTransferContext context,
        string reason,
        string followupKind)
    {
        string? pauseReason;
        int suppressedCount;
        int committedChunk;
        int highestReceivedChunk;
        long bytesTransferred;
        lock (gate)
        {
            if (!ReferenceEquals(inboundTransfer, context) ||
                context.IsTerminal ||
                !context.PullTransportPaused ||
                !IsTunaActivationNegotiationTransportPauseReason(context.PullTransportPauseReason))
            {
                return false;
            }

            pauseReason = context.PullTransportPauseReason;
            suppressedCount = context.TunaActivationBarrierStateSendSuppressedCount;
            committedChunk = context.NextChunkIndex;
            highestReceivedChunk = context.PullHighestReceivedChunkIndex;
            bytesTransferred = context.BytesTransferred;
        }

        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_regular_v4_followup_repair_suppressed_for_tuna_activation_barrier; direction=inbound; transfer_id={context.TransferId}; session_id={context.SessionId}; state_reason={FormatProtocolLogValue(reason)}; followup_kind={FormatProtocolLogValue(followupKind)}; pause_reason={FormatProtocolLogValue(pauseReason)}; suppressed_state_count={suppressedCount}; committed_chunk={committedChunk}; highest_received_chunk={highestReceivedChunk}; bytes_transferred={bytesTransferred}");
        return true;
    }

    private static bool ShouldSendInboundV4FrontierStallStateLocked(InboundTransferContext context, DateTimeOffset now)
    {
        if (context.UserPaused ||
            context.PeerPaused ||
            context.PullTransportPaused ||
            context.NextChunkIndex >= context.ChunkCount ||
            context.V4CreditUntilChunkIndexExclusive <= context.NextChunkIndex)
        {
            return false;
        }

        var frontierStallAgeMs = GetInboundV4FrontierStallAgeMsLocked(context, now);
        var repairRepeatIntervalMs = ResolveV4FrontierRepairRepeatIntervalMs(context);
        if (frontierStallAgeMs < repairRepeatIntervalMs)
        {
            return false;
        }

        var repairEndExclusive = Math.Min(
            context.ChunkCount,
            Math.Min(
                Math.Max(context.NextChunkIndex, context.V4CreditUntilChunkIndexExclusive),
                context.NextChunkIndex + V4RepairBurstMaxChunks));
        if (repairEndExclusive <= context.NextChunkIndex)
        {
            return false;
        }

        var previousFrontierRepair = FindRecentInboundV4FrontierTailRepairLocked(context, context.NextChunkIndex);
        return previousFrontierRepair?.LastRequestedUtc is null ||
            now - previousFrontierRepair.LastRequestedUtc.Value >= TimeSpan.FromMilliseconds(repairRepeatIntervalMs);
    }

    private async Task<bool> SendInboundV4CompleteAsync(
        InboundTransferContext context,
        string sessionId,
        string transferId,
        long fileSizeBytes,
        string sha256Base64,
        CancellationToken ct,
        bool failOnSendFailure = true)
    {
        IFileTransferDataSession? dataSession;
        lock (gate)
        {
            if (!ReferenceEquals(inboundTransfer, context) || context.IsTerminal)
            {
                return false;
            }

            dataSession = context.DataSession;
        }

        if (dataSession is null)
        {
            return false;
        }

        try
        {
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_complete_send_started; transfer_id={transferId}; session_id={sessionId}; file_size_bytes={fileSizeBytes}");
            FileTransferCompleteFrameV4 completeFrame = ShouldUseV6SparseCreditEnvelope(context)
                ? new FileTransferCompleteFrameV6
                {
                    SessionId = sessionId,
                    TransferId = transferId,
                    FileSizeBytes = fileSizeBytes,
                    Sha256Base64 = sha256Base64,
                }
                : new FileTransferCompleteFrameV4
                {
                    SessionId = sessionId,
                    TransferId = transferId,
                    FileSizeBytes = fileSizeBytes,
                    Sha256Base64 = sha256Base64,
                };
            await dataSession.SendAsync(completeFrame, ct).ConfigureAwait(false);
            LocalOperationalLog.Info(
                "FileTransferService",
                $"event=filetransfer_v4_complete_sent; transfer_id={transferId}; session_id={sessionId}; file_size_bytes={fileSizeBytes}");
            return true;
        }
        catch (Exception ex) when (ex is not OperationCanceledException || !failOnSendFailure)
        {
            if (!failOnSendFailure)
            {
                LocalOperationalLog.Warn(
                    "FileTransferService",
                    $"event=filetransfer_v4_complete_data_frame_echo_failed; transfer_id={transferId}; session_id={sessionId}; file_size_bytes={fileSizeBytes}; error={ex.GetType().Name}");
                return false;
            }

            await TransitionInboundToTerminalAsync(
                context,
                FileTransferTransferState.Failed,
                errorCode: InvalidStateErrorCode,
                statusMessage: ex.Message,
                sendError: true,
                errorMessage: "Could not send V4 completion.",
                cancelReason: null,
                ct: CancellationToken.None).ConfigureAwait(false);
            return false;
        }
    }

    private async Task FailInboundV4Async(InboundTransferContext context, string errorCode, string statusMessage, string errorMessage)
    {
        LocalOperationalLog.Warn(
            "FileTransferService",
            $"event=filetransfer_v4_receiver_failed; transfer_id={context.TransferId}; session_id={context.SessionId}; error_code={errorCode}; reason={FormatProtocolLogValue(statusMessage)}");
        await TransitionInboundToTerminalAsync(
            context,
            FileTransferTransferState.Failed,
            errorCode: errorCode,
            statusMessage: statusMessage,
            sendError: true,
            errorMessage: errorMessage,
            cancelReason: null,
            ct: CancellationToken.None).ConfigureAwait(false);
    }

    private async Task TrySendInboundV4ErrorAsync(InboundTransferContext context, string errorCode, string message)
    {
        IFileTransferDataSession? dataSession;
        string sessionId;
        string transferId;
        lock (gate)
        {
            if (!ReferenceEquals(inboundTransfer, context) || context.IsTerminal)
            {
                return;
            }

            dataSession = context.DataSession;
            sessionId = context.SessionId;
            transferId = context.TransferId;
        }

        if (dataSession is null)
        {
            return;
        }

        try
        {
            FileTransferErrorFrameV4 errorFrame = ShouldUseV6SparseCreditEnvelope(context)
                ? new FileTransferErrorFrameV6
                {
                    SessionId = sessionId,
                    TransferId = transferId,
                    ErrorCode = errorCode,
                    Message = message,
                }
                : new FileTransferErrorFrameV4
                {
                    SessionId = sessionId,
                    TransferId = transferId,
                    ErrorCode = errorCode,
                    Message = message,
                };
            await dataSession.SendAsync(errorFrame, context.LifetimeCts.Token).ConfigureAwait(false);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            LocalOperationalLog.Warn(
                "FileTransferService",
                $"event=filetransfer_v4_error_send_failed; transfer_id={transferId}; session_id={sessionId}; error_code={errorCode}; reason={FormatProtocolLogValue(ex.Message)}");
        }
    }

    private FileTransferStateFrameV4 CreateInboundV4StateLocked(
        InboundTransferContext context,
        string reason,
        bool terminalReady,
        bool forceMissingRange = false)
    {
        context.V4StateEpoch++;
        var missingRanges = BuildInboundV4MissingRangesLocked(context, forceMissingRange);

        var primaryRegularNknCheckpoint =
            context.RouteRuntime.UsesV6SparsePump &&
            string.Equals(reason, V6RegularNknCheckpointSyncRecoveryMode, StringComparison.Ordinal);
        if (primaryRegularNknCheckpoint)
        {
            context.V6RegularNknCheckpointSequence++;
        }

        var currentPostTunaFallbackLeg =
            context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
            IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg);
        var postTunaFallbackCheckpointPending =
            context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
            IsCurrentPostTunaFallbackLegCheckpointPending(context.CurrentTransferLeg) &&
            !string.IsNullOrWhiteSpace(context.CurrentTransferLeg!.CheckpointRequestId);
        var postTunaFallbackCheckpoint = postTunaFallbackCheckpointPending;
        var postTunaFallbackFrontierRepair =
            HasCurrentInboundPostTunaFallbackFrontierAuthorityLocked(context) &&
            !postTunaFallbackCheckpoint &&
            missingRanges.Count > 0 &&
            missingRanges[0].StartChunkIndex == context.NextChunkIndex &&
            missingRanges[0].ChunkCount > 0;
        var postTunaFallbackFrontierTransportEpoch = postTunaFallbackFrontierRepair
            ? context.V6ReceiverTransportEpoch > 0
                ? context.V6ReceiverTransportEpoch
                : context.CurrentTransferLeg!.TransportEpochId
            : 0;
        var postTunaFallbackFrontierRepairRequestId = postTunaFallbackFrontierRepair
            ? EnsureInboundPostTunaFallbackStateFrontierRepairRequestIdLocked(
                context,
                postTunaFallbackFrontierTransportEpoch,
                reason)
            : null;
        var postTunaFallbackFrontierRecoveryMode = postTunaFallbackFrontierRepair
            ? IsInboundV6RegularNknFrontierControlBulkEscalatedLocked(context, DateTimeOffset.UtcNow)
                ? "regular_nkn_frontier_stall_control_bulk"
                : "regular_nkn_frontier_stall"
            : null;
        var primaryRegularNknFrontierRepairRequestId = primaryRegularNknCheckpoint
            ? null
            : postTunaFallbackCheckpoint
                ? null
            : postTunaFallbackFrontierRepair
                ? null
            : EnsureInboundPrimaryRegularNknFrontierRepairTransactionLocked(context, missingRanges);

        var unresolvedV6Epoch = IsV6TransportEpochUnresolved(context.V6TransportEpoch)
            ? context.V6TransportEpoch
            : null;
        var receiverTransportEpoch = primaryRegularNknCheckpoint
            ? context.PullTransportRebindGeneration
            : postTunaFallbackCheckpoint
                ? context.CurrentTransferLeg!.TransportEpochId
            : postTunaFallbackFrontierRepair
                ? postTunaFallbackFrontierTransportEpoch
            : currentPostTunaFallbackLeg
                ? context.V6ReceiverTransportEpoch > 0
                    ? context.V6ReceiverTransportEpoch
                    : context.CurrentTransferLeg!.TransportEpochId
            : unresolvedV6Epoch?.EpochId ?? context.V6TransportHandoff?.EpochId ?? 0;
        var receiverRepairRequestId = primaryRegularNknCheckpoint
            ? context.V6RegularNknLastCheckpointSyncRequestId ?? $"checkpoint:{context.V6RegularNknCheckpointSequence}"
            : postTunaFallbackCheckpoint
                ? context.CurrentTransferLeg!.CheckpointRequestId
            : postTunaFallbackFrontierRepair
                ? postTunaFallbackFrontierRepairRequestId
            : currentPostTunaFallbackLeg
                ? null
            : primaryRegularNknFrontierRepairRequestId ?? unresolvedV6Epoch?.LastRepairRequestId ?? context.V6TransportHandoff?.LastRepairRequestId;
        var receiverPriority = primaryRegularNknCheckpoint
            ? V6RegularNknCheckpointSyncPriority
            : postTunaFallbackCheckpoint
                ? context.CurrentTransferLeg!.CheckpointPriority ?? V6RegularNknStateRefreshPriority
            : postTunaFallbackFrontierRepair
                ? "frontier"
            : currentPostTunaFallbackLeg
                ? null
            : primaryRegularNknFrontierRepairRequestId is not null
                ? V6RegularNknFrontierRepairTransactionPriority
            : unresolvedV6Epoch is not null
                ? unresolvedV6Epoch.State == V6TransportEpochState.BackfillRepair
                    ? "backfill"
                    : "frontier"
                : context.V6TransportHandoff is null
                    ? null
                    : context.V6TransportHandoff.State == V6TransportHandoffState.BackfillRepair
                        ? "backfill"
                        : "frontier";
        var receiverRecoveryMode = primaryRegularNknCheckpoint
            ? V6RegularNknCheckpointSyncRecoveryMode
            : postTunaFallbackCheckpoint
                ? V6RegularNknStateRefreshRecoveryMode
            : postTunaFallbackFrontierRepair
                ? postTunaFallbackFrontierRecoveryMode
            : currentPostTunaFallbackLeg
                ? null
            : primaryRegularNknFrontierRepairRequestId is not null
                ? V6RegularNknFrontierRepairTransactionRecoveryMode
            : unresolvedV6Epoch is not null
                ? FormatV6TransportEpochState(unresolvedV6Epoch.State)
                : context.V6TransportHandoff is null
                    ? null
                    : FormatV6TransportHandoffState(context.V6TransportHandoff.State);
        var bytesCommitted = ResolveInboundV4StateBytesCommittedLocked(context);

        if (!ShouldUseV6SparseCreditEnvelope(context))
        {
            return new FileTransferStateFrameV4
            {
                SessionId = context.SessionId,
                TransferId = context.TransferId,
                Epoch = context.V4StateEpoch,
                ContiguousCommittedChunkIndex = context.NextChunkIndex,
                DurableReceivedHighestChunkIndex = context.PullHighestReceivedChunkIndex,
                CreditUntilChunkIndexExclusive = context.V4CreditUntilChunkIndexExclusive,
                MissingRanges = missingRanges,
                BytesCommitted = bytesCommitted,
                ReceiverMemoryPressure = context.ReceiverBufferPressureActive,
                ReceiverDiskPressure = false,
                TerminalReady = terminalReady,
                TransferPaused = context.UserPaused,
                TransferPauseReason = context.UserPauseReason,
            };
        }

        return new FileTransferReceiverStateFrameV6
        {
            SessionId = context.SessionId,
            TransferId = context.TransferId,
            Epoch = context.V4StateEpoch,
            ContiguousCommittedChunkIndex = context.NextChunkIndex,
            DurableReceivedHighestChunkIndex = context.PullHighestReceivedChunkIndex,
            CreditUntilChunkIndexExclusive = context.V4CreditUntilChunkIndexExclusive,
            MissingRanges = missingRanges,
            BytesCommitted = bytesCommitted,
            ReceiverMemoryPressure = context.ReceiverBufferPressureActive,
            ReceiverDiskPressure = false,
            TerminalReady = terminalReady,
            TransferPaused = context.UserPaused,
            TransferPauseReason = context.UserPauseReason,
            TransportEpoch = receiverTransportEpoch,
            RepairRequestId = receiverRepairRequestId,
            Priority = receiverPriority,
            RecoveryMode = receiverRecoveryMode,
        };
    }

    private static string? EnsureInboundPostTunaFallbackStateFrontierRepairRequestIdLocked(
        InboundTransferContext context,
        long transportEpoch,
        string reason)
    {
        if (!HasCurrentInboundPostTunaFallbackFrontierAuthorityLocked(context) ||
            context.NextChunkIndex < 0 ||
            context.NextChunkIndex >= context.ChunkCount)
        {
            return null;
        }

        var currentId = context.V6LastFrontierRequestId?.Trim();
        if (context.V6LastFrontierRequestChunkIndex == context.NextChunkIndex &&
            !string.IsNullOrWhiteSpace(currentId) &&
            IsCurrentInboundPostTunaFallbackStateFrontierRepairRequestId(currentId, transportEpoch))
        {
            return currentId;
        }

        context.V6FrontierRequestSequence++;
        var repairRequestId = transportEpoch > 0
            ? $"v6-state-frontier:{transportEpoch}:{context.NextChunkIndex}:{context.V6FrontierRequestSequence}"
            : $"v6-state-frontier:{context.NextChunkIndex}:{context.V6FrontierRequestSequence}";
        context.V6LastFrontierRequestChunkIndex = context.NextChunkIndex;
        context.V6LastFrontierRequestId = repairRequestId;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event=filetransfer_v6_post_tuna_fallback_state_frontier_repair_id_allocated; direction=inbound; transfer_id={context.TransferId}; session_id={context.SessionId}; route={context.RouteSelection.TelemetryToken}; protocol_version={context.NegotiatedDataProtocolVersion}; transport_epoch={transportEpoch}; frontier_chunk_index={context.NextChunkIndex}; repair_request_id={FormatProtocolLogValue(repairRequestId)}; reason={FormatProtocolLogValue(reason)}");
        return repairRequestId;
    }

    private static bool HasCurrentInboundPostTunaFallbackCheckpointAuthorityLocked(InboundTransferContext context)
        => context.RouteRuntime.UsesPostTunaFallbackV6Runtime &&
           context.NegotiatedDataProtocolVersion >= FileTransferProtocol.ProtocolVersionV6 &&
           IsCurrentPostTunaFallbackLeg(context.CurrentTransferLeg) &&
           context.V6TransportEpoch is not { TargetTransport: FileTransferTransportKind.Tuna };

    private static bool HasCurrentInboundPostTunaFallbackFrontierAuthorityLocked(InboundTransferContext context)
        => HasCurrentInboundPostTunaFallbackCheckpointAuthorityLocked(context);

    private static bool IsCurrentInboundPostTunaFallbackStateFrontierRepairRequestId(
        string repairRequestId,
        long transportEpoch)
    {
        if (transportEpoch <= 0)
        {
            return true;
        }

        return !repairRequestId.StartsWith("v6-state-frontier:", StringComparison.Ordinal) ||
               repairRequestId.StartsWith($"v6-state-frontier:{transportEpoch}:", StringComparison.Ordinal);
    }

    private static long ResolveInboundV4StateBytesCommittedLocked(InboundTransferContext context)
    {
        var bytesCommitted = context.BytesTransferred;
        if (ShouldAdvertiseInboundV4SparseWrittenProgressLocked(context))
        {
            bytesCommitted = Math.Max(bytesCommitted, context.ReceiverSparseBytesWritten);
        }

        return Math.Clamp(bytesCommitted, 0L, Math.Max(0L, context.FileSizeBytes));
    }

    private static bool ShouldAdvertiseInboundV4SparseWrittenProgressLocked(InboundTransferContext context)
        => context.ReceiverSparseWriteActive &&
           (context.NegotiatedDataProtocolVersion == FileTransferProtocol.ProtocolVersionV4 ||
            context.RouteRuntime.UsesV6SparsePump) &&
           context.V6TransportHandoff is null &&
           !context.PullPostTunaRecoveryActive;

    private static string FormatInboundRegularV4FrontierRepairProjectionKind(
        InboundRegularV4FrontierRepairProjectionKind kind)
        => kind switch
        {
            InboundRegularV4FrontierRepairProjectionKind.InitialDue => "initial_due",
            InboundRegularV4FrontierRepairProjectionKind.RetainedCurrent => "retained_current",
            InboundRegularV4FrontierRepairProjectionKind.Narrowed => "narrowed",
            InboundRegularV4FrontierRepairProjectionKind.RetiredAuthorityRetained => "retired_authority_retained",
            _ => "unknown",
        };

    private static IReadOnlyList<FileTransferRangeV4> CloneInboundRegularV4FrontierRepairProjectionRanges(
        IReadOnlyList<FileTransferRangeV4> ranges)
        => ranges
            .Where(static range => range.ChunkCount > 0)
            .Select(static range => new FileTransferRangeV4
            {
                StartChunkIndex = range.StartChunkIndex,
                ChunkCount = range.ChunkCount,
            })
            .ToArray();

    private static bool InboundRegularV4FrontierRepairProjectionRangesEqual(
        IReadOnlyList<FileTransferRangeV4> first,
        IReadOnlyList<FileTransferRangeV4> second)
    {
        if (first.Count != second.Count)
        {
            return false;
        }

        for (var index = 0; index < first.Count; index++)
        {
            if (first[index].StartChunkIndex != second[index].StartChunkIndex ||
                first[index].ChunkCount != second[index].ChunkCount)
            {
                return false;
            }
        }

        return true;
    }

    private static string CreateInboundRegularV4FrontierRepairProjectionRangeFingerprint(
        IReadOnlyList<FileTransferRangeV4> ranges,
        int chunkCount,
        int durableReceivedHighestChunkIndex)
        => CreateFallbackFrontierRepairIdentity(ranges, chunkCount, durableReceivedHighestChunkIndex)?.RangeFingerprint ??
           "(none)";

    private static string FormatInboundRegularV4FrontierRepairProjectionRanges(
        IReadOnlyList<FileTransferRangeV4> ranges)
        => ranges.Count == 0
            ? "(none)"
            : string.Join(",", ranges.Select(static range => $"{range.StartChunkIndex}:{range.ChunkCount}"));

    private static bool HasInboundRegularV4DurableFrontierGapLocked(InboundTransferContext context)
        => context.ReceiverSparseChunksWritten is { } written &&
           context.NextChunkIndex >= 0 &&
           context.NextChunkIndex < context.ChunkCount &&
           context.PullHighestReceivedChunkIndex >= context.NextChunkIndex &&
           !written[context.NextChunkIndex];

    private static bool IsInboundRegularV4FrontierRepairProjectionScopeCurrentLocked(
        InboundTransferContext context,
        InboundRegularV4FrontierRepairProjection projection,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        var authority = projection.SourceContract.Authority;
        if (context.IsTerminal)
        {
            rejectionReason = "transfer_terminal";
            return false;
        }

        if (!IsCurrentRegularV4FrontierRepairRuntime(context))
        {
            rejectionReason = "regular_v4_runtime_replaced";
            return false;
        }

        if (!string.Equals(context.SessionId, authority.SessionId, StringComparison.Ordinal) ||
            !string.Equals(context.TransferId, authority.TransferId, StringComparison.Ordinal) ||
            authority.Direction != FileTransferDirection.Inbound)
        {
            rejectionReason = "transfer_identity_mismatch";
            return false;
        }

        if (context.CurrentRuntimeOwner is not { } owner ||
            !string.Equals(owner.SessionId, authority.SessionId, StringComparison.Ordinal) ||
            !string.Equals(owner.TransferId, authority.TransferId, StringComparison.Ordinal) ||
            owner.Direction != authority.Direction ||
            !string.Equals(owner.RouteToken, authority.RouteToken, StringComparison.Ordinal) ||
            owner.ProtocolVersion != authority.ProtocolVersion ||
            owner.LiveRouteEpoch != authority.LiveRouteEpoch ||
            owner.RuntimeGeneration != authority.RuntimeGeneration ||
            owner.TerminalGeneration != authority.TerminalGeneration)
        {
            rejectionReason = "runtime_owner_mismatch";
            return false;
        }

        if (context.CurrentRoutePublicationToken is not { IsDefault: false } publication ||
            !string.Equals(publication.SessionId, authority.SessionId, StringComparison.Ordinal) ||
            !string.Equals(publication.TransferId, authority.TransferId, StringComparison.Ordinal) ||
            publication.Direction != authority.Direction ||
            !string.Equals(publication.RouteToken, authority.RouteToken, StringComparison.Ordinal) ||
            publication.ProtocolVersion != authority.ProtocolVersion ||
            publication.LiveRouteEpoch != authority.LiveRouteEpoch ||
            publication.RuntimeGeneration != authority.RuntimeGeneration ||
            publication.TerminalGeneration != authority.TerminalGeneration ||
            publication.LegGeneration != authority.LegGeneration ||
            publication.PublicationGeneration != authority.RoutePublicationGeneration ||
            publication.RouteCommitGeneration != authority.RouteCommitGeneration ||
            publication.TargetTransport != authority.TargetTransport)
        {
            rejectionReason = "route_publication_mismatch";
            return false;
        }

        if (context.CurrentTransferLeg is not { } leg ||
            leg.Generation != authority.LegGeneration ||
            leg.ProtocolVersion != authority.ProtocolVersion ||
            leg.LiveRouteEpochId != authority.LiveRouteEpoch ||
            leg.TransportEpochId != authority.TransportEpoch ||
            leg.BridgeRecoveryGeneration != authority.BridgeRecoveryGeneration ||
            !string.Equals(leg.RouteSelection.TelemetryToken, authority.RouteToken, StringComparison.Ordinal))
        {
            rejectionReason = "transfer_leg_mismatch";
            return false;
        }

        var currentBridgeDecisionGeneration = context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ?? 0;
        if (currentBridgeDecisionGeneration != authority.BridgeDecisionGeneration)
        {
            rejectionReason = "bridge_decision_generation_mismatch";
            return false;
        }

        if (context.DataSessionGeneration != projection.DataSessionGeneration)
        {
            rejectionReason = "data_session_generation_mismatch";
            return false;
        }

        if (!projection.SourceContract.Lifecycle.IsSettled &&
            !IsRegularV4FrontierRepairContractCurrent(
                context,
                projection.SourceContract,
                out _))
        {
            rejectionReason = "source_repair_authority_replaced";
            return false;
        }

        return true;
    }

    private static IReadOnlyList<FileTransferRangeV4> BuildInboundRegularV4DurableProjectionRangesLocked(
        InboundTransferContext context,
        InboundRegularV4FrontierRepairProjection projection)
    {
        if (context.ReceiverSparseChunksWritten is not { } written ||
            context.PullHighestReceivedChunkIndex < projection.FrontierChunkIndex)
        {
            return [];
        }

        var ranges = new List<FileTransferRangeV4>();
        var upperExclusive = Math.Min(context.ChunkCount, context.PullHighestReceivedChunkIndex + 1);
        foreach (var sourceRange in projection.SourceRanges)
        {
            var sourceStart = Math.Max(projection.FrontierChunkIndex, sourceRange.StartChunkIndex);
            var sourceEndExclusive = (int)Math.Clamp(
                (long)sourceRange.StartChunkIndex + Math.Max(0, sourceRange.ChunkCount),
                sourceStart,
                upperExclusive);
            var chunkIndex = sourceStart;
            while (chunkIndex < sourceEndExclusive && ranges.Count < FileTransferProtocol.MaxStateMissingRangesV4)
            {
                while (chunkIndex < sourceEndExclusive && written[chunkIndex])
                {
                    chunkIndex++;
                }

                if (chunkIndex >= sourceEndExclusive)
                {
                    break;
                }

                var start = chunkIndex;
                while (chunkIndex < sourceEndExclusive && !written[chunkIndex])
                {
                    chunkIndex++;
                }

                ranges.Add(new FileTransferRangeV4
                {
                    StartChunkIndex = start,
                    ChunkCount = chunkIndex - start,
                });
            }

            if (ranges.Count >= FileTransferProtocol.MaxStateMissingRangesV4)
            {
                break;
            }
        }

        return ranges;
    }

    private static IReadOnlyList<FileTransferRangeV4> BuildInboundRegularV4DurableFrontierProjectionRangesLocked(
        InboundTransferContext context,
        int maximumMissingChunks)
    {
        if (context.ReceiverSparseChunksWritten is not { } written ||
            context.NextChunkIndex < 0 ||
            context.NextChunkIndex >= context.ChunkCount ||
            context.PullHighestReceivedChunkIndex < context.NextChunkIndex ||
            maximumMissingChunks <= 0)
        {
            return [];
        }

        var ranges = new List<FileTransferRangeV4>();
        var upperInclusive = Math.Min(context.ChunkCount - 1, context.PullHighestReceivedChunkIndex);
        var chunkIndex = context.NextChunkIndex;
        var projectedMissingChunks = 0;
        while (chunkIndex <= upperInclusive &&
               ranges.Count < FileTransferProtocol.MaxStateMissingRangesV4 &&
               projectedMissingChunks < maximumMissingChunks)
        {
            while (chunkIndex <= upperInclusive && written[chunkIndex])
            {
                chunkIndex++;
            }

            if (chunkIndex > upperInclusive)
            {
                break;
            }

            var start = chunkIndex;
            var count = 0;
            while (chunkIndex <= upperInclusive &&
                   !written[chunkIndex] &&
                   projectedMissingChunks + count < maximumMissingChunks)
            {
                count++;
                chunkIndex++;
            }

            if (count > 0)
            {
                ranges.Add(new FileTransferRangeV4
                {
                    StartChunkIndex = start,
                    ChunkCount = count,
                });
                projectedMissingChunks += count;
            }
        }

        return ranges;
    }

    private static string FormatInboundRegularV4FrontierRepairProjectionTuple(
        InboundRegularV4FrontierRepairProjection projection)
    {
        var authority = projection.SourceContract.Authority;
        var lifecycle = projection.SourceContract.Lifecycle;
        return $"authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(authority.PredecessorAuthorityId?.ToString() ?? "(none)")}; direction=inbound; transfer_id={FormatProtocolLogValue(authority.TransferId)}; session_id={FormatProtocolLogValue(authority.SessionId)}; route={FormatProtocolLogValue(authority.RouteToken)}; protocol_version={authority.ProtocolVersion}; live_route_epoch={authority.LiveRouteEpoch}; runtime_generation={authority.RuntimeGeneration}; terminal_generation={authority.TerminalGeneration}; leg_generation={authority.LegGeneration}; transport_epoch={authority.TransportEpoch}; bridge_recovery_generation={authority.BridgeRecoveryGeneration}; bridge_decision_generation={authority.BridgeDecisionGeneration}; data_session_generation={projection.DataSessionGeneration}; route_publication_generation={authority.RoutePublicationGeneration}; route_commit_generation={authority.RouteCommitGeneration ?? 0}; repair_generation={authority.DecisionGeneration}; source_repair_request_key={FormatProtocolLogValue(projection.SourceRepairKey)}; projected_repair_request_key={FormatProtocolLogValue(projection.ProjectedRepairKey)}; source_range_fingerprint={FormatProtocolLogValue(projection.SourceRangeFingerprint)}; projected_range_fingerprint={FormatProtocolLogValue(projection.ProjectedRangeFingerprint)}; source_ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(projection.SourceRanges))}; projected_ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(projection.ProjectedRanges))}; projection_generation={projection.ProjectionGeneration}; projection_kind={FormatInboundRegularV4FrontierRepairProjectionKind(projection.Kind)}; source_authority_lifecycle={(lifecycle.IsSettled ? "retired" : "active")}; source_authority_settlement={FormatProtocolLogValue(lifecycle.SettlementOutcome?.ToString() ?? "(none)")}; source_authority_settlement_reason={FormatProtocolLogValue(lifecycle.SettlementReason ?? "(none)")}; frontier_chunk_index={projection.FrontierChunkIndex}; durable_received_highest_chunk_index={projection.DurableReceivedHighestChunkIndex}; source_range_count={projection.SourceRanges.Count}; projected_range_count={projection.ProjectedRanges.Count}; projected_chunk_count={projection.ProjectedRanges.Sum(static range => range.ChunkCount)}; target_transport={FormatFileTransferTransportKind(authority.TargetTransport)}";
    }

    private static InboundRegularV4FrontierRepairProjectionRefreshSource?
        CreateInboundRegularV4FrontierRepairProjectionRefreshSourceLocked(
            InboundTransferContext context,
            InboundRegularV4FrontierRepairProjection projection)
    {
        if (context.CurrentRuntimeOwner is not { } owner ||
            context.CurrentRoutePublicationToken is not { IsDefault: false } publication ||
            context.CurrentTransferLeg is not { } leg)
        {
            return null;
        }

        return new InboundRegularV4FrontierRepairProjectionRefreshSource(
            projection,
            context.SessionId,
            context.TransferId,
            publication.RouteToken,
            publication.ProtocolVersion,
            publication.LiveRouteEpoch,
            owner.RuntimeGeneration,
            owner.TerminalGeneration,
            leg.Generation,
            leg.TransportEpochId,
            leg.BridgeRecoveryGeneration,
            context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ?? 0,
            publication.PublicationGeneration,
            publication.RouteCommitGeneration,
            context.DataSessionGeneration);
    }

    private static bool IsInboundRegularV4FrontierRepairProjectionRefreshSourceCurrentLocked(
        InboundTransferContext context,
        InboundRegularV4FrontierRepairProjectionRefreshSource refreshSource)
        => !context.IsTerminal &&
           IsCurrentRegularV4FrontierRepairRuntime(context) &&
           context.CurrentRuntimeOwner is { } owner &&
           context.CurrentRoutePublicationToken is { IsDefault: false } publication &&
           context.CurrentTransferLeg is { } leg &&
           string.Equals(context.SessionId, refreshSource.SessionId, StringComparison.Ordinal) &&
           string.Equals(context.TransferId, refreshSource.TransferId, StringComparison.Ordinal) &&
           string.Equals(publication.RouteToken, refreshSource.RouteToken, StringComparison.Ordinal) &&
           publication.ProtocolVersion == refreshSource.ProtocolVersion &&
           publication.LiveRouteEpoch == refreshSource.LiveRouteEpoch &&
           owner.RuntimeGeneration == refreshSource.RuntimeGeneration &&
           owner.TerminalGeneration == refreshSource.TerminalGeneration &&
           leg.Generation == refreshSource.LegGeneration &&
           leg.TransportEpochId == refreshSource.TransportEpoch &&
           leg.BridgeRecoveryGeneration == refreshSource.BridgeRecoveryGeneration &&
           (context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ?? 0) ==
           refreshSource.BridgeDecisionGeneration &&
           publication.PublicationGeneration == refreshSource.RoutePublicationGeneration &&
           publication.RouteCommitGeneration == refreshSource.RouteCommitGeneration &&
           context.DataSessionGeneration == refreshSource.DataSessionGeneration;

    private static string FormatInboundRegularV4FrontierRepairProjectionRefreshTupleLocked(
        InboundTransferContext context,
        IReadOnlyList<FileTransferRangeV4>? requiredRanges = null)
    {
        var refreshSource = context.V4RegularFrontierRepairProjectionRefreshSource;
        var sourceProjection = refreshSource?.Projection;
        var sourceAuthority = sourceProjection?.SourceContract.Authority;
        var currentRequiredRanges = requiredRanges ??
            (sourceProjection is null
                ? []
                : BuildInboundRegularV4DurableProjectionRangesLocked(context, sourceProjection));
        var requiredRangeFingerprint = CreateInboundRegularV4FrontierRepairProjectionRangeFingerprint(
            currentRequiredRanges,
            context.ChunkCount,
            context.PullHighestReceivedChunkIndex);
        return $"bridge_decision_generation={context.CurrentBridgeRecoveryDecision?.BridgeDecisionGeneration ?? 0}; data_session_generation={context.DataSessionGeneration}; refresh_source_authority_id={FormatProtocolLogValue(sourceAuthority?.AuthorityId.ToString() ?? "(none)")}; refresh_source_repair_request_key={FormatProtocolLogValue(sourceProjection?.ProjectedRepairKey ?? sourceAuthority?.RepairKey ?? "(none)")}; refresh_source_bridge_decision_generation={sourceAuthority?.BridgeDecisionGeneration ?? 0}; refresh_source_data_session_generation={sourceProjection?.DataSessionGeneration ?? 0}; refresh_target_bridge_decision_generation={refreshSource?.BridgeDecisionGeneration ?? 0}; refresh_target_data_session_generation={refreshSource?.DataSessionGeneration ?? 0}; required_ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(currentRequiredRanges))}; required_range_fingerprint={FormatProtocolLogValue(requiredRangeFingerprint)}";
    }

    private static void LogInboundRegularV4FrontierRepairProjectionEvent(
        string eventName,
        InboundRegularV4FrontierRepairProjection projection,
        string reason,
        InboundRegularV4FrontierRepairProjectionRefreshSource? refreshSource = null)
        => LocalOperationalLog.Info(
            "FileTransferService",
            $"event={eventName}; {FormatInboundRegularV4FrontierRepairProjectionTuple(projection)}; refresh_source_authority_id={FormatProtocolLogValue(refreshSource?.Projection.SourceContract.Authority.AuthorityId.ToString() ?? "(none)")}; refresh_source_repair_request_key={FormatProtocolLogValue(refreshSource?.Projection.ProjectedRepairKey ?? "(none)")}; refresh_source_bridge_decision_generation={refreshSource?.Projection.SourceContract.Authority.BridgeDecisionGeneration ?? 0}; refresh_source_data_session_generation={refreshSource?.Projection.DataSessionGeneration ?? 0}; refresh_target_bridge_decision_generation={refreshSource?.BridgeDecisionGeneration ?? 0}; refresh_target_data_session_generation={refreshSource?.DataSessionGeneration ?? 0}; decision_reason={FormatProtocolLogValue(reason)}");

    private static void ClearInboundRegularV4FrontierRepairProjectionLocked(
        InboundTransferContext context,
        string reason,
        bool requireFreshProjection)
    {
        var projection = context.V4RegularFrontierRepairProjection;
        if (projection is not null)
        {
            LogInboundRegularV4FrontierRepairProjectionEvent(
                "filetransfer_regular_v4_frontier_repair_projection_cleared",
                projection,
                reason);
        }

        var refreshRequired =
            requireFreshProjection &&
            HasInboundRegularV4DurableFrontierGapLocked(context);
        if (refreshRequired && projection is not null)
        {
            context.V4RegularFrontierRepairProjectionRefreshSource =
                CreateInboundRegularV4FrontierRepairProjectionRefreshSourceLocked(context, projection);
        }
        else if (!refreshRequired)
        {
            context.V4RegularFrontierRepairProjectionRefreshSource = null;
        }

        context.V4RegularFrontierRepairProjection = null;
        context.V4RegularFrontierRepairProjectionRefreshRequired = refreshRequired;
    }

    private static void RejectInboundRegularV4FrontierRepairProjectionLocked(
        InboundTransferContext context,
        InboundRegularV4FrontierRepairProjection projection,
        string reason,
        bool requireFreshProjection)
    {
        LogInboundRegularV4FrontierRepairProjectionEvent(
            "filetransfer_regular_v4_frontier_repair_projection_rejected",
            projection,
            reason);
        ClearInboundRegularV4FrontierRepairProjectionLocked(context, reason, requireFreshProjection);
    }

    private static bool TryRefreshInboundRegularV4FrontierRepairProjectionLocked(
        InboundTransferContext context,
        out InboundRegularV4FrontierRepairProjection? projection)
    {
        projection = context.V4RegularFrontierRepairProjection;
        if (projection is null)
        {
            return false;
        }

        if (!IsInboundRegularV4FrontierRepairProjectionScopeCurrentLocked(context, projection, out var rejectionReason))
        {
            RejectInboundRegularV4FrontierRepairProjectionLocked(
                context,
                projection,
                rejectionReason,
                requireFreshProjection: true);
            projection = null;
            return false;
        }

        var settlementOutcome = projection.SourceContract.Lifecycle.SettlementOutcome;
        if (settlementOutcome is
            FileTransferRegularV4FrontierRepairSettlementOutcome.TransferTerminal or
            FileTransferRegularV4FrontierRepairSettlementOutcome.TerminalRejected)
        {
            ClearInboundRegularV4FrontierRepairProjectionLocked(
                context,
                $"source_authority_{NormalizeReason(settlementOutcome.Value.ToString())}",
                requireFreshProjection: false);
            projection = null;
            return false;
        }

        if (context.NextChunkIndex > projection.FrontierChunkIndex)
        {
            if (!HasInboundRegularV4DurableFrontierGapLocked(context))
            {
                ClearInboundRegularV4FrontierRepairProjectionLocked(
                    context,
                    "frontier_advanced_gap_resolved",
                    requireFreshProjection: false);
            }
            else
            {
                // Retain only the exact coordinator lineage while the new frontier
                // obtains a successor authority. The old range is not returned or
                // published after this boundary.
                context.V4RegularFrontierRepairProjectionRefreshSource =
                    CreateInboundRegularV4FrontierRepairProjectionRefreshSourceLocked(context, projection);
                context.V4RegularFrontierRepairProjectionRefreshRequired = true;
            }
            projection = null;
            return false;
        }

        var projectedRanges = BuildInboundRegularV4DurableProjectionRangesLocked(context, projection);
        if (projectedRanges.Count == 0)
        {
            ClearInboundRegularV4FrontierRepairProjectionLocked(
                context,
                "range_filled",
                requireFreshProjection: false);
            projection = null;
            return false;
        }

        var projectedRepairKey = CreateV4RepairRequestKey(
            context.TransferId,
            projectedRanges[0].StartChunkIndex,
            projectedRanges.Sum(static range => range.ChunkCount),
            context.NextChunkIndex,
            context.PullHighestReceivedChunkIndex,
            projectedRanges);
        var projectedFingerprint = CreateInboundRegularV4FrontierRepairProjectionRangeFingerprint(
            projectedRanges,
            context.ChunkCount,
            context.PullHighestReceivedChunkIndex);
        var projectionKind = projection.SourceContract.Lifecycle.IsSettled
            ? InboundRegularV4FrontierRepairProjectionKind.RetiredAuthorityRetained
            : InboundRegularV4FrontierRepairProjectionRangesEqual(projection.ProjectedRanges, projectedRanges)
                ? InboundRegularV4FrontierRepairProjectionKind.RetainedCurrent
                : InboundRegularV4FrontierRepairProjectionKind.Narrowed;
        if (!InboundRegularV4FrontierRepairProjectionRangesEqual(projection.ProjectedRanges, projectedRanges) ||
            projection.Kind != projectionKind ||
            projection.DurableReceivedHighestChunkIndex != context.PullHighestReceivedChunkIndex)
        {
            context.LastV4RegularFrontierRepairProjectionGeneration++;
            projection = projection with
            {
                ProjectionGeneration = context.LastV4RegularFrontierRepairProjectionGeneration,
                ProjectedRepairKey = projectedRepairKey,
                ProjectedRanges = CloneInboundRegularV4FrontierRepairProjectionRanges(projectedRanges),
                ProjectedRangeFingerprint = projectedFingerprint,
                DurableReceivedHighestChunkIndex = context.PullHighestReceivedChunkIndex,
                Kind = projectionKind,
            };
            context.V4RegularFrontierRepairProjection = projection;
            LogInboundRegularV4FrontierRepairProjectionEvent(
                "filetransfer_regular_v4_frontier_repair_projection_retained",
                projection,
                projectionKind == InboundRegularV4FrontierRepairProjectionKind.Narrowed
                    ? "durable_projection_narrowed"
                    : projectionKind == InboundRegularV4FrontierRepairProjectionKind.RetiredAuthorityRetained
                        ? "attempt_authority_retired_projection_retained"
                        : "durable_projection_current");
        }

        return true;
    }

    private static InboundRegularV4FrontierRepairProjection? StageInboundRegularV4FrontierRepairProjectionLocked(
        InboundTransferContext context,
        V4ReceiverRepairRequestState repairState,
        IReadOnlyList<FileTransferRangeV4> ranges,
        InboundRegularV4FrontierRepairProjectionKind kind,
        string reason)
    {
        if (repairState.RegularV4RepairContract is not { } contract ||
            contract.Lifecycle.IsSettled ||
            !IsRegularV4FrontierRepairContractCurrent(context, contract, out _) ||
            !IsCurrentRegularV4FrontierRepairRuntime(context) ||
            ranges.Count == 0 ||
            ranges[0].StartChunkIndex != context.NextChunkIndex ||
            context.PullHighestReceivedChunkIndex < context.NextChunkIndex)
        {
            return null;
        }

        var sourceRanges = CloneInboundRegularV4FrontierRepairProjectionRanges(ranges);
        if (sourceRanges.Count == 0)
        {
            return null;
        }

        if (context.V4RegularFrontierRepairProjection is { } replacedProjection &&
            replacedProjection.SourceContract.Authority.AuthorityId != contract.Authority.AuthorityId)
        {
            LogInboundRegularV4FrontierRepairProjectionEvent(
                "filetransfer_regular_v4_frontier_repair_projection_cleared",
                replacedProjection,
                "successor_projection_installed");
        }

        context.LastV4RegularFrontierRepairProjectionGeneration++;
        var fingerprint = CreateInboundRegularV4FrontierRepairProjectionRangeFingerprint(
            sourceRanges,
            context.ChunkCount,
            context.PullHighestReceivedChunkIndex);
        var projection = new InboundRegularV4FrontierRepairProjection(
            context.LastV4RegularFrontierRepairProjectionGeneration,
            contract.Authority.RepairKey,
            contract.Authority.RepairKey,
            sourceRanges,
            sourceRanges,
            fingerprint,
            fingerprint,
            context.NextChunkIndex,
            context.PullHighestReceivedChunkIndex,
            context.DataSessionGeneration,
            contract,
            kind);
        var refreshSource = context.V4RegularFrontierRepairProjectionRefreshSource;
        context.V4RegularFrontierRepairProjection = projection;
        context.V4RegularFrontierRepairProjectionRefreshRequired = false;
        context.V4RegularFrontierRepairProjectionRefreshSource = null;
        LogInboundRegularV4FrontierRepairProjectionEvent(
            "filetransfer_regular_v4_frontier_repair_projection_retained",
            projection,
            reason,
            refreshSource);
        return projection;
    }

    private bool TryCaptureInboundRegularV4FrontierTailRepairStateAuthorityLocked(
        InboundTransferContext context,
        FileTransferStateFrameV4 state,
        out InboundRegularV4FrontierTailRepairStateAuthority? stateAuthority)
    {
        stateAuthority = null;
        if (state.MissingRanges.Count == 0 ||
            state.DurableReceivedHighestChunkIndex >= state.ContiguousCommittedChunkIndex ||
            context.V4RegularFrontierRepairProjection is not null ||
            context.CurrentRegularV4FrontierRepairContract is not { } contract ||
            context.DataSession is not { } dataSession)
        {
            return false;
        }

        var repairState = context.V4ReceiverRepairRequests.Values.FirstOrDefault(candidate =>
            candidate.FrontierRepair &&
            candidate.FrontierTailRepair &&
            ReferenceEquals(candidate.RegularV4RepairContract, contract) &&
            string.Equals(candidate.RepairRequestKey, contract.Authority.RepairKey, StringComparison.Ordinal) &&
            InboundRegularV4FrontierRepairProjectionRangesEqual(candidate.Ranges, state.MissingRanges));
        if (repairState is null ||
            !IsInboundRegularV4FrontierTailRepairAttemptCurrentLocked(
                context,
                repairState,
                state.MissingRanges,
                out _) ||
            !TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                contract.Authority.AuthorityId,
                out var installedBinding,
                out _,
                out _))
        {
            return false;
        }

        var ranges = CloneInboundRegularV4FrontierRepairProjectionRanges(state.MissingRanges);
        stateAuthority = new InboundRegularV4FrontierTailRepairStateAuthority(
            contract,
            contract.Authority,
            installedBinding.InstallGeneration,
            repairState.RepairRequestKey,
            ranges,
            CreateInboundRegularV4FrontierRepairProjectionRangeFingerprint(
                ranges,
                context.ChunkCount,
                context.PullHighestReceivedChunkIndex),
            context.NextChunkIndex,
            context.PullHighestReceivedChunkIndex,
            dataSession,
            context.DataSessionGeneration);
        return true;
    }

    private bool IsInboundRegularV4FrontierRepairPressureInstalledLocked(
        InboundTransferContext context,
        RegularV4FrontierRepairContract contract,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (!ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, contract) ||
            contract.Lifecycle.IsSettled ||
            !TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                contract.Authority.AuthorityId,
                out var binding,
                out _,
                out var receipt) ||
            binding.State != RegularV4FrontierRepairPressureBindingState.Installed ||
            binding.Authority != contract.Authority ||
            binding.InstallGeneration <= 0 ||
            receipt.InstallGeneration != binding.InstallGeneration ||
            !IsAcceptedRegularV4FrontierRepairPressureInstallReceipt(
                contract,
                contract.Authority.PredecessorAuthorityId,
                binding.PressureReason,
                receipt,
                out _))
        {
            rejectionReason = "repair_pressure_binding_not_current";
            return false;
        }

        return IsRegularV4FrontierRepairPressureInstallScopeCurrentLocked(
            context,
            contract,
            out rejectionReason);
    }

    private bool IsInboundRegularV4FrontierTailRepairAttemptCurrentLocked(
        InboundTransferContext context,
        V4ReceiverRepairRequestState repairState,
        IReadOnlyList<FileTransferRangeV4> ranges,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (!repairState.FrontierRepair ||
            !repairState.FrontierTailRepair ||
            repairState.Filled ||
            repairState.RegularV4RepairContract is not { } contract ||
            contract.Lifecycle.IsSettled)
        {
            rejectionReason = "attempt_contract_missing_or_settled";
            return false;
        }

        if (!InboundRegularV4FrontierRepairProjectionRangesEqual(repairState.Ranges, ranges) ||
            ranges.Count == 0 ||
            ranges[0].StartChunkIndex != context.NextChunkIndex ||
            context.PullHighestReceivedChunkIndex >= context.NextChunkIndex)
        {
            rejectionReason = "attempt_range_not_current";
            return false;
        }

        if (!ReferenceEquals(context.CurrentRegularV4FrontierRepairContract, contract) ||
            !IsRegularV4FrontierRepairContractCurrent(context, contract, out rejectionReason))
        {
            rejectionReason = string.IsNullOrWhiteSpace(rejectionReason)
                ? "attempt_authority_replaced"
                : rejectionReason;
            return false;
        }

        if (!IsInboundRegularV4FrontierRepairPressureInstalledLocked(
                context,
                contract,
                out rejectionReason))
        {
            rejectionReason = string.IsNullOrWhiteSpace(rejectionReason)
                ? "attempt_pressure_binding_not_current"
                : rejectionReason;
            return false;
        }

        return true;
    }

    private bool IsInboundRegularV4FrontierTailRepairStateSendCurrentLocked(
        InboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferStateFrameV4 state,
        InboundRegularV4FrontierTailRepairStateAuthority stateAuthority,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (!ReferenceEquals(inboundTransfer, context) ||
            context.IsTerminal ||
            !ReferenceEquals(context.DataSession, dataSession) ||
            !ReferenceEquals(dataSession, stateAuthority.DataSession) ||
            context.DataSessionGeneration != stateAuthority.DataSessionGeneration ||
            !string.Equals(state.SessionId, context.SessionId, StringComparison.Ordinal) ||
            !string.Equals(state.TransferId, context.TransferId, StringComparison.Ordinal) ||
            state.ContiguousCommittedChunkIndex != stateAuthority.FrontierChunkIndex ||
            state.DurableReceivedHighestChunkIndex != stateAuthority.DurableReceivedHighestChunkIndex ||
            !InboundRegularV4FrontierRepairProjectionRangesEqual(state.MissingRanges, stateAuthority.Ranges))
        {
            rejectionReason = "state_send_scope_replaced";
            return false;
        }

        if (!context.V4ReceiverRepairRequests.TryGetValue(stateAuthority.RepairRequestKey, out var repairState) ||
            !ReferenceEquals(repairState.RegularV4RepairContract, stateAuthority.Contract) ||
            stateAuthority.Contract.Authority != stateAuthority.Authority ||
            !TryGetInstalledRegularV4FrontierRepairPressure(
                CreateCoordinatorStateLocked(context),
                stateAuthority.Contract.Authority.AuthorityId,
                out var binding,
                out _,
                out _) ||
            binding.State != RegularV4FrontierRepairPressureBindingState.Installed ||
            binding.Authority != stateAuthority.Contract.Authority ||
            binding.InstallGeneration != stateAuthority.InstallGeneration)
        {
            rejectionReason = "attempt_authority_replaced";
            return false;
        }

        return IsInboundRegularV4FrontierTailRepairAttemptCurrentLocked(
            context,
            repairState,
            stateAuthority.Ranges,
            out rejectionReason);
    }

    private static void LogInboundRegularV4FrontierTailRepairStateAuthority(
        string eventName,
        InboundRegularV4FrontierTailRepairStateAuthority stateAuthority,
        string reason)
    {
        var authority = stateAuthority.Authority;
        LocalOperationalLog.Info(
            "FileTransferService",
            $"event={eventName}; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={FormatProtocolLogValue(authority.AuthorityId.ToString())}; predecessor_authority_id={FormatProtocolLogValue(authority.PredecessorAuthorityId?.ToString() ?? "(none)")}; direction=inbound; transfer_id={FormatProtocolLogValue(authority.TransferId)}; session_id={FormatProtocolLogValue(authority.SessionId)}; route={FormatProtocolLogValue(authority.RouteToken)}; protocol_version={authority.ProtocolVersion}; live_route_epoch={authority.LiveRouteEpoch}; runtime_generation={authority.RuntimeGeneration}; terminal_generation={authority.TerminalGeneration}; leg_generation={authority.LegGeneration}; transport_epoch={authority.TransportEpoch}; bridge_recovery_generation={authority.BridgeRecoveryGeneration}; bridge_decision_generation={authority.BridgeDecisionGeneration}; route_publication_generation={authority.RoutePublicationGeneration}; route_commit_generation={authority.RouteCommitGeneration ?? 0}; data_session_generation={stateAuthority.DataSessionGeneration}; install_generation={stateAuthority.InstallGeneration}; repair_request_key={FormatProtocolLogValue(stateAuthority.RepairRequestKey)}; range_fingerprint={FormatProtocolLogValue(stateAuthority.RangeFingerprint)}; ranges={FormatProtocolLogValue(FormatInboundRegularV4FrontierRepairProjectionRanges(stateAuthority.Ranges))}; frontier_chunk_index={stateAuthority.FrontierChunkIndex}; durable_received_highest_chunk_index={stateAuthority.DurableReceivedHighestChunkIndex}; repair_publication_kind=attempt_scoped_frontier_tail; decision_reason={FormatProtocolLogValue(reason)}");
    }

    private static bool IsInboundRegularV4FrontierRepairProjectionStateLocked(
        InboundTransferContext context,
        FileTransferStateFrameV4 state,
        out InboundRegularV4FrontierRepairProjection? projection)
    {
        projection = context.V4RegularFrontierRepairProjection;
        return projection is not null &&
               state.ContiguousCommittedChunkIndex == projection.FrontierChunkIndex &&
               InboundRegularV4FrontierRepairProjectionRangesEqual(state.MissingRanges, projection.ProjectedRanges);
    }

    private bool IsInboundRegularV4FrontierRepairProjectionSendCurrentLocked(
        InboundTransferContext context,
        IFileTransferDataSession dataSession,
        FileTransferStateFrameV4 state,
        InboundRegularV4FrontierRepairProjection projection)
    {
        if (!ReferenceEquals(inboundTransfer, context) ||
            context.IsTerminal ||
            !ReferenceEquals(context.DataSession, dataSession) ||
            !string.Equals(state.SessionId, context.SessionId, StringComparison.Ordinal) ||
            !string.Equals(state.TransferId, context.TransferId, StringComparison.Ordinal) ||
            context.V4RegularFrontierRepairProjection is not { } currentProjection ||
            currentProjection.ProjectionGeneration != projection.ProjectionGeneration ||
            currentProjection.SourceContract.Authority.AuthorityId != projection.SourceContract.Authority.AuthorityId ||
            state.ContiguousCommittedChunkIndex != currentProjection.FrontierChunkIndex ||
            !InboundRegularV4FrontierRepairProjectionRangesEqual(
                state.MissingRanges,
                currentProjection.ProjectedRanges))
        {
            return false;
        }

        return IsInboundRegularV4FrontierRepairProjectionScopeCurrentLocked(
            context,
            currentProjection,
            out _);
    }

    private static void ReconcileInboundRegularV4FrontierRepairProjectionLocked(
        InboundTransferContext context,
        string reason)
    {
        if (context.V4RegularFrontierRepairProjection is { } projection)
        {
            if (IsInboundRegularV4FrontierRepairProjectionScopeCurrentLocked(context, projection, out _))
            {
                return;
            }

            RejectInboundRegularV4FrontierRepairProjectionLocked(
                context,
                projection,
                reason,
                requireFreshProjection: true);
            return;
        }

        if (context.V4RegularFrontierRepairProjectionRefreshSource is not { } refreshSource ||
            IsInboundRegularV4FrontierRepairProjectionRefreshSourceCurrentLocked(context, refreshSource))
        {
            return;
        }

        LogInboundRegularV4FrontierRepairProjectionEvent(
            "filetransfer_regular_v4_frontier_repair_projection_cleared",
            refreshSource.Projection,
            $"{reason}_refresh_source_scope_replaced",
            refreshSource);
        context.V4RegularFrontierRepairProjectionRefreshSource = null;
        context.V4RegularFrontierRepairProjectionRefreshRequired =
            !context.IsTerminal &&
            IsCurrentRegularV4FrontierRepairRuntime(context) &&
            HasInboundRegularV4DurableFrontierGapLocked(context);
    }

    private IReadOnlyList<FileTransferRangeV4> BuildInboundV4MissingRangesLocked(
        InboundTransferContext context,
        bool forceFrontierRepair = false)
    {
        var written = context.ReceiverSparseChunksWritten;
        if (written is null ||
            context.NextChunkIndex >= context.ChunkCount)
        {
            context.V4FrontierStallStartedUtc = null;
            context.V4FrontierStallChunkIndex = -1;
            context.V4FrontierStallLastSuppressedLogUtc = null;
            if (context.V4RegularFrontierRepairProjection is not null ||
                context.V4RegularFrontierRepairProjectionRefreshSource is not null ||
                context.V4RegularFrontierRepairProjectionRefreshRequired)
            {
                ClearInboundRegularV4FrontierRepairProjectionLocked(
                    context,
                    written is null ? "sparse_manifest_state_missing" : "frontier_complete",
                    requireFreshProjection: false);
            }
            return [];
        }

        var now = DateTimeOffset.UtcNow;
        ClearFilledInboundV4RepairRequestsLocked(context, now);
        ReconcileInboundRegularV4FrontierRepairProjectionLocked(
            context,
            "state_projection_refresh_scope_revalidation");
        var hasRetainedProjection = TryRefreshInboundRegularV4FrontierRepairProjectionLocked(
            context,
            out var retainedProjection);
        if (context.V4RegularFrontierRepairProjectionRefreshRequired &&
            !HasInboundRegularV4DurableFrontierGapLocked(context))
        {
            ClearInboundRegularV4FrontierRepairProjectionLocked(
                context,
                "refresh_gap_resolved",
                requireFreshProjection: false);
        }
        if (context.UserPaused || context.PeerPaused)
        {
            return hasRetainedProjection
                ? retainedProjection!.ProjectedRanges
                : [];
        }

        var hasDistinctActiveRepairAttempt =
            context.CurrentRegularV4FrontierRepairContract is { Lifecycle.IsSettled: false } activeRepairAttempt &&
            !ReferenceEquals(activeRepairAttempt, retainedProjection?.SourceContract) &&
            IsRegularV4FrontierRepairContractCurrent(context, activeRepairAttempt, out _);
        if (hasRetainedProjection &&
            retainedProjection!.SourceContract.Lifecycle.IsSettled &&
            !hasDistinctActiveRepairAttempt)
        {
            return retainedProjection.ProjectedRanges;
        }

        var frontierStallAgeMs = GetInboundV4FrontierStallAgeMsLocked(context, now);
        var frontierRepairRepeatIntervalMs = ResolveV4FrontierRepairRepeatIntervalMs(context);
        var frontierSuppressedLogIntervalMs = ResolveV4RepairSuppressedLogIntervalMs(context, frontierRepairRepeatIntervalMs);
        if (!forceFrontierRepair &&
            !context.V4RegularFrontierRepairProjectionRefreshRequired &&
            context.PullHighestReceivedChunkIndex >= context.NextChunkIndex &&
            frontierStallAgeMs < frontierRepairRepeatIntervalMs)
        {
            context.V4FrontierStallSuppressedCountTotal++;
            if (context.V4FrontierStallLastSuppressedLogUtc is null ||
                now - context.V4FrontierStallLastSuppressedLogUtc.Value >= TimeSpan.FromMilliseconds(frontierSuppressedLogIntervalMs))
            {
                context.V4FrontierStallLastSuppressedLogUtc = now;
                if (FileTransferDiagnosticLogPolicy.TraceEnabled)
                {
                    LocalOperationalLog.Info(
                        "FileTransferService",
                        $"event=filetransfer_v4_frontier_stall_missing_range_suppressed; transfer_id={context.TransferId}; session_id={context.SessionId}; reason=stall_age_below_min; epoch={context.V4StateEpoch}; start_chunk_index={context.NextChunkIndex}; frontier_stall_age_ms={frontierStallAgeMs}; retry_in_ms={Math.Max(0, frontierRepairRepeatIntervalMs - frontierStallAgeMs)}; repair_interval_ms={frontierRepairRepeatIntervalMs}; initial_frontier_repair_chunks={ResolveV4InitialFrontierRepairChunks(context)}; credit_until_chunk_index_exclusive={context.V4CreditUntilChunkIndexExclusive}; durable_received_highest_chunk_index={context.PullHighestReceivedChunkIndex}");
                }
            }

            return hasRetainedProjection
                ? retainedProjection!.ProjectedRanges
                : [];
        }

        var previousFrontierRepair = FindRecentInboundV4RepairStateForRangeLocked(
            context,
            context.NextChunkIndex,
            Math.Min(context.ChunkCount, context.NextChunkIndex + 1));
        var sameFrontierRetry = previousFrontierRepair?.LastRequestedUtc is not null &&
            previousFrontierRepair.FirstStartChunkIndex == context.NextChunkIndex;
        var frontierRetryNarrowed = false;
        var originalFrontierRangeChunkCount = 0;
        var repairBurstMaxChunks = ResolveV4RepairBurstMaxChunks(context);
        var ranges = new List<FileTransferRangeV4>();
        var totalMissingChunks = 0;
        if (context.PullHighestReceivedChunkIndex >= context.NextChunkIndex)
        {
            var upperInclusive = Math.Min(context.PullHighestReceivedChunkIndex, context.ChunkCount - 1);
            var chunkIndex = context.NextChunkIndex;
            while (chunkIndex <= upperInclusive &&
                   ranges.Count < FileTransferProtocol.MaxStateMissingRangesV4 &&
                   totalMissingChunks < repairBurstMaxChunks)
            {
                if (written[chunkIndex] || context.ReceiverSparseChunksPendingWrite.Contains(chunkIndex))
                {
                    chunkIndex++;
                    continue;
                }

                var start = chunkIndex;
                var count = 0;
                var isFrontierRange = start == context.NextChunkIndex;
                var exactFrontierRepairRequired = isFrontierRange &&
                    IsInboundV6ExactFrontierRepairRequiredLocked(context);
                var maxRangeChunks = isFrontierRange && IsInboundPostTunaRecoveryActiveLocked(context)
                    ? exactFrontierRepairRequired
                        ? V4PostFallbackEmergencyFrontierRepairChunks
                        : ResolveV4PostFallbackFrontierRepairChunks(context)
                    : isFrontierRange && sameFrontierRetry
                    ? ResolveV4FrontierTailRetryChunks(context)
                    : isFrontierRange
                        ? ResolveV4InitialFrontierRepairChunks(context)
                        : repairBurstMaxChunks;

                while (chunkIndex <= upperInclusive &&
                       !written[chunkIndex] &&
                       !context.ReceiverSparseChunksPendingWrite.Contains(chunkIndex) &&
                       totalMissingChunks + count < repairBurstMaxChunks &&
                       count < maxRangeChunks)
                {
                    count++;
                    chunkIndex++;
                }

                if (isFrontierRange)
                {
                    originalFrontierRangeChunkCount = count;
                    while (chunkIndex <= upperInclusive &&
                           !written[chunkIndex] &&
                           !context.ReceiverSparseChunksPendingWrite.Contains(chunkIndex))
                    {
                        originalFrontierRangeChunkCount++;
                        chunkIndex++;
                    }

                    frontierRetryNarrowed = sameFrontierRetry && originalFrontierRangeChunkCount > count;
                }

                if (count > 0)
                {
