        var firstStart = ranges[0].StartChunkIndex;
        var lastEndExclusive = ranges[^1].StartChunkIndex + ranges[^1].ChunkCount;
        var repairRequestKey = CreateV4RepairRequestKey(
            context.TransferId,
            firstStart,
