                    hasRetainedProjection
                        ? firstStart
                        : durableProjectionAuthorizationRanges[0].StartChunkIndex,
                    context.PullHighestReceivedChunkIndex,
                    hasRetainedProjection
                        ? requestedChunkCount
                        : durableProjectionAuthorizationRanges.Sum(static range => range.ChunkCount),
